#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CONFIG 0x4003 // Single-shot, AIN0, PGA ±4.096V, 128 SPS
#define SENSOR_SENSITIVITY 40.0 // mV/A
#define ZERO_CURRENT_OFFSET 2.5 // V
#define SUPPLY_VOLTAGE 5.0 // V
#define CURRENT_SCALE (SUPPLY_VOLTAGE - ZERO_CURRENT_OFFSET) / SENSOR_SENSITIVITY

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115();
float convert_to_current(int raw_value);
void log_current(float current);
void signal_handler(int signal);

// Structure for ADS1115 configuration
typedef struct {
    int mux;
    int pga;
    int mode;
    int data_rate;
} ads1115_config_t;

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure ADS1115 for single-shot mode, AIN0, PGA ±4.096V, 128 SPS
int configure_ads1115() {
    unsigned char config[3];
    config[0] = (AIN0_CONFIG >> 8) & 0xFF; // MSB of config register
    config[1] = AIN0_CONFIG & 0xFF;      // LSB of config register
    config[2] = 0x83; // Start single conversion

    int result = i2cWriteI2CBlockData(i2c_handle, 0x01, config, 3);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read the raw ADC value from ADS1115
int read_ads1115() {
    unsigned char data[2];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)data, 2);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    int raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Convert raw ADC value to current in amperes
float convert_to_current(int raw_value) {
    float voltage = (raw_value * SUPPLY_VOLTAGE) / 32768.0; // Assuming 16-bit ADC
    float current = (voltage - ZERO_CURRENT_OFFSET) / CURRENT_SCALE;
    return current;
}

// Log the computed current to the console
void log_current(float current) {
    printf("Current: %.4f A\n", current);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Start single conversion
        unsigned char start_conversion = 0x83;
        i2cWriteByteData(i2c_handle, 0x01, start_conversion);

        // Wait for conversion to complete (at least 8ms for 128 SPS)
        gpioDelay(10000); // 10ms

        // Read ADC value
        int raw_value = read_ads1115();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading ADC value, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert to current
        float current = convert_to_current(raw_value);

        // Log current
        log_current(current);

        // Wait 500ms
        gpioDelay(500000);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

