int configure_ads1115() {
    // Configure for single-shot mode, AIN0, +/- 4.096V, 128 SPS
    unsigned char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x44; // Single-shot, AIN0, +/- 4.096V, 128 SPS, disable comparator
    config[2] = 0x83; // 128 SPS, start single conversion

    int result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %d\n", result);
