    unsigned char config[3];
    config[0] = ADS1115_CONFIG_REG;
    config[1] = 0x44; // Single-shot, AIN0, +/- 4.096V, 128 SPS, disable comparator
    config[2] = 0x83; // 128 SPS, start single conversion

    int result = i2cWriteDevice(i2c_handle, (char *)config, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register for conversion: %d\n", result);
        return -1.0; // Indicate error
    }

    // Wait for conversion to complete (adjust delay as needed)
    gpioDelay(10); // Wait 10ms for conversion

    // Read the conversion result
    data[0] = ADS1115_CONVERSION_REG;
    result = i2cWriteDevice(i2c_handle, (char *)data, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register: %d\n", result);
        return -1.0; // Indicate error
    }

