    while (running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read temperature
        float temperature = read_temperature();

        if (temperature > 0) {
            if (temperature > TEMPERATURE_THRESHOLD) {
                log_event("Temperature exceeds threshold!");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Check sensor connection.\n");
            log_event("Failed to read temperature. Check sensor connection.");
        }

        // Check for fire condition
        if (flame_detected == 0 && temperature > TEMPERATURE_THRESHOLD) {
