            activate_buzzer();
            gpioDelay(BUZZER_DURATION_MS);
            deactivate_buzzer();
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup
    deactivate_buzzer();
    gpioSetISRFuncEx(FLAME_SENSOR_GPIO, FALLING_EDGE, 0, NULL, NULL); // Disable ISR
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
