#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <getopt.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip4" // Try gpiochip4 first, fallback to gpiochip0
#define GPIO_PIN 18
#define DEFAULT_SENSITIVITY 0.100 // 100 mV/A
#define DEFAULT_THRESHOLD 5.000 // 5.0 A
#define LOG_FILE "current_log.txt"

// Global variables (minimize usage)
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static double sensitivity = DEFAULT_SENSITIVITY;
static double threshold = DEFAULT_THRESHOLD;
static int gpio_chip_number = 0; // Store the actual chip number

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
double adc_to_current(int adc_value);
int gpio_init(void);
int gpio_set_value(int value);
int log_data(double current);
void signal_handler(int sig);
int detect_gpio_chip(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &ret);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &ret);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED);
    if (ret == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &ret);
    if (ret == -1) {
        perror("Error getting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    uint8_t tx[3];
    uint8_t rx[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// ADC to Current Conversion
double adc_to_current(int adc_value) {
    // Assuming VREF = 3.3V and 10-bit ADC
    double voltage = (adc_value / 1023.0) * 3.3;
    double current = voltage / sensitivity;
    return current;
}

// GPIO Initialization
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip %s, trying gpiochip0...\n", GPIO_CHIP);
        gpio_chip = gpiod_chip_open_by_name("gpiochip0");
        if (!gpio_chip) {
            perror("Error opening GPIO chip");
            return -1;
        }
        gpio_chip_number = 0; // Store the chip number
    } else {
        gpio_chip_number = 4; // Store the chip number
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request(gpio_line, "current_monitor", GPIOD_LINE_REQUEST_DIRECTION_OUTPUT);
    if (ret < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int value) {
    int ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(double current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %.4f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (log_file) {
        fclose(log_file);
    }

    exit(0);
}

// Detect GPIO Chip
int detect_gpio_chip(void) {
    int chip_number = 0;
    while (chip_number <= 4) {
        char chip_name[20];
        snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip_number);
        if (gpiod_chip_open_by_name(chip_name) != NULL) {
            return chip_number;
        }
        chip_number++;
    }
    return -1; // No GPIO chip found
}

int main(int argc, char *argv[]) {
    int opt;
    int adc_value;
    double current;
    int fan_on = 0; // Track fan state

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:t:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity] [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to current
        current = adc_to_current(adc_value);

        // Log data
        if (log_data(current) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Control fan
        if (current > threshold && !fan_on) {
            if (gpio_set_value(1) < 0) {
                fprintf(stderr, "Error turning fan ON.\n");
            } else {
                fan_on = 1;
                printf("Fan turned ON (Current: %.4f A, Threshold: %.4f A)\n", current, threshold);
            }
        } else if (current <= threshold && fan_on) {
            if (gpio_set_value(0) < 0) {
                fprintf(stderr, "Error turning fan OFF.\n");
            } else {
                fan_on = 0;
                printf("Fan turned OFF (Current: %.4f A, Threshold: %.4f A)\n", current, threshold);
            }
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

