#define CO_CHANNEL 0
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define FULL_SCALE_VOLTAGE 4.096 // +/- 4.096V
#define MAX_PPM 1000.0          // Maximum CO concentration in PPM
#define LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

