        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read CO resistance from ADS1115
int16_t read_co_resistance() {
    // Configure ADS1115 for single-ended reading on CO channel
    // and 128 SPS, +/- 4.096V, and continuous conversion mode
    uint16_t config = 0x4003; // Single-ended AIN0, 128 SPS, +/-4.096V, Continuous
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config) < 0) {
        fprintf(stderr, "Failed to write config register\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    int16_t raw_value = i2cReadWordData(i2c_handle, CONVERSION_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Failed to read conversion register\n");
        return -1;
    }

    // The ADS1115 returns the MSB first, so swap bytes
    raw_value = ((raw_value & 0xFF) << 8) | ((raw_value & 0xFF00) >> 8);

    return raw_value;
}

// Function to convert raw resistance to PPM
float convert_to_ppm(int16_t raw_resistance) {
    // Assuming a logarithmic relationship between resistance and PPM
    // This is a simplified example and needs calibration for accurate results
    float resistance = (float)raw_resistance / 32768.0 * FULL_SCALE_VOLTAGE; // Assuming 16-bit ADC
    float ppm = MAX_PPM * (resistance / FULL_SCALE_VOLTAGE); // Linear approximation
    return ppm;
}

