        // Read CO resistance
        int16_t raw_resistance = read_co_resistance();
        if (raw_resistance < 0) {
            fprintf(stderr, "Failed to read CO resistance\n");
        } else {
            // Convert to PPM
            float ppm_value = convert_to_ppm(raw_resistance);

            // Log PPM value
            if (log_ppm_value(ppm_value) != 0) {
                fprintf(stderr, "Failed to log PPM value\n");
            }

            printf("CO Concentration: %.2f PPM\n", ppm_value);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

