#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define SPI_CE 0
#define SPI_SCLK 11
#define SPI_MOSI 10
#define SPI_MISO 9

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define CSV filename
#define CSV_FILENAME "flame_data.csv"

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_flame_sensor();
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int log_data(int flame_detected, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold SPI configuration
typedef struct {
    int ce;
    int sclk;
    int mosi;
    int miso;
    int baud;
} spi_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);

    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_config_t spi_config = {SPI_CE, SPI_SCLK, SPI_MOSI, SPI_MISO, SPI_BAUD};

    spi_handle = spiOpen(SPI_CHANNEL, spi_config.baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", spi_result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    return 10.0 + (float)adc_value / 1023.0 * 30.0;
}

// Function to log data to CSV file
int log_data(int flame_detected, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f\n", timestamp, flame_detected, temperature);
    fflush(fp); // Ensure data is written to file immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (fp != NULL) {
        fclose(fp);
    }

    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen(CSV_FILENAME, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open CSV file\n");
        cleanup();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "Timestamp,Flame Detected,Temperature (C)\n");
    }
    rewind(fp);

    // Main loop
    while (program_running) {
        // Read flame sensor
        int flame_detected = read_flame_sensor();

        // Read temperature from MCP3008
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip logging this iteration
        }

        float temperature = convert_adc_to_temperature(adc_value);

        // Log data
        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

