    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("CO Monitoring System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sensor_data();
        float co_ppm = calculate_co_ppm(sensor_data.co_raw);

        log_co_level(co_ppm);

        if (co_ppm > CO_THRESHOLD) {
            log_alert(co_ppm);
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

