#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MIC1_ADDR 0x48
#define MIC2_ADDR 0x49
#define REFERENCE_PRESSURE 20e-6 // 20 microPa
#define SENSITIVITY -38.0 // dBV/Pa
#define SAMPLE_INTERVAL_MS 100
#define ERROR_VALUE -999.0

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    int i2c_bus;
    int mic1_address;
    int mic2_address;
    double reference_pressure;
    double sensitivity;
    int sample_interval_ms;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_microphone_data(int i2c_handle);
double convert_to_db(int raw_data);
void log_data(double db1, double db2);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read microphone data from I2C
int read_microphone_data(int i2c_handle) {
    char buffer[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (int16_t)((buffer[0] << 8) | buffer[1]);
    return raw_data;
}

// Convert raw data to dB
double convert_to_db(int raw_data) {
    // Convert raw data to voltage (assuming a simple linear relationship)
    double voltage = (double)raw_data / 32767.0 * 3.3; // Assuming 3.3V range

    // Convert voltage to pressure (Pa)
    double pressure = voltage * REFERENCE_PRESSURE;

    // Convert pressure to dB
    double db = 20 * log10(pressure / REFERENCE_PRESSURE);

    return db;
}

// Log data to file
void log_data(double db1, double db2) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, db1, db2);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, MIC1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, MIC2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int raw_data1 = read_microphone_data(i2c_handle1);
        int raw_data2 = read_microphone_data(i2c_handle2);

        double db1, db2;

        if (raw_data1 < 0) {
            db1 = ERROR_VALUE;
            fprintf(stderr, "Error reading from microphone 1\n");
        } else {
            db1 = convert_to_db(raw_data1);
        }

        if (raw_data2 < 0) {
            db2 = ERROR_VALUE;
            fprintf(stderr, "Error reading from microphone 2\n");
        } else {
            db2 = convert_to_db(raw_data2);
        }

        log_data(db1, db2);

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

