#define SAMPLE_WINDOW_MS 100
#define SAMPLE_INTERVAL_MS 1
#define NUM_SAMPLES (SAMPLE_WINDOW_MS / SAMPLE_INTERVAL_MS)
#define NORMALIZATION_FACTOR 1000.0 // Adjust as needed

// Global variables
int spi_handle_0, spi_handle_1;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
