    spi_handle_0 = spiOpen(SPI_CHANNEL_0, 1000000, 0); // CE0, 1MHz, mode 0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "SPI channel 0 open failed: %d\n", spi_handle_0);
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, 1000000, 0); // CE1, 1MHz, mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "SPI channel 1 open failed: %d\n", spi_handle_1);
        spiClose(spi_handle_0);
        gpioTerminate();
