#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define ADS1115_FULL_SCALE_4_096V 0x00
#define ADS1115_MODE_SINGLE_SHOT 0x01
#define ADS1115_DATA_RATE_128_SPS 0x02
#define ADS1115_COMPARATOR_MODE_TRADITIONAL 0x00
#define ADS1115_COMPARATOR_POLARITY_ACTIVE_LOW 0x00
#define ADS1115_COMPARATOR_LATCH_NON_LATCHING 0x00
#define ADS1115_COMPARATOR_QUEUE_DISABLE 0x03
#define ADS1115_CHANNEL_0_SINGLE_ENDED 0x04
#define GPIO_LED 17
#define CURRENT_THRESHOLD 50.0
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_ads1115(int *raw_value);
float convert_to_current(int raw_value);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void control_led(float average_current);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read data from ADS1115
int read_ads1115(int *raw_value) {
    char config[3];
    char data[2];

    // Configure ADS1115 for single-ended channel 0, 128 SPS, +/- 4.096V, single-shot mode
    config[0] = ADS1115_CONFIG_REG;
    config[1] = (ADS1115_MODE_SINGLE_SHOT << 1) | 0x00; // Start single conversion
    config[2] = (ADS1115_DATA_RATE_128_SPS << 5) | (ADS1115_FULL_SCALE_4_096V << 2) | ADS1115_CHANNEL_0_SINGLE_ENDED;

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        fprintf(stderr, "Failed to write configuration to ADS1115\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10ms

    // Read conversion result
    config[0] = ADS1115_CONVERSION_REG;
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Failed to write read command to ADS1115\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Failed to read data from ADS1115\n");
        return -1;
    }

    *raw_value = (data[0] << 8) | data[1];
    return 0;
}

// Convert raw ADC value to current
float convert_to_current(int raw_value) {
    // Assuming a 5V supply and 0.5V to 4.5V output for 0-100A
    float voltage = (float)raw_value * 0.0001220703125; // 5V / 4096
    float current = (voltage - 0.5) / 0.004; // (voltage - 0.5V) / (4.5V - 0.5V) * 100A
    return current;
}

// Control the warning LED
void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO_LED as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_circular_buffer(&current_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int raw_value;
    float current;
    float average_current;

    printf("Overcurrent protection system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read sensor value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to current
            current = convert_to_current(raw_value);

            // Add to circular buffer
            add_to_buffer(&current_buffer, current);

            // Calculate average current
            average_current = calculate_average(&current_buffer);

            // Control LED
            control_led(average_current);

            printf("Current: %.2f A, Average Current: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

