#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define MOTOR_SHUTDOWN_PIN 17
#define OVERCURRENT_THRESHOLD 10.0
#define SENSITIVITY 0.1
#define OFFSET 0.05
#define LOG_FILE "current_log.csv"
#define SPI_RETRY_COUNT 3

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_read_adc(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    char spi_device[20];
    int motor_pin;
    float overcurrent_threshold;
    float sensitivity;
    float offset;
    char log_file[20];
} Config;

// Function to initialize the system
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set motor shutdown pin as output
    gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT);
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Initially enable the motor

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        gpioTerminate();
        return -1;
    }

    // Configure SPI parameters
    unsigned int speed = 1000000; // 1 MHz
    unsigned int mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        gpioTerminate();
        return -1;
    }

    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,current_in_Amperes\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    return 0;
}

// Function to clean up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Disable motor on exit
    gpioTerminate();
}

// Function to read from MCP3008 ADC
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int retries = 0;

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    while (retries < SPI_RETRY_COUNT) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
            perror("SPI transfer failed");
            retries++;
            usleep(10000); // Wait 10ms before retrying
        } else {
            break; // Exit retry loop on success
        }
    }

    if (retries == SPI_RETRY_COUNT) {
        fprintf(stderr, "SPI transfer failed after %d retries\n", SPI_RETRY_COUNT);
        return -1; // Indicate failure
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * 3.3;
}

// Function to convert voltage to current
float voltage_to_current(float voltage) {
    return (voltage - OFFSET) / SENSITIVITY;
}

// Function to log current reading to file
void log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to check for overcurrent condition and shutdown motor
void check_overcurrent(float current) {
    if (current > OVERCURRENT_THRESHOLD) {
        printf("Overcurrent detected: %.2f A\n", current);
        fprintf(log_file, "Overcurrent detected: %.2f A\n", current);
        fflush(log_file);
        gpioWrite(MOTOR_SHUTDOWN_PIN, 0); // Disable motor
        sleep(1); // Wait 1 second
        gpioWrite(MOTOR_SHUTDOWN_PIN, 1); // Re-enable motor
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received: %d. Shutting down...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        log_current(current);
        check_overcurrent(current);

        sleep(1); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

