#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x40
#define PRESSURE_REGISTER 0x00
#define LOG_FILE "pressure_log.csv"
#define SENSOR_ABSENT_THRESHOLD 3
#define SENSOR_ABSENT_TIMEOUT 60 // seconds

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor data
typedef struct {
    int i2c_handle;
    FILE *log_file;
    int sensor_absent_count;
    time_t sensor_absent_start_time;
} SensorData;

SensorData sensor_data;

// Function prototypes
int initialize_i2c();
int read_pressure(int *raw_pressure);
float convert_to_kPa(int raw_pressure);
int log_data(float pressure_kPa);
void signal_handler(int signal);
int open_log_file();
void close_resources();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads the pressure value from the sensor
int read_pressure(int *raw_pressure) {
    char buffer[2];
    int result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }

    *raw_pressure = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Converts the raw pressure value to kPa
float convert_to_kPa(int raw_pressure) {
    return (float)raw_pressure / 65535.0 * 500.0;
}

// Logs the pressure data to a file
int log_data(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fprintf(log_file, "timestamp,pressure_kPa\n"); // Write header if the file is newly created
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure_kPa);
    fflush(log_file);
    return 0;
}

// Opens the log file
int open_log_file() {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }
    return 0;
}

// Closes I2C and log file resources
void close_resources() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        close_resources();
        return 1;
    }

    // Open log file
    if (open_log_file() != 0) {
        close_resources();
        return 1;
    }

    sensor_data.i2c_handle = i2c_handle;
    sensor_data.log_file = log_file;
    sensor_data.sensor_absent_count = 0;
    sensor_data.sensor_absent_start_time = 0;

    // Main loop
    while (program_running) {
        int raw_pressure;
        float pressure_kPa;

        if (read_pressure(&raw_pressure) == 0) {
            pressure_kPa = convert_to_kPa(raw_pressure);
            if (log_data(pressure_kPa) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
            sensor_data.sensor_absent_count = 0; // Reset counter if read is successful
        } else {
            sensor_data.sensor_absent_count++;
            fprintf(stderr, "Failed to read pressure data. Count: %d\n", sensor_data.sensor_absent_count);

            if (sensor_data.sensor_absent_count >= SENSOR_ABSENT_THRESHOLD) {
                if (sensor_data.sensor_absent_start_time == 0) {
                    sensor_data.sensor_absent_start_time = time(NULL);
                    fprintf(stderr, "Sensor possibly absent. Starting timer.\n");
                } else {
                    time_t current_time = time(NULL);
                    if (difftime(current_time, sensor_data.sensor_absent_start_time) >= SENSOR_ABSENT_TIMEOUT) {
                        fprintf(stderr, "Sensor absent for %d seconds. Closing log file and exiting.\n", SENSOR_ABSENT_TIMEOUT);
                        close_resources();
                        return 0;
                    }
                }
            }
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Clean up resources before exiting
    close_resources();

    return 0;
}

