// Constants
#define ADS1115_ADDR 0x48
#define AIN0_REG 0x00
#define AIN1_REG 0x02
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define WARNING_LED_GPIO 17
#define PRESSURE_THRESHOLD 105.0
#define VREF 4.096 // ADS1115 reference voltage

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_ads1115(int handle, int reg);
float convert_to_pressure(int16_t adc_value);
float convert_to_temperature(int16_t adc_value);
void control_led(int gpio, int state);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0); // Bus 1, address 0x48, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0 and AIN1, 128 SPS, +/- 6.144V
    // Single-shot mode, disable comparator, disable ALERT/RDY pin
    uint16_t config = 0x8383; //0b1000001110000011;
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to read data from ADS1115
int read_ads1115(int handle, int reg) {
    int retries = 3;
    int16_t value = 0;
    char buf[1];
    buf[0] = reg;

    while (retries > 0) {
        if (i2cWriteDevice(handle, buf, 1) == 0) {
            gpioDelay(10); // Small delay for conversion
            char read_buf[2];
            if (i2cReadDevice(handle, read_buf, 2) == 2) {
                value = (read_buf[0] << 8) | read_buf[1];
                return value;
            } else {
                fprintf(stderr, "Error reading from I2C (retry %d): %d\n", 4 - retries, i2cReadDevice(handle, read_buf, 2));
            }
        } else {
            fprintf(stderr, "Error writing to I2C (retry %d): %d\n", 4 - retries, i2cWriteDevice(handle, buf, 1));
        }
        retries--;
        gpioDelay(10); // Wait before retrying
    }

    fprintf(stderr, "Failed to read from I2C after multiple retries.\n");
    return -1; // Indicate failure
}

