float convert_to_temperature(int16_t adc_value) {
    float voltage = (float)adc_value / 32767.0 * VREF; // Assuming 16-bit ADC
    return (voltage - 1.0) * 100.0;
}

// Function to control the warning LED
void control_led(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

