    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set warning LED GPIO as output
    gpioSetMode(WARNING_LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int16_t pressure_adc = read_ads1115(i2c_handle, AIN0_REG);
        int16_t temperature_adc = read_ads1115(i2c_handle, AIN1_REG);

        if (pressure_adc == -1 || temperature_adc == -1) {
            fprintf(stderr, "Error reading ADC values, retrying I2C initialization...\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert ADC values to pressure and temperature
        float pressure = convert_to_pressure(pressure_adc);
        float temperature = convert_to_temperature(temperature_adc);

        // Display data
        printf("Pressure: %.2f kPa, Temperature: %.2f °C\n", pressure, temperature);

        // Control warning LED
        if (pressure > PRESSURE_THRESHOLD) {
            control_led(WARNING_LED_GPIO, 1); // HIGH
        } else {
            control_led(WARNING_LED_GPIO, 0); // LOW
        }

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioWrite(WARNING_LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

