#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VCC 3.3
#define SENSOR_ZERO_CURRENT_VOLTAGE (VCC / 2.0)
#define SENSOR_SENSITIVITY 0.066 // 66 mV/A
#define OVERCURRENT_THRESHOLD 10.0 // 10 A
#define OVERCURRENT_GPIO 27
#define LOG_FILE "current_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_current(float voltage);
void log_current(float current);
void check_overcurrent(float current);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vcc;
    float sensor_zero_current_voltage;
    float sensor_sensitivity;
    float overcurrent_threshold;
    int overcurrent_gpio;
    char *log_file;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    MCP3008_CHANNEL,
    VCC,
    SENSOR_ZERO_CURRENT_VOLTAGE,
    SENSOR_SENSITIVITY,
    OVERCURRENT_THRESHOLD,
    OVERCURRENT_GPIO,
    LOG_FILE
};

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (program_running) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying.\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float current = voltage_to_current(voltage);

        log_current(current);
        check_overcurrent(current);

        gpioDelay(100); // Sample every 100ms
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(OVERCURRENT_GPIO, PI_OUTPUT);
    gpioWrite(OVERCURRENT_GPIO, 0); // Ensure it starts LOW

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", config.log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    gpioWrite(OVERCURRENT_GPIO, 0); // Ensure GPIO is LOW on exit
    gpioTerminate();
}

int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

float adc_to_voltage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0;
    }
    return (float)adc_value * config.vcc / 1024.0;
}

float voltage_to_current(float voltage) {
    return (voltage - config.sensor_zero_current_voltage) / config.sensor_sensitivity;
}

void log_current(float current) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    printf("%s, Current: %.2f A\n", timestamp, current);
}

void check_overcurrent(float current) {
    if (current > config.overcurrent_threshold) {
        fprintf(stderr, "OVERCURRENT DETECTED: %.2f A\n", current);
        fprintf(log_file, "OVERCURRENT DETECTED: %.2f A\n", current);
        fflush(log_file);
        gpioWrite(config.overcurrent_gpio, 1); // Set GPIO HIGH
    } else {
        gpioWrite(config.overcurrent_gpio, 0); // Set GPIO LOW
    }
}

void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

