#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "methane_log.txt"
#define ALARM_THRESHOLD 1000.0 // PPM

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_mcp3008(int channel);
float convert_to_ppm(int adc_value);
int log_data(float ppm_value);
void check_alarm(float ppm_value);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    char *log_file;
    float alarm_threshold;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    LOG_FILE,
    ALARM_THRESHOLD
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        fprintf(stderr, "Failed to open SPI channel. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Continuing.\n");
            gpioDelay(1000); // Wait 1 second
            continue;
        }

        // Convert to PPM
        float ppm_value = convert_to_ppm(adc_value);

        // Log data
        if (log_data(ppm_value) != 0) {
            fprintf(stderr, "Failed to log data. Continuing.\n");
        }

        // Check alarm
        check_alarm(ppm_value);

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read MCP3008 channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx[3];
    char rx[3];

    // Construct SPI message (single-ended read)
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | channel) << 4; // Single-ended, channel select
    tx[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Convert ADC value to PPM
float convert_to_ppm(int adc_value) {
    return (float)adc_value * (5000.0 / 1023.0);
}

// Log data to file
int log_data(float ppm_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(log_file, "%s, %.2f PPM\n", timestamp, ppm_value) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Check alarm
void check_alarm(float ppm_value) {
    if (ppm_value > config.alarm_threshold) {
        fprintf(stderr, "LEAK ALARM: Methane concentration exceeds threshold (%.2f PPM > %.2f PPM)\n", ppm_value, config.alarm_threshold);
    }
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

