#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CHANNEL 0
#define VREF 4.096 // Reference voltage for ADS1115
#define OFFSET_PRESSURE 0.5 // Voltage at 0 kPa
#define SENSITIVITY 0.1 // Voltage change per kPa
#define MIN_PRESSURE 0.0
#define MAX_PRESSURE 100.0
#define LOG_FILE "pressure_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int ain0_channel;
    float vref;
    float offset_pressure;
    float sensitivity;
    float min_pressure;
    float max_pressure;
    char *log_file;
} Config;

// Function prototypes
int initialize_i2c(int bus, int addr);
int16_t read_ads1115(int handle, int channel);
float convert_to_voltage(int16_t raw_value, float vref);
float convert_to_pressure(float voltage, float offset_pressure, float sensitivity);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Function to read from ADS1115
int16_t read_ads1115(int handle, int channel) {
    // Configure ADS1115 for single-ended mode, 16-bit resolution, 100 SPS
    uint8_t config[3];
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // Single-ended AIN0, 16-bit, 100 SPS
    config[2] = 0x83; // Start single conversion

    if (i2cWriteDevice(handle, (char *)config, 3) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 100 SPS)
    gpioDelay(10000); // 10ms

    // Read the conversion result
    uint8_t data[2];
    if (i2cReadDevice(handle, (char *)data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    // Combine the two bytes to form the 16-bit value
    int16_t raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Function to convert raw value to voltage
float convert_to_voltage(int16_t raw_value, float vref) {
    // The ADS1115 returns a signed 16-bit value, so we need to handle the sign bit.
    // The value is in the range -32768 to 32767, representing -VREF to VREF.
    // We need to convert it to a value between 0 and VREF.
    float voltage = (float)raw_value / 32768.0 * vref;
    return voltage;
}

// Function to convert voltage to pressure
float convert_to_pressure(float voltage, float offset_pressure, float sensitivity) {
    float pressure = (voltage - offset_pressure) / sensitivity;
    return pressure;
}

// Function to log pressure to file
int log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115(i2c_handle, AIN0_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading from ADS1115, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert raw value to voltage
        float voltage = convert_to_voltage(raw_value, VREF);

        // Convert voltage to pressure
        float pressure = convert_to_pressure(voltage, OFFSET_PRESSURE, SENSITIVITY);

        // Validate pressure range
        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

