    // The value is in the range -32768 to 32767, representing -VREF to VREF.
    // We need to convert it to a value between 0 and VREF.
    float voltage = (float)raw_value / 32768.0 * vref;
    return voltage;
}

// Function to convert voltage to pressure
float convert_to_pressure(float voltage, float offset_pressure, float sensitivity) {
    float pressure = (voltage - offset_pressure) / sensitivity;
    return pressure;
}

// Function to log pressure to file
int log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f kPa\n", timestamp, pressure);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_handle = initialize_i2c(I2C_BUS, ADS1115_ADDR);
    if (i2c_handle < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw value from ADS1115
        int16_t raw_value = read_ads1115(i2c_handle, AIN0_CHANNEL);
        if (raw_value < 0) {
            fprintf(stderr, "Error reading from ADS1115, retrying...\n");
            gpioDelay(100000); // Wait 0.1 seconds before retrying
            continue;
        }

        // Convert raw value to voltage
        float voltage = convert_to_voltage(raw_value, VREF);

        // Convert voltage to pressure
        float pressure = convert_to_pressure(voltage, OFFSET_PRESSURE, SENSITIVITY);

        // Validate pressure range
        if (pressure >= MIN_PRESSURE && pressure <= MAX_PRESSURE) {
            // Log pressure
            if (log_pressure(pressure) != 0) {
                fprintf(stderr, "Error logging pressure\n");
            }
        } else {
            fprintf(stderr, "Pressure out of range: %.2f kPa\n", pressure);
        }

        // Wait for 1 second
        gpioDelay(1000000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

