// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define HUMIDITY_CHANNEL 0
#define TEMPERATURE_CHANNEL 1
#define HUMIDITY_THRESHOLD 80.0
#define HUMIDITY_SENSOR_VOLTAGE 5.0
#define BETA_COEFFICIENT 3950.0
#define R0 10000.0 // 10kΩ
#define TEMPERATURE_AT_R0 25.0
#define LOG_FILE "humidity_log.txt"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
void send_email_alert(float humidity, float temperature);
void log_data(float humidity, float temperature);
void signal_handler(int signal);

// Function to read from MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate relative humidity
float calculate_humidity(int adc_value) {
    float voltage = (adc_value / 1023.0) * HUMIDITY_SENSOR_VOLTAGE;
    float humidity = (voltage - 0.824) / 0.0315;

    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;

    return humidity;
}

// Function to calculate temperature from thermistor
float calculate_temperature(int adc_value) {
    float voltage = (adc_value / 1023.0) * HUMIDITY_SENSOR_VOLTAGE;
    float resistance = R0 * (HUMIDITY_SENSOR_VOLTAGE / voltage - 1.0);
    float temperature = TEMPERATURE_AT_R0 * (BETA_COEFFICIENT + 273.15) / (BETA_COEFFICIENT + 273.15 + (BETA_COEFFICIENT * resistance) / R0);

    return temperature - 273.15; // Convert to Celsius
}

// Function to send email alert
void send_email_alert(float humidity, float temperature) {
    char command[200];
    snprintf(command, sizeof(command), "echo \"Humidity: %.2f%%, Temperature: %.2f°C\" | ssmtp -t recipient@example.com -s \"Humidity Alert\"", humidity, temperature);
