    if (result == -1) {
        fprintf(stderr, "Error: Failed to execute ssmtp command.\n");
    } else if (WEXITSTATUS(result) != 0) {
        fprintf(stderr, "Error: ssmtp command failed with exit code %d\n", WEXITSTATUS(result));
    }
}

