    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC values
        int humidity_adc = read_mcp3208(HUMIDITY_CHANNEL);
        int temperature_adc = read_mcp3208(TEMPERATURE_CHANNEL);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error: Failed to read ADC values\n");
            continue; // Skip to the next iteration
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(humidity_adc);
        float temperature = calculate_temperature(temperature_adc);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            send_email_alert(humidity, temperature);
        }

        // Print data to console
        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 milliseconds = 5 seconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

