#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_MAX_SPEED_HZ 1000000 // 1 MHz
#define MCP3208_CHANNEL 0
#define VREF 3.3
#define LOG_FILE "temperature_log.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t channel, uint16_t *adc_value);
float adc_to_voltage(uint16_t adc_value);
float voltage_to_celsius(float voltage);
int log_temperature(float temperature);
void signal_handler(int sig);
int gpio_init(void);
void gpio_cleanup(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// SPI initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &ret);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &ret);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_MAX_SPEED_HZ);
    if (ret == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &ret);
    if (ret == -1) {
        perror("Error getting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function
int spi_transfer(uint8_t channel, uint16_t *adc_value) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_MAX_SPEED_HZ;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    *adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];

    return 0;
}

// ADC to voltage conversion
float adc_to_voltage(uint16_t adc_value) {
    return (float)adc_value * VREF / 4095.0;
}

// Voltage to Celsius conversion
float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);

    return 0;
}

// GPIO initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "tmp36_monitor", 0) < 0) {
        perror("Error requesting CS line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup
void gpio_cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    uint16_t adc_value;
    float voltage, temperature;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        gpio_cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        if (spi_transfer(MCP3208_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Validate ADC reading
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC value: %u, skipping.\n", adc_value);
            sleep(1);
            continue;
        }

        // Convert to voltage and Celsius
        voltage = adc_to_voltage(adc_value);
        temperature = voltage_to_celsius(voltage);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging failed, retrying in 1 second.\n");
        }

        printf("Temperature: %.2f °C\n", temperature);

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    gpio_cleanup();

    return 0;
}

