float adc_to_voltage(uint16_t adc_value) {
    return (float)adc_value * VREF / 4095.0;
}

// Voltage to Celsius conversion
float voltage_to_celsius(float voltage) {
    return (voltage - 0.5) / 0.01;
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,temperature_celsius\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fclose(log_file);

    return 0;
}

// GPIO initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip4");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, 8);
    if (!cs_line) {
        perror("Error getting CS line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "tmp36_monitor", 0) < 0) {
        perror("Error requesting CS line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup
void gpio_cleanup(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main(void) {
    uint16_t adc_value;
    float voltage, temperature;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        gpio_cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read ADC value
        if (spi_transfer(MCP3208_CHANNEL, &adc_value) < 0) {
            fprintf(stderr, "SPI transfer failed, retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Validate ADC reading
        if (adc_value < 0 || adc_value > 4095) {
            fprintf(stderr, "Invalid ADC value: %u, skipping.\n", adc_value);
            sleep(1);
            continue;
        }

        // Convert to voltage and Celsius
        voltage = adc_to_voltage(adc_value);
        temperature = voltage_to_celsius(voltage);

        // Log temperature
        if (log_temperature(temperature) < 0) {
            fprintf(stderr, "Logging failed, retrying in 1 second.\n");
        }

        printf("Temperature: %.2f °C\n", temperature);

        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    gpio_cleanup();

    return 0;
}

