#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define HR_REG 0xC1
#define SPO2_REG 0xC2
#define COMMAND_REG 0xC0
#define MEASURE_CMD 0x01
#define LOG_FILE "biometric_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int hr;
    int spo2;
    int error_flag;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sensor_data(sensor_data_t *data);
int process_sensor_data(int raw_hr, int raw_spo2, sensor_data_t *processed_data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw sensor data from the Si1172
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;

    // Trigger a measurement
    result = i2cWriteByteData(i2c_handle, COMMAND_REG, MEASURE_CMD);
    if (result < 0) {
        fprintf(stderr, "Error writing to command register: %d\n", result);
        data->error_flag = 1; // I2C error
        return -1;
    }

    // Wait for a short period for the measurement to complete
    gpioDelay(10000); // 10ms

    // Read HR and SpO2 data (4 bytes)
    result = i2cReadI2CBlockData(i2c_handle, HR_REG, buf, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data->error_flag = 1; // I2C error
        return -1;
    }

    // Extract raw HR and SpO2 values (assuming 16-bit each)
    data->hr = (buf[0] << 8) | buf[1];
    data->spo2 = (buf[2] << 8) | buf[3];

    return 0;
}

// Process raw sensor data (replace with actual Si1172 algorithm)
int process_sensor_data(int raw_hr, int raw_spo2, sensor_data_t *processed_data) {
    // This is a placeholder.  A real implementation would use
    // the Si1172's proprietary algorithm to convert the raw
    // PPG samples to HR and SpO2.
    processed_data->hr = raw_hr; // Placeholder HR
    processed_data->spo2 = raw_spo2; // Placeholder SpO2
    processed_data->error_flag = 0; // No error

    // Basic validation (replace with actual sensor limits)
    if (processed_data->hr < 40 || processed_data->hr > 200) {
        processed_data->error_flag = 3; // Invalid HR
    }
    if (processed_data->spo2 < 80 || processed_data->spo2 > 100) {
        processed_data->error_flag = 4; // Invalid SpO2
    }

    return 0;
}

// Log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.hr, data.spo2, data.error_flag);
    fflush(log_file); // Flush the buffer to ensure data is written

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR,SpO2,ErrorFlag\n");
    }
    rewind(log_file);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Process sensor data
            process_sensor_data(sensor_data.hr, sensor_data.spo2, &sensor_data);

            // Log the data
            log_data(sensor_data);
        } else {
            // Log an error if reading failed
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,0,0,1\n", timestamp);
            fflush(log_file);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

