#include <signal.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 3.3
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define LOG_FILE "flow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_spi();
int read_mcp3008(int channel);
float convert_to_flow_rate(int adc_value);
int log_data(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int mcp3008_channel;
    float vref;
    float flow_rate_min;
    float flow_rate_max;
    char *log_file;
} config_t;

config_t config = {
    SPI_CHANNEL,
    SPI_BAUD,
    MCP3008_CHANNEL,
    VREF,
    FLOW_RATE_MIN,
    FLOW_RATE_MAX,
    LOG_FILE
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Error initializing pigpio.\n");
        return 1;
    }

    // Open SPI
    if (open_spi() != 0) {
        fprintf(stderr, "Error opening SPI.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Continue to the next iteration
        }

        // Convert to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Log data
        if (log_data(flow_rate) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        // Sleep for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI
int open_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_baud, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate
float convert_to_flow_rate(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * config.vref;
    float flow_rate = (voltage / config.vref) * (config.flow_rate_max - config.flow_rate_min) + config.flow_rate_min;
    return flow_rate;
}

// Log data to file
int log_data(float flow_rate) {
    if (flow_rate < config.flow_rate_min || flow_rate > config.flow_rate_max) {
        fprintf(stderr, "Warning: Flow rate out of range: %.2f L/min\n", flow_rate);
    }

    // Get timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    // Write to file
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

