#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x67
#define MEASUREMENT_COMMAND 0x6845
#define DATA_LENGTH 6
#define RETRY_COUNT 3
#define RETRY_DELAY_SEC 5
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int i2c_open(int bus, int address);
int i2c_write(int fd, uint8_t *data, int length);
int i2c_read(int fd, uint8_t *data, int length);
int i2c_close(int fd);
int read_sensor_data(int fd, uint8_t *data);
sensor_data_t process_sensor_data(uint8_t *raw_data);
int log_data(FILE *fp, sensor_data_t data);
void display_data(sensor_data_t data);
void signal_handler(int sig);

// I2C open function
int i2c_open(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int length) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = write(fd, data, length);
        if (result == length) {
            return 0; // Success
        } else {
            perror("Error writing to I2C device");
            retries--;
            sleep(RETRY_DELAY_SEC);
        }
    }
    return -1; // Failure after retries
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int length) {
    int retries = RETRY_COUNT;
    int result;
    while (retries > 0) {
        result = read(fd, data, length);
        if (result == length) {
            return 0; // Success
        } else {
            perror("Error reading from I2C device");
            retries--;
            sleep(RETRY_DELAY_SEC);
        }
    }
    return -1; // Failure after retries
}

// I2C close function
int i2c_close(int fd) {
    if (close(fd) < 0) {
        perror("Error closing I2C device");
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int fd, uint8_t *data) {
    uint8_t command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    if (i2c_write(fd, command, 2) != 0) {
        fprintf(stderr, "Error writing measurement command.\n");
        return -1;
    }

    // Wait for conversion (adjust as needed based on sensor datasheet)
    usleep(10000); // 10ms

    if (i2c_read(fd, data, DATA_LENGTH) != 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(uint8_t *raw_data) {
    sensor_data_t data;
    // Placeholder for calibration formulas and data conversion
    // Replace with actual formulas from the ICP-10125 datasheet
    // This is a simplified example
    int32_t raw_pressure = (raw_data[0] << 16) | (raw_data[1] << 8) | raw_data[2];
    int32_t raw_temperature = (raw_data[3] << 16) | (raw_data[4] << 8) | raw_data[5];

    // Example calibration (replace with actual formulas)
    data.temperature = (float)raw_temperature / 100.0; // Dummy conversion
    data.pressure = (float)raw_pressure / 100.0;       // Dummy conversion

    return data;
}

// Function to log data to a file
int log_data(FILE *fp, sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.pressure);
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Function to display data on the console
void display_data(sensor_data_t data) {
    printf("Timestamp: %ld, Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", time(NULL), data.temperature, data.pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }

    uint8_t raw_data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, raw_data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(raw_data);

            // Log data
            log_data(log_file, sensor_data);

            // Display data
            display_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", RETRY_DELAY_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

