    printf("Timestamp: %ld, Temperature: %.2f \u00b0C, Pressure: %.2f Pa\n", time(NULL), data.temperature, data.pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2c_close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C),Pressure (Pa)\n");
    }

    uint8_t raw_data[DATA_LENGTH];
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, raw_data) == 0) {
            // Process sensor data
            sensor_data = process_sensor_data(raw_data);

            // Log data
            log_data(log_file, sensor_data);

            // Display data
            display_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying in %d seconds.\n", RETRY_DELAY_SEC);
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    i2c_close(i2c_fd);
    fclose(log_file);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

