// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define GAIN_DEFAULT 1.0

// Global variables
int spi_handle;
double gain = GAIN_DEFAULT;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
double process_audio_data(int channel0_value, int channel1_value);
void output_csv(double processed_data);
void signal_handler(int signal);

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    double default_gain;
} config_t;

config_t config = {SPI_CHANNEL, SPI_SPEED, GAIN_DEFAULT};

int main(int argc, char *argv[]) {
    // Parse command-line arguments for gain
    if (argc > 1) {
        char *endptr;
        gain = strtod(argv[1], &endptr);
        if (*endptr != '\0' || gain <= 0) {
            fprintf(stderr, "Error: Invalid gain value. Using default gain of %.2f.\n", GAIN_DEFAULT);
            gain = GAIN_DEFAULT;
        }
    }

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read audio data from MCP3008 channels
        int channel0_value = read_mcp3008(MCP3008_CHANNEL_0);
        int channel1_value = read_mcp3008(MCP3008_CHANNEL_1);

        // Process audio data
        double processed_data = process_audio_data(channel0_value, channel1_value);

        // Output CSV data
        output_csv(processed_data);

        // Delay for a short period
        gpioDelay(1000); // 1 ms delay
    }

    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        return 1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel\n");
        return 0; // Return 0 as a default value
    }

    // Construct SPI message (MCP3008 datasheet)
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return 0; // Return 0 as a default value
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Process audio data (noise cancellation)
double process_audio_data(int channel0_value, int channel1_value) {
    // Apply gain control
    double processed_data = (channel0_value - channel1_value) * gain;
    return processed_data;
}

// Output CSV data
void output_csv(double processed_data) {
    printf("%.2f\n", processed_data);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

