    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);

    while (!terminate) {
        // Read ADC value
        int adc_reading = read_mcp3008(MCP3008_CHANNEL);
