            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(adc_reading) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Wait for the next sample interval
        gpioDelay(SAMPLE_INTERVAL * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

