float read_temperature(void) {
    FILE *fp = fopen(TEMPERATURE_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        fprintf(stderr, "Using default temperature: 25.0\n");
        return 25.0;
    }

    float temperature;
    if (fscanf(fp, "%f", &temperature) != 1) {
        perror("Error reading temperature from file");
        fclose(fp);
        fprintf(stderr, "Using default temperature: 25.0\n");
        return 25.0;
    }

    fclose(fp);
    return temperature;
}

// Voltage Compensation
float voltage_compensation(int adc_value, float temperature) {
    float voltage = (float)adc_value / 1023.0 * 3.3;
    return voltage + (temperature - 25.0) * 0.001;
}

