    fflush(log_file);

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (buzzer_line) {
        buzzer_control(0); // Turn off buzzer
        gpiod_line_release(buzzer_line);
    }
    if (gpio_chip) {
