        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping iteration\n");
            buzzer_control(0); // Ensure buzzer is off on error
            sleep(SLEEP_MS / 1000.0); // Sleep for SLEEP_MS milliseconds
            continue;
        }

        // Read temperature
        float temperature = read_temperature();

