#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_HIGH 75.0
#define WATER_LEVEL_LOW 70.0
#define JSON_FILE "water_levels.json"

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_percentage(int adc_value);
void log_water_level(float percentage);
void control_led(float percentage);
void signal_handler(int signal);
int json_array_start(FILE *fp);
int json_array_end(FILE *fp);
int json_add_object(FILE *fp, const char *timestamp, float percentage);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (channel << 4)); // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) | rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to percentage
float convert_to_percentage(int adc_value) {
    return ((float)adc_value / 1023.0) * 100.0;
}

// Function to log water level to JSON file
void log_water_level(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (json_file == NULL) {
        fprintf(stderr, "Error: Could not open JSON file for writing.\n");
        return;
    }

    if (json_add_object(json_file, timestamp, percentage) != 0) {
        fprintf(stderr, "Error: Failed to add object to JSON file.\n");
    }
    fflush(json_file);
}

// Function to control LED based on water level
void control_led(float percentage) {
    if (percentage > WATER_LEVEL_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (percentage < WATER_LEVEL_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating program...\n");
    terminate = 1;
}

// Function to start the JSON array
int json_array_start(FILE *fp) {
    if (fprintf(fp, "[") < 0) {
        fprintf(stderr, "Error: Failed to write JSON array start.\n");
        return -1;
    }
    return 0;
}

// Function to end the JSON array
int json_array_end(FILE *fp) {
    if (fprintf(fp, "]") < 0) {
        fprintf(stderr, "Error: Failed to write JSON array end.\n");
        return -1;
    }
    return 0;
}

// Function to add a JSON object to the array
int json_add_object(FILE *fp, const char *timestamp, float percentage) {
    if (fprintf(fp, "{\"timestamp\": \"%s\", \"water_level\": %.2f}\n", timestamp, percentage) < 0) {
        fprintf(stderr, "Error: Failed to write JSON object.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file
    json_file = fopen(JSON_FILE, "a+");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Could not open JSON file for appending.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is empty, if so, start the array
    fseek(json_file, 0, SEEK_END);
    long file_size = ftell(json_file);
    if (file_size == 0) {
        if (json_array_start(json_file) != 0) {
            fclose(json_file);
            spiClose(spi_handle);
            gpioTerminate();
            return 1;
        }
    } else {
        // If the file is not empty, go back to the end to append
        fseek(json_file, -1, SEEK_END); // Go to the last character
        int last_char = fgetc(json_file);
        if (last_char != ']') {
            fseek(json_file, 0, SEEK_END);
            if (json_array_start(json_file) != 0) {
                fclose(json_file);
                spiClose(spi_handle);
                gpioTerminate();
                return 1;
            }
        } else {
            fseek(json_file, -1, SEEK_END); // Remove the ']'
        }
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value >= 0) {
            float percentage = convert_to_percentage(adc_value);
            log_water_level(percentage);
            control_led(percentage);
        } else {
            fprintf(stderr, "Error: Failed to read ADC value.\n");
        }

        gpioDelay(5000); // 5 seconds
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    if (json_array_end(json_file) != 0) {
        fprintf(stderr, "Error: Failed to write JSON array end.\n");
    }

    fclose(json_file);

    return 0;
}

