#define VREF 3.3 // Reference voltage for MCP3008
#define AWM7300V_MIN_VOLTAGE 0.5 // Minimum voltage output of AWM7300V
#define AWM7300V_MAX_VOLTAGE 4.5 // Maximum voltage output of AWM7300V
#define AWM7300V_MIN_FLOW 0.0 // Minimum flow rate (LPM)
#define AWM7300V_MAX_FLOW 200.0 // Maximum flow rate (LPM)
#define LOG_FILE "airflow_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_lpm(int adc_value);
char* get_iso8601_timestamp();
int log_data(char *timestamp, float flow_rate);
void signal_handler(int signal);
void cleanup();

