void send_email_alert(const char *timestamp, float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int spi_handle, int channel) {
    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int raw_value, int min_raw, int max_raw) {
    float moisture_percentage = 100.0 - ((float)(raw_value - min_raw) / (float)(max_raw - min_raw) * 100.0);
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    }
    if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }
    return moisture_percentage;
}

