                recipient_email = optarg;
                break;
            case 's':
                msmtp_config_file = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_raw] [-x max_raw] [-t moisture_threshold] [-f logging_frequency] [-r recipient_email] [-s msmtp_config_file]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(spi_channel, 500000, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int raw_value = read_mcp3008(spi_handle, adc_channel);
        if (raw_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in %d seconds\n", logging_frequency);
            sleep(logging_frequency);
            continue; // Retry on the next cycle
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture(raw_value, min_raw, max_raw);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data
        log_data(timestamp, moisture_percentage);

