#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_moisture.log"
#define SAMPLE_INTERVAL 1 // Seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
int log_data(int adc_value, float moisture_percentage);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    char *log_file;
    int sample_interval;
} Config;

Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    SPI_MODE,
    MCP3008_CHANNEL,
    LOG_FILE,
    SAMPLE_INTERVAL
};

int main(int argc, char *argv[]) {
    // Override sample interval if provided as command-line argument
    if (argc > 1) {
        config.sample_interval = atoi(argv[1]);
        if (config.sample_interval <= 0) {
            fprintf(stderr, "Invalid sample interval. Using default: %d seconds\n", config.sample_interval);
        }
    }

    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    while (!terminate) {
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value >= 0) {
            float moisture_percentage = calculate_moisture_percentage(adc_value);
            if (log_data(adc_value, moisture_percentage) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read ADC value.\n");
        }

        gpioDelay(config.sample_interval * 1000); // Delay in milliseconds
    }

    cleanup();
    return 0;
}

int initialize() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

