#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define SPI device and pins
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_CE 8
#define SPI_MOSI 10
#define SPI_MISO 9
#define SPI_SCLK 11

// Define calibration values
#define DRY_ADC 700
#define WET_ADC 300

// Global variables for GPIO and SPI
struct gpiod_chip *gpio_chip;
struct gpiod_line *spi_ce_line;
struct gpiod_line *spi_mosi_line;
struct gpiod_line *spi_miso_line;
struct gpiod_line *spi_sclk_line;
int spi_fd;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (spi_ce_line) {
        gpiod_line_release(spi_ce_line);
    }
    if (spi_mosi_line) {
        gpiod_line_release(spi_mosi_line);
    }
    if (spi_miso_line) {
        gpiod_line_release(spi_miso_line);
    }
    if (spi_sclk_line) {
        gpiod_line_release(spi_sclk_line);
    }

    // Close SPI device
    if (spi_fd > 0) {
        close(spi_fd);
    }

    // Release GPIO chip
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value, int dry_adc, int wet_adc) {
    float moisture_percentage = ((float)(adc_value - wet_adc) / (float)(dry_adc - wet_adc)) * 100.0;

    // Clamp moisture percentage between 0 and 100
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    }
    if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO lines
    spi_ce_line = gpiod_chip_get_line(gpio_chip, SPI_CE);
    spi_mosi_line = gpiod_chip_get_line(gpio_chip, SPI_MOSI);
    spi_miso_line = gpiod_chip_get_line(gpio_chip, SPI_MISO);
    spi_sclk_line = gpiod_chip_get_line(gpio_chip, SPI_SCLK);

    if (!spi_ce_line || !spi_mosi_line || !spi_miso_line || !spi_sclk_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(spi_ce_line, "soil_moisture", 0) < 0 ||
        gpiod_line_request_output(spi_mosi_line, "soil_moisture", 0) < 0 ||
        gpiod_line_request_input(spi_miso_line, "soil_moisture") < 0 ||
        gpiod_line_request_output(spi_sclk_line, "soil_moisture", 0) < 0) {
        perror("Failed to request GPIO line");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        gpiod_chip_close(gpio_chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value, DRY_ADC, WET_ADC);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[80];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log data to console
        printf("%s - Raw ADC: %d, Moisture: %.2f%%\n", timestamp, adc_value, moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

