#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MCP3008 channel connected to MLX90823
#define VREF 3.3 // Reference voltage of MCP3008
#define PRESSURE_MIN 10.0 // Minimum pressure in kPa
#define PRESSURE_MAX 150.0 // Maximum pressure in kPa
#define ADC_MIN 0 // Minimum ADC value
#define ADC_MAX 1023 // Maximum ADC value

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float pressure_min;
    float pressure_max;
    int adc_min;
    int adc_max;
} sensor_config_t;

// Function prototypes
int initialize_pigpio();
int initialize_spi(int channel, int speed);
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value, float vref);
float voltage_to_pressure(float voltage, float pressure_min, float pressure_max);
char* get_iso8601_timestamp();
void log_pressure_reading(float pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI communication
int initialize_spi(int channel, int speed) {
    spi_handle = spiOpen(channel, speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value, float vref) {
    return ((float)adc_value / 1023.0) * vref;
}

// Convert voltage to pressure
float voltage_to_pressure(float voltage, float pressure_min, float pressure_max) {
    return pressure_min + (voltage / 4.5) * (pressure_max - pressure_min);
}

// Get current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for timestamp

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    return timestamp;
}

// Log pressure reading with timestamp
void log_pressure_reading(float pressure) {
    char* timestamp = get_iso8601_timestamp();
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure);
    free(timestamp); // Free allocated memory
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi(SPI_CHANNEL, SPI_SPEED) != 0) {
        cleanup();
        return 1;
    }

    sensor_config_t config = {
        .spi_channel = SPI_CHANNEL,
        .spi_speed = SPI_SPEED,
        .mcp3008_channel = MCP3008_CHANNEL,
        .vref = VREF,
        .pressure_min = PRESSURE_MIN,
        .pressure_max = PRESSURE_MAX,
        .adc_min = ADC_MIN,
        .adc_max = ADC_MAX
    };

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Validate ADC value
        if (adc_value < config.adc_min || adc_value > config.adc_max) {
            fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value, config.vref);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage, config.pressure_min, config.pressure_max);

        // Log pressure reading
        log_pressure_reading(pressure);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

