#include <linux/spi/spidev.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define SPI device and channel
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// MCP3008 single-ended read command for channel 0
#define MCP3008_START_BIT 0x01
#define MCP3008_SINGLE_ENDED_CONFIG 0x80
#define MCP3008_DONT_CARE_BIT 0x00

// Global variable for SPI file descriptor
int spi_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_fd != -1) {
        close(spi_fd);
    }
    exit(0);
}

// Function to initialize SPI
int spi_init() {
    int fd;
    uint8_t mode = SPI_MODE;
    uint8_t bits = SPI_BITS_PER_WORD;
    uint32_t speed = SPI_SPEED;

    // Open SPI device
    fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read from MCP3008
int read_mcp3008(int spi_fd, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = MCP3008_START_BIT;
    tx_buf[1] = (MCP3008_SINGLE_ENDED_CONFIG | (channel << 4));
    tx_buf[2] = MCP3008_DONT_CARE_BIT;

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Perform SPI transfer
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error during SPI transfer");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    float percentage = (float)adc_value / 1023.0 * 100.0;
    return percentage;
}

// Function to log moisture percentage
void log_moisture_percentage(float percentage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Moisture percentage: %.2f%%\n", timestamp, percentage);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init();
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read ADC value from channel 0
        int adc_value = read_mcp3008(spi_fd, 0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Clamp moisture percentage to 0-100 range
        if (moisture_percentage < 0.0) {
            moisture_percentage = 0.0;
        } else if (moisture_percentage > 100.0) {
            moisture_percentage = 100.0;
        }

        // Log moisture percentage
        log_moisture_percentage(moisture_percentage);

        // Wait for 5 seconds
        sleep(5);
    }

    return 0;
}

