#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 300
#define MOISTURE_THRESHOLD_HIGH 600
#define SAMPLE_INTERVAL 5 // seconds
#define LOG_BUFFER_SIZE 20

// Data Structures
typedef struct {
    time_t timestamp;
    int moisture_level;
    int pump_state;
} LogEntry;

typedef struct {
    LogEntry buffer[LOG_BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Global Variables
int spi_handle;
CircularBuffer log_buffer;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int read_mcp3008(int channel);
void control_pump(int moisture_level);
void log_data(int moisture_level, int pump_state);
void print_log_buffer();
void timer_callback();
void signal_handler(int signal);
void init_circular_buffer(CircularBuffer *cb);

// Function Implementations

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Reads data from the MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3008 datasheet)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract 10-bit ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Controls the water pump based on moisture level
void control_pump(int moisture_level) {
    static int pump_state = 0; // 0 = off, 1 = on

    if (moisture_level < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
        gpioWrite(PUMP_GPIO, 1); // Turn pump on
        pump_state = 1;
        printf("Pump turned ON\n");
    } else if (moisture_level > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
        gpioWrite(PUMP_GPIO, 0); // Turn pump off
        pump_state = 0;
        printf("Pump turned OFF\n");
    }
}

// Logs data to the circular buffer
void log_data(int moisture_level, int pump_state) {
    time_t now = time(NULL);

    log_buffer.buffer[log_buffer.head].timestamp = now;
    log_buffer.buffer[log_buffer.head].moisture_level = moisture_level;
    log_buffer.buffer[log_buffer.head].pump_state = pump_state;

    log_buffer.head = (log_buffer.head + 1) % LOG_BUFFER_SIZE;
    if (log_buffer.count < LOG_BUFFER_SIZE) {
        log_buffer.count++;
    }
}

// Prints the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < log_buffer.count; i++) {
        int index = (log_buffer.head - log_buffer.count + i + LOG_BUFFER_SIZE) % LOG_BUFFER_SIZE;
        char timestamp_str[30];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", localtime(&log_buffer.buffer[index].timestamp));
        printf("Timestamp: %s, Moisture: %d, Pump: %s\n",
               timestamp_str, log_buffer.buffer[index].moisture_level,
               log_buffer.buffer[index].pump_state ? "ON" : "OFF");
    }
    printf("--- End of Log Buffer ---\n\n");
}

// Timer callback function
void timer_callback() {
    int moisture_level = read_mcp3008(0);
    if (moisture_level == -1) {
        fprintf(stderr, "Error: Failed to read moisture level\n");
        return;
    }

    control_pump(moisture_level);
    log_data(moisture_level, gpioRead(PUMP_GPIO));
    print_log_buffer();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    init_circular_buffer(&log_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer callback
    gpioSetTimerFuncEx(0, SAMPLE_INTERVAL * 1000, timer_callback, NULL); // Timer 0, every 5 seconds

    printf("Soil Moisture Monitoring and Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Cleanup
    gpioWrite(PUMP_GPIO, 0); // Ensure pump is off
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

