#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MAX30102_ADDR 0x57
#define PART_ID_REG 0xFF
#define MODE_CONFIG_REG 0x06
#define SPO2_CONFIG_REG 0x08
#define LED1_PA_REG 0x09
#define LED2_PA_REG 0x0A
#define FIFO_DATA_REG 0x07
#define FIFO_WRITE_PTR_REG 0x08
#define FIFO_READ_PTR_REG 0x09
#define FIFO_SAMPLES_REG 0x0A
#define INTERRUPT_ENABLE_REG 0x02
#define INTERRUPT_STATUS_REG 0x03

#define RED_CHANNEL 0
#define IR_CHANNEL 1

#define SAMPLE_RATE 100 // Hz
#define PULSE_WIDTH 411 // us
#define ADC_RANGE 4096

#define SPO2_THRESHOLD 95
#define HR_THRESHOLD 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_fifo_data(int *red, int *ir);
float calculate_spo2(int *red, int *ir, int num_samples);
float calculate_heart_rate(int *ir, int num_samples);
void log_data(float spo2, float heart_rate);
void signal_handler(int signal);

// Structure for sensor configuration
typedef struct {
    int sample_rate;
    int pulse_width;
    int adc_range;
} sensor_config_t;

// Function to write a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

// Function to initialize the MAX30102 sensor
int init_max30102() {
    // Reset the sensor
    if (write_register(i2c_handle, MODE_CONFIG_REG, 0x40) != 0) {
        fprintf(stderr, "Error resetting MAX30102\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure mode (SpO2 mode)
    if (write_register(i2c_handle, MODE_CONFIG_REG, 0x03) != 0) {
        fprintf(stderr, "Error configuring mode\n");
        return -1;
    }

    // Configure SPO2 settings
    if (write_register(i2c_handle, SPO2_CONFIG_REG, 0x27) != 0) {
