// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_voltage(int adc_value);
void log_data(int channel, float voltage);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];
    int count;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    for (count = 0; count < 3; count++) {
        int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
        if (result != 0) {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", count + 1, result);
            gpioDelay(1000); // Wait 1 ms before retrying
            continue;
        }
        break; // Exit loop if transfer is successful
    }

    if (count == 3) {
        fprintf(stderr, "SPI transfer failed after multiple retries.\n");
        return -1; // Indicate failure
    }

    // Combine the last two bytes to get the 10-bit ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to calculate voltage from ADC value
float calculate_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Function to log data to CSV file
void log_data(int channel, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%.3f\n", timestamp, channel, voltage);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    int i;
    int adc_value;
    float voltage;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Reading analog values from MCP3008... Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                voltage = calculate_voltage(adc_value);
                log_data(i, voltage);
                printf("Channel %d: Voltage = %.3f V\n", i, voltage);
            } else {
                fprintf(stderr, "Failed to read from channel %d\n", i);
            }
        }
        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

