#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MQ2_CHANNEL 0
#define BUZZER_GPIO 24
#define THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mq2_value();
void control_buzzer(int mq2_value);
void signal_handler(int signal);

// Function to read the MQ-2 sensor value from MCP3008
int read_mq2_value() {
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];
    int adc_value;

    // MCP3008 command to read channel 0 (single-ended)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | MQ2_CHANNEL) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI read/write failed\n");
        return -1; // Indicate error
    }

    // Extract the ADC value from the response
    adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to control the buzzer based on the MQ-2 value
void control_buzzer(int mq2_value) {
    if (mq2_value < THRESHOLD) {
        gpioWrite(BUZZER_GPIO, 0); // Turn buzzer OFF
    } else {
        gpioWrite(BUZZER_GPIO, 1); // Turn buzzer ON
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MQ-2 Gas Sensor Monitoring and Buzzer Control\n");

    // Main loop
    while (!terminate) {
        int mq2_value = read_mq2_value();
        if (mq2_value >= 0) {
            printf("MQ-2 Value: %d\n", mq2_value);
            control_buzzer(mq2_value);
        } else {
            fprintf(stderr, "Error: Failed to read MQ-2 value\n");
        }

        gpioDelay(500); // Sample every 500 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is OFF
    gpioTerminate();

    printf("Program terminated successfully.\n");
    return 0;
}

