#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <math.h>

// Configuration
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00
#define RELAY_GPIO_PIN 17
#define DOOR_SENSOR_GPIO_PIN 27
#define NUM_BASELINE_SAMPLES 10
#define BASELINE_SAMPLE_INTERVAL_MS 50
#define THRESHOLD_PERCENT 80
#define RELAY_ACTIVATION_DURATION_MS 3000
#define POLL_INTERVAL_MS 200
#define LOG_FILE "/var/log/door_events.log"

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static struct gpiod_line *door_sensor_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int read_distance_sensor(int fd);
double calculate_baseline(int fd);
int is_door_open(struct gpiod_line *line);
void log_event(const char *message);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    struct i2c_msg msgs[2];

    buf[0] = reg;

    msgs[0].addr = ADS1115_ADDR;
    msgs[0].flags = 0; // Write
    msgs[0].len = 1;
    msgs[0].buf = buf;

    msgs[1].addr = ADS1115_ADDR;
    msgs[1].flags = I2C_M_RD; // Read
    msgs[1].len = 2;
    msgs[1].buf = buf;

    if (ioctl(fd, I2C_RDWR, msgs) < 0) {
        perror("I2C read failed");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// I2C write function
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];

    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("I2C write failed");
        return -1;
    }

    return 0;
}

// Read distance sensor function
int read_distance_sensor(int fd) {
    int16_t raw_value = i2c_read_word(fd, ADS1115_REG_CONVERT);
    if (raw_value < 0) {
        log_event("Error reading distance sensor");
        return -1;
    }
    return raw_value;
}

// Calculate baseline function
double calculate_baseline(int fd) {
    double sum = 0.0;
    for (int i = 0; i < NUM_BASELINE_SAMPLES; i++) {
        int raw_value = read_distance_sensor(fd);
        if (raw_value < 0) {
            return -1.0; // Indicate error
        }
        sum += raw_value;
        usleep(BASELINE_SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }
    return sum / NUM_BASELINE_SAMPLES;
}

// Check if door is open function
int is_door_open(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        log_event("Error reading door sensor");
        return -1; // Indicate error
    }
    return (value == 0) ? 1 : 0; // Active-low
}

// Log event function
void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return;
    }

    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler function
void signal_handler(int sig) {
    log_event("Signal received, cleaning up...");
    terminate = 1;
}

// Setup GPIO function
int setup_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO_PIN);
    if (!relay_line) {
        perror("Failed to get relay GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "door_lock", 0) < 0) {
        perror("Failed to request relay GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    door_sensor_line = gpiod_chip_get_line(gpio_chip, DOOR_SENSOR_GPIO_PIN);
    if (!door_sensor_line) {
        perror("Failed to get door sensor GPIO line");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
    }

    if (gpiod_line_request_input(door_sensor_line, "door_sensor") < 0) {
        perror("Failed to request door sensor GPIO line for input");
        gpiod_chip_close(gpio_chip);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Cleanup GPIO function
void cleanup_gpio(void) {
    if (relay_line) {
        gpiod_line_set_value(relay_line, 0); // De-energize relay
        gpiod_line_release(relay_line);
    }
    if (door_sensor_line) {
        gpiod_line_release(door_sensor_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // I2C setup
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // ADS1115 configuration (Single-shot mode, AIN0, +/-4.096V, 128 SPS)
    uint16_t config = 0x4083; //0b0100000010000011;
    if (i2c_write_word(i2c_fd, ADS1115_REG_CONFIG, config) < 0) {
        log_event("Failed to configure ADS1115");
        close(i2c_fd);
        return 1;
    }

    // GPIO setup
    if (setup_gpio() < 0) {
        log_event("GPIO setup failed");
        close(i2c_fd);
        return 1;
    }

    // Calculate baseline
    double baseline = calculate_baseline(i2c_fd);
    if (baseline < 0) {
        log_event("Failed to calculate baseline");
        cleanup_gpio();
        close(i2c_fd);
        return 1;
    }
    log_event("Baseline calculated");

    // Threshold calculation
    double threshold = baseline * (THRESHOLD_PERCENT / 100.0);
    char threshold_str[50];
    snprintf(threshold_str, sizeof(threshold_str), "Threshold set to: %.2f", threshold);
    log_event(threshold_str);

    // Main loop
    while (!terminate) {
        int raw_distance = read_distance_sensor(i2c_fd);
        if (raw_distance < 0) {
            log_event("Failed to read distance sensor, retrying...");
            usleep(POLL_INTERVAL_MS * 1000); // Wait before retrying
            continue;
        }

        double distance = (double)raw_distance; // Assuming raw value is directly proportional to distance

        if (distance < threshold) {
            log_event("Distance below threshold, releasing lock");
            gpiod_line_set_value(relay_line, 1); // Energize relay
            usleep(RELAY_ACTIVATION_DURATION_MS * 1000); // Wait for activation duration
            gpiod_line_set_value(relay_line, 0); // De-energize relay

            int door_open = is_door_open(door_sensor_line);
            if (door_open < 0) {
                log_event("Failed to check door status");
            } else if (door_open) {
                log_event("Door opened");
            } else {
                log_event("Door not opened");
            }
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every POLL_INTERVAL_MS ms
    }

    // Cleanup
    cleanup_gpio();
    close(i2c_fd);
    log_event("Exiting cleanly");

    return 0;
}

