#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_BITS_PER_WORD 8

#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

#define NUM_SENSORS 3
#define LOG_FILE "soil_moisture_log.csv"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_lines[NUM_SENSORS] = {NULL};
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int gpio_init(void);
int read_mcp3008(int chip_select_line, int channel);
int log_data(FILE *fp, int sensor1, int sensor2, int sensor3);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Open chip-select lines
    for (int i = 0; i < NUM_SENSORS; i++) {
        cs_lines[i] = gpiod_chip_get_line(gpio_chip, (i == 0) ? CS0_PIN : ((i == 1) ? CS1_PIN : CS2_PIN));
        if (!cs_lines[i]) {
            perror("Error getting GPIO line");
            gpiod_chip_close(gpio_chip);
            return -1;
        }

        ret = gpiod_line_request_output(cs_lines[i], "soil_moisture", 0); // Initial value LOW
        if (ret < 0) {
            perror("Error requesting GPIO line as output");
            gpiod_chip_close(gpio_chip);
            return -1;
        }
    }

    return 0;
}

// Read from MCP3008
int read_mcp3008(int chip_select_line, int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];
    int ret;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Shift left to align with the 4 bits of don't care
    tx_buf[2] = 0x00;

    // Configure SPI transfer
    memset(transfer, 0, sizeof(transfer));
    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].delay_usecs = 0;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    // Activate chip select
    ret = gpiod_line_set_value(cs_lines[chip_select_line], 0); // LOW
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    usleep(1); // Small delay after CS activation

    // Perform SPI transfer
