#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define PUMP_GPIO 18
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define DEFAULT_THRESHOLD 30
#define DEFAULT_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60

// Global variables
int spi_handle;
int pump_state = 0; // 0 = off, 1 = on
int running = 1;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value, int dry_value, int wet_value);
void control_pump(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Retry loop
    int retries = 3;
    int result = -1;
    while (retries > 0) {
        result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
        if (result == 0) {
            // Extract ADC value
            int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI read failed (attempt %d): %d\n", 4 - retries, result);
            log_event("SPI read failed. Retrying...");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "SPI read failed after multiple retries.\n");
    log_event("SPI read failed after multiple retries.");
    return -1; // Indicate failure
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value, int dry_value, int wet_value) {
    float moisture = 100.0 - ((float)(adc_value - wet_value) / (float)(dry_value - wet_value)) * 100.0;
    if (moisture < 0.0) moisture = 0.0;
    if (moisture > 100.0) moisture = 100.0;
    return moisture;
}

// Function to control the water pump
void control_pump(int state) {
    if (state != pump_state) {
        gpioWrite(PUMP_GPIO, state);
        pump_state = state;
        char message[50];
        sprintf(message, "Pump %s", state ? "activated" : "deactivated");
        log_event(message);
    }
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int threshold = DEFAULT_THRESHOLD;
    int duration = DEFAULT_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            case 's':
                sleep_interval = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d duration] [-s sleep_interval]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for pump control
    gpioSetMode(PUMP_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        log_event("SPI open failed. Exiting.");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read soil moisture sensor
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Skipping irrigation cycle.\n");
            sleep(sleep_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture = calculate_moisture(adc_value, 800, 200);
        char message[50];
        sprintf(message, "Moisture: %.2f%% (ADC: %d)", moisture, adc_value);
        log_event(message);

        // Control pump based on moisture level
        if (moisture < threshold) {
            control_pump(1); // Activate pump
            printf("Moisture below threshold. Activating pump for %d seconds.\n", duration);
            sleep(duration);
            control_pump(0); // Deactivate pump
        }

        // Sleep for the specified interval
        sleep(sleep_interval);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_pump(0); // Turn off the pump
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

