#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define PCF8591_ADDR 0x48

// Define the control byte for single-ended mode on AIN0
#define CONTROL_BYTE 0x40

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl-C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read the ADC value from PCF8591
int read_adc(int fd, uint8_t control_byte) {
    uint8_t buffer[2];

    // Write the control byte to initiate the conversion
    if (write(fd, &control_byte, 1) != 1) {
        perror("Error writing control byte");
        return -1;
    }

    // Read two bytes from the ADC (dummy read + actual read)
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading ADC value");
        return -1;
    }

    // Return only the actual ADC value (the second byte)
    return buffer[1];
}

int main() {
    // Register the signal handler for Ctrl-C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, PCF8591_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    printf("PCF8591 ADC Monitor\n");

    // Main loop to continuously read and print the ADC value
    while (1) {
        int adc_value = read_adc(i2c_fd, CONTROL_BYTE);
        if (adc_value >= 0) {
            printf("ADC Value: %d\n", adc_value);
        } else {
            fprintf(stderr, "Error reading ADC value. Retrying...\n");
        }

        usleep(100000); // Sleep for 100 milliseconds
    }

    return 0;
}

