#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define AIN0_CHANNEL 0
#define GAUSS_THRESHOLD 500.0
#define GPIO_PIN 27
#define SAMPLE_RATE_HZ 1
#define VOLTAGE_RANGE 3.3
#define ZERO_FIELD_VOLTAGE 2.5
#define SENSITIVITY 1.4
#define BUFFER_SIZE 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize();
int read_ads1115(int channel);
float convert_to_gauss(int16_t raw_value);
void update_circular_buffer(CircularBuffer *cb, float value);
float calculate_rolling_average(CircularBuffer *cb);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Update the circular buffer with a new value
void update_circular_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the rolling average of the circular buffer
float calculate_rolling_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize pigpio and I2C
int initialize() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure GPIO is initially LOW

    return 0;
}

// Read data from ADS1115
int read_ads1115(int channel) {
    char config[3];
    int16_t raw_value;

    // Configure ADS1115 for single-ended mode, 128 SPS, channel AIN0
    config[0] = 0x01; // Configuration register address
    config[1] = 0xC3; // Single-ended AIN0, 128 SPS, start single conversion
    config[2] = 0x83; // +/- 4.096V, disable comparator

    if (i2cWriteDevice(i2c_handle, config, 3) != 0) {
        syslog(LOG_ERR, "Failed to write to ADS1115");
        return -1;
    }

    // Wait for conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10000); // 10 ms

    // Read the conversion result
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read from ADS1115");
        return -1;
    }

    raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Convert raw ADC value to Gauss
float convert_to_gauss(int16_t raw_value) {
    float voltage = (float)raw_value / 32767.0 * VOLTAGE_RANGE; // Assuming 16-bit ADC
    float gauss = (voltage - ZERO_FIELD_VOLTAGE) / (SENSITIVITY / 1000.0); // Convert mV/Gauss to Gauss
    return gauss;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, terminating...", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();
}

int main() {
    openlog("hall_sensor", LOG_PID, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    if (initialize() != 0) {
        syslog(LOG_ERR, "Initialization failed, exiting");
        return 1;
    }

    CircularBuffer gauss_buffer;
    circular_buffer_init(&gauss_buffer);

    while (!terminate) {
        int raw_value = read_ads1115(AIN0_CHANNEL);
        if (raw_value < 0) {
            syslog(LOG_ERR, "Failed to read sensor data");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        float gauss = convert_to_gauss(raw_value);

        if (gauss < 0 || gauss > VOLTAGE_RANGE) {
            syslog(LOG_WARNING, "Invalid Gauss value: %f", gauss);
        } else {
            update_circular_buffer(&gauss_buffer, gauss);
            float rolling_average = calculate_rolling_average(&gauss_buffer);

            syslog(LOG_INFO, "Raw: %d, Gauss: %f, Rolling Average: %f", raw_value, gauss, rolling_average);

            if (rolling_average > GAUSS_THRESHOLD) {
                syslog(LOG_WARNING, "Threshold exceeded: %f > %f", rolling_average, GAUSS_THRESHOLD);
                gpioWrite(GPIO_PIN, 1); // Set GPIO HIGH
            } else {
                gpioWrite(GPIO_PIN, 0); // Set GPIO LOW
            }
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ); // Delay to achieve desired sample rate
    }

    cleanup();
    return 0;
}

