    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the rain sensor value from MCP3008
int read_rain_sensor(int spi_handle) {
    unsigned char tx_buffer[3];
    unsigned char rx_buffer[3];
    int adc_value;

    // MCP3008 single-ended read sequence:
    // Start bit (1), single/diff (1), channel (3), don't care (3)
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | (RAIN_SENSOR_CHANNEL << 4)); // Single-ended, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed. Retrying...\n");
        return -1; // Indicate error
    }

    // Extract ADC value from the received data
    adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map the ADC value to a rainfall intensity level
int map_adc_to_intensity(int adc_value) {
    if (adc_value < 0) return 0; // Handle potential negative values
    if (adc_value > ADC_MAX_VALUE) return INTENSITY_MAX_LEVEL; // Handle potential out-of-range values

    return (int)(((float)adc_value / ADC_MAX_VALUE) * INTENSITY_MAX_LEVEL);
}

// Function to log the data to stdout
void log_data(int adc_value, int intensity_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - ADC Value: %d, Intensity Level: %d\n", timestamp, adc_value, intensity_level);
}

