    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // SPI channel 0, 1 MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        int adc_value = read_rain_sensor(spi_handle);
        if (adc_value >= 0) {
            int intensity_level = map_adc_to_intensity(adc_value);
            log_data(adc_value, intensity_level);
        } else {
            fprintf(stderr, "Error: Failed to read rain sensor. Skipping logging.\n");
        }

        gpioDelay(1000); // Delay for 1 second
    }

    // The following lines will never be reached due to the infinite loop.
    spiClose(spi_handle);
    gpioTerminate();
    return 0;
}

