#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>
#include <MQTTClient.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_BROKER_ADDRESS "tcp://localhost:1883" // Replace with your broker address
#define MQTT_CLIENT_ID "soil_moisture_sensor"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define MQTT_TOPIC_SOIL_MOISTURE "soil_moisture"
#define MQTT_TOPIC_ERROR "error"
#define MQTT_QOS 1
#define SLEEP_INTERVAL 60 // seconds

// Global variables
int spi_handle;
MQTTClient mqtt_client;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture(int adc_value);
void control_relay(int state);
int mqtt_connect();
void mqtt_disconnect();
void mqtt_message_callback(char *topicName, int topicLen, MQTTClient_message *message);
void mqtt_connect_callback(void *context, MQTTClient_connect_options *conn_opts);
void mqtt_subscribe_callback(void *context, MQTTClient_deliveryToken dt);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message(LOG_ERR, "Invalid MCP3008 channel");
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int spi_result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (spi_result != 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "SPI transfer failed: %d", spi_result);
        log_message(LOG_ERR, error_message);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture(int adc_value) {
    // Assuming ADC value of 0 corresponds to 100% moisture
    // and ADC value of 1023 corresponds to 0% moisture
    float moisture = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return moisture;
}

// Function to control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_GPIO, state) != 0) {
        log_message(LOG_ERR, "Failed to write to relay GPIO");
    }
}

// MQTT connect function
int mqtt_connect() {
    MQTTClient_connectOptions conn_opts = MQTTClient_connectOptions_initializer;
    int rc;

    MQTTClient_create(&mqtt_client, MQTT_BROKER_ADDRESS, MQTT_CLIENT_ID, MQTTCLIENT_PERSISTENCE_NONE, NULL);

    conn_opts.keepAliveInterval = 20;
    conn_opts.cleansession = 1;
    conn_opts.username = NULL;
    conn_opts.password = NULL;

    conn_opts.onSuccess = mqtt_connect_callback;
    conn_opts.onFailure = NULL;
    conn_opts.context = NULL;

    rc = MQTTClient_connect(mqtt_client, &conn_opts);
    if (rc != MQTTCLIENT_SUCCESS) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to connect to MQTT broker: %s", MQTTClient_strerror(rc));
        log_message(LOG_ERR, error_message);
        return -1;
    }

    rc = MQTTClient_subscribe(mqtt_client, MQTT_TOPIC_PUMP_CONTROL, MQTT_QOS);
    if (rc != MQTTCLIENT_SUCCESS) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to subscribe to topic: %s", MQTTClient_strerror(rc));
        log_message(LOG_ERR, error_message);
        return -1;
    }

    return 0;
}

// MQTT disconnect function
void mqtt_disconnect() {
    MQTTClient_disconnect(mqtt_client, 1000);
    MQTTClient_destroy(&mqtt_client);
}

// MQTT message callback function
void mqtt_message_callback(char *topicName, int topicLen, MQTTClient_message *message) {
    char *payload = message->payload;
    if (strcmp(topicName, MQTT_TOPIC_PUMP_CONTROL) == 0) {
        if (strcmp(payload, "pump_on") == 0) {
            control_relay(1); // Turn pump ON
            log_message(LOG_INFO, "Received pump_on command, turning pump ON");
        } else if (strcmp(payload, "pump_off") == 0) {
            control_relay(0); // Turn pump OFF
            log_message(LOG_INFO, "Received pump_off command, turning pump OFF");
        } else {
            log_message(LOG_WARNING, "Received invalid pump command");
        }
    }
    MQTTClient_freeMessage(&message);
    MQTTClient_free(topicName);
}

// MQTT connect callback function
void mqtt_connect_callback(void *context, MQTTClient_connect_options *conn_opts) {
    log_message(LOG_INFO, "Connected to MQTT broker");
}

// MQTT subscribe callback function
void mqtt_subscribe_callback(void *context, MQTTClient_deliveryToken dt) {
    log_message(LOG_INFO, "Subscribed to MQTT topic");
}

// Signal handler function
void signal_handler(int signal) {
    log_message(LOG_INFO, "Signal received, cleaning up...");
    terminate = 1;
}

// Log message function
void log_message(int priority, const char *message) {
    openlog("soil_moisture_sensor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(priority, message);
    closelog();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "SPI open failed: %d", spi_handle);
        log_message(LOG_ERR, error_message);
        gpioTerminate();
        return 1;
    }

    // Initialize MQTT
    if (mqtt_connect() != 0) {
        log_message(LOG_ERR, "MQTT connection failed");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read soil moisture
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            log_message(LOG_ERR, "Failed to read ADC value");
        } else {
            float moisture = calculate_moisture(adc_value);

            // Control relay based on moisture level
            if (moisture < MOISTURE_THRESHOLD_LOW && gpioRead(RELAY_GPIO) == 0) {
                control_relay(1); // Turn pump ON
                log_message(LOG_INFO, "Moisture level low, turning pump ON");
            } else if (moisture > MOISTURE_THRESHOLD_HIGH && gpioRead(RELAY_GPIO) == 1) {
                control_relay(0); // Turn pump OFF
                log_message(LOG_INFO, "Moisture level high, turning pump OFF");
            }

            // Publish moisture reading to MQTT
            char moisture_str[20];
            snprintf(moisture_str, sizeof(moisture_str), "%.2f", moisture);
            MQTTClient_message pubmsg = MQTTClient_message_initializer;
            pubmsg.payload = moisture_str;
            pubmsg.payloadlen = strlen(moisture_str);
            pubmsg.qos = MQTT_QOS;
            pubmsg.retained = 0;

            MQTTClient_deliveryToken token;
            int rc = MQTTClient_publishMessage(mqtt_client, MQTT_TOPIC_SOIL_MOISTURE, &pubmsg, &token);
            if (rc != MQTTCLIENT_SUCCESS) {
                char error_message[100];
                snprintf(error_message, sizeof(error_message), "Failed to publish message: %s", MQTTClient_strerror(rc));
                log_message(LOG_ERR, error_message);
            }
        }

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Cleanup
    mqtt_disconnect();
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

