    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s - Noise level: %d\n", timestamp, adc_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to stop motors and close SPI
void cleanup(void) {
    printf("Cleaning up...\n");

    // Stop motors
    set_motor_speed(MOTOR1_GPIO, 0);
    set_motor_speed(MOTOR2_GPIO, 0);

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main(void) {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_GPIO, PWM_FREQUENCY);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Vibration motor control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Optionally add retry logic here
            continue; // Skip to the next iteration
        }

        // Check if noise level exceeds threshold
        if (adc_value > NOISE_THRESHOLD) {
            // Map ADC value to duty cycle (0-1000)
            int duty_cycle = (int)(((float)adc_value / 1023.0) * 1000.0);

            // Set motor speeds
            set_motor_speed(MOTOR1_GPIO, duty_cycle);
            set_motor_speed(MOTOR2_GPIO, duty_cycle);

            // Log event
            log_event(adc_value);
        } else {
            // Turn off motors
            set_motor_speed(MOTOR1_GPIO, 0);
            set_motor_speed(MOTOR2_GPIO, 0);
        }

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

