    // Send measurement command
    buf[0] = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    // Wait for measurement (at least 180 ms)
    usleep(180000);

    // Read 2 bytes of data
    if (read(i2c_fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert to lux
    unsigned int raw_value = (buf[0] << 8) | buf[1];
    *lux = (double)raw_value / 1.2;

    return 0;
}

