    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = spi_read_adc(0);
        double sound_db;
        double light_lux;
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            sound_db = -999.0; // Indicate error
            error_code = 1;
        } else {
            sound_db = adc_to_db(adc_value);
        }

        if (i2c_read_bh1750(&light_lux) != 0) {
            fprintf(stderr, "Error reading light level\n");
            light_lux = -999.0; // Indicate error
            error_code = 2;
        }

        log_data(sound_db, light_lux, error_code);

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    fclose(log_file);
    close(spi_fd);
    close(i2c_fd);
    gpioTerminate();

    return 0;
}

