#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define RELAY_GPIO 17
#define RELAY_ACTIVE_HIGH 1
#define PROXIMITY_THRESHOLD 20 // cm
#define DEBOUNCE_DELAY 1000000 // 1 second (in microseconds)
#define POLLING_INTERVAL 100000 // 100 ms (in microseconds)
#define LOG_FILE "door_events.log"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *relay_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int read_mcp3008(int channel);
float adc_to_distance(int adc_value);
int gpio_init(void);
int control_relay(int state);
int log_event(const char *event);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Convert ADC value to distance (cm) - Example calibration
float adc_to_distance(int adc_value) {
    // This is a placeholder.  You MUST calibrate this.
    // The GP2Y0A21YK0F has a non-linear relationship between ADC value and distance.
    // You'll need to determine the relationship empirically.
    // Example (replace with your calibration data):
    // distance = A * adc_value^2 + B * adc_value + C
    // Where A, B, and C are constants determined by your calibration.
    // This is a simplified example.  A real implementation would involve a lookup table or polynomial fit.

    // Example linear approximation (replace with your calibration):
    float distance = 29.1 * adc_value; // Example: 29.1 cm per ADC unit

    // Clamp the distance to a reasonable range (e.g., 10cm - 80cm)
    if (distance < 10.0) distance = 10.0;
    if (distance > 80.0) distance = 80.0;

    return distance;
}

// GPIO Initialization
int gpio_init(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    relay_line = gpiod_chip_get_line(gpio_chip, RELAY_GPIO);
    if (!relay_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(relay_line, "relay_control", RELAY_ACTIVE_HIGH) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Control Relay
int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Log Event
int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting...\n");
        terminate = 1;
    }
}

// Cleanup
void cleanup(void) {
    printf("Cleaning up...\n");

    // Disable relay
    if (relay_line) {
        control_relay(0);
    }

    // Close SPI device
    if (spi_fd != -1) {
        close(spi_fd);
    }

    // Release GPIO line
    if (relay_line) {
        gpiod_line_release(relay_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize hardware
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (gpio_init() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    int proximity_detected = 0;
    struct timespec last_trigger_time = {0, 0};

    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d ms.\n", POLLING_INTERVAL / 1000);
            nanosleep(&(struct timespec){0, POLLING_INTERVAL}, NULL);
            continue;
        }

        // Convert ADC value to distance
        float distance = adc_to_distance(adc_value);

        // Check for proximity
        if (distance < PROXIMITY_THRESHOLD) {
            if (!proximity_detected) {
                // Trigger relay
                if (control_relay(1) < 0) {
                    fprintf(stderr, "Error controlling relay. \n");
                }

                // Log event
                if (log_event("Proximity detected, relay activated") < 0) {
                    fprintf(stderr, "Error logging event. \n");
                }

                // Debounce
                clock_gettime(CLOCK_MONOTONIC, &last_trigger_time);
                proximity_detected = 1;
            } else {
                // Check debounce time
                struct timespec current_time;
                clock_gettime(CLOCK_MONOTONIC, &current_time);
                long elapsed_time = (current_time.tv_sec - last_trigger_time.tv_sec) * 1000000 + (current_time.tv_nsec - last_trigger_time.tv_nsec) / 1000;

                if (elapsed_time >= DEBOUNCE_DELAY) {
                    proximity_detected = 0; // Reset debounce
                }
            }
        } else {
            // Reset debounce
            proximity_detected = 0;

            // Deactivate relay if not already off
            if (gpiod_line_get_value(relay_line) == 1) {
                if (control_relay(0) < 0) {
                    fprintf(stderr, "Error controlling relay. \n");
                }

                // Log event
                if (log_event("Proximity cleared, relay deactivated") < 0) {
                    fprintf(stderr, "Error logging event. \n");
                }
            }
        }

        // Wait before next poll
        nanosleep(&(struct timespec){0, POLLING_INTERVAL}, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

