#include <unistd.h>
#include <pigpio.h>

// Constants
#define VALVE_GPIO 17
#define SPI_CHANNEL 0
#define SPI_CE 8
#define SPI_FREQUENCY 1000000 // 1 MHz
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define NUM_SENSORS 3
#define LOG_FILE "irrigation.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float average_soil_moisture(int sensor_values[NUM_SENSORS]);
int map_to_pwm(float average_moisture);
void log_data(int sensor_values[NUM_SENSORS], float average_moisture, int valve_position);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (single-ended mode)
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", channel);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to average soil moisture readings
float average_soil_moisture(int sensor_values[NUM_SENSORS]) {
    float sum = 0.0;
    int count = 0;

    for (int i = 0; i < NUM_SENSORS; i++) {
        if (sensor_values[i] != -1) {
            sum += sensor_values[i];
            count++;
        }
    }

    if (count == 0) {
        return 0.0; // Avoid division by zero
    }

    return sum / count;
}

// Function to map average moisture to PWM duty cycle
int map_to_pwm(float average_moisture) {
    // Inverse relationship: higher moisture = lower valve opening
    // Map 0-1023 to 100-0
    int pwm_value = 100 - (int)((average_moisture / 1023.0) * 100.0);

    // Clamp the PWM value to the valid range
    if (pwm_value < 0) {
        pwm_value = 0;
    } else if (pwm_value > 100) {
        pwm_value = 100;
    }

    return pwm_value;
}

// Function to log data to file
void log_data(int sensor_values[NUM_SENSORS], float average_moisture, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d, %d\n", timestamp,
            sensor_values[0], sensor_values[1], sensor_values[2],
            (int)average_moisture, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as PWM output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_FREQUENCY, 0); // SPI mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Logging to %s\n", LOG_FILE);

    // Main loop
    while (!terminate) {
        int sensor_values[NUM_SENSORS];
        int valid_sensor_count = 0;

        // Read sensor values
        for (int i = 0; i < NUM_SENSORS; i++) {
            sensor_values[i] = read_mcp3008(i);
            if (sensor_values[i] != -1) {
                valid_sensor_count++;
            } else {
                sensor_values[i] = -1; // Mark as invalid
            }
        }

        // Calculate average moisture
        float average_moisture = average_soil_moisture(sensor_values);

        // Map to PWM duty cycle
        int valve_position = map_to_pwm(average_moisture);

        // Set PWM duty cycle
        gpioPWM(VALVE_GPIO, valve_position);

        // Log data
        log_data(sensor_values, average_moisture, valve_position);

        // Wait 5 seconds
        sleep(5);
    }

    // Shutdown sequence
    printf("Shutting down...\n");

    // Close valve
    gpioPWM(VALVE_GPIO, 0);

    // Close SPI
    spiClose(spi_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Irrigation system stopped.\n");

    return 0;
}

