#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define MAX_RETRIES 5
#define BACKOFF_BASE_MS 10

// Global variables
int spi_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_moisture_percentage(int adc_value);
void log_data(float moisture_percentage);
void signal_handler(int signal);
int spi_transfer(int spi_handle, char *tx_buf, char *rx_buf, int len);

// Structure for SPI transfer
typedef struct {
    int spi_handle;
    char tx_buf[3];
    char rx_buf[3];
    int len;
} spi_transfer_t;

// Function to perform SPI transfer with retry mechanism
int spi_transfer(int spi_handle, char *tx_buf, char *rx_buf, int len) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = spiXfer(spi_handle, tx_buf, rx_buf, len);
        if (result == len) {
            return 0; // Success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(BACKOFF_BASE_MS * (1 << retries)); // Exponential backoff
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct SPI command (start bit, single-ended, channel number)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        return -1; // Indicate error
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to moisture percentage
float convert_to_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate error
    }

    return (float)adc_value / 1023.0 * 100.0;
}

// Function to log data to file
void log_data(float moisture_percentage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %.2f\n", timestamp, moisture_percentage);
        fflush(log_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float moisture_percentage = convert_to_moisture_percentage(adc_value);
            if (moisture_percentage >= 0.0) {
                log_data(moisture_percentage);
                printf("Moisture: %.2f%%\n", moisture_percentage);
            } else {
                fprintf(stderr, "Error converting ADC value to moisture percentage.\n");
            }
        } else {
            fprintf(stderr, "Error reading from MCP3008.\n");
        }

        sleep(5);
    }

    // Cleanup
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

