// Helper function to get current timestamp
void get_timestamp(char *timestamp)
{
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, 20, "%Y-%m-%d %H:%M:%S", timeinfo);
}

// Function to read distance from HC-SR04 sensor
float read_distance(int trig_pin, int echo_pin) {
    struct timespec start, end;
    long long start_ns, end_ns, elapsed_ns;
    int ret;

    // Trigger the sensor
    set_gpio_value(trig_pin, 0);
    usleep(2);
    set_gpio_value(trig_pin, 1);
    usleep(10);
    set_gpio_value(trig_pin, 0);

    // Measure the echo pulse width
    while (get_gpio_value(echo_pin) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
    }

    while (get_gpio_value(echo_pin) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
    }

    start_ns = start.tv_sec * 1000000000LL + start.tv_nsec;
    end_ns = end.tv_sec * 1000000000LL + end.tv_nsec;
    elapsed_ns = end_ns - start_ns;

    // Calculate the distance
    float distance = (elapsed_ns / 1000000000.0) * 34300.0 / 2.0; // Speed of sound: 343 m/s

    return distance;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Apply calibration
    distance = distance_calibration[0][0] * distance + distance_calibration[0][1];

    // Clamp the distance
    if (distance < MIN_DISTANCE) {
        distance = MIN_DISTANCE;
    } else if (distance > MAX_DISTANCE) {
        distance = MAX_DISTANCE;
    }

    // Map distance to frequency
    float frequency = MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    return frequency;
}

// Function to read volume from MCP3008 ADC
float read_volume(int spi_channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    int adc_value;

    // MCP3008 command: start bit (1), single-ended mode (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (spi_channel << 4)); // Single-ended, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
        fprintf(stderr, "Error: SPI transfer failed for channel %d\n", spi_channel);
        return -1.0; // Indicate error
    }

    // Extract the ADC value (10 bits)
    adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    // Apply calibration
    float volume = volume_calibration[0] * adc_value + volume_calibration[1];

    // Clamp the volume
    if (volume < MIN_VOLUME) {
        volume = MIN_VOLUME;
    } else if (volume > MAX_VOLUME) {
        volume = MAX_VOLUME;
    }

    return volume;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", gpio_pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open duty_cycle file for GPIO %d\n", gpio_pin);
        return;
    }

    char buf[16];
    snprintf(buf, sizeof(buf), "%d", duty_cycle);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error: Could not write duty_cycle to GPIO %d\n", gpio_pin);
    }

    close(fd);
}

