// Function to get GPIO value
int get_gpio_value(int gpio_pin) {
    char path[64];
    int fd;
    char buf[2];

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio_pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error: Could not open value file for GPIO %d\n", gpio_pin);
        return -1; // Indicate error
    }

    if (read(fd, buf, 1) < 0) {
        fprintf(stderr, "Error: Could not read value from GPIO %d\n", gpio_pin);
        close(fd);
        return -1; // Indicate error
    }

    close(fd);
    return (buf[0] == '1') ? 1 : 0;
}

// Function to perform SPI transfer
int spi_transfer(int spi_fd, unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return 0;
}

// Function to load calibration data from file
void load_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file %s, using default values\n", filename);
        return;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        if (strncmp(line, "distance_calibration", 19) == 0) {
            if (sscanf(line, "distance_calibration[%d][%d] = %f", int *i, int *j, float *value) == 3) {
                distance_calibration[i][j] = value;
            }
        } else if (strncmp(line, "volume_calibration", 17) == 0) {
            if (sscanf(line, "volume_calibration[%d] = %f", int *i, float *value) == 2) {
                volume_calibration[i] = value;
            }
        }
    }

    fclose(fp);
}

// Function to save calibration data to file
void save_calibration_data(const char *filename) {
    FILE *fp = fopen(filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing\n", filename);
        return;
    }

    fprintf(fp, "# Theremin calibration data\n");
    fprintf(fp, "# Format: distance_calibration[sensor_index][0/1] = slope\n");
    fprintf(fp, "#        distance_calibration[sensor_index][1] = intercept\n");
    fprintf(fp, "#        volume_calibration[0] = slope\n");
    fprintf(fp, "#        volume_calibration[1] = intercept\n");

    for (int i = 0; i < NUM_SENSORS; i++) {
        fprintf(fp, "distance_calibration[%d][0] = %f\n", i, distance_calibration[i][0]);
        fprintf(fp, "distance_calibration[%d][1] = %f\n", i, distance_calibration[i][1]);
    }
    fprintf(fp, "volume_calibration[0] = %f\n", volume_calibration[0]);
    fprintf(fp, "volume_calibration[1] = %f\n", volume_calibration[1]);

    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    running = 0;
    printf("Exiting...\n");
}

int main() {
    int i;
    float distance, frequency, volume;
    int duty_cycle;
    char timestamp[20];
    FILE *log_file;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Load calibration data
    load_calibration_data(CONFIG_FILE);

    // Initialize GPIO
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip\n");
        return 1;
    }

    for (i = 0; i < NUM_SENSORS; i++) {
        trig_lines[i] = gpiod_chip_get_line(gpio_chip, sensor_pins[i]);
        if (!trig_lines[i]) {
            fprintf(stderr, "Error: Could not get line for trig pin %d\n", sensor_pins[i]);
            goto cleanup_gpio;
        }

        echo_lines[i] = gpiod_chip_get_line(gpio_chip, sensor_pins[i] + 1);
        if (!echo_lines[i]) {
            fprintf(stderr, "Error: Could not get line for echo pin %d\n", sensor_pins[i] + 1);
            goto cleanup_gpio;
        }

        if (gpiod_line_request_output(trig_lines[i], "theremin", 0) < 0) {
            fprintf(stderr, "Error: Could not request trig pin %d as output\n", sensor_pins[i]);
            goto cleanup_gpio;
        }

        if (gpiod_line_request_input(echo_lines[i]) < 0) {
            fprintf(stderr, "Error: Could not request echo pin %d as input\n", sensor_pins[i] + 1);
            goto cleanup_gpio;
        }
    }

    // Initialize PWM
    export_pwm(PWM_PIN);
    set_pwm_period(PWM_PIN, PWM_PERIOD);
    set_pwm_enable(PWM_PIN, 1);

    // Initialize SPI
    char spi_device[20];
    snprintf(spi_device, sizeof(spi_device), "/dev/spidev%d.%d", SPI_BUS, SPI_DEVICE);
    spi_fd = open(spi_device, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device %s\n", spi_device);
        goto cleanup_pwm;
    }

    // Main loop
    while (running) {
        // Read sensor data
        float total_distance = 0.0;
        for (i = 0; i < NUM_SENSORS; i++) {
            distance = read_distance(sensor_pins[i], sensor_pins[i] + 1);
            if (distance < 0) {
                fprintf(stderr, "Error: Could not read distance from sensor %d\n", i);
                continue; // Skip to the next sensor
            }
            total_distance += distance;
        }

        // Calculate average distance
        if (i > 0) {
            distance = total_distance / i;
        } else {
            distance = 0.0; // Avoid division by zero
        }

        // Map distance to frequency
        frequency = map_distance_to_frequency(distance);

        // Read volume
        volume = read_volume(0); // Read from channel 0
        if (volume < 0) {
            fprintf(stderr, "Error: Could not read volume\n");
            volume = 0.0; // Use a default volume
        }

        // Calculate duty cycle
        duty_cycle = (int)(volume * PWM_PERIOD / 100.0);

        // Set PWM duty cycle
        set_pwm_duty_cycle(PWM_PIN, duty_cycle);

        // Log data
        get_timestamp(timestamp);
        log_file = fopen("theremin_log.txt", "a");
        if (log_file) {
            fprintf(log_file, "%s, Distance: %.2f cm, Frequency: %.2f Hz, Volume: %.2f, Duty Cycle: %d\n",
                    timestamp, distance, frequency, volume, duty_cycle);
            fclose(log_file);
        } else {
            fprintf(stderr, "Error: Could not open log file\n");
        }

        usleep(50000); // 50 ms delay
    }

    // Cleanup
cleanup_pwm:
    set_pwm_enable(PWM_PIN, 0);
    unexport_pwm(PWM_PIN);

cleanup_gpio:
    for (i = 0; i < NUM_SENSORS; i++) {
        if (trig_lines[i]) {
            gpiod_line_release(trig_lines[i]);
        }
        if (echo_lines[i]) {
            gpiod_line_release(echo_lines[i]);
        }
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    if (spi_fd >= 0) {
        close(spi_fd);
    }

    return 0;
}

