    return ((float)adc_value / 1023.0) * 500.0;
}

// Function to control the ventilation fan
void control_fan(float aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
        printf("AQI: %.2f - Fan ON\n", aqi);
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
        printf("AQI: %.2f - Fan OFF\n", aqi);
    }
}

// Function to log data to file
void log_data(float aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (aqi >= 0) {
        fprintf(log_file, "%s, %.2f\n", timestamp, aqi);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(log_file, "%s, ERROR: SPI read failed\n", timestamp);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Function to re-initialize SPI
int spi_reinit() {
    spiClose(spi_handle);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI re-initialization failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for fan control
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            // Calculate AQI
            float aqi = calculate_aqi(adc_value);

            // Control fan
            control_fan(aqi);

            // Log data
            log_data(aqi);
        } else {
            // Log error if ADC read failed
            log_data(-1.0);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

