#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "alcohol_log.txt"
#define SENSOR_ABSENT_THRESHOLD 2
#define SENSOR_ABSENT_READINGS 5

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_read_adc(int channel);
float adc_to_ppm(int adc_value);
const char *classify_reading(float ppm_value);
int log_data(int adc_value, float ppm_value, const char *classification);
int gpio_init(void);
void signal_handler(int sig);
void cleanup(void);

// SPI Initialization
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, SPI_MODE);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MODE, &ret);
    if (ret == -1) {
        perror("Error getting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, SPI_BITS_PER_WORD);
    if (ret == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_BITS_PER_WORD, &ret);
    if (ret == -1) {
        perror("Error getting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, SPI_SPEED);
    if (ret == -1) {
        perror("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    ret = ioctl(spi_fd, SPI_IOC_RD_MAX_SPEED_HZ, &ret);
    if (ret == -1) {
        perror("Error getting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    unsigned char tx[3];
    unsigned char rx[3];
    struct spi_ioc_transfer tr;
    int ret, i;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = SPI_SPEED;
    tr.bits_per_word = SPI_BITS_PER_WORD;

    for (i = 0; i < 3; i++) {
        ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret < 0) {
            perror("Error sending SPI message");
            return -1;
        }
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];

    return adc_value;
}

// ADC Value to PPM Conversion
float adc_to_ppm(int adc_value) {
    return (adc_value * 0.5) - 10.0;
}

// PPM Classification
const char *classify_reading(float ppm_value) {
    if (ppm_value > 50.0) {
        return "Alcohol detected! Limit exceeded.";
    } else if (ppm_value < 20.0) {
        return "Sobriety confirmed.";
    } else {
        return "Alcohol level within acceptable range.";
    }
}

// Log Data
int log_data(int adc_value, float ppm_value, const char *classification) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, ADC: %d, PPM: %.2f, Classification: %s\n", timestamp, adc_value, ppm_value, classification);
    fflush(log_file);

    return 0;
}

// GPIO Initialization
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "alcohol_sensor", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int adc_value, i;
    float ppm_value;
    const char *classification;
    int sensor_absent_count = 0;
    int last_adc_value = -1;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    fprintf(stdout, "Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        adc_value = spi_read_adc(MCP3008_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "SPI read failed, retrying...\n");
            log_data(-1, -1.0, "SPI read error");
            sleep(1); // Wait before retrying
            continue;
        }

        // Sensor absense detection
        if (adc_value == 0 || adc_value == 1023) {
            sensor_absent_count++;
            if (sensor_absent_count >= SENSOR_ABSENT_READINGS) {
                fprintf(stderr, "Sensor appears to be absent or disconnected.\n");
                log_data(-1, -1.0, "Sensor absent");
                sensor_absent_count = 0; // Reset counter after logging
            }
        } else {
            sensor_absent_count = 0; // Reset counter if reading is valid
        }

        // Check for consecutive readings of the same value
        if (last_adc_value != -1 && adc_value == last_adc_value) {
            fprintf(stderr, "Consecutive identical ADC readings detected.\n");
            log_data(-1, -1.0, "Consecutive identical readings");
        }
        last_adc_value = adc_value;

        ppm_value = adc_to_ppm(adc_value);
        classification = classify_reading(ppm_value);

        log_data(adc_value, ppm_value, classification);

        printf("ADC: %d, PPM: %.2f, Classification: %s\n", adc_value, ppm_value, classification);

        sleep(1);
    }

    cleanup();
    fprintf(stdout, "Alcohol sensor monitoring stopped.\n");

    return 0;
}

