#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor 1
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23

// Motor 2
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25

// MCP3008 SPI
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// MCP3008 Channels
#define POT1_CHANNEL 0
#define POT2_CHANNEL 1

// PWM Range
#define PWM_RANGE 255

// Speed Factors
#define MIN_SPEED 50
#define MAX_SPEED 255

// Global variables for graceful shutdown
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float map_speed(int adc_value);
void set_motor_speed(int motor_num, int speed);
void set_motor_direction(int motor_num, int direction);
void move_forward();
void move_backward();
void stop_motors();
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to map ADC value to speed factor using logarithmic function
float map_speed(int adc_value) {
    // Clamp ADC value to 0-1023 range
    adc_value = (adc_value < 0) ? 0 : adc_value;
    adc_value = (adc_value > 1023) ? 1023 : adc_value;

    // Map ADC value to logarithmic speed range (MIN_SPEED to MAX_SPEED)
    float speed_factor = MIN_SPEED + (MAX_SPEED - MIN_SPEED) * log10(adc_value + 1) / log10(1024);
    return speed_factor;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_num, int speed) {
    int gpio_enable, gpio_direction;

    if (motor_num == 1) {
        gpio_enable = MOTOR1_ENABLE;
        gpio_direction = MOTOR1_DIRECTION;
    } else if (motor_num == 2) {
        gpio_enable = MOTOR2_ENABLE;
        gpio_direction = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    // Set direction first
    gpioWrite(gpio_direction, (speed > 0) ? 1 : 0); // 1 for forward, 0 for backward

    // Enable motor
    gpioWrite(gpio_enable, 1); // Enable motor

    // Set PWM duty cycle
    gpioPWM(gpio_enable, abs(speed)); // Use absolute value for PWM
}

// Function to set motor direction
void set_motor_direction(int motor_num, int direction) {
    int gpio_direction;

    if (motor_num == 1) {
        gpio_direction = MOTOR1_DIRECTION;
    } else if (motor_num == 2) {
        gpio_direction = MOTOR2_DIRECTION;
    } else {
        fprintf(stderr, "Error: Invalid motor number: %d\n", motor_num);
        return;
    }

    gpioWrite(gpio_direction, direction); // 1 for forward, 0 for backward
}

// Function to move forward
void move_forward() {
    set_motor_direction(1, 1);
    set_motor_direction(2, 0);
}

// Function to move backward
void move_backward() {
    set_motor_direction(1, 0);
    set_motor_direction(2, 1);
}

// Function to stop motors
void stop_motors() {
    set_motor_speed(1, 0);
    set_motor_speed(2, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM range
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(POT1_CHANNEL);
        int pot2_value = read_mcp3008(POT2_CHANNEL);

        if (pot1_value == -1 || pot2_value == -1) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            // Attempt to recover, or exit if persistent errors
            continue; // Or break if recovery is not possible
        }

        // Map speed factors
        float speed1 = map_speed(pot1_value);
        float speed2 = map_speed(pot2_value);

        // Move forward
        set_motor_speed(1, (int)speed1);
        set_motor_speed(2, (int)speed2);
        gpioDelay(2000); // 2 seconds

        // Stop motors
        stop_motors();
        gpioDelay(2000); // 2 seconds

        // Move backward
        set_motor_speed(1, (int)speed1);
        set_motor_speed(2, (int)speed2);
        gpioDelay(2000); // 2 seconds

        // Stop motors
        stop_motors();
        gpioDelay(5000); // 5 seconds
    }

    // Stop motors
    stop_motors();

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

