#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LED_PIN 17
#define SPI_CE 0 // Chip Enable 0 (GPIO8)

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define sampling parameters
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD (1000000 / SAMPLE_RATE) // microseconds

// Define noise threshold
#define NOISE_THRESHOLD 1.1

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int read_mcp3008(int channel);
float calibrate_noise_level();
void trigger_led(int state);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int led_pin;
    int spi_ce;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int sample_rate;
    float noise_threshold;
} Config;

Config config = {
    .led_pin = LED_PIN,
    .spi_ce = SPI_CE,
    .spi_channel = SPI_CHANNEL,
    .spi_speed = SPI_SPEED,
    .spi_mode = SPI_MODE,
    .sample_rate = SAMPLE_RATE,
    .noise_threshold = NOISE_THRESHOLD
};

int main() {
    float ambient_noise_level;
    int sound_level;
    int led_state = 0; // 0 = off, 1 = on
    unsigned long last_led_change = 0;

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    // Calibrate noise level
    ambient_noise_level = calibrate_noise_level();
    printf("Ambient noise level: %.2f\n", ambient_noise_level);

    // Main loop
    while (!terminate) {
        // Read sound level
        sound_level = read_mcp3008(0);

        // Check if sound level exceeds threshold
        if (sound_level > (int)(ambient_noise_level * config.noise_threshold)) {
            // Debounce LED
            if (gpioTick() - last_led_change > 10000) { // 10 ms debounce
                trigger_led(1);
                led_state = 1;
                last_led_change = gpioTick();
            }
        } else {
            // Turn off LED if it was on
            if (led_state == 1) {
                trigger_led(0);
                led_state = 0;
            }
        }

        // Delay for sample period
        gpioDelay(SAMPLE_PERIOD);
    }

    // Cleanup
    trigger_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio and SPI
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(config.led_pin, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, config.spi_mode);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel\n");
        return -1;
    }

    unsigned char spi_data[3];
    spi_data[0] = 0x01; // Start bit
    spi_data[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_data[2] = 0x00;

    char rx_buffer[3];

    if (spiXfer(spi_handle, spi_data, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Calibrate noise level
float calibrate_noise_level() {
    double sum = 0.0;
    int num_samples = 500; // 5 seconds at 100 Hz

    printf("Calibrating noise level...\n");
    for (int i = 0; i < num_samples; i++) {
        int sound_level = read_mcp3008(0);
        if (sound_level < 0) {
            fprintf(stderr, "Error reading sound level during calibration\n");
            return 0.0; // Return a default value
        }
        sum += sound_level;
        gpioDelay(SAMPLE_PERIOD); // Delay for sample period
    }

    return (float)(sum / num_samples);
}

// Trigger LED
void trigger_led(int state) {
    gpioWrite(config.led_pin, state);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

