#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define MCP3008 channel assignments
#define ADXL335_X_CHANNEL 0
#define ADXL335_Y_CHANNEL 1
#define ADXL335_Z_CHANNEL 2

// Define ADXL335 parameters
#define ADXL335_SENSITIVITY 0.300 // mV/g
#define ADXL335_ZERO_G_BIAS 1.5   // V

// Define Kalman filter parameters
#define PROCESS_NOISE 0.01
#define MEASUREMENT_NOISE 0.1

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Kalman filter state
float x_acceleration = 0.0;
float y_acceleration = 0.0;
float z_acceleration = 0.0;

float x_state_estimate = 0.0;
float y_state_estimate = 0.0;
float z_state_estimate = 0.0;

float x_error_covariance = 1.0;
float y_error_covariance = 1.0;
float z_error_covariance = 1.0;

// Function prototypes
int read_adc_channel(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_acceleration(float voltage);
void kalman_filter(float *acceleration, float *state_estimate, float *error_covariance, float measurement);
void signal_handler(int signal);

// Function to read ADC value from MCP3008
int read_adc_channel(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return (float)adc_value * (3.3 / 1024.0);
}

// Function to convert voltage to acceleration (g)
float voltage_to_acceleration(float voltage) {
    return (voltage - ADXL335_ZERO_G_BIAS) / (ADXL335_SENSITIVITY / 1000.0);
}

// Kalman filter implementation
void kalman_filter(float *acceleration, float *state_estimate, float *error_covariance, float measurement) {
    // Prediction step
    float predicted_state = *state_estimate;
    float predicted_error_covariance = *error_covariance + PROCESS_NOISE;

    // Update step
    float kalman_gain = predicted_error_covariance / (predicted_error_covariance + MEASUREMENT_NOISE);
    *state_estimate = predicted_state + kalman_gain * (measurement - predicted_state);
    *error_covariance = (1 - kalman_gain) * predicted_error_covariance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Read ADC values
        int x_adc = read_adc_channel(ADXL335_X_CHANNEL);
        int y_adc = read_adc_channel(ADXL335_Y_CHANNEL);
        int z_adc = read_adc_channel(ADXL335_Z_CHANNEL);

        if (x_adc == -1 || y_adc == -1 || z_adc == -1) {
            fprintf(stderr, "Error: Failed to read ADC values, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert ADC values to voltages
        float x_voltage = adc_to_voltage(x_adc);
        float y_voltage = adc_to_voltage(y_adc);
        float z_voltage = adc_to_voltage(z_adc);

        // Convert voltages to acceleration values
        float x_acceleration_raw = voltage_to_acceleration(x_voltage);
        float y_acceleration_raw = voltage_to_acceleration(y_voltage);
        float z_acceleration_raw = voltage_to_acceleration(z_voltage);

        // Apply Kalman filter
        kalman_filter(&x_acceleration_raw, &x_state_estimate, &x_error_covariance, x_acceleration_raw);
        kalman_filter(&y_acceleration_raw, &y_state_estimate, &y_error_covariance, y_acceleration_raw);
        kalman_filter(&z_acceleration_raw, &z_state_estimate, &z_error_covariance, z_acceleration_raw);

        // Print filtered acceleration values
        printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", x_state_estimate, y_state_estimate, z_state_estimate);

        // Delay for 100 ms
        gpioDelay(100);
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

