#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17
#define SENSOR3_PIN 27

// Define the number of sensors
#define NUM_SENSORS 3

// Define the number of readings to average
#define NUM_READINGS 10

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL_MS 100

// Define the voltage quiescent (1.65V)
#define V_QUIESCENT 1.65

// Define the sensitivity (0.025 V/mT = 25 mV/mT)
#define SENSITIVITY 0.025

// Define the voltage range (0.0V to 3.3V)
#define V_MIN 0.0
#define V_MAX 3.3

// Define the magnetic field range (-100 mT to +100 mT)
#define MAG_MIN -100.0
#define MAG_MAX 100.0

// Global variables
static struct gpiod_chip *chip;
static struct gpiod_line *lines[NUM_SENSORS];
static FILE *log_file;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(struct gpiod_line *line);
double calculate_magnetic_field(int sensor_value);
void log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT);
void signal_handler(int sig);
int setup_gpio();
void cleanup_gpio();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT) {
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully.\n");
        terminate = 1;
    }
}

// Function to read the sensor value from a GPIO line
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(errno));
        return -1; // Indicate an error
    }
    return value;
}

// Function to calculate the magnetic field strength in millitesla
double calculate_magnetic_field(int sensor_value) {
    // Convert the sensor value (0 or 1) to a voltage
    double voltage = (double)sensor_value * V_MAX;

    // Calculate the magnetic field strength
    double magnetic_field = (voltage - V_QUIESCENT) / SENSITIVITY;

    return magnetic_field;
}

// Function to log the sensor data to a file
void log_data(double sensor1_mT, double sensor2_mT, double sensor3_mT) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, sensor1_mT, sensor2_mT, sensor3_mT);
    fflush(log_file); // Flush the buffer to ensure data is written to the file
}

// Function to set up the GPIO lines
int setup_gpio() {
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    int pins[NUM_SENSORS] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN};
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting GPIO line %d: %s\n", pins[i], strerror(errno));
            return -1;
        }

        struct gpiod_line_request_config config;
        memset(&config, 0, sizeof(config));
        config.consumer = "magnetic_sensor";
        config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

        int ret = gpiod_line_request(lines[i], &config, 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting GPIO line %d: %s\n", pins[i], strerror(errno));
            return -1;
        }
    }

    return 0;
}

// Function to clean up the GPIO lines
void cleanup_gpio() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handler for Ctrl+C
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        exit(EXIT_FAILURE);
    }

    // Open the log file
    log_file = fopen("magnetic_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Set up GPIO lines
    if (setup_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!terminate) {
        double sensor1_mT = 0.0, sensor2_mT = 0.0, sensor3_mT = 0.0;
        double sum1 = 0.0, sum2 = 0.0, sum3 = 0.0;

        // Read sensor values and calculate magnetic field strength
        for (int i = 0; i < NUM_READINGS; i++) {
            int sensor1_value = read_sensor(lines[0]);
            int sensor2_value = read_sensor(lines[1]);
            int sensor3_value = read_sensor(lines[2]);

            if (sensor1_value == -1 || sensor2_value == -1 || sensor3_value == -1) {
                fprintf(stderr, "Error reading sensor, skipping iteration.\n");
                continue; // Skip to the next iteration if there's an error
            }

            sum1 += calculate_magnetic_field(sensor1_value);
            sum2 += calculate_magnetic_field(sensor2_value);
            sum3 += calculate_magnetic_field(sensor3_value);

            usleep(SAMPLING_INTERVAL_MS * 1000); // Sleep for the sampling interval
        }

        // Calculate the average magnetic field strength
        sensor1_mT = sum1 / NUM_READINGS;
        sensor2_mT = sum2 / NUM_READINGS;
        sensor3_mT = sum3 / NUM_READINGS;

        // Log the data
        log_data(sensor1_mT, sensor2_mT, sensor3_mT);

        // Check for out-of-range values
        if (sensor1_mT < MAG_MIN || sensor1_mT > MAG_MAX ||
            sensor2_mT < MAG_MIN || sensor2_mT > MAG_MAX ||
            sensor3_mT < MAG_MIN || sensor3_mT > MAG_MAX) {
            fprintf(stderr, "Warning: Out-of-range magnetic field value detected.\n");
        }

        usleep(SAMPLING_INTERVAL_MS * 1000); // Sleep for the sampling interval
    }

    // Clean up GPIO lines and close the log file
    cleanup_gpio();
    fclose(log_file);

    return EXIT_SUCCESS;
}

