#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int spi_init(void);
int read_adc_channel(int channel);
void log_data(int channel, int adc_value);
void signal_handler(int sig);

// Structure to hold SPI configuration
typedef struct {
    char *device;
    uint8_t mode;
    uint8_t bits_per_word;
    uint32_t speed;
} spi_config_t;

// Function to initialize SPI
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read ADC channel
int read_adc_channel(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer transfer[1];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80 | (channel << 4); // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 3;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) | rx_buf[2];
    return adc_value;
}

// Function to log data to CSV file
void log_data(int channel, int adc_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s,%d,%d\n", timestamp, channel, adc_value);
    fflush(csv_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    stop_flag = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", sig);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (spi_init() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen("sensor_data.csv", "a");
    if (csv_file == NULL) {
        perror("Error opening CSV file");
        close(spi_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Channel,ADC_Value\n");
    }

    // Main loop
    while (!stop_flag) {
        // Read ADC channels
        int adc_value_0 = read_adc_channel(0);
        int adc_value_1 = read_adc_channel(1);
        int adc_value_2 = read_adc_channel(2);

        if (adc_value_0 != -1 && adc_value_1 != -1 && adc_value_2 != -1) {
            // Log data
            log_data(0, adc_value_0);
            log_data(1, adc_value_1);
            log_data(2, adc_value_2);
        } else {
            fprintf(stderr, "Error reading ADC values. Skipping logging.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Close SPI device and CSV file
    close(spi_fd);
    fclose(csv_file);

    return 0;
}

