#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>
#include <cjson/cJSON.h>

#define MQTT_BROKER "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17

// Global variables for MQTT and pigpio
struct mosquitto *mosq = NULL;

// Function prototypes
int mqtt_connect(struct mosquitto **mosq);
int mqtt_subscribe(struct mosquitto *mosq);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
int parse_json_payload(const char *payload, bool *led_state);
int set_led_state(bool state);
void signal_handler(int signum);
void log_error(const char *message);

// Signal handler function
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, cleaning up...\n", signum);
        if (mosq) {
            mosquitto_disconnect(mosq);
            mosquitto_destroy(mosq);
        }
        mosquitto_lib_cleanup();
        gpioTerminate();
        exit(0);
    }
}

// MQTT connect function with exponential backoff
int mqtt_connect(struct mosquitto **mosq) {
    int rc = 0;
    int reconnect_delay = 1; // Initial delay in seconds

    while (rc == 0) {
        rc = mosquitto_connect(*mosq, MQTT_BROKER, MQTT_PORT, 60); // Keepalive = 60 seconds
        if (rc != MOSQ_ERR_SUCCESS) {
            log_error("MQTT connection failed, retrying...");
            sleep(reconnect_delay);
            reconnect_delay *= 2; // Exponential backoff
            if (reconnect_delay > 60) {
                reconnect_delay = 60; // Max delay of 60 seconds
            }
        }
    }

    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT connection failed after multiple retries.");
        return -1;
    }

    return 0;
}

// MQTT subscribe function
int mqtt_subscribe(struct mosquitto *mosq) {
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_error("MQTT subscribe failed");
        return -1;
    }
    return 0;
}

// MQTT message callback function
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen) {
        bool led_state;
        if (parse_json_payload(message->payload, &led_state)) {
            if (set_led_state(led_state) != 0) {
                log_error("Failed to set LED state");
            }
        } else {
            log_error("Failed to parse JSON payload");
        }
    } else {
        log_error("Empty MQTT message received");
    }
}

// JSON parsing function
int parse_json_payload(const char *payload, bool *led_state) {
    cJSON *json = cJSON_Parse(payload);
    if (json == NULL) {
        const char *error_ptr = cJSON_GetErrorPtr();
        if (error_ptr != NULL) {
            fprintf(stderr, "%s\n", error_ptr);
        }
        return -1;
    }

    cJSON *led_state_json = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (cJSON_IsBool(led_state_json)) {
        *led_state = led_state_json->valueint;
        cJSON_Delete(json);
        return 0;
    } else {
        cJSON_Delete(json);
        return -1;
    }
}

// LED control function
int set_led_state(bool state) {
    gpioWrite(GPIO_PIN, state ? 1 : 0);
    return 0;
}

// Error logging function
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Turn off the LED on startup
    gpioWrite(GPIO_PIN, 0);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_error("MQTT client creation failed");
        gpioTerminate();
        return 1;
    }

    // Set MQTT callbacks
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    // Connect to MQTT broker with exponential backoff
    if (mqtt_connect(&mosq) != 0) {
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Subscribe to the MQTT topic
    if (mqtt_subscribe(mosq) != 0) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        return 1;
    }

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Keep the program running until a signal is received
    while (1) {
        sleep(1); // Sleep to reduce CPU usage
    }

    // The following lines will never be reached due to the infinite loop
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();

    return 0;
}

