#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C and SIGTERM
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    int sound_level = gpioRead(SOUND_SENSOR_PIN);
    return sound_level;
}

// Function to control the alarm LED
void control_alarm_led(int sound_detected) {
    if (sound_detected == 0) { // Sound detected (LOW signal)
        gpioWrite(ALARM_LED_PIN, 1); // Turn LED ON
        gpioDelay(1000); // Wait for 1 second
        gpioWrite(ALARM_LED_PIN, 0); // Turn LED OFF
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();
        printf("Sound Level: %d\n", sound_level);
        control_alarm_led(sound_level);
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is OFF
    gpioTerminate(); // Terminate pigpio
    printf("Program terminated gracefully.\n");
    return 0;
}

