#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define LOG_FILE "/var/log/vibration_shutdown.log"

static volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp()
{
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log a message to the log file
int log_message(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open log file");
        return -1;
    }

    char *timestamp = get_timestamp();
    if (timestamp == NULL) {
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s: %s\n", timestamp, message);
    free(timestamp);

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

// Function to shut down the system
void shutdown_system()
{
    printf("Vibration detected! Shutting down...\n");
    if (log_message("Vibration detected! Shutting down...") != 0) {
        fprintf(stderr, "Failed to log shutdown message.\n");
    }
    system("sudo shutdown -h now");
}

int main()
{
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_event event;
    int ret;

    // Register signal handlers
    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO line for input with falling edge event detection
    ret = gpiod_line_request_rising_edge_events(line, "vibration-monitor");
    if (ret < 0) {
        perror("Failed to request GPIO line for rising edge events");
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    printf("Vibration monitor started. Monitoring GPIO%d on %s...\n", GPIO_PIN, GPIO_CHIP);

    // Main loop
    while (!terminate) {
        ret = gpiod_line_event_wait(line, NULL);
        if (ret < 0) {
            perror("Failed to wait for GPIO line event");
            break;
        }

        ret = gpiod_line_event_read(line, &event);
        if (ret < 0) {
            perror("Failed to read GPIO line event");
            break;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING) {
            shutdown_system();
            break; // Exit the loop after shutdown is initiated
        }
    }

    // Clean up
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Vibration monitor stopped.\n");

    return 0;
}

