#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define LM35_SCALE 0.01 // 10 mV/°C
#define VREF 3.3
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_celsius(int adc_value);
void log_temperature(float temperature);
void write_to_file(float temperature);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode + channel number
    tx[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx, rx, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1; // Indicate error
    }

    // Extract ADC value
    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float convert_to_celsius(int adc_value) {
    float voltage = (adc_value / 1023.0) * VREF;
    float temperature = voltage / LM35_SCALE;
    return temperature;
}

// Function to log temperature to console
void log_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Function to write temperature to file
void write_to_file(float temperature) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file %s\n", LOG_FILE);
        return;
    }

    // Write temperature to file
    fwrite(&temperature, sizeof(float), 1, fp);

    // Write the rest of the buffer to the file
    fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // SPI channel 0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            // Error reading ADC, skip this iteration
            gpioDelay(5000); // Wait 5 seconds
            continue;
        }

        // Convert ADC value to Celsius
        float temperature = convert_to_celsius(adc_value);

        // Log temperature
        log_temperature(temperature);

        // Store temperature in circular buffer
        temperature_buffer[buffer_index] = temperature;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Write temperature to file every 5 seconds
        if (buffer_index == 0) {
            write_to_file(temperature);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    return 0;
}

