        buffer_index = (buffer_index + 1) % BUFFER_SIZE;

        // Write temperature to file every 5 seconds
        if (buffer_index == 0) {
            write_to_file(temperature);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    return 0;
}

