#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define MCP4725_ADDR 0x62
#define MCP4725_VREF 3.3 // V
#define TEMP_MIN 0.0      // C
#define TEMP_MAX 50.0     // C
#define ADC_MIN 0
#define ADC_MAX 1023
#define LOG_FILE "temperature_log.txt"

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_celsius(int adc_value);
int dac_set_voltage(int handle, float voltage);
int log_data(FILE *fp, int adc_value, float temperature, float voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to Celsius
float adc_to_celsius(int adc_value) {
    float temperature = (float)(adc_value - ADC_MIN) * (TEMP_MAX - TEMP_MIN) / (ADC_MAX - ADC_MIN) + TEMP_MIN;
    return temperature;
}

// Function to set DAC voltage
int dac_set_voltage(int handle, float voltage) {
    if (voltage < 0.0 || voltage > MCP4725_VREF) {
        fprintf(stderr, "Error: Invalid DAC voltage: %.2f V\n", voltage);
        return -1;
    }

    // Convert voltage to 12-bit DAC value
    int dac_value = (int)((voltage / MCP4725_VREF) * 4095.0);

    // Construct I2C message
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write DAC value command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // Upper 8 bits
    tx_buffer[2] = (dac_value << 4) & 0xF0; // Lower 4 bits

    // Write to I2C device
    int result = i2cWriteDevice(handle, tx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(FILE *fp, int adc_value, float temperature, float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);
    fflush(fp); // Ensure data is written to file immediately

    printf("%s, %d, %.2f, %.2f\n", timestamp, adc_value, temperature, voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

