#define MCP4725_VREF 3.3 // V
#define TEMP_MIN 0.0      // C
#define TEMP_MAX 50.0     // C
#define ADC_MIN 0
#define ADC_MAX 1023
#define LOG_FILE "temperature_log.txt"

// Global variables
