float convert_to_moisture(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate an error
    }
    return (1.0 - (adc_value / 1023.0)) * 100.0;
}

