            moisture_levels[0], moisture_levels[1], moisture_levels[2]);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    terminate = 1;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Goodbye!\n");
}

int main() {
    if (initialize() != 0) {
        return 1;
    }

    SensorData sensor_data;

    while (!terminate) {
        // Read sensor data
        for (int i = 0; i < NUM_SENSORS; i++) {
            int adc_value = read_mcp3008(i);
            if (adc_value >= 0) {
                sensor_data.moisture_levels[i] = convert_to_moisture(adc_value);
            } else {
                sensor_data.moisture_levels[i] = -1.0; // Indicate error
            }
        }

        // Log data
        log_data(sensor_data.moisture_levels);

        // Sleep for 60 seconds
        gpioDelay(60000); // pigpioDelay takes milliseconds
    }

    cleanup();
    return 0;
}

