#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Define the number of relays
#define NUM_RELAYS 4

// Define the delay between relay activations (in seconds)
#define DELAY_SECONDS 1

// Global variable to store the GPIO chip
struct gpiod_chip *chip;

// Function prototypes
int initialize_gpio(void);
int set_relay_state(int pin, int state);
int cleanup_gpio(void);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Function to initialize the GPIO pins
int initialize_gpio(void) {
    int i;
    struct gpiod_line *line;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines for the relay pins
    int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    for (i = 0; i < NUM_RELAYS; i++) {
        line = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!line) {
            perror("Error getting GPIO line");
            cleanup_gpio();
            return -1;
        }

        // Request the GPIO line for output
        if (gpiod_line_request_output(line, "relay_sequencer", 0) < 0) {
            perror("Error requesting GPIO line for output");
            cleanup_gpio();
            return -1;
        }
    }

    return 0;
}

// Function to set the state of a relay (active or inactive)
int set_relay_state(int pin, int state) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        perror("Error getting GPIO line");
        return -1;
    }

    // Set the GPIO line value to the desired state
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Function to clean up the GPIO pins and close the chip
int cleanup_gpio(void) {
    int i;
    struct gpiod_line *line;

    // Get the GPIO lines for the relay pins
    int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    for (i = 0; i < NUM_RELAYS; i++) {
        line = gpiod_chip_get_line(chip, relay_pins[i]);
        if (line) {
            gpiod_line_release(line);
        }
    }

    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

int main(void) {
    int i;
    int relay_pins[NUM_RELAYS] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pins
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Main loop to sequence the relays
    while (1) {
        for (i = 0; i < NUM_RELAYS; i++) {
            // Activate the relay
            if (set_relay_state(relay_pins[i], 1) < 0) {
                fprintf(stderr, "Failed to activate relay %d. Exiting.\n", relay_pins[i]);
                cleanup_gpio();
                return 1;
            }

            // Wait for the specified delay
            sleep(DELAY_SECONDS);

            // Deactivate the relay
            if (set_relay_state(relay_pins[i], 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay %d. Exiting.\n", relay_pins[i]);
                cleanup_gpio();
                return 1;
            }
        }
    }

    return 0;
}

