#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 16
#define SOUND_THRESHOLD 500
#define DEBOUNCE_DELAY 1000 // 1 second
#define LED_ON_TIME 500     // 500 ms

// Global variables
int spi_handle;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
int is_sound_detected(int adc_value, int threshold);
void control_led(int gpio_pin, int state);
void log_event(const char *filename);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1; // Indicate an error
    }

    char spi_tx_buf[3];
    char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;          // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1; // Indicate an error
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to check if sound is detected
int is_sound_detected(int adc_value, int threshold) {
    return (adc_value > threshold) ? 1 : 0;
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

// Function to log the event
void log_event(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", filename);
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Sound detected\n", timestamp);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        if (is_sound_detected(adc_value, SOUND_THRESHOLD)) {
            printf("Sound detected! ADC value: %d\n", adc_value);
            control_led(LED_GPIO, 1); // Turn LED on
            log_event("sound_events.log");
            gpioDelay(LED_ON_TIME * 1000); // Keep LED on for 500 ms
            control_led(LED_GPIO, 0); // Turn LED off

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Wait for 1 second
        }

        gpioDelay(10000); // Check every 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

