#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins
#define MOTOR_IN1 17
#define MOTOR_IN2 18
#define MOTOR_ENA 27

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define rain threshold
#define RAIN_THRESHOLD 5

// Define motor speed
#define MOTOR_SPEED 150

// Define log file name
#define LOG_FILE "rain_log.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int convert_adc_to_rain_level(int adc_value);
void control_motor(int direction, int speed);
void log_rain_data(int rain_level);
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    // Construct SPI message
    tx[0] = 0x01; // Start bit
    tx[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel selection
    tx[2] = 0x00; // Don't care

    // Transfer data
    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Parse ADC value from response
    int adc_value = ((rx[1] & 0x03) << 8) + rx[2];

    return adc_value;
}

// Function to convert ADC value to rain level (0-10)
int convert_adc_to_rain_level(int adc_value) {
    // Map ADC value (0-1023) to rain level (0-10)
    // Assuming ADC 1023 maps to rain level 0 (dry) and ADC 0 maps to rain level 10 (heaviest rain)
    return 10 - (int)(((float)adc_value / 1023.0) * 10.0);
}

// Function to control the motor
void control_motor(int direction, int speed) {
    if (direction == 1) { // Forward
        gpioWrite(MOTOR_IN1, 1);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, speed);
    } else if (direction == -1) { // Reverse
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 1);
        gpioPWM(MOTOR_ENA, speed);
    } else { // Stop
        gpioWrite(MOTOR_IN1, 0);
        gpioWrite(MOTOR_IN2, 0);
        gpioPWM(MOTOR_ENA, 0);
    }
}

// Function to log rain data to file
void log_rain_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Rain Level: %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_ENA, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(MOTOR_ENA, 255);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read rain sensor value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read rain sensor value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to rain level
        int rain_level = convert_adc_to_rain_level(adc_value);

        // Log rain data
        log_rain_data(rain_level);

        // Control motor based on rain level
        if (rain_level >= RAIN_THRESHOLD) {
            printf("Rain detected! Closing window.\n");
            control_motor(1, MOTOR_SPEED); // Close window
            gpioDelay(3000); // Wait 3 seconds
            control_motor(0, MOTOR_SPEED); // Stop motor
            printf("Window closed.\n");
        } else {
            printf("No rain detected. Opening window.\n");
            control_motor(-1, MOTOR_SPEED); // Open window
            gpioDelay(3000); // Wait 3 seconds
            control_motor(0, MOTOR_SPEED); // Stop motor
            printf("Window opened.\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_motor(0, MOTOR_SPEED); // Stop motor
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

