#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define MIC_DATA_PIN 26
#define MIC_CLOCK_PIN 19
#define LED_PIN 16

// Define constants
#define NUM_SAMPLES 100
#define THRESHOLD 700 // Adjust based on calibration
#define LED_ON_TIME_MS 500
#define DEBOUNCE_DELAY_MS 50

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_microphone_data();
int process_audio_data(int *samples);
void control_led(int state);
void log_detection();
void signal_handler(int signal);

// Structure to hold GPIO pin configurations
typedef struct {
    int data_pin;
    int clock_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_DATA_PIN, PI_INPUT);
    gpioSetMode(MIC_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read microphone data using bit-banged ADC
int read_microphone_data() {
    int data = 0;
    for (int i = 0; i < 10; i++) {
        gpioWrite(MIC_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay for clock stability
        data = data << 1;
        data |= gpioRead(MIC_DATA_PIN);
        gpioWrite(MIC_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay for clock stability
    }
    return data;
}

// Function to process audio data and detect claps
int process_audio_data(int *samples) {
    int sum = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        sum += samples[i];
    }
    int average = sum / NUM_SAMPLES;
    return (average > THRESHOLD) ? 1 : 0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log detection events
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Clap detected!\n", timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int samples[NUM_SAMPLES];
    int debounce_count = 0;

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read microphone data
        int raw_data = read_microphone_data();

        // Store the data in the circular buffer
        samples[debounce_count] = raw_data;
        debounce_count = (debounce_count + 1) % NUM_SAMPLES;

        // Process audio data after filling the buffer
        if (debounce_count == 0) {
            if (process_audio_data(samples)) {
                // Clap detected
                control_led(1); // Turn on LED
                log_detection(); // Log the detection
                gpioDelay(LED_ON_TIME_MS * 1000); // Keep LED on for specified time
                control_led(0); // Turn off LED
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

