    for (int i = 0; i < NUM_SAMPLES; i++) {
        sum += samples[i];
    }
    int average = sum / NUM_SAMPLES;
    return (average > THRESHOLD) ? 1 : 0;
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Function to log detection events
void log_detection() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Clap detected!\n", timestamp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Exiting...\n");
    control_led(0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    int samples[NUM_SAMPLES];
    int debounce_count = 0;

    printf("Clap detector running. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read microphone data
        int raw_data = read_microphone_data();

        // Store the data in the circular buffer
        samples[debounce_count] = raw_data;
        debounce_count = (debounce_count + 1) % NUM_SAMPLES;

        // Process audio data after filling the buffer
        if (debounce_count == 0) {
            if (process_audio_data(samples)) {
                // Clap detected
                control_led(1); // Turn on LED
                log_detection(); // Log the detection
                gpioDelay(LED_ON_TIME_MS * 1000); // Keep LED on for specified time
                control_led(0); // Turn off LED
                gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
            }
        }

        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return 0;
}

