// Calibration parameters (placeholder)
#define A 26.0
#define B -6.0

// Global variable to track if the program should exit
volatile sig_atomic_t program_running = 1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
float voltage_to_distance(int gpio_value);
void log_distance(float distance);
void check_proximity(float distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully...\n", signal);
        program_running = 0;
    }
}

// Exports the specified GPIO pin
int gpio_export(int pin) {
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/export", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open /sys/class/gpio/export for writing: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        fprintf(stderr, "Error: Unable to write to /sys/class/gpio/export: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Unexports the specified GPIO pin
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    FILE *fp = NULL;

    fp = fopen("/sys/class/gpio/unexport", "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open /sys/class/gpio/unexport for writing: %s\n", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (fwrite(buffer, 1, len, fp) != len) {
        fprintf(stderr, "Error: Unable to write to /sys/class/gpio/unexport: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Sets the direction of the specified GPIO pin (in or out)
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open %s for writing: %s\n", path, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%s", direction) < 0) {
        fprintf(stderr, "Error: Unable to write to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Reads the value of the specified GPIO pin (0 or 1)
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    FILE *fp = NULL;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fp = fopen(path, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open %s for reading: %s\n", path, strerror(errno));
        return -1;
    }

    if (fgets(value_str, 3, fp) == NULL) {
        fprintf(stderr, "Error: Unable to read from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return atoi(value_str);
}

// Converts the GPIO value (0 or 1) to a placeholder voltage (0V or 3.3V)
float voltage_to_distance(int gpio_value) {
    return (gpio_value == 0) ? 0.0 : 3.3;
}

// Logs the distance to a file with a timestamp
void log_distance(float distance) {
    FILE *fp = NULL;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Unable to open %s for appending: %s\n", LOG_FILE, strerror(errno));
        return;
    }

    fprintf(fp, "%s, Distance: %.2f mm\n", timestamp, distance);
    fclose(fp);
}

// Checks if the distance is below the threshold and prints a message
void check_proximity(float distance) {
    if (distance < DISTANCE_THRESHOLD) {
        printf("Feeder Activated\n");
    } else {
        printf("Feeder Idle\n");
    }
}

int main() {
    int gpio_value;
    float distance;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export the GPIO pin
    if (gpio_export(GPIO_PIN) == -1) {
        fprintf(stderr, "Failed to export GPIO %d. Exiting.\n", GPIO_PIN);
        return 1;
    }

    // Set the GPIO direction to input
    if (gpio_set_direction(GPIO_PIN, "in") == -1) {
        fprintf(stderr, "Failed to set GPIO %d direction to input. Exiting.\n", GPIO_PIN);
        gpio_unexport(GPIO_PIN);
        return 1;
    }

    printf("Distance sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read the GPIO value
        gpio_value = gpio_read(GPIO_PIN);
        if (gpio_value == -1) {
            fprintf(stderr, "Failed to read GPIO %d value. Retrying in 1 second.\n", GPIO_PIN);
            sleep(1);
            continue;
        }

        // Convert the GPIO value to a distance
        distance = voltage_to_distance(gpio_value);

        // Apply the calibration formula
        distance = A / distance + B;

        // Log the distance
        log_distance(distance);

        // Check for proximity
        check_proximity(distance);

        // Wait for 1 second
        sleep(1);
    }

    // Unexport the GPIO pin before exiting
    if (gpio_unexport(GPIO_PIN) == -1) {
        fprintf(stderr, "Failed to unexport GPIO %d. May need manual cleanup.\n", GPIO_PIN);
    }

    printf("Program finished.\n");
    return 0;
}

