#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define PUMP_GPIO_CHIP "gpiochip0"
#define PUMP_GPIO_PIN 17
#define DRY_ADC_VALUE 800
#define WET_ADC_VALUE 300
#define MOISTURE_THRESHOLD 30.0
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE "soil_moisture.log"

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *pump_gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device);
int spi_read_adc(int channel);
float calculate_moisture_percentage(int adc_value);
int control_pump(int state);
int log_data(float moisture_percentage, int pump_state);
void signal_handler(int sig);
int gpio_init(const char *chip_name, int pin);
int gpio_set_value(int value);

// SPI Initialization
int spi_init(const char *device) {
    int fd;
    unsigned int mode = 0; // SPI mode 0
    unsigned int bits = 8; // 8 bits per word
    unsigned int speed = 1000000; // 1 MHz

    fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MODE, &mode) == -1) {
        perror("Error getting SPI mode");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_BITS_PER_WORD, &bits) == -1) {
        perror("Error getting bits per word");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting max speed HZ");
        close(fd);
        return -1;
    }

    if (ioctl(fd, SPI_IOC_RD_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error getting max speed HZ");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Read ADC
int spi_read_adc(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];
    struct spi_ioc_transfer tr;

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (4 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)); // Single-ended + channel
    tx_buf[2] = 0x00; // Don't care

    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx_buf;
    tr.rx_buf = (unsigned long)rx_buf;
    tr.len = 3;
    tr.delay_usecs = 0;
    tr.speed_hz = 1000000; // 1 MHz
    tr.bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract the ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Calculate Moisture Percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1.0; // Indicate an error
    }

    float moisture_percentage = 100.0 - ((float)(adc_value - WET_ADC_VALUE) / (float)(DRY_ADC_VALUE - WET_ADC_VALUE) * 100.0);

    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Control Pump
int control_pump(int state) {
    if (gpio_set_value(state) != 0) {
        fprintf(stderr, "Error controlling pump\n");
        return -1;
    }
    return 0;
}

// Log Data
int log_data(float moisture_percentage, int pump_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file not opened\n");
        return -1;
    }

    fprintf(log_file, "%s, Moisture: %.2f%%, Pump: %s\n", timestamp, moisture_percentage, pump_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO Initialization
int gpio_init(const char *chip_name, int pin) {
    gpio_chip = gpiod_chip_open_by_name(chip_name);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    pump_gpio_line = gpiod_chip_get_line(gpio_chip, pin);
    if (!pump_gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(pump_gpio_line, "soil_moisture", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Set Value
int gpio_set_value(int value) {
    if (gpiod_line_set_value(pump_gpio_line, value) < 0) {
        perror("Error setting GPIO value");
        return -1;
    }
    return 0;
}

int main() {
    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // SPI Initialization
    spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed\n");
        return 1;
    }

    // GPIO Initialization
    if (gpio_init(PUMP_GPIO_CHIP, PUMP_GPIO_PIN) < 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(spi_fd);
        return 1;
    }

    // Log File
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_line_release(pump_gpio_line);
        gpiod_chip_close(gpio_chip);
        close(spi_fd);
        return 1;
    }

    int pump_state = 0; // 0 = OFF, 1 = ON

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            // Optionally add retry logic here
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);
        if (moisture_percentage < 0.0) {
            fprintf(stderr, "Error calculating moisture percentage\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        // Control pump
        if (moisture_percentage < MOISTURE_THRESHOLD && pump_state == 0) {
            if (control_pump(1) == 0) {
                pump_state = 1;
                printf("Pump turned ON\n");
            }
        } else if (moisture_percentage >= MOISTURE_THRESHOLD && pump_state == 1) {
            if (control_pump(0) == 0) {
                pump_state = 0;
                printf("Pump turned OFF\n");
            }
        }

        // Log data
        if (log_data(moisture_percentage, pump_state) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    fclose(log_file);
    gpiod_line_release(pump_gpio_line);
    gpiod_chip_close(gpio_chip);
    close(spi_fd);

    return 0;
}

