#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/spi/spidev.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <errno.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define GPIO_PIN 17
#define VREF 3.3 // Reference voltage for MCP3008
#define SENSITIVITY 0.100 // Sensitivity of MLX91209 in V/A
#define LOG_FILE "current_log.txt"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    char spi_device[20];
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int mcp3008_channel;
    int gpio_pin;
    float vref;
    float sensitivity;
    char log_file[20];
} Config;

// Function prototypes
int spi_init(const char *device, int mode, int bits, int speed);
int spi_read_adc(int fd, int channel);
float adc_to_current(int adc_value, float vref, float sensitivity);
int gpio_init(int pin);
int log_data(FILE *fp, float current);
void signal_handler(int signal);
int config_load(const char *filename, Config *config);

// SPI initialization function
int spi_init(const char *device, int mode, int bits, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode_arg = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_arg) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    int bits_arg = bits;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_arg) == -1) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set SPI speed
    int speed_arg = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_arg) == -1) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI read ADC function
int spi_read_adc(int fd, int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel << 4)) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Dummy byte

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value, float vref, float sensitivity) {
    float voltage = (adc_value / 1023.0) * vref;
    float current = voltage / sensitivity;
    return current;
}

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 1); // Set initial state to HIGH
    return 0;
}

// Log data function
int log_data(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Configuration loading function
int config_load(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_device") == 0) {
            strncpy(config->spi_device, value, sizeof(config->spi_device) - 1);
            config->spi_device[sizeof(config->spi_device) - 1] = '\0';
        } else if (strcmp(key, "spi_mode") == 0) {
            config->spi_mode = atoi(value);
        } else if (strcmp(key, "spi_bits_per_word") == 0) {
            config->spi_bits_per_word = atoi(value);
        } else if (strcmp(key, "spi_speed") == 0) {
            config->spi_speed = atoi(value);
        } else if (strcmp(key, "mcp3008_channel") == 0) {
            config->mcp3008_channel = atoi(value);
        } else if (strcmp(key, "gpio_pin") == 0) {
            config->gpio_pin = atoi(value);
        } else if (strcmp(key, "vref") == 0) {
            config->vref = atof(value);
        } else if (strcmp(key, "sensitivity") == 0) {
            config->sensitivity = atof(value);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(config->log_file, value, sizeof(config->log_file) - 1);
            config->log_file[sizeof(config->log_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    Config config;
    if (config_load("config.txt", &config) != 0) {
        fprintf(stderr, "Failed to load configuration. Using default values.\n");
        // Set default values if loading fails
        strcpy(config.spi_device, SPI_DEVICE);
        config.spi_mode = SPI_MODE;
        config.spi_bits_per_word = SPI_BITS_PER_WORD;
        config.spi_speed = SPI_SPEED;
        config.mcp3008_channel = MCP3008_CHANNEL;
        config.gpio_pin = GPIO_PIN;
        config.vref = VREF;
        config.sensitivity = SENSITIVITY;
        strcpy(config.log_file, LOG_FILE);
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(config.gpio_pin) != 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(config.spi_device, config.spi_mode, config.spi_bits_per_word, config.spi_speed);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to terminate.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value, config.vref, config.sensitivity);

        // Log data
        if (log_data(log_file, current) != 0) {
            fprintf(stderr, "Error logging data. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

