    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// ADC to current conversion function
float adc_to_current(int adc_value, float vref, float sensitivity) {
    float voltage = (adc_value / 1023.0) * vref;
    float current = voltage / sensitivity;
    return current;
}

// GPIO initialization function
int gpio_init(int pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(pin, PI_OUTPUT);
    gpioWrite(pin, 1); // Set initial state to HIGH
    return 0;
}

// Log data function
int log_data(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Configuration loading function
int config_load(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "\n");

        if (key == NULL || value == NULL) continue;

        if (strcmp(key, "spi_device") == 0) {
            strncpy(config->spi_device, value, sizeof(config->spi_device) - 1);
            config->spi_device[sizeof(config->spi_device) - 1] = '\0';
        } else if (strcmp(key, "spi_mode") == 0) {
            config->spi_mode = atoi(value);
        } else if (strcmp(key, "spi_bits_per_word") == 0) {
            config->spi_bits_per_word = atoi(value);
        } else if (strcmp(key, "spi_speed") == 0) {
            config->spi_speed = atoi(value);
        } else if (strcmp(key, "mcp3008_channel") == 0) {
            config->mcp3008_channel = atoi(value);
        } else if (strcmp(key, "gpio_pin") == 0) {
            config->gpio_pin = atoi(value);
        } else if (strcmp(key, "vref") == 0) {
            config->vref = atof(value);
        } else if (strcmp(key, "sensitivity") == 0) {
            config->sensitivity = atof(value);
        } else if (strcmp(key, "log_file") == 0) {
            strncpy(config->log_file, value, sizeof(config->log_file) - 1);
            config->log_file[sizeof(config->log_file) - 1] = '\0';
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    Config config;
    if (config_load("config.txt", &config) != 0) {
        fprintf(stderr, "Failed to load configuration. Using default values.\n");
        // Set default values if loading fails
        strcpy(config.spi_device, SPI_DEVICE);
        config.spi_mode = SPI_MODE;
        config.spi_bits_per_word = SPI_BITS_PER_WORD;
        config.spi_speed = SPI_SPEED;
        config.mcp3008_channel = MCP3008_CHANNEL;
        config.gpio_pin = GPIO_PIN;
        config.vref = VREF;
        config.sensitivity = SENSITIVITY;
        strcpy(config.log_file, LOG_FILE);
    }

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init(config.gpio_pin) != 0) {
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_init(config.spi_device, config.spi_mode, config.spi_bits_per_word, config.spi_speed);
    if (spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to terminate.\n");

    while (!terminate) {
        // Read ADC value
        int adc_value = spi_read_adc(spi_fd, config.mcp3008_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value, config.vref, config.sensitivity);

        // Log data
        if (log_data(log_file, current) != 0) {
            fprintf(stderr, "Error logging data. Retrying in 1 second.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close(spi_fd);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

