#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define VREF 5.0         // Reference voltage
#define ZERO_CURRENT_VOLTAGE 2.5 // Voltage at 0A
#define FULL_SCALE_CURRENT 50.0  // Full-scale current
#define LOG_FILE "current_log.txt"

// Global variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// Function prototypes
int initialize_pigpio();
int open_spi();
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
float convert_to_current(float voltage);
int log_current(float current);
void signal_handler(int signal);
int close_resources();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int mcp3008_channel;
    float vref;
    float zero_current_voltage;
    float full_scale_current;
    char log_file[64];
} config_t;

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open SPI channel
int open_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return 1;
    }
    return 0;
}

// Read from MCP3008
int read_mcp3008(int channel) {
    char tx[3];
    char rx[3];

    tx[0] = 0x01;                  // Start bit
    tx[1] = (0x08 | (channel << 4)); // Single-ended mode, channel selection
    tx[2] = 0x00;                  // Don't care

    if (spiXfer(spi_handle, tx, rx, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

// Convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Convert voltage to current
float convert_to_current(float voltage) {
    if (voltage < 0 || voltage > VREF) {
        fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        return -1.0; // Indicate out-of-range
    }
    return (voltage - ZERO_CURRENT_VOLTAGE) * (FULL_SCALE_CURRENT / ZERO_CURRENT_VOLTAGE);
}

// Log current to file
int log_current(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

// Close resources
int close_resources() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio()) {
        return 1;
    }

    // Open SPI
    if (open_spi()) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        close_resources();
        return 1;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            float voltage = convert_to_voltage(adc_value);
            float current = convert_to_current(voltage);

            if (current >= 0) {
                log_current(current);
            }
        }

        gpioDelay(100000); // 100 ms
    }

    // Close resources before exiting
    close_resources();

    printf("Current monitoring stopped.\n");

    return 0;
}

