#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define SENSOR1_PIN 4
#define SENSOR2_PIN 17

// Define the number of debouncing samples
#define NUM_SAMPLES 5

// Define the debouncing delay in milliseconds
#define DEBOUNCE_DELAY_MS 2

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor1_line = NULL;
struct gpiod_line *sensor2_line = NULL;

// Function prototypes
int read_sensor(struct gpiod_line *line);
int debounce_sensor(struct gpiod_line *line);
void log_sensor_state(int sensor1_state, int sensor2_state);
void check_alert(int sensor1_state, int sensor2_state);
void cleanup(int signal);

// Signal handler for Ctrl+C
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");

    // Release GPIO lines
    if (sensor1_line) {
        gpiod_line_release(sensor1_line);
    }
    if (sensor2_line) {
        gpiod_line_release(sensor2_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to read the sensor value
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value: %s\n", strerror(-value));
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor reading
int debounce_sensor(struct gpiod_line *line) {
    int high_count = 0;
    for (int i = 0; i < NUM_SAMPLES; i++) {
        int value = read_sensor(line);
        if (value == 1) {
            high_count++;
        } else if (value < 0) {
            return -1; // Propagate error
        }
        usleep(DEBOUNCE_DELAY_MS * 1000); // Convert milliseconds to microseconds
    }
    return (high_count >= NUM_SAMPLES / 2) ? 1 : 0;
}

// Function to log the sensor state
void log_sensor_state(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor 1: %d, Sensor 2: %d\n", timestamp, sensor1_state, sensor2_state);
}

// Function to check for alert condition
void check_alert(int sensor1_state, int sensor2_state) {
    if (sensor1_state == 0 && sensor2_state == 0) {
        printf("ALERT: Both sensors detect object\n");
    }
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, cleanup);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get the GPIO lines for the sensors
    sensor1_line = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!sensor1_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 1: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    sensor2_line = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!sensor2_line) {
        fprintf(stderr, "Error getting GPIO line for sensor 2: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    // Request the GPIO lines for input
    if (gpiod_line_request_input(sensor1_line, "sensor1") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 1: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    if (gpiod_line_request_input(sensor2_line, "sensor2") < 0) {
        fprintf(stderr, "Error requesting GPIO line for sensor 2: %s\n", strerror(errno));
        cleanup(0);
        return 1;
    }

    // Main loop
    while (1) {
        int sensor1_state = debounce_sensor(sensor1_line);
        int sensor2_state = debounce_sensor(sensor2_line);

        if (sensor1_state < 0 || sensor2_state < 0) {
            fprintf(stderr, "Error during sensor reading. Exiting.\n");
            cleanup(0);
            return 1;
        }

        log_sensor_state(sensor1_state, sensor2_state);
        check_alert(sensor1_state, sensor2_state);

        sleep(1);
    }

    return 0;
}

