#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000
#define MCP3008_CHANNEL 0
#define READ_DELAY 60
#define MIN_ADC 300
#define MAX_ADC 800
#define LOG_FILE "soil_moisture_log.csv"

// Global flag for signal handling
volatile sig_atomic_t terminate = 0;

// Structure for SPI configuration
typedef struct {
    int channel;
    int baud;
} spi_config_t;

// Function prototypes
int read_mcp3008(int channel);
double calculate_moisture_level(int adc_value);
int log_data(double moisture_level);
void signal_handler(int signal);
int spi_setup(spi_config_t config);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    int handle, count, retries = 0;
    char tx_buf[3], rx_buf[3];

    tx_buf[0] = 0x01;
    tx_buf[1] = (0x08 | (channel << 4));
    tx_buf[2] = 0x00;

    while (retries < 3) {
        handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Open SPI channel
        if (handle < 0) {
            fprintf(stderr, "Error opening SPI channel: %d\n", handle);
            gpioTerminate();
            exit(1);
        }

