#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_COMMAND "libcamera-still -o /home/pi/security_cam/%Y%m%d_%H%M%S.jpg --width 1280 --height 720 --immediate"
#define IMAGE_DIR "/home/pi/security_cam/"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");
    return 0;
}

// Function to configure GPIO pin as input with pull-down resistor
int configure_gpio() {
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_DOWN);
    syslog(LOG_INFO, "GPIO %d configured as input with pull-down resistor", MOTION_SENSOR_GPIO);
    return 0;
}

// Function to read the motion sensor state
int read_motion_sensor() {
    return gpioRead(MOTION_SENSOR_GPIO);
}

// Function to apply a debounce delay
void debounce_delay() {
    gpioDelay(DEBOUNCE_DELAY_MS * 1000); // pigpioDelay takes microseconds
}

// Function to capture an image using libcamera-still
int capture_image() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), IMAGE_DIR "%Y%m%d_%H%M%S.jpg", timeinfo);
    snprintf(command, sizeof(command), CAPTURE_COMMAND, timeinfo->tm_year + 1900, timeinfo->tm_mon + 1, timeinfo->tm_mday, timeinfo->tm_hour, timeinfo->tm_min, timeinfo->tm_sec);

    syslog(LOG_INFO, "Capturing image: %s", filename);

    // Check if the image directory exists
    struct stat st = {0};
    if (stat(IMAGE_DIR, &st) == -1) {
        syslog(LOG_ERR, "Image directory %s does not exist. Creating...", IMAGE_DIR);
        if (mkdir(IMAGE_DIR, 0777) == -1) {
            syslog(LOG_ERR, "Failed to create image directory: %s", IMAGE_DIR);
            return -1;
        }
    }

    pid_t pid = fork();
    if (pid == 0) {
        // Child process
        execvp("libcamera-still", (char *const[]){"libcamera-still", "-o", filename, "--width", "1280", "--height", "720", "--immediate", NULL});
        syslog(LOG_ERR, "Failed to execute libcamera-still: %m");
        exit(EXIT_FAILURE);
    } else if (pid > 0) {
        // Parent process
        int status;
        waitpid(pid, &status, 0);
        if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
            syslog(LOG_INFO, "Image captured successfully: %s", filename);
            return 0;
        } else {
            syslog(LOG_ERR, "Image capture failed with status: %d", status);
            return -1;
        }
    } else {
        syslog(LOG_ERR, "Fork failed: %m");
        return -1;
    }
}

int main() {
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting motion detector...");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        closelog();
        return 1;
    }

    // Configure GPIO
    if (configure_gpio() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    int last_state = 0; // Assume no motion initially

    while (program_running) {
        int current_state = read_motion_sensor();

        if (current_state != last_state) {
            syslog(LOG_INFO, "Motion detected!");
            debounce_delay();
            if (read_motion_sensor() == current_state) { // Re-read to confirm
                if (capture_image() == 0) {
                    syslog(LOG_INFO, "Image captured successfully.");
                } else {
                    syslog(LOG_ERR, "Image capture failed.");
                }
            }
            last_state = current_state;
        }

        gpioDelay(50000); // Check every 50 ms
    }

    // Cleanup
    syslog(LOG_INFO, "Shutting down...");
    gpioTerminate();
    closelog();

    return 0;
}

