#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <signal.h>
#include <linux/videodev2.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT)
#define PGM_HEADER_SIZE 64
#define MAX_BUFFERS 1

static int fd = -1;
static void *buffers[MAX_BUFFERS];
static size_t buffer_sizes[MAX_BUFFERS];
static int num_buffers = 0;
static volatile sig_atomic_t stop_flag = 0;

// Signal handler for SIGINT and SIGTERM
static void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    stop_flag = 1;
    fprintf(stderr, "\nCaught signal, stopping...\n");
}

// Function to open the V4L2 device
int open_device(const char *device_name)
{
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", device_name, strerror(errno));
        return -1;
    }
    return fd;
}

// Function to set the video format
int set_format(int fd, uint32_t width, uint32_t height, uint32_t pixel_format)
{
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = pixel_format;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, int count)
{
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to query buffer information
int query_buffer(int fd, int index, void **buffer, size_t *size)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        fprintf(stderr, "Error querying buffer %d: %s\n", index, strerror(errno));
        return -1;
    }

    *size = buf.length;
    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        fprintf(stderr, "Error mapping buffer %d: %s\n", index, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to queue a buffer
int queue_buffer(int fd, int index)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "Error queuing buffer %d: %s\n", index, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to start streaming
int start_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to stop streaming
int stop_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to dequeue a buffer
int dequeue_buffer(int fd, int *index)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for buffer\n");
        return -1;
    }

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    *index = buf.index;
    return 0;
}

// Function to save a frame as a PGM file
int save_frame(const char *filename, const void *buffer, size_t size)
{
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file %s for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    // Write PGM header
    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);

    // Write image data
    if (fwrite(buffer, 1, size, fp) != size) {
        fprintf(stderr, "Error writing to file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Function to unmap buffers
int unmap_buffers()
{
    for (int i = 0; i < num_buffers; ++i) {
        if (munmap(buffers[i], buffer_sizes[i]) < 0) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to close the device
int close_device(int fd)
{
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[])
