        if (dequeue_buffer(fd, &buffer_index) < 0) {
            break; // Exit loop on dequeue error
        }

        // Create filename
        char filename[64];
        snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_count + 1);

        // Save frame
        if (save_frame(filename, buffers[buffer_index], IMAGE_SIZE) < 0) {
            fprintf(stderr, "Error saving frame %s\n", filename);
        }

        // Requeue buffer
        if (queue_buffer(fd, buffer_index) < 0) {
            break; // Exit loop on queue error
        }

        frame_count++;
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        unmap_buffers();
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Unmap buffers
    if (unmap_buffers() < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

