#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <errno.h>
#include <signal.h>
#include <poll.h>
#include <linux/videodev2.h>

#define DEVICE_NAME "/dev/video0"
#define FRAME_LOG_FILE "frame_log.txt"
#define BUFFER_COUNT 4

// Structure to hold video device information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffers[BUFFER_COUNT];
    int buffer_index;
    FILE *log_file;
} video_device_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signum) {
    if (signum == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to open the video device
int open_device(video_device_t *dev) {
    dev->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (dev->fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return 0;
}

// Function to query device capabilities
int query_capabilities(video_device_t *dev) {
    if (ioctl(dev->fd, VIDIOC_QUERYCAP, &dev->cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }
    return 0;
}

// Function to set the video format
int set_format(video_device_t *dev) {
    memset(&dev->fmt, 0, sizeof(dev->fmt));
    dev->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->fmt.fmt.pix.width = 640;
    dev->fmt.fmt.pix.height = 480;
    dev->fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    dev->fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(dev->fd, VIDIOC_S_FMT, &dev->fmt) < 0) {
        perror("Error setting format");
        return -1;
    }
    return 0;
}

// Function to request buffers
int request_buffers(video_device_t *dev) {
    memset(&dev->req, 0, sizeof(dev->req));
    dev->req.count = BUFFER_COUNT;
    dev->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_REQBUFS, &dev->req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }
    return 0;
}

// Function to map buffers
int map_buffers(video_device_t *dev) {
    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&dev->buf, 0, sizeof(dev->buf));
        dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        dev->buf.memory = V4L2_MEMORY_MMAP;
        dev->buf.index = i;

        if (ioctl(dev->fd, VIDIOC_QUERYBUF, &dev->buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        dev->buffers[i] = mmap(NULL, dev->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev->fd, dev->buf.m.offset);
        if (dev->buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to start streaming
int start_streaming(video_device_t *dev) {
    for (int i = 0; i < BUFFER_COUNT; i++) {
        memset(&dev->buf, 0, sizeof(dev->buf));
        dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        dev->buf.memory = V4L2_MEMORY_MMAP;
        dev->buf.index = i;

        if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(video_device_t *dev) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(dev->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    memset(&dev->buf, 0, sizeof(dev->buf));
    dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_DQBUF, &dev->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Get timestamp
    struct timeval tv_now;
    gettimeofday(&tv_now, NULL);
    long long timestamp_us = (long long)tv_now.tv_sec * 1000000 + tv_now.tv_usec;

    // Log timestamp to file
    fprintf(dev->log_file, "%lld.%06ld\n", timestamp_us / 1000000, timestamp_us % 1000000);
    fflush(dev->log_file);

    // Requeue the buffer
    if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(video_device_t *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers(video_device_t *dev) {
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (munmap(dev->buffers[i], dev->req.bufs[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to release buffers
int release_buffers(video_device_t *dev) {
    if (ioctl(dev->fd, VIDIOC_REQBUFS, &dev->req) < 0) {
        perror("Error releasing buffers");
        return -1;
    }
    return 0;
}

// Function to close the device
int close_device(video_device_t *dev) {
    if (close(dev->fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    video_device_t dev;
    memset(&dev, 0, sizeof(dev));

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    if (open_device(&dev) < 0) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Set format
    if (set_format(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Map buffers
    if (map_buffers(&dev) < 0) {
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Open log file
    dev.log_file = fopen(FRAME_LOG_FILE, "a");
    if (dev.log_file == NULL) {
        perror("Error opening log file");
        unmap_buffers(&dev);
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&dev) < 0) {
        fclose(dev.log_file);
        unmap_buffers(&dev);
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Capture frames
    while (program_running) {
        if (capture_frame(&dev) < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }
    }

    // Stop streaming
    if (stop_streaming(&dev) < 0) {
        fprintf(stderr, "Error stopping stream, continuing...\n");
    }

    // Clean up
    fclose(dev.log_file);
    unmap_buffers(&dev);
    release_buffers(&dev);
    close_device(&dev);

    return EXIT_SUCCESS;
}

