    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(dev->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select()");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "select() timeout\n");
        return -1;
    }

    memset(&dev->buf, 0, sizeof(dev->buf));
    dev->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev->buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev->fd, VIDIOC_DQBUF, &dev->buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Get timestamp
    struct timeval tv_now;
    gettimeofday(&tv_now, NULL);
    long long timestamp_us = (long long)tv_now.tv_sec * 1000000 + tv_now.tv_usec;

    // Log timestamp to file
    fprintf(dev->log_file, "%lld.%06ld\n", timestamp_us / 1000000, timestamp_us % 1000000);
    fflush(dev->log_file);

    // Requeue the buffer
    if (ioctl(dev->fd, VIDIOC_QBUF, &dev->buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(video_device_t *dev) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(dev->fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers(video_device_t *dev) {
    for (int i = 0; i < BUFFER_COUNT; i++) {
        if (munmap(dev->buffers[i], dev->req.bufs[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }
    return 0;
}

// Function to release buffers
int release_buffers(video_device_t *dev) {
    if (ioctl(dev->fd, VIDIOC_REQBUFS, &dev->req) < 0) {
        perror("Error releasing buffers");
        return -1;
    }
    return 0;
}

// Function to close the device
int close_device(video_device_t *dev) {
    if (close(dev->fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main() {
    video_device_t dev;
    memset(&dev, 0, sizeof(dev));

    // Install signal handler
    signal(SIGINT, signal_handler);

    // Open the device
    if (open_device(&dev) < 0) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Set format
    if (set_format(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(&dev) < 0) {
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Map buffers
    if (map_buffers(&dev) < 0) {
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Open log file
    dev.log_file = fopen(FRAME_LOG_FILE, "a");
    if (dev.log_file == NULL) {
        perror("Error opening log file");
        unmap_buffers(&dev);
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(&dev) < 0) {
        fclose(dev.log_file);
        unmap_buffers(&dev);
        release_buffers(&dev);
        close_device(&dev);
        return EXIT_FAILURE;
    }

    // Capture frames
    while (program_running) {
        if (capture_frame(&dev) < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }
    }

    // Stop streaming
    if (stop_streaming(&dev) < 0) {
        fprintf(stderr, "Error stopping stream, continuing...\n");
    }

    // Clean up
    fclose(dev.log_file);
    unmap_buffers(&dev);
    release_buffers(&dev);
    close_device(&dev);

    return EXIT_SUCCESS;
}

