#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>

#define VIDEO_DEVICE "/dev/video0"
#define BUFFER_COUNT 4
#define FRAGMENT_SIZE 65000
#define HEADER_SIZE sizeof(frame_header_t)

typedef struct {
    unsigned int frame_index;
    unsigned int fragment_index;
    unsigned int total_fragments;
    unsigned int payload_size;
} frame_header_t;

typedef struct {
    int fd;
    void *buffer;
    size_t size;
} buffer_t;

static volatile int running = 1;
static int sockfd = -1;
static buffer_t buffers[BUFFER_COUNT];
static unsigned int frame_index = 0;

void signal_handler(int sig) {
    printf("Signal received, exiting...\n");
    running = 0;
}

int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", VIDEO_DEVICE);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", VIDEO_DEVICE);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    struct v4l2_streamparm streamparm;
    memset(&streamparm, 0, sizeof(streamparm));
    streamparm.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    streamparm.parm.capture.timeperframe.numerator = 30;
    streamparm.parm.capture.timeperframe.denominator = 1;

    if (ioctl(fd, VIDIOC_S_PARM, &streamparm) < 0) {
        perror("Error setting frame rate");
        return -1;
    }

    return 0;
}

int init_mmap(int fd, buffer_t *buffer) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        return -1;
    }

    buffer->size = buf.length;
    buffer->buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (buffer->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    return 0;
}

int start_streaming(int fd) {
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

int capture_frame(int fd, buffer_t *buffer) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return buf.index;
}

int send_fragment(int sockfd, const void *data, size_t data_size, unsigned int frame_index, unsigned int fragment_index, unsigned int total_fragments, unsigned int payload_size) {
    frame_header_t header;
    header.frame_index = frame_index;
    header.fragment_index = fragment_index;
    header.total_fragments = total_fragments;
    header.payload_size = payload_size;

    char buffer[FRAGMENT_SIZE + HEADER_SIZE];
    memcpy(buffer, &header, HEADER_SIZE);
    memcpy(buffer + HEADER_SIZE, data, data_size);

    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(5000); // Example port
    if (inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        return -1;
    }

    if (sendto(sockfd, buffer, data_size + HEADER_SIZE, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending data");
        return -1;
    }

    return 0;
}

int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }
    return 0;
}

int uninit_device(int fd) {
    for (int i = 0; i < BUFFER_COUNT; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer for uninit");
            return -1;
        }
    }
    return 0;
}

int close_device(int fd) {
    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return EXIT_FAILURE;
    }

    const char *server_ip = argv[1];
    int server_port = atoi(argv[2]);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int fd = open_device(VIDEO_DEVICE);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    if (init_device(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (init_mmap(fd, &buffers[0]) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("Error creating socket");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (start_streaming(fd) < 0) {
        close(sockfd);
        close_device(fd);
        return EXIT_FAILURE;
    }

    while (running) {
        int buffer_index = capture_frame(fd, &buffers[0]);
        if (buffer_index < 0) {
            fprintf(stderr, "Error capturing frame, exiting...\n");
            break;
        }

        size_t frame_size = buffers[buffer_index].size;
        unsigned int total_fragments = (frame_size + FRAGMENT_SIZE - 1) / FRAGMENT_SIZE;

        for (unsigned int i = 0; i < total_fragments; ++i) {
            size_t offset = i * FRAGMENT_SIZE;
            size_t fragment_size = (i == total_fragments - 1) ? (frame_size % FRAGMENT_SIZE) : FRAGMENT_SIZE;

            if (send_fragment(sockfd, (char *)buffers[buffer_index].buffer + offset, fragment_size, frame_index, i, total_fragments, fragment_size) < 0) {
                fprintf(stderr, "Error sending fragment, exiting...\n");
                running = 0;
                break;
            }
        }

        frame_index++;
    }

    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Error stopping stream, continuing cleanup...\n");
    }

    close(sockfd);

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (buffers[i].buffer != NULL && buffers[i].buffer != MAP_FAILED) {
            if (munmap(buffers[i].buffer, buffers[i].size) < 0) {
                perror("Error unmapping buffer");
            }
        }
    }

    if (close_device(fd) < 0) {
        fprintf(stderr, "Error closing device, exiting...\n");
    }

    return EXIT_SUCCESS;
}

