// Structure to hold device information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void **buffers;
    size_t buffer_size;
} device_info_t;

device_info_t dev;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    printf("Caught signal %d, cleaning up...\n", signum);
    // Stop streaming
    if (dev.fd != -1) {
        ioctl(dev.fd, VIDIOC_STREAMOFF, &dev.type);
    }

    // Unmap buffers
    if (dev.buffers != NULL) {
        for (int i = 0; i < dev.req.count; i++) {
            if (dev.buffers[i] != NULL) {
                munmap(dev.buffers[i], dev.buffer_size);
            }
        }
        free(dev.buffers);
    }

    // Close device
    if (dev.fd != -1) {
        close(dev.fd);
    }

    // Close output file
    if (file_fd != -1) {
        close(file_fd);
    }

    exit(0);
}

// Function to initialize the device
int init_device() {
    dev.fd = open(VIDEO_DEVICE, O_RDWR /*| O_NONBLOCK*/);
    if (dev.fd == -1) {
        perror("Error opening device");
        return -1;
    }

    // Check device capabilities
    if (ioctl(dev.fd, VIDIOC_QUERYCAP, &dev.cap) == -1) {
        perror("Error querying capabilities");
        close(dev.fd);
        return -1;
    }

    if (!(dev.cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(dev.fd);
        return -1;
    }

    if (!(dev.cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        close(dev.fd);
        return -1;
    }

    // Set image format
    dev.fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev.fmt.fmt.pix.width = IMAGE_WIDTH;
    dev.fmt.fmt.pix.height = IMAGE_HEIGHT;
    dev.fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG; // Request MJPEG
    dev.fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(dev.fd, VIDIOC_S_FMT, &dev.fmt) == -1) {
        perror("Error setting format");
        close(dev.fd);
        return -1;
    }

    printf("Format set to MJPEG, width: %d, height: %d\n", dev.fmt.fmt.pix.width, dev.fmt.fmt.pix.height);

    // Request buffers
    dev.req.count = NUM_BUFFERS;
    dev.req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev.req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev.fd, VIDIOC_REQBUFS, &dev.req) == -1) {
        perror("Error requesting buffers");
        close(dev.fd);
        return -1;
    }

    if (dev.req.count < NUM_BUFFERS) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(dev.fd);
        return -1;
    }

    // Allocate buffer array
    dev.buffers = calloc(dev.req.count, sizeof(void*));
    if (!dev.buffers) {
        perror("Error allocating buffer array");
        close(dev.fd);
        return -1;
    }

    dev.buffer_size = BUFFER_SIZE; // Adjust based on format

    // Map buffers
    for (int i = 0; i < dev.req.count; i++) {
        dev.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        dev.buf.memory = V4L2_MEMORY_MMAP;
        dev.buf.index = i;

        if (ioctl(dev.fd, VIDIOC_QUERYBUF, &dev.buf) == -1) {
            perror("Error querying buffer");
            close(dev.fd);
            free(dev.buffers);
            return -1;
        }

        dev.buffers[i] = mmap(NULL, dev.buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, dev.fd, dev.buf.m.offset);
        if (dev.buffers[i] == MAP_FAILED) {
            perror("Error mapping buffer");
            close(dev.fd);
            free(dev.buffers);
            return -1;
        }
    }

    // Queue buffers
    for (int i = 0; i < dev.req.count; i++) {
        dev.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        dev.buf.memory = V4L2_MEMORY_MMAP;
        dev.buf.index = i;

        if (ioctl(dev.fd, VIDIOC_QBUF, &dev.buf) == -1) {
            perror("Error queuing buffer");
            close(dev.fd);
            free(dev.buffers);
            return -1;
        }
    }

    return 0;
}

// Function to start streaming
int start_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(dev.fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to capture a single frame
int capture_frame() {
    dev.buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    dev.buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(dev.fd, VIDIOC_DQBUF, &dev.buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Basic error checking: ensure bytesused is greater than 0
    if (dev.buf.bytesused == 0) {
        fprintf(stderr, "Warning: bytesused is 0, frame may be corrupt\n");
    }

    return 0;
}

// Function to write the frame to a file
int write_to_file() {
    file_fd = open(OUTPUT_FILE, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (file_fd == -1) {
        perror("Error opening output file");
        return -1;
    }

    // Write the raw MJPEG data directly to the file
    ssize_t bytes_written = write(file_fd, dev.buffers[dev.buf.index], dev.buf.bytesused);
    if (bytes_written == -1) {
        perror("Error writing to file");
        close(file_fd);
        return -1;
    }

    printf("Wrote %zd bytes to %s\n", bytes_written, OUTPUT_FILE);

    close(file_fd);
    file_fd = -1; // Reset file_fd after closing

    return 0;
}

// Function to stop streaming
int stop_streaming() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;

    if (ioctl(dev.fd, VIDIOC_STREAMOFF, &type) == -1) {
        perror("Error stopping stream");
        return -1;
    }

    return 0;
}

// Function to clean up resources
int cleanup() {
    // Unmap buffers
    if (dev.buffers != NULL) {
        for (int i = 0; i < dev.req.count; i++) {
            if (dev.buffers[i] != NULL) {
                munmap(dev.buffers[i], dev.buffer_size);
            }
        }
        free(dev.buffers);
    }

    // Close device
    if (dev.fd != -1) {
        close(dev.fd);
    }

    // Close output file
    if (file_fd != -1) {
        close(file_fd);
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize device
    if (init_device() == -1) {
        fprintf(stderr, "Device initialization failed\n");
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming() == -1) {
        fprintf(stderr, "Streaming start failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Capture frame
    if (capture_frame() == -1) {
        fprintf(stderr, "Frame capture failed\n");
        stop_streaming();
        cleanup();
        return EXIT_FAILURE;
    }

    // Write to file
    if (write_to_file() == -1) {
        fprintf(stderr, "File write failed\n");
        stop_streaming();
        cleanup();
        return EXIT_FAILURE;
    }

    // Stop streaming
    if (stop_streaming() == -1) {
        fprintf(stderr, "Streaming stop failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    // Cleanup resources
    if (cleanup() == -1) {
        fprintf(stderr, "Cleanup failed\n");
        return EXIT_FAILURE;
    }

    printf("Captured and saved image.jpg\n");

    return EXIT_SUCCESS;
}

