#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define TILT_UP_BUTTON 6
#define TILT_DOWN_BUTTON 7
#define PAN_LEFT_BUTTON 8
#define PAN_RIGHT_BUTTON 9

// Define servo limits
#define MIN_PULSE_WIDTH 1000 // 1 ms
#define MAX_PULSE_WIDTH 2000 // 2 ms
#define MIN_DUTY 25
#define MAX_DUTY 125

// Define initial servo positions
#define INITIAL_PAN_DUTY 75
#define INITIAL_TILT_DUTY 75

// Global variables
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
void set_servo_pulse_width(int pin, int duty);
int read_button(int pin);
void update_servo_positions(int *pan_duty, int *tilt_duty);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and sets up GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_UP_BUTTON, PI_INPUT);
    gpioSetMode(TILT_DOWN_BUTTON, PI_INPUT);
    gpioSetMode(PAN_LEFT_BUTTON, PI_INPUT);
    gpioSetMode(PAN_RIGHT_BUTTON, PI_INPUT);

    // Enable pull-up resistors on buttons
    gpioSetPullUpDown(TILT_UP_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(TILT_DOWN_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_LEFT_BUTTON, PI_PUD_UP);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON, PI_PUD_UP);

    return 0;
}

// Sets the servo pulse width based on the duty cycle
void set_servo_pulse_width(int pin, int duty) {
    // Calculate pulse width based on duty cycle
    int pulse_width = MIN_PULSE_WIDTH + (int)((float)(duty - MIN_DUTY) / (MAX_DUTY - MIN_DUTY) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(pin, pulse_width);
}

// Reads the state of a button
int read_button(int pin) {
    return gpioRead(pin);
}

// Updates the servo positions based on button presses
void update_servo_positions(int *pan_duty, int *tilt_duty) {
    int tilt_up = read_button(TILT_UP_BUTTON);
    int tilt_down = read_button(TILT_DOWN_BUTTON);
    int pan_left = read_button(PAN_LEFT_BUTTON);
    int pan_right = read_button(PAN_RIGHT_BUTTON);

    if (tilt_up) {
        *tilt_duty += 5;
        if (*tilt_duty > MAX_DUTY) {
            *tilt_duty = MAX_DUTY;
        }
    }
    if (tilt_down) {
        *tilt_duty -= 5;
        if (*tilt_duty < MIN_DUTY) {
            *tilt_duty = MIN_DUTY;
        }
    }
    if (pan_left) {
        *pan_duty -= 5;
        if (*pan_duty < MIN_DUTY) {
            *pan_duty = MIN_DUTY;
        }
    }
    if (pan_right) {
        *pan_duty += 5;
        if (*pan_duty > MAX_DUTY) {
            *pan_duty = MAX_DUTY;
        }
    }
}

// Cleans up the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize servo positions
    int pan_duty = INITIAL_PAN_DUTY;
    int tilt_duty = INITIAL_TILT_DUTY;

    set_servo_pulse_width(PAN_SERVO_PIN, pan_duty);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_duty);

    printf("Pan-Tilt Control System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        update_servo_positions(&pan_duty, &tilt_duty);

        set_servo_pulse_width(PAN_SERVO_PIN, pan_duty);
        set_servo_pulse_width(TILT_SERVO_PIN, tilt_duty);

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

