    return gpioRead(pin);
}

// Updates the servo positions based on button presses
void update_servo_positions(int *pan_duty, int *tilt_duty) {
    int tilt_up = read_button(TILT_UP_BUTTON);
    int tilt_down = read_button(TILT_DOWN_BUTTON);
    int pan_left = read_button(PAN_LEFT_BUTTON);
    int pan_right = read_button(PAN_RIGHT_BUTTON);

    if (tilt_up) {
        *tilt_duty += 5;
        if (*tilt_duty > MAX_DUTY) {
            *tilt_duty = MAX_DUTY;
        }
    }
    if (tilt_down) {
        *tilt_duty -= 5;
        if (*tilt_duty < MIN_DUTY) {
            *tilt_duty = MIN_DUTY;
        }
    }
    if (pan_left) {
        *pan_duty -= 5;
        if (*pan_duty < MIN_DUTY) {
            *pan_duty = MIN_DUTY;
        }
    }
    if (pan_right) {
        *pan_duty += 5;
        if (*pan_duty > MAX_DUTY) {
            *pan_duty = MAX_DUTY;
        }
    }
}

// Cleans up the pigpio library
void cleanup_gpio() {
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize servo positions
    int pan_duty = INITIAL_PAN_DUTY;
    int tilt_duty = INITIAL_TILT_DUTY;

    set_servo_pulse_width(PAN_SERVO_PIN, pan_duty);
    set_servo_pulse_width(TILT_SERVO_PIN, tilt_duty);

    printf("Pan-Tilt Control System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        update_servo_positions(&pan_duty, &tilt_duty);

        set_servo_pulse_width(PAN_SERVO_PIN, pan_duty);
        set_servo_pulse_width(TILT_SERVO_PIN, tilt_duty);

        gpioDelay(50); // Delay for 50 ms
    }

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

