#include <jpeglib.h>
#include <setjmp.h>

#define VIDEO_DEVICE "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define FRAME_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV
#define BLUR_RADIUS 2
#define JPEG_QUALITY 75

// Structure to hold image data
typedef struct {
    unsigned char *data;
    int width;
    int height;
    int channels;
} Image;

// Global variables
int video_fd = -1;
Image *current_frame = NULL;
Image *blurred_frame = NULL;

// Signal handler for Ctrl+C
