        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) == -1) {
            fprintf(stderr, "Error querying buffer %d: %s\n", i, strerror(errno));
            return -1;
        }

        buffers[i] = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
        if (buffers[i] == MAP_FAILED) {
            fprintf(stderr, "Error mapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to queue buffers
int queue_buffers(int fd, void **buffers, int n_buffers) {
    struct v4l2_buffer buf;
    for (int i = 0; i < n_buffers; i++) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
            fprintf(stderr, "Error queuing buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to start streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) == -1) {
        fprintf(stderr, "Error starting streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int fd, void **buffers, int n_buffers, Image *frame) {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        fprintf(stderr, "Error during select: %s\n", strerror(errno));
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) == -1) {
        fprintf(stderr, "Error dequeuing buffer: %s\n", strerror(errno));
        return -1;
    }

    // Copy the frame data
    frame->data = (unsigned char *)malloc(FRAME_SIZE);
    if (frame->data == NULL) {
        fprintf(stderr, "Error allocating memory for frame data\n");
        return -1;
    }
    memcpy(frame->data, buffers[buf.index], FRAME_SIZE);
    frame->width = IMAGE_WIDTH;
    frame->height = IMAGE_HEIGHT;
    frame->channels = 2; // YUYV

    if (ioctl(fd, VIDIOC_QBUF, &buf) == -1) {
        fprintf(stderr, "Error queuing buffer: %s\n", strerror(errno));
        free(frame->data);
        frame->data = NULL;
        return -1;
    }

    return 0;
}

// Function to stop streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) == -1) {
        fprintf(stderr, "Error stopping streaming: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to unmap buffers
int unmap_buffers(void **buffers, int n_buffers) {
    for (int i = 0; i < n_buffers; i++) {
        if (munmap(buffers[i], FRAME_SIZE) == -1) {
            fprintf(stderr, "Error unmapping buffer %d: %s\n", i, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to free buffers
int free_buffers(int fd, int n_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = 0; // Release all buffers
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) == -1) {
        fprintf(stderr, "Error freeing buffers: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close the video device
int close_video_device(int fd) {
    if (close(fd) == -1) {
        fprintf(stderr, "Error closing video device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to convert YUYV to RGB24
void yuyv_to_rgb24(const Image *yuyv_frame, Image *rgb_frame) {
    rgb_frame->width = yuyv_frame->width;
    rgb_frame->height = yuyv_frame->height;
    rgb_frame->channels = 3;
    rgb_frame->data = (unsigned char *)malloc(rgb_frame->width * rgb_frame->height * rgb_frame->channels);

    if (rgb_frame->data == NULL) {
        fprintf(stderr, "Error allocating memory for RGB frame\n");
        return;
    }

    for (int i = 0; i < rgb_frame->height; i++) {
        for (int j = 0; j < rgb_frame->width; j += 2) {
            unsigned char y1 = yuyv_frame->data[(i * yuyv_frame->width + j) * 2];
            unsigned char u = yuyv_frame->data[(i * yuyv_frame->width + j) * 2 + 1];
            unsigned char y2 = yuyv_frame->data[(i * yuyv_frame->width + j + 1) * 2];
            unsigned char v = yuyv_frame->data[(i * yuyv_frame->width + j + 1) * 2 + 1];

            // YUV to RGB conversion (simplified)
            int r1 = y1 + 1.13983 * (v - 128);
            int g1 = y1 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            int b1 = y1 + 2.03211 * (u - 128);

            int r2 = y2 + 1.13983 * (v - 128);
            int g2 = y2 - 0.39465 * (u - 128) - 0.58060 * (v - 128);
            int b2 = y2 + 2.03211 * (u - 128);

            // Clamp to 0-255
            r1 = (r1 < 0) ? 0 : ((r1 > 255) ? 255 : r1);
            g1 = (g1 < 0) ? 0 : ((g1 > 255) ? 255 : g1);
            b1 = (b1 < 0) ? 0 : ((b1 > 255) ? 255 : b1);

            r2 = (r2 < 0) ? 0 : ((r2 > 255) ? 255 : r2);
            g2 = (g2 < 0) ? 0 : ((g2 > 255) ? 255 : g2);
            b2 = (b2 < 0) ? 0 : ((b2 > 255) ? 255 : b2);

            rgb_frame->data[(i * rgb_frame->width + j) * 3 + 0] = (unsigned char)r1;
            rgb_frame->data[(i * rgb_frame->width + j) * 3 + 1] = (unsigned char)g1;
            rgb_frame->data[(i * rgb_frame->width + j) * 3 + 2] = (unsigned char)b1;

            rgb_frame->data[(i * rgb_frame->width + j + 1) * 3 + 0] = (unsigned char)r2;
            rgb_frame->data[(i * rgb_frame->width + j + 1) * 3 + 1] = (unsigned char)g2;
            rgb_frame->data[(i * rgb_frame->width + j + 1) * 3 + 2] = (unsigned char)b2;
        }
    }
}

// Function to apply box blur
void apply_box_blur(const Image *input_frame, Image *output_frame) {
    output_frame->width = input_frame->width;
    output_frame->height = input_frame->height;
    output_frame->channels = input_frame->channels;
    output_frame->data = (unsigned char *)malloc(output_frame->width * output_frame->height * output_frame->channels);

    if (output_frame->data == NULL) {
        fprintf(stderr, "Error allocating memory for blurred frame\n");
        return;
    }

    for (int i = 0; i < output_frame->height; i++) {
        for (int j = 0; j < output_frame->width; j++) {
            // Clamp indices to the image boundary
            int x1 = (j - BLUR_RADIUS < 0) ? 0 : (j - BLUR_RADIUS);
            int x2 = (j + BLUR_RADIUS >= output_frame->width) ? output_frame->width - 1 : (j + BLUR_RADIUS);
            int y1 = (i - BLUR_RADIUS < 0) ? 0 : (i - BLUR_RADIUS);
            int y2 = (i + BLUR_RADIUS >= output_frame->height) ? output_frame->height - 1 : (i + BLUR_RADIUS);

            // Calculate the average of the surrounding pixels
            unsigned long r_sum = 0, g_sum = 0, b_sum = 0;
            int count = 0;
            for (int y = y1; y <= y2; y++) {
                for (int x = x1; x <= x2; x++) {
                    r_sum += input_frame->data[(y * input_frame->width + x) * input_frame->channels + 0];
                    g_sum += input_frame->data[(y * input_frame->width + x) * input_frame->channels + 1];
                    b_sum += input_frame->data[(y * input_frame->width + x) * input_frame->channels + 2];
                    count++;
                }
            }

            // Average the color values
            unsigned char r = (unsigned char)(r_sum / count);
            unsigned char g = (unsigned char)(g_sum / count);
            unsigned char b = (unsigned char)(b_sum / count);

            // Assign the averaged color to the output pixel
            output_frame->data[(i * output_frame->width + j) * output_frame->channels + 0] = r;
            output_frame->data[(i * output_frame->width + j) * output_frame->channels + 1] = g;
            output_frame->data[(i * output_frame->width + j) * output_frame->channels + 2] = b;
        }
    }
}

// Function to save as JPEG using libjpeg
int save_as_jpeg(const Image *image, const char *filename) {
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    FILE *outfile;
    JSAMPROW row_pointer[1];
    int row_stride;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    if ((outfile = fopen(filename, "wb")) == NULL) {
        fprintf(stderr, "Error opening %s for writing: %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }
    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width = image->width;
    cinfo.image_height = image->height;
    cinfo.input_components = image->channels;
    cinfo.in_color_space = JCS_RGB; // Assuming RGB24

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUALITY, TRUE);

    jpeg_start_compress(&cinfo, TRUE);

    row_stride = image->width * image->channels;

    while (cinfo.next_scanline < cinfo.image_height) {
        row_pointer[0] = &image->data[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row_pointer, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize the video device
    video_fd = init_video_device(VIDEO_DEVICE);
    if (video_fd == -1) {
        return 1;
    }

    // Allocate buffers
    void *buffers[2];
    if (allocate_buffers(video_fd, 2) == -1) {
        close_video_device(video_fd);
        return 1;
    }

    // Map buffers
    if (map_buffers(video_fd, buffers, 2) == -1) {
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        return 1;
    }

    // Queue buffers
    if (queue_buffers(video_fd, buffers, 2) == -1) {
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        return 1;
    }

    // Start streaming
    if (start_streaming(video_fd) == -1) {
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        return 1;
    }

    // Capture a frame
    current_frame = (Image *)malloc(sizeof(Image));
    if (current_frame == NULL) {
        fprintf(stderr, "Error allocating memory for current frame\n");
        stop_streaming(video_fd);
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        return 1;
    }

    if (capture_frame(video_fd, buffers, 2, current_frame) == -1) {
        stop_streaming(video_fd);
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        free(current_frame);
        return 1;
    }

    // Convert to RGB24
    blurred_frame = (Image *)malloc(sizeof(Image));
    if (blurred_frame == NULL) {
        fprintf(stderr, "Error allocating memory for blurred frame\n");
        stop_streaming(video_fd);
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        free(current_frame);
        return 1;
    }

    yuyv_to_rgb24(current_frame, blurred_frame);

    // Apply box blur
    Image *blurred_frame_blurred = (Image *)malloc(sizeof(Image));
    if (blurred_frame_blurred == NULL) {
        fprintf(stderr, "Error allocating memory for blurred frame\n");
        stop_streaming(video_fd);
        unmap_buffers(buffers, 2);
        free_buffers(video_fd, 2);
        close_video_device(video_fd);
        free(current_frame);
        free(blurred_frame);
        return 1;
    }

    apply_box_blur(blurred_frame, blurred_frame_blurred);

    // Save as JPEG
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (save_as_jpeg(blurred_frame_blurred, filename) == -1) {
        fprintf(stderr, "Error saving JPEG\n");
    }

    // Clean up
    stop_streaming(video_fd);
    unmap_buffers(buffers, 2);
    free_buffers(video_fd, 2);
    close_video_device(video_fd);
    free(current_frame->data);
    free(current_frame);
    free(blurred_frame->data);
    free(blurred_frame);
    free(blurred_frame_blurred->data);
    free(blurred_frame_blurred);

    return 0;
}

