#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NAME "/dev/video0"

// Structure to hold camera capabilities
typedef struct {
    int width;
    int height;
    int fps;
    int autofocus;
} camera_capabilities_t;

// Function to open the video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR); // Open in read/write mode
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to query camera capabilities
int query_capabilities(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    printf("Driver: %s\n", cap.driver);
    printf("Card: %s\n", cap.card);
    printf("Bus Info: %s\n", cap.bus_info);
    printf("Version: %u\n", cap.version);
    printf("Capabilities: %08x\n", cap.capabilities);

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    return 0;
}

// Function to enumerate frame sizes
int enumerate_frame_sizes(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_frmsizeenum frame_size;
    memset(&frame_size, 0, sizeof(frame_size));
    frame_size.index = 0;

    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, &frame_size) == 0) {
        if (frame_size.pixel_format == V4L2_PIX_FMT_YUYV) {
            printf("  Width: %d, Height: %d\n", frame_size.discrete.width, frame_size.discrete.height);
            capabilities->width = frame_size.discrete.width;
            capabilities->height = frame_size.discrete.height;
        }
        frame_size.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1;
    }

    return 0;
}

// Function to enumerate frame intervals
int enumerate_frame_intervals(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_frmivalenum frame_interval;
    memset(&frame_interval, 0, sizeof(frame_interval));
    frame_interval.index = 0;
    frame_interval.pixel_format = V4L2_PIX_FMT_YUYV;
    frame_interval.width = capabilities->width;
    frame_interval.height = capabilities->height;

    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, &frame_interval) == 0) {
        printf("  FPS: %d/%d\n", frame_interval.discrete.numerator, frame_interval.discrete.denominator);
        capabilities->fps = frame_interval.discrete.numerator / frame_interval.discrete.denominator;
        frame_interval.index++;
    }

    if (errno != EINVAL) {
        perror("Error enumerating frame intervals");
        return -1;
    }

    return 0;
}

// Function to check for autofocus support
int check_autofocus(int fd, camera_capabilities_t *capabilities) {
    struct v4l2_queryctrl query_ctrl;
    memset(&query_ctrl, 0, sizeof(query_ctrl));
    query_ctrl.id = V4L2_CID_FOCUS_AUTO;

    if (ioctl(fd, VIDIOC_QUERYCTRL, &query_ctrl) == 0) {
        printf("  Autofocus supported\n");
        capabilities->autofocus = 1;
    } else {
        printf("  Autofocus not supported\n");
        capabilities->autofocus = 0;
    }

    return 0;
}

int main() {
    int fd;
    camera_capabilities_t capabilities = {0, 0, 0, 0};

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Query capabilities
    if (query_capabilities(fd, &capabilities) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Enumerate frame sizes
    if (enumerate_frame_sizes(fd, &capabilities) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Enumerate frame intervals
    if (enumerate_frame_intervals(fd, &capabilities) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Check for autofocus support
    if (check_autofocus(fd, &capabilities) < 0) {
        close(fd);
        return EXIT_FAILURE;
    }

    // Close the device
    close(fd);

    printf("\nCamera Capabilities:\n");
    printf("  Resolution: %dx%d\n", capabilities.width, capabilities.height);
    printf("  Frame Rate: %d fps\n", capabilities.fps);
    printf("  Autofocus: %s\n", capabilities.autofocus ? "Yes" : "No");

    return EXIT_SUCCESS;
}

