#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <errno.h>
#include <pigpio.h>
#include <curl/curl.h>
#include <jansson.h>

#define GPIO_PIN 17
#define DEBOUNCE_TIME 2000 // milliseconds
#define CAPTURE_DIR "motion_captures"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define IMAGE_QUALITY 85

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;

// Structure to hold program configuration
typedef struct {
    char *server_ip;
    int server_port;
} ProgramConfig;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_image(char *filename);
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port);
void signal_handler(int signal);
char* get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
    }
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read the PIR sensor
int read_pir_sensor() {
    return gpioRead(GPIO_PIN);
}

// Function to capture an image using libcamera-still
int capture_image(char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "libcamera-still -o %s --width %d --height %d --quality %d", filename, IMAGE_WIDTH, IMAGE_HEIGHT, IMAGE_QUALITY);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing libcamera-still command: %s\n", strerror(errno));
        return -1;
    } else if (WEXITSTATUS(status) != 0) {
        fprintf(stderr, "libcamera-still command failed with exit status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Function to send data to the server using libcurl
int send_data(const char *filename, const char *timestamp, int motion_status, int gpio_pin, const char *server_ip, int server_port) {
    CURL *curl;
    CURLcode res;
    char json_string[512];

    json_t *root = json_object();
    json_object_set_new(root, "filename", json_string_nocheck(filename));
    json_object_set_new(root, "timestamp", json_string_nocheck(timestamp));
    json_object_set_new(root, "motion_status", json_integer(motion_status));
    json_object_set_new(root, "gpio_pin", json_integer(gpio_pin));

    json_string_t json_str = json_dumps(root, JSON_REAL_PRECISION(10));
    strncpy(json_string, json_str, sizeof(json_string) - 1);
    json_decref(root);
    json_free(json_str);

    curl_global_init(CURL_GLOBAL_ALL);
    curl = curl_easy_init();
    if (curl) {
        char url[256];
        snprintf(url, sizeof(url), "http://%s:%d/upload", server_ip, server_port);

        curl_easy_setopt(curl, CURLOPT_URL, url);
        curl_easy_setopt(curl, CURLOPT_POST, 1L);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
        curl_easy_setopt(curl, CURLOPT_POSTFIELDSIZE, (long)strlen(json_string));

        res = curl_easy_perform(curl);
        if (res != CURLE_OK) {
            fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
        }

        curl_easy_cleanup(curl);
    } else {
        fprintf(stderr, "curl_easy_init() failed\n");
        curl_global_cleanup();
        return -1;
    }
    curl_global_cleanup();
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp(char *timestamp_buffer, size_t buffer_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_buffer;
}

int main(int argc, char *argv[]) {
    ProgramConfig config;

    if (argc != 3) {
        fprintf(stderr, "Usage: %s <server_ip> <server_port>\n", argv[0]);
        return 1;
    }

    config.server_ip = argv[1];
    config.server_port = atoi(argv[2]);

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Create the capture directory if it doesn't exist
    if (mkdir(CAPTURE_DIR, 0777) == -1 && errno != EEXIST) {
        fprintf(stderr, "Error creating directory %s: %s\n", CAPTURE_DIR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    int last_motion_state = 0;
    unsigned long last_motion_time = 0;

    while (program_running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected && !last_motion_state) {
            // Motion detected
            unsigned long current_time = gpioTick();
            if (current_time - last_motion_time > DEBOUNCE_TIME * 1000) {
                char filename[256];
                char timestamp[32];
                get_iso8601_timestamp(timestamp, sizeof(timestamp));

                snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

                if (capture_image(filename) == 0) {
                    fprintf(stderr, "Motion detected at %s, image captured as %s\n", timestamp, filename);
                    if (send_data(filename, timestamp, 1, GPIO_PIN, config.server_ip, config.server_port) != 0) {
                        fprintf(stderr, "Failed to send data to server\n");
                    }
                } else {
                    fprintf(stderr, "Failed to capture image\n");
                }
                last_motion_time = current_time;
            }
        }

        last_motion_state = motion_detected;
        gpioDelay(100); // Check every 100 ms
    }

    // Clean up
    gpioTerminate();
    return 0;
}

