// Configuration
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IMAGES_DIR "/home/pi/images"
#define LOG_FILE "/home/pi/motion_capture.log"
#define DEBOUNCE_DELAY_MS 50
#define CAPTURE_TIMEOUT_MS 2000
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define JPEG_QUALITY 85

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
void cleanup_gpio(void);
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int sig);
char* generate_filename(void);

// Signal handler
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        log_event("Received signal, exiting...");
        terminate = 1;
    }
}

// Initialize GPIO
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "motion_capture";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        perror("Error requesting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Cleanup GPIO
void cleanup_gpio(void) {
    if (line) {
        gpiod_line_release(line);
