#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <sys/time.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <stdint.h>

#define DEVICE_NAME "/dev/video0"
#define CAPTURE_WIDTH 640
#define CAPTURE_HEIGHT 480
#define CROP_WIDTH 200
#define CROP_HEIGHT 150
#define CROP_X 100
#define CROP_Y 50
#define FRAME_FORMAT V4L2_PIX_FMT_YUYV

// Structure to hold camera information
typedef struct {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;
    void *buffer;
    size_t buffer_size;
} camera_t;

// Global camera instance
camera_t camera;

// Signal handler for Ctrl+C
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Caught signal %d, cleaning up...\n", signum);
        // Unmap the buffer
        if (camera.buffer != NULL && camera.buffer_size > 0) {
            if (munmap(camera.buffer, camera.buffer_size) == -1) {
                perror("munmap failed");
            }
        }

        // Close the device
        if (camera.fd != -1) {
            close(camera.fd);
        }

        exit(EXIT_SUCCESS);
    }
}

// Function to initialize the camera
int init_camera(camera_t *camera) {
    camera->fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (camera->fd == -1) {
        perror("Error opening device");
        return -1;
    }

    // Query capabilities
    if (ioctl(camera->fd, VIDIOC_QUERYCAP, &camera->cap) == -1) {
        perror("Error querying capabilities");
        close(camera->fd);
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: %s is not a video capture device\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    if (!(camera->cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: %s does not support streaming I/O\n", DEVICE_NAME);
        close(camera->fd);
        return -1;
    }

    // Set format
    camera->fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->fmt.fmt.pix.width = CAPTURE_WIDTH;
    camera->fmt.fmt.pix.height = CAPTURE_HEIGHT;
    camera->fmt.fmt.pix.pixelformat = FRAME_FORMAT;
    camera->fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(camera->fd, VIDIOC_S_FMT, &camera->fmt) == -1) {
        perror("Error setting format");
        close(camera->fd);
        return -1;
    }

    // Request buffers
    camera->req.count = 1; // Single buffer
    camera->req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera->fd, VIDIOC_REQBUFS, &camera->req) == -1) {
        perror("Error requesting buffers");
        close(camera->fd);
        return -1;
    }

    // Query buffer
    camera->buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    camera->buf.memory = V4L2_MEMORY_MMAP;
    camera->buf.index = 0;

    if (ioctl(camera->fd, VIDIOC_QUERYBUF, &camera->buf) == -1) {
        perror("Error querying buffer");
        close(camera->fd);
        return -1;
    }

    camera->buffer_size = camera->buf.length;
    camera->buffer = mmap(NULL, camera->buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, camera->fd, camera->buf.m.offset);
    if (camera->buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        close(camera->fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame(camera_t *camera) {
    fd_set fds;
    struct timeval tv;
    int r;

    // Queue the buffer
    if (ioctl(camera->fd, VIDIOC_QBUF, &camera->buf) == -1) {
        perror("Error queuing buffer");
        return -1;
    }

    // Start streaming
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera->fd, VIDIOC_STREAMON, &type) == -1) {
        perror("Error starting stream");
        return -1;
    }

    // Wait for frame with timeout
    FD_ZERO(&fds);
    FD_SET(camera->fd, &fds);

    tv.tv_sec = 2; // Timeout of 2 seconds
    tv.tv_usec = 0;

    r = select(camera->fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("Error during select");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout waiting for frame\n");
        return -1;
    }

    // Dequeue the buffer
    if (ioctl(camera->fd, VIDIOC_DQBUF, &camera->buf) == -1) {
        perror("Error dequeuing buffer");
        return -1;
    }

    // Verify frame dimensions
    if (camera->buf.bytesused != camera->buffer_size) {
        fprintf(stderr, "Error: Captured frame size mismatch (expected %zu, got %u)\n", camera->buffer_size, camera->buf.bytesused);
        return -1;
    }

    return 0;
}

// Function to crop the frame
int crop_frame(camera_t *camera, unsigned char *cropped_frame) {
    unsigned char *src = (unsigned char *)camera->buffer;
    unsigned char *dst = cropped_frame;
    int src_row_size = CAPTURE_WIDTH * 2; // YUYV
    int dst_row_size = CROP_WIDTH * 2;
    int src_offset, dst_offset;

    for (int y = 0; y < CROP_HEIGHT; y++) {
        src_offset = (CROP_Y + y) * src_row_size + (CROP_X * 2);
        dst_offset = y * dst_row_size;

        memcpy(dst + dst_offset, src + src_offset, dst_row_size);
    }

    return 0;
}

// Function to save the cropped frame to a file
int save_frame(const unsigned char *cropped_frame) {
    FILE *fp = fopen("cropped.yuv", "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }

    size_t bytes_written = fwrite(cropped_frame, 1, CROP_WIDTH * CROP_HEIGHT * 2, fp);
    if (bytes_written != CROP_WIDTH * CROP_HEIGHT * 2) {
        perror("Error writing to file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize camera
    if (init_camera(&camera) == -1) {
        fprintf(stderr, "Camera initialization failed\n");
        return EXIT_FAILURE;
    }

    // Allocate memory for cropped frame
    unsigned char *cropped_frame = (unsigned char *)malloc(CROP_WIDTH * CROP_HEIGHT * 2);
    if (cropped_frame == NULL) {
        perror("Error allocating memory for cropped frame");
        close(camera.fd);
        munmap(camera.buffer, camera.buffer_size);
        return EXIT_FAILURE;
    }

    // Capture frame
    if (capture_frame(&camera) == -1) {
        fprintf(stderr, "Frame capture failed\n");
        free(cropped_frame);
        close(camera.fd);
        munmap(camera.buffer, camera.buffer_size);
        return EXIT_FAILURE;
    }

    // Crop frame
    if (crop_frame(&camera, cropped_frame) == -1) {
        fprintf(stderr, "Frame cropping failed\n");
        free(cropped_frame);
        close(camera.fd);
        munmap(camera.buffer, camera.buffer_size);
        return EXIT_FAILURE;
    }

    // Save frame
    if (save_frame(cropped_frame) == -1) {
        fprintf(stderr, "Frame saving failed\n");
        free(cropped_frame);
        close(camera.fd);
        munmap(camera.buffer, camera.buffer_size);
        return EXIT_FAILURE;
    }

    printf("Frame cropped and saved successfully\n");

    // Clean up
    free(cropped_frame);
    close(camera.fd);
    munmap(camera.buffer, camera.buffer_size);

    return EXIT_SUCCESS;
}

