#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for pan and tilt servos
#define PAN_GPIO 17
#define TILT_GPIO 18

// Define neutral angles (90 degrees)
#define NEUTRAL_PAN 90
#define NEUTRAL_TILT 90

// Define PWM frequency (50 Hz)
#define PWM_FREQUENCY 50

// Define minimum and maximum angles (0 to 180 degrees)
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define minimum and maximum pulse widths (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define angle increment (5 degrees)
#define ANGLE_INCREMENT 5

// Global variables to store current angles
int current_pan_angle = NEUTRAL_PAN;
int current_tilt_angle = NEUTRAL_TILT;

// Function prototypes
int angle_to_pulse_width(int angle);
int set_servo_angle(int gpio, int angle);
void handle_input(char input);
void signal_handler(int signal);

