        case 'n': // Neutral
            current_pan_angle = NEUTRAL_PAN;
            current_tilt_angle = NEUTRAL_TILT;
            break;
        case 'q': // Quit
            set_servo_angle(PAN_GPIO, NEUTRAL_PAN);
            set_servo_angle(TILT_GPIO, NEUTRAL_TILT);
            gpioTerminate();
            exit(0);
            break;
        default:
            fprintf(stderr, "Error: Invalid input: %c\n", input);
            break;
    }

    // Set servo angles
    if (set_servo_angle(PAN_GPIO, current_pan_angle) != 0) {
