    display_text(x, y, buffer);
}

// Read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = -1;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        handle_error("Failed to open temperature file");
        return -1;
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        handle_error("Failed to read temperature from file");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp / 1000; // Convert to Celsius
}

// Calculate CPU usage percentage
float calculate_cpu_usage(unsigned long long user, unsigned long long nice, unsigned long long system, unsigned long long idle, unsigned long long iowait, unsigned long long irq, unsigned long long softirq, unsigned long long steal, unsigned long long guest, unsigned long long guest_nice) {
    unsigned long long prev_idle = idle + iowait;
    unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
    unsigned long long prev_total = prev_idle + prev_non_idle;

    // Simulate a delay to read the next stats
    sleep(1);

    FILE *fp;
    unsigned long long curr_user, curr_nice, curr_system, curr_idle, curr_iowait, curr_irq, curr_softirq, curr_steal, curr_guest, curr_guest_nice;

    fp = fopen(STAT_FILE, "r");
    if (fp == NULL) {
        handle_error("Failed to open stat file");
        return -1.0;
    }

    if (fscanf(fp, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu %llu %llu",
               &curr_user, &curr_nice, &curr_system, &curr_idle, &curr_iowait, &curr_irq, &curr_softirq, &curr_steal, &curr_guest, &curr_guest_nice) != 10) {
        handle_error("Failed to read CPU stats from file");
        fclose(fp);
        return -1.0;
    }
    fclose(fp);

    unsigned long long curr_idle = curr_idle + curr_iowait;
    unsigned long long curr_non_idle = curr_user + curr_nice + curr_system + curr_irq + curr_softirq + curr_steal;
    unsigned long long curr_total = curr_idle + curr_non_idle;

    unsigned long long totald = curr_total - prev_total;
    unsigned long long idled = curr_idle - prev_idle;

    float cpu_usage = (float)(totald - idled) / totald * 100.0;

    return cpu_usage;
}

