// Helper function to write a command to the SSD1306
void ssd1306_command(unsigned char command) {
    char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        handle_error("I2C write command failed");
    }
}

// Helper function to write data to the SSD1306
void ssd1306_data(unsigned char data) {
    char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        handle_error("I2C write data failed");
    }
}

// Initialize the SSD1306 OLED display
void ssd1306_init() {
    ssd1306_command(0xAE); // Display off
    ssd1306_command(0xD5); // Set display clock divide ratio/oscillator frequency
    ssd1306_command(0x80); // --ratio
    ssd1306_command(0xA8); // Set multiplex ratio
    ssd1306_command(0x3F); // --ratio
    ssd1306_command(0xD3); // Set display offset
    ssd1306_command(0x00); // --offset
    ssd1306_command(0x40); // Set start line address
    ssd1306_command(0x8D); // Charge pump setting
    ssd1306_command(0x14); // --enable
    ssd1306_command(0x20); // Set memory addressing mode
    ssd1306_command(0x00); // --horizontal addressing mode
    ssd1306_command(0xA1); // Set segment re-map
    ssd1306_command(0xC8); // Set COM output scan direction
    ssd1306_command(0xDA); // Set COM pins hardware configuration
    ssd1306_command(0x12); // --configuration
    ssd1306_command(0x81); // Set contrast control
    ssd1306_command(0xCF); // --contrast
    ssd1306_command(0xD9); // Set pre-charge period
    ssd1306_command(0xF1); // --period
    ssd1306_command(0xDB); // Set VCOM deselect level
    ssd1306_command(0x40); // --level
    ssd1306_command(0xA4); // Display all points off
    ssd1306_command(0xA6); // Set normal display
    ssd1306_command(0xAF); // Display on
}

// Clear the display buffer
void display_clear() {
    for (int i = 0; i < SCREEN_WIDTH * (SCREEN_HEIGHT / 8); i++) {
        ssd1306_data(0x00);
    }
}

// Display text at the specified coordinates
void display_text(int x, int y, const char *text) {
    int text_len = strlen(text);
    for (int i = 0; i < text_len; i++) {
        char c = text[i];
        if (c >= ' ' && c <= '~') {
            int char_index = c - ' ';
            for (int j = 0; j < FONT_HEIGHT; j++) {
                unsigned char line = font[char_index][j];
                for (int k = 0; k < FONT_WIDTH; k++) {
                    if ((line >> (FONT_WIDTH - k - 1)) & 0x01) {
                        // Calculate the pixel position on the screen
                        int pixel_x = x + i * FONT_WIDTH + k;
                        int pixel_y = y + j;

                        // Check if the pixel is within the display bounds
                        if (pixel_x >= 0 && pixel_x < SCREEN_WIDTH && pixel_y >= 0 && pixel_y < SCREEN_HEIGHT) {
                            // Calculate the byte and bit position within the display buffer
                            int byte_index = pixel_x + (pixel_y / 8) * SCREEN_WIDTH;
                            int bit_index = pixel_y % 8;

                            // Set the pixel in the display buffer
                            char buf[2];
                            buf[0] = 0x40; // Data byte
                            buf[1] = 0x00 | (1 << bit_index); // Set the bit
                            ssd1306_command(0xB0 + (pixel_y / 8)); // Set page address
                            ssd1306_command(0x00 + (pixel_x & 0x0F)); // Set lower column address
                            ssd1306_command(0x10 + (pixel_x >> 4)); // Set higher column address
                            if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
                                handle_error("I2C write data failed");
                            }
                        }
                    }
                }
            }
        }
    }
}

// Display a number at the specified coordinates
void display_number(int x, int y, int number) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "%d", number);
    display_text(x, y, buffer);
}

