#include <unistd.h>
#include <time.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define LCD_RS 25
#define LCD_EN 24
#define LCD_D4 23
#define LCD_D5 22
#define LCD_D6 21
#define LCD_D7 14

// Define I2C parameters
#define I2C_BUS 1
#define LCD_ADDR 0x27

// Define pulse counting parameters
#define PULSES_PER_LITER 450.0
#define PULSE_WINDOW_MS 1000

// Global variables
volatile int pulse_count = 0;
double flow_rate = 0.0;
double total_volume = 0.0;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user);
void calculate_flow_rate();
void update_lcd();
void signal_handler(int signal);

// Callback function for pulse counting
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused
    pulse_count++;
}

// Function to calculate flow rate
void calculate_flow_rate()
{
    flow_rate = (double)pulse_count / PULSES_PER_LITER * 60000.0 / PULSE_WINDOW_MS; // LPM
    total_volume += flow_rate / 60.0; // Liters
    pulse_count = 0;
}

// Function to update LCD display
void update_lcd()
{
    char buffer[32];
    int result;

    // Clear LCD
    result = i2cWriteByteData(i2c_handle, 0x01, 0x02); // Clear display command
    if (result < 0) {
        fprintf(stderr, "Error clearing LCD: %d\n", result);
        return;
    }
    gpioDelay(2); // Delay for clear command

    // Set cursor position
    result = i2cWriteByteData(i2c_handle, 0x02, 0x00); // Set cursor position to 0,0
    if (result < 0) {
        fprintf(stderr, "Error setting cursor position: %d\n", result);
        return;
    }

    // Flow Rate
    sprintf(buffer, "Flow: %.2f LPM", flow_rate);
    for (int i = 0; i < 16; i++) {
        result = i2cWriteByteData(i2c_handle, 0x40, buffer[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to LCD (flow): %d\n", result);
            return;
        }
    }

    // Total Volume
    sprintf(buffer, "Total: %.2f L", total_volume);
    for (int i = 0; i < 16; i++) {
        result = i2cWriteByteData(i2c_handle, 0x40, buffer[i]);
        if (result < 0) {
            fprintf(stderr, "Error writing to LCD (volume): %d\n", result);
            return;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LCD_RS, PI_OUTPUT);
    gpioSetMode(LCD_EN, PI_OUTPUT);
    gpioSetMode(LCD_D4, PI_OUTPUT);
    gpioSetMode(LCD_D5, PI_OUTPUT);
    gpioSetMode(LCD_D6, PI_OUTPUT);
    gpioSetMode(LCD_D7, PI_OUTPUT);

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0)
    {
        fprintf(stderr, "I2C initialisation failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD (basic initialization sequence)
    gpioDelay(50); // Wait for LCD to power up
    i2cWriteByteData(i2c_handle, 0x00, 0x33); // Initialize
    gpioDelay(5);  // Delay
    i2cWriteByteData(i2c_handle, 0x00, 0x32); // Initialize
    gpioDelay(5);  // Delay
    i2cWriteByteData(i2c_handle, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    gpioDelay(5);  // Delay
    i2cWriteByteData(i2c_handle, 0x00, 0x0C); // Display on, cursor off, blink off
    gpioDelay(5);  // Delay
    i2cWriteByteData(i2c_handle, 0x00, 0x06); // Increment cursor, no shift
    gpioDelay(5);  // Delay
    i2cWriteByteData(i2c_handle, 0x00, 0x01); // Clear display
    gpioDelay(2);  // Delay

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up pulse counting callback
    gpioSetAlertFuncEx(FLOW_SENSOR_PIN, pulse_callback, NULL);

    // Main loop
    while (1)
    {
        calculate_flow_rate();
        update_lcd();
        printf("Flow Rate: %.2f LPM, Total Volume: %.2f L\n", flow_rate, total_volume);
        sleep(1);
    }

    return 0;
}

