#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Configuration
#define I2C_ADDR 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ANEMOMETER_GPIO 17
#define WIND_VANE_CHANNEL 0
#define WIND_SPEED_SAMPLE_INTERVAL_MS 500
#define WIND_DIRECTION_SAMPLE_INTERVAL_MS 1000
#define WIND_VANE_STUCK_THRESHOLD 10
#define WIND_VANE_STUCK_TIMEOUT_MS 5000
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
static volatile int anemometer_pulses = 0;
static volatile int wind_vane_value = 0;
static volatile int wind_vane_stuck_count = 0;
static volatile int running = 1;
static int i2c_handle = -1;
static int spi_handle = -1;

// LCD functions
int lcd_init(int i2c_handle);
void lcd_clear(int i2c_handle);
void lcd_set_cursor(int i2c_handle, int row, int col);
void lcd_print(int i2c_handle, const char *str);

// Wind speed and direction calculation
float calculate_wind_speed(int pulses, int interval_ms);
float calculate_wind_direction(int adc_value);

// Sensor reading functions
int read_wind_vane(int spi_handle);

// Signal handler
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, I2C_ADDR, 0); // Bus 1, address 0x27, no flags
    if (i2c_handle < 0)
    {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    if (lcd_init(i2c_handle) != 0)
    {
        fprintf(stderr, "LCD initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open SPI bus
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Channel 0, 1 MHz, mode 0
    if (spi_handle < 0)
    {
        fprintf(stderr, "Failed to open SPI bus: %d\n", spi_handle);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up interrupt for anemometer
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetISRFuncEx(ANEMOMETER_GPIO, RISING_EDGE, 0, anemometer_interrupt_handler, NULL);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running)
    {
        // Calculate wind speed
        float wind_speed = calculate_wind_speed(anemometer_pulses, WIND_SPEED_SAMPLE_INTERVAL_MS);
        anemometer_pulses = 0; // Reset pulse count

        // Read wind vane
        int new_wind_vane_value = read_wind_vane(spi_handle);

        // Check for stuck wind vane
        if (new_wind_vane_value == wind_vane_value)
        {
            wind_vane_stuck_count++;
            if (wind_vane_stuck_count > WIND_VANE_STUCK_TIMEOUT_MS / WIND_DIRECTION_SAMPLE_INTERVAL_MS)
            {
                fprintf(stderr, "Wind vane stuck at %d for %d ms\n", wind_vane_value, WIND_VANE_STUCK_TIMEOUT_MS);
                wind_vane_value = -1; // Indicate stuck
            }
        }
        else
        {
            wind_vane_stuck_count = 0;
            wind_vane_value = new_wind_vane_value;
        }

        // Calculate wind direction
        float wind_direction = calculate_wind_direction(wind_vane_value);

        // Display data on LCD
        char speed_str[17];
        char direction_str[17];

        snprintf(speed_str, sizeof(speed_str), "Speed: %.1f m/s", wind_speed);
        snprintf(direction_str, sizeof(direction_str), "Dir: %.0f deg", wind_direction);

        lcd_clear(i2c_handle);
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_print(i2c_handle, speed_str);
        lcd_set_cursor(i2c_handle, 1, 0);
        lcd_print(i2c_handle, direction_str);

        // Wait for next sample
        gpioDelay(WIND_DIRECTION_SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup
    i2cClose(i2c_handle);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// LCD initialization function
int lcd_init(int i2c_handle)
{
    // Initialize LCD (PCF8574 specific initialization sequence)
    char init_sequence[] = {
        0x33, // Initialize
        0x32, // Initialize
        0x06, // Cursor move direction
        0x0C, // Display on, cursor off, blink off
        0x28  // Data length, number of lines, font size
    };

    for (int i = 0; i < sizeof(init_sequence); i++)
    {
        char data[2];
        data[0] = 0x80; // Control byte: enable, data mode
        data[1] = init_sequence[i];
        if (i2cWriteDevice(i2c_handle, data, 2) != 0)
        {
            fprintf(stderr, "LCD initialization failed at step %d\n", i);
            return -1;
        }
        gpioDelay(5000); // Delay 5ms
    }

    return 0;
}

// LCD clear function
void lcd_clear(int i2c_handle)
{
    char data[3];
    data[0] = 0x80; // Control byte: enable, data mode
    data[1] = 0x01; // Clear display command
    data[2] = 0x00; // Dummy byte
    i2cWriteDevice(i2c_handle, data, 3);
    gpioDelay(2000); // Delay 2ms
}

// LCD set cursor function
void lcd_set_cursor(int i2c_handle, int row, int col)
{
    char data[3];
    data[0] = 0x80; // Control byte: enable, data mode
    data[1] = 0x80 | (row * 0x40) | col; // Set DDRAM address
    data[2] = 0x00; // Dummy byte
    i2cWriteDevice(i2c_handle, data, 3);
    gpioDelay(2000); // Delay 2ms
}

// LCD print function
void lcd_print(int i2c_handle, const char *str)
{
    char data[33]; // Maximum 32 characters + control byte
    data[0] = 0x80; // Control byte: enable, data mode
    for (int i = 0; i < strlen(str); i++)
    {
        data[2 * i + 1] = str[i];
    }
    data[2 * strlen(str) + 1] = 0x00; // Dummy byte
    i2cWriteDevice(i2c_handle, data, 2 * strlen(str) + 2);
    gpioDelay(2000); // Delay 2ms
}

// Wind speed calculation function
float calculate_wind_speed(int pulses, int interval_ms)
{
    return (float)pulses * 0.5; // m/s
}

// Wind direction calculation function
float calculate_wind_direction(int adc_value)
{
    // Map ADC value (0-1023) to angle (0-359 degrees)
    float angle = (float)adc_value / 1023.0 * 359.0;
    return angle;
}

// Wind vane reading function
int read_wind_vane(int spi_handle)
{
    char tx_buf[3];
    char rx_buf[3];

    // MCP3008 configuration: single-ended, channel 0, start bit
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | WIND_VANE_CHANNEL) << 4; // Single-ended, channel selection
    tx_buf[2] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0)
    {
        fprintf(stderr, "SPI transfer failed\n");
        return -1; // Indicate error
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Signal handler function
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Anemometer interrupt handler function
void anemometer_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data)
{
    anemometer_pulses++;
}

