#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <wiringPiI2C.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define PULSES_PER_LITER 7.5
#define FLOW_RATE_SCALE 100.0 // Scale factor for flow rate display
#define TIMEOUT_SECONDS 5
#define MAX_PULSES 1000 // Maximum number of pulses to count before timeout

// Global variables
volatile int pulse_count = 0;
int lcd_fd;

// Function prototypes
void pulse_counter(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulse_count, float pulses_per_liter);
void display_flow_rate(float flow_rate, int lcd_fd);
void signal_handler(int signal);
int lcd_init(int lcd_fd);
void lcd_clear(int lcd_fd);
void lcd_print(int lcd_fd, const char *line1, const char *line2);

// Interrupt handler for flow sensor pulses
void pulse_counter(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH) // Rising edge
    {
        pulse_count++;
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulse_count, float pulses_per_liter)
{
    return (float)pulse_count / pulses_per_liter * 60.0;
}

// Function to display flow rate on LCD1602
void display_flow_rate(float flow_rate, int lcd_fd)
{
    char line1[17] = "Flow Rate: ";
    char line2[17];
    snprintf(line2, sizeof(line2), "%.2f L/min", flow_rate * FLOW_RATE_SCALE);

    lcd_clear(lcd_fd);
    lcd_print(lcd_fd, line1, line2);
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// LCD1602 initialization function
int lcd_init(int lcd_fd)
{
    // Initialization sequence (adjust as needed for your LCD)
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x33); // Initialize
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x32); // Initialize
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x28); // 4-bit mode, 2 lines, 5x8 font
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x0C); // Display on, cursor off, blink off
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x06); // Increment cursor, no shift
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    gpioDelay(2000); // Delay for clear display
    return 0;
}

// LCD1602 clear function
void lcd_clear(int lcd_fd)
{
    wiringPiI2CWriteReg8(lcd_fd, 0x00, 0x01); // Clear display
    gpioDelay(2000); // Delay for clear display
}

// LCD1602 print function
void lcd_print(int lcd_fd, const char *line1, const char *line2)
{
    // Send string to LCD (adjust as needed for your LCD library)
    int i;
    for (i = 0; line1[i] != '\0'; i++)
    {
