#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins for rows and columns
const int rows[] = {17, 18, 27, 22, 23, 24, 25, 4};
const int cols[] = {5, 6, 12, 13, 19, 16, 26, 20};
const int num_rows = sizeof(rows) / sizeof(rows[0]);
const int num_cols = sizeof(cols) / sizeof(cols[0]);

// Define wave patterns
const int left_to_right_pattern[] = {0, 1, 2, 3, 4, 5, 6, 7};
const int right_to_left_pattern[] = {7, 6, 5, 4, 3, 2, 1, 0};

// Define scan delay in microseconds
const int scan_delay_us = 800;

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *rows_lines[8];
struct gpiod_line *cols_lines[8];

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    for (int i = 0; i < num_rows; i++) {
        gpiod_line_release(rows_lines[i]);
    }
    for (int i = 0; i < num_cols; i++) {
        gpiod_line_release(cols_lines[i]);
    }

    // Close GPIO chip
    gpiod_chip_close(chip);

    exit(0);
}

// Function to set the state of a GPIO line
int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// Function to scan the LED matrix
void scan_led_matrix(int pattern[], int num_frames)
{
    for (int frame = 0; frame < num_frames; frame++) {
        for (int row = 0; row < num_rows; row++) {
            // Set row HIGH, all columns LOW
            for (int i = 0; i < num_cols; i++) {
                if (set_gpio_value(cols_lines[i], 0) != 0) return; // Exit if error
            }
            if (set_gpio_value(rows_lines[row], 1) != 0) return; // Exit if error

            // Delay for scan_delay_us
            struct timespec delay;
            delay.tv_sec = 0;
            delay.tv_nsec = scan_delay_us * 1000; // Convert microseconds to nanoseconds
            nanosleep(&delay, NULL);

            // Set all columns HIGH, row LOW
            for (int i = 0; i < num_cols; i++) {
                if (set_gpio_value(cols_lines[i], 1) != 0) return; // Exit if error
            }
            if (set_gpio_value(rows_lines[row], 0) != 0) return; // Exit if error
        }
    }
}

int main()
{
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines for rows
    for (int i = 0; i < num_rows; i++) {
        rows_lines[i] = gpiod_chip_get_line(chip, rows[i]);
        if (!rows_lines[i]) {
            fprintf(stderr, "Error getting GPIO line for row %d: %s\n", rows[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(rows_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line for row %d as output: %s\n", rows[i], strerror(errno));
            goto cleanup;
        }
    }

    // Get GPIO lines for columns
    for (int i = 0; i < num_cols; i++) {
        cols_lines[i] = gpiod_chip_get_line(chip, cols[i]);
        if (!cols_lines[i]) {
            fprintf(stderr, "Error getting GPIO line for column %d: %s\n", cols[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(cols_lines[i], "led-matrix", 0) < 0) {
            fprintf(stderr, "Error requesting GPIO line for column %d as output: %s\n", cols[i], strerror(errno));
            goto cleanup;
        }
    }

    // Main loop: display wave patterns
    while (1) {
        printf("Displaying left-to-right wave...\n");
        scan_led_matrix(left_to_right_pattern, 10); // Display for 10 frames
        printf("Displaying right-to-left wave...\n");
        scan_led_matrix(right_to_left_pattern, 10); // Display for 10 frames
    }

cleanup:
    // Release GPIO lines
    for (int i = 0; i < num_rows; i++) {
        if (rows_lines[i]) gpiod_line_release(rows_lines[i]);
    }
    for (int i = 0; i < num_cols; i++) {
        if (cols_lines[i]) gpiod_line_release(cols_lines[i]);
    }

    // Close GPIO chip
    if (chip) gpiod_chip_close(chip);

    return 1;
}

