    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        return 1;
    }

    // Get the row lines
    for (int i = 0; i < num_rows; i++) {
        row_lines[i] = gpiod_chip_get_line(chip, row_pins[i]);
        if (!row_lines[i]) {
            fprintf(stderr, "Error getting row line %d\n", row_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(row_lines[i], "wave-matrix", 0) < 0) {
            fprintf(stderr, "Error requesting row line %d as output\n", row_pins[i]);
            goto cleanup;
        }
    }

    // Get the column lines
    for (int i = 0; i < num_cols; i++) {
        col_lines[i] = gpiod_chip_get_line(chip, col_pins[i]);
        if (!col_lines[i]) {
            fprintf(stderr, "Error getting column line %d\n", col_pins[i]);
            goto cleanup;
        }
        if (gpiod_line_request_output(col_lines[i], "wave-matrix", 1) < 0) {
            fprintf(stderr, "Error requesting column line %d as output\n", col_pins[i]);
            goto cleanup;
        }
    }

    // Main loop: display the wave pattern indefinitely
    while (1) {
        if (display_wave() < 0) {
            fprintf(stderr, "Error displaying wave\n");
            break;
        }
    }

cleanup:
    // Release all GPIO lines and close the chip
    for (int i = 0; i < num_rows; i++) {
        if (row_lines[i]) gpiod_line_release(row_lines[i]);
    }
    for (int i = 0; i < num_cols; i++) {
        if (col_lines[i]) gpiod_line_release(col_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);

    return 1;
}

