#define VL53L3CX_SYSTEM_START 0x0010
#define VL53L3CX_INTERMEASUREMENT_PERIOD 0x001E
#define VL53L3CX_TARGET_ORDER 0x0020
#define VL53L3CX_START_STOP_MEASURE 0x0040
#define VL53L3CX_RESULT_RANGE_STATUS 0x0089
#define VL53L3CX_RESULT_SPAD_NB 0x008A
#define VL53L3CX_RESULT_SIGNAL_RATE 0x008B
#define VL53L3CX_RESULT_AMBIENT_RATE 0x008C
#define VL53L3CX_RESULT_DISTANCE 0x0096

// Define the number of targets
#define NUM_TARGETS 4

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int distance[NUM_TARGETS];
    int status[NUM_TARGETS];
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
