// Function to initialize the VL53L3CX sensor
int initialize_sensor() {
    // Example initialization sequence (adjust based on datasheet)
    // This is a simplified example and may not be complete
    char data[2];
    int status;

    // Check sensor model ID
    data[0] = VL53L3CX_MODEL_ID;
    status = i2cWriteDevice(i2c_handle, data, 1);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    char model_id;
    status = i2cReadDevice(i2c_handle, &model_id, 1);
    if (status != 0) {
        fprintf(stderr, "Error reading from I2C device: %d\n", status);
        return -1;
    }

    if (model_id != 0xEA) { // Example model ID, check datasheet
        fprintf(stderr, "Error: Incorrect model ID: 0x%02X\n", model_id);
        return -1;
    }

    // Start the sensor (example)
    data[0] = VL53L3CX_SYSTEM_START;
    data[1] = 0x01; // Example value, check datasheet
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
    }

    // Set intermeasurement period (example)
    data[0] = VL53L3CX_INTERMEASUREMENT_PERIOD;
    data[1] = 0x32; // Example value, check datasheet
    status = i2cWriteDevice(i2c_handle, data, 2);
    if (status != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", status);
        return -1;
