        return -1;
    }

    printf("Sensor initialized successfully.\n");
    return 0;
}

// Function to read distance measurements from the sensor
int read_sensor_data(sensor_data_t *data) {
    char reg[1];
    char buffer[2]; // Assuming 2 bytes for distance and status
    int status;

    // Read distance and status for each target
    for (int i = 0; i < NUM_TARGETS; i++) {
        // Set register address for distance
        reg[0] = VL53L3CX_RESULT_DISTANCE + (i * 2); // Adjust based on datasheet
        status = i2cWriteDevice(i2c_handle, reg, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", status);
            return -1;
        }

        // Read distance and status
        status = i2cReadDevice(i2c_handle, buffer, 2);
        if (status != 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", status);
            return -1;
        }

        // Interpret the data (adjust based on datasheet)
        data->distance[i] = (buffer[0] << 8) | buffer[1]; // Example, might need adjustment

        // Set register address for status
        reg[0] = VL53L3CX_RESULT_RANGE_STATUS + (i * 2); // Adjust based on datasheet
        status = i2cWriteDevice(i2c_handle, reg, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", status);
            return -1;
        }

        // Read status
        status = i2cReadDevice(i2c_handle, buffer, 1);
        if (status != 0) {
            fprintf(stderr, "Error reading from I2C device: %d\n", status);
            return -1;
        }

        data->status[i] = buffer[0]; // Example, might need adjustment
    }

    return 0;
}

// Function to log the sensor data with an ISO-8601 timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s, ", timestamp);
    for (int i = 0; i < NUM_TARGETS; i++) {
        printf("Target %d: Distance = %d mm, Status = 0x%02X", i + 1, data.distance[i], data.status[i]);
        if (i < NUM_TARGETS - 1) {
            printf(", ");
        }
    }
    printf("\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 100 ms
        gpioDelay(100);
    }

