    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            if (log_data(distance) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            // Log error
            log_file = fopen(LOG_FILE, "a");
            if (log_file != NULL) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[20];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
                fprintf(log_file, "%s,-1\n", timestamp);
                fclose(log_file);
