            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);
            fprintf(log_file, "%s,ERROR,ERROR\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_MS);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

