#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define GPIO chip name
#define GPIO_CHIP "gpiochip4"

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
void control_led(int state);
void log_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
    char *gpio_chip;
    char *log_file;
} gpio_config_t;

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Control the LED state
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

// Log the event to a file
void log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s Object detected\n", timestamp);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Turn off the LED
    control_led(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Signal received (%d).  Shutting down...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    int last_sensor_state = 1; // Assume no object initially

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        // Check for falling edge (object entering range)
        if (sensor_value == 0 && last_sensor_state == 1) {
            log_event();
            control_led(1); // Turn LED on
            gpioDelay(100);   // Wait 100 ms
            control_led(0); // Turn LED off
            gpioDelay(900);   // Wait 900 ms (100 ms blink + 800 ms off)
        }

        last_sensor_state = sensor_value;
        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

