#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define HW_KEY_REGISTER 0x07
#define HW_KEY_VALUE 0x17
#define CH_LIST_REGISTER 0x4F
#define CH_LIST_VALUE 0x77 // Enable PS1 and ALS_VIS
#define MEASUREMENT_RATE_REGISTER 0x08
#define MEASUREMENT_RATE_VALUE 0x0A // Example rate
#define COMMAND_REGISTER 0x30
#define ALS_FORCE_BIT 0x06
#define PS_FORCE_BIT 0x07
#define PS1_DATA_REGISTER 0x18
#define ALS_VIS_DATA_REGISTER 0x22
#define PART_ID_REGISTER 0x00
#define PART_ID_EXPECTED 0x45

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int hw_key_register;
    int hw_key_value;
    int ch_list_register;
    int ch_list_value;
    int measurement_rate_register;
    int measurement_rate_value;
    int command_register;
    int als_force_bit;
    int ps_force_bit;
    int ps1_data_register;
    int als_vis_data_register;
    int part_id_register;
    int part_id_expected;
} sensor_config_t;

// Initialize sensor configuration
sensor_config_t sensor_config = {
    .i2c_bus = I2C_BUS,
    .i2c_address = I2C_ADDRESS,
    .hw_key_register = HW_KEY_REGISTER,
    .hw_key_value = HW_KEY_VALUE,
    .ch_list_register = CH_LIST_REGISTER,
    .ch_list_value = CH_LIST_VALUE,
    .measurement_rate_register = MEASUREMENT_RATE_REGISTER,
    .measurement_rate_value = MEASUREMENT_RATE_VALUE,
    .command_register = COMMAND_REGISTER,
    .als_force_bit = ALS_FORCE_BIT,
    .ps_force_bit = PS_FORCE_BIT,
    .ps1_data_register = PS1_DATA_REGISTER,
    .als_vis_data_register = ALS_VIS_DATA_REGISTER,
    .part_id_register = PART_ID_REGISTER,
    .part_id_expected = PART_ID_EXPECTED
};


int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(sensor_config.i2c_bus, sensor_config.i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t proximity, ambient_light;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            // Log data
            if (log_data(proximity, ambient_light) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize the Si1145 sensor
int initialize_sensor() {
    // Verify PART_ID
    int part_id = i2cReadByteData(i2c_handle, sensor_config.part_id_register);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register: %d\n", part_id);
        return 1;
    }
    if (part_id != sensor_config.part_id_expected) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", part_id, sensor_config.part_id_expected);
        return 1;
    }

    // Write HW_KEY
    int result = i2cWriteByteData(i2c_handle, sensor_config.hw_key_register, sensor_config.hw_key_value);
    if (result < 0) {
        fprintf(stderr, "Error writing HW_KEY register: %d\n", result);
        return 1;
    }

    // Write CH_LIST
    result = i2cWriteByteData(i2c_handle, sensor_config.ch_list_register, sensor_config.ch_list_value);
    if (result < 0) {
        fprintf(stderr, "Error writing CH_LIST register: %d\n", result);
        return 1;
    }

    // Write MEASUREMENT_RATE
    result = i2cWriteByteData(i2c_handle, sensor_config.measurement_rate_register, sensor_config.measurement_rate_value);
    if (result < 0) {
        fprintf(stderr, "Error writing MEASUREMENT_RATE register: %d\n", result);
        return 1;
    }

    return 0;
}

// Read proximity and ambient light data from the sensor
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
