#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 30      // ms
#define MIN_DISTANCE 2.0         // cm
#define MAX_DISTANCE 400.0       // cm

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
double measurePulseWidth();
double calculateDistance(double pulse_width);
void logDistance(double distance);
void signalHandler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int trigger_pin;
    int echo_pin;
} gpio_config_t;

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
double measurePulseWidth() {
    struct timespec start, end;
    double pulse_width = 0.0;
    int timeout_count = 0;

    // Wait for the echo pin to go high
    while (gpioRead(ECHO_PIN) == 0) {
        clock_gettime(CLOCK_MONOTONIC, &start);
        timeout_count++;
        if (timeout_count > (TIMEOUT_DURATION * 1000)) { // Check every microsecond
            return -1.0; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &start);

    // Wait for the echo pin to go low
    timeout_count = 0;
    while (gpioRead(ECHO_PIN) == 1) {
        clock_gettime(CLOCK_MONOTONIC, &end);
        timeout_count++;
        if (timeout_count > (TIMEOUT_DURATION * 1000)) { // Check every microsecond
            return -1.0; // Timeout
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    clock_gettime(CLOCK_MONOTONIC, &end);

    // Calculate the pulse width in seconds
    pulse_width = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;

    return pulse_width;
}

// Function to calculate the distance in centimeters
double calculateDistance(double pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate an error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance to a file
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(log_file, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Plant watering reminder started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        double pulse_width = measurePulseWidth();

        if (pulse_width < 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

            if (pulse_width == -1.0) {
                fprintf(log_file, "%s, Error: Timeout waiting for echo\n", timestamp);
                fflush(log_file);
            } else {
                fprintf(log_file, "%s, Error: Unknown error during measurement\n", timestamp);
                fflush(log_file);
            }
        } else {
            double distance = calculateDistance(pulse_width);
            logDistance(distance);

            if (distance >= 0 && distance < 15.0) {
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

                fprintf(log_file, "%s, Time to water the plant!\n", timestamp);
                fflush(log_file);
            }
        }

        sleep(60);
    }

    // Close the log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Plant watering reminder stopped.\n");

    return 0;
}

