#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define APDS9960_ADDR 0x39
#define PROXIMITY_THRESHOLD 200
#define LOG_FILE "color_proximity_log.csv"

// APDS9960 Registers
#define APDS9960_ID 0x92
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0xF1
#define APDS9960_CONFIG2 0x90
#define APDS9960_RED_L 0x96
#define APDS9960_RED_H 0x97
#define APDS9960_GREEN_L 0x98
#define APDS9960_GREEN_H 0x99
#define APDS9960_BLUE_L 0x9A
#define APDS9960_BLUE_H 0x9B
#define APDS9960_PROXIMITY 0x9C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity);
int log_data(uint16_t red, uint16_t green, uint16_t blue, uint8_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int initialize_sensor() {
    // Verify sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Enable the sensor
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Set ATIME
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xDB) < 0) {
        fprintf(stderr, "Error writing to ATIME register\n");
        return -1;
    }

    // Set WTIME
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xF6) < 0) {
        fprintf(stderr, "Error writing to WTIME register\n");
        return -1;
    }

    // Set PPULSE
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x87) < 0) {
        fprintf(stderr, "Error writing to PPULSE register\n");
        return -1;
    }

    // Set CONTROL
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register\n");
        return -1;
    }

    // Set CONFIG2
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint8_t *proximity) {
    int red_l, red_h, green_l, green_h, blue_l, blue_h, proximity_val;

    red_l = i2cReadByteData(i2c_handle, APDS9960_RED_L);
    red_h = i2cReadByteData(i2c_handle, APDS9960_RED_H);
    green_l = i2cReadByteData(i2c_handle, APDS9960_GREEN_L);
    green_h = i2cReadByteData(i2c_handle, APDS9960_GREEN_H);
    blue_l = i2cReadByteData(i2c_handle, APDS9960_BLUE_L);
