// Function to write a byte to a VL53L0X register
int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L0X register
int vl53l0x_read_word(int handle, uint16_t reg, uint16_t *data) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the VL53L0X sensor
int vl53l0x_init() {
    // Check sensor presence by reading the model ID
    uint8_t model_id;
    if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
        return -1;
    }

