#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0x0000
#define VL53L0X_REG_IDENTIFICATION_REVISION_ID 0x0001
#define VL53L0X_REG_ROI_CONFIG_USER_ROI_CENTRE_SPAD 0x001E
#define VL53L0X_REG_ROI_CONFIG_USER_ROI_REQUESTED_GLOBAL_XY_SIZE 0x001F
#define VL53L0X_REG_SYSRANGE_START 0x000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x014
#define VL53L0X_REG_RESULT_SPAD_NB_DETECTED 0x022
#define VL53L0X_REG_RESULT_PEAK_SIGNAL_RATE 0x024
#define VL53L0X_REG_RESULT_AMBIENT_RATE 0x026
#define VL53L0X_REG_RESULT_SIGNAL_RATE 0x028
#define VL53L0X_REG_RESULT_AMBIENT_RATE_MCPS 0x02A
#define VL53L0X_REG_RESULT_SIGNAL_RATE_MCPS 0x02C
#define VL53L0X_REG_RESULT_TOTAL_RATE_MCPS 0x02E
#define VL53L0X_REG_RESULT_DISTANCE 0x030
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR 0x00B

// GPIO pin for interrupt
#define INTERRUPT_GPIO 17

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l0x_init();
int vl53l0x_read_distance();
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint8_t status;
} sensor_data_t;

// Function to write a byte to a VL53L0X register
int vl53l0x_write_byte(int handle, uint16_t reg, uint8_t data) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = data;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L0X register
int vl53l0x_read_byte(int handle, uint16_t reg, uint8_t *data) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from a VL53L0X register
int vl53l0x_read_word(int handle, uint16_t reg, uint16_t *data) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    reg_buf[1] = reg & 0xFF;        // LSB of register address

    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    char buf[2];
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }

    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to initialize the VL53L0X sensor
int vl53l0x_init() {
    // Check sensor presence by reading the model ID
    uint8_t model_id;
    if (vl53l0x_read_byte(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading model ID\n");
