#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define CH101_ADDR 0x45
#define TRIGGER_REG 0x00
#define DISTANCE_REG_HIGH 0x01
#define DISTANCE_REG_LOW 0x02
#define SAMPLE_INTERVAL_MS 200
#define TIMEOUT_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int write_register(int handle, int reg, int value);
int read_register(int handle, int reg);
int trigger_measurement(int handle);
int read_distance(int handle);
char* get_timestamp();
int log_distance(const char *timestamp, int distance);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write to a register
int write_register(int handle, int reg, int value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Read from a register
int read_register(int handle, int reg) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Failed to read from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return result;
}

// Trigger a measurement
int trigger_measurement(int handle) {
    if (write_register(handle, TRIGGER_REG, 0x01) < 0) {
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(int handle) {
    int high_byte = read_register(handle, DISTANCE_REG_HIGH);
    int low_byte = read_register(handle, DISTANCE_REG_LOW);

    if (high_byte < 0 || low_byte < 0) {
        return -1;
    }

    return (high_byte << 8) | low_byte;
}

// Get current timestamp
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[8]; // YYYYMMDD

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y%m%d", timeinfo);
    return buffer;
}

// Log distance to file
int log_distance(const char *timestamp, int distance) {
    char log_entry[50];
    snprintf(log_entry, sizeof(log_entry), "%s, %d\n", timestamp, distance);

    if (fprintf(log_file, "%s", log_entry) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() < 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement(i2c_handle) < 0) {
            fprintf(stderr, "Measurement trigger failed\n");
        } else {
            // Wait for measurement to complete (adjust as needed)
            gpioDelay(50000); // 50 ms

            // Read distance
            int distance = read_distance(i2c_handle);
            if (distance >= 0) {
                // Get timestamp
                char *timestamp = get_timestamp();

                // Log distance
                if (log_distance(timestamp, distance) < 0) {
                    fprintf(stderr, "Failed to log distance\n");
                }

                // Print to stdout
                printf("%s, %d\n", timestamp, distance);
            } else {
                fprintf(stderr, "Failed to read distance\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Close I2C device and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

