#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x60
#define PROXIMITY_REG 0x18
#define AMBIENT_LIGHT_REG 0x16
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light);
int log_data(uint16_t proximity, uint16_t ambient_light);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data with retries
int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light) {
    int result, i;
    char buf[2];

    // Read proximity data
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_REG, buf, 2);
        if (result == 2) {
            *proximity = (buf[1] << 8) | buf[0];
            break;
        } else {
            fprintf(stderr, "Error reading proximity data (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    if (i == RETRY_COUNT) {
        fprintf(stderr, "Failed to read proximity data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Read ambient light data
    for (i = 0; i < RETRY_COUNT; ++i) {
        result = i2cReadI2CBlockData(i2c_handle, AMBIENT_LIGHT_REG, buf, 2);
        if (result == 2) {
            *ambient_light = (buf[1] << 8) | buf[0];
            break;
        } else {
            fprintf(stderr, "Error reading ambient light data (attempt %d): %d\n", i + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }
    }
    if (i == RETRY_COUNT) {
        fprintf(stderr, "Failed to read ambient light data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Log data to file
int log_data(uint16_t proximity, uint16_t ambient_light) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n", timestamp, proximity, ambient_light);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uint16_t proximity, ambient_light;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            log_data(proximity, ambient_light);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioDelay(500000); // 500 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

