// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

// Initializes the ICU-20201 sensor
int initialize_sensor(int i2c_handle) {
    int who_am_i;

    // Verify WHO_AM_I register
    who_am_i = i2cReadByteData(i2c_handle, ICU20201_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x41, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Enable continuous mode (example, adjust as needed)
    if (i2cWriteByteData(i2c_handle, ICU20201_CTRL_REG0, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG0\n");
        return -1;
    }

    printf("Sensor initialized successfully. WHO_AM_I = 0x%02X\n", who_am_i);
    return 0;
}

// Reads the distance from the ICU-20201 sensor
int read_distance(int i2c_handle) {
    int distance_msb, distance_lsb;
    int distance;

    distance_msb = i2cReadByteData(i2c_handle, ICU20201_DISTANCE_MSB);
    if (distance_msb < 0) {
        fprintf(stderr, "Error reading distance MSB: %d\n", distance_msb);
        return -1;
    }

    distance_lsb = i2cReadByteData(i2c_handle, ICU20201_DISTANCE_LSB);
    if (distance_lsb < 0) {
