#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x50

// Define the command to request a distance measurement
const uint8_t command_frame[] = {0x50, 0x0A, 0x00, 0x01};

// Define the expected header byte
#define EXPECTED_HEADER 0x50

// Define the number of samples to average
#define NUM_SAMPLES 10

// Define the intrusion threshold (in mm)
#define INTRUSION_THRESHOLD 1000

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *bus, int address);
int i2c_ioctl(int fd, int request, void *arg);
int i2c_write(int fd, const uint8_t *data, int length);
int i2c_read(int fd, uint8_t *data, int length);
int read_distance(int fd);
float calculate_average_distance(int fd, int num_samples);
void log_intrusion(float average_distance);
void signal_handler(int signal);

// Function to open the I2C bus
int i2c_open(const char *bus, int address) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to perform an I2C ioctl operation
int i2c_ioctl(int fd, int request, void *arg) {
    int result = ioctl(fd, request, arg);
    if (result < 0) {
        perror("I2C ioctl error");
        return -1;
    }
    return 0;
}

// Function to write data to the I2C bus
int i2c_write(int fd, const uint8_t *data, int length) {
    ssize_t bytes_written = write(fd, data, length);
    if (bytes_written != length) {
        perror("Error writing to I2C bus");
        return -1;
    }
    return 0;
}

// Function to read data from the I2C bus
int i2c_read(int fd, uint8_t *data, int length) {
    ssize_t bytes_read = read(fd, data, length);
    if (bytes_read != length) {
        perror("Error reading from I2C bus");
        return -1;
    }
    return 0;
}

// Function to read a distance measurement from the sensor
int read_distance(int fd) {
    uint8_t response_frame[15];
    int16_t distance;

    // Send the command frame
    if (i2c_write(fd, command_frame, sizeof(command_frame)) < 0) {
        fprintf(stderr, "Error sending command frame\n");
        return -1;
    }

    // Wait for at least 10 ms
    usleep(10000); // 10 ms

    // Read the response frame
    if (i2c_read(fd, response_frame, sizeof(response_frame)) < 0) {
        fprintf(stderr, "Error reading response frame\n");
        return -1;
    }

    // Validate the header byte
    if (response_frame[0] != EXPECTED_HEADER) {
        fprintf(stderr, "Invalid header byte: 0x%02X\n", response_frame[0]);
        return -1;
    }

    // Extract the distance from the response frame
    distance = (response_frame[11] << 8) | response_frame[12];

    return distance;
}

// Function to calculate the average distance over multiple samples
float calculate_average_distance(int fd, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        int distance = read_distance(fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance in sample %d\n", i + 1);
            return -1.0; // Indicate an error
        }
        sum += distance;
    }
    return sum / num_samples;
}

// Function to log an intrusion event
void log_intrusion(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Intrusion detected! Average distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the I2C bus
    i2c_fd = i2c_open(I2C_BUS, I2C_ADDRESS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("intrusion_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        float average_distance = calculate_average_distance(i2c_fd, NUM_SAMPLES);

        if (average_distance >= 0) {
            printf("Average distance: %.2f mm\n", average_distance);

            if (average_distance < INTRUSION_THRESHOLD) {
                log_intrusion(average_distance);
            }
        } else {
            fprintf(stderr, "Error calculating average distance. Retrying...\n");
        }

        // Delay for 100 ms
        usleep(100000);
    }

    return 0;
}

