#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L0X I2C address
#define VL53L0X_ADDR 0x29

// VL53L0X register addresses
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID  0xC0
#define VL53L0X_REG_SYSRANGE_START             0x00
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS   0x13
#define VL53L0X_REG_RESULT_RANGE_STATUS        0x14
#define VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR     0x0B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l0x();
int read_distance();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the VL53L0X sensor
int init_vl53l0x() {
    // Check sensor ID
    char id;
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &id, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }

    if (id != 0xEE) {
        fprintf(stderr, "Error: Incorrect sensor ID (0x%02X). Expected 0xEE.\n", id);
        return -1;
    }

    printf("VL53L0X sensor initialized successfully.\n");
    return 0;
}

// Read distance from the VL53L0X sensor
int read_distance() {
    char data[2];
    int distance;
    int retries = 3;

    // Start a single-shot ranging
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete with timeout
    int timeout_count = 0;
    while (1) {
        char status;
        if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status, 1) != 1) {
            fprintf(stderr, "Error reading interrupt status: %s\n", strerror(errno));
            return -1;
        }

        if (status & 0x01) {
            break; // Measurement complete
        }

        gpioDelay(1); // Wait 1 ms
        timeout_count++;
        if (timeout_count > 100) { // Timeout after 100 ms
            fprintf(stderr, "Error: Timeout waiting for measurement.\n");
            return -1;
        }
    }

    // Read distance
    if (i2cReadI2CBlockData(i2c_handle, VL53L0X_REG_RESULT_RANGE_STATUS, data, 2) != 2) {
        fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL53L0X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error clearing interrupt: %s\n", strerror(errno));
        return -1;
    }

    // Convert distance to millimeters
    distance = (data[0] << 8) | data[1];

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L0X sensor
    if (init_vl53l0x() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Distance: %d mm\n", timestamp, distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Close I2C device and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

