// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDR 0x39

// Define the registers
#define REG_CONFIG 0x18
#define REG_IRQ_STATUS 0x25
#define REG_PROX_LSB 0x2A
#define REG_PROX_MSB 0x2B

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to initialize the Si1182 sensor
int init_si1182() {
    // Enable proximity mode
    int result = i2cWriteByteData(i2c_handle, REG_CONFIG, 0x01);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read proximity data
int read_proximity() {
    int lsb, msb;
    int prox_value;

    // Read IRQ status
    int irq_status = i2cReadByteData(i2c_handle, REG_IRQ_STATUS);
    if (irq_status < 0) {
        fprintf(stderr, "Error reading IRQ status: %d\n", irq_status);
        return -1;
    }

    // Check if data is ready (bit 0 of IRQ status is set)
    if (!(irq_status & 0x01)) {
        return -2; // Data not ready
    }

    // Read proximity LSB
    lsb = i2cReadByteData(i2c_handle, REG_PROX_LSB);
    if (lsb < 0) {
        fprintf(stderr, "Error reading proximity LSB: %d\n", lsb);
        return -1;
    }

    // Read proximity MSB
    msb = i2cReadByteData(i2c_handle, REG_PROX_MSB);
    if (msb < 0) {
        fprintf(stderr, "Error reading proximity MSB: %d\n", msb);
        return -1;
    }

    // Combine LSB and MSB to get the 16-bit proximity value
    prox_value = (msb << 8) | lsb;

    return prox_value;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_si1182() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

