#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C

// Define the distance register address
#define DISTANCE_REG 0x00

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl-C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    // Verify the device is present by reading a register
    unsigned char buf[1];
    if (read(fd, buf, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device. Check if the sensor is connected.\n");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read distance data from the sensor
int read_distance(int fd) {
    unsigned char buf[2];
    int distance_mm;

    // Read 2 bytes from the distance register
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value (little-endian)
    int distance_raw = (buf[1] << 8) | buf[0];

    // Convert the raw value to millimetres (0.125 mm per count)
    distance_mm = distance_raw * 125 / 1000;

    return distance_mm;
}

int main() {
    // Register the signal handler for Ctrl-C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, MLX75030_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop to read and print distance data
    while (1) {
        int distance = read_distance(i2c_fd);
        if (distance >= 0) {
            printf("Distance: %d mm\n", distance);
        } else {
            fprintf(stderr, "Failed to read distance. Retrying...\n");
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

