#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3101_ADDR 0x44

// Define register addresses (replace with actual values from datasheet)
#define REG_CH0_DISTANCE 0x00
#define REG_AMBIENT_LIGHT 0x02
#define REG_ERROR_FLAGS 0x04

// Global variable for I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit value from the OPT3101
int read_opt3101_data(int handle, int reg) {
    int data = i2cReadWordData(handle, reg);
    if (data < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, data);
        return -1; // Indicate an error
    }
    return data;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance from channel 0
        int distance = read_opt3101_data(i2c_handle, REG_CH0_DISTANCE);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Read ambient light data
        int ambient_light = read_opt3101_data(i2c_handle, REG_AMBIENT_LIGHT);
        if (ambient_light < 0) {
            fprintf(stderr, "Error reading ambient light. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Read error flags
        int error_flags = read_opt3101_data(i2c_handle, REG_ERROR_FLAGS);
        if (error_flags < 0) {
            fprintf(stderr, "Error reading error flags. Retrying...\n");
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Print the data
        printf("Distance: %d, Ambient Light: %d, Error Flags: %d\n", distance, ambient_light, error_flags);

        // Wait 500 ms
        gpioDelay(500);
    }

    // The following lines will never be reached due to the infinite loop.
    i2cClose(i2c_handle);
