#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define TRIGGER_PULSE_DURATION 10 // microseconds
#define TIMEOUT_DURATION 200      // milliseconds
#define SPEED_OF_SOUND 0.0343     // cm/us
#define RESISTOR_VALUE 1000.0     // ohms
#define VCC 5.0                   // Volts
#define MAX_PULSE_DURATION 38000.0 // Maximum pulse duration (38ms)

// Global variables
static volatile int echo_start_tick = 0;
static volatile int echo_end_tick = 0;
static volatile int echo_valid = 0; // Flag to indicate if the echo pulse is valid

// Function prototypes
void triggerSensor();
void echoCallback(int gpio, int level, uint32_t tick);
double calculateDistance(int pulse_duration);
void logDistance(double distance);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioTerminate();
    exit(0);
}

// Callback function for echo pin changes
void echoCallback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        // Rising edge
        echo_start_tick = tick;
        echo_valid = 1; // Reset the validity flag
    } else if (level == 0) {
        // Falling edge
        if (echo_valid) {
            echo_end_tick = tick;
            int pulse_duration = echo_end_tick - echo_start_tick;

            if (pulse_duration > 0 && pulse_duration <= MAX_PULSE_DURATION) {
                double distance = calculateDistance(pulse_duration);
                logDistance(distance);
            } else {
                fprintf(stderr, "Error: Invalid pulse duration: %d us\n", pulse_duration);
            }
            echo_valid = 0; // Invalidate the echo pulse
        }
    }
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
double calculateDistance(int pulse_duration) {
    return (pulse_duration * SPEED_OF_SOUND) / 2.0;
}

// Function to log the distance with a timestamp
void logDistance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Distance: %.2f cm\n", timestamp, distance);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register callback function for echo pin
    gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        triggerSensor();
        gpioDelay(1000); // Wait for 1 second
    }

    return 0;
}

