#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <termios.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>

// Constants
#define UART_PORT "/dev/serial0"
#define BAUD_RATE B115200
#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 1.0 // meters
#define RANGE_RESOLUTION 0.0486 // meters per bin
#define MAGIC_WORD_SIZE 8
#define DATA_FRAME_SIZE 128
#define LOG_FILE "intrusion_log.csv"

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
FILE *log_file = NULL;

// Structure for UART configuration
typedef struct {
    char *port;
    int baud_rate;
} uart_config_t;

// Function prototypes
int initialize_uart(uart_config_t config);
int read_radar_data(int fd, unsigned char *buffer, int buffer_size);
int parse_range_profile(unsigned char *data, int data_len, float *range_profile);
int detect_intrusion(float *range_profile, int range_bins);
void activate_led(int gpio_pin, int duration_ms);
void log_intrusion(float distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (uart_fd != -1) {
        close(uart_fd);
        printf("UART port closed.\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();
    printf("pigpio terminated.\n");
}

// Initialize UART port
int initialize_uart(uart_config_t config) {
    int fd = open(config.port, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART port");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = config.baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                                 // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                      // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read doesn't block
    tty.c_cc[VTIME] = 5; // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    printf("UART port %s initialized at %d baud.\n", config.port, config.baud_rate);
    return fd;
}

// Read data from UART port
int read_radar_data(int fd, unsigned char *buffer, int buffer_size) {
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read == -1) {
        perror("Error reading from UART");
        return -1;
    } else if (bytes_read == 0) {
        fprintf(stderr, "Timeout reading from UART\n");
        return 0; // Timeout
    }
    return (int)bytes_read;
}

// Parse range profile data
int parse_range_profile(unsigned char *data, int data_len, float *range_profile) {
    if (data_len != DATA_FRAME_SIZE) {
        fprintf(stderr, "Error: Invalid data frame size (%d bytes). Expected %d bytes.\n", data_len, DATA_FRAME_SIZE);
        return -1;
    }

    for (int i = 0; i < 64; i++) {
        // Extract 16-bit integer from the data buffer
        int16_t range_bin = (data[2 * i] << 8) | data[2 * i + 1];

        // Convert range bin to distance in meters
        range_profile[i] = (float)range_bin * RANGE_RESOLUTION;
    }
    return 0;
}

// Detect intrusion based on range profile
int detect_intrusion(float *range_profile, int range_bins) {
    for (int i = 0; i < range_bins; i++) {
        if (range_profile[i] < DISTANCE_THRESHOLD) {
            return 1; // Intrusion detected
        }
    }
    return 0; // No intrusion detected
}

// Activate LED for 2 seconds
void activate_led(int gpio_pin, int duration_ms) {
    gpioWrite(gpio_pin, 1); // Turn on LED
    gpioDelay(duration_ms * 1000); // Delay for specified duration
    gpioWrite(gpio_pin, 0); // Turn off LED
}

// Log intrusion event to file
void log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s,%.3f\n", timestamp, distance);
    fclose(log_file);
    printf("Intrusion logged: %s, %.3f meters\n", timestamp, distance);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // UART configuration
    uart_config_t uart_config = {
        .port = UART_PORT,
        .baud_rate = BAUD_RATE
    };

    // Initialize UART
    uart_fd = initialize_uart(uart_config);
    if (uart_fd == -1) {
        cleanup();
        return 1;
    }

    unsigned char buffer[DATA_FRAME_SIZE];
    float range_profile[64];

    // Main loop
    while (program_running) {
        // Read data from UART
        int bytes_read = read_radar_data(uart_fd, buffer, DATA_FRAME_SIZE);
        if (bytes_read > 0) {
            // Parse range profile
            if (parse_range_profile(buffer, bytes_read, range_profile) == 0) {
                // Detect intrusion
                if (detect_intrusion(range_profile, 64)) {
                    // Activate LED
                    activate_led(GPIO_PIN, 2000); // 2 seconds

                    // Log intrusion
                    float distance = 0.0;
                    for (int i = 0; i < 64; i++) {
                        if (range_profile[i] < DISTANCE_THRESHOLD) {
                            distance = range_profile[i];
                            break;
                        }
                    }
                    log_intrusion(distance);
                }
            }
        } else if (bytes_read == 0) {
            // Handle timeout (no data received)
            // Optionally add retry logic here
        } else {
            // Handle read error
            fprintf(stderr, "Error reading from UART, exiting.\n");
            break;
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

