#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x007
#define VL53L1X_REG_RESULT_INTERRUPT_STATUS 0x013
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x078
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x014

// Distance thresholds
#define STOP_THRESHOLD 300
#define APPROACH_THRESHOLD 600
#define SLOW_THRESHOLD 1200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_vl53l1x();
int read_distance();
void log_distance(int distance);
void print_guidance(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_bus;
    int i2c_address;
    int stop_threshold;
    int approach_threshold;
    int slow_threshold;
} sensor_config_t;

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address
    buf[2] = value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;      // LSB of register address

    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing register address for read 0x%04X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    uint8_t sensor_id;
    if (read_register(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (sensor_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Software reset
    if (write_register(i2c_handle, 0x0000, 0x00) != 0) {
        fprintf(stderr, "Error writing reset command\n");
        return -1;
    }
    gpioDelay(2000); // Wait 2 ms

    // Start continuous ranging
    if (write_register(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
        fprintf(stderr, "Error starting continuous ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    uint8_t interrupt_status;
    uint8_t range_status;
    uint8_t distance_msb, distance_lsb;
    int distance;
    int timeout = 0;

    // Wait for data ready (with timeout)
    while (1) {
        if (read_register(i2c_handle, VL53L1X_REG_RESULT_INTERRUPT_STATUS, &interrupt_status) != 0) {
            fprintf(stderr, "Error reading interrupt status\n");
            return -1;
        }
        if (interrupt_status & 0x01) {
            break;
        }
        gpioDelay(10000); // 10 ms
        timeout++;
        if (timeout > 100) {
            fprintf(stderr, "Timeout waiting for data ready\n");
            return -1;
        }
    }

    // Read range status
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) != 0) {
        fprintf(stderr, "Error reading range status\n");
        return -1;
    }

    // Read distance (big-endian)
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 10, &distance_msb) != 0) {
        fprintf(stderr, "Error reading distance MSB\n");
        return -1;
    }
    if (read_register(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS + 11, &distance_lsb) != 0) {
        fprintf(stderr, "Error reading distance LSB\n");
        return -1;
    }

    distance = (distance_msb << 8) | distance_lsb;

    // Clear interrupt
    if (write_register(i2c_handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) != 0) {
        fprintf(stderr, "Error clearing interrupt\n");
        return -1;
    }

    return distance;
}

// Function to log the distance to a CSV file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to print parking guidance based on the distance
void print_guidance(int distance) {
    if (distance < STOP_THRESHOLD) {
        printf("STOP\n");
    } else if (distance < APPROACH_THRESHOLD) {
        printf("APPROACH\n");
    } else if (distance < SLOW_THRESHOLD) {
        printf("SLOW\n");
    } else {
        printf("CLEAR\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int distance = read_distance();
        if (distance >= 0) {
            log_distance(distance);
            print_guidance(distance);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }
        gpioDelay(100000); // 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

