// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x45
#define LED_GPIO 18
#define DISTANCE_MIN 50.0  // mm
#define DISTANCE_MAX 500.0 // mm
#define FREQUENCY_MIN 1.0  // Hz
#define FREQUENCY_MAX 10.0 // Hz

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_distance(float *distance);
float map_distance_to_frequency(float distance);
void set_led_frequency(float frequency);
void log_data(float distance, float frequency);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from the sensor
int read_distance(float *distance) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert raw distance to millimeters (example conversion, adjust as needed)
    *distance = (float)raw_distance * 0.1; // Example scaling factor

    return 0;
}

// Map distance to blink frequency
float map_distance_to_frequency(float distance) {
    if (distance < DISTANCE_MIN) {
        return FREQUENCY_MAX;
    } else if (distance > DISTANCE_MAX) {
        return FREQUENCY_MIN;
    } else {
        // Linear mapping
        return FREQUENCY_MAX - (distance - DISTANCE_MIN) * (FREQUENCY_MAX - FREQUENCY_MIN) / (DISTANCE_MAX - DISTANCE_MIN);
    }
}

