    gpioPWM(LED_GPIO, 500); // 50% duty cycle

    // Delay for half the period
    gpioDelay(period / 2.0);

    // Turn off the LED for half the period
    gpioWrite(LED_GPIO, 0);
    gpioDelay(period / 2.0);
}

