#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27
#define DEBOUNCE_DELAY_MS 50

// Structure to hold sensor state
typedef struct {
    int sensor_id;
    int last_state;
    unsigned long last_change_time;
} sensor_state_t;

// Global variables
FILE *log_file = NULL;
sensor_state_t sensor1_state = {1, 1, 0};
sensor_state_t sensor2_state = {2, 1, 0};

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_event(int sensor_id, const char *event_type);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    return 0;
}

// Function to read sensor value with debouncing
int read_sensor(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    unsigned long now = gpioTick();

    if (gpio_pin == SENSOR_1_GPIO) {
        if (current_state != sensor1_state.last_state) {
            if ((now - sensor1_state.last_change_time) > DEBOUNCE_DELAY_MS * 1000) {
                sensor1_state.last_state = current_state;
                sensor1_state.last_change_time = now;
                return current_state;
            }
        }
    } else if (gpio_pin == SENSOR_2_GPIO) {
        if (current_state != sensor2_state.last_state) {
            if ((now - sensor2_state.last_change_time) > DEBOUNCE_DELAY_MS * 1000) {
                sensor2_state.last_state = current_state;
                sensor2_state.last_change_time = now;
                return current_state;
            }
        }
    }

    return sensor1_state.last_state; // Return last known state if debouncing
}

// Function to log events to file
void log_event(int sensor_id, const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", timestamp, sensor_id, event_type);
        fflush(log_file); // Ensure immediate write to file
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("proximity_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == 0 && sensor1_state.last_state == 1) {
            log_event(sensor1_state.sensor_id, "DETECTED");
        } else if (sensor1_value == 1 && sensor1_state.last_state == 0) {
            log_event(sensor1_state.sensor_id, "CLEARED");
        }

        if (sensor2_value == 0 && sensor2_state.last_state == 1) {
            log_event(sensor2_state.sensor_id, "DETECTED");
        } else if (sensor2_value == 1 && sensor2_state.last_state == 0) {
            log_event(sensor2_state.sensor_id, "CLEARED");
        }

        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

