#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x49

// Define register addresses
#define MEAS_TRIGGER 0x04
#define MEAS_STATUS 0x06
#define DIST_HIGH 0x08
#define DIST_LOW 0x09

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int distance_mm;
    char timestamp[32];
} sensor_data_t;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len);
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t data);
int trigger_measurement(int fd);
int read_distance(int fd, int *distance_mm);
int log_data(FILE *fp, const char *timestamp, int distance_mm);
void get_iso8601_timestamp(char *timestamp);
void signal_handler(int signal);

// Function to read data from an I2C register
int i2c_read_register(int fd, uint8_t reg_addr, uint8_t *data, int len) {
    if (write(fd, &reg_addr, 1) != 1) {
        fprintf(stderr, "Error writing register address: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading register data: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to write data to an I2C register
int i2c_write_register(int fd, uint8_t reg_addr, uint8_t data) {
    uint8_t buf[2];
    buf[0] = reg_addr;
    buf[1] = data;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to trigger a single range measurement
int trigger_measurement(int fd) {
    if (i2c_write_register(fd, MEAS_TRIGGER, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd, int *distance_mm) {
    uint8_t high_byte, low_byte;
    int distance;

    if (i2c_read_register(fd, DIST_HIGH, &high_byte, 1) != 0) {
        fprintf(stderr, "Error reading high byte\n");
        return -1;
    }
    if (i2c_read_register(fd, DIST_LOW, &low_byte, 1) != 0) {
        fprintf(stderr, "Error reading low byte\n");
        return -1;
    }

    distance = (high_byte << 8) | low_byte;
    *distance_mm = distance;
    return 0;
}

// Function to log the data to a CSV file
int log_data(FILE *fp, const char *timestamp, int distance_mm) {
    if (fprintf(fp, "%s,%d\n", timestamp, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to get the current timestamp in ISO 8601 format
void get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 32, "%Y-%m-%dT%H:%M:%SZ", info);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    int distance_mm;
    char timestamp[32];
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 500000000; // 500 milliseconds

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Open the log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Error triggering measurement, retrying...\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Wait for measurement to complete with timeout
        int timeout_count = 0;
        uint8_t status;
        while (timeout_count < 10) {
            if (i2c_read_register(i2c_fd, MEAS_STATUS, &status, 1) != 0) {
                fprintf(stderr, "Error reading measurement status, retrying...\n");
                nanosleep(&sleep_time, NULL);
                timeout_count++;
                continue;
            }
            if (status & 0x01) {
                break;
            }
            nanosleep(&sleep_time, NULL);
            timeout_count++;
        }

        if (timeout_count >= 10) {
            fprintf(stderr, "Timeout waiting for measurement, skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Read distance
        if (read_distance(i2c_fd, &distance_mm) != 0) {
            fprintf(stderr, "Error reading distance, skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        // Get timestamp
        get_iso8601_timestamp(timestamp);

        // Log data
        if (log_data(log_file, timestamp, distance_mm) != 0) {
            fprintf(stderr, "Error logging data, skipping sample.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        fflush(log_file);
        nanosleep(&sleep_time, NULL);
    }

    // Clean up
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

