#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define VL53L5CX_ADDR 0x29

// Define the number of zones
#define NUM_ZONES 64

// Define the register addresses for zone data (example, adjust based on datasheet)
#define RESULT_RANGE_STATUS 0x001A
#define RESULT_SPAD_NB_DETECTED 0x0022
#define RESULT_SIGNAL_RATE 0x0024
#define RESULT_AMBIENT_RATE 0x0026
#define RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0028

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to I2C device");
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("Failed to read from I2C device");
        return -1;
    }
    return 0;
}

// Function to read a word (2 bytes) from an I2C register
int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[1];
    uint8_t data[2];

    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, data, 2) != 2) {
        perror("Failed to read from I2C device");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_vl53l5cx(int fd) {
    // Example initialization sequence (adjust based on datasheet)
    if (i2c_write_byte(fd, 0x00, 0x01) != 0) return -1; // Example register write
    usleep(10000); // Delay
    if (i2c_write_byte(fd, 0x01, 0x10) != 0) return -1; // Example register write
    usleep(10000); // Delay
    if (i2c_write_byte(fd, 0x02, 0x00) != 0) return -1; // Example register write
    usleep(10000); // Delay

    // Configure the sensor for 8x8 grid (example, adjust based on datasheet)
    if (i2c_write_byte(fd, 0x03, 0x08) != 0) return -1; // Example register write
