// Define the register address for distance data (replace with actual address from datasheet)
#define DISTANCE_REGISTER 0x00 // Example address

// Global variable for I2C handle
int i2c_handle = -1;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read distance from the sensor
int read_distance(int i2c_handle) {
    char buf[2]; // Assuming 2 bytes for distance data
    int result;

    // Read 2 bytes from the distance register
    result = i2cReadI2CBlockData(i2c_handle, DISTANCE_REGISTER, buf, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading distance data: %d\n", result);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    uint16_t distance = (buf[0] << 8) | buf[1];

    return distance;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read distance from the sensor
        int distance = read_distance(i2c_handle);

        // Get current timestamp
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

        // Log the distance and timestamp
        if (distance >= 0) {
            printf("Timestamp: %ld ms, Distance: %d\n", timestamp_ms, distance);
        } else {
            fprintf(stderr, "Failed to read distance at timestamp: %ld ms\n", timestamp_ms);
        }

        // Wait for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to demonstrate
    // proper resource cleanup.
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

