        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Check sensor ID (example)
    int sensor_id = i2cReadByteData(i2c_handle, VL53L4CX_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
