// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100 // mm
#define I2C_RETRY_COUNT 3

// VL53L1X register addresses
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00C0
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM 0x0096
#define VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS 0x008A
#define VL53L1X_REG_SOFT_RESET 0x0000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_buzzer(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize VL53L1X sensor
int vl53l1x_init() {
    int retries = I2C_RETRY_COUNT;
    int status;

    // Soft reset
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_SOFT_RESET, 0x00);
        if (status == 0) break;
        fprintf(stderr, "Error: Soft reset failed (attempt %d). Error code: %d\n", I2C_RETRY_COUNT - retries + 1, status);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Soft reset failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(20000); // 20ms delay

    // Set I2C address (optional, but good practice)
    retries = I2C_RETRY_COUNT;
    while (retries > 0) {
        status = i2cWriteByteData(i2c_handle, VL53L1X_REG_I2C_SLAVE_DEVICE_ADDRESS, VL53L1X_ADDR);
        if (status == 0) break;
        fprintf(stderr, "Error: Setting I2C address failed (attempt %d). Error code: %d\n", I2C_RETRY_COUNT - retries + 1, status);
        gpioDelay(10000); // 10ms delay
        retries--;
    }
    if (retries == 0) {
        fprintf(stderr, "Error: Setting I2C address failed after multiple retries.\n");
        return -1;
    }
    gpioDelay(10000); // 10ms delay

    // Start continuous ranging
    retries = I2C_RETRY_COUNT;
