#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 17

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_MS 50
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 400.0    // cm
#define MIN_ANGLE -90.0       // degrees
#define MAX_ANGLE 90.0        // degrees
#define SERVO_CENTER_PULSE 1500 // us

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long getPulseWidth();
float calculateDistance(long pulse_width);
int mapDistanceToAngle(float distance);
void setServoAngle(int angle);
void logData(float distance, int angle);
void signalHandler(int signal);

// Function to send a 10us trigger pulse
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long getPulseWidth() {
    long start_time = 0, end_time = 0;
    long pulse_width = 0;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1); // Check every microsecond
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo pin stuck low.\n");
        return -1; // Timeout
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_MS * 1000) {
        count++;
        gpioDelay(1);
    }

    if (count >= TIMEOUT_MS * 1000) {
        fprintf(stderr, "Error: Echo pin stuck high.\n");
        return -2; // Timeout
    }

    end_time = gpioTick();

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Function to calculate distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Error code for timeout
    }
    return (float)pulse_width * SPEED_OF_SOUND / 20000.0; // Divide by 1000000.0 for us to s conversion
}

// Function to map distance to servo angle
int mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (int)((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) + MIN_ANGLE);
    }
}

// Function to set the servo angle
void setServoAngle(int angle) {
    // Calculate pulse width based on angle
    int pulse_width = (int)(SERVO_CENTER_PULSE + (angle - 90) * (2000.0 / 180.0)); // Assuming 1000us - 2000us for 0-180 degrees

    // Limit pulse width to safe range (1000-2000 us)
    if (pulse_width < 1000) {
        pulse_width = 1000;
    } else if (pulse_width > 2000) {
        pulse_width = 2000;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

// Function to log data to a file
void logData(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm, Angle: %d degrees\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("sensor_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = getPulseWidth();
        float distance = calculateDistance(pulse_width);

        if (distance > 0) {
            int angle = mapDistanceToAngle(distance);
            setServoAngle(angle);
            logData(distance, angle);
        } else {
            fprintf(stderr, "Error: Invalid distance reading.\n");
        }

        gpioDelay(200); // Delay 200ms
    }

    // Cleanup
    setServoAngle(0); // Stop the servo
    fclose(log_file);
    gpioTerminate();

    printf("Parking assist system stopped.\n");
    return 0;
}

