#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <mqueue.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100 // mm
#define MESSAGE_QUEUE_NAME "/distance_queue"
#define MAX_MSG_SIZE 10
#define MAX_RETRIES 3

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0080
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
mqd_t mq;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_buzzer(int distance);
void log_distance(int distance);
void signal_handler(int signal);

// Structure for message queue
typedef struct {
    int distance;
} distance_message;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Configure buzzer GPIO
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Create message queue
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = 10;
    attr.mq_msgsize = sizeof(distance_message);
    attr.mq_curmsgs = 0;

    mq = mq_open(MESSAGE_QUEUE_NAME, O_CREAT | O_WRONLY | O_NONBLOCK, 0644, &attr);
    if (mq == (mqd_t)-1) {
        perror("mq_open");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int distance = read_distance();
        if (distance != -1) {
            control_buzzer(distance);
            log_distance(distance);
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        gpioDelay(50000); // 50 ms
    }

    return 0;
}

// Initialize VL53L1X sensor
int init_vl53l1x() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Check model ID
    char model_id;
    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) == 1) {
            if (model_id == 0xEA) {
                printf("VL53L1X model ID verified\n");
                break;
            } else {
                fprintf(stderr, "Incorrect model ID: 0x%02X\n", model_id);
                return -1;
            }
        } else {
            fprintf(stderr, "Failed to read model ID, retrying...\n");
            retries++;
            gpioDelay(10000); // 10 ms delay
        }
    }
    if (retries == MAX_RETRIES) {
        fprintf(stderr, "Max retries reached for model ID check\n");
        return -1;
    }

    // Software reset
    char reset_data[2] = {0x00, 0x01};
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, reset_data, 2) != 2) {
        fprintf(stderr, "Failed to perform software reset\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Configure timing budget (50 ms)
    char timing_budget[2] = {0x00, 0x32}; // 50 ms = 0x32 * 0.034 us
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG, timing_budget, 2) != 2) {
        fprintf(stderr, "Failed to configure timing budget\n");
        return -1;
    }

    // Start ranging
    char start_ranging[1] = {0x01};
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, start_ranging, 1) != 1) {
        fprintf(stderr, "Failed to start ranging\n");
        return -1;
