#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0     // cm
#define BUZZER_THRESHOLD 30.0   // cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void triggerSensor();
float calculateDistance(unsigned int pulse_width);
void echoCallback(int gpio, int level, unsigned int tick);
void buzzerControl(float distance);
void signalHandler(int signal);

// Function to send a 10 microsecond HIGH trigger pulse
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
float calculateDistance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate invalid reading
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for round trip
}

// Callback function for echo pin interrupt
void echoCallback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge was received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 2; // Indicate that a falling edge was received
    }
}

// Function to control the buzzer based on distance
void buzzerControl(float distance) {
    if (distance < BUZZER_THRESHOLD) {
        gpioWrite(BUZZER_PIN, 1); // Turn buzzer ON
    } else {
        gpioWrite(BUZZER_PIN, 0); // Turn buzzer OFF
    }
}

// Signal handler for Ctrl+C
void signalHandler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate();           // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    // Register alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echoCallback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function\n");
        gpioTerminate();
        return 1;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");

    while (1) {
        triggerSensor();

        // Wait for echo or timeout
        int timeout_count = 0;
        while (echo_received < 2 && timeout_count < (TIMEOUT_US / 1000)) {
            gpioDelay(1); // Wait 1ms
            timeout_count++;
        }

        if (echo_received == 2) {
            // Calculate pulse width
            unsigned int pulse_width = end_tick - start_tick;

            // Calculate distance
            float distance = calculateDistance(pulse_width);

            if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
                printf("Sensor-absent or invalid reading: Distance = %.2f cm\n", distance);
            } else {
                printf("Distance: %.2f cm\n", distance);
                buzzerControl(distance);
            }
        } else {
            printf("Timeout waiting for echo\n");
        }

        echo_received = 0; // Reset echo received flag
        gpioDelay(100);     // Wait 100ms
    }

    return 0;
}

