#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdarg.h>

// Configuration
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // mm
#define MQTT_BROKER "localhost" // Replace with your MQTT broker address
#define MQTT_PORT 1883
#define MQTT_TOPIC "gate_control"
#define MQTT_STATUS_TOPIC "gate_status"
#define MQTT_CLIENT_ID "gate_controller"
#define MQTT_KEEPALIVE 60

// Servo limits (SG90)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variables
int i2c_handle;
struct mosquitto *mosq = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void servo_set_angle(int angle);
void log_event(const char *format, ...);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to write a byte to an I2C register
int i2c_write_byte(int handle, uint8_t reg, uint8_t data) {
    char buf[2];
    buf[0] = reg;
    buf[1] = data;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        log_event("Error writing to I2C register 0x%02x", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from an I2C register
int i2c_read_byte(int handle, uint8_t reg, uint8_t *data) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        log_event("Error writing register address for read 0x%02x", reg);
        return -1;
    }
    if (i2cReadDevice(handle, data, 1) != 1) {
        log_event("Error reading from I2C register 0x%02x", reg);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit word from an I2C register
int i2c_read_word(int handle, uint8_t reg, uint16_t *data) {
    char buf[1];
    buf[0] = reg;

    if (i2cWriteDevice(handle, buf, 1) != 1) {
        log_event("Error writing register address for read 0x%02x", reg);
        return -1;
    }

    char read_buf[2];
    if (i2cReadDevice(handle, read_buf, 2) != 2) {
        log_event("Error reading from I2C register 0x%02x", reg);
        return -1;
    }

    *data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// VL53L1X Initialization
int vl53l1x_init() {
    int retries = 3;
    while (retries > 0) {
        // Check sensor ID (Example)
        uint8_t sensor_id;
        if (i2c_read_byte(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &sensor_id) != 0) {
            log_event("Error reading sensor ID, retrying...");
            retries--;
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (sensor_id != 0xEA) {
            log_event("Incorrect sensor ID: 0x%02x", sensor_id);
            retries--;
            gpioDelay(100);
            continue;
        }

        // Reset the sensor
        if (i2c_write_byte(i2c_handle, 0x00, 0x01) != 0) {
            log_event("Error resetting sensor, retrying...");
            retries--;
            gpioDelay(100);
            continue;
        }
        gpioDelay(100); // Wait for reset to complete

        // Start continuous ranging
        if (i2c_write_byte(i2c_handle, VL53L1X_REG_SYSTEM_START, 0x01) != 0) {
            log_event("Error starting ranging, retrying...");
            retries--;
            gpioDelay(100);
            continue;
        }

        log_event("VL53L1X sensor initialized successfully.");
        return 0; // Success
    }

    log_event("VL53L1X initialization failed after multiple retries.");
    return -1; // Failure
}

// VL53L1X Read Distance
int vl53l1x_read_distance() {
    uint16_t distance;
    if (i2c_read_word(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, &distance) != 0) {
        log_event("Error reading distance from VL53L1X.");
        return -1;
    }
    return (int)distance;
}

// Servo Control
void servo_set_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event("Invalid servo angle: %d", angle);
        return;
    }

    // Map angle (0-180) to pulse width (SERVO_MIN_PULSE_WIDTH - SERVO_MAX_PULSE_WIDTH)
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)((float)angle / 180.0 * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));

    gpioServo(SERVO_GPIO, pulse_width);
    log_event("Servo set to angle: %d, pulse width: %d", angle, pulse_width);
}

// Logging
void log_event(const char *format, ...) {
    if (log_file == NULL) return;

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] ", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

    va_list args;
    va_start(args, format);
    vfprintf(log_file, format, args);
    va_end(args);

    fprintf(log_file, "\n");
    fflush(log_file);
}

// MQTT Connect Callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (result == MOSQ_ERR_SUCCESS) {
        log_event("MQTT connected to broker.");
        mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    } else {
        log_event("MQTT connection error: %s", mosquitto_strerror(result));
    }
}

// MQTT Message Callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        log_event("Received MQTT message: %s", payload);

        if (strcmp(payload, "force_open") == 0) {
            servo_set_angle(0);
            log_event("Gate forced open.");
        } else if (strcmp(payload, "force_close") == 0) {
            servo_set_angle(180);
            log_event("Gate forced closed.");
        } else if (strcmp(payload, "status_request") == 0) {
            // Publish status
            char status_message[50];
            int distance = vl53l1x_read_distance();
            if (distance == -1) {
                snprintf(status_message, sizeof(status_message), "{\"status\": \"error\"}");
            } else {
                snprintf(status_message, sizeof(status_message), "{\"status\": \"open\", \"distance\": %d}", distance);
            }

            int ret = mosquitto_publish(mosq, NULL, MQTT_STATUS_TOPIC, strlen(status_message), status_message, 0, false);
            if (ret != MOSQ_ERR_SUCCESS) {
                log_event("Error publishing status: %s", mosquitto_strerror(ret));
            }
        }
    }
}

// Signal Handler
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("gate_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error opening I2C bus: %d", i2c_handle);
        fclose(log_file);
        gpioTerminate();
