#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define TIMEOUT_US 60000      // 60ms timeout
#define MIN_PULSE_US 100      // Minimum valid pulse width (noise)
#define MAX_PULSE_US 30000    // Maximum valid pulse width (timeout)

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold echo timestamps
typedef struct {
    uint32_t rising_tick;
    uint32_t falling_tick;
    int valid;
} EchoData;

EchoData echo_data = {0, 0, 0};

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_duration);
void log_distance(double distance);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to generate a 10 microsecond trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 microseconds
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for ECHO pin changes
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_data.rising_tick = tick;
        echo_data.valid = 0; // Reset valid flag for new reading
    } else if (level == 0) {
        echo_data.falling_tick = tick;
        echo_data.valid = 1; // Set valid flag when both edges are detected
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_duration) {
    if (pulse_duration < MIN_PULSE_US || pulse_duration > MAX_PULSE_US) {
        return -1.0; // Indicate invalid reading
    }
    return (double)pulse_duration * SPEED_OF_SOUND / 2.0;
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Set pull-down resistor on ECHO pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up resources.\n");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    if (initialize()) {
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (running) {
        echo_data.rising_tick = 0;  // Reset rising edge tick
        echo_data.falling_tick = 0; // Reset falling edge tick
        echo_data.valid = 0;       // Reset valid flag

        trigger_pulse();

        // Wait for echo or timeout
        gpioDelay(TIMEOUT_US); // Wait for 60ms

        if (!echo_data.valid) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            fprintf(log_file, "Timeout waiting for echo.\n");
            fflush(log_file);
        } else {
            uint32_t pulse_duration = echo_data.falling_tick - echo_data.rising_tick;
            double distance = calculate_distance(pulse_duration);

            if (distance < 0) {
                fprintf(stderr, "Invalid pulse width: %u us\n", pulse_duration);
                fprintf(log_file, "Invalid pulse width: %u us\n", pulse_duration);
                fflush(log_file);
            } else {
                log_distance(distance);
            }
        }

        gpioDelay(200000); // Measure every 200ms (5Hz)
    }

    cleanup();
    return 0;
}

