// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_OPEN 18
#define GPIO_CLOSE 19
#define DISTANCE_THRESHOLD 200 // mm
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// VL53L1X Register Addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_SYSTEM_SEQUENCE_CONFIG 0x0081
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance();
void control_gate(int distance);
void log_event(const char *event_type);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// VL53L1X Initialization
int vl53l1x_init() {
    // Soft reset
    char data[2] = {0x00, 0x00};
    if (i2cWriteI2CBlockData(i2c_handle, 0x00, data, 2) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    // Configure timing budget (example: 33 ms)
    char timing_config[2] = {0x00, 0x20}; // Example: 33 ms
    if (i2cWriteI2CBlockData(i2c_handle, 0x008E, timing_config, 2) < 0) {
        fprintf(stderr, "Error: Timing budget configuration failed\n");
        return -1;
    }

    // Start ranging
    char start_ranging[2] = {0x00, 0x01};
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_SYSTEM_START, start_ranging, 2) < 0) {
        fprintf(stderr, "Error: Starting ranging failed\n");
        return -1;
    }

    return 0;
}

// VL53L1X Distance Reading
int vl53l1x_read_distance() {
    char buffer[2];
    int distance = -1; // Default to error value
    int retries = I2C_RETRY_COUNT;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, buffer, 2) == 2) {
            distance = (buffer[0] << 8) | buffer[1];
            break; // Success, exit retry loop
        } else {
            fprintf(stderr, "Error: I2C read failed, retrying...\n");
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries--;
        }
    }

    if (distance == -1) {
        fprintf(stderr, "Error: Failed to read distance after multiple retries\n");
    }

    return distance;
}

// Gate Control
void control_gate(int distance) {
    if (distance < DISTANCE_THRESHOLD) {
        gpioWrite(GPIO_OPEN, 1);
        gpioWrite(GPIO_CLOSE, 0);
        log_event("OPEN");
    } else {
        gpioWrite(GPIO_OPEN, 0);
        gpioWrite(GPIO_CLOSE, 1);
        log_event("CLOSE");
    }
}

