#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define LED_PIN_1 17
#define LED_PIN_2 18
#define LED_PIN_3 27
#define LED_PIN_4 22
#define NUM_ELECTRODES 12
#define POLL_INTERVAL_MS 50

// Global variables
int i2c_fd;
struct gpiod_chip *gpio_chip;
struct gpiod_line *led_lines[4];
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int mpr121_init(int fd);
int mpr121_read_touch_status(int fd);
void gpio_set_output(struct gpiod_line *line, int value);
void gpio_cleanup(struct gpiod_line **lines, int num_lines);
void signal_handler(int sig);

// I2C read function
int i2c_read_register(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return value;
}

// I2C write function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write to register");
        return -1;
    }

    return 0;
}

// MPR121 initialization function
int mpr121_init(int fd) {
    // Soft reset
    if (i2c_write_register(fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Check device ID (optional, but good practice)
    int device_id = i2c_read_register(fd, 0x00);
    if (device_id < 0 || device_id != 0x5A) {
        fprintf(stderr, "Error: MPR121 not found (Device ID: 0x%X)\n", device_id);
        return -1;
    }

    // Stop mode
    if (i2c_write_register(fd, 0x5E, 0x00) < 0) return -1;

    // Baseline filtering
    if (i2c_write_register(fd, 0x2B, 0x01) < 0) return -1; // MHDR
    if (i2c_write_register(fd, 0x2C, 0x01) < 0) return -1; // NHDR
    if (i2c_write_register(fd, 0x2D, 0x0E) < 0) return -1; // NCLR
    if (i2c_write_register(fd, 0x2E, 0x00) < 0) return -1; // FDLR

    // Auto-configuration thresholds
    if (i2c_write_register(fd, 0x5A, 0x0B) < 0) return -1;
    if (i2c_write_register(fd, 0x5D, 0xC8) < 0) return -1;
    if (i2c_write_register(fd, 0x5E, 0x82) < 0) return -1;
    if (i2c_write_register(fd, 0x5F, 0xB4) < 0) return -1;

    // Enable all electrodes in run mode
    if (i2c_write_register(fd, 0x5E, 0x0C) < 0) return -1;

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(int fd) {
    int touch_status_low = i2c_read_register(fd, 0x00);
    int touch_status_high = i2c_read_register(fd, 0x01);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Could not read touch status\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// GPIO set output function
void gpio_set_output(struct gpiod_line *line, int value) {
    gpiod_line_set_value(line, value);
}

// GPIO cleanup function
void gpio_cleanup(struct gpiod_line **lines, int num_lines) {
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            gpiod_line_release(lines[i]);
        }
    }
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init(i2c_fd) < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error: Could not open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO lines
    for (int i = 0; i < 4; i++) {
        led_lines[i] = gpiod_chip_get_line(gpio_chip, i + 17);
        if (!led_lines[i]) {
            perror("Error: Could not get GPIO line");
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }

        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            perror("Error: Could not request GPIO line for output");
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Could not read touch status, retrying...\n");
            usleep(100000); // Wait before retrying
            continue;
        }

        // Determine which electrode is active
        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                active_electrode = i;
                break;
            }
        }

        // Map electrode to LED pattern
        int led_pattern = 0;
        switch (active_electrode) {
            case 0: led_pattern = 0b0001; break;
            case 1: led_pattern = 0b0010; break;
            case 2: led_pattern = 0b0100; break;
            case 3: led_pattern = 0b1000; break;
            default: led_pattern = 0b0000; break; // No electrode active
        }

        // Set LED outputs
        for (int i = 0; i < 4; i++) {
            gpio_set_output(led_lines[i], (led_pattern >> i) & 1);
        }

        // Log event
        if (active_electrode != -1) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("%s - Electrode %d active, LED pattern: 0b%d\n", timestamp, active_electrode, led_pattern);
        } else {
            printf("No electrode active.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 50 ms
    }

    // Cleanup
    gpio_cleanup(led_lines, 4);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

