        led_lines[i] = gpiod_chip_get_line(gpio_chip, i + 17);
        if (!led_lines[i]) {
            perror("Error: Could not get GPIO line");
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }

        if (gpiod_line_request_output(led_lines[i], "mpr121_led", 0) < 0) {
            perror("Error: Could not request GPIO line for output");
            gpiod_chip_close(gpio_chip);
            close(i2c_fd);
            return 1;
        }
    }

    // Main loop
    while (program_running) {
        int touch_status = mpr121_read_touch_status(i2c_fd);
        if (touch_status < 0) {
            fprintf(stderr, "Error: Could not read touch status, retrying...\n");
            usleep(100000); // Wait before retrying
            continue;
        }

        // Determine which electrode is active
        int active_electrode = -1;
        for (int i = 0; i < NUM_ELECTRODES; i++) {
            if (touch_status & (1 << i)) {
                active_electrode = i;
                break;
            }
        }

        // Map electrode to LED pattern
        int led_pattern = 0;
        switch (active_electrode) {
            case 0: led_pattern = 0b0001; break;
            case 1: led_pattern = 0b0010; break;
            case 2: led_pattern = 0b0100; break;
            case 3: led_pattern = 0b1000; break;
            default: led_pattern = 0b0000; break; // No electrode active
        }

        // Set LED outputs
        for (int i = 0; i < 4; i++) {
            gpio_set_output(led_lines[i], (led_pattern >> i) & 1);
        }

        // Log event
        if (active_electrode != -1) {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[26];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            printf("%s - Electrode %d active, LED pattern: 0b%d\n", timestamp, active_electrode, led_pattern);
        } else {
            printf("No electrode active.\n");
        }

        usleep(POLL_INTERVAL_MS * 1000); // Poll every 50 ms
    }

    // Cleanup
    gpio_cleanup(led_lines, 4);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

