#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_DEBOUNCECONFIG 0x5B
#define MPR121_AFECONFIG 0x5D
#define MPR121_FFI 0x2B
#define MPR121_SFI 0x2C
#define MPR121_ESI 0x2D
#define MPR121_RESET 0x80
#define MPR121_DEVICEID 0x00

// GPIO pin for LED
#define LED_PIN 27

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void led_on();
void led_off();
void log_proximity_event();
void signal_handler(int signal);

// Function to write a byte to an MPR121 register
int mpr121_write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (i2cWriteDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to read a byte from an MPR121 register
int mpr121_read_register(int handle, uint8_t reg, uint8_t *value) {
    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read 0x%02X\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, value, 1) != 1) {
        fprintf(stderr, "Error reading from MPR121 register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

// Function to initialize the MPR121
int mpr121_init() {
    // Reset the MPR121
    if (mpr121_write_register(i2c_handle, MPR121_RESET, 0x63) < 0) {
        fprintf(stderr, "Error resetting MPR121\n");
        return -1;
    }
    gpioDelay(100000); // Wait for reset to complete

    // Configure FFI
    if (mpr121_write_register(i2c_handle, MPR121_FFI, 0x01) < 0) return -1;
    // Configure SFI
    if (mpr121_write_register(i2c_handle, MPR121_SFI, 0x01) < 0) return -1;
    // Configure ESI
    if (mpr121_write_register(i2c_handle, MPR121_ESI, 0x01) < 0) return -1;

    // Configure Debounce
    if (mpr121_write_register(i2c_handle, MPR121_DEBOUNCECONFIG, 0x10) < 0) return -1;

    // Configure AFE Config
    if (mpr121_write_register(i2c_handle, MPR121_AFECONFIG, 0x0F) < 0) return -1;

    // Configure Electrode Configuration (enable electrode 0)
    if (mpr121_write_register(i2c_handle, MPR121_ELECTRODECONFIG, 0x01) < 0) return -1;

    // Configure Touch and Release Thresholds for electrode 0
    if (mpr121_write_register(i2c_handle, 0x41, 0x0A) < 0) return -1; // Touch threshold
    if (mpr121_write_register(i2c_handle, 0x42, 0x05) < 0) return -1; // Release threshold

    return 0;
}

// Function to read the touch status from the MPR121
int mpr121_read_touch_status() {
    uint8_t touch_status_l, touch_status_h;
    int touch_status;

    if (mpr121_read_register(i2c_handle, MPR121_TOUCHSTATUS_L, &touch_status_l) < 0) return -1;
    if (mpr121_read_register(i2c_handle, MPR121_TOUCHSTATUS_H, &touch_status_h) < 0) return -1;

    touch_status = (touch_status_h << 8) | touch_status_l;
    return touch_status;
}

// Function to turn the LED on
void led_on() {
    gpioWrite(LED_PIN, 1); // Set GPIO high
}

// Function to turn the LED off
void led_off() {
    gpioWrite(LED_PIN, 0); // Set GPIO low
}

// Function to log a proximity event
void log_proximity_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity detected!\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify MPR121 device ID
    uint8_t device_id;
    if (mpr121_read_register(i2c_handle, MPR121_DEVICEID, &device_id) < 0) {
        fprintf(stderr, "Error reading MPR121 device ID\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (device_id != 0x5A) {
        fprintf(stderr, "MPR121 device ID mismatch. Expected 0x5A, got 0x%02X\n", device_id);
