#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 343.0 // m/s
#define TEMPERATURE_CELSIUS 20.0 // degrees Celsius
#define TIMEOUT_US 30000 // 30ms timeout in microseconds

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *log_file = NULL;

// Structure to hold GPIO line handles
typedef struct {
    int trigger_handle;
    int echo_handle;
} gpio_handles_t;

// Function prototypes
int initialize_gpio();
void trigger_sensor();
long long measure_pulse_width();
float calculate_distance(long long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 0); // Ensure trigger is low
    gpioDelay(5); // Wait 5 microseconds
    gpioWrite(TRIGGER_PIN, 1); // Send trigger pulse
    gpioDelay(10); // Wait 10 microseconds
    gpioWrite(TRIGGER_PIN, 0); // Keep trigger low
}

// Function to measure the echo pulse width
long long measure_pulse_width() {
    long long start_tick, end_tick, pulse_width;

    // Wait for echo to go high with timeout
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        gpioDelay(1); // Wait 1 microsecond
        count++;
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate distance in centimeters
float calculate_distance(long long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }

    float distance = (pulse_width * 0.0343) / 2.0;
    return distance;
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance >= 2.0 && distance <= 400.0) {
        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file); // Flush the file to ensure data is written
    } else {
        fprintf(log_file, "%s, Sensor Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            log_distance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s, Sensor Error: Invalid pulse width\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

