void log_distance(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (distance >= 2.0 && distance <= 400.0) {
        fprintf(log_file, "%s, %.2f cm\n", timestamp, distance);
        fflush(log_file); // Flush the file to ensure data is written
    } else {
        fprintf(log_file, "%s, Sensor Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        trigger_sensor();
        long long pulse_width = measure_pulse_width();
        float distance = calculate_distance(pulse_width);

        if (distance >= 0) {
            log_distance(distance);
        } else {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = gmtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            fprintf(log_file, "%s, Sensor Error: Invalid pulse width\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(1000); // Wait 1 second
    }

