// Define GPIO pins
#define TRIG_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MIN_PULSE_WIDTH 58 // Minimum valid pulse width in microseconds (approx. 1 cm)
#define MAX_PULSE_WIDTH 25000 // Maximum valid pulse width in microseconds (approx. 4 m)

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;

// Function prototypes
void trigger_pulse();
double calculate_distance(uint32_t pulse_width);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Function to generate a 10us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1); // Set TRIG HIGH
    gpioDelay(TRIGGER_PULSE_DURATION); // Wait for 10 microseconds
    gpioWrite(TRIG_PIN, 0); // Set TRIG LOW
}

// Function to calculate distance in meters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2000000.0 to convert us to s and then to cm, then to m
}

// Interrupt service routine for ECHO pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        end_tick = tick;
        echo_received = 0; // Reset the flag

        // Calculate pulse width
        uint32_t pulse_width = end_tick - start_tick;

        // Handle tick wraparound
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        }

        // Validate pulse width
        if (pulse_width > MIN_PULSE_WIDTH && pulse_width < MAX_PULSE_WIDTH) {
            // Calculate distance
            double distance = calculate_distance(pulse_width);

            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log data to file
            fprintf(log_file, "%s, %.2f\n", timestamp, distance);
            fflush(log_file); // Ensure data is written to disk immediately
        } else {
            fprintf(stderr, "Error: Invalid pulse width: %u us\n", pulse_width);
        }
    }
}

