        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting ISR function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        trigger_pulse(); // Send trigger pulse
        gpioDelay(1000000); // Wait for 1 second
    }

    return 0;
}

