#include <stdint.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define DISTANCE_REG 0x0014
#define STATUS_REG 0x0016
#define CONTINUOUS_MODE_REG 0x0018
#define TIMEOUT_REG 0x0019
#define START_RANGING_REG 0x0020

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int init_sensor();
int read_distance(uint16_t *distance);
int read_status(uint8_t *status);
void log_data(uint16_t distance, uint8_t status);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int xshut_gpio;
} sensor_config_t;

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully");
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return -1;
    }
    syslog(LOG_INFO, "I2C device opened successfully");
    return 0;
}

// Initialize the VL53L1X sensor
int init_sensor() {
    // Configure continuous mode
    if (i2cWriteByteData(i2c_handle, CONTINUOUS_MODE_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to continuous mode register");
        return -1;
    }

    // Configure no timeout
    if (i2cWriteByteData(i2c_handle, TIMEOUT_REG, 0x00) < 0) {
        syslog(LOG_ERR, "Failed to write to timeout register");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, START_RANGING_REG, 0x01) < 0) {
        syslog(LOG_ERR, "Failed to write to start ranging register");
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialised successfully");
    return 0;
}

// Read distance from the sensor
int read_distance(uint16_t *distance) {
    char buffer[2];
    if (i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buffer, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    *distance = (buffer[1] << 8) | buffer[0]; // Little-endian
    return 0;
}

// Read status from the sensor
int read_status(uint8_t *status) {
    if (i2cReadByteData(i2c_handle, STATUS_REG) < 0) {
        syslog(LOG_ERR, "Failed to read status data");
        return -1;
    }
    *status = i2cReadByteData(i2c_handle, STATUS_REG);
    return 0;
}

// Log data to syslog
void log_data(uint16_t distance, uint8_t status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s Distance: %d mm, Status: %d", timestamp, distance, status);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

int main() {
    // Open syslog
    openlog("vl53l1x_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        closelog();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        closelog();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t distance;
        uint8_t status;

        if (read_distance(&distance) == 0 && read_status(&status) == 0) {
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read sensor data");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    closelog();

    return 0;
}

