#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_GATE 24
#define DISTANCE_THRESHOLD 20 // cm
#define I2C_RETRY_COUNT 3

// VL53L1X Registers
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_RANGING_MODE 0x0021
#define VL53L1X_REG_START_STOP 0x0015
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void control_gate(int distance);
void log_data(int distance, int gate_state, const char *error_message);
void signal_handler(int signal);

// Structure for VL53L1X configuration
typedef struct {
    uint8_t ranging_mode;
    uint8_t start_stop;
} vl53l1x_config_t;

// Function to write a byte to a VL53L1X register
int write_register(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address
    buf[2] = value;

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        log_data(-1, -1, "I2C Write Error");
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L1X register
int read_register(int handle, uint16_t reg, uint8_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_data(-1, -1, "I2C Write (Address) Error");
        return -1;
    }

    result = i2cReadDevice(handle, (char *)value, 1);
    if (result != 0) {
        log_data(-1, -1, "I2C Read Error");
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from a VL53L1X register
int read_16bit_register(int handle, uint16_t reg, uint16_t *value) {
    char buf[2];
    buf[0] = (reg >> 8) & 0xFF; // MSB of register address
    buf[1] = reg & 0xFF;        // LSB of register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        log_data(-1, -1, "I2C Write (Address) Error");
        return -1;
    }

    char data[2];
    result = i2cReadDevice(handle, data, 2);
    if (result != 0) {
        log_data(-1, -1, "I2C Read Error");
        return -1;
    }

    *value = (data[0] << 8) | data[1];
    return 0;
}

