#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define DISTANCE_MIN 2.0      // cm
#define DISTANCE_MAX 400.0    // cm
#define SERVO_MIN_PULSEWIDTH 500 // us
#define SERVO_MAX_PULSEWIDTH 2500 // us
#define SERVO_MIN_ANGLE 0      // degrees
#define SERVO_MAX_ANGLE 180    // degrees
#define TIMEOUT_US 30000       // 30 ms
#define MOVING_AVG_SIZE 5
#define TRIGGER_PULSE_US 10

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Structure to hold pulse width data
typedef struct {
    unsigned int pulse_width;
    int valid;
} pulse_width_data_t;

pulse_width_data_t pulse_width_data = {0, 0};

// Function prototypes
void signal_handler(int signal);
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_distance(unsigned int pulse_width);
double apply_moving_average(double new_distance);
double map_distance_to_angle(double distance);
int set_servo_angle(double angle);
int log_data(double distance, double angle);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin changes
void echo_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static uint32_t start_tick = 0;
    static uint32_t end_tick = 0;

    if (level == 1) {
        start_tick = tick;
    } else if (level == 0) {
        end_tick = tick;

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Handle potential wrap-around
        if (end_tick < start_tick) {
            pulse_width = (0xFFFFFFFF - start_tick) + end_tick;
        }

        // Store pulse width data
        pulse_width_data.pulse_width = pulse_width;
        pulse_width_data.valid = 1; // Mark as valid
    }
}

// Function to calculate distance from pulse width
double calculate_distance(unsigned int pulse_width) {
    double distance = (pulse_width * SPEED_OF_SOUND) / 2000000.0; // in cm
    return distance;
}

// Function to apply a moving average filter
double apply_moving_average(double new_distance) {
    static double distance_history[MOVING_AVG_SIZE] = {0.0};
    static int history_index = 0;
    static int history_filled = 0;

    distance_history[history_index] = new_distance;
    history_index = (history_index + 1) % MOVING_AVG_SIZE;

    if (!history_filled) {
        history_filled = (history_index == 0);
    }

    double sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_history[i];
    }

    return sum / MOVING_AVG_SIZE;
}

// Function to map distance to servo angle (logarithmic mapping)
double map_distance_to_angle(double distance) {
    if (distance < DISTANCE_MIN) {
        return SERVO_MIN_ANGLE;
    } else if (distance > DISTANCE_MAX) {
        return SERVO_MAX_ANGLE;
    } else {
        // Logarithmic mapping
        double angle = (distance - DISTANCE_MIN) / (DISTANCE_MAX - DISTANCE_MIN) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE;
        return angle;
    }
}

// Function to set the servo angle
int set_servo_angle(double angle) {
    int pulse_width = (int)(SERVO_MIN_PULSEWIDTH + (angle / SERVO_MAX_ANGLE) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH));
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to log data to a CSV file
int log_data(double distance, double angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set pull-down resistor on echo pin
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
        fflush(log_file);
    }

    // Register alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error registering alert function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(100); // Wait 100 ms

        // Read and process pulse width data
        if (pulse_width_data.valid) {
            double distance = calculate_distance(pulse_width_data.pulse_width);

            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                double avg_distance = apply_moving_average(distance);
                double angle = map_distance_to_angle(avg_distance);

                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Error setting servo angle, defaulting to 90 degrees.\n");
                    set_servo_angle(90.0); // Set to a safe default
                }

                if (log_data(avg_distance, angle) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
                log_data(-1.0, 90.0); // Log -1 for distance and 90 for angle
                set_servo_angle(90.0); // Set to a safe default
            }

            pulse_width_data.valid = 0; // Reset valid flag
        } else {
            fprintf(stderr, "Timeout waiting for echo.\n");
            log_data(-1.0, 90.0); // Log -1 for distance and 90 for angle
            set_servo_angle(90.0); // Set to a safe default
        }
    }

    // Stop the servo
    set_servo_angle(90.0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

