        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
        fflush(log_file);
    }

    // Register alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error registering alert function!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor and servo control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        gpioDelay(100); // Wait 100 ms

        // Read and process pulse width data
        if (pulse_width_data.valid) {
            double distance = calculate_distance(pulse_width_data.pulse_width);

            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                double avg_distance = apply_moving_average(distance);
                double angle = map_distance_to_angle(avg_distance);

                if (set_servo_angle(angle) != 0) {
                    fprintf(stderr, "Error setting servo angle, defaulting to 90 degrees.\n");
                    set_servo_angle(90.0); // Set to a safe default
                }

                if (log_data(avg_distance, angle) != 0) {
                    fprintf(stderr, "Error logging data.\n");
                }
            } else {
                fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
                log_data(-1.0, 90.0); // Log -1 for distance and 90 for angle
                set_servo_angle(90.0); // Set to a safe default
            }

            pulse_width_data.valid = 0; // Reset valid flag
        } else {
            fprintf(stderr, "Timeout waiting for echo.\n");
            log_data(-1.0, 90.0); // Log -1 for distance and 90 for angle
            set_servo_angle(90.0); // Set to a safe default
        }
    }

    // Stop the servo
    set_servo_angle(90.0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

