#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <pigpio.h>
#include <getopt.h>

// Constants
#define I2C_BUS 1
#define DEFAULT_I2C_ADDRESS 0x60
#define DEFAULT_THRESHOLD 1000
#define PROXIMITY_HIGH_REG 0x08
#define PROXIMITY_LOW_REG 0x09
#define GPIO_PIN 27
#define LOG_FILE "proximity.log"

// Global variables
static int i2c_handle;
static FILE *log_file;
static int i2c_address = DEFAULT_I2C_ADDRESS;
static int threshold = DEFAULT_THRESHOLD;
static volatile int interrupt_flag = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

// Structure to hold data for the interrupt handler
typedef struct {
    int proximity_value;
    int status;
} InterruptData;

// Function prototypes
int init_pigpio();
int init_i2c(int address);
int read_proximity(int *proximity);
int configure_gpio_interrupt(int gpio_pin, int edge);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
int log_proximity_data(int proximity, int status);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int init_i2c(int address) {
    i2c_handle = i2cOpen(I2C_BUS, address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read proximity value from the sensor
int read_proximity(int *proximity) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, PROXIMITY_HIGH_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read proximity data: %d\n", result);
        return -1;
    }

    *proximity = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to configure GPIO interrupt
int configure_gpio_interrupt(int gpio_pin, int edge) {
    if (gpioSetMode(gpio_pin, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        return -1;
    }

    if (gpioSetPullUpDown(gpio_pin, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Failed to set GPIO pull-down resistor\n");
        return -1;
    }

    if (gpioSetISRFuncEx(gpio_pin, edge, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return -1;
    }

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;
    int status;

    if (read_proximity(&proximity) == 0) {
        if (proximity <= threshold) {
            status = 0; // SAFE
        } else {
            status = 1; // ALERT
        }

        InterruptData data;
        data.proximity_value = proximity;
        data.status = status;

        // Use a mutex to protect access to the log file
        pthread_mutex_lock(&log_mutex);
        log_proximity_data(proximity, status);
        pthread_mutex_unlock(&log_mutex);
    }
}

// Function to log proximity data to a file
int log_proximity_data(int proximity, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status ? "ALERT" : "SAFE");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure GPIO interrupt
    if (configure_gpio_interrupt(GPIO_PIN, RISING_EDGE) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop (sleep to avoid busy-waiting)
    while (1) {
        sleep(1);
    }

    return 0;
}

