    if (gpioSetISRFuncEx(gpio_pin, edge, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return -1;
    }

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    int proximity;
    int status;

    if (read_proximity(&proximity) == 0) {
        if (proximity <= threshold) {
            status = 0; // SAFE
        } else {
            status = 1; // ALERT
        }

        InterruptData data;
        data.proximity_value = proximity;
        data.status = status;

        // Use a mutex to protect access to the log file
        pthread_mutex_lock(&log_mutex);
        log_proximity_data(proximity, status);
        pthread_mutex_unlock(&log_mutex);
    }
}

// Function to log proximity data to a file
int log_proximity_data(int proximity, int status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Proximity: %d, Status: %s\n", timestamp, proximity, status ? "ALERT" : "SAFE");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    pthread_mutex_destroy(&log_mutex);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
            case 'a':
                i2c_address = strtol(optarg, NULL, 0); // Allow hex or decimal
                break;
            case 't':
                threshold = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c(i2c_address) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure GPIO interrupt
    if (configure_gpio_interrupt(GPIO_PIN, RISING_EDGE) != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Threshold: %d\n", threshold);

    // Main loop (sleep to avoid busy-waiting)
    while (1) {
        sleep(1);
    }

    return 0;
}

