#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SPEAKER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000       // 200 ms timeout for echo
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 200.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz

// Global variables
static volatile int running = 1;
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;

// Function prototypes
void signal_handler(int signal);
void trigger_pulse();
float measure_distance();
float calculate_frequency(float distance);
void set_pwm_frequency(float frequency);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to generate the trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the distance using the HC-SR04 sensor
float measure_distance() {
    trigger_pulse();

    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return -1.0; // Indicate timeout error
        }
    }
    start_tick = gpioTick();

    end_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - end_tick > TIMEOUT_US) {
            fprintf(stderr, "Error: Echo pulse timeout\n");
            return -1.0; // Indicate timeout error
        }
    }
    end_tick = gpioTick();

    unsigned int diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Time in seconds
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to calculate the frequency based on the distance
float calculate_frequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return -1.0; // Indicate out-of-range error
    }

    float frequency = MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * exp((distance - MIN_DISTANCE) / 50.0);
    return frequency;
}

// Function to set the PWM frequency on the speaker pin
void set_pwm_frequency(float frequency) {
    if (frequency < 0) {
        gpioPWM(SPEAKER_PIN, 0); // Stop PWM if frequency is negative
        return;
    }

    int range = 1000; // PWM range (adjust as needed)
    int duty_cycle = range / 2; // 50% duty cycle

    gpioSetPWMfrequency(SPEAKER_PIN, (int)frequency);
    gpioPWM(SPEAKER_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SPEAKER_PIN, PI_OUTPUT);

    // Set PWM range (optional, but recommended)
    gpioSetPWMrange(SPEAKER_PIN, 1000); // Example range

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Theremin-like instrument running. Press Ctrl+C to exit.\n");

    while (running) {
        float distance = measure_distance();
        if (distance > 0) {
            float frequency = calculate_frequency(distance);
            if (frequency > 0) {
                set_pwm_frequency(frequency);
            } else {
                fprintf(stderr, "Error: Invalid frequency calculated\n");
            }
        } else {
            fprintf(stderr, "Error: Invalid distance measurement\n");
        }

        gpioDelay(50); // Delay between measurements
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioPWM(SPEAKER_PIN, 0); // Stop PWM output
    gpioTerminate();         // Terminate pigpio

    return 0;
}

