// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 5.0      // Minimum distance in cm
#define MAX_DISTANCE 50.0     // Maximum distance in cm
#define MIN_FREQUENCY 200.0   // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0  // Maximum frequency in Hz
#define TIMEOUT_US 100000.0   // Timeout in microseconds (100 ms)

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_time, end_time, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo start.\n");
        return -1; // Indicate timeout error
    }

    start_time = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Timeout waiting for echo end.\n");
        return -1; // Indicate timeout error
    }

    end_time = gpioTick();

    pulse_width = end_time - start_time;
    return pulse_width;
}

// Function to calculate distance from pulse width
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (MAX_FREQUENCY - MIN_FREQUENCY) * (MAX_DISTANCE - distance) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the PWM frequency
void setPWMFrequency(float frequency) {
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
}

// Function to set the PWM duty cycle (volume)
void setPWMDutyCycle(float dutyCycle) {
    if (dutyCycle < 0.0) dutyCycle = 0.0;
    if (dutyCycle > 1.0) dutyCycle = 1.0;
    gpioPWM(BUZZER_PIN, (int)(dutyCycle * 255)); // pigpio uses 0-255 for duty cycle
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM frequency (initial value)
    setPWMFrequency(MIN_FREQUENCY);

    // Set PWM duty cycle (initial value)
    setPWMDutyCycle(0.5); // 50% duty cycle

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float last_distance = MIN_DISTANCE; // Initialize with minimum distance

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulse_width = measurePulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulse_width);

        // Map the distance to a frequency
        float frequency = MIN_FREQUENCY;
        if (distance > 0) {
            frequency = mapDistanceToFrequency(distance);
            last_distance = distance; // Update last valid distance
        } else {
            frequency = mapDistanceToFrequency(last_distance); // Use last valid distance
            fprintf(stderr, "Error: Invalid distance, using last valid distance.\n");
        }

        // Set the PWM frequency
        setPWMFrequency(frequency);

        // Print the distance and frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Stop the PWM output
    gpioPWM(BUZZER_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

