                    printf("Too close!\n");
                }
            } else {
                printf("Invalid reading: %.2f cm\n", distance);
            }
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

