#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // Chip Select pin (GPIO8)
#define DISTANCE_MIN 200  // Minimum distance in mm
#define DISTANCE_MAX 5000 // Maximum distance in mm

// ICU-20201 Register Addresses
#define REG_MEASUREMENT_MODE 0x01
#define REG_RANGE_SETTING 0x02
#define REG_MEASURE 0x00
#define REG_DISTANCE_LOW 0x0C
#define REG_DISTANCE_HIGH 0x0D

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_distance(uint16_t *distance);
void log_distance(uint16_t distance);
void signal_handler(int signal);

// Structure for SPI configuration
typedef struct {
    int channel;
    int speed;
    int cs_pin;
} spi_config_t;

// Function to write a register
int write_register(uint8_t reg, uint8_t value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg | 0x80; // Set MSB for write operation
    tx_buf[1] = value;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error writing to register 0x%02X\n", reg);
        return -1;
    }

    return 0;
}

// Function to read a register
int read_register(uint8_t reg, uint8_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for read operation
    tx_buf[1] = 0x00;       // Dummy byte for reading

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error reading from register 0x%02X\n", reg);
        return -1;
    }

    *value = rx_buf[1];
    return 0;
}

// Function to initialize the sensor
int initialize_sensor() {
    // Set measurement mode to continuous
    if (write_register(REG_MEASUREMENT_MODE, 0x01) != 0) {
        fprintf(stderr, "Error setting measurement mode\n");
        return -1;
    }

    // Set range to 5m
    if (write_register(REG_RANGE_SETTING, 0x00) != 0) {
        fprintf(stderr, "Error setting range\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the sensor
int read_distance(uint16_t *distance) {
    uint8_t low_byte, high_byte;

    // Trigger a measurement
    if (write_register(REG_MEASURE, 0x01) != 0) {
        fprintf(stderr, "Error triggering measurement\n");
        return -1;
    }

    // Read distance data
    if (read_register(REG_DISTANCE_LOW, &low_byte) != 0) {
        fprintf(stderr, "Error reading distance low byte\n");
        return -1;
    }

    if (read_register(REG_DISTANCE_HIGH, &high_byte) != 0) {
        fprintf(stderr, "Error reading distance high byte\n");
        return -1;
    }

    *distance = (high_byte << 8) | low_byte;

    return 0;
}

// Function to log the distance to a file
void log_distance(uint16_t distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    spi_config_t spi_config = {SPI_CHANNEL, SPI_SPEED, CS_PIN};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(spi_config.channel, spi_config.speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    uint16_t distance;
    while (program_running) {
        if (read_distance(&distance) == 0) {
            if (distance >= DISTANCE_MIN && distance <= DISTANCE_MAX) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Distance out of range: %u mm\n", distance);
            }
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

