#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1" // I2C bus on Raspberry Pi
#define SI1175_ADDR 0x60      // Si1175 I2C address
#define ALS_VISIBLE_LOW_REG 0x22
#define ALS_VISIBLE_HIGH_REG 0x23
#define LOG_FILE "proximity_log.csv"

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_open(const char *bus, int addr);
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
uint16_t read_als_visible(int fd);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(const char *timestamp, uint16_t als_value);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error reading from I2C device");
        return -1;
    }

    return value;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Read ALS visible light function
uint16_t read_als_visible(int fd) {
    int low_byte = i2c_read_reg(fd, ALS_VISIBLE_LOW_REG);
    int high_byte = i2c_read_reg(fd, ALS_VISIBLE_HIGH_REG);

    if (low_byte < 0 || high_byte < 0) {
        fprintf(stderr, "Error reading ALS visible light data\n");
        return 0; // Return 0 on error
    }

    return (uint16_t)((high_byte << 8) | low_byte);
}

// Get ISO 8601 timestamp function
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp_str;
}

// Log data to CSV file function
int log_data(const char *timestamp, uint16_t als_value) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%u\n", timestamp, als_value);
    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,als_visible\n");
        fflush(log_file);
    }

    // Main loop
    while (program_running) {
        // Read ALS visible light value
        uint16_t als_value = read_als_visible(i2c_fd);

        // Get ISO 8601 timestamp
        char timestamp[32];
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log data
        if (log_data(timestamp, als_value) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

