void log_data(uint16_t als, uint16_t ps1);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reset the Si1120 sensor
int reset_sensor() {
    if (write_register(SI1120_RESET_REG, 0x01) != 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10 ms after reset
    return 0;
}

// Verify the Si1120 part ID
int verify_part_id() {
    uint8_t part_id;
    if (read_register(SI1120_PART_ID_REG, &part_id) != 0) {
        fprintf(stderr, "Error reading part ID\n");
        return -1;
    }
    if (part_id != 0x41) {
        fprintf(stderr, "Incorrect part ID: 0x%02X\n", part_id);
        return -1;
    }
    return 0;
}

// Read a single byte from a register with retry
int read_register(uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cReadByteData(i2c_handle, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X, attempt %d): %d\n", reg, retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_US);
        }
    }
    fprintf(stderr, "Failed to read register 0x%02X after %d retries\n", reg, MAX_RETRIES);
    return -1; // Failure
}

// Write a single byte to a register with retry
int write_register(uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByteData(i2c_handle, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X, attempt %d): %d\n", reg, value, retries + 1, result);
            retries++;
            gpioDelay(RETRY_DELAY_US);
