int read_sensor_data(uint16_t *als, uint16_t *ps1) {
    uint8_t als_low, als_high, ps1_low, ps1_high;

    if (read_register(SI1120_ALS_LOW_REG, &als_low) != 0) return -1;
    if (read_register(SI1120_ALS_HIGH_REG, &als_high) != 0) return -1;
    if (read_register(SI1120_PS1_LOW_REG, &ps1_low) != 0) return -1;
    if (read_register(SI1120_PS1_HIGH_REG, &ps1_high) != 0) return -1;

    *als = (uint16_t)((als_high << 8) | als_low);
    *ps1 = (uint16_t)((ps1_high << 8) | ps1_low);

    return 0;
}

// Log the sensor data to a file
void log_data(uint16_t als, uint16_t ps1) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ALS: %u, PS1: %u\n", timestamp, als, ps1);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

