    uint16_t als, ps1;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Reset the sensor
    if (reset_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Verify the part ID
    if (verify_part_id() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&als, &ps1) == 0) {
            log_data(als, ps1);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(500000); // 500 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
