#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and sensor address
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x39

// Define register addresses
#define REG_PART_ID 0x00
#define REG_MEAS_RATE 0x08
#define REG_ALS_DATA_LOW 0x22
#define REG_ALS_DATA_HIGH 0x23
#define REG_PS_DATA_LOW 0x24
#define REG_PS_DATA_HIGH 0x25

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int init_si1182(int fd);
int read_si1182_data(int fd, float *lux, int *proximity);
void log_data(FILE *fp, float lux, int proximity);
void print_data(float lux, int proximity);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Initialize the Si1182 sensor
int init_si1182(int fd) {
    // Verify Part ID
    int part_id = i2c_read_reg(fd, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID. Sensor might be absent.\n");
        return -1;
    }
    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X (expected 0x82)\n", part_id);
        return -1;
    }

    // Set measurement rate to 7 (every 100ms)
    if (i2c_write_reg(fd, REG_MEAS_RATE, 0x07) < 0) {
        fprintf(stderr, "Error setting measurement rate.\n");
        return -1;
    }

    printf("Si1182 sensor initialized successfully.\n");
    return 0;
}

// Read data from the Si1182 sensor
int read_si1182_data(int fd, float *lux, int *proximity) {
    int als_low, als_high, ps_low, ps_high;

    als_low = i2c_read_reg(fd, REG_ALS_DATA_LOW);
    als_high = i2c_read_reg(fd, REG_ALS_DATA_HIGH);
    ps_low = i2c_read_reg(fd, REG_PS_DATA_LOW);
    ps_high = i2c_read_reg(fd, REG_PS_DATA_HIGH);

    if (als_low < 0 || als_high < 0 || ps_low < 0 || ps_high < 0) {
        fprintf(stderr, "Error reading sensor data.\n");
        return -1;
    }

    *lux = (float)((als_high << 8) | als_low) * 0.1;
    *proximity = (ps_high << 8) | ps_low;

    return 0;
}

// Log data to file
void log_data(FILE *fp, float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3N", timeinfo);

    fprintf(fp, "%s,%.2f,%d\n", timestamp, lux, proximity);
    fflush(fp); // Ensure data is written to disk immediately
}

// Print data to stdout
void print_data(float lux, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S.%3N", timeinfo);

    printf("%s,%.2f,%d\n", timestamp, lux, proximity);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize the sensor
    if (init_si1182(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    float lux;
    int proximity;

    // Main loop
    while (program_running) {
        if (read_si1182_data(i2c_fd, &lux, &proximity) == 0) {
            log_data(log_file, lux, proximity);
            print_data(lux, proximity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        usleep(100000); // 100 ms
    }

    // Close I2C bus and log file
    close(i2c_fd);
    fclose(log_file);

    printf("Program finished.\n");
    return 0;
}

