#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <time.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18
#define BUZZER_PIN 27

// Define constants
#define SPEED_OF_SOUND 0.0343 // cm/us
#define DISTANCE_THRESHOLD 20.0 // cm

// Global variables
volatile int echo_start_tick = 0;
volatile int echo_end_tick = 0;
volatile int echo_received = 0;

// Function prototypes
void trigger_pulse();
double calculate_distance(int pulse_width);
void echo_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    gpioTerminate();
    exit(0);
}

// Function to generate a 10 us trigger pulse
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2.0;
}

// Interrupt handler for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        echo_start_tick = tick;
        echo_received = 1; // Indicate that a rising edge has been received
    } else if (level == 0 && echo_received == 1) {
        echo_end_tick = tick;
        echo_received = 2; // Indicate that a falling edge has been received
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set up interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for ECHO_PIN\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Trigger the sensor
        trigger_pulse();

        // Wait for the echo pulse to be received
        int timeout_counter = 0;
        while (echo_received < 2 && timeout_counter < 1000) {
            gpioDelay(1); // Wait 1 ms
            timeout_counter++;
        }

        if (echo_received < 2) {
            fprintf(stderr, "Timeout waiting for echo pulse\n");
            echo_start_tick = 0;
            echo_end_tick = 0;
            echo_received = 0;
            gpioDelay(1000); // Wait 1 second before next measurement
            continue;
        }

        // Calculate pulse width
        int pulse_width = echo_end_tick - echo_start_tick;

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Print distance
        printf("Distance: %.2f cm\n", distance);

        // Control buzzer
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1); // Activate buzzer
        } else {
            gpioWrite(BUZZER_PIN, 0); // Deactivate buzzer
        }

        // Reset variables for next measurement
        echo_start_tick = 0;
        echo_end_tick = 0;
        echo_received = 0;

        // Wait 1 second
        gpioDelay(1000);
    }

    // This point should not be reached due to the infinite loop
    gpioTerminate();
    return 0;
}

