            return -1.0; // Timeout
        }
    }

    start_tick = gpioTick();

    // Wait for echo to go low with timeout
    while (gpioRead(ECHO_PIN) == 1) {
        end_tick = gpioTick();
        if (end_tick - start_tick > TIMEOUT_US) {
            return -1.0; // Timeout
        }
    }

    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;

    // Calculate distance in centimeters
    float distance = (float)diff * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s, and by 2 for one-way distance

    return distance;
}

// Function to set servo angle based on distance
void setServoAngle(float distance) {
    // Map distance to servo pulse width (500 us - 2500 us)
    float pulse_width = 500.0 + (distance - MAX_DISTANCE) * (2000.0 - 500.0) / (MIN_DISTANCE - MAX_DISTANCE);

    // Limit pulse width to 500 us - 2500 us
    if (pulse_width < 500.0) {
        pulse_width = 500.0;
    } else if (pulse_width > 2500.0) {
        pulse_width = 2500.0;
    }

    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking Assist System running. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measureDistance();

        if (distance < 0) {
            fprintf(stderr, "Error: Distance measurement timeout\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
            setServoAngle(distance);
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Stop the servo and terminate pigpio
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();

    return 0;
}

