#define CLOSE_PULSE_WIDTH 2000
#define DISTANCE_THRESHOLD_OPEN 200
#define DISTANCE_THRESHOLD_CLOSE 250
#define TIMING_BUDGET 50000 // 50 ms
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void open_gate();
void close_gate();
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (Example - refer to datasheet for complete list)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_TIMING_BUDGET 0x008E
#define VL53L1X_REG_START_STOP 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    char data[1];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, data, 1) != 1) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }

    if (data[0] != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", data[0]);
        return -1;
    }

    // Set timing budget
    char timing_data[2];
    timing_data[0] = TIMING_BUDGET & 0xFF;       // LSB
    timing_data[1] = (TIMING_BUDGET >> 8) & 0xFF; // MSB

    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_TIMING_BUDGET, timing_data, 2) != 2) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging
    char start_data[1];
    start_data[0] = 0x01; // Start ranging
    if (i2cWriteI2CBlockData(i2c_handle, VL53L1X_REG_START_STOP, start_data, 1) != 1) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance() {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, data, 2) != 2) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }

    int distance = (data[0] << 8) | data[1];
    return distance;
}

