    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    int distance;
    int gate_open = 0; // 0 = closed, 1 = open

    // Main loop
    while (program_running) {
        distance = read_distance();
        if (distance > 0) {
            printf("Distance: %d mm\n", distance);

            if (distance < DISTANCE_THRESHOLD_OPEN && !gate_open) {
                open_gate();
                gate_open = 1;
            } else if (distance > DISTANCE_THRESHOLD_CLOSE && gate_open) {
                close_gate();
                gate_open = 0;
            }
        } else {
            fprintf(stderr, "Error reading distance, retrying...\n");
        }

        gpioDelay(100); // Delay 100 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioServo(SERVO_GPIO, 0); // Stop servo
    fclose(log_file);
    gpioTerminate();

    return 0;
}

