#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Constants
#define SPEED_OF_SOUND 343.0 // m/s
#define TRIGGER_PULSE_DURATION 10 // us
#define TIMEOUT_DURATION 50000 // us (50 ms)
#define MIN_DISTANCE 2.0 // cm
#define MAX_DISTANCE 400.0 // cm
#define MIN_ANGLE 0.0 // degrees
#define MAX_ANGLE 180.0 // degrees

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
float measure_distance();
float calculate_distance(long pulse_duration);
float map_distance_to_angle(float distance);
void set_servo_angle(float angle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCtrl+C detected. Stopping servo and terminating pigpio.\n");
        program_running = 0;
        gpioServo(SERVO_PIN, 0); // Stop the servo
        gpioTerminate(); // Terminate pigpio
        exit(0);
    }
}

// Function to measure distance using the HC-SR04 sensor
float measure_distance() {
    long start_tick, end_tick, pulse_duration;

    // Trigger the sensor
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIGGER_PIN, 0);

    // Measure the echo pulse width
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_DURATION) {
            return -1.0; // Timeout
        }
    }
    start_tick = gpioTick();

    while (gpioRead(ECHO_PIN) == 1) {
        if (gpioTick() - start_tick > TIMEOUT_DURATION) {
            return -1.0; // Timeout
        }
    }
    end_tick = gpioTick();

    pulse_duration = end_tick - start_tick;

    return calculate_distance(pulse_duration);
}

// Function to calculate distance from pulse duration
float calculate_distance(long pulse_duration) {
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Convert us to s and divide by 2
}

// Function to map distance to servo angle
float map_distance_to_angle(float distance) {
    if (distance < MIN_DISTANCE) {
        return MIN_ANGLE;
    } else if (distance > MAX_DISTANCE) {
        return MAX_ANGLE;
    } else {
        return (distance - MIN_DISTANCE) * (MAX_ANGLE - MIN_ANGLE) / (MAX_DISTANCE - MIN_DISTANCE) + MIN_ANGLE;
    }
}

// Function to set the servo angle
void set_servo_angle(float angle) {
    // Map angle (0-180) to pulse width (500-2500 us)
    int pulse_width = (int)(500 + (angle / 180.0) * 2000);
    gpioServo(SERVO_PIN, pulse_width);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        float distance = measure_distance();

        if (distance > 0) {
            float angle = map_distance_to_angle(distance);
            set_servo_angle(angle);
            printf("Distance: %.2f cm, Angle: %.2f degrees\n", distance, angle);
        } else {
            fprintf(stderr, "Sensor timeout or error occurred.\n");
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate(); // Terminate pigpio

    return 0;
}

