#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0x03
#define TEMP_REG 0x01
#define HUMID_REG 0x02
#define MEASURE_TEMP 0x00

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_config_register(int handle, unsigned char config_value);
int read_sensor_data(int handle, unsigned char reg_addr, unsigned short *data);
float convert_temperature(unsigned short raw_temp);
float convert_humidity(unsigned short raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02x: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Write to the Si7005 configuration register
int write_config_register(int handle, unsigned char config_value) {
    int result = i2cWriteByteData(handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait 10 ms
    return 0;
}

// Read sensor data from the Si7005
int read_sensor_data(int handle, unsigned char reg_addr, unsigned short *data) {
    int result = i2cReadWordData(handle, reg_addr);
    if (result < 0) {
        fprintf(stderr, "Failed to read from register 0x%02x: %d\n", reg_addr, result);
        return -1;
    }
    *data = (unsigned short)result;
    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned short raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to relative humidity
float convert_humidity(unsigned short raw_humidity) {
    return (125.0 * raw_humidity / 65536.0) - 6.0;
}

// Log temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
}

