#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 register addresses
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG  0x1B
#define ACCEL_XOUT_H 0x3B

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set sample rate divider
    if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 7) < 0) {
        fprintf(stderr, "Error: Could not set sample rate divider\n");
        return -1;
    }

    // Configure accelerometer range (+/- 2g)
    if (i2cWriteByteData(i2c_handle, ACCEL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure accelerometer range\n");
        return -1;
    }

    // Configure gyroscope range (+/- 250 deg/s)
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence by reading WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, 0x75); // WHO_AM_I register
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (who_am_i != 0x68) {
        fprintf(stderr, "Error: MPU-6050 not found (WHO_AM_I = 0x%x)\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MPU-6050 sensor found and initialized successfully.\n");

    // Main loop
    while (!terminate) {
        char buffer[14];
        int bytes_read = i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buffer, 14);

        if (bytes_read != 14) {
            fprintf(stderr, "Error: Could not read data from MPU-6050 (read %d bytes)\n", bytes_read);
            // Attempt to re-initialize the sensor
            if (init_mpu6050() < 0) {
                fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Parse data
        int16_t accel_x = (buffer[0] << 8) | buffer[1];
        int16_t accel_y = (buffer[2] << 8) | buffer[3];
        int16_t accel_z = (buffer[4] << 8) | buffer[5];
        int16_t temperature = (buffer[6] << 8) | buffer[7];
        int16_t gyro_x = (buffer[8] << 8) | buffer[9];
        int16_t gyro_y = (buffer[10] << 8) | buffer[11];
        int16_t gyro_z = (buffer[12] << 8) | buffer[13];

        // Print data
        printf("Accel: X=%6d, Y=%6d, Z=%6d  Temp=%6d  Gyro: X=%6d, Y=%6d, Z=%6d\n",
               accel_x, accel_y, accel_z, temperature, gyro_x, gyro_y, gyro_z);

        gpioDelay(100); // 100 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

