#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variable for I2C handle
int i2c_handle = -1;

// Function prototypes
int read_sht40(int i2c_handle, float *temperature, float *humidity);
uint8_t calculate_crc(const uint8_t *data, int len);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature and humidity from SHT40 sensor
int read_sht40(int i2c_handle, float *temperature, float *humidity) {
    uint8_t data[6];
    int result;

    // Send measurement command
    result = i2cWriteByte(i2c_handle, MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Extract raw temperature and humidity values
    uint16_t raw_temperature = (data[0] << 8) | data[1];
    uint16_t raw_humidity = (data[3] << 8) | data[4];

    // Validate CRC checksums
    if (calculate_crc(data, 2) != data[2] || calculate_crc(data + 3, 2) != data[5]) {
        fprintf(stderr, "CRC checksum failure\n");
        return -1;
    }

    // Convert raw values to temperature and humidity
    *temperature = -45.0 + 175.0 * raw_temperature / 65535.0;
    *humidity = -6.0 + 125.0 * raw_humidity / 65535.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;

    // Main loop
    while (1) {
        // Read temperature and humidity
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            // Print temperature and humidity
            printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Error reading SHT40 sensor\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // This point will not be reached unless there is an error or the program is interrupted.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

