#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD_SIZE 2
#define MEASURE_CMD {0x36, 0x08}
#define DATA_FRAME_SIZE 9
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define SLEEP_SECONDS 1
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t differential_pressure;
    int16_t temperature;
    uint16_t scale_factor_pressure;
    uint16_t scale_factor_temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
int validate_crc(const uint8_t *data, size_t len);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = CRC_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to the sensor
int send_measurement_command() {
    char cmd[MEASURE_CMD_SIZE] = MEASURE_CMD;
    int result = i2cWriteDevice(i2c_handle, cmd, MEASURE_CMD_SIZE);
    if (result != MEASURE_CMD_SIZE) {
        fprintf(stderr, "Error sending measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1000); // Wait 1 ms
    return 0;
}

// Read sensor data from I2C bus
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, DATA_FRAME_SIZE);
    if (result != DATA_FRAME_SIZE) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Validate CRC checksum
int validate_crc(const uint8_t *data, size_t len) {
    uint8_t crc = crc8(data, len - 1);
    if (crc != data[len - 1]) {
        fprintf(stderr, "CRC checksum error\n");
        return -1;
    }
    return 0;
}

// Convert raw data to physical units
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    sensor_data->differential_pressure = (int16_t)((data[0] << 8) | data[1]);
    sensor_data->temperature = (int16_t)((data[3] << 8) | data[4]);
    sensor_data->scale_factor_pressure = (uint16_t)((data[6] << 8) | data[7]);
    sensor_data->scale_factor_temperature = (uint16_t)((data[6] << 8) | data[7]);

    // Basic sanity checks
    if (sensor_data->scale_factor_pressure == 0 || sensor_data->scale_factor_temperature == 0) {
        fprintf(stderr, "Invalid scale factors\n");
        return -1;
    }

    return 0;
}

// Log data to CSV file
int log_data(const sensor_data_t *sensor_data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    float pressure_pa = (float)sensor_data->differential_pressure / sensor_data->scale_factor_pressure;
    float temperature_c = (float)sensor_data->temperature / sensor_data->scale_factor_temperature;

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure_pa, temperature_c);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
