        cleanup();
        return 1;
    }

    // Write header row if the file is new
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Differential Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    // Main loop
    uint8_t data[DATA_FRAME_SIZE];
    sensor_data_t sensor_data;
    while (!terminate) {
        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Validate CRC checksum
        if (validate_crc(data, DATA_FRAME_SIZE) != 0) {
            fprintf(stderr, "CRC checksum error, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Convert data
        if (convert_data(data, &sensor_data) != 0) {
            fprintf(stderr, "Error converting data, retrying...\n");
            gpioDelay(1000000); // Wait 1 second before retrying
            continue;
        }

        // Log data
