#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define TEMPERATURE_OFFSET -45.0
#define TEMPERATURE_SCALE 175.0
#define HUMIDITY_SCALE 100.0
