int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_HIGH_REPEATABILITY;
    uint8_t buf[6];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (i2c_write(fd, &cmd, 1) != 0) {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
            continue;
        }

        usleep(10000); // Wait 10 ms for measurement

        if (i2c_read(fd, buf, 6) != 0) {
