            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
            retries--;
            continue;
        }

        // Convert data
        uint16_t raw_temperature = (buf[0] << 8) | buf[1];
        uint16_t raw_humidity = (buf[3] << 8) | buf[4];

