// Global variables
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float pressure_pa;
    float temperature_c;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint8_t command, uint8_t arg);
int read_data(int handle, uint8_t *data, int count);
sensor_data_t process_data(uint8_t *data);
int log_data(sensor_data_t data);
