// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command with retry
int send_command(int handle, uint8_t command, uint8_t arg) {
    char buf[2];
    buf[0] = command;
    buf[1] = arg;
    int retries = RETRY_COUNT;
    int delay_ms = BACKOFF_BASE_MS;

    while (retries > 0) {
        int result = i2cWriteDevice(handle, buf, 2);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", RETRY_COUNT - retries + 1, result);
            retries--;
