#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7015_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_S 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_command(int handle, int command);
int read_i2c_data(int handle, char *data, int count);
int read_sensor_data(int handle, float *temperature, float *humidity);
float convert_temperature(unsigned int raw_temp);
float convert_humidity(unsigned int raw_humidity);
int log_sensor_data(float temperature, float humidity);
void print_sensor_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SI7015_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("sensor_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &temperature, &humidity) == 0) {
            print_sensor_data(temperature, humidity);
            log_sensor_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0); // Sleep for 5 seconds
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %s\n", bus, addr, strerror(errno));
        return -1;
    }
    return handle;
}

// Write I2C command
int write_i2c_command(int handle, int command) {
    int result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command 0x%02X: %s\n", command, strerror(errno));
        return -1;
    }
    return 0;
}

// Read I2C data
int read_i2c_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read %d bytes: %s\n", count, strerror(errno));
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, float *temperature, float *humidity) {
    char data[2];
    unsigned int raw_temp, raw_humidity;
    int retries = RETRY_COUNT;

    // Read temperature
    if (write_i2c_command(handle, TEMP_CMD) != 0) return -1;
    gpioSleep(PI_TIME_RELATIVE, 0, 20000); // Wait 20ms
    if (read_i2c_data(handle, data, 2) != 0) return -1;
    raw_temp = (data[0] << 8) | data[1];
    *temperature = convert_temperature(raw_temp);

    // Read humidity
    if (write_i2c_command(handle, HUMID_CMD) != 0) return -1;
    gpioSleep(PI_TIME_RELATIVE, 0, 20000); // Wait 20ms
    if (read_i2c_data(handle, data, 2) != 0) return -1;
    raw_humidity = (data[0] << 8) | data[1];
    *humidity = convert_humidity(raw_humidity);

    return 0;
}

// Convert raw temperature to Celsius
float convert_temperature(unsigned int raw_temp) {
    return (175.72 * raw_temp / 65536.0) - 46.85;
}

// Convert raw humidity to %RH
float convert_humidity(unsigned int raw_humidity) {
    float humidity = (125.0 * raw_humidity / 65536.0) - 6.0;
    if (humidity < 0.0) humidity = 0.0;
    if (humidity > 100.0) humidity = 100.0;
    return humidity;
}

// Log sensor data to file
int log_sensor_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Print sensor data to console
void print_sensor_data(float temperature, float humidity) {
    printf("Temperature: %.2f C, Humidity: %.2f %%RH\n", temperature, humidity);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    terminate = 1;
}

