#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define DATA_LENGTH 9
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR_REG 0x00
#define PRESSURE_REG 0x03
#define TEMPERATURE_REG 0x06

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t stop_flag = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int sdp800_init(int fd);
int read_sdp800_data(int fd, sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t checksum);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SDP800 initialization function
int sdp800_init(int fd) {
    uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    if (write(fd, cmd, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(45000); // Wait 45 ms
    return 0;
}

// Function to read data from SDP800 sensor
int read_sdp800_data(int fd, sensor_data_t *data) {
    uint8_t buffer[DATA_LENGTH];
    if (read(fd, buffer, DATA_LENGTH) != DATA_LENGTH) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Extract raw data
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    // CRC Validation
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "CRC validation failed for pressure data\n");
        return -1;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC validation failed for temperature data\n");
        return -1;
    }
    if (!validate_crc(buffer + 6, 2, buffer[8])) {
        fprintf(stderr, "CRC validation failed for scale factor data\n");
        return -1;
    }

    return 0;
}

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
