// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASURE_CMD 0x2C06
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define TEMP_MIN -45.0
#define TEMP_MAX 130.0
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_FILE "error_log.txt"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *data, int count);
uint8_t calculate_crc(const char *data, int len);
float convert_to_celsius(uint16_t raw_temp);
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);

// Structure for grouping I2C configuration
typedef struct {
    int bus;
    int addr;
} i2c_config_t;

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus.");
        return -1;
    }
    return 0;
}

// Send command to STS30
int send_command(int handle, uint16_t command) {
    char cmd[2];
    cmd[0] = (command >> 8) & 0xFF;
    cmd[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to write command to I2C.");
        return -1;
    }
    return 0;
}

// Read data from STS30
int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        log_error("Failed to read data from I2C.");
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Convert raw temperature to Celsius
float convert_to_celsius(uint16_t raw_temp) {
    return TEMP_MIN + (TEMP_MAX - TEMP_MIN) * (raw_temp / 65535.0);
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        log_error("Failed to open log file.");
        return -1;
    }

    fprintf(fp, "%s, %.2f\n", timestamp, temperature);
    fclose(fp);
    return 0;
}

// Log error to file
int log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen(ERROR_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return -1;
    }

    fprintf(fp, "%s, %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASURE_CMD) != 0) {
            log_error("Failed to send measurement command.");
            break;
        }

        // Wait for conversion
        gpioDelay(15000); // 15 ms

        // Read data
        char data[3];
        if (read_data(i2c_handle, data, 3) != 0) {
            log_error("Failed to read temperature data.");
            break;
        }

        // Validate CRC
        uint8_t crc = calculate_crc(data, 2);
        if (crc != (uint8_t)data[2]) {
            log_error("CRC checksum mismatch.");
            break;
        }

        // Convert to Celsius
        uint16_t raw_temp = (data[0] << 8) | data[1];
        float temperature = convert_to_celsius(raw_temp);

        // Log temperature
        if (log_temperature(temperature) != 0) {
            log_error("Failed to log temperature.");
            break;
        }

        printf("Temperature: %.2f °C\n", temperature);

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

