#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_ioctl(int fd, int cmd, int arg);
int i2c_write(int fd, uint8_t *data, int len);
int i2c_read(int fd, uint8_t *data, int len);
uint8_t calculate_crc(uint8_t data[], int len);
int validate_crc(uint8_t data[], int len);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_humidity);
int read_sht40(int fd, float *temperature, float *humidity);
int log_data(FILE *fp, float temperature, float humidity);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C ioctl function
int i2c_ioctl(int fd, int cmd, int arg) {
    if (ioctl(fd, cmd, arg) < 0) {
        perror("Error in ioctl");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// CRC-8 calculation function
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Temperature conversion function
float convert_temperature(uint16_t raw_temp) {
    return -45.0 + 175.0 * (float)raw_temp / 65535.0;
}

// Humidity conversion function
float convert_humidity(uint16_t raw_humidity) {
    return 100.0 * (float)raw_humidity / 65535.0;
}

// Read SHT40 function
int read_sht40(int fd, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    // Send measurement command
    if (i2c_write(fd, &cmd, 1) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    // Wait for measurement (at least 8.5 ms)
    usleep(8500);

    // Read 6 bytes of data
    if (i2c_read(fd, data, 6) < 0) {
        fprintf(stderr, "Error reading data from SHT40\n");
        return -1;
    }

    // Validate CRC
