#include <errno.h>

// SHT40 I2C address
#define SHT40_ADDR 0x44

// Measurement command (High Repeatability)
#define MEASURE_CMD 0xFD

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_ioctl(int fd, int cmd, int arg);
