        return -1;
    }
    return fd;
}

// I2C ioctl function
int i2c_ioctl(int fd, int cmd, int arg) {
    if (ioctl(fd, cmd, arg) < 0) {
        perror("Error in ioctl");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, uint8_t *data, int len) {
    if (write(fd, data, len) != len) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
