#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Structure for sensor data
typedef struct {
    time_t timestamp;
    float temperature;
    float humidity;
} SensorData;

// Circular buffer
SensorData data_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_sensor_data(float *temperature, float *humidity);
void control_fan(float temperature);
void log_data(float temperature, float humidity);
void print_buffer();
void signal_handler(int signal);

// Function to read sensor data with retries and hysteresis
int read_sensor_data(float *temperature, float *humidity) {
    int retries = 0;
    int status;
    uint8_t cmd;
    uint8_t data[2];
    int raw_temperature, raw_humidity;

    // Trigger temperature measurement
    cmd = 0xE3;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByte(i2c_handle, cmd);
        if (status == 0) break;
        gpioDelay(10); // Wait 10 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to trigger temperature measurement after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10 ms)

    // Read temperature data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (status == 2) break;
        gpioDelay(10); // Wait 10 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to read temperature data after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    raw_temperature = (data[0] << 8) | data[1];

    // Trigger humidity measurement
    cmd = 0xE5;
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByte(i2c_handle, cmd);
        if (status == 0) break;
        gpioDelay(10); // Wait 10 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to trigger humidity measurement after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10 ms)

    // Read humidity data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadDevice(i2c_handle, (char *)data, 2);
        if (status == 2) break;
        gpioDelay(10); // Wait 10 ms
        retries++;
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: Failed to read humidity data after %d retries.\n", RETRY_COUNT);
        return -1;
    }
    raw_humidity = (data[0] << 8) | data[1];

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * raw_temperature / 65536.0 - 46.85;
    *humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return 0;
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log sensor data to the circular buffer
