#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD40 I2C address
#define SCD40_ADDR 0x62

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_device();
int send_command(uint16_t command);
int read_data(uint8_t *data);
int verify_crc(uint8_t data[], int len);
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int log_data(uint16_t co2, float temperature, float humidity);
void signal_handler(int signal);

// CRC-8 polynomial
#define CRC_POLYNOMIAL 0x31

// CRC-8 initialization value
#define CRC_INITIALIZATION 0xFF

// Function to calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIALIZATION;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send a command to the SCD40
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send command 0x%04X: %d\n", command, result);
        return -1;
    }
    return 0;
}

// Function to read data from the SCD40
int read_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to verify the CRC-8 checksum
int verify_crc(uint8_t data[], int len) {
    uint8_t crc = calculate_crc(data, len);
    if (crc != data[len]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }
    return 0;
}

// Function to read CO2, temperature, and humidity
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t data[9];
    if (read_data(data) != 0) {
        return -1;
    }

    if (verify_crc(data, 2) != 0 || verify_crc(data + 3, 2) != 0 || verify_crc(data + 6, 2) != 0) {
        return -1;
    }

    *co2 = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t raw_humidity = (data[6] << 8) | data[7];

    *temperature = -45.0 + 175.0 * (float)raw_temperature / 65535.0;
    *humidity = 100.0 * (float)raw_humidity / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(uint16_t co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);
    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, stopping...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Send Start Periodic Measurement command
    if (send_command(0x21B1) != 0) {
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Wait for 1 second
    gpioDelay(1000000); // 1 second

    uint16_t co2;
    float temperature, humidity;

    // Main loop
    while (!terminate) {
        // Check data ready flag
        char cmd[2] = {0xE4, 0xB8};
        if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
            fprintf(stderr, "Failed to send data ready command\n");
            break;
        }
        gpioDelay(1000); // Small delay
        char data[1] = {0};
        if (i2cReadDevice(i2c_handle, data, 1) != 1) {
            fprintf(stderr, "Failed to read data ready flag\n");
            break;
        }

        if (data[0] & 0x01) {
            // Read measurement
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity);
                printf("CO2: %d ppm, Temperature: %.2f C, Humidity: %.2f %%\n", co2, temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read measurement\n");
            }
        } else {
            //printf("Data not ready yet\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000);
    }

    // Stop periodic measurement
    if (send_command(0x3F86) != 0) {
        fprintf(stderr, "Failed to stop periodic measurement\n");
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    // Close log file
    fclose(log_file);

    return 0;
}

