#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define GPIO_PIN 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 5
#define TIMEOUT_US 50000 // 50ms timeout
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define MAX_FAILURES 3

static volatile int running = 1;
static FILE *log_file = NULL;
static int failure_count = 0;

// Structure to hold the last edge time
typedef struct {
    uint32_t last_tick;
} EdgeData;

static EdgeData edge_data = {0};

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the log file
FILE *open_log_file() {
    FILE *file = fopen(LOG_FILE, "a");
    if (file == NULL) {
        perror("Error opening log file");
        return NULL;
    }
    return file;
}

// Function to get the current timestamp in ISO 8601 format
char *get_iso8601_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp;
}

// Function to read the temperature from the TMP05 sensor
float read_temperature() {
    uint32_t start_tick, end_tick, high_tick;
    uint32_t high_time, total_time;

    // Wait for the start of the PWM cycle
    start_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 0) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for start of PWM cycle\n");
            return -1.0; // Indicate error
        }
    }

    // Measure the high time
    high_tick = gpioTick();
    while (gpioRead(GPIO_PIN) == 1) {
        if (gpioTick() - high_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for end of PWM cycle\n");
            return -1.0; // Indicate error
        }
    }
    end_tick = gpioTick();

    high_time = end_tick - high_tick;
    total_time = end_tick - start_tick;

    // Check for division by zero
    if (total_time == 0) {
        fprintf(stderr, "Total time is zero, cannot calculate temperature\n");
        return -1.0; // Indicate error
    }

    // Calculate the temperature
    float temperature = 4215.0 - (2143.0 * (float)high_time / (float)total_time);

    return temperature;
}

// Function to log the temperature to the file
void log_temperature(float temperature) {
    char timestamp[30];
    get_iso8601_timestamp(timestamp);

    if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
        fprintf(log_file, "%s SENSOR MALFUNCTION: Temperature out of range: %.2f\n", timestamp, temperature);
        fprintf(stderr, "%s SENSOR MALFUNCTION: Temperature out of range: %.2f\n", timestamp, temperature);
        failure_count++;
        if (failure_count >= MAX_FAILURES) {
            fprintf(log_file, "%s SENSOR MALFUNCTION: Too many consecutive failures\n", timestamp);
            fprintf(stderr, "%s SENSOR MALFUNCTION: Too many consecutive failures\n", timestamp);
            failure_count = 0; // Reset the counter after logging the error
        }
    } else {
        fprintf(log_file, "%s Temperature: %.2f\n", timestamp, temperature);
        failure_count = 0; // Reset the failure count on successful read
    }
    fflush(log_file); // Ensure data is written to the file immediately
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = open_log_file();
    if (log_file == NULL) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO pin as input
    gpioSetMode(GPIO_PIN, PI_INPUT);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = read_temperature();

        if (temperature >= 0) {
            log_temperature(temperature);
        } else {
            char timestamp[30];
            get_iso8601_timestamp(timestamp);
            fprintf(log_file, "%s ERROR: Failed to read temperature\n", timestamp);
            fprintf(stderr, "%s ERROR: Failed to read temperature\n", timestamp);
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Clean up
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

