#define RETRY_DELAY 1
#define LOG_INTERVAL 5 // seconds
#define SINUSOIDAL_PERIOD 3600 // seconds (1 hour)

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
SensorData convert_raw_data(const uint8_t *data);
SensorData apply_sinusoidal_offset(SensorData data);
int log_data(SensorData data);
void signal_handler(int signal);
void cleanup();

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to send measurement command
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to send measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(15); // Wait for at least 15 ms
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to calculate CRC
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate CRC
int validate_crc(const uint8_t *data, int len) {
    uint8_t crc = calculate_crc(data, len);
    return (crc == data[len]);
}

// Function to convert raw data to temperature and humidity
SensorData convert_raw_data(const uint8_t *data) {
    SensorData sensor_data;
    int32_t raw_temperature = (data[0] << 8) | data[1];
    int32_t raw_humidity = (data[3] << 8) | data[4];

    sensor_data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    sensor_data.humidity = 100.0 * (float)raw_humidity / 65535.0;

    return sensor_data;
}

// Function to apply sinusoidal offset
SensorData apply_sinusoidal_offset(SensorData data) {
    time_t now = time(NULL);
    double time_in_period = (double)now % SINUSOIDAL_PERIOD;
    double offset_temperature = 2.0 * sin(2.0 * M_PI * time_in_period / SINUSOIDAL_PERIOD);
    double offset_humidity = 5.0 * sin(2.0 * M_PI * time_in_period / SINUSOIDAL_PERIOD);

    data.temperature += offset_temperature;
    data.humidity += offset_humidity;

    return data;
}

// Function to log data
int log_data(SensorData data) {
    time_t now = time(NULL);
    struct tm *utc_time = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

