    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    uint8_t sensor_data[6];
    SensorData processed_data;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            // Send measurement command
            if (send_measurement_command() == 0) {
                // Read sensor data
                if (read_sensor_data(sensor_data) == 0) {
                    // Validate CRC
                    if (validate_crc(sensor_data, 2) && validate_crc(sensor_data + 3, 2)) {
                        // Convert raw data
                        processed_data = convert_raw_data(sensor_data);

                        // Apply sinusoidal offset
                        processed_data = apply_sinusoidal_offset(processed_data);

                        // Log data
                        if (log_data(processed_data) != 0) {
                            fprintf(stderr, "Failed to log data\n");
                        }
                        break; // Exit retry loop on success
                    } else {
                        fprintf(stderr, "CRC validation failed, retry %d\n", retry + 1);
                    }
                } else {
                    fprintf(stderr, "Failed to read sensor data, retry %d\n", retry + 1);
                }
            } else {
                fprintf(stderr, "Failed to send measurement command, retry %d\n", retry + 1);
            }

            retry++;
            if (retry < RETRY_COUNT) {
                gpioDelay(RETRY_DELAY * 1000); // Delay in milliseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries, logging NaN values\n", RETRY_COUNT);
            time_t now = time(NULL);
            struct tm *utc_time = gmtime(&now);
            char timestamp[32];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", utc_time);
            fprintf(log_file, "%s,NaN,NaN\n", timestamp);
            fflush(log_file);
        }

        gpioDelay(LOG_INTERVAL * 1000); // Delay in milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

