#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_MS 45
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL 0xFF
#define CSV_FILENAME "airflow.csv"

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t checksum);
int convert_data(const char *buffer, sensor_data_t *sensor_data);
float calculate_pressure(int16_t raw_pressure);
float calculate_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INITIAL;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// CRC validation function
int validate_crc(const char *data, int len, uint8_t checksum) {
    uint8_t calculated_crc = calculate_crc(data, len);
    return (calculated_crc == checksum);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
int convert_data(const char *buffer, sensor_data_t *sensor_data) {
    sensor_data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    sensor_data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);
    sensor_data->scale_factor = (uint16_t)((buffer[6] << 8) | buffer[7]);

    // CRC Validation
    if (!validate_crc(buffer, 2, buffer[2])) {
        fprintf(stderr, "CRC check failed for pressure data\n");
        return -1;
    }
    if (!validate_crc(buffer + 3, 2, buffer[5])) {
        fprintf(stderr, "CRC check failed for temperature data\n");
        return -1;
    }
    if (!validate_crc(buffer + 6, 2, buffer[8])) {
        fprintf(stderr, "CRC check failed for scale factor data\n");
        return -1;
    }

    return 0;
}

// Calculate pressure in Pascals
float calculate_pressure(int16_t raw_pressure) {
    // Scaling factor is already included in the raw_pressure value
    return (float)raw_pressure / 10.0; // Scale factor is 10
}

// Calculate temperature in Celsius
float calculate_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0; // Scaling factor is 200
}

// Log data to CSV file
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(csv_file); // Ensure data is written immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    csv_file = fopen(CSV_FILENAME, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }

    // Main loop
    char buffer[9];
    sensor_data_t sensor_data;
    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            break;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Error reading data\n");
            break;
        }

        // Convert data
        if (convert_data(buffer, &sensor_data) != 0) {
            fprintf(stderr, "Error converting data\n");
            break;
        }

        // Calculate pressure and temperature
        float pressure = calculate_pressure(sensor_data.pressure);
        float temperature = calculate_temperature(sensor_data.temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

