        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Error sending measurement command\n");
            break;
        }

        // Wait for conversion time
        gpioDelay(CONVERSION_TIME_MS * 1000); // Convert ms to microseconds

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Error reading data\n");
            break;
        }

        // Convert data
        if (convert_data(buffer, &sensor_data) != 0) {
            fprintf(stderr, "Error converting data\n");
            break;
        }

        // Calculate pressure and temperature
        float pressure = calculate_pressure(sensor_data.pressure);
        float temperature = calculate_temperature(sensor_data.temperature);

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
            break;
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

