    while (!terminate) {
        uint8_t data[6];
        uint16_t raw_temperature, raw_humidity;
        float temperature, humidity;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Error: Failed to send measurement command, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        // Wait for measurement (at least 15 ms)
