        // Read sensor data
        if (read_sensor_data(data) != 0) {
            fprintf(stderr, "Error: Failed to read sensor data, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
