#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define SI7021_ADDR 0x40
#define SI7021_RESET_CMD 0xFE

volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write(int fd, uint8_t reg);
int i2c_read(int fd, uint8_t *data, int len);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t read_sensor_data(int fd);
char* format_iso8601(char *buf, size_t buf_size);
void log_data(const char *timestamp, float temperature, float humidity);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, SI7021_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", SI7021_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

// I2C write function
int i2c_write(int fd, uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(fd, buf, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int len) {
    if (read(fd, data, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read sensor data
sensor_data_t read_sensor_data(int fd) {
    sensor_data_t data = {0.0, 0.0};
    uint8_t raw_data[3];
    uint8_t cmd;

    // Read temperature
    cmd = 0xF3; // No Hold Master Temperature command
    if (i2c_write(fd, cmd) < 0) {
        fprintf(stderr, "Error writing temperature command\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    if (i2c_read(fd, raw_data, 3) < 0) {
        fprintf(stderr, "Error reading temperature data\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    if (crc8(raw_data, 2) != raw_data[2]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    uint16_t raw_temperature = (raw_data[0] << 8) | raw_data[1];
    data.temperature = 175.72 * raw_temperature / 65536.0 - 46.85;

    // Read humidity
    cmd = 0xF5; // No Hold Master Humidity command
    if (i2c_write(fd, cmd) < 0) {
        fprintf(stderr, "Error writing humidity command\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    usleep(100000); // Wait for measurement (at least 85ms)
    if (i2c_read(fd, raw_data, 3) < 0) {
        fprintf(stderr, "Error reading humidity data\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    if (crc8(raw_data, 2) != raw_data[2]) {
        fprintf(stderr, "Humidity CRC check failed\n");
        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }
    uint16_t raw_humidity = (raw_data[0] << 8) | raw_data[1];
    data.humidity = 125.0 * raw_humidity / 65536.0 - 6.0;

    return data;
}

// Function to format timestamp in ISO 8601 format
char* format_iso8601(char *buf, size_t buf_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(buf, buf_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return buf;
}

// Function to log data to CSV file
void log_data(const char *timestamp, float temperature, float humidity) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(log_file); // Ensure data is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Received signal %d, shutting down...\n", signal);
}

int main() {
    char timestamp[32];
    sensor_data_t sensor_values;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen("environment.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read sensor data
        sensor_values = read_sensor_data(i2c_fd);

        // Format timestamp
        format_iso8601(timestamp, sizeof(timestamp));

        // Log data or error
        if (sensor_values.temperature == -999.0 || sensor_values.humidity == -999.0) {
            log_data("ERROR", -999.0, -999.0);
            fprintf(stderr, "Error reading sensor data, logging ERROR\n");
        } else {
            log_data(timestamp, sensor_values.temperature, sensor_values.humidity);
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

