#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define CONVERSION_TIME_US 10000 // 10ms
#define CRC_POLYNOMIAL 0x31
#define SCALE_FACTOR 60.0
#define LOG_FILE "airflow.dat"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} SensorData;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t crc);
SensorData convert_data(const char *buffer);
int log_data(FILE *file, SensorData data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    int handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const char *data, int len, uint8_t crc) {
    return (calculate_crc(data, len) == crc);
}

// Convert raw data to pressure and temperature
SensorData convert_data(const char *buffer) {
    SensorData data;
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

    data.pressure = (float)raw_pressure / SCALE_FACTOR - 1000.0;
    data.temperature = (float)raw_temperature / 200.0 - 45.0;

    return data;
}

// Log data to file
int log_data(FILE *file, SensorData data) {
    if (fwrite(&data.pressure, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&data.temperature, sizeof(float), 1, file) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus();
    if (i2c_handle < 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char buffer[9];

        // Write command
        if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to write command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for conversion
        gpioDelay(CONVERSION_TIME_US);

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(buffer, 2, buffer[2]) || !validate_crc(buffer + 3, 2, buffer[5])) {
            fprintf(stderr, "CRC validation failed, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert data
        SensorData data = convert_data(buffer);

        // Log data
        if (log_data(log_file, data) != 0) {
            fprintf(stderr, "Failed to log data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        fflush(log_file); // Flush the buffer to ensure data is written

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

