#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3603
#define SCALE_FACTOR 60.0
#define LOG_FILE "pressure_log.txt"
#define SLEEP_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t checksum;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_command(int handle, uint16_t command);
int read_sensor_data(int handle, sensor_data_t *data);
float convert_pressure(int16_t raw_pressure);
int validate_crc(uint8_t data[], int len, uint8_t checksum);
int log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;
    float pressure;

    // Main loop
    while (!terminate) {
        // Send continuous measurement command
        if (send_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to send command\n");
            log_pressure(-999.0); // Log error value
        } else {
            // Read sensor data
            if (read_sensor_data(i2c_handle, &sensor_data) != 0) {
                fprintf(stderr, "Failed to read sensor data\n");
                log_pressure(-999.0); // Log error value
            } else {
                // Convert pressure
                pressure = convert_pressure(sensor_data.pressure);

                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                }
            }
        }

        // Sleep for 5 seconds
        sleep(SLEEP_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send command to the sensor
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to I2C device: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int handle, sensor_data_t *data) {
    char buf[9];
    int result = i2cReadDevice(handle, buf, 9);
    if (result != 9) {
        fprintf(stderr, "Failed to read from I2C device: %d\n", result);
        return 1;
    }

    // Extract data
    data->pressure = (buf[0] << 8) | buf[1];
    data->temperature = (buf[3] << 8) | buf[4];
    data->checksum = buf[8];

    // Validate CRC
    uint8_t data_to_crc[2] = {buf[0], buf[1]};
    if (!validate_crc(data_to_crc, 2, buf[2])) {
        fprintf(stderr, "Pressure CRC validation failed\n");
        return 1;
    }

    uint8_t data_to_crc2[2] = {buf[3], buf[4]};
    if (!validate_crc(data_to_crc2, 2, buf[5])) {
        fprintf(stderr, "Temperature CRC validation failed\n");
        return 1;
    }

    return 0;
}

// Convert raw pressure to Pascal
float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / SCALE_FACTOR;
}

// Validate CRC-8 checksum
int validate_crc(uint8_t data[], int len, uint8_t checksum) {
    uint8_t calculated_crc = crc8(data, len);
    return calculated_crc == checksum;
}

// Log pressure to file
int log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

