// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x28
#define FAN_GPIO 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define MIN_FLOW_RATE 0.0   // SLPM
#define MAX_FLOW_RATE 10.0  // SLPM
#define MIN_DUTY_CYCLE 0.0  // %
#define MAX_DUTY_CYCLE 100.0 // %
#define MIN_RAW_FLOW 1638    // Counts
#define MAX_RAW_FLOW 14745   // Counts
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_sensor(int i2c_handle, uint16_t *raw_flow);
float convert_to_flow_rate(uint16_t raw_flow);
void set_fan_speed(int gpio_pin, float flow_rate);
void log_data(FILE *log_file, uint16_t raw_flow, float flow_rate);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Reads the sensor data from the I2C device
int read_sensor(int i2c_handle, uint16_t *raw_flow) {
    char buffer[2];
    int result;

    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *raw_flow = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Converts the raw flow reading to a flow rate in SLPM
float convert_to_flow_rate(uint16_t raw_flow) {
    float flow_rate = (float)(raw_flow - MIN_RAW_FLOW) * (MAX_FLOW_RATE - MIN_FLOW_RATE) / (MAX_RAW_FLOW - MIN_RAW_FLOW) + MIN_FLOW_RATE;
    return flow_rate;
}

// Sets the fan speed based on the flow rate
void set_fan_speed(int gpio_pin, float flow_rate) {
    float duty_cycle = (flow_rate - MIN_FLOW_RATE) * (MAX_DUTY_CYCLE - MIN_DUTY_CYCLE) / (MAX_FLOW_RATE - MIN_FLOW_RATE) + MIN_DUTY_CYCLE;
    int pwm_value = (int)(duty_cycle * 255.0 / 100.0); // pigpio PWM range is 0-255

    gpioPWM(gpio_pin, pwm_value);
}

