void log_data(FILE *log_file, uint16_t raw_flow, float flow_rate) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f\n", now, flow_rate);
    fflush(log_file); // Ensure data is written to disk immediately
}

