#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// LPS33HW I2C address
#define LPS33HW_ADDR 0x5D

// LPS33HW register addresses
#define WHO_AM_I 0x0F
#define CTRL_REG1 0x10
#define PRESS_OUT_XL 0x28
#define PRESS_OUT_L 0x29
#define PRESS_OUT_H 0x2A
#define TEMP_OUT_L 0x2B
#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(int32_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int32_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void log_data(float pressure, float temperature);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the LPS33HW sensor
int init_lps33hw() {
    // Check WHO_AM_I register
    char who_am_i;
    if (i2cReadI2CBlockData(i2c_handle, WHO_AM_I, &who_am_i, 1) != 1) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0xB1) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xB1, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 for 10 Hz output rate and active mode
    char ctrl_reg1 = 0xB0; // 0b10110000
    if (i2cWriteI2CBlockData(i2c_handle, CTRL_REG1, &ctrl_reg1, 1) != 1) {
        fprintf(stderr, "Error writing to CTRL_REG1 register\n");
        return -1;
    }

    return 0;
}

// Read pressure data from the sensor
int read_pressure(int32_t *pressure) {
    char data[3];
    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, data, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    *pressure = (int32_t)data[0] | ((int32_t)data[1] << 8) | ((int32_t)data[2] << 16);
    return 0;
}

// Read temperature data from the sensor
int read_temperature(int16_t *temperature) {
    char data[2];
    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, data, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    *temperature = (int16_t)data[0] | ((int16_t)data[1] << 8);
    return 0;
}

// Convert raw pressure to hPa
float convert_pressure(int32_t raw_pressure) {
    return (float)raw_pressure / 4096.0;
}

// Convert raw temperature to Celsius
float convert_temperature(int16_t raw_temperature) {
    return 42.5 + (float)raw_temperature / 480.0;
}

// Log data to file
void log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() != 0) {
        fprintf(stderr, "LPS33HW initialization failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_pressure;
    int16_t raw_temperature;
    float pressure_hpa, temperature_celsius;

    // Main loop
    while (!terminate) {
        // Read pressure and temperature
        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            // Convert data
            pressure_hpa = convert_pressure(raw_pressure);
            temperature_celsius = convert_temperature(raw_temperature);

            // Log data
            log_data(pressure_hpa, temperature_celsius);

            printf("Pressure: %.2f hPa, Temperature: %.2f °C\n", pressure_hpa, temperature_celsius);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Delay for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

