#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define TEMP_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int read_temperature(int i2c_handle);
float convert_to_celsius(int raw_temp);
float calculate_average(float buffer[], int size);
void control_led(float average_temp);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to read temperature from STLM75
int read_temperature(int i2c_handle) {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1; // Indicate error
    }
    return raw_temp;
}

// Function to convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    // Swap bytes (little-endian to big-endian)
    int swapped_temp = ((raw_temp & 0xFF) << 8) | ((raw_temp & 0xFF00) >> 8);

    // Right-shift by 7 bits
    swapped_temp = swapped_temp >> 7;

    // Divide by 2
    return (float)swapped_temp / 2.0;
}

// Function to calculate the running average
float calculate_average(float buffer[], int size) {
    float sum = 0.0;
    for (int i = 0; i < size; i++) {
        sum += buffer[i];
    }
    return sum / size;
}

// Function to control the LED based on average temperature
void control_led(float average_temp) {
    if (average_temp > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read temperature
        int raw_temp = read_temperature(i2c_handle);
        if (raw_temp >= 0) {
            // Convert to Celsius
            float temperature = convert_to_celsius(raw_temp);

            // Update circular buffer
            temperature_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate average temperature
            float average_temp = calculate_average(temperature_buffer, BUFFER_SIZE);

            // Control LED
            control_led(average_temp);

            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

