#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define SCD30_CMD_START_CONT_MEAS 0x0010
#define SCD30_CMD_STOP_CONT_MEAS 0x0104
#define SCD30_CMD_READ_MEASUREMENT 0x0300
#define SCD30_CMD_GET_DATA_READY 0x0202

// Ventilation system states
typedef enum {
    OFF,
    LOW,
    HIGH
} VentilationState;

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int initialize_scd30();
int start_continuous_measurement();
int stop_continuous_measurement();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int is_data_ready();
uint8_t calculate_crc(const uint8_t *data, int len);
int log_data(uint16_t co2, float temperature, float humidity);
VentilationState determine_ventilation_state(uint16_t co2);
void signal_handler(int signal);

// CRC-8 checksum calculation
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0); // Bus 1, address 0x61, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize SCD30 sensor
int initialize_scd30() {
    // No specific initialization command in SCD30, just start continuous measurement
    return 0;
}

// Start continuous measurement
int start_continuous_measurement() {
    uint8_t cmd[2] = {(SCD30_CMD_START_CONT_MEAS >> 8) & 0xFF, SCD30_CMD_START_CONT_MEAS & 0xFF};
    uint8_t crc = calculate_crc(cmd, 2);
    uint8_t data[3] = {cmd[0], cmd[1], crc};

    int result = i2cWriteDevice(i2c_handle, (char *)data, 3);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write start continuous measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for command to be processed
    return 0;
}

// Stop continuous measurement
int stop_continuous_measurement() {
    uint8_t cmd[2] = {(SCD30_CMD_STOP_CONT_MEAS >> 8) & 0xFF, SCD30_CMD_STOP_CONT_MEAS & 0xFF};
    uint8_t crc = calculate_crc(cmd, 2);
    uint8_t data[3] = {cmd[0], cmd[1], crc};

    int result = i2cWriteDevice(i2c_handle, (char *)data, 3);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write stop continuous measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for command to be processed
    return 0;
}

// Read measurement data
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {(SCD30_CMD_READ_MEASUREMENT >> 8) & 0xFF, SCD30_CMD_READ_MEASUREMENT & 0xFF};
    uint8_t data[2] = {cmd[0], cmd[1]};

    int result = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    uint8_t buffer[18];
    result = i2cReadDevice(i2c_handle, (char *)buffer, 18);
    if (result != 18) {
        fprintf(stderr, "Error: Could not read measurement data: %d\n", result);
        return -1;
    }

    // CRC Check
    uint8_t crc_co2 = calculate_crc(buffer, 2);
    uint8_t crc_temperature = calculate_crc(buffer + 2, 2);
    uint8_t crc_humidity = calculate_crc(buffer + 4, 2);

    if (crc_co2 != buffer[2] || crc_temperature != buffer[4] || crc_humidity != buffer[6]) {
        fprintf(stderr, "Error: CRC mismatch\n");
        return -1;
    }

    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535;
    *humidity = 100 * ((float)((buffer[5] << 8) | buffer[6])) / 65535;

    return 0;
}

// Check if data is ready
int is_data_ready() {
    uint8_t cmd[2] = {(SCD30_CMD_GET_DATA_READY >> 8) & 0xFF, SCD30_CMD_GET_DATA_READY & 0xFF};
    uint8_t data[2] = {cmd[0], cmd[1]};

    int result = i2cWriteDevice(i2c_handle, (char *)data, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Could not write get data ready command: %d\n", result);
        return -1;
    }
    gpioDelay(1); // Small delay after writing the command

    uint8_t buffer[3];
    result = i2cReadDevice(i2c_handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: Could not read data ready data: %d\n", result);
        return -1;
    }

    uint16_t data_ready = (buffer[0] << 8) | buffer[1];
    return (data_ready & 0x0001) ? 1 : 0;
}

// Log data to file
int log_data(uint16_t co2, float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%d,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Determine ventilation state
VentilationState determine_ventilation_state(uint16_t co2) {
    if (co2 < 800) {
        return OFF;
    } else if (co2 < 1200) {
        return LOW;
    } else {
        return HIGH;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, stopping measurement and cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (initialize_scd30() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Start continuous measurement
    if (start_continuous_measurement() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        stop_continuous_measurement();
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    uint16_t co2;
    float temperature, humidity;
    VentilationState ventilation_state = OFF;

    // Main loop
    while (!terminate) {
        // Check if data is ready
        if (is_data_ready() == 1) {
            // Read measurement data
            if (read_measurement(&co2, &temperature, &humidity) == 0) {
                // Log data
                log_data(co2, temperature, humidity);

                // Determine ventilation state
                VentilationState new_state = determine_ventilation_state(co2);
                if (new_state != ventilation_state) {
                    fprintf(log_file, "Ventilation State Change: %s\n", new_state == HIGH ? "HIGH" : (new_state == LOW ? "LOW" : "OFF"));
                    fflush(log_file);
                    ventilation_state = new_state;
                }
            } else {
                fprintf(stderr, "Error: Could not read measurement data\n");
            }
        } else {
            //fprintf(stderr, "Data not ready yet\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Stop continuous measurement
    if (stop_continuous_measurement() != 0) {
        fprintf(stderr, "Error: Could not stop continuous measurement\n");
    }

    // Close I2C bus
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

