// SDP32 I2C address
#define SDP32_ADDR 0x21

// Continuous measurement command
#define SDP32_MEASURE_CMD 0x362F

// CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
int running = 1;

// Structure to hold sensor data
typedef struct {
    int16_t raw_pressure;
    int16_t raw_temperature;
    uint16_t scale_factor;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t crc8(const uint8_t *data, int len);
int verify_crc(uint8_t received_crc, const uint8_t *data, int len);
float convert_pressure(int16_t raw_pressure, uint16_t scale_factor);
void log_data(float pressure_pa);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SDP32_ADDR, 0); // Bus 1, address 0x21, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the SDP32
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the SDP32
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Error reading data: %d\n", result);
        return -1;
    }
    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

