        if (read_data(i2c_handle, buffer, 9) == 0) {
            // Extract data
            sensor_data.raw_pressure = (buffer[0] << 8) | buffer[1];
            sensor_data.raw_temperature = (buffer[3] << 8) | buffer[4];
            sensor_data.scale_factor = (buffer[6] << 8) | buffer[7];

            // Verify CRC checksums
            if (verify_crc(buffer[2], buffer, 2) && verify_crc(buffer[5], buffer + 3, 2) && verify_crc(buffer[8], buffer + 6, 2)) {
                // Convert pressure to Pascal
                float pressure_pa = convert_pressure(sensor_data.raw_pressure, sensor_data.scale_factor);

                // Log the data
                log_data(pressure_pa);
            } else {
