// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define HDC1000_ADDR 0x40

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to configure the HDC1000 sensor
int config_hdc1000(int fd) {
    uint8_t config_data[2] = {0x00, 0x00}; // Reset command
    if (write(fd, config_data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    usleep(15000); // Wait for reset to complete

    config_data[0] = 0x02; // Configuration register address
    config_data[1] = 0x00; // Default configuration: Temperature and Humidity, 14-bit resolution
    if (write(fd, config_data, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }

    return 0;
}

// Function to read temperature and humidity data from the HDC1000
int read_hdc1000(int fd, float *temperature, float *humidity) {
    uint8_t trigger_data[1] = {0x00}; // Trigger measurement command
    uint8_t buffer[4];

    // Trigger measurement
    if (write(fd, trigger_data, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(20000); // Wait for conversion (at least 20 ms)

    // Read temperature and humidity data
    if (read(fd, buffer, 4) != 4) {
        perror("Error reading from I2C device");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_temperature = (buffer[0] << 8) | buffer[1];
    uint16_t raw_humidity = (buffer[2] << 8) | buffer[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, HDC1000_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Configure HDC1000
    if (config_hdc1000(i2c_fd) < 0) {
        fprintf(stderr, "Failed to configure HDC1000. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    float temperature, humidity;
    while (1) {
        if (read_hdc1000(i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        sleep(5);
    }

    return 0;
}

