    result = i2cReadI2CBlockData(i2c_handle, PRESSURE_REGISTER, buffer, 2);

    if (result < 0) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1.0; // Indicate an error
    }

    // Convert the raw data to a pressure value (replace with actual conversion formula)
    // This is a placeholder; refer to the MLX90833 datasheet for the correct formula.
    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
    float pressure = (float)raw_pressure * 0.1; // Example conversion

