#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// I2C address of the ICP-10101 sensor
#define ICP10101_ADDR 0x63

// I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Calibration data structure
typedef struct {
    uint16_t c0;
    uint16_t c1;
    uint16_t c00;
    uint16_t c10;
    uint16_t c01;
    uint16_t c11;
    uint16_t c20;
    uint16_t c21;
    uint16_t c30;
} calibration_data_t;

// Global variables
int i2c_handle;
calibration_data_t calibration;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_calibration_data(int i2c_handle, calibration_data_t *calibration);
int trigger_measurement(int i2c_handle);
int read_raw_data(int i2c_handle, int16_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, const calibration_data_t *calibration);
double compensate_pressure(int32_t raw_pressure, double temperature, const calibration_data_t *calibration);
void log_data(double temperature, double pressure);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to read calibration data from the sensor
int read_calibration_data(int i2c_handle, calibration_data_t *calibration) {
    char buf[8];
    int result = i2cReadI2CBlockData(i2c_handle, 0x50, buf, 8);

    if (result != 8) {
        fprintf(stderr, "Error reading calibration data: %d\n", result);
        return -1;
    }

    calibration->c0 = (buf[0] << 8) | buf[1];
    calibration->c1 = (buf[2] << 8) | buf[3];
    calibration->c00 = (buf[4] << 8) | buf[5];
    calibration->c10 = (buf[6] << 8) | buf[7];

    result = i2cReadI2CBlockData(i2c_handle, 0x60, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data (second block): %d\n", result);
        return -1;
    }

    calibration->c01 = (buf[0] << 8) | buf[1];
    calibration->c11 = (buf[2] << 8) | buf[3];
    calibration->c20 = (buf[4] << 8) | buf[5];
    calibration->c21 = (buf[6] << 8) | buf[7];

    result = i2cReadI2CBlockData(i2c_handle, 0x70, buf, 8);
    if (result != 8) {
        fprintf(stderr, "Error reading calibration data (third block): %d\n", result);
        return -1;
    }

    calibration->c30 = (buf[0] << 8) | buf[1];

    return 0;
}

// Function to trigger a high-precision measurement
int trigger_measurement(int i2c_handle) {
    int result = i2cWriteByteData(i2c_handle, 0x40, 0x07); // Command 0x40, parameter 0x07
    if (result != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        return -1;
    }
    gpioDelay(7); // Wait 7 ms
    return 0;
}

// Function to read raw temperature and pressure data
int read_raw_data(int i2c_handle, int16_t *temperature, int32_t *pressure) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading raw data: %d\n", result);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *pressure = ((uint32_t)buf[2] << 24) | ((uint32_t)buf[3] << 16) | ((uint32_t)buf[4] << 8) | (uint32_t)buf[5];

    return 0;
}

// Function to compensate temperature
double compensate_temperature(int32_t raw_temperature, const calibration_data_t *calibration) {
    double T_ref = 25.0; // Reference temperature
    double temp = (double)raw_temperature;
    double T_fine = 0.0;

    double c0 = (double)calibration->c0;
    double c1 = (double)calibration->c1;
    double c00 = (double)calibration->c00;
    double c10 = (double)calibration->c10;
    double c01 = (double)calibration->c01;
    double c11 = (double)calibration->c11;

    T_fine = c0 * 0.5 + c1 * temp;

    return T_ref + (T_fine / 2.0) - 40.0;
}

// Function to compensate pressure
double compensate_pressure(int32_t raw_pressure, double temperature, const calibration_data_t *calibration) {
    double P_ref = 100000.0; // Reference pressure
    double temp = (double)raw_pressure;
    double T_fine = 0.0;

    double c00 = (double)calibration->c00;
    double c10 = (double)calibration->c10;
    double c01 = (double)calibration->c01;
    double c11 = (double)calibration->c11;
    double c20 = (double)calibration->c20;
    double c21 = (double)calibration->c21;
    double c30 = (double)calibration->c30;

    T_fine = c00 + c10 * temperature + c01 * temperature * temperature + c11 * temperature * temperature * temperature;

    double p = c20 + c21 * temperature + c30 * temperature * temperature;
    p = p + temp * (c00 + c10 * temperature + c01 * temperature * temperature + c11 * temperature * temperature * temperature);

    return P_ref + p;
}

// Function to log data with timestamp
void log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n", timestamp, temperature, pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ICP10101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_handle, &calibration) != 0) {
        fprintf(stderr, "Failed to read calibration data. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int16_t raw_temperature;
        int32_t raw_pressure;
        double temperature, pressure;

        // Trigger measurement
        if (trigger_measurement(i2c_handle) != 0) {
            fprintf(stderr, "Failed to trigger measurement. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Read raw data
        if (read_raw_data(i2c_handle, &raw_temperature, &raw_pressure) != 0) {
            fprintf(stderr, "Failed to read raw data. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        // Check for sensor absence (all bytes 0xFF)
        if (raw_temperature == 0xFFFF && raw_pressure == 0xFFFFFFFF) {
            fprintf(stderr, "Sensor appears to be absent or not responding.\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature, &calibration);
        pressure = compensate_pressure(raw_pressure, temperature, &calibration);

        // Log data
        log_data(temperature, pressure);

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

