#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDRESS 0x60

// Define the pressure registers
#define PRESSURE_MSB_REG 0xAA
#define PRESSURE_LSB_REG 0xAB

// Define the scaling factor
#define SCALING_FACTOR 0.1

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to read a 16-bit value from the I2C device
int16_t read_i2c_word(int fd, uint8_t reg) {
    uint8_t buffer[2];
    int result;

    // Write the register address to the sensor
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Read two bytes from the sensor
    result = read(fd, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

// Function to convert the raw pressure value to kPa
float convert_to_kPa(int16_t raw_pressure) {
    return (float)raw_pressure * SCALING_FACTOR;
}

// Function to log the pressure reading with a timestamp
void log_pressure(float pressure_kPa) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("%s Pressure: %.2f kPa\n", timestamp, pressure_kPa);
}

int main() {
    int16_t raw_pressure;
    float pressure_kPa;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read the raw pressure value from the sensor
        raw_pressure = read_i2c_word(i2c_fd, PRESSURE_MSB_REG);
        if (raw_pressure == -1) {
            fprintf(stderr, "Error reading pressure from sensor, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert the raw pressure to kPa
        pressure_kPa = convert_to_kPa(raw_pressure);

        // Log the pressure reading
        log_pressure(pressure_kPa);

        // Wait for 1 second
        sleep(1);
    }

    // Close the I2C bus (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

