float convert_pressure(int16_t raw_pressure) {
    return (float)raw_pressure / 60.0;
}

// Temperature conversion function
float convert_temperature(int16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Data logging function
int log_data(float pressure, float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen("pressure_log.txt", "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Send measurement command
        uint8_t cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
        if (i2c_write(i2c_fd, cmd, 2) < 0) {
            fprintf(stderr, "Error writing measurement command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement
        usleep(45000); // 45 ms

        // Read data
        uint8_t data[9];
        if (i2c_read(i2c_fd, data, 9) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Validate CRC
        if (!validate_crc(data, 3) || !validate_crc(data + 3, 3) || !validate_crc(data + 6, 3)) {
            fprintf(stderr, "CRC validation failed, skipping data\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Convert data
        int16_t raw_pressure = (data[0] << 8) | data[1];
        int16_t raw_temperature = (data[3] << 8) | data[4];

        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Log data
        if (log_data(pressure, temperature) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Print data to console
        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        sleep(1); // Wait 1 second
    }

    // Close I2C bus and log file
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

