int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *raw_pressure);
uint8_t calculate_crc(const uint8_t *data, size_t length);
int verify_crc(const uint8_t *data, size_t length, uint8_t crc);
float convert_to_pressure(int16_t raw_pressure);
int log_data(float pressure);
void signal_handler(int signal);
void cleanup();

