            fprintf(stderr, "Failed to open log file for writing\n");
            return 1;
        }
        fprintf(log_file, "Timestamp,Pressure (Pa)\n");
    } else {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file for appending\n");
            return 1;
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);
    log_file = NULL; // Reset log_file after closing

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

