#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MLX90821_ADDR 0x40
#define PRESSURE_REG 0x00
#define SAFE_PRESSURE_MIN 200.0  // kPa
#define SAFE_PRESSURE_MAX 250.0  // kPa
#define SCALE_FACTOR 0.01       // kPa/raw unit
#define LOG_FILE "pressure_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_pressure(float *pressure);
void log_pressure(float pressure);
void check_pressure_range(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    float safe_pressure_min;
    float safe_pressure_max;
    float scale_factor;
    char *log_file;
} config_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90821_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read pressure from the sensor
int read_pressure(float *pressure) {
    char buf[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, PRESSURE_REG, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    uint16_t raw_pressure = (buf[0] << 8) | buf[1];

    // Convert raw value to kPa
    *pressure = (float)raw_pressure * SCALE_FACTOR;

    return 0;
}

// Log pressure data to a CSV file
void log_pressure(float pressure) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }

    // Check if the file is newly created and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,pressure_kPa\n");
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, pressure);
    fclose(log_file);
}

// Check pressure range and print warning if outside safe range
void check_pressure_range(float pressure) {
    if (pressure < SAFE_PRESSURE_MIN || pressure > SAFE_PRESSURE_MAX) {
        fprintf(stderr, "Warning: Pressure out of safe range: %.2f kPa\n", pressure);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    float pressure;

    // Main loop
    while (!terminate) {
        if (read_pressure(&pressure) == 0) {
            log_pressure(pressure);
            check_pressure_range(pressure);
        } else {
            fprintf(stderr, "Failed to read pressure, retrying...\n");
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before retrying
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting.\n");
                break;
            }
            continue; // Skip the rest of the loop and retry
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

