    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read data from the HIH6130 sensor
int read_hih6130(int i2c_handle, float *temperature, float *humidity) {
    char buf[4];
    int result;

    // Trigger measurement
    result = i2cWriteByte(i2c_handle, 0x00);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (at least 37 ms)
    gpioDelay(40000); // 40 ms

    // Read 4 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate status bits
    if ((buf[0] & 0xC0) != 0) {
        fprintf(stderr, "Error: Invalid status bits in sensor data\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    uint16_t raw_humidity = ((uint16_t)buf[0] << 8) | (uint16_t)buf[1];
    uint16_t raw_temperature = ((uint16_t)buf[2] << 8) | (uint16_t)buf[3];

    *humidity = (float)raw_humidity * 100.0 / 16383.0;
    *temperature = (float)raw_temperature * 165.0 / 16383.0 - 40.0;

    return 0;
}

