int log_data(const char *timestamp, float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);

    // Truncate the log file if it exceeds the size limit
    struct stat st;
    if (stat(LOG_FILE, &st) == 0 && st.st_size > LOG_FILE_SIZE_LIMIT) {
        fp = fopen(LOG_FILE, "w"); // Open in write mode to truncate
        if (fp == NULL) {
            perror("Error opening log file for truncation");
            return -1;
        }
        fclose(fp);
    }

    return 0;
}

