    float temperature, humidity;
    char *timestamp;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Starting environmental data logging...\n");

    while (running) {
        // Read temperature and humidity
        result = read_hih6130(i2c_handle, &temperature, &humidity);
        if (result == 0) {
            // Get timestamp
            timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                // Log data
                if (log_data(timestamp, temperature, humidity) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
