#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Configuration
#define SENT_GPIO 4
#define TICK_TIME_US 3
#define SYNC_PULSE_TICKS 56
#define MIN_PULSE_WIDTH_US 36
#define MAX_PULSE_WIDTH_US 813
#define SCALE 0.01
#define OFFSET 0.0
#define TIMEOUT_US 100000 // 100ms timeout

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold SENT data
typedef struct {
    unsigned int status;
    unsigned int data1;
    unsigned int data2;
    unsigned int data3;
    unsigned int checksum;
} SENT_Data;

// Function prototypes
int initialize_gpio();
int read_sent_data(SENT_Data *data);
int validate_checksum(const SENT_Data *data);
float convert_to_pressure(unsigned int raw_value);
void log_pressure(float pressure);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP); // Enable pull-up resistor
    return 0;
}

// Function to read SENT data
int read_sent_data(SENT_Data *data) {
    int i;
    unsigned int pulse_width;
    unsigned int start_tick, end_tick;

    // Synchronization pulse
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 0 && running) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for synchronization pulse\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < SYNC_PULSE_TICKS * TICK_TIME_US || pulse_width > (SYNC_PULSE_TICKS + 1) * TICK_TIME_US) {
        fprintf(stderr, "Invalid synchronization pulse width: %u us\n", pulse_width);
        return -1;
    }

    // Status nibble
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1 && running) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for status nibble\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
        fprintf(stderr, "Invalid status nibble pulse width: %u us\n", pulse_width);
        return -1;
    }
    data->status = (pulse_width - MIN_PULSE_WIDTH_US) / (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) * 15; // Scale to 0-15

    // Data nibbles
    for (i = 0; i < 3; i++) {
        start_tick = gpioTick();
        while (gpioRead(SENT_GPIO) == 1 && running) {
            if (gpioTick() - start_tick > TIMEOUT_US) {
                fprintf(stderr, "Timeout waiting for data nibble %d\n", i + 1);
                return -1;
            }
        }
        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
            fprintf(stderr, "Invalid data nibble %d pulse width: %u us\n", i + 1, pulse_width);
            return -1;
        }
        data->data1 = (pulse_width - MIN_PULSE_WIDTH_US) / (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) * 15; // Scale to 0-15
    }

    // Checksum nibble
    start_tick = gpioTick();
    while (gpioRead(SENT_GPIO) == 1 && running) {
        if (gpioTick() - start_tick > TIMEOUT_US) {
            fprintf(stderr, "Timeout waiting for checksum nibble\n");
            return -1;
        }
    }
    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;
    if (pulse_width < MIN_PULSE_WIDTH_US || pulse_width > MAX_PULSE_WIDTH_US) {
        fprintf(stderr, "Invalid checksum nibble pulse width: %u us\n", pulse_width);
        return -1;
    }
    data->checksum = (pulse_width - MIN_PULSE_WIDTH_US) / (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US) * 15; // Scale to 0-15

    return 0;
}

// Function to validate the checksum
int validate_checksum(const SENT_Data *data) {
    unsigned int sum = data->status + data->data1 + data->data2 + data->data3;
    if (sum % 16 != data->checksum) {
        fprintf(stderr, "Checksum validation failed: calculated %u, received %u\n", sum % 16, data->checksum);
        return -1;
    }
    return 0;
}

// Function to convert raw value to pressure
float convert_to_pressure(unsigned int raw_value) {
    return (float)raw_value * SCALE + OFFSET;
}

// Function to log pressure data
void log_pressure(float pressure) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    SENT_Data data;
    float pressure;
    int result;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        result = read_sent_data(&data);
        if (result == 0) {
            if (validate_checksum(&data) == 0) {
                pressure = convert_to_pressure((data.data1 << 8) | data.data2); // Combine data1 and data2
                log_pressure(pressure);
                printf("Pressure: %.2f Pa\n", pressure);
            } else {
                fprintf(stderr, "Checksum validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading SENT data\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    cleanup();
    return 0;
}

