#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define DEVICE_ID_REG 0x0F
#define TEMP_SCALE 0.0078125
#define TEMP_OFFSET 0.0
#define DATA_FILE "greenhouse_temps.dat"

// Global variables
int i2c_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int verify_device_id();
float read_temperature();
int write_temperature_to_file(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify the TMP117 device ID
int verify_device_id() {
    int device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);
    if (device_id < 0) {
        fprintf(stderr, "Error reading device ID: %d\n", device_id);
        return -1;
    }

    if (device_id != 0x17) {
        fprintf(stderr, "Error: Incorrect device ID (0x%02X). Expected 0x17.\n", device_id);
        return -1;
    }

    printf("TMP117 device ID verified.\n");
    return 0;
}

// Read temperature from the TMP117
float read_temperature() {
    int raw_temp = i2cReadWordData(i2c_handle, TEMP_REG);
    if (raw_temp < 0) {
        fprintf(stderr, "Error reading temperature: %d\n", raw_temp);
        return -1000.0; // Indicate an error with a very low temperature
    }

    // Convert raw temperature to Celsius
    float temperature = (float)raw_temp * TEMP_SCALE + TEMP_OFFSET;
    return temperature;
}

// Write temperature to file
int write_temperature_to_file(float temperature) {
    fp = fopen(DATA_FILE, "ab");
    if (fp == NULL) {
        fprintf(stderr, "Error opening file for writing.\n");
        return -1;
    }

    // Convert float to little-endian bytes
    uint8_t buffer[4];
    for (int i = 0; i < 4; i++) {
        buffer[i] = (uint8_t)(temperature * 1000000); // Store as microdegrees
        temperature *= 256;
