#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_HIGH_PRECISION 0xFD
#define DATA_LENGTH 6
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define TEMP_OFFSET -45.0
#define TEMP_SCALE 175.0
#define HUM_OFFSET -6.0
#define HUM_SCALE 125.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int write_i2c_command(int handle, uint8_t command);
int read_i2c_data(int handle, char *data, int count);
uint8_t calculate_crc(const char *data, int len);
int validate_crc(const char *data, int len, uint8_t checksum);
float convert_temperature(uint16_t raw_temp);
float convert_humidity(uint16_t raw_hum);
int log_data(float temperature, float humidity);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

int main() {
    sensor_data_t sensor_data;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, SHT40_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        char data[DATA_LENGTH];

        // Send measurement command
        if (write_i2c_command(i2c_handle, MEASURE_HIGH_PRECISION) != 0) {
            fprintf(stderr, "Failed to write measurement command.\n");
            continue; // Try again
        }

        // Wait for conversion (at least 8.5 ms)
        gpioDelay(10000); // 10 ms

        // Read data
        if (read_i2c_data(i2c_handle, data, DATA_LENGTH) != 0) {
            fprintf(stderr, "Failed to read data.\n");
            continue; // Try again
        }

        // Validate CRC
        if (!validate_crc(data, 2, data[2]) || !validate_crc(data + 3, 2, data[5])) {
            fprintf(stderr, "CRC validation failed.\n");
            continue; // Try again
        }

        // Convert data
        uint16_t raw_temp = (data[0] << 8) | data[1];
        uint16_t raw_hum = (data[3] << 8) | data[4];

        sensor_data.temperature = convert_temperature(raw_temp);
        sensor_data.humidity = convert_humidity(raw_hum);

        // Log data
        if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();
    fclose(log_file);

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write I2C command
int write_i2c_command(int handle, uint8_t command) {
    int result = i2cWriteByte(handle, command);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read I2C data
int read_i2c_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const char *data, int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const char *data, int len, uint8_t checksum) {
    return (calculate_crc(data, len) == checksum);
}

// Convert temperature
float convert_temperature(uint16_t raw_temp) {
    return TEMP_OFFSET + (TEMP_SCALE / 65535.0) * raw_temp;
}

// Convert humidity
float convert_humidity(uint16_t raw_hum) {
    return HUM_OFFSET + (HUM_SCALE / 65535.0) * raw_hum;
}

// Log data
int log_data(float temperature, float humidity) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Humidity: %.2f %%RH\n", timestamp, temperature, humidity);
    fflush(log_file);

    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

