#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds
#define LSB_RESOLUTION 0.0078125
#define LOG_FILE "temperature_log.dat"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
void save_buffer_to_file();
void signal_handler(int signal);
void cleanup();

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP117
int read_temperature(float *temperature) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Failed to read temperature: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_temp = (buf[0] << 8) | buf[1];

    // Convert to temperature in Celsius
    *temperature = raw_temp * LSB_RESOLUTION;

    return 0;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
}

// Save buffer to file
void save_buffer_to_file() {
    FILE *fp = fopen(LOG_FILE, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }

    size_t elements_written = fwrite(temp_buffer.buffer, sizeof(float), temp_buffer.count, fp);
    if (elements_written != temp_buffer.count) {
        fprintf(stderr, "Failed to write all data to file: %s\n", strerror(errno));
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    save_buffer_to_file();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

