        fprintf(stderr, "Failed to open log file for writing: %s\n", strerror(errno));
        return;
    }

    size_t elements_written = fwrite(temp_buffer.buffer, sizeof(float), temp_buffer.count, fp);
    if (elements_written != temp_buffer.count) {
        fprintf(stderr, "Failed to write all data to file: %s\n", strerror(errno));
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    save_buffer_to_file();
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            add_to_buffer(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

