        gpioDelay(15000); // 15 ms

        // Read data
        if (read_data(i2c_handle, data, 6) != 0) {
            fprintf(stderr, "Failed to read data\n");
            continue; // Try again
        }

        // Validate CRC
        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Try again
        }

