#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x49
#define FLOW_REGISTER 0x00 // Placeholder, I2C doesn't use registers
#define TEMP_REGISTER 0x00 // Placeholder, I2C doesn't use registers
#define FLOW_SCALE 16384.0
#define TEMP_SCALE 4096.0
#define FLOW_OFFSET 0.1
#define TEMP_OFFSET 0.1
#define FLOW_GAIN 0.8
#define TEMP_GAIN 0.8
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int *flow_raw, int *temp_raw);
float convert_flow(int raw_flow);
float convert_temperature(int raw_temp);
int log_data(float flow_slpm, float temperature_celsius);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C connection
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads raw flow and temperature data from the sensor
int read_sensor_data(int *flow_raw, int *temp_raw) {
    char buffer[4];
    int bytes_read = i2cReadDevice(i2c_handle, buffer, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    *flow_raw = (buffer[0] << 8) | buffer[1];
    *temp_raw = (buffer[2] << 8) | buffer[3];

    return 0;
}

// Converts raw flow data to SLPM
float convert_flow(int raw_flow) {
    return ((float)raw_flow / FLOW_SCALE - FLOW_OFFSET) / FLOW_GAIN * 25.0;
}

// Converts raw temperature data to Celsius
float convert_temperature(int raw_temp) {
    return ((float)raw_temp / TEMP_SCALE - TEMP_OFFSET) / TEMP_GAIN * 80.0 - 40.0;
}

// Logs the timestamped flow rate and temperature to the file
int log_data(float flow_slpm, float temperature_celsius) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow: %.2f SLPM, Temperature: %.2f °C\n", timestamp, flow_slpm, temperature_celsius);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

