    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    int flow_raw, temp_raw;
    float flow_slpm, temperature_celsius;

    // Read sensor data and log it every second
    while (!terminate) {
        if (read_sensor_data(&flow_raw, &temp_raw) == 0) {
            flow_slpm = convert_flow(flow_raw);
            temperature_celsius = convert_temperature(temp_raw);
            log_data(flow_slpm, temperature_celsius);
        } else {
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s, ERROR: Failed to read sensor data\n", timestamp);
            fflush(log_file);
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-initializing
            if (initialize_i2c() != 0) {
                fprintf(stderr, "I2C re-initialization failed. Exiting.\n");
                break; // Exit the loop if re-initialization fails
            }
        }
        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

