#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define DHT11_GPIO 4
#define TIMEOUT_US 100000 // 100ms timeout
#define RETRY_COUNT 3

// Structure to hold DHT11 data
typedef struct {
    int humidity;
    int temperature;
} DHT11Data;

// Global variables
static volatile int running = 1;
FILE *log_file = NULL;

// Function prototypes
int read_dht11(DHT11Data *data);
void log_data(DHT11Data data);
void log_error(const char *message, int error_code);
void signal_handler(int signal);

// Function to read DHT11 sensor data
int read_dht11(DHT11Data *data) {
    int i, j;
    unsigned int raw_data[5] = {0, 0, 0, 0, 0};
    int bit_idx = 0;
    int byte_idx = 0;
    int checksum = 0;

    // Send start signal
    gpioSetMode(DHT11_GPIO, PI_OUTPUT);
    gpioWrite(DHT11_GPIO, 0);
    gpioDelay(18000); // 18 ms
    gpioWrite(DHT11_GPIO, 1);
    gpioSetMode(DHT11_GPIO, PI_INPUT);

    // Wait for response (low then high)
    int start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for DHT11 start signal", 1);
            return 1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 0) {
        if (gpioTick() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for DHT11 start signal", 1);
            return 1; // Timeout
        }
    }

    start_time = gpioTick();
    while (gpioRead(DHT11_GPIO) == 1) {
        if (gpioTck() - start_time > TIMEOUT_US) {
            log_error("Timeout waiting for DHT11 start signal", 1);
            return 1; // Timeout
        }
    }

    // Read 40 data bits
    for (i = 0; i < 40; i++) {
        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 0) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for DHT11 data bit start", 2);
                return 2; // Timeout
            }
        }

        start_time = gpioTick();
        while (gpioRead(DHT11_GPIO) == 1) {
            if (gpioTick() - start_time > TIMEOUT_US) {
                log_error("Timeout waiting for DHT11 data bit end", 2);
                return 2; // Timeout
            }
        }

        int pulse_width = gpioTick() - start_time;
        if (pulse_width > 40) {
            raw_data[byte_idx] |= (1 << (7 - bit_idx));
        }

        bit_idx++;
        if (bit_idx == 8) {
            bit_idx = 0;
            byte_idx++;
        }
    }

    // Validate checksum
    checksum = raw_data[0] + raw_data[1] + raw_data[2] + raw_data[3];
    if (checksum != raw_data[4]) {
        log_error("Checksum validation failed", 3);
        return 3; // Checksum failure
    }

    // Convert data to temperature and humidity
    data->humidity = raw_data[0];
    data->temperature = raw_data[2];

    return 0; // Success
}

// Function to log data to file
void log_data(DHT11Data data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Temperature: %d, Humidity: %d\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to log errors to file
void log_error(const char *message, int error_code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, ERROR: %s (Code: %d)\n", timestamp, message, error_code);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    DHT11Data data;
    int result;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        result = read_dht11(&data);
        if (result == 0) {
            log_data(data);
        } else {
            log_error("Failed to read DHT11 data", result);
        }

        sleep(2);
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    return 0;
}

