int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Write I2C command
int write_i2c_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write I2C command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read I2C data
int read_i2c_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "Failed to read I2C data: %d\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC
uint8_t calculate_crc(const char *data, int length, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = initial_value;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ polynomial;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(const char *data, int length, uint8_t polynomial, uint8_t initial_value) {
    uint8_t crc = calculate_crc(data, length, polynomial, initial_value);
    return (crc == 0) ? 0 : -1;
}

