#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x64
#define SENSOR2_ADDR 0x65
#define RED_REG 0x64
#define GREEN_REG 0x66
#define BLUE_REG 0x68
#define DEVICE_ID_REG 0x00
#define DEVICE_ID 0x2A
#define CCT_LOG_FILE "cct_log.csv"

// Global variables for I2C handles and file pointer
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue);
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue);
int log_cct_data(float cct1, float cct2);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function to initialize I2C
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }

    // Verify device ID
    char buf[1];
    int result = i2cReadI2CBlockData(handle, DEVICE_ID_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading device ID from address 0x%02X: %d\n", addr, result);
        i2cClose(handle);
        return -1;
    }

    if (buf[0] != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID (0x%02X) from address 0x%02X. Expected 0x%02X\n", buf[0], addr, DEVICE_ID);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

// Function to read sensor data
int read_sensor_data(int i2c_handle, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[6];
    int result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *red = (uint16_t)((buf[1] << 8) | buf[0]);
    *green = (uint16_t)((buf[3] << 8) | buf[2]);
    *blue = (uint16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

// Function to calculate CCT using McCamy's formula
float calculate_cct(uint16_t red, uint16_t green, uint16_t blue) {
    // McCamy's formula (simplified for brevity)
    float X = (float)red;
    float Y = (float)green;
    float Z = (float)blue;

    float x = X / (X + Y + Z);
    float y = Y / (X + Y + Z);

    float n = (x - 0.3320) / (0.1858 - y);

    float cct = 449.0 * pow(n, 3) + 3525.0 * pow(n, 2) + 6823.3 * n + 5520.33;

    return cct;
}

// Function to log CCT data to a file
int log_cct_data(float cct1, float cct2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, (cct1 + cct2) / 2.0);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(CCT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        sensor_data_t sensor1_data, sensor2_data;
        float cct1, cct2;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data.red, &sensor1_data.green, &sensor1_data.blue) == 0) {
            cct1 = calculate_cct(sensor1_data.red, sensor1_data.green, sensor1_data.blue);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &sensor2_data.red, &sensor2_data.green, &sensor2_data.blue) == 0) {
            cct2 = calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Log the data
        if (cct1 != -1.0 && cct2 != -1.0) {
            log_cct_data(cct1, cct2);
        } else {
            fprintf(stderr, "Error reading data from one or more sensors. Skipping log entry.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

