    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, (cct1 + cct2) / 2.0);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C for both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        i2cClose(i2c_handle1);
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(CCT_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle1);
        i2cClose(i2c_handle2);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Average_CCT\n");
    }
    rewind(log_file);

    // Main loop
    while (1) {
        sensor_data_t sensor1_data, sensor2_data;
        float cct1, cct2;

        // Read data from sensor 1
        if (read_sensor_data(i2c_handle1, &sensor1_data.red, &sensor1_data.green, &sensor1_data.blue) == 0) {
            cct1 = calculate_cct(sensor1_data.red, sensor1_data.green, sensor1_data.blue);
        } else {
            cct1 = -1.0; // Indicate error
        }

        // Read data from sensor 2
        if (read_sensor_data(i2c_handle2, &sensor2_data.red, &sensor2_data.green, &sensor2_data.blue) == 0) {
            cct2 = calculate_cct(sensor2_data.red, sensor2_data.green, sensor2_data.blue);
        } else {
            cct2 = -1.0; // Indicate error
        }

        // Log the data
        if (cct1 != -1.0 && cct2 != -1.0) {
            log_cct_data(cct1, cct2);
        } else {
            fprintf(stderr, "Error reading data from one or more sensors. Skipping log entry.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // The following lines will never be reached due to the infinite loop.
    // However, they are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle1);
    i2cClose(i2c_handle2);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

