int init_i2c();
int read_sensor_data(int handle, uint16_t *pressure, uint16_t *temperature);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_sensor_data(int handle, uint16_t *pressure, uint16_t *temperature) {
    char buf[4];
    int result;

    // Read pressure register
    result = i2cReadI2CBlockData(handle, PRESSURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading pressure data: %d\n", result);
        return -1;
    }
    *pressure = (buf[0] << 8) | buf[1];

    // Read temperature register
    result = i2cReadI2CBlockData(handle, TEMPERATURE_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %d\n", result);
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    return 0;
}

// Convert raw pressure data to kPa
float convert_pressure(uint16_t raw_pressure) {
    const float output_min = 0.0;
    const float output_max = 32768.0;
    const float pmin_kPa = 0.0;
    const float pmax_kPa = 800.0;

    return (raw_pressure - output_min) * (pmax_kPa - pmin_kPa) / (output_max - output_min);
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return raw_temperature * 0.01 - 40.0;
}

