#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define TEMP_REG 0x00
#define FAN_GPIO 18
#define BUFFER_SIZE 60
#define HIGH_THRESHOLD 28.0
#define LOW_THRESHOLD 26.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(float *temperature);
void add_to_buffer(float temperature);
float calculate_average();
void control_fan(float average_temperature);
void signal_handler(int signal);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75B
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (signed 9-bit format)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    raw_temp = raw_temp >> 7; // Shift right by 7 bits

    *temperature = raw_temp * 0.5;

    return 0;
}

// Add temperature to circular buffer
void add_to_buffer(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Calculate running average
float calculate_average() {
    float sum = 0.0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    return sum / BUFFER_SIZE;
}

// Control cooling fan with hysteresis
void control_fan(float average_temperature) {
    if (average_temperature > HIGH_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temperature < LOW_THRESHOLD) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    float temperature;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Add to buffer
            add_to_buffer(temperature);

            // Calculate average
            float average_temperature = calculate_average();

            // Control fan
            control_fan(average_temperature);

            printf("Temperature: %.2f °C, Average: %.2f °C, Fan: %s\n", temperature, average_temperature, gpioRead(FAN_GPIO) ? "ON" : "OFF");
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

