#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x362F
#define PRESSURE_SCALE_FACTOR 60.0
#define TEMPERATURE_SCALE_FACTOR 200.0
#define PRESSURE_THRESHOLD 5.0
#define LOG_FILE "airflow.log"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
uint8_t calculate_crc(const char *data, int len, uint8_t polynomial);
int validate_crc(const char *data, int len, uint8_t expected_crc);
int convert_raw_data(int16_t raw_pressure, int16_t raw_temperature, float *pressure_pa, float *temperature_c);
int log_data(float pressure_pa, float temperature_c);
void check_pressure_threshold(float pressure_pa);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        char buffer[9];
        int16_t raw_pressure, raw_temperature;
        float pressure_pa, temperature_c;

        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to send measurement command\n");
            continue; // Retry
        }

        // Wait for measurement
        gpioDelay(45000); // 45 ms

        // Read data
        if (read_data(i2c_handle, buffer, 9) != 0) {
            fprintf(stderr, "Failed to read data\n");
            continue; // Retry
        }

        // Validate CRC
        if (validate_crc(buffer, 2, buffer[2]) != 0 || validate_crc(buffer + 3, 2, buffer[5]) != 0 || validate_crc(buffer + 6, 2, buffer[8]) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            continue; // Retry
        }

        // Convert raw data
        if (convert_raw_data((int16_t)((buffer[0] << 8) | buffer[1]), (int16_t)((buffer[3] << 8) | buffer[4]), &pressure_pa, &temperature_c) != 0) {
            fprintf(stderr, "Failed to convert raw data\n");
            continue; // Retry
        }

        // Log data
        if (log_data(pressure_pa, temperature_c) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Check pressure threshold
        check_pressure_threshold(pressure_pa);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Send command to the sensor
