#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define TEMP_SCALE 0.0625

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_celsius(int16_t raw_temp);
int set_led_state(int state);
void signal_handler(int sig);
int initialize_gpio(void);
void cleanup_gpio(void);

// Signal handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// I2C read function
int i2c_read_word(int fd, uint8_t reg) {
    int retries = 3;
    int16_t raw_temp = -1;

    while (retries > 0) {
        if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
            fprintf(stderr, "Error: Could not set I2C slave address: %s\n", strerror(errno));
            return -1;
        }

        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error: Could not write register address: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        uint8_t buffer[2];
        if (read(fd, buffer, 2) != 2) {
            fprintf(stderr, "Error: Could not read temperature data: %s\n", strerror(errno));
            retries--;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        raw_temp = (buffer[0] << 8) | buffer[1];
        return raw_temp;
    }

    fprintf(stderr, "Error: Failed to read temperature after multiple retries.\n");
    return -1;
}

// Temperature conversion function
float convert_to_celsius(int16_t raw_temp) {
    return (float)(raw_temp >> 4) * TEMP_SCALE;
}

// LED control function
int set_led_state(int state) {
    int ret = gpiod_line_set_value(led_line, state);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not set LED state: %s\n", strerror(-ret));
        return -1;
    }
    return 0;
}

// GPIO initialization function
int initialize_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error: Could not open GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        fprintf(stderr, "Error: Could not get LED GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "temp_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    int ret = gpiod_line_request(led_line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Could not request LED GPIO line: %s\n", strerror(-ret));
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO cleanup function
void cleanup_gpio(void) {
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %s\n", strerror(errno));
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_temp = i2c_read_word(i2c_fd, TEMP_REG);
        if (raw_temp < 0) {
            fprintf(stderr, "Error: Could not read temperature, retrying...\n");
            sleep(1);
            continue;
        }

        float temp_celsius = convert_to_celsius(raw_temp);
        printf("Temperature: %.2f °C\n", temp_celsius);

        if (temp_celsius > TEMP_THRESHOLD_HIGH) {
            set_led_state(1);
        } else if (temp_celsius < TEMP_THRESHOLD_LOW) {
            set_led_state(0);
        }

        sleep(1);
    }

    // Cleanup
    cleanup_gpio();
    close(i2c_fd);

    return 0;
}

