#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define TEMP_CMD 0xF3
#define HUMID_CMD 0xF5
#define ELEC_ID_CMD 0xF1
#define RETRY_COUNT 3
#define SLEEP_SECONDS 60

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_sensor_data(int handle, float *temperature, float *humidity);
int validate_sensor(int handle);
void log_data(float temperature, float humidity);
void log_error(const char *message);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(int handle, float *temperature, float *humidity) {
    unsigned char buf[2];
    int result;
    int retries = RETRY_COUNT;

    // Measure Relative Humidity
    while (retries > 0) {
        result = i2cWriteByte(handle, HUMID_CMD);
        if (result == 0) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to write humidity command");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (at least 20ms)

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(handle, (char *)buf, 2);
        if (result == 2) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to read humidity data");
        return -1;
    }
    unsigned int humidity_raw = (buf[0] << 8) | buf[1];

    // Measure Temperature
    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cWriteByte(handle, TEMP_CMD);
        if (result == 0) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to write temperature command");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (at least 20ms)

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(handle, (char *)buf, 2);
        if (result == 2) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to read temperature data");
        return -1;
    }
    unsigned int temperature_raw = (buf[0] << 8) | buf[1];

    // Convert raw values to temperature and humidity
    *temperature = 175.72 * temperature_raw / 65536.0 - 46.85;
    *humidity = 125.0 * humidity_raw / 65536.0 - 6.0;

    // Clamp humidity to 0-100%
    if (*humidity < 0.0) *humidity = 0.0;
    if (*humidity > 100.0) *humidity = 100.0;

    return 0;
}

// Function to validate the sensor
int validate_sensor(int handle) {
    unsigned char buf[2];
    int result;
    int retries = RETRY_COUNT;

    // Read Electronic ID (should return 0xFF)
    while (retries > 0) {
        result = i2cWriteByte(handle, ELEC_ID_CMD);
        if (result == 0) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to write electronic ID command");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (at least 20ms)

    retries = RETRY_COUNT;
    while (retries > 0) {
        result = i2cReadDevice(handle, (char *)buf, 2);
        if (result == 2) break; // Success
        gpioDelay(10); // Wait before retry
        retries--;
    }
    if (retries == 0) {
        log_error("Failed to read electronic ID data");
        return -1;
    }

    if (buf[0] != 0xFF) {
        fprintf(stderr, "Electronic ID mismatch: 0x%02X\n", buf[0]);
        return -1;
    }

    return 0;
}

// Function to log data to file
void log_data(float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    FILE *fp = fopen("environment.log", "a");
    if (fp == NULL) {
        perror("Error opening environment.log");
        return;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fflush(fp);
    fclose(fp);

    printf("%s,%.2f,%.2f\n", timestamp, temperature, humidity);
}

// Function to log errors to file and stderr
void log_error(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(stderr, "%s Error: %s\n", timestamp, message);

    FILE *fp = fopen("environment.log", "a");
    if (fp != NULL) {
        fprintf(fp, "%s Error: %s\n", timestamp, message);
        fflush(fp);
        fclose(fp);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Validate the sensor
    if (validate_sensor(i2c_handle) != 0) {
        log_error("Sensor validation failed");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Si7021 sensor initialized successfully.\n");

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sensor_data(i2c_handle, &sensor_data.temperature, &sensor_data.humidity) == 0) {
            log_data(sensor_data.temperature, sensor_data.humidity);
        } else {
            log_error("Failed to read sensor data");
        }
        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

