    while (1) {
        float temperature, humidity;

        // Read temperature and humidity
        if (read_hdc1080(i2c_handle, &temperature, &humidity) == 0) {
            // Log data
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read HDC1080 data.\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", handle);
        return -1;
    }
    return handle;
}

// Configure HDC1080
int configure_hdc1080(int handle) {
    // Configure for 14-bit temperature and humidity resolution
    // 0x0000 = 14-bit temperature and 14-bit humidity
    char config_data[2] = {0x00, 0x00};
    int result = i2cWriteDevice(handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to configuration register: %d\n", result);
        return -1;
    }
