#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define I2C_DEVICE "/dev/i2c-1"
#define STS40_ADDR 0x44
#define MEASURE_CMD_HIGH_REPEATABILITY 0x2C
#define MEASURE_CMD_LOW_POWER 0x2D
#define MEASURE_CMD_ULTRA_LOW_POWER 0x2E
#define CRC8_POLYNOMIAL 0x31

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int i2c_fd = -1;
FILE *log_file = NULL;

// Function prototypes
int i2c_open(const char *device);
int i2c_set_slave_address(int fd, int address);
int i2c_write(int fd, const uint8_t *data, int length);
int i2c_read(int fd, uint8_t *data, int length);
uint8_t calculate_crc8(const uint8_t *data, int length);
float convert_raw_to_celsius(uint16_t raw_temperature);
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size);
int log_temperature(const char *timestamp, float temperature);
void signal_handler(int signal);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device %s: %s\n", device, strerror(errno));
        return -1;
    }
    return fd;
}

// I2C set slave address function
int i2c_set_slave_address(int fd, int address) {
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", address, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write(int fd, const uint8_t *data, int length) {
    if (write(fd, data, length) != length) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read(int fd, uint8_t *data, int length) {
    if (read(fd, data, length) != length) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// CRC8 calculation function
uint8_t calculate_crc8(const uint8_t *data, int length) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < length; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Temperature conversion function
float convert_raw_to_celsius(uint16_t raw_temperature) {
    return -45.0 + 175.0 * (float)raw_temperature / 65535.0;
}

// Get ISO 8601 timestamp function
char* get_iso8601_timestamp(char* timestamp_buffer, size_t buffer_size) {
    time_t timer;
    struct tm* tm_info;

    time(&timer);
    tm_info = gmtime(&timer);

    strftime(timestamp_buffer, buffer_size, "%Y-%m-%dT%H:%M:%SZ", tm_info);
    return timestamp_buffer;
}

// Log temperature function
int log_temperature(const char *timestamp, float temperature) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    uint8_t data[3];
    uint16_t raw_temperature;
    float temperature;
    char timestamp[32];

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open(I2C_DEVICE);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set I2C slave address
    if (i2c_set_slave_address(i2c_fd, STS40_ADDR) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("temperature_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        // Send measurement command
        uint8_t cmd[2] = {MEASURE_CMD_HIGH_REPEATABILITY, 0xE0};
        if (i2c_write(i2c_fd, cmd, 2) < 0) {
            fprintf(stderr, "Error writing measurement command.\n");
            continue; // Continue to the next iteration
        }

        // Wait for conversion (at least 10 ms)
        usleep(10000); // 10 ms

        // Read data
        if (i2c_read(i2c_fd, data, 3) < 0) {
            fprintf(stderr, "Error reading data.\n");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        uint8_t crc = calculate_crc8(data, 2);
        if (crc != data[2]) {
            fprintf(stderr, "CRC mismatch: calculated 0x%02X, received 0x%02X\n", crc, data[2]);
            continue; // Continue to the next iteration
        }

        // Convert raw data to temperature
        raw_temperature = (data[0] << 8) | data[1];
        temperature = convert_raw_to_celsius(raw_temperature);

        // Get timestamp
        get_iso8601_timestamp(timestamp, sizeof(timestamp));

        // Log temperature
        if (log_temperature(timestamp, temperature) < 0) {
            fprintf(stderr, "Error logging temperature.\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

