#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define MEASUREMENT_COMMAND 0x3615
#define DATA_LENGTH 9
#define LOG_FILE "hvac_pressure_log.txt"
#define ERROR_LOG_FILE "hvac_error_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int send_command(int handle, uint16_t command);
int read_data(int handle, char *data, int count);
uint8_t calculate_crc(const char *data, int count);
int validate_crc(const char *data, int count, uint8_t expected_crc);
int convert_raw_to_pressure(int16_t raw_pressure, uint8_t scale_factor);
int convert_raw_to_temperature(int16_t raw_temperature);
int log_data(FILE *file, int16_t pressure, int16_t temperature);
int log_error(FILE *file, const char *message);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t scale_factor;
} sensor_data_t;

int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            log_error(error_log_file, "Failed to send measurement command.");
            continue; // Continue to the next iteration
        }

        // Wait for at least 50 ms
        gpioDelay(50000); // 50 ms

        // Read data
        char data[DATA_LENGTH];
        if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
            log_error(error_log_file, "Failed to read data.");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(data, 2, data[2]) != 0 || validate_crc(data + 3, 2, data[5]) != 0) {
            log_error(error_log_file, "CRC validation failed.");
            continue; // Continue to the next iteration
        }

        // Extract data
        sensor_data.pressure = (int16_t)((data[0] << 8) | data[1]);
        sensor_data.temperature = (int16_t)((data[3] << 8) | data[4]);
        sensor_data.scale_factor = data[6];

        // Convert raw data
        int16_t raw_pressure = sensor_data.pressure;
        int16_t raw_temperature = sensor_data.temperature;
        uint8_t scale_factor = sensor_data.scale_factor;

        int16_t pressure_pa = convert_raw_to_pressure(raw_pressure, scale_factor);
        int16_t temperature_c = convert_raw_to_temperature(raw_temperature);

        // Log data
        if (log_data(log_file, pressure_pa, temperature_c) != 0) {
            log_error(error_log_file, "Failed to log data.");
        }

        // Wait for the next sample
        sleep(SAMPLE_INTERVAL_SEC);
    }

    cleanup();
    return 0;
}

int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    return 0;
}

int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "I2C write failed: %d\n", result);
        return 1;
    }
    return 0;
}

int read_data(int handle, char *data, int count) {
    int result = i2cReadDevice(handle, data, count);
    if (result != count) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return 1;
