#define LOG_FILE "hvac_pressure_log.txt"
#define ERROR_LOG_FILE "hvac_error_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize();
int send_command(int handle, uint16_t command);
