int main() {
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed. Exiting.\n");
        return 1;
    }

    sensor_data_t sensor_data;

    while (!terminate) {
        // Send measurement command
        if (send_command(i2c_handle, MEASUREMENT_COMMAND) != 0) {
            log_error(error_log_file, "Failed to send measurement command.");
