        // Read data
        char data[DATA_LENGTH];
        if (read_data(i2c_handle, data, DATA_LENGTH) != 0) {
            log_error(error_log_file, "Failed to read data.");
            continue; // Continue to the next iteration
        }

        // Validate CRC
        if (validate_crc(data, 2, data[2]) != 0 || validate_crc(data + 3, 2, data[5]) != 0) {
