#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <pthread.h>
#include <sys/stat.h>
#include <sys/types.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_CAPACITY 100
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xE000

// Data Structure
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} SCD40Data;

// Circular Buffer Structure
typedef struct {
    SCD40Data data[BUFFER_CAPACITY];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
static int i2c_handle;
static CircularBuffer buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

// Function Prototypes
int init_pigpio();
int init_i2c();
int send_command(int handle, uint16_t command);
int read_data(int handle, uint8_t *data, int count);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int convert_data(const uint8_t *data, float *co2, float *temperature, float *humidity);
void add_to_buffer(CircularBuffer *buffer, float co2, float temperature, float humidity);
int get_from_buffer(CircularBuffer *buffer, int index, SCD40Data *data);
void *logging_thread_func(void *arg);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send command to SCD40
int send_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = command >> 8;
    buf[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error: I2C write failed (%d)\n", result);
        return -1;
    }
    return 0;
}

// Read data from SCD40
int read_data(int handle, uint8_t *data, int count) {
    int result = i2cReadDevice(handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error: I2C read failed (%d)\n", result);
        return -1;
    }
    return 0;
}

// Calculate CRC-8
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8
int validate_crc(const uint8_t *data, int len) {
    if (len < 3) return 0; // CRC is 1 byte, need at least 3 bytes for data + CRC
    uint8_t crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Convert raw data to CO2, temperature, and humidity
int convert_data(const uint8_t *data, float *co2, float *temperature, float *humidity) {
    uint16_t raw_co2 = (data[0] << 8) | data[1];
    uint16_t raw_temperature = (data[3] << 8) | data[4];
    uint16_t raw_humidity = (data[6] << 8) | data[7];

    *co2 = (float)raw_co2; // CO2 is already in ppm
    *temperature = -45 + 175 * (float)raw_temperature / 65535;
    *humidity = 100 * (float)raw_humidity / 65535;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(CircularBuffer *buffer, float co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->data[buffer->head].timestamp = time(NULL);
    buffer->data[buffer->head].co2 = co2;
    buffer->data[buffer->head].temperature = temperature;
    buffer->data[buffer->head].humidity = humidity;

    buffer->head = (buffer->head + 1) % BUFFER_CAPACITY;
    if (buffer->count < BUFFER_CAPACITY) {
        buffer->count++;
    } else {
        buffer->tail = (buffer->tail + 1) % BUFFER_CAPACITY;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from circular buffer
int get_from_buffer(CircularBuffer *buffer, int index, SCD40Data *data) {
    pthread_mutex_lock(&buffer->mutex);
    if (index < 0 || index >= buffer->count) {
        pthread_mutex_unlock(&buffer->mutex);
        return -1; // Invalid index
    }

    int actual_index = (buffer->tail + index) % BUFFER_CAPACITY;
    *data = buffer->data[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Logging thread function
void *logging_thread_func(void *arg) {
    while (running) {
        sleep(60);

        // Create filename
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char filename[256];
        strftime(filename, sizeof(filename), LOG_DIR "%Y%m%d_%H%M%S.csv", t);

        // Create directory if it doesn't exist
        char dir_path[256];
        strncpy(dir_path, filename, strrchr(filename, '/') - filename + 1);
        dir_path[strrchr(filename, '/') - filename + 1] = '\0';
        if (mkdir(dir_path, 0777) == -1 && errno != EEXIST) {
            fprintf(stderr, "Error creating directory: %s\n", dir_path);
            continue; // Skip logging this iteration
        }

        // Write data to file
        FILE *fp = fopen(filename, "w");
        if (fp == NULL) {
            fprintf(stderr, "Error opening file for writing: %s\n", filename);
            continue;
        }

        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");

        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int actual_index = (buffer.tail + i) % BUFFER_CAPACITY;
            fprintf(fp, "%ld,%.2f,%.2f,%.2f\n",
                    buffer.data[actual_index].timestamp,
                    buffer.data[actual_index].co2,
                    buffer.data[actual_index].temperature,
                    buffer.data[actual_index].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);

        fclose(fp);
    }
    return NULL;
}

// Signal handler
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, stopping...\n", signal);
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Stop periodic measurement
    send_command(i2c_handle, CMD_STOP_PERIODIC_MEASUREMENT);

    // Join logging thread
    pthread_join(logging_thread, NULL);

    // Flush buffer to file
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char filename[256];
    strftime(filename, sizeof(filename), LOG_DIR "%Y%m%d_%H%M%S_final.csv", t);

    FILE *fp = fopen(filename, "w");
    if (fp != NULL) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
        pthread_mutex_lock(&buffer.mutex);
        for (int i = 0; i < buffer.count; i++) {
            int actual_index = (buffer.tail + i) % BUFFER_CAPACITY;
            fprintf(fp, "%ld,%.2f,%.2f,%.2f\n",
                    buffer.data[actual_index].timestamp,
                    buffer.data[actual_index].co2,
                    buffer.data[actual_index].temperature,
                    buffer.data[actual_index].humidity);
        }
        pthread_mutex_unlock(&buffer.mutex);
        fclose(fp);
    } else {
        fprintf(stderr, "Error opening final log file for writing: %s\n", filename);
    }

    // Close I2C handle
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    buffer.head = 0;
    buffer.tail = 0;
    buffer.count = 0;
    pthread_mutex_init(&buffer.mutex, NULL);

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Create logging thread
    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        fprintf(stderr, "Error creating logging thread\n");
        cleanup();
        return 1;
    }

    // Start periodic measurement
    if (send_command(i2c_handle, CMD_START_PERIODIC_MEASUREMENT) != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        sleep(5);

        uint8_t data[9];
        if (send_command(i2c_handle, CMD_READ_MEASUREMENT) == 0 && read_data(i2c_handle, data, 9) == 0) {
            if (validate_crc(data, 3) && validate_crc(data + 3, 3) && validate_crc(data + 6, 3)) {
                float co2, temperature, humidity;
                if (convert_data(data, &co2, &temperature, &humidity) == 0) {
                    add_to_buffer(&buffer, co2, temperature, humidity);
                    printf("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%RH\n", co2, temperature, humidity);
                } else {
                    fprintf(stderr, "Error converting data\n");
                }
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Error reading data\n");
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

