#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ICP10110_ADDR 0x63
#define WHO_AM_I_REG 0x08
#define CALIB_COEFF_REG 0x05
#define MEASURE_CMD_REG 0x00
#define DATA_REG 0x00
#define DATA_LENGTH 6

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration coefficients
int32_t c0, c1, c2, c3, c4, c5, c6;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int verify_sensor_id();
int read_calibration_coefficients();
int trigger_measurement();
int read_sensor_data(int32_t *pressure, int32_t *temperature);
double convert_pressure(int32_t raw_pressure);
double convert_temperature(int32_t raw_temperature);
char* get_iso8601_timestamp();
int log_data(double pressure, double temperature);
void print_data(double pressure, double temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    double pressure;
    double temperature;
} sensor_data_t;

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio.\n");
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        fprintf(stderr, "Failed to open I2C bus.\n");
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    if (verify_sensor_id() != 0) {
        fprintf(stderr, "Sensor ID verification failed.\n");
        cleanup();
        return 1;
    }

    // Read calibration coefficients
    if (read_calibration_coefficients() != 0) {
        fprintf(stderr, "Failed to read calibration coefficients.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        int32_t raw_pressure, raw_temperature;

        // Trigger measurement
        if (trigger_measurement() != 0) {
            fprintf(stderr, "Failed to trigger measurement.\n");
            continue; // Skip to the next iteration
        }

        // Wait for measurement to complete (10 ms)
        gpioDelay(10000); // 10 ms

        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) != 0) {
            fprintf(stderr, "Failed to read sensor data.\n");
            continue; // Skip to the next iteration
        }

        // Convert data
        double pressure = convert_pressure(raw_pressure);
        double temperature = convert_temperature(raw_temperature);

        // Get timestamp
        char *timestamp = get_iso8601_timestamp();

        // Log data
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        // Print data
        print_data(pressure, temperature);

        // Free timestamp memory
        free(timestamp);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Verify sensor ID
int verify_sensor_id() {
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return 1;
    }
    if (who_am_i != 0x08) {
        fprintf(stderr, "Incorrect WHO_AM_I value: 0x%02X\n", who_am_i);
        return 1;
    }
    return 0;
}

// Read calibration coefficients
int read_calibration_coefficients() {
    char buffer[14];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, CALIB_COEFF_REG, buffer, 14);
    if (bytes_read != 14) {
        fprintf(stderr, "Failed to read calibration coefficients: %d\n", bytes_read);
        return 1;
    }

    c0 = (int32_t)((uint32_t)buffer[0] << 24 | (uint32_t)buffer[1] << 16 | (uint32_t)buffer[2] << 8 | (uint32_t)buffer[3]);
    c1 = (int32_t)((uint32_t)buffer[4] << 24 | (uint32_t)buffer[5] << 16 | (uint32_t)buffer[6] << 8 | (uint32_t)buffer[7]);
    c2 = (int32_t)((uint32_t)buffer[8] << 24 | (uint32_t)buffer[9] << 16 | (uint32_t)buffer[10] << 8 | (uint32_t)buffer[11]);
    c3 = (int32_t)((uint32_t)buffer[12] << 24 | (uint32_t)buffer[13] << 16);

    return 0;
}

// Trigger measurement
int trigger_measurement() {
    int result = i2cWriteByteData(i2c_handle, MEASURE_CMD_REG, 0x00);
    if (result < 0) {
        fprintf(stderr, "Failed to trigger measurement: %d\n", result);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(int32_t *pressure, int32_t *temperature) {
    char buffer[DATA_LENGTH];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DATA_REG, buffer, DATA_LENGTH);
    if (bytes_read != DATA_LENGTH) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return 1;
    }

