        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }
    usleep(20000); // 20 ms delay
    return 0;
}

// Read Sensor Data
int read_sensor_data(int fd, int16_t *pressure, int16_t *temperature, uint16_t *crc) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, PRESSURE_REG, data, 6) != 0) {
        fprintf(stderr, "Failed to read sensor data\n");
