    return 1; // Replace with actual CRC calculation
}

// Set LED Blink Rate
int set_led_blink_rate(struct gpiod_line *line, int hz) {
    if (hz == 1) {
        gpiod_line_set_value(line, 1);
        usleep(LED_ON_TIME_MS * 1000);
        gpiod_line_set_value(line, 0);
        usleep(LED_OFF_TIME_MS * 1000);
    } else if (hz == 5) {
        for (int i = 0; i < 5; i++) {
            gpiod_line_set_value(line, 1);
            usleep(100 * 1000);
            gpiod_line_set_value(line, 0);
            usleep(100 * 1000);
        }
    } else {
        fprintf(stderr, "Invalid Hz value: %d\n", hz);
        return -1;
    }
    return 0;
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(i2c_fd, &calibration_data) != 0) {
        fprintf(stderr, "Failed to read calibration data, exiting\n");
        close(i2c_fd);
        return 1;
