    // Initialize libgpiod
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        close(i2c_fd);
        return 1;
    }

    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led_control", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int16_t raw_pressure, raw_temperature;
        uint16_t crc;

        // Trigger measurement
        if (trigger_measurement(i2c_fd) != 0) {
            fprintf(stderr, "Measurement failed, retrying...\n");
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(i2c_fd, &raw_pressure, &raw_temperature, &crc) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        // Verify CRC
        if (!verify_crc(raw_pressure, crc)) {
            fprintf(stderr, "CRC verification failed, retrying...\n");
            usleep(1000000); // Wait 1 second before retrying
            continue;
        }

        // Calculate pressure and temperature
        float pressure = calculate_pressure(raw_pressure, calibration_data);
        float temperature = calculate_temperature(raw_temperature, calibration_data);

        printf("Pressure: %.2f Pa, Temperature: %.2f C\n", pressure, temperature);

        // Control LED based on pressure
        if (pressure < PRESSURE_THRESHOLD_LOW) {
            set_led_blink_rate(led_line, 5);
        } else if (pressure > PRESSURE_THRESHOLD_HIGH) {
            set_led_blink_rate(led_line, 1);
        } else {
            set_led_blink_rate(led_line, 0); // Turn off LED
        }

        sleep(1);
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

