#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 30.0
#define TEMP_THRESHOLD_LOW 28.0
#define LOG_FILE "temperature_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus(int bus, int addr);
int read_raw_temperature(int handle, int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
int control_fan(float object_temp);
void signal_handler(int signal);

// Structure for grouping sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = open_i2c_bus(I2C_BUS, MLX90614_ADDR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read raw temperatures
        int raw_ambient_temp = read_raw_temperature(i2c_handle, AMBIENT_TEMP_REG);
        int raw_object_temp = read_raw_temperature(i2c_handle, OBJECT_TEMP_REG);

        // Convert to Celsius
        float ambient_temp = convert_to_celsius(raw_ambient_temp);
        float object_temp = convert_to_celsius(raw_object_temp);

        // Log temperature
        if (log_temperature(ambient_temp, object_temp) != 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        // Control fan
        if (control_fan(object_temp) != 0) {
            fprintf(stderr, "Failed to control fan.\n");
        }

        // Wait 2 seconds
        sleep(2);
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

