    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f C, Object: %.2f C\n", s, ambient_temp, object_temp);
    fclose(fp);
    return 0;
}

// Control fan based on object temperature
int control_fan(float object_temp) {
    if (object_temp > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn on fan
    } else if (object_temp < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn off fan
    }
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

