// HDC2010 I2C address
#define HDC2010_ADDR 0x40

// HDC2010 register addresses
#define MEASUREMENT_CONFIG 0x0E
#define TEMPERATURE_REG 0x00
#define HUMIDITY_REG 0x02
#define CONFIG_REG 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
    terminate = 1;
}

// Function to initialize the HDC2010 sensor
int init_hdc2010() {
    // Configure the sensor (heater disabled, 14-bit resolution)
    if (i2cWriteByteData(i2c_handle, CONFIG_REG, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to trigger a temperature and humidity measurement
int trigger_measurement() {
    // Write 0x01 to the MEASUREMENT_CONFIG register to trigger a measurement
    if (i2cWriteByteData(i2c_handle, MEASUREMENT_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to MEASUREMENT_CONFIG register\n");
        return -1;
    }
    return 0;
}

// Function to read temperature and humidity data
int read_hdc2010(float *temperature, float *humidity) {
    unsigned char data[4];
    int retries = 5; // Maximum retries
    int result;

    // Poll MEASUREMENT_CONFIG register until bit 0 clears or timeout
    while (retries > 0) {
        result = i2cReadByteData(i2c_handle, MEASUREMENT_CONFIG);
        if (result < 0) {
            fprintf(stderr, "Error reading MEASUREMENT_CONFIG register, retrying...\n");
            gpioDelay(100); // Wait 100ms before retrying
            retries--;
            continue;
        }
        if ((result & 0x01) == 0) {
            break; // Measurement complete
        }
        gpioDelay(100); // Wait 100ms
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for measurement completion\n");
        return -1;
    }

    // Read temperature and humidity registers
    result = i2cReadI2CBlockData(i2c_handle, TEMPERATURE_REG, (char *)data, 4);
    if (result < 0) {
        fprintf(stderr, "Error reading temperature and humidity registers\n");
        return -1;
    }

    // Convert raw data to temperature and humidity
    int raw_temperature = (data[0] << 8) | data[1];
    int raw_humidity = (data[2] << 8) | data[3];

    *temperature = ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
    *humidity = ((float)raw_humidity / 65536.0) * 100.0;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HDC2010_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the HDC2010 sensor
    if (init_hdc2010() < 0) {
        fprintf(stderr, "HDC2010 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float temperature, humidity;
    while (!terminate) {
        // Trigger measurement
        if (trigger_measurement() < 0) {
            fprintf(stderr, "Measurement trigger failed\n");
        } else {
            // Read temperature and humidity
            if (read_hdc2010(&temperature, &humidity) == 0) {
                // Log the values
                printf("Temperature: %.2f °C, Humidity: %.2f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Failed to read temperature and humidity\n");
            }
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

