#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x25
#define CONTINUOUS_MEASUREMENT_COMMAND 0x362F
#define CRC_POLYNOMIAL 0x31
#define CRC_INITIAL_VALUE 0xFF
#define MEASUREMENT_INTERVAL_MS 500

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int write_command(int handle, uint16_t command);
int read_data(int handle, char *buffer, int count);
int16_t read_pressure(char *buffer);
int16_t read_temperature(char *buffer);
uint8_t calculate_crc(uint8_t data[], int len);
void log_data(int16_t pressure, int16_t temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write command to the sensor
int write_command(int handle, uint16_t command) {
    char buffer[2];
    buffer[0] = (command >> 8) & 0xFF;
    buffer[1] = command & 0xFF;

    int result = i2cWriteDevice(handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(int handle, char *buffer, int count) {
    int result = i2cReadDevice(handle, buffer, count);
    if (result != count) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }
    return 0;
}

// Read pressure value from buffer
int16_t read_pressure(char *buffer) {
    return (int16_t)((buffer[0] << 8) | buffer[1]);
}

// Read temperature value from buffer
int16_t read_temperature(char *buffer) {
    return (int16_t)((buffer[3] << 8) | buffer[4]);
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(uint8_t data[], int len) {
    uint8_t crc = CRC_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to the console
void log_data(int16_t pressure, int16_t temperature) {
    printf("Pressure: %d Pa, Temperature: %d \u00b0C\n", pressure, temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger continuous measurement
        if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (45 ms)
        gpioDelay(45000); // 45 ms

        // Read data
        char buffer[6];
        if (read_data(i2c_handle, buffer, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract pressure and temperature
        int16_t pressure = read_pressure(buffer);
        int16_t temperature = read_temperature(buffer);

        // CRC Check
        uint8_t pressure_data[2] = {buffer[0], buffer[1]};
        uint8_t temperature_data[2] = {buffer[3], buffer[4]};

        uint8_t pressure_crc = buffer[2];
        uint8_t temperature_crc = buffer[5];

        if (calculate_crc(pressure_data, 2) != pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed!\n");
            continue;
        }

        if (calculate_crc(temperature_data, 2) != temperature_crc) {
            fprintf(stderr, "Temperature CRC check failed!\n");
            continue;
        }

        // Log data
        log_data(pressure, temperature);

        // Wait before next measurement
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

