    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Log data to the console
void log_data(int16_t pressure, int16_t temperature) {
    printf("Pressure: %d Pa, Temperature: %d \u00b0C\n", pressure, temperature);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Trigger continuous measurement
        if (write_command(i2c_handle, CONTINUOUS_MEASUREMENT_COMMAND) != 0) {
            fprintf(stderr, "Failed to trigger measurement, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for measurement to complete (45 ms)
        gpioDelay(45000); // 45 ms

        // Read data
        char buffer[6];
        if (read_data(i2c_handle, buffer, 6) != 0) {
            fprintf(stderr, "Failed to read data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Extract pressure and temperature
        int16_t pressure = read_pressure(buffer);
        int16_t temperature = read_temperature(buffer);

        // CRC Check
        uint8_t pressure_data[2] = {buffer[0], buffer[1]};
        uint8_t temperature_data[2] = {buffer[3], buffer[4]};

        uint8_t pressure_crc = buffer[2];
        uint8_t temperature_crc = buffer[5];

        if (calculate_crc(pressure_data, 2) != pressure_crc) {
            fprintf(stderr, "Pressure CRC check failed!\n");
            continue;
        }

        if (calculate_crc(temperature_data, 2) != temperature_crc) {
            fprintf(stderr, "Temperature CRC check failed!\n");
            continue;
        }

        // Log data
        log_data(pressure, temperature);

        // Wait before next measurement
        gpioDelay(MEASUREMENT_INTERVAL_MS * 1000); // Convert ms to us
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

