#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL_0 0
#define SPI_CHANNEL_1 1
#define SPI_SPEED 1000000 // 1 MHz
#define REFLOW_PIN 17
#define PWM_FREQUENCY 1000 // 1 kHz
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_LINES 100

// Global variables
int spi_handle_0, spi_handle_1;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for PID controller parameters
typedef struct {
    double Kp;
    double Ki;
    double Kd;
} PIDParams;

// Structure for reflow profile
typedef struct {
    int time_seconds;
    double target_temp_celsius;
} ReflowProfile;

ReflowProfile profile[MAX_PROFILE_LINES];
int profile_length = 0;

// Function prototypes
int read_max6675(int spi_channel);
double pid_control(double setpoint, double actual_temp, PIDParams params, double *integral, double *previous_error);
void set_reflow_output(double duty_cycle);
void log_data(double temp0, double temp1, double pid_output);
void signal_handler(int signal);
int load_profile(const char *filename);

// Function to read temperature from MAX6675 thermocouple
int read_max6675(int spi_channel) {
    char buffer[2];
    int raw_data;

    if (spi_channel == SPI_CHANNEL_0) {
        if (spiRead(spi_handle_0, buffer, 2) != 2) {
            fprintf(stderr, "Error reading SPI channel 0\n");
            return -1; // Indicate error
        }
        raw_data = (buffer[0] << 8) | buffer[1];
    } else if (spi_channel == SPI_CHANNEL_1) {
        if (spiRead(spi_handle_1, buffer, 2) != 2) {
            fprintf(stderr, "Error reading SPI channel 1\n");
            return -1; // Indicate error
        }
        raw_data = (buffer[0] << 8) | buffer[1];
    } else {
        fprintf(stderr, "Invalid SPI channel: %d\n", spi_channel);
        return -1;
    }

    // Check for open circuit
    if (raw_data & 0x0004) {
        fprintf(stderr, "Thermocouple open circuit on channel %d\n", spi_channel);
        return -1; // Indicate sensor error
    }

    // Extract temperature data (bits 3-14)
    raw_data = raw_data >> 3;
    return raw_data;
}

// Function to implement PID controller
double pid_control(double setpoint, double actual_temp, PIDParams params, double *integral, double *previous_error) {
    double error = setpoint - actual_temp;
    *integral += error;
    double derivative = error - *previous_error;
    double output = (params.Kp * error) + (params.Ki * (*integral)) + (params.Kd * derivative);
    *previous_error = error;

    // Clamp the output to the range [0.0, 1.0]
    if (output < 0.0) {
        output = 0.0;
    } else if (output > 1.0) {
        output = 1.0;
    }

    return output;
}

// Function to set the reflow oven output using PWM
void set_reflow_output(double duty_cycle) {
    int pwm_value = (int)(duty_cycle * 255.0); // pigpio PWM range is 0-255
    gpioPWM(REFLOW_PIN, pwm_value);
}

// Function to log data to a CSV file
void log_data(double temp0, double temp1, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, temp0, temp1, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Function to load the reflow profile from a file
int load_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening profile file: %s\n", filename);
        return -1;
    }

    char line[256];
    profile_length = 0;
    while (fgets(line, sizeof(line), fp) != NULL && profile_length < MAX_PROFILE_LINES) {
        if (sscanf(line, "%d,%lf", &profile[profile_length].time_seconds, &profile[profile_length].target_temp_celsius) == 2) {
            profile_length++;
        } else {
            fprintf(stderr, "Invalid line in profile file: %s", line);
        }
    }

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channels
    spi_handle_0 = spiOpen(SPI_CHANNEL_0, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle_0 < 0) {
        fprintf(stderr, "Error opening SPI channel 0: %d\n", spi_handle_0);
        gpioTerminate();
        return 1;
    }

    spi_handle_1 = spiOpen(SPI_CHANNEL_1, SPI_SPEED, 0); // CE1, 1MHz, Mode 0
    if (spi_handle_1 < 0) {
        fprintf(stderr, "Error opening SPI channel 1: %d\n", spi_handle_1);
        spiClose(spi_handle_0);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output for PWM
    gpioSetMode(REFLOW_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(REFLOW_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(REFLOW_PIN, 255); // Set PWM range to 0-255

    // Load reflow profile
    if (load_profile(PROFILE_FILE) != 0) {
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle_0);
        spiClose(spi_handle_1);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID controller parameters
    PIDParams pid_params = {0.5, 0.01, 0.1};
    double integral = 0.0, previous_error = 0.0;

    // Main loop
    time_t start_time = time(NULL);
    int current_profile_index = 0;
    while (!terminate && current_profile_index < profile_length) {
        // Read temperatures from thermocouples
        int temp0_raw = read_max6675(SPI_CHANNEL_0);
        int temp1_raw = read_max6675(SPI_CHANNEL_1);

        double temp0 = (double)temp0_raw * 0.25; // Convert to Celsius
        double temp1 = (double)temp1_raw * 0.25; // Convert to Celsius

        // Calculate average temperature
        double avg_temp = (temp0 + temp1) / 2.0;

        // PID control
        double pid_output = pid_control(profile[current_profile_index].target_temp_celsius, avg_temp, pid_params, &integral, &previous_error);

        // Set reflow oven output
        set_reflow_output(pid_output);

        // Log data
        log_data(temp0, temp1, pid_output);

        // Check if the current time exceeds the target time in the profile
        time_t current_time = time(NULL);
        if (difftime(current_time, start_time) >= profile[current_profile_index].time_seconds) {
            current_profile_index++;
            start_time = current_time; // Reset start time for the next step
            integral = 0.0; // Reset integral term
            previous_error = 0.0; // Reset previous error
        }

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup
    spiClose(spi_handle_0);
    spiClose(spi_handle_1);
    gpioPWM(REFLOW_PIN, 0); // Turn off PWM
    fclose(log_file);
    gpioTerminate();

    return 0;
}

