#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define DEHUMIDIFIER_GPIO 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_aht20_data(float *humidity);
void control_dehumidifier(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Structure for AHT20 data
typedef struct {
    uint8_t status;
    uint8_t humidity_msb;
    uint8_t humidity_lsb;
    uint8_t temperature_msb;
    uint8_t temperature_lsb;
} aht20_data_t;

// Function to initialize the AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, init_cmd, 3) == 0) {
            return 0; // Success
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: AHT20 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from the AHT20 sensor
int read_aht20_data(float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    aht20_data_t data;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, trigger_cmd, 3) == 0) {
            gpioDelay(80000); // 80 ms delay

            if (i2cReadDevice(i2c_handle, buf, 6) == 6) {
                data.status = buf[0];
                data.humidity_msb = buf[1];
                data.humidity_lsb = buf[2];
                data.temperature_msb = buf[3];
                data.temperature_lsb = buf[4];

                if ((data.status & 0x80) == 0) {
                    // Sensor is busy
                    fprintf(stderr, "Error: AHT20 busy.\n");
                    return -1;
                }

                if ((data.status & 0x08) != 0) {
                    // Sensor is calibrated
                    uint16_t raw_humidity = ((uint16_t)data.humidity_msb << 8) | data.humidity_lsb;
                    *humidity = ((float)raw_humidity / 0x100000) * 100;
                    return 0; // Success
                } else {
                    fprintf(stderr, "Error: AHT20 not calibrated.\n");
                    return -1;
                }
            } else {
                fprintf(stderr, "Error: I2C read failed.\n");
            }
        } else {
            fprintf(stderr, "Error: I2C write failed.\n");
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

