#define HUMIDITY_THRESHOLD_LOW 55.0
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define POLL_INTERVAL_S 5

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_aht20();
int read_aht20_data(float *humidity);
void control_dehumidifier(float humidity);
