    uint8_t status;
    uint8_t humidity_msb;
    uint8_t humidity_lsb;
    uint8_t temperature_msb;
    uint8_t temperature_lsb;
} aht20_data_t;

// Function to initialize the AHT20 sensor
int init_aht20() {
    char init_cmd[3] = {0xBE, 0x08, 0x00};
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, init_cmd, 3) == 0) {
            return 0; // Success
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Error: AHT20 initialization failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to read data from the AHT20 sensor
int read_aht20_data(float *humidity) {
    char trigger_cmd[3] = {0xAC, 0x33, 0x00};
    aht20_data_t data;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, trigger_cmd, 3) == 0) {
