#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <syslog.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <stdint.h>

#define I2C_DEVICE "/dev/i2c-1"
#define API_ENDPOINT "http://api.example.com/humidity"
#define HTU21D_ADDR 0x40
#define MEASURE_HUMIDITY 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

int i2c_fd = -1;

// Function to calculate CRC8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x131; // Polynomial X^8 + X^5 + X^4 + 1
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read humidity from HTU21D sensor
float read_humidity() {
    uint8_t cmd = MEASURE_HUMIDITY;
    uint8_t data[3];
    int retries = RETRY_COUNT;

    while (retries > 0) {
        if (write(i2c_fd, &cmd, 1) != 1) {
            syslog(LOG_ERR, "Failed to write to I2C device: %s", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        usleep(50000); // Wait for measurement (at least 50ms)

        if (read(i2c_fd, data, 3) != 3) {
            syslog(LOG_ERR, "Failed to read from I2C device: %s", strerror(errno));
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        // CRC Check
        uint8_t crc = crc8(data, 2);
        if (crc != data[2]) {
            syslog(LOG_ERR, "CRC check failed");
            retries--;
            usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
            continue;
        }

        // Convert data to humidity
        uint16_t raw_humidity = (data[0] << 8) | data[1];
        float humidity = -6.0 + 125.0 * (raw_humidity / 65536.0);

        return humidity;
    }

    syslog(LOG_ERR, "Failed to read humidity after multiple retries");
    return -1.0; // Indicate error
}

// Function to format humidity data as JSON
char *format_json(float humidity) {
    char *json_string = malloc(50); // Allocate memory for the JSON string
    if (json_string == NULL) {
        syslog(LOG_ERR, "Failed to allocate memory for JSON string");
        return NULL;
    }
    snprintf(json_string, 50, "{\"humidity\": %.2f}", humidity);
    return json_string;
}

// Function to send HTTP POST request
int send_http_post(const char *json_data) {
    int sock = 0;
    struct sockaddr_in serv_addr;

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        syslog(LOG_ERR, "Socket creation error: %s", strerror(errno));
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80); // Port 80 for HTTP

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, "api.example.com", &serv_addr.sin_addr) <= 0) {
        syslog(LOG_ERR, "Invalid address/ Address not supported: %s", strerror(errno));
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection Failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char request[256];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: api.example.com\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s", API_ENDPOINT, strlen(json_data), json_data);

    if (send(sock, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Send failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    char buffer[1024] = {0};
    ssize_t bytes_received = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        syslog(LOG_ERR, "Receive failed: %s", strerror(errno));
        close(sock);
        return -1;
    }

    // Basic HTTP response parsing (check for 200 OK)
    if (strstr(buffer, "200 OK") == NULL) {
        syslog(LOG_ERR, "HTTP request failed: %s", buffer);
        close(sock);
        return -1;
    }

    close(sock);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    syslog(LOG_INFO, "Signal received, closing I2C device and exiting...");
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    closelog();
    exit(0);
}

int main() {
    openlog("humidity_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %s", strerror(errno));
        closelog();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to set I2C slave address: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    while (1) {
        float humidity = read_humidity();
        if (humidity >= 0) {
            char *json_data = format_json(humidity);
            if (json_data != NULL) {
                if (send_http_post(json_data) == 0) {
                    syslog(LOG_INFO, "Humidity: %.2f%%, Sent to API", humidity);
                } else {
                    syslog(LOG_ERR, "Failed to send HTTP POST");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(60); // Wait 60 seconds
    }

    // The following lines will never be reached due to the infinite loop.
    close(i2c_fd);
    closelog();
    return 0;
}

