// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_CALIB_00 0x88

// Calibration data structure
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_data;

// Global variables
int i2c_handle;
bmp280_calib_data calib;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_bmp280();
int read_calibration_data(int i2c_handle, bmp280_calib_data *calib);
int read_raw_data(int i2c_handle, int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temperature, bmp280_calib_data calib);
double compensate_pressure(int32_t raw_pressure, int32_t raw_temperature, bmp280_calib_data calib);
void log_pressure_breach(double pressure);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, shutting down...\n", signal);
}

// Initialize BMP280 sensor
int init_bmp280() {
    int retries = 3;
    while (retries > 0) {
        i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Open I2C bus 1
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C bus: %d. Retrying...\n", i2c_handle);
            gpioDelay(100); // Wait before retrying
            retries--;
            continue;
        }

        // Verify chip ID
