#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_DIR "/var/log/sensor_data"
#define RETRY_COUNT 3
#define BACKOFF_DELAY_MS 10

// Global variables
static volatile int running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_i2c();
int read_tmp117(float *temperature);
int read_aht20(float *temperature, float *humidity);
int read_pir();
int log_data(float temperature, float humidity, int motion_detected);
void signal_handler(int signal);
int check_sensor_presence();
int create_log_file();

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int motion_detected;
} sensor_data_t;

// Function to initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }
    return 0;
}

// Function to read temperature from TMP117
int read_tmp117(float *temperature) {
    unsigned char buf[2];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, TMP117_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        if (read(i2c_fd, buf, 2) != 2) {
            perror("Error reading from TMP117");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        // Convert big-endian to signed 16-bit integer
        short raw_temp = (buf[0] << 8) | buf[1];
        *temperature = raw_temp * 0.0078125;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read TMP117 after multiple retries.\n");
    return -1; // Failure
}

// Function to read temperature and humidity from AHT20
int read_aht20(float *temperature, float *humidity) {
    unsigned char init_cmd[3] = {0xBE, 0x08, 0x00};
    unsigned char measure_cmd[3] = {0xAC, 0x33, 0x00};
    unsigned char data[7];
    int retries = RETRY_COUNT;
    int result;

    // Initialize AHT20
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        if (write(i2c_fd, init_cmd, 3) != 3) {
            perror("Error writing init command to AHT20");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }
        usleep(100000); // Wait for initialization to complete
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to initialize AHT20 after multiple retries.\n");
        return -1;
    }

    // Trigger measurement
    retries = RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        if (write(i2c_fd, measure_cmd, 3) != 3) {
            perror("Error writing measure command to AHT20");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }
        break;
    }
    if (retries == 0) {
        fprintf(stderr, "Failed to trigger measurement after multiple retries.\n");
        return -1;
    }

    // Read data
    usleep(80000); // Wait for measurement to complete
    retries = RETRY_COUNT;
    while (retries > 0) {
        if (ioctl(i2c_fd, I2C_SLAVE, AHT20_ADDR) < 0) {
            perror("Error setting I2C slave address");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        if (read(i2c_fd, data, 7) != 7) {
            perror("Error reading data from AHT20");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

        // Check busy bit
        if (data[0] & 0x80) {
            fprintf(stderr, "AHT20 busy.\n");
            retries--;
            usleep(BACKOFF_DELAY_MS * 1000);
            continue;
        }

