// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Global flag to indicate program termination
volatile sig_atomic_t program_running = 1;

// Structure to hold CPU statistics
typedef struct {
    unsigned long user;
    unsigned long nice;
    unsigned long system;
    unsigned long idle;
    unsigned long iowait;
    unsigned long irq;
    unsigned long softirq;
} cpu_stats_t;

// Function prototypes
cpu_stats_t read_cpu_stats();
float calculate_cpu_load(cpu_stats_t prev, cpu_stats_t curr);
void map_cpu_load_to_color(float cpu_load, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Function to read CPU statistics from /proc/stat
cpu_stats_t read_cpu_stats() {
    cpu_stats_t stats;
    FILE *fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening /proc/stat\n");
        stats.user = 0; stats.nice = 0; stats.system = 0; stats.idle = 0; stats.iowait = 0; stats.irq = 0; stats.softirq = 0;
        return stats;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading /proc/stat\n");
        fclose(fp);
        stats.user = 0; stats.nice = 0; stats.system = 0; stats.idle = 0; stats.iowait = 0; stats.irq = 0; stats.softirq = 0;
        return stats;
    }

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected format in /proc/stat\n");
        fclose(fp);
        stats.user = 0; stats.nice = 0; stats.system = 0; stats.idle = 0; stats.iowait = 0; stats.irq = 0; stats.softirq = 0;
        return stats;
    }

