#include <arpa/inet.h>
#include <pigpio.h>

// BMP280 I2C address
#define BMP280_I2C_ADDR 0x76

// BMP280 register addresses
#define BMP280_REG_CHIPID 0xD0
#define BMP280_REG_RESET 0xE0
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_PRESS_LSB 0xF8
#define BMP280_REG_PRESS_XLSB 0xF9
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_TEMP_LSB 0xFB
#define BMP280_REG_TEMP_XLSB 0xFC
#define BMP280_REG_CALIB_00 0x88

// UDP server address and port
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000

// Global variables
int i2c_handle;
int udp_socket;
struct sockaddr_in server_addr;

// Calibration data structure
struct bmp280_calib_data {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
};

struct bmp280_calib_data calib;

// Function prototypes
int init_i2c();
int init_udp_socket();
int read_calibration_data();
int read_raw_data(int32_t *temperature, int32_t *pressure);
double compensate_temperature(int32_t raw_temp);
double compensate_pressure(int32_t raw_pressure, double t_fine);
char* format_json(double temperature, double pressure);
int send_udp_packet(const char *json_string);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // I2C bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_CHIPID);
    if (chip_id < 0) {
        fprintf(stderr, "Error reading chip ID: %d\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    if (chip_id != 0x58) {
        fprintf(stderr, "Incorrect chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        fprintf(stderr, "Error reading calibration data\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int init_udp_socket() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return -1;
    }

    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Read calibration data from the BMP280
int read_calibration_data() {
    uint8_t buffer[26];
    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, (char *)buffer, 26) < 0) {
        fprintf(stderr, "Error reading calibration data block\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)buffer[0] | ((uint16_t)buffer[1] << 8);
    calib.dig_T2 = (int16_t)buffer[2] | ((int16_t)buffer[3] << 8);
    calib.dig_T3 = (int16_t)buffer[4] | ((int16_t)buffer[5] << 8);
    calib.dig_P1 = (uint16_t)buffer[6] | ((uint16_t)buffer[7] << 8);
    calib.dig_P2 = (int16_t)buffer[8] | ((int16_t)buffer[9] << 8);
    calib.dig_P3 = (int16_t)buffer[10] | ((int16_t)buffer[11] << 8);
    calib.dig_P4 = (int16_t)buffer[12] | ((int16_t)buffer[13] << 8);
    calib.dig_P5 = (int16_t)buffer[14] | ((int16_t)buffer[15] << 8);
    calib.dig_P6 = (int16_t)buffer[16] | ((int16_t)buffer[17] << 8);
    calib.dig_P7 = (int16_t)buffer[18] | ((int16_t)buffer[19] << 8);
    calib.dig_P8 = (int16_t)buffer[20] | ((int16_t)buffer[21] << 8);
    calib.dig_P9 = (int16_t)buffer[22] | ((int16_t)buffer[23] << 8);

    return 0;
}

// Read raw temperature and pressure data from the BMP280
int read_raw_data(int32_t *temperature, int32_t *pressure) {
    uint8_t buffer[6];

    // Set the sensor to forced mode
    if (i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x3F) < 0) {
        fprintf(stderr, "Error writing to control register\n");
        return -1;
    }

    // Wait for the measurement to complete (adjust as needed)
    gpioDelay(10); // 10 ms delay

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_PRESS_MSB, (char *)buffer, 6) < 0) {
        fprintf(stderr, "Error reading raw data\n");
        return -1;
    }

    *pressure = ((int32_t)buffer[0] << 12) | ((int32_t)buffer[1] << 4) | ((int32_t)buffer[2] >> 4);
    *temperature = ((int32_t)buffer[3] << 12) | ((int32_t)buffer[4] << 4) | ((int32_t)buffer[5] >> 4);

    return 0;
}

// Compensate temperature using the BMP280 formula
double compensate_temperature(int32_t raw_temp) {
    double var1, var2, T;
    double t_fine;

    var1 = (((double)raw_temp / 16384.0) - ((double)calib.dig_T1) / 1024.0) * ((double)calib.dig_T2);
    var2 = ((((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0) * (((double)raw_temp / 131072.0) - ((double)calib.dig_T1) / 8192.0)) * ((double)calib.dig_T3);
    t_fine = (var1 + var2);
    T = (t_fine / 5120.0);
    return T;
}

// Compensate pressure using the BMP280 formula
double compensate_pressure(int32_t raw_pressure, double t_fine) {
    double var1, var2, p;

    var1 = ((double)t_fine / 2.0) - 64000.0;
    var2 = var1 * var1 * ((double)calib.dig_P6) / 32768.0;
    var2 = var2 + var1 * ((double)calib.dig_P5) * 2.0;
    var2 = (var2 / 4.0) + (((double)calib.dig_P4) * 65536.0);
    var1 = (((double)calib.dig_P3) * var1 * var1 / 524288.0 + ((double)calib.dig_P2) * var1) / 524288.0;
    var1 = (1.0 + var1 / 32768.0) * ((double)calib.dig_P1);

    if (var1 == 0)
    {
        return 0;
    }

    p = 1048576.0 - (double)raw_pressure;
    p = (p - (var2 / 4096.0)) * 6250.0 / var1;
    var1 = ((double)calib.dig_P9) * p * p / 2147483648.0;
    var2 = p * ((double)calib.dig_P8) / 32768.0;
    p = p + (var1 + var2 + ((double)calib.dig_P7)) / 16.0;

    return p;
}

// Format temperature and pressure data into a JSON string
char* format_json(double temperature, double pressure) {
    char *json_string = (char*)malloc(100 * sizeof(char)); // Allocate memory for the JSON string
    if (json_string == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }
    sprintf(json_string, "{\"temperature\": %.2f, \"pressure\": %.2f}", temperature, pressure);
    return json_string;
}

// Send the JSON string over UDP
int send_udp_packet(const char *json_string) {
    if (sendto(udp_socket, json_string, strlen(json_string), 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error sending UDP packet");
        return -1;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
