#include <pigpio.h>
#include <string.h>

// Constants
#define FAN_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define SPI_MODE 0
#define BUFFER_SIZE 20

// Temperature thresholds
#define TEMP_LOW 25.0
#define TEMP_HIGH 60.0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure for the circular buffer
typedef struct {
    time_t timestamp;
    float temperature;
    int duty_cycle;
} LogEntry;

LogEntry log_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_pigpio();
int open_spi_channel();
int read_max31855(int spi_handle, float *temperature);
int calculate_duty_cycle(float temperature);
void set_fan_speed(int gpio, int duty_cycle);
void log_data(float temperature, int duty_cycle);
void print_log_buffer();
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open SPI channel
int open_spi_channel() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from MAX31855
int read_max31855(int spi_handle, float *temperature) {
    char tx_buf[4] = {0}; // Dummy data for SPI transfer
    char rx_buf[4];

    if (spiXfer(spi_handle, tx_buf, rx_buf, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Combine the bytes into a 32-bit integer
    int32_t raw_data = (rx_buf[0] << 24) | (rx_buf[1] << 16) | (rx_buf[2] << 8) | rx_buf[3];

    // Check for fault bits
    if (raw_data & 0x00000001) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1;
    }
    if (raw_data & 0x00000002) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1;
    }
    if (raw_data & 0x00000004) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1;
    }

    // Extract the thermocouple temperature (bits 31:18)
    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF; // Mask out the relevant bits

    // Check for negative temperature
    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend if negative
    }

    *temperature = thermocouple_data * 0.25;

    return 0;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < TEMP_LOW) {
        duty_cycle = 0;
    } else if (temperature >= TEMP_LOW && temperature <= TEMP_HIGH) {
        duty_cycle = (int)((temperature - TEMP_LOW) / (TEMP_HIGH - TEMP_LOW) * 50.0);
    } else if (temperature > TEMP_HIGH) {
        duty_cycle = 100;
    }

    return duty_cycle;
}

// Function to set fan speed using PWM
void set_fan_speed(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
}

// Function to log data to the circular buffer
void log_data(float temperature, int duty_cycle) {
    time(&log_buffer[buffer_index].timestamp);
    log_buffer[buffer_index].temperature = temperature;
    log_buffer[buffer_index].duty_cycle = duty_cycle;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print the contents of the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer Contents ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        struct tm *timeinfo;
        char timestamp_str[20];
        timeinfo = localtime(&log_buffer[i].timestamp);
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f°C, Duty Cycle: %d\n", timestamp_str, log_buffer[i].temperature, log_buffer[i].duty_cycle);
    }
    printf("--- End of Log Buffer ---\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open SPI channel
    if (open_spi_channel() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency to 1 kHz
    gpioSetPWMfrequency(FAN_GPIO, 1000);

    float temperature;
    int duty_cycle;

    // Main loop
    while (!terminate) {
        // Read temperature from MAX31855
        if (read_max31855(spi_handle, &temperature) == 0) {
            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature);

            // Set fan speed
            set_fan_speed(FAN_GPIO, duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);

            printf("Temperature: %.2f°C, Duty Cycle: %d\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping fan update.\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Stop PWM
    gpioPWM(FAN_GPIO, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Print log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

