#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <errno.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_SPEED 1000000 // 1 MHz
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define LOG_FILE "rtd_log.csv"
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
void spi_close(void);
int gpio_init(void);
void gpio_close(void);
int log_init(void);
void log_close(void);
int read_max31865(uint32_t *raw_data);
float calculate_temperature(uint32_t raw_data);
void log_data(float temperature);
void signal_handler(int sig);

// SPI Initialization
int spi_init(void) {
    int ret = 0;
    uint8_t mode = SPI_MODE;
    uint32_t speed = SPI_SPEED;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set SPI speed
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI Close
void spi_close(void) {
    if (spi_fd != -1) {
        close(spi_fd);
        spi_fd = -1;
    }
}

// GPIO Initialization
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(cs_line, "rtd_monitor", 1); // Initial value HIGH
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO Close
void gpio_close(void) {
    if (cs_line) {
        gpiod_line_release(cs_line);
        cs_line = NULL;
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
        gpio_chip = NULL;
    }
}

// Log File Initialization
int log_init(void) {
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        return -1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }

    return 0;
}

// Log File Close
void log_close(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
}

// Read MAX31865 Data
int read_max31865(uint32_t *raw_data) {
    uint8_t tx_buf[4] = {0}; // Dummy data for reading
    uint8_t rx_buf[4];
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    gpiod_line_set_value(cs_line, 0); // Select the chip
    int ret = ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer);
    gpiod_line_set_value(cs_line, 1); // Deselect the chip

    if (ret < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    *raw_data = ((uint32_t)rx_buf[0] << 24) | ((uint32_t)rx_buf[1] << 16) | ((uint32_t)rx_buf[2] << 8) | (uint32_t)rx_buf[3];

    return 0;
}

// Calculate Temperature (Callendar-Van Dusen)
float calculate_temperature(uint32_t raw_data) {
    // Extract RTD value (bits 18:0)
    uint32_t rtd_data = raw_data >> 16; // Shift right by 16 bits
    rtd_data &= 0x3FFF; // Mask to 14 bits

    // Check for fault
    if (raw_data & 0x0001) {
        fprintf(stderr, "Fault detected: %08X\n", raw_data);
        return NAN; // Return NaN for error
    }

    // Callendar-Van Dusen equation (simplified for 3-wire PT100)
    float rtd_resistance = (rtd_data * 430.0) / 32768.0; // Assuming 430 Ohm reference resistor
    float temperature = (rtd_resistance - 100.0) / 0.385; // PT100 temperature coefficient

    return temperature;
}

// Log Data to File
void log_data(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk
}

// Signal Handler
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main(void) {
    uint32_t raw_data;
    float temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize hardware
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed, exiting.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed, exiting.\n");
        spi_close();
        return 1;
    }

    if (log_init() != 0) {
        fprintf(stderr, "Log file initialization failed, exiting.\n");
        gpio_close();
        spi_close();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_max31865(&raw_data) == 0) {
            temperature = calculate_temperature(raw_data);
            if (!isnan(temperature)) {
                log_data(temperature);
                printf("Temperature: %.2f C\n", temperature);
            } else {
                fprintf(stderr, "Error: Invalid temperature reading.\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read MAX31865 data.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    log_close();
    gpio_close();
    spi_close();

    return 0;
}

