#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BMP180_ADDR 0x77
#define GPIO_ALERT 24
#define SAMPLE_INTERVAL_MS 50
#define BUFFER_SIZE 120 // 60 seconds * 2 (pressure and temperature)
#define DEVICE_ID_REG 0xD0
#define DEVICE_ID 0x55
#define CALIBRATION_DATA_START 0xAA
#define CALIBRATION_DATA_LENGTH 22
#define PRESSURE_REG 0xF4
#define TEMPERATURE_REG 0xF6
#define OSS 0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data structure
typedef struct {
    int16_t ac1;
    int16_t ac2;
    int16_t ac3;
    uint16_t ac4;
    uint16_t ac5;
    uint16_t ac6;
    int16_t b1;
    int16_t b2;
    int16_t mb;
    int16_t mc;
    int16_t md;
} bmp180_calibration_data_t;

bmp180_calibration_data_t calibration_data;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

circular_buffer_t pressure_buffer;

// Function prototypes
int init_i2c();
int read_calibration_data(bmp180_calibration_data_t *calibration);
int read_raw_temperature(int *raw_temperature);
int read_raw_pressure(int *raw_pressure);
float calculate_temperature(int raw_temperature, const bmp180_calibration_data_t *calibration);
float calculate_pressure(int raw_pressure, int raw_temperature, const bmp180_calibration_data_t *calibration);
void add_to_buffer(circular_buffer_t *buffer, float value);
float calculate_rolling_average(const circular_buffer_t *buffer);
void check_pressure_deviation(float current_pressure);
void timer_callback();
void signal_handler(int signal);
void log_error(const char *message);

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data(bmp180_calibration_data_t *calibration) {
    char data[CALIBRATION_DATA_LENGTH];
    if (i2cReadI2CBlockData(i2c_handle, CALIBRATION_DATA_START, data, CALIBRATION_DATA_LENGTH) != CALIBRATION_DATA_LENGTH) {
        log_error("Failed to read calibration data");
        return -1;
    }

    calibration->ac1 = (data[0] << 8) | data[1];
    calibration->ac2 = (data[2] << 8) | data[3];
    calibration->ac3 = (data[4] << 8) | data[5];
    calibration->ac4 = (data[6] << 8) | data[7];
    calibration->ac5 = (data[8] << 8) | data[9];
    calibration->ac6 = (data[10] << 8) | data[11];
    calibration->b1 = (data[12] << 8) | data[13];
    calibration->b2 = (data[14] << 8) | data[15];
    calibration->mb = (data[16] << 8) | data[17];
    calibration->mc = (data[18] << 8) | data[19];
    calibration->md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature data
int read_raw_temperature(int *raw_temperature) {
    if (i2cWriteByteData(i2c_handle, TEMPERATURE_REG, 0x2E) != 0) {
        log_error("Failed to write temperature conversion command");
        return -1;
    }
    gpioDelay(5); // Wait 5 ms
    if (i2cReadWordData(i2c_handle, TEMPERATURE_REG) < 0) {
        log_error("Failed to read raw temperature data");
        return -1;
    }
    *raw_temperature = i2cReadWordData(i2c_handle, TEMPERATURE_REG);
    return 0;
}

// Function to read raw pressure data
int read_raw_pressure(int *raw_pressure) {
    if (i2cWriteByteData(i2c_handle, PRESSURE_REG, 0x34 + (OSS << 6)) != 0) {
        log_error("Failed to write pressure conversion command");
        return -1;
    }
    gpioDelay(5); // Wait 5 ms
    if (i2cReadWordData(i2c_handle, PRESSURE_REG) < 0) {
        log_error("Failed to read raw pressure data");
        return -1;
    }
    *raw_pressure = i2cReadWordData(i2c_handle, PRESSURE_REG);
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int raw_temperature, const bmp180_calibration_data_t *calibration) {
    long x1 = ((long)raw_temperature - (long)calibration->ac6) * ((long)calibration->ac5) / pow(2, 15);
    long x2 = ((long)calibration->mc * pow(2, 11)) / (x1 + calibration->md);
    long b5 = x1 + x2;
    float temperature = (b5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
float calculate_pressure(int raw_pressure, int raw_temperature, const bmp180_calibration_data_t *calibration) {
    long x1 = ((long)raw_temperature - (long)calibration->ac6) * ((long)calibration->ac5) / pow(2, 15);
    long x2 = ((long)calibration->mc * pow(2, 11)) / (x1 + calibration->md);
    long b5 = x1 + x2;

    long b6 = b5 - 4000;
    long x3 = ((long)calibration->b2 * (b6 * b6) / pow(2, 12)) / pow(2, 11);
    long x4 = ((long)calibration->ac2 * b6) / pow(2, 11);
    long b3 = (((((long)calibration->ac1) * 4 + x3) << OSS) + 2) / 4;

    unsigned long b4 = ((unsigned long)calibration->ac4 * (unsigned long)(x3 + x4 + 32768)) / pow(2, 15);
    unsigned long b7 = ((unsigned long)raw_pressure - b3) * (50000 >> OSS);

    long p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }

    x1 = (p / pow(2, 8)) * (p / pow(2, 8));
    x1 = (x1 * 3038) / pow(2, 16);
    x2 = (-7357 * p) / pow(2, 16);
    float pressure = p + (x1 + x2 + 3791) / pow(2, 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to add a value to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to calculate the rolling average of the pressure readings
float calculate_rolling_average(const circular_buffer_t *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Function to check for pressure deviation
void check_pressure_deviation(float current_pressure) {
    float rolling_average = calculate_rolling_average(&pressure_buffer);
    float deviation = current_pressure - rolling_average;
    if (fabs(deviation) > 5.0) {
        gpioWrite(GPIO_ALERT, 1); // Set GPIO HIGH
        fprintf(stderr, "ALERT: Pressure deviation detected! Current: %.2f hPa, Rolling Average: %.2f hPa, Deviation: %.2f hPa\n", current_pressure, rolling_average, deviation);
    } else {
        gpioWrite(GPIO_ALERT, 0); // Set GPIO LOW
    }
}

// Timer callback function
void timer_callback() {
    int raw_temperature, raw_pressure;
    float temperature, pressure;

    // Check for sensor presence by reading the device ID
    char device_id;
    if (i2cReadByteData(i2c_handle, DEVICE_ID_REG) < 0) {
        log_error("Failed to read device ID");
        return;
    }
    device_id = i2cReadByteData(i2c_handle, DEVICE_ID_REG);

    if (device_id != DEVICE_ID) {
        log_error("Sensor not present or ID mismatch");
        return;
    }

    if (read_raw_temperature(&raw_temperature) != 0) {
        return;
    }
    if (read_raw_pressure(&raw_pressure) != 0) {
        return;
    }

    temperature = calculate_temperature(raw_temperature, &calibration_data);
    pressure = calculate_pressure(raw_pressure, raw_temperature, &calibration_data);

    printf("Temperature: %.2f C, Pressure: %.2f hPa\n", temperature, pressure);

    add_to_buffer(&pressure_buffer, pressure);
    check_pressure_deviation(pressure);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

// Function to log errors to stderr
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    fprintf(stderr, "%d-%02d-%02d %02d:%02d:%02d: ERROR: %s\n",
            t->tm_year + 1900, t->tm_mon + 1, t->tm_mday, t->tm_hour, t->tm_min, t->tm_sec, message);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data(&calibration_data) != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize GPIO for alert
    gpioSetMode(GPIO_ALERT, PI_OUTPUT);
    gpioWrite(GPIO_ALERT, 0); // Set LOW initially

    // Initialize circular buffer
    pressure_buffer.head = 0;
    pressure_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up timer function
    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_MS, timer_callback, NULL) != 0) {
        log_error("Failed to set timer function");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("BMP180 pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        gpioDelay(100); // Sleep to reduce CPU usage
    }

    // Clean up
    gpioSetTimerFuncEx(0, 0, NULL, NULL); // Disable timer
    i2cClose(i2c_handle);
    gpioWrite(GPIO_ALERT, 0); // Set LOW before exiting
    gpioTerminate();

    printf("BMP180 pressure sensor monitoring stopped.\n");

    return 0;
}

