}

// Read raw pressure value
int read_raw_pressure(int *raw_pressure) {
    char buf[3];
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) != 0) {
        fprintf(stderr, "Failed to write pressure read command\n");
        return 1;
    }
    gpioDelay(2 + (3 << BMP180_OSS)) ; // Wait for conversion

    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3) {
        fprintf(stderr, "Failed to read raw pressure data\n");
        return 1;
    }

    *raw_pressure = ((buf[0] << 16) | (buf[1] << 8) | buf[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Calculate temperature in degrees Celsius
double calculate_temperature(int raw_temp) {
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;
    double temperature = (B5 + 8) / pow(2, 4) / 10.0;
    return temperature;
}

// Calculate pressure in Pascals
double calculate_pressure(int raw_pressure, int raw_temp) {
    long X1 = ((long)raw_temp - (long)ac6) * ((long)ac5) / pow(2, 15);
    long X2 = ((long)mc * pow(2, 11)) / (X1 + md);
    long B5 = X1 + X2;

    long B6 = B5 - 4000;
    long X3 = ((long)b2 * (B6 * B6) / pow(2, 12)) / pow(2, 11);
    long X4 = ((long)ac2 * B6) / pow(2, 11);
    long B3 = (((((long)ac1) * 4 + X3) << BMP180_OSS) + 2) / 4;

    unsigned long X5 = ((long)ac4 * (unsigned long)(B6)) / pow(2, 15);
    unsigned long X6 = ((unsigned long)X5 * (unsigned long)(X5)) / pow(2, 13);
    unsigned long X7 = ((unsigned long)X6 * (unsigned long)(ac3)) / pow(2, 16);
    unsigned long B4 = ((unsigned long)X7 + X4) / pow(2, 15);

    unsigned long B7 = ((unsigned long)raw_pressure - B3) * (50000 >> BMP180_OSS);
    long p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p / pow(2, 8)) * (p / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * p) / pow(2, 16);
    double pressure = p + (X1 + X2 + 3791) / pow(2, 4);
    return pressure;
}

// Log data to file
int log_data(double temperature, double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f\n", timestamp, temperature, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Timer callback function
void timer_callback() {
    int raw_temp, raw_pressure;
    double temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);

        if (log_data(temperature, pressure) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }
    } else {
        fprintf(stderr, "Failed to read sensor data\n");
    }
}

// Signal handler
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

