#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FAN_GPIO 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"

static volatile int running = 1;

// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    char temp_str[10];
    float temperature = 0.0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file %s\n", TEMP_FILE);
        return -1.0; // Indicate error
    }

    if (fgets(temp_str, sizeof(temp_str), fp) != NULL) {
        temperature = atoi(temp_str) / 1000.0;
    } else {
        fprintf(stderr, "Error: Could not read temperature from file %s\n", TEMP_FILE);
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return temperature;
}

// Function to calculate duty cycle based on temperature
int calculate_duty_cycle(float temperature) {
    int duty_cycle = 0;

    if (temperature < 40.0) {
        duty_cycle = 0;
    } else if (temperature > 70.0) {
        duty_cycle = 255;
    } else {
        duty_cycle = (int)((temperature - 40.0) / (70.0 - 40.0) * 255.0);
    }

    return duty_cycle;
}

// Function to set fan speed using pigpio
void set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f, Duty Cycle: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, duty_cycle);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: Could not close log file %s\n", LOG_FILE);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping fan and cleaning up...\n", signal);
    running = 0;
    set_fan_speed(0); // Stop the fan
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for PWM output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(FAN_GPIO, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature = read_cpu_temp();
        if (temperature < 0) {
            fprintf(stderr, "Error: Could not read CPU temperature. Retrying in 5 seconds.\n");
            sleep(5);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        set_fan_speed(duty_cycle);
        log_data(temperature, duty_cycle);

        sleep(5);
    }

    return 0;
}

