#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define TEMP_REG 0x00
#define GPIO_LED 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SLEEP_SECONDS 1

// Global variables
int i2c_handle;
double temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
pthread_mutex_t buffer_mutex;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_temperature(int *raw_temp);
double convert_to_celsius(int raw_temp);
void update_circular_buffer(double temperature);
double calculate_running_average();
void control_led(double average_temperature);
void *data_acquisition_thread(void *arg);
void signal_handler(int signal);

// Structure to pass arguments to the thread
typedef struct {
    int i2c_bus;
    int lm75_address;
    int gpio_led;
} thread_args_t;

int main() {
    pthread_t data_thread;
    thread_args_t thread_args = {I2C_BUS, LM75_ADDR, GPIO_LED};

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed\n");
        pthread_mutex_destroy(&buffer_mutex);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 18 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Create data acquisition thread
    if (pthread_create(&data_thread, NULL, data_acquisition_thread, &thread_args) != 0) {
        fprintf(stderr, "Thread creation failed\n");
        i2cClose(i2c_handle);
        pthread_mutex_destroy(&buffer_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop (empty, data acquisition is done in the thread)
    while (program_running) {
        sleep(1);
    }

    // Clean up
    pthread_join(data_thread, NULL);
    i2cClose(i2c_handle);
    pthread_mutex_destroy(&buffer_mutex);
    gpioTerminate();

    printf("Program terminated gracefully.\n");
    return 0;
}

int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

int read_temperature(int *raw_temp) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    *raw_temp = (buf[0] << 8) | buf[1];
    return 0;
}

double convert_to_celsius(int raw_temp) {
    // Shift right by 5 bits and divide by 256.0
    return (double)(raw_temp >> 5) / 256.0;
}

void update_circular_buffer(double temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    pthread_mutex_unlock(&buffer_mutex);
}

double calculate_running_average() {
    double sum = 0.0;
    pthread_mutex_lock(&buffer_mutex);
    for (int i = 0; i < BUFFER_SIZE; i++) {
        sum += temperature_buffer[i];
    }
    pthread_mutex_unlock(&buffer_mutex);
    return sum / BUFFER_SIZE;
}

