#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>
#include <math.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define RTD_RESISTOR 430.0 // Ohms
#define RTD_NOMINAL 100.0 // Ohms
#define TARGET_TEMP 25.0 // Degrees Celsius
#define KP 1.0
#define KI 0.1
#define KD 0.01
#define MAX_TEMP 80.0 // Maximum allowed temperature
#define MAX_PWM_DUTY 1000
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define CONFIG_FILE "heater_config.json"

// Global variables
static volatile int running = 1;
static int spi_handle;
static double target_temperature = TARGET_TEMP;
static double kp = KP;
static double ki = KI;
static double kd = KD;

// Function prototypes
double read_temperature();
double calculate_resistance(int rtd_code);
double calculate_temperature(double resistance);
double calculate_pid(double setpoint, double actual_temperature, double kp, double ki, double kd, double *integral, double *previous_error);
void set_pwm_duty_cycle(double duty_cycle);
void load_configuration();
void signal_handler(int signal);
void log_error(const char *message);

// PID variables
double integral = 0.0;
double previous_error = 0.0;

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char buffer[3];
    int rtd_code;
    double resistance, temperature;

    // Read RTD MSB and LSB registers (0x01 and 0x02)
    if (spiRead(spi_handle, buffer, 3) != 3) {
        log_error("SPI read failed");
        return -1000.0; // Indicate error
    }

    // Check for fault
    if (buffer[0] & 0x01) {
        log_error("MAX31865 fault detected");
        return -1000.0; // Indicate error
    }

    // Extract RTD code (15 bits)
    rtd_code = ((buffer[0] << 8) | buffer[1]) >> 1;

    // Calculate resistance
    resistance = calculate_resistance(rtd_code);

    // Calculate temperature
    temperature = calculate_temperature(resistance);

    return temperature;
}

// Function to calculate resistance from RTD code
double calculate_resistance(int rtd_code) {
    return ((double)rtd_code / 32768.0) * RTD_RESISTOR;
}

// Function to calculate temperature from resistance using Callendar-Van Dusen equation
double calculate_temperature(double resistance) {
    double r0 = RTD_NOMINAL; // Reference resistance at 0°C
    double a = 3.9083e-3;
    double b = -5.775e-7;

    double r = resistance;

    double temperature = (r0 * (1.0 / (1.0 + a * r) - 1.0)) / b;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature, double kp, double ki, double kd, double *integral, double *previous_error) {
    double error = setpoint - actual_temperature;
    *integral += error;
    double derivative = error - *previous_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *previous_error = error;

    // Limit the output to the PWM range
    if (output < 0.0) {
        output = 0.0;
    } else if (output > PWM_RANGE) {
        output = PWM_RANGE;
    }

    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(double duty_cycle) {
    gpioPWM(HEATER_GPIO, (int)duty_cycle);
}

// Function to load configuration from JSON file
void load_configuration() {
    json_t *root;
    json_error_t error;

    root = json_load_file(CONFIG_FILE, 0, &error);

    if (!root) {
        fprintf(stderr, "Error: Could not load config file: %s\n", error.text);
        fprintf(stderr, "Using default configuration.\n");
        return;
    }

    json_t *target_temp_json = json_object_get(root, "target_temperature");
    if (json_is_real(target_temp_json)) {
        target_temperature = json_real_value(target_temp_json);
    }

    json_t *kp_json = json_object_get(root, "kp");
    if (json_is_real(kp_json)) {
        kp = json_real_value(kp_json);
    }

    json_t *ki_json = json_object_get(root, "ki");
    if (json_is_real(ki_json)) {
        ki = json_real_value(ki_json);
    }

    json_t *kd_json = json_object_get(root, "kd");
    if (json_is_real(kd_json)) {
        kd = json_real_value(kd_json);
    }

    json_decref(root);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, shutting down...\n", signal);
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

int main() {
    double temperature, pid_output;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return 1;
    }

    // Load configuration from file
    load_configuration();

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 500kHz, mode 0
    if (spi_handle < 0) {
        log_error("SPI open failed");
        gpioTerminate();
        return 1;
    }

    // Configure MAX31865 (Enable VBIAS, auto-conversion, clear faults)
    unsigned char config_data[2];
    config_data[0] = 0xC1; // Configuration register address
    config_data[1] = 0xC1; // Configuration value (VBIAS, auto-conversion, clear faults)
    spiWrite(spi_handle, config_data, 2);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        temperature = read_temperature();

        if (temperature < -900.0) {
            log_error("Failed to read temperature, shutting down");
            running = 0;
            break;
        }

        if (temperature > MAX_TEMP) {
            log_error("Temperature exceeds maximum limit, shutting down");
            running = 0;
            break;
        }

        pid_output = calculate_pid(target_temperature, temperature, kp, ki, kd, &integral, &previous_error);

        set_pwm_duty_cycle(pid_output);

        gpioDelay(100); // 100 ms delay
    }

    // Shutdown sequence
    set_pwm_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

