#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 0

// Thresholds
#define TEMPERATURE_THRESHOLD 30.0
#define PRESSURE_THRESHOLD 950.0

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Calibration data
static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c(const char *device, int addr);
int read_calibration_data(int fd);
int read_raw_temperature(int fd);
int read_raw_pressure(int fd);
double calculate_temperature(int32_t ut);
double calculate_pressure(int32_t up, int32_t ut);
int log_breach(double temperature, double pressure);
void signal_handler(int sig);
void cleanup();

// I2C initialization function
int init_i2c(const char *device, int addr) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read calibration data from the BMP180
int read_calibration_data(int fd) {
    uint8_t buffer[22];
    if (read(fd, buffer, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    ac1 = (buffer[0] << 8) | buffer[1];
    ac2 = (buffer[2] << 8) | buffer[3];
    ac3 = (buffer[4] << 8) | buffer[5];
    ac4 = (buffer[6] << 8) | buffer[7];
    ac5 = (buffer[8] << 8) | buffer[9];
    ac6 = (buffer[10] << 8) | buffer[11];
    b1 = (buffer[12] << 8) | buffer[13];
    b2 = (buffer[14] << 8) | buffer[15];
    mb = (buffer[16] << 8) | buffer[17];
    mc = (buffer[18] << 8) | buffer[19];
    md = (buffer[20] << 8) | buffer[21];

    return 0;
}

// Function to read raw temperature data from the BMP180
int read_raw_temperature(int fd) {
    uint8_t buffer[2];
    buffer[0] = BMP180_REG_CONTROL;
    buffer[1] = 0x2E; // Temperature measurement command

    if (write(fd, buffer, 2) != 2) {
        perror("Error writing temperature measurement command");
        return -1;
    }

    usleep(5000); // Wait 4.5ms

    buffer[0] = BMP180_REG_MSB;
    if (write(fd, buffer, 1) != 1) {
        perror("Error writing register address for temperature read");
        return -1;
    }

    if (read(fd, buffer, 2) != 2) {
        perror("Error reading raw temperature data");
        return -1;
    }

    return (buffer[0] << 8) | buffer[1];
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int fd) {
    uint8_t buffer[2];
    buffer[0] = BMP180_REG_CONTROL;
    buffer[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (write(fd, buffer, 2) != 2) {
        perror("Error writing pressure measurement command");
        return -1;
    }

    usleep(2 + (3 << BMP180_OSS)); // Wait for conversion

    buffer[0] = BMP180_REG_MSB;
    if (write(fd, buffer, 1) != 1) {
        perror("Error writing register address for pressure read");
        return -1;
    }

    if (read(fd, buffer, 3) != 3) {
        perror("Error reading raw pressure data");
        return -1;
    }

    return ((buffer[0] << 16) | (buffer[1] << 8) | buffer[2]) >> (8 - BMP180_OSS);
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t ut) {
    int32_t x1 = (((int32_t)ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + md);
    int32_t b5 = x1 + x2;
    double temperature = ((b5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t up, int32_t ut) {
