    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(TOGGLE_PIN, PI_INPUT);
    gpioSetPullUpDown(TOGGLE_PIN, PI_PUD_UP);

    // Set interrupt handler for falling edge detection
    gpioSetAlertFunc(TOGGLE_PIN, toggle_logging);

    // Set signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int raw_temperature, raw_pressure;
    double pressure;

    // Main loop
    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate pressure
                pressure = calculate_pressure(raw_temperature, raw_pressure);

                // Log data
                log_data(pressure);
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        }

        gpioDelay(LOGGING_INTERVAL * 1000000); // Delay for 2 seconds
    }

    return 0;
}

