#include <math.h>

// Constants
#define HEATER_GPIO 17
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define MAX_DUTY_CYCLE 80.0
#define DEFAULT_TARGET_TEMPERATURE 25.0
#define LOG_FILE "heater_log.csv"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double target_temperature = DEFAULT_TARGET_TEMPERATURE;

// PI controller parameters
static double Kp = 1.0;
static double Ki = 0.1;
static double integral_limit = 100.0;

// Function prototypes
double read_temperature();
double calculate_duty_cycle(double current_temperature, double target_temperature, double *integral);
void set_heater_duty_cycle(double duty_cycle);
void log_data(double temperature, double duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855 via SPI
double read_temperature() {
    int handle, count;
    char buf[4];
    double temperature = NAN; // Initialize to NaN in case of error

    handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", handle);
        return NAN;
    }

    count = spiRead(handle, buf, 4);
    if (count != 4) {
        fprintf(stderr, "Error reading from SPI: %d\n", count);
        spiClose(handle);
        return NAN;
    }

    spiClose(handle);

    // Check for fault bits
    if (buf[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return NAN;
    }
    if (buf[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return NAN;
    }
    if (buf[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return NAN;
    }

    // Extract temperature data (bits 31:18, signed 14-bit value)
    int16_t raw_temp = ((buf[0] << 8) | buf[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PWM duty cycle using PI controller
double calculate_duty_cycle(double current_temperature, double target_temperature, double *integral) {
    double error = target_temperature - current_temperature;
    *integral += error;

    // Anti-windup
    if (*integral > integral_limit) {
        *integral = integral_limit;
    } else if (*integral < -integral_limit) {
        *integral = -integral_limit;
    }

    double duty_cycle = Kp * error + Ki * (*integral);

    // Limit duty cycle
    if (duty_cycle > MAX_DUTY_CYCLE) {
        duty_cycle = MAX_DUTY_CYCLE;
    } else if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    }

    return duty_cycle;
}

