#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define temperature thresholds
#define TEMP_BLUE  40000
#define TEMP_GREEN 60000

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
}

// Function to read CPU temperature from file
int read_cpu_temp()
{
    FILE *fp;
    char buffer[10];
    int temp = -1; // Default to -1 to indicate error

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open temperature file.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error: Could not read temperature from file.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Convert millidegrees to Celsius
    temp = atoi(buffer) / 1000;

    return temp;
}

// Function to set RGB color using PWM
void set_rgb(int red, int green, int blue)
{
    gpioPWM(RED_PIN, 255 - red);   // Invert for common anode
    gpioPWM(GREEN_PIN, 255 - green); // Invert for common anode
    gpioPWM(BLUE_PIN, 255 - blue);  // Invert for common anode
}

// Function to map temperature to RGB values
void map_temp_to_rgb(int temp, int *red, int *green, int *blue)
{
    if (temp < TEMP_BLUE) {
        *red = 0;
        *green = 0;
        *blue = 255;
    } else if (temp < TEMP_GREEN) {
        *red = 0;
        *green = 255;
        *blue = 0;
    } else {
        *red = 255;
        *green = 0;
        *blue = 0;
    }
}

int main()
{
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Set PWM frequency (e.g., 1 kHz)
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int temp = read_cpu_temp();
        if (temp == -1) {
            fprintf(stderr, "Error: Could not read temperature. Skipping update.\n");
        } else {
            int red, green, blue;
            map_temp_to_rgb(temp, &red, &green, &blue);
            set_rgb(red, green, blue);
            printf("Temperature: %d m°C, RGB: (%d, %d, %d)\n", temp, red, green, blue);
        }

        gpioDelay(500); // Wait 0.5 seconds
    }

    // Cleanup: Turn off LED and terminate pigpio
    set_rgb(0, 0, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

