#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <curl/curl.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define MAX_RETRIES 3
#define RETRY_DELAY_BASE_MS 100
#define MAX_RESPONSE_LENGTH 256

// Global variables
static volatile int running = 1;
static int pigpio_initialized = 0;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

// Function prototypes
int init_gpio();
int read_dht22(DHT22Data *data);
unsigned char calculate_checksum(const unsigned char *data);
int validate_checksum(const unsigned char *data);
int post_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Initialize GPIO using pigpio
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;
    gpioSetMode(DHT22_GPIO, PI_OUTPUT); // Set GPIO as output initially
    return 0;
}

// Read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int retries = 0;
    while (retries < MAX_RETRIES) {
        unsigned char data_buffer[5] = {0};
        int i, j;

        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // Minimum 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioSetMode(DHT22_GPIO, PI_INPUT); // Release the data line
        gpioDelay(30); // Wait for DHT22 to respond

        // Read data
        gpioSetMode(DHT22_GPIO, PI_INPUT);
        gpioSetPullUpDown(DHT22_GPIO, PI_PUD_UP);

        // Wait for the DHT22 to pull the line low
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal (low)\n");
            retries++;
            gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries));
            continue;
        }

        // Wait for the DHT22 to pull the line high
        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // Wait 1 us
            timeout++;
        }

        if (timeout >= 100) {
            fprintf(stderr, "DHT22: Timeout waiting for start signal (high)\n");
            retries++;
            gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries));
            continue;
        }

        // Read 40 bits (5 bytes)
        for (i = 0; i < 5; i++) {
            for (j = 0; j < 8; j++) {
                // Wait for the line to go low
                timeout = 0;
                while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
                    gpioDelay(1); // Wait 1 us
                    timeout++;
                }

                if (timeout >= 100) {
                    fprintf(stderr, "DHT22: Timeout waiting for data bit (low)\n");
                    retries++;
                    gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries));
                    goto retry;
                }

                // Measure the length of the high pulse
                long start = gpioTick();
                timeout = 0;
                while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
                    gpioDelay(1); // Wait 1 us
                    timeout++;
                }

                if (timeout >= 100) {
                    fprintf(stderr, "DHT22: Timeout waiting for data bit (high)\n");
                    retries++;
                    gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries));
                    goto retry;
                }

                long end = gpioTick();
                long pulse_length = end - start;

                // Determine if the bit is a 0 or a 1 based on the pulse length
                if (pulse_length > 40) { // Empirical value, adjust as needed
                    data_buffer[i] |= (1 << (7 - j));
                }
            }
        }

        // Validate checksum
        if (validate_checksum(data_buffer)) {
            // Convert data to temperature and humidity
            data->humidity = (float)(((unsigned int)data_buffer[0] << 8) | data_buffer[1]) / 10.0;
            data->temperature = (float)(((unsigned int)(data_buffer[2] & 0x7F) << 8) | data_buffer[3]) / 10.0;
            if (data_buffer[2] & 0x80) {
                data->temperature *= -1.0;
            }

            return 0; // Success
        } else {
            fprintf(stderr, "DHT22: Checksum validation failed\n");
            retries++;
            gpioDelay(RETRY_DELAY_BASE_MS * (1 << retries));
        }

        retry:
        continue;
    }

    fprintf(stderr, "DHT22: Max retries reached\n");
    return -1; // Failure
}

// Calculate checksum
unsigned char calculate_checksum(const unsigned char *data) {
    return data[0] + data[1] + data[2] + data[3];
}

// Validate checksum
int validate_checksum(const unsigned char *data) {
    return (calculate_checksum(data) == data[4]);
}

// Post data to server
int post_data(float temperature, float humidity) {
    CURL *curl;
    CURLcode res;
    char json_payload[MAX_RESPONSE_LENGTH];
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
