// Function to read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temperature) {
    char buf[2];
    int result;

    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing temperature command: %d\n", result);
        return -1;
    }

    gpioDelay(BMP180_CONVERSION_DELAY * 1000); // Delay for conversion (in microseconds)

    buf[0] = BMP180_REG_MSB;
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing read temperature command: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading raw temperature: %d\n", result);
        return -1;
    }

    *raw_temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    int result;

    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, buf + 1, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing pressure command: %d\n", result);
        return -1;
    }

    gpioDelay(BMP180_CONVERSION_DELAY * 1000); // Delay for conversion (in microseconds)

    buf[0] = BMP180_REG_MSB;
    result = i2cWriteI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error writing read pressure command: %d\n", result);
        return -1;
    }

    char data[3];
    result = i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading raw pressure: %d\n", result);
        return -1;
    }

    *raw_pressure = ((data[0] << 16) | (data[1] << 8) | data[2]) >> (8 - BMP180_OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temperature) {
    int32_t X1 = (((int32_t)raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temperature) {
    int32_t X1 = (((int32_t)raw_temperature - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    int32_t X3 = ((int32_t)b2 * (B6 * B6) >> 12) >> 11;
    int32_t X4 = ((int32_t)ac2 * B6) >> 11;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;

    uint32_t X1_u = ((uint32_t)ac3 * B6) >> 13;
    uint32_t X2_u = ((uint32_t)b1 * ((B6 * B6) >> 12)) >> 16;
    uint32_t B4 = X1_u + X2_u + ac4;

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (B7 < 0x80000000) {
        p = (B7 * 2) / B4;
    } else {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to log data to a file
int log_data(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    fprintf(fp, "%s, %.2f hPa\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    uint32_t current_time = gpioTick();
    if (current_time - last_interrupt_time > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        last_interrupt_time = current_time;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO mode for interrupt pin
    gpioSetMode(INTERRUPT_GPIO, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_GPIO, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_GPIO, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    while (1) {
        if (logging_enabled) {
            // Read raw temperature and pressure
            if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
                // Calculate temperature and pressure
                temperature = calculate_temperature(raw_temperature);
                pressure = calculate_pressure(raw_pressure, raw_temperature);

                // Log data
                if (log_data(pressure) != 0) {
                    fprintf(stderr, "Error logging data\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data\n");
            }
        } else {
            printf("Data logging disabled\n");
        }

        gpioDelay(2000000); // Delay for 2 seconds (in microseconds)
    }

    return 0;
}

