#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>
#include <curl/curl.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define BACKOFF_DELAY 2
#define READ_INTERVAL 10

// Structure to hold program configuration
typedef struct {
    char *server_url;
    int running;
} ProgramConfig;

// Global configuration
ProgramConfig config = {
    .server_url = "http://your-server.com/api/humidity",
    .running = 1
};

// Function prototypes
int read_dht22(float *humidity);
int validate_checksum(const unsigned char *data);
int post_humidity(float humidity, const char *server_url);
void signal_handler(int signal);
void cleanup();

// Callback function for libcurl to handle the response
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    // You can process the response here if needed
    return real_size;
}

// Function to read data from the DHT22 sensor
int read_dht22(float *humidity) {
    int retries = 0;
    unsigned char data[5] = {0};

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1 ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30 us

        // Switch to input mode
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Read data
        unsigned int tick = gpioTick();
        int i = 0;
        while (i < 40) {
            while (gpioRead(DHT22_GPIO) == 0 && (gpioTick() - tick) < 100) {}
            unsigned int start = gpioTick();
            while (gpioRead(DHT22_GPIO) == 1 && (gpioTick() - start) < 100) {}
            unsigned int end = gpioTick();
            if ((end - start) > 40) {
                data[i / 8] |= (1 << (7 - (i % 8)));
            }
            i++;
        }

        // Validate checksum
        if (validate_checksum(data)) {
            // Calculate humidity
            *humidity = (float)(((unsigned int)data[0] << 8) | data[1]) / 10.0;
            return 0; // Success
        } else {
            syslog(LOG_ERR, "Checksum validation failed. Retry %d/%d", retries + 1, MAX_RETRIES);
            retries++;
            sleep(BACKOFF_DELAY);
        }
    }

    syslog(LOG_ERR, "Failed to read DHT22 after %d retries.", MAX_RETRIES);
    return -1; // Failure
}

// Function to validate the checksum of the DHT22 data
int validate_checksum(const unsigned char *data) {
    return (data[4] == ((data[0] + data[1] + data[2] + data[3]) & 0xFF));
}

// Function to post the humidity reading to the server
int post_humidity(float humidity, const char *server_url) {
    CURL *curl;
    CURLcode res;
    char json_data[50]; // Buffer to hold JSON data
    int retries = 0;

    // Create JSON string
    snprintf(json_data, sizeof(json_data), "{\"humidity\": %.1f}", humidity);

    while (retries < MAX_RETRIES) {
        curl_global_init(CURL_GLOBAL_ALL);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, server_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_data);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);

            struct curl_slist *headers = NULL;
            headers = curl_slist_append(headers, "Content-Type: application/json");
            curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);

            res = curl_easy_perform(curl);

            if (res != CURLE_OK) {
                syslog(LOG_ERR, "curl_easy_perform() failed: %s. Retry %d/%d", curl_easy_strerror(res), retries + 1, MAX_RETRIES);
                curl_slist_free_all(headers); /* free the list of custom headers */
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                retries++;
                sleep(BACKOFF_DELAY);
            } else {
                long response_code;
                curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
                if (response_code >= 200 && response_code < 300) {
                    syslog(LOG_INFO, "Humidity posted successfully: %.1f%%", humidity);
                    curl_slist_free_all(headers); /* free the list of custom headers */
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    return 0; // Success
                } else {
                    syslog(LOG_ERR, "HTTP request failed with status code: %ld. Retry %d/%d", response_code, retries + 1, MAX_RETRIES);
                    curl_slist_free_all(headers); /* free the list of custom headers */
                    curl_easy_cleanup(curl);
                    curl_global_cleanup();
                    retries++;
                    sleep(BACKOFF_DELAY);
                }
            }
        } else {
            syslog(LOG_ERR, "curl_easy_init() failed. Retry %d/%d", retries + 1, MAX_RETRIES);
            curl_global_cleanup();
            retries++;
            sleep(BACKOFF_DELAY);
        }
    }

    syslog(LOG_ERR, "Failed to post humidity after %d retries.", MAX_RETRIES);
    curl_global_cleanup();
    return -1; // Failure
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    config.running = 0;
}

// Cleanup function to release resources
void cleanup() {
    gpioTerminate();
    curl_global_cleanup();
    syslog(LOG_INFO, "Cleanup complete. Exiting.");
    closelog();
    exit(0);
}

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                config.server_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s <server_url>]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float humidity;

    // Main loop
    while (config.running) {
        if (read_dht22(&humidity) == 0) {
            if (post_humidity(humidity, config.server_url) != 0) {
                syslog(LOG_ERR, "Failed to post humidity.");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity.");
        }

        sleep(READ_INTERVAL);
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

