#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define THERMAL_ZONE_PATH "/sys/class/thermal/thermal_zone0/temp"
#define COOLING_DEVICE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE_PATH "/var/log/fan_control.log"

// Global variable to track the current fan state
static int current_fan_state = 0;

// Function to read the CPU temperature from sysfs
int read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;

    fp = fopen(THERMAL_ZONE_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening thermal zone file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading thermal zone file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to read the cooling device's max_state from sysfs
int read_cooling_device_max_state() {
    FILE *fp;
    char buffer[10];
    int max_state = -1;

    fp = fopen(COOLING_DEVICE_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening cooling device file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading cooling device file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    max_state = atoi(buffer);
    return max_state;
}

// Function to set the fan speed based on the temperature
int set_fan_speed(int temperature) {
    FILE *fp;
    int new_fan_state = 0;

    if (temperature < 45000) {
        new_fan_state = 0;
    } else if (temperature < 55000) {
        new_fan_state = 1;
    } else if (temperature < 65000) {
        new_fan_state = 2;
    } else {
        new_fan_state = 3;
    }

    int max_state = read_cooling_device_max_state();
    if (max_state == -1) {
        fprintf(stderr, "Failed to read max_state. Cannot set fan speed.\n");
        return -1;
    }

    if (new_fan_state > max_state) {
        fprintf(stderr, "Requested fan state (%d) exceeds max_state (%d). Setting to max_state.\n", new_fan_state, max_state);
        new_fan_state = max_state;
    }

    fp = fopen(COOLING_DEVICE_PATH, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening cooling device file for writing: %s\n", strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", new_fan_state) < 0) {
        fprintf(stderr, "Error writing to cooling device file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return new_fan_state;
}

// Function to log the fan speed change to a file
int log_fan_speed(int new_fan_state) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE_PATH, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return -1;
    }

    if (new_fan_state != current_fan_state) {
        fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Fan speed changed to state: %d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, new_fan_state);
        current_fan_state = new_fan_state;
    }

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
