#define LOG_FILE_PATH "/var/log/fan_control.log"

// Global variable to track the current fan state
static int current_fan_state = 0;

// Function to read the CPU temperature from sysfs
int read_cpu_temperature() {
    FILE *fp;
    char buffer[10];
    int temperature = -1;

    fp = fopen(THERMAL_ZONE_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening thermal zone file: %s\n", strerror(errno));
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), fp) == NULL) {
        fprintf(stderr, "Error reading thermal zone file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    temperature = atoi(buffer);
    return temperature;
}

// Function to read the cooling device's max_state from sysfs
int read_cooling_device_max_state() {
    FILE *fp;
    char buffer[10];
    int max_state = -1;

    fp = fopen(COOLING_DEVICE_PATH, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening cooling device file: %s\n", strerror(errno));
        return -1;
