#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

// Constants
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_SPEED 500000 // 500 kHz
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 100
#define LOG_FILE "heater_log.txt"

// PID Gains
#define Kp 1.0
#define Ki 0.1
#define Kd 0.01

// Target Temperature
#define TARGET_TEMPERATURE 50.0

// Global Variables
static volatile int running = 1;
static int spi_handle;
static FILE *log_file;

// PID Variables
static float integral = 0.0;
static float previous_error = 0.0;

// Function Prototypes
float read_temperature();
void set_pwm_duty_cycle(int duty_cycle);
void log_data(float temperature, int duty_cycle, float pid_output);
void signal_handler(int signal);
void cleanup();

// Function to read temperature from MAX31855
float read_temperature() {
    unsigned char data[4];
    int i2c_handle;
    float temperature = -1000.0; // Initialize to an invalid value

    i2c_handle = i2cOpen(SPI_CHANNEL, 0x00, 0); // Open I2C device (CE0)
    if (i2c_handle < 0) {
        fprintf(log_file, "%ld, SPI Open Error: %d\n", time(NULL), i2c_handle);
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    if (i2cReadDevice(i2c_handle, (char *)data, 4) != 4) {
        fprintf(log_file, "%ld, SPI Read Error\n", time(NULL));
        fflush(log_file);
        i2cClose(i2c_handle);
        return -1000.0; // Indicate error
    }

    i2cClose(i2c_handle);

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(log_file, "%ld, MAX31855 Fault: Open Circuit\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }
    if (data[3] & 0x02) {
        fprintf(log_file, "%ld, MAX31855 Fault: Short to GND\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }
    if (data[3] & 0x04) {
        fprintf(log_file, "%ld, MAX31855 Fault: Short to VCC\n", time(NULL));
        fflush(log_file);
        return -1000.0; // Indicate error
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;
    temperature = raw_temp * 0.25;

    return temperature;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(float temperature, int duty_cycle, float pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f, Duty Cycle: %d, PID Output: %.2f\n", timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty_cycle(0); // Turn off heater
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main(int argc, char *argv[]) {
    float target_temperature = TARGET_TEMPERATURE;

    // Parse command-line arguments
    if (argc > 1) {
        target_temperature = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    float error, pid_output;

    // Main loop
    while (running) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature < 0) {
            fprintf(log_file, "%ld, Error reading temperature, disabling heater\n", time(NULL));
            fflush(log_file);
            set_pwm_duty_cycle(0);
            sleep(1); // Wait before retrying
            continue;
        }

        // Failsafe checks
        if (temperature > 100.0 || temperature < 0.0) {
            fprintf(log_file, "%ld, Temperature out of range (%.2f), disabling heater\n", time(NULL), temperature);
            fflush(log_file);
            set_pwm_duty_cycle(0);
            sleep(1);
            continue;
        }

        // Calculate error
        error = target_temperature - temperature;

        // Calculate PID output
        integral += error;
        float derivative = error - previous_error;
        pid_output = Kp * error + Ki * integral + Kd * derivative;

        // Limit PID output to PWM range
        if (pid_output < 0) pid_output = 0;
        if (pid_output > PWM_RANGE) pid_output = PWM_RANGE;

        // Set PWM duty cycle
        set_pwm_duty_cycle((int)pid_output);

        // Log data
        log_data(temperature, (int)pid_output, pid_output);

        // Update previous error
        previous_error = error;

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

