#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PWM_FREQUENCY 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "cooling_log.csv"

static volatile int running = 1;

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp = 0;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1; // Indicate error
    }

    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1; // Indicate error
    }

    fclose(fp);
    return temp;
}

// Function to calculate PWM duty cycle based on temperature
int calculate_duty_cycle(int temperature) {
    int duty_cycle;

    if (temperature <= 40000) {
        duty_cycle = 0;
    } else if (temperature >= 70000) {
        duty_cycle = 100;
    } else {
        duty_cycle = (temperature - 40000) * 100 / 30000; // Linear mapping
    }

    return duty_cycle;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    gpioPWM(GPIO_PIN, duty_cycle * 255 / 100); // pigpio duty cycle is 0-255
}

// Function to log data to file
void log_data(int temperature, int duty_cycle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature (C),Duty Cycle (%%)\n");
    }

    fprintf(fp, "%s,%d,%d\n", timestamp, temperature, duty_cycle);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

int main() {
    int temperature, duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin to output mode
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(GPIO_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read CPU temperature
        temperature = read_cpu_temp();
        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, using previous value or exiting.\n");
            // Consider exiting if temperature reading consistently fails
            // running = 0; // Uncomment to exit on temperature read failure
            continue; // Skip to the next iteration
        }

        // Calculate duty cycle
        duty_cycle = calculate_duty_cycle(temperature);

        // Set PWM duty cycle
        set_pwm_duty_cycle(duty_cycle);

        // Log data
        log_data(temperature, duty_cycle);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Turn off the fan
    set_pwm_duty_cycle(0);

    // Terminate pigpio
    gpioTerminate();

    printf("Fan control program stopped.\n");

    return 0;
}

