#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR_0 0x08
#define SLF3S_ADDR_1 0x09
#define MEASUREMENT_COMMAND 0x3608
#define CRC_POLYNOMIAL 0x31
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define FLOW_RATE_SCALE 0.01

// Global variables
int i2c_handle_0 = -1;
int i2c_handle_1 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int read_sensor(int handle, int *raw_value);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len, uint8_t crc);
float convert_to_flow_rate(int raw_value);
int log_data(float flow_rate_0, float flow_rate_1);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C connection
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read data from the sensor with retries
int read_sensor(int handle, int *raw_value) {
    uint8_t buffer[3];
    int retries = RETRY_COUNT;
    int result;

    while (retries > 0) {
        result = i2cReadDevice(handle, (char *)buffer, 3);
        if (result == 3) {
            // CRC validation
            if (validate_crc(buffer, 2, buffer[2])) {
                *raw_value = (buffer[0] << 8) | buffer[1];
                return 0; // Success
            } else {
                fprintf(stderr, "CRC validation failed for handle %d\n", handle);
            }
        } else {
            fprintf(stderr, "I2C read error for handle %d (attempt %d): %d\n", handle, RETRY_COUNT - retries + 1, result);
        }
        retries--;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Failed to read sensor after %d retries for handle %d\n", RETRY_COUNT, handle);
    return -1; // Failure
}

// Calculate CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC-8 checksum
int validate_crc(const uint8_t *data, int len, uint8_t crc) {
    return (calculate_crc(data, len) == crc);
}

// Convert raw value to flow rate
float convert_to_flow_rate(int raw_value) {
    return (float)raw_value * FLOW_RATE_SCALE;
}

// Log data to file
int log_data(float flow_rate_0, float flow_rate_1) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, flow_rate_0, flow_rate_1);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C connections
    i2c_handle_0 = init_i2c(I2C_BUS, SLF3S_ADDR_0);
    if (i2c_handle_0 < 0) {
        gpioTerminate();
        return 1;
    }

    i2c_handle_1 = init_i2c(I2C_BUS, SLF3S_ADDR_1);
    if (i2c_handle_1 < 0) {
        i2cClose(i2c_handle_0);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("flow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        i2cClose(i2c_handle_0);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_value_0, raw_value_1;
        float flow_rate_0, flow_rate_1;

        // Read sensor 0
        if (read_sensor(i2c_handle_0, &raw_value_0) == 0) {
            flow_rate_0 = convert_to_flow_rate(raw_value_0);
        } else {
            flow_rate_0 = -1.0; // Indicate error
        }

        // Read sensor 1
        if (read_sensor(i2c_handle_1, &raw_value_1) == 0) {
            flow_rate_1 = convert_to_flow_rate(raw_value_1);
        } else {
            flow_rate_1 = -1.0; // Indicate error
        }

        // Log data
        if (log_data(flow_rate_0, flow_rate_1) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        sleep(1);
    }

    // Cleanup
    i2cClose(i2c_handle_0);
    i2cClose(i2c_handle_1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

