#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the encoder channels
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution
#define PULSES_PER_REVOLUTION 360.0

// Define the number of states in the quadrature state machine
#define NUM_STATES 4

// Quadrature state machine states
enum {
    STATE_00 = 0,
    STATE_01,
    STATE_10,
    STATE_11
};

// Global variables
static volatile int current_state = STATE_00;
static volatile int pulse_count = 0;
static volatile int running = 1; // Flag to control the main loop

// Function prototypes
int initialize_gpio();
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_data(int state, int pulse_count);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    FILE *log_file;
} ProgramState;

ProgramState state = {0, NULL};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetMode(ENCODER_B, PI_INPUT);

    // Enable internal pull-up resistors
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    state.gpio_initialized = 1;
    return 0;
}

// Callback function for encoder pulses
void encoder_callback(int gpio, int level, uint32_t tick, void *user_data) {
    int a = gpioRead(ENCODER_A);
    int b = gpioRead(ENCODER_B);

    // Quadrature decoding logic
    switch (current_state) {
        case STATE_00:
            if (a == 0 && b == 0) {
                pulse_count++;
                current_state = STATE_01;
            } else if (a == 1 && b == 0) {
                pulse_count--;
                current_state = STATE_10;
            }
            break;
        case STATE_01:
            if (a == 1 && b == 0) {
                pulse_count++;
                current_state = STATE_11;
            } else if (a == 0 && b == 0) {
                pulse_count--;
                current_state = STATE_00;
            }
            break;
        case STATE_10:
            if (a == 1 && b == 0) {
                pulse_count--;
                current_state = STATE_00;
            } else if (a == 0 && b == 0) {
                pulse_count++;
                current_state = STATE_01;
            }
            break;
        case STATE_11:
            if (a == 0 && b == 0) {
                pulse_count--;
                current_state = STATE_10;
            } else if (a == 1 && b == 0) {
                pulse_count++;
                current_state = STATE_01;
            }
            break;
    }

    // Log data every 100 pulses
    if (pulse_count % 100 == 0) {
        log_data(current_state, pulse_count);
    }
}

// Function to log data to file
void log_data(int state, int pulse_count) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    double angular_position;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    angular_position = (double)pulse_count / PULSES_PER_REVOLUTION * 360.0;

    if (state == STATE_00) {
        fprintf(state.log_file, "%s, State: 00, Pulse Count: %d, Angular Position: %.2f\n", timestamp, pulse_count, angular_position);
    } else if (state == STATE_01) {
        fprintf(state.log_file, "%s, State: 01, Pulse Count: %d, Angular Position: %.2f\n", timestamp, pulse_count, angular_position);
    } else if (state == STATE_10) {
        fprintf(state.log_file, "%s, State: 10, Pulse Count: %d, Angular Position: %.2f\n", timestamp, pulse_count, angular_position);
    } else {
        fprintf(state.log_file, "%s, State: 11, Pulse Count: %d, Angular Position: %.2f\n", timestamp, pulse_count, angular_position);
    }
    fflush(state.log_file); // Ensure data is written to file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Set the flag to exit the main loop
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    state.log_file = fopen("encoder_log.txt", "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Set up interrupt callbacks
    gpioSetAlertFuncEx(ENCODER_A, encoder_callback, NULL);
    gpioSetAlertFuncEx(ENCODER_B, encoder_callback, NULL);

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Do other tasks here if needed
        gpioDelay(100); // Sleep for 100ms to reduce CPU usage
    }

    // Clean up and exit
    printf("Cleaning up...\n");
    gpioSetAlertFuncEx(ENCODER_A, NULL, NULL); // Disable callbacks
    gpioSetAlertFuncEx(ENCODER_B, NULL, NULL);

    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    if (state.gpio_initialized) {
        gpioTerminate();
    }

    printf("Exiting.\n");
    return 0;
}

