    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t red, ir;

    // Main loop
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                control_led(LED_GPIO, 1); // Turn LED on
