#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

#define GPIO_PIN 18
#define LOG_FILE "rpm_log.txt"

volatile int pulse_count = 0;
pthread_mutex_t mutex;
FILE *log_file = NULL;

// Function to handle the interrupt
void pulse_callback(int gpio, int level, uint32_t tick, void *user)
{
    if (level == PI_HIGH)
    {
        pthread_mutex_lock(&mutex);
        pulse_count++;
        pthread_mutex_unlock(&mutex);
    }
}

// Function to calculate RPM
double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0;
}

// Function to log RPM to file
void log_rpm(double rpm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL)
    {
        fprintf(log_file, "%s, %.2f\n", timestamp, rpm);
        fflush(log_file);
    }
    else
    {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);

    if (log_file != NULL)
    {
        fclose(log_file);
    }

    gpioTerminate();
    pthread_mutex_destroy(&mutex);
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pin as input with pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0)
    {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL)
    {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Register interrupt handler
    if (gpioSetISRFuncEx(GPIO_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0)
    {
        fprintf(stderr, "Error registering interrupt handler!\n");
        fclose(log_file);
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1)
    {
        gpioDelay(1000); // Wait for 1 second

        pthread_mutex_lock(&mutex);
        int current_pulses = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&mutex);

        double rpm = calculate_rpm(current_pulses);

        if (rpm > 0.0)
        {
            log_rpm(rpm);
        }
        else
        {
            log_rpm(0.0); // Log 0 RPM if no pulses detected
        }
    }

    return 0;
}

