#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADPD144RI_ADDR 0x39
#define PART_ID_REG 0x00
#define RED_DATA_REG 0x02
#define IR_DATA_REG 0x04
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define IR_THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int adpd144ri_init(int fd);
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir);
void control_led(int gpio_chip_name, int gpio_pin, int value);
void log_data(FILE *fp, uint16_t red, uint16_t ir);
void signal_handler(int sig);

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return value;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// ADPD144RI initialization function
int adpd144ri_init(int fd) {
    // Check PART_ID register
    int part_id = i2c_read_register(fd, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID register\n");
        return -1;
    }

    // Basic check, can be expanded based on datasheet
    if (part_id != 0x44) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X\n", part_id);
        return -1;
    }

    // Add more initialization steps here based on the ADPD144RI datasheet
    // Example: Set integration time, gain, etc.

    return 0;
}

// Function to read red and IR data from the ADPD144RI
int read_adpd144ri_data(int fd, uint16_t *red, uint16_t *ir) {
    int red_low, red_high, ir_low, ir_high;

    red_low = i2c_read_register(fd, RED_DATA_REG);
    red_high = i2c_read_register(fd, RED_DATA_REG + 1);
    ir_low = i2c_read_register(fd, IR_DATA_REG);
    ir_high = i2c_read_register(fd, IR_DATA_REG + 1);

    if (red_low < 0 || red_high < 0 || ir_low < 0 || ir_high < 0) {
        fprintf(stderr, "Error reading data registers\n");
        return -1;
    }

    *red = (uint16_t)((red_high << 8) | red_low);
    *ir = (uint16_t)((ir_high << 8) | ir_low);

    return 0;
}

// Function to control the LED
void control_led(int gpio_chip_name, int gpio_pin, int value) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(gpio_chip_name);
    if (!chip) {
        perror("Open GPIO chip failed");
        return;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        perror("Get GPIO line failed");
        gpiod_chip_close(chip);
        return;
    }

    if (gpiod_line_request_output(line, "adpd144ri", value) < 0) {
        perror("Request GPIO line as output failed");
        gpiod_chip_close(chip);
        return;
    }

    gpiod_line_set_value(line, value);

    gpiod_line_release(line);
    gpiod_chip_close(chip);
}

// Function to log data to a file
void log_data(FILE *fp, uint16_t red, uint16_t ir) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u\n", timestamp, red, ir);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Initialize ADPD144RI sensor
    if (adpd144ri_init(i2c_fd) < 0) {
        fprintf(stderr, "ADPD144RI initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t red, ir;
    while (!terminate) {
        if (read_adpd144ri_data(i2c_fd, &red, &ir) == 0) {
            log_data(log_file, red, ir);

            if (ir > IR_THRESHOLD) {
                control_led(GPIO_CHIP, GPIO_PIN, 1); // Turn LED on
            } else {
                control_led(GPIO_CHIP, GPIO_PIN, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        usleep(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100 ms
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

