#include <pigpio.h>

#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18
#define SAMPLE_INTERVAL_MS 10
#define LOG_FILE "audio_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(AUDIO_INPUT_PIN, PI_INPUT);
    gpioSetMode(GAIN_SELECT_PIN, PI_OUTPUT);

    // Set GAIN_SELECT_PIN to LOW (60dB gain)
    gpioWrite(GAIN_SELECT_PIN, 0);

    return 0;
}

// Function to read the audio input pin
int read_audio_input() {
    return gpioRead(AUDIO_INPUT_PIN);
}

// Function to detect rising edges
int detect_rising_edge(int previous_state, int current_state) {
    return (previous_state == 0 && current_state == 1);
}

// Function to log peak events
int log_peak_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s LEVEL 1\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Audio peak detection started. Press Ctrl+C to exit.\n");

    int previous_state = 0;
    int current_state = 0;

    while (running) {
        previous_state = current_state;
        current_state = read_audio_input();

        if (detect_rising_edge(previous_state, current_state)) {
            if (log_peak_event() != 0) {
                fprintf(stderr, "Error logging peak event.\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay for 10 milliseconds
    }

    // Cleanup
    printf("Cleaning up and exiting.\n");
    fclose(log_file);
    gpioTerminate();

    return 0;
}

