#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x36
#define MEASUREMENT_COMMAND 0x3608
#define FLOW_RATE_SCALE_FACTOR 1000.0
#define LOG_FILE_NAME "flow_log.csv"

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int send_measurement_command();
int read_flow_data(int16_t *raw_flow);
uint8_t calculate_crc8(const uint8_t *data, int len);
float convert_to_flow_rate(int16_t raw_flow);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function (Sensirion variant)
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Send measurement command to the sensor
int send_measurement_command() {
    char command[2] = {(MEASUREMENT_COMMAND >> 8) & 0xFF, MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to send measurement command: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read flow data from the sensor
int read_flow_data(int16_t *raw_flow) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow data: %s\n", strerror(errno));
        return -1;
    }

    // CRC validation
    uint8_t crc = calculate_crc8((uint8_t *)buffer, 2);
    if (crc != (uint8_t)buffer[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    // Convert to signed 16-bit integer (MSB first)
    *raw_flow = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Convert raw flow data to flow rate in uL/min
float convert_to_flow_rate(int16_t raw_flow) {
    return (float)raw_flow / FLOW_RATE_SCALE_FACTOR;
}

// Log flow rate to CSV file
int log_flow_rate(float flow_rate) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C device
    if (open_i2c_device() != 0) {
        cleanup();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Send measurement command
    if (send_measurement_command() != 0) {
        cleanup();
        return 1;
    }

    int16_t raw_flow;
    float flow_rate;

    // Main loop
    while (!terminate) {
        // Read flow data
        if (read_flow_data(&raw_flow) == 0) {
            // Convert to flow rate
            flow_rate = convert_to_flow_rate(raw_flow);

            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Failed to log flow rate\n");
            }
        } else {
            fprintf(stderr, "Failed to read flow data, retrying...\n");
        }

        // Wait for 1000 ms
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

