#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x70
#define SENSOR_DATA_LENGTH 7
#define TVOC_REGISTER 0x00
#define ECO2_REGISTER 0x03
#define IAQ_INDEX_REGISTER 0x06
#define LOG_FILE "air_quality_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_sensor_data(int i2c_handle, uint8_t *data);
int parse_sensor_data(const uint8_t *data, uint16_t *tvoc, uint16_t *eco2);
float calculate_iaq_index(uint16_t tvoc, uint16_t eco2);
int log_data(FILE *log_file, float iaq_index, uint16_t tvoc, uint16_t eco2);
void signal_handler(int signal);

// Function to read sensor data from I2C
int read_sensor_data(int i2c_handle, uint8_t *data) {
    int result = i2cReadI2CBlockData(i2c_handle, TVOC_REGISTER, (char *)data, SENSOR_DATA_LENGTH);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }
    return 0;
