#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define CONSUMER_NAME "ttp223_tamper"
#define TAMPER_THRESHOLD_SEC 5

static volatile int keep_running = 1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static struct timespec last_touch_time = {0, 0};
static int intrusion_alert_printed = 0;

void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

int main() {
    int ret;
    struct gpiod_line_request_config config;
    struct timespec current_time;
    double time_diff;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    // Get GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure line request
    memset(&config, 0, sizeof(config));
    config.consumer = CONSUMER_NAME;
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    // Request line
    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("Monitoring tamper events on GPIO %d...\n", GPIO_PIN);

    while (keep_running) {
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            fprintf(stderr, "Error reading GPIO line: %s\n", strerror(errno));
            break;
        }

        if (value == 1) { // Touched
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            time_diff = (current_time.tv_sec - last_touch_time.tv_sec) +
                        (current_time.tv_nsec - last_touch_time.tv_nsec) / 1e9;

            if (time_diff >= TAMPER_THRESHOLD_SEC && !intrusion_alert_printed) {
                printf("INTRUSION DETECTED!\n");
                intrusion_alert_printed = 1;
            }

            last_touch_time = current_time;
        } else { // Released
            intrusion_alert_printed = 0;
        }

        usleep(100000); // 100 ms
    }

    // Release line and close chip
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

