#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <alsa/asoundlib.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define PCM_DEVICE "default"
#define SAMPLE_RATE 44100
#define CHANNELS 1
#define FORMAT SND_PCM_FORMAT_S32_LE
#define FILENAME "audio_capture.pcm"

static volatile int keep_running = 1;
static snd_pcm_t *pcm_handle = NULL;
static FILE *fp = NULL;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;

void signal_handler(int sig) {
    fprintf(stderr, "Signal received, exiting gracefully...\n");
    keep_running = 0;
}

int init_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(gpio_line, "audio_capture", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int init_alsa(void) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(&pcm_handle, PCM_DEVICE, SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(pcm_handle, hw_params, FORMAT)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(pcm_handle, hw_params, CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(pcm_handle);
        return -1;
    }

    return 0;
}

int capture_audio(void) {
    int err;
    int frames = 1024; // Adjust as needed
    char buffer[frames * 4]; // 4 bytes per sample (32-bit)
    int16_t pcm_data[frames];

    if ((err = snd_pcm_readi(pcm_handle, buffer, frames)) != frames) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        return -1;
    }

    // Convert 32-bit data to 16-bit PCM
    for (int i = 0; i < frames; i++) {
        // Extract 24-bit data from the 32-bit buffer
        int32_t sample = ((int32_t *)buffer)[i];
        // Right-shift to get 24-bit data
        sample = sample >> 8;
        // Sign-extend to 32-bit
        sample = (int32_t)(sample << 8) >> 8;
        // Store as 16-bit PCM
        pcm_data[i] = (int16_t)sample;
    }

    // Write PCM data to file
    size_t bytes_written = fwrite(pcm_data, sizeof(int16_t), frames, fp);
    if (bytes_written != frames) {
        fprintf(stderr, "Error writing to file\n");
        return -1;
    }

    return 0;
}

int cleanup(void) {
    int err;

    if (pcm_handle) {
        if ((err = snd_pcm_drain(pcm_handle)) < 0) {
            fprintf(stderr, "Error draining PCM: %s\n", snd_strerror(err));
        }
        if ((err = snd_pcm_close(pcm_handle)) < 0) {
            fprintf(stderr, "Error closing PCM: %s\n", snd_strerror(err));
        }
    }

    if (fp) {
        if (fclose(fp) != 0) {
            perror("Error closing file");
        }
    }

    if (gpio_line) {
        gpiod_line_set_value(gpio_line, 0);
        gpiod_line_release(gpio_line);
    }

    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }

    return 0;
}

int main(void) {
    signal(SIGINT, signal_handler);

    if (init_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    if (init_alsa() != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    fp = fopen(FILENAME, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Capturing audio... Press Ctrl+C to stop.\n");

    while (keep_running) {
        if (capture_audio() != 0) {
            fprintf(stderr, "Audio capture failed\n");
            break;
        }
    }

    fprintf(stderr, "Cleaning up...\n");
    cleanup();

    fprintf(stderr, "Audio capture complete. File saved as %s\n", FILENAME);
    return 0;
}

