#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define PWM range
#define PWM_RANGE 255

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define flame duration threshold in milliseconds
#define FLAME_DURATION_THRESHOLD 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static time_t flame_start_time = 0;
static int flame_detected = 0;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
int calculate_duty_cycle(long duration);
int set_fan_speed(int duty_cycle);
int log_event(const char *event);
void signal_handler(int signal);
void cleanup();

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    int fan_enabled;
} ProgramState;

ProgramState state = {0, 0};

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    state.gpio_initialized = 1;
    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to calculate the PWM duty cycle based on flame duration
int calculate_duty_cycle(long duration) {
    // Exponential curve: duty_cycle = 80 * (1 - exp(-duration/100))
    double exponent = (double)duration / 100.0;
    double duty_cycle_float = 80.0 * (1.0 - exp(-exponent));
    int duty_cycle = (int)duty_cycle_float;

    // Clamp the duty cycle to the valid range
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 80) {
        duty_cycle = 80;
    }

    return duty_cycle;
}

// Function to set the fan speed using PWM
int set_fan_speed(int duty_cycle) {
    gpioPWM(FAN_PIN, duty_cycle);
    return 0;
}

