int log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S%z", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", buf, event);
        fflush(log_file); // Ensure the log is written immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
        return 1;
    }
}

