void cleanup() {
    printf("Cleaning up...\n");

    // Stop the fan
    set_fan_speed(0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT); // Set back to input

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Cleanup complete. Exiting.\n");
}

