        if (sensor_value == 0) { // Flame detected (LOW signal)
            if (!flame_detected) {
                flame_detected = 1;
                flame_start_time = time(NULL);
                log_event("Flame detected");
            }
        } else if (sensor_value == 1) { // No flame (HIGH signal)
            if (flame_detected) {
                flame_detected = 0;
                log_event("Flame ended");
            }
        } else {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            log_event("Error reading sensor");
            gpioDelay(DEBOUNCE_TIME * 1000); // Wait before retrying
            continue;
        }

        if (flame_detected) {
            time_t current_time = time(NULL);
            long duration = (long)(current_time - flame_start_time) * 1000; // Convert to milliseconds

            if (duration > FLAME_DURATION_THRESHOLD) {
                int duty_cycle = calculate_duty_cycle(duration);
                set_fan_speed(duty_cycle);
                state.fan_enabled = 1; // Fan is enabled
            } else {
