#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define TRIGGER_GPIO 23
#define DATA_READY_GPIO 24
#define FRAME_SIZE 32768
#define HEADER_SIZE 48
#define FILE_NAME "radar_data.bin"

// Data structure for the configuration
typedef struct {
    double start_frequency;
    double end_frequency;
    int num_chirps;
    int num_samples;
    int frame_period_ms;
} radar_config_t;

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_spi();
int write_header();
void trigger_frame();
void data_ready_callback(int gpio, int level, uint32_t tick);
int read_frame(uint8_t *frame_data);
int log_frame(uint8_t *frame_data, int frame_number);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_GPIO, PI_OUTPUT);
    gpioSetMode(DATA_READY_GPIO, PI_INPUT);
    gpioSetPullUpDown(DATA_READY_GPIO, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Write header to file
int write_header() {
    uint8_t header[HEADER_SIZE];
    memcpy(header, "RDAD", 4); // Magic number

    // Timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[8];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d", timeinfo);
    memcpy(header + 4, timestamp, 8);

    // Configuration
    radar_config_t config = {77.0, 79.0, 64, 256, 100};
    memcpy(header + 12, &config, sizeof(radar_config_t));

    if (fwrite(header, 1, HEADER_SIZE, log_file) != HEADER_SIZE) {
        fprintf(stderr, "Failed to write header to file\n");
        return -1;
    }

    return 0;
}

// Trigger a frame
void trigger_frame() {
    gpioWrite(TRIGGER_GPIO, 1);
    gpioDelay(100); // 100 us trigger pulse
    gpioWrite(TRIGGER_GPIO, 0);
}

// Data ready callback
void data_ready_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Falling edge indicates data is ready
        uint8_t *frame_data = (uint8_t *)malloc(FRAME_SIZE);
        if (frame_data == NULL) {
            fprintf(stderr, "Failed to allocate memory for frame data\n");
            return;
        }

        if (read_frame(frame_data) == 0) {
            static int frame_number = 0;
            if (log_frame(frame_data, frame_number) != 0) {
                fprintf(stderr, "Failed to log frame\n");
            }
            frame_number++;
        } else {
            fprintf(stderr, "Failed to read frame\n");
        }
        free(frame_data);
    }
}

// Read a frame from SPI
int read_frame(uint8_t *frame_data) {
    int bytes_read = spiXfer(spi_handle, NULL, frame_data, FRAME_SIZE);
    if (bytes_read != FRAME_SIZE) {
        fprintf(stderr, "SPI read failed: %d bytes read\n", bytes_read);
        return -1;
    }
    return 0;
}

// Log a frame to file
int log_frame(uint8_t *frame_data, int frame_number) {
    // Timestamp
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    char timestamp[8];
    strftime(timestamp, sizeof(timestamp), "%Y%m%d", timeinfo);

    // Write frame number and timestamp
    fwrite(&frame_number, sizeof(int), 1, log_file);
    fwrite(timestamp, 1, 8, log_file);

    // Write frame data
    if (fwrite(frame_data, 1, FRAME_SIZE, log_file) != FRAME_SIZE) {
        fprintf(stderr, "Failed to write frame data to file\n");
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(FILE_NAME, "wb");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header
    if (write_header() != 0) {
        cleanup();
        return 1;
    }

    // Set up data ready callback
    gpioSetAlertFuncEx(DATA_READY_GPIO, data_ready_callback, NULL);

    printf("Radar data logging started. Press Ctrl+C to terminate.\n");

    // Main loop
    while (!terminate) {
        trigger_frame();
        gpioDelay(100); // Wait 100 ms before next trigger
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

