#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONTINUOUS_MODE 0x1000 // Continuous conversion mode
#define RANGE_AUTO 0x0800      // Automatic full-scale range
#define CONFIG_VALUE (CONTINUOUS_MODE | RANGE_AUTO)
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration
typedef struct {
    uint16_t config_value;
} sensor_config_t;

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor() {
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, CONFIG_VALUE);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read raw data from the sensor
int read_sensor_data(uint16_t *raw_data) {
    int result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", result);
        return -1;
    }
    *raw_data = (uint16_t)result;
    return 0;
}

// Convert raw data to lux
float convert_to_lux(uint16_t raw_data) {
    int exponent = (raw_data >> 12) & 0x0F;
    int mantissa = raw_data & 0x0FFF;
    return 0.01 * (float)(1 << exponent) * mantissa;
}

// Log data to file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f lux\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    uint16_t raw_data;
    float lux;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_sensor_data(&raw_data) == 0) {
                lux = convert_to_lux(raw_data);
                log_data(lux);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error reading sensor data, retry %d/%d\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }
        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(100 * 1000); // Delay 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

