#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip and line number
#define GPIO_CHIP "gpiochip0"
#define GPIO_LINE 17

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

int main() {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    struct gpiod_line_request_config config;
    int ret;
    int flame_detected;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    // Register the signal handler for SIGINT
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("signal");
        return EXIT_FAILURE;
    }

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("gpiod_chip_get_line");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Configure the GPIO line as input with pull-up resistor
    struct gpiod_line_config line_config;
    memset(&line_config, 0, sizeof(line_config));
    line_config.consumer = "flame_detect";
    line_config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    line_config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    ret = gpiod_line_config(line, &line_config, NULL);
    if (ret < 0) {
        perror("gpiod_line_config");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Request the GPIO line
    memset(&config, 0, sizeof(config));
    config.consumer = "flame_detect";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        perror("gpiod_line_request");
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    // Main loop to read the flame sensor
    while (!terminate) {
        // Read the GPIO line value
        flame_detected = gpiod_line_get_value(line);
        if (flame_detected < 0) {
            perror("gpiod_line_get_value");
            break; // Exit loop on error
        }

        // Get current timestamp
        time(&rawtime);
        timeinfo = localtime(&rawtime);
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        // Log the flame detection status
        if (flame_detected == 0) {
            printf("%s: Flame Detected: YES\n", timestamp);
        } else {
            printf("%s: Flame Detected: NO\n", timestamp);
        }

        // Wait for 1 second
        sleep(1);
    }

    // Release the GPIO line request
    ret = gpiod_line_release(line);
    if (ret < 0) {
        perror("gpiod_line_release");
    }

    // Close the GPIO chip
    ret = gpiod_chip_close(chip);
    if (ret < 0) {
        perror("gpiod_chip_close");
    }

    return EXIT_SUCCESS;
}

