#define GPIO_CH8 9

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGTERM received, exiting gracefully...\n");
}

// Function to read the state of all 8 channels
int read_all_channels()
{
    int ch1 = gpioRead(GPIO_CH1);
    int ch2 = gpioRead(GPIO_CH2);
    int ch3 = gpioRead(GPIO_CH3);
    int ch4 = gpioRead(GPIO_CH4);
    int ch5 = gpioRead(GPIO_CH5);
    int ch6 = gpioRead(GPIO_CH6);
    int ch7 = gpioRead(GPIO_CH7);
    int ch8 = gpioRead(GPIO_CH8);

    return (ch1 << 0) | (ch2 << 1) | (ch3 << 2) | (ch4 << 3) |
           (ch5 << 4) | (ch6 << 5) | (ch7 << 6) | (ch8 << 7);
}

// Function to log the sensor data with a timestamp
void log_data(int channel_states)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    printf("[+%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           timestamp_ms,
           (channel_states >> 0) & 1,
           (channel_states >> 1) & 1,
           (channel_states >> 2) & 1,
           (channel_states >> 3) & 1,
           (channel_states >> 4) & 1,
           (channel_states >> 5) & 1,
           (channel_states >> 6) & 1,
           (channel_states >> 7) & 1);
}

