#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the TTP226 sensor channels
#define GPIO_2 2
#define GPIO_3 3
#define GPIO_4 4
#define GPIO_17 17
#define GPIO_27 27
#define GPIO_22 22
#define GPIO_10 10
#define GPIO_9 9

// Structure to hold GPIO pin numbers
typedef struct {
    int gpio2;
    int gpio3;
    int gpio4;
    int gpio17;
    int gpio27;
    int gpio22;
    int gpio10;
    int gpio9;
} gpio_pins_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCtrl+C pressed. Exiting gracefully...\n");
}

// Function to initialize GPIO pins
int initialize_gpio(gpio_pins_t *pins) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with no pull-up/pull-down resistors
    gpioSetMode(pins->gpio2, PI_INPUT);
    gpioSetMode(pins->gpio3, PI_INPUT);
    gpioSetMode(pins->gpio4, PI_INPUT);
    gpioSetMode(pins->gpio17, PI_INPUT);
    gpioSetMode(pins->gpio27, PI_INPUT);
    gpioSetMode(pins->gpio22, PI_INPUT);
    gpioSetMode(pins->gpio10, PI_INPUT);
    gpioSetMode(pins->gpio9, PI_INPUT);

    return 0;
}

// Function to read the state of all 8 channels
int read_all_channels(gpio_pins_t *pins, unsigned char *channel_states) {
    channel_states[0] = gpioRead(pins->gpio2);
    channel_states[1] = gpioRead(pins->gpio3);
    channel_states[2] = gpioRead(pins->gpio4);
    channel_states[3] = gpioRead(pins->gpio17);
    channel_states[4] = gpioRead(pins->gpio27);
    channel_states[5] = gpioRead(pins->gpio22);
    channel_states[6] = gpioRead(pins->gpio10);
    channel_states[7] = gpioRead(pins->gpio9);

    return 0;
}

// Function to format the data into a CSV string
int format_data(unsigned char *channel_states, char *output_string) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    snprintf(output_string, 100, "%s,%d,%d,%d,%d,%d,%d,%d,%d\n",
             timestamp,
             channel_states[0],
             channel_states[1],
             channel_states[2],
             channel_states[3],
             channel_states[4],
             channel_states[5],
             channel_states[6],
             channel_states[7]);

    return 0;
}

// Function to log the data to the console
int log_data(const char *data) {
    printf("%s", data);
    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio(gpio_pins_t *pins) {
    gpioTerminate();
}

int main() {
    gpio_pins_t pins = {GPIO_2, GPIO_3, GPIO_4, GPIO_17, GPIO_27, GPIO_22, GPIO_10, GPIO_9};
    unsigned char channel_states[8];
    char output_string[100];

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
