    signal(SIGINT, signal_handler);

    // Initialize GPIO pins
    if (initialize_gpio(&pins) != 0) {
        return 1;
    }

    // Main loop
    while (program_running) {
        // Read the state of all 8 channels
        if (read_all_channels(&pins, channel_states) != 0) {
            fprintf(stderr, "Error reading channel states\n");
        }

        // Format the data into a CSV string
        if (format_data(channel_states, output_string) != 0) {
            fprintf(stderr, "Error formatting data\n");
        }

        // Log the data to the console
        if (log_data(output_string) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Clean up GPIO resources before exiting
    cleanup_gpio(&pins);

    return 0;
}

