#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TILT_SENSOR_GPIO 4

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    int tilt_state = -1; // Initialize to an invalid state
    int current_tilt_state;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO 4 as an input with pull-up resistor
    gpioSetMode(TILT_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_GPIO, PI_PUD_UP);

    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    while (program_running) {
        current_tilt_state = gpioRead(TILT_SENSOR_GPIO);

        if (current_tilt_state == 0) {
            tilt_state = 0;
        } else if (current_tilt_state == 1) {
            tilt_state = 1;
        } else {
            fprintf(stderr, "Error: Invalid GPIO read value: %d\n", current_tilt_state);
            continue; // Skip to the next iteration
        }

        if (tilt_state != -1) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (tilt_state == 0) {
                printf("%s: Tilted\n", timestamp);
            } else {
                printf("%s: Not Tilted\n", timestamp);
            }
            fflush(stdout); // Ensure output is flushed immediately
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

