#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI1145_ADDR 0x60
#define HW_KEY_REG 0x18
#define HW_KEY_VALUE 0x17
#define CHLIST_REG 0x01
#define CHLIST_VALUE 0x77 // Enable UV, ALS_VIS, ALS_IR
#define ALS_FORCE_REG 0x16
#define ALS_FORCE_VALUE 0x06
#define UV_INDEX_REG 0x2C
#define ALS_VIS_DATA0 0x22
#define ALS_VIS_DATA1 0x23

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_uv_index(float *uv_index);
int read_als_visible(uint16_t *als_visible);
void log_data(float uv_index, uint16_t als_visible);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the Si1145 sensor
int initialize_sensor() {
    // Write HW_KEY
    if (i2cWriteByteData(i2c_handle, HW_KEY_REG, HW_KEY_VALUE) < 0) {
        fprintf(stderr, "Error writing HW_KEY register\n");
        return -1;
    }

    // Configure CHLIST
    if (i2cWriteByteData(i2c_handle, CHLIST_REG, CHLIST_VALUE) < 0) {
        fprintf(stderr, "Error writing CHLIST register\n");
        return -1;
    }

    // Force a measurement
    if (i2cWriteByteData(i2c_handle, ALS_FORCE_REG, ALS_FORCE_VALUE) < 0) {
        fprintf(stderr, "Error writing ALS_FORCE register\n");
        return -1;
    }

    return 0;
}

// Function to read the UV index from the sensor
int read_uv_index(float *uv_index) {
    int uv_raw = i2cReadByteData(i2c_handle, UV_INDEX_REG);
    if (uv_raw < 0) {
        fprintf(stderr, "Error reading UV index register\n");
        return -1;
    }
    *uv_index = (float)uv_raw / 10.0; // Convert raw value to UV index
    return 0;
}

// Function to read the visible ALS data from the sensor
int read_als_visible(uint16_t *als_visible) {
    int als_low = i2cReadByteData(i2c_handle, ALS_VIS_DATA0);
    int als_high = i2cReadByteData(i2c_handle, ALS_VIS_DATA1);

    if (als_low < 0 || als_high < 0) {
        fprintf(stderr, "Error reading ALS visible data registers\n");
        return -1;
    }

    *als_visible = (uint16_t)((als_high << 8) | als_low);
    return 0;
}

// Function to log the data to a CSV file
void log_data(float uv_index, uint16_t als_visible) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%u\n", timestamp, uv_index, als_visible);
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float uv_index;
    uint16_t als_visible;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_uv_index(&uv_index) == 0 && read_als_visible(&als_visible) == 0) {
            // Log the data
            log_data(uv_index, als_visible);

            // Print the data to the console
            printf("UV Index: %.2f, Visible ALS: %u\n", uv_index, als_visible);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function (milliseconds)
    }

    // Close the log file
    fclose(log_file);

    // Close I2C bus
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

