#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define FLOW_SCALE_FACTOR 0.036
#define ALARM_THRESHOLD 0.5
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_fd = -1;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *gpio_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len);
int i2c_write_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len);
int validate_crc(uint8_t data[], size_t len);
float convert_to_ml_min(int16_t raw_flow);
float calculate_average_flow(float flow1, float flow2);
void set_alarm(int state);
void log_flow_rate(float flow1, float flow2, float average_flow);
void signal_handler(int sig);
int initialize_i2c(void);
int initialize_gpio(void);
void cleanup(void);

// CRC-8-Maxim polynomial 0x31, initial value 0xFF
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// I2C read function
int i2c_read_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    ssize_t bytes_read = read(fd, buf, len);
    if (bytes_read != len) {
        fprintf(stderr, "Failed to read %zu bytes: %zd\n", len, bytes_read);
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_bytes(int fd, uint8_t addr, uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t data[len + 1];
    data[0] = reg;
    memcpy(data + 1, buf, len);

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Failed to set I2C slave address");
        return -1;
    }

    if (write(fd, data, len + 1) != len + 1) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// CRC validation function
int validate_crc(uint8_t data[], size_t len) {
    uint8_t crc = data[len - 1];
    uint8_t calculated_crc = crc8(data, len - 1);
    return (crc == calculated_crc);
}

// Flow conversion function
float convert_to_ml_min(int16_t raw_flow) {
    return (float)raw_flow * FLOW_SCALE_FACTOR;
}

// Average flow calculation function
float calculate_average_flow(float flow1, float flow2) {
    return (flow1 + flow2) / 2.0;
}

// GPIO alarm control function
void set_alarm(int state) {
    if (gpiod_line_set_value(gpio_line, state) < 0) {
        perror("Failed to set GPIO value");
    }
}

// Logging function
void log_flow_rate(float flow1, float flow2, float average_flow) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Flow1: %.2f ml/min, Flow2: %.2f ml/min, Average: %.2f ml/min\n",
            timestamp, flow1, flow2, average_flow);
    fflush(log_file);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// I2C initialization function
int initialize_i2c(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    return 0;
}

// GPIO initialization function
int initialize_gpio(void) {
    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "flow_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(gpio_line, &config, 0) < 0) {
