#include <pigpio.h>
#include <string.h>

#define GPIO_PIN 4
#define BUFFER_SIZE 100

// Structure to hold timestamp and sensor reading
typedef struct {
    time_t timestamp;
    int reading;
} SensorData;

// Circular buffer
SensorData buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(time_t timestamp, int reading);
void print_buffer();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) {
            time_t current_time = time(NULL);
            add_to_buffer(current_time, sensor_value);
            printf("Obstacle detected!\n");
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    gpioTerminate();
    return 0;
}

// Initializes the pigpio library and configures the GPIO pin.
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Reads the sensor value from the specified GPIO pin.
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Adds a new entry to the circular buffer.
void add_to_buffer(time_t timestamp, int reading) {
    buffer[buffer_index].timestamp = timestamp;
    buffer[buffer_index].reading = reading;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Prints the contents of the circular buffer to stdout.
void print_buffer() {
    printf("\n--- Sensor Data Log ---\n");
    for (int i = 0; i < buffer_count; i++) {
        int index = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char time_str[30];
        strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", localtime(&buffer[index].timestamp));
        printf("Timestamp: %s, Reading: %d\n", time_str, buffer[index].reading);
    }
    printf("--- End of Log ---\n\n");
}

// Signal handler for Ctrl+C.
void signal_handler(int signal) {
    program_running = 0;
    print_buffer();
    gpioTerminate();
    exit(0);
}

