#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define D7S_ADDR 0x55
#define MODE_CONTROL_REG 0x1D
#define OPERATING_STATUS_REG 0x1B
#define ACCEL_X_LSB_REG 0x2A
#define ACCEL_X_MSB_REG 0x2B
#define ACCEL_Y_LSB_REG 0x2C
#define ACCEL_Y_MSB_REG 0x2D
#define ACCEL_Z_LSB_REG 0x2E
#define ACCEL_Z_MSB_REG 0x2F
#define SCALE_FACTOR 0.0009765625
#define TIMEOUT_SEC 1
#define RETRY_DELAY_MS 10
#define MAX_RETRIES 5

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_init(int address);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len);
int d7s_init(int fd);
int d7s_read_acceleration(int fd, float *x, float *y, float *z);
char* get_iso8601_timestamp(char* timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, float x, float y, float z);
void signal_handler(int sig);

// I2C initialization function
int i2c_init(int address) {
    int fd = open(I2C_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (write(fd, buf, 2) == 2) {
            return 0; // Success
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X), retry %d: %s\n", reg, value, retries + 1, strerror(errno));
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
    fprintf(stderr, "I2C write failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (address) error: %s\n", strerror(errno));
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, value, 1) == 1) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read error (reg 0x%02X), retry %d: %s\n", reg, retries + 1, strerror(errno));
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
    fprintf(stderr, "I2C read failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (address) error: %s\n", strerror(errno));
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (read(fd, data, len) == len) {
            return 0; // Success
        }
        fprintf(stderr, "I2C read block error (reg 0x%02X, len %d), retry %d: %s\n", reg, len, retries + 1, strerror(errno));
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
    fprintf(stderr, "I2C read block failed after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// D7S initialization function
int d7S_init(int fd) {
    // Set to active mode
    if (i2c_write_reg(fd, MODE_CONTROL_REG, 0x10) < 0) {
        fprintf(stderr, "Error setting D7S to active mode.\n");
        return -1;
    }

    // Wait for sensor to become active
    time_t start_time = time(NULL);
    uint8_t status;
    while (1) {
        if (i2c_read_reg(fd, OPERATING_STATUS_REG, &status) < 0) {
            fprintf(stderr, "Error reading operating status.\n");
            return -1;
        }

        if (status & 0x01) {
            break; // Sensor is active
        }

        if (time(NULL) - start_time > TIMEOUT_SEC) {
            fprintf(stderr, "Timeout waiting for sensor to become active.\n");
            return -1;
        }

        usleep(100000); // 100 ms
    }

    return 0;
}

