            return 0; // Success
        }
        fprintf(stderr, "I2C read block error (reg 0x%02X, len %d), retry %d: %s\n", reg, len, retries + 1, strerror(errno));
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Exponential backoff
    }
