// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define LED_PIN 25

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void control_led(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check if either sensor detects an obstacle
        if (sensor1_value == 0 || sensor2_value == 0) {
            // Obstacle detected, turn LED ON
            control_led(1);
        } else {
            // No obstacle detected, turn LED OFF
            control_led(0);
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Obstacle avoidance system stopped.\n");

    return 0;
}

// Function to initialize pigpio and GPIO pins
int initialize_gpio() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Failed to read GPIO pin %d\n", gpio_pin);
        return 1; // Return a default value or handle the error appropriately
    }
    return value;
}

// Function to control the LED
void control_led(int state) {
    if (gpioWrite(LED_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to LED_PIN\n");
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioTerminate();
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d).  Shutting down gracefully...\n", signal);
    program_running = 0;
}

