#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define STALL_DURATION_SEC 2
#define LOG_FILE "stall_log.txt"

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor value
int read_sensor(int gpio) {
    int value = gpioRead(gpio);
    if (value != 0 && value != 1) {
        fprintf(stderr, "Error: Invalid sensor reading on GPIO %d: %d\n", gpio, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to check for stall
int is_stall(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log stall event
int log_stall() {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    // Check if the log entry already exists
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > 0) {
        char last_line[256];
        fseek(fp, file_size - 256, SEEK_SET); // Read the last 256 bytes
        if (fgets(last_line, sizeof(last_line), fp) != NULL) {
            if (strstr(last_line, timestamp) != NULL) {
                fclose(fp);
                return 0; // Log entry already exists, skip logging
            }
        }
    }

    fprintf(fp, "%s - Stall detected\n", timestamp);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    int stall_count = 0;
    while (program_running) {
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensors, exiting...\n");
            break;
        }

        if (is_stall(sensor1_value, sensor2_value)) {
            stall_count++;
            if (stall_count >= STALL_DURATION_SEC) {
                if (log_stall() == 0) {
                    printf("Stall logged.\n");
                } else {
                    fprintf(stderr, "Error logging stall.\n");
                }
                stall_count = 0; // Reset stall count after logging
            }
        } else {
            stall_count = 0; // Reset stall count if no stall
        }

        gpioDelay(100); // Check every 100ms
    }

    // Clean up
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

