#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMAG5170_ADDR 0x0E
#define CONTINUOUS_MODE 0x00 // Example value, check datasheet
#define RANGE_50MT 0x00       // Example value, check datasheet
#define SENSOR_ID_REG 0x00
#define SENSOR_ID_EXPECTED 0x8D
#define DATA_REG_X 0x01
#define DATA_REG_Y 0x03
#define DATA_REG_Z 0x05
#define LSB_SCALE_FACTOR 0.00013 // Example value, check datasheet
#define CSV_FILE "magnetic_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_mt(int16_t raw_value);
char *get_iso8601_timestamp();
int log_data(double x, double y, double z);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize the TMAG5170 sensor
int initialize_sensor() {
    // Check sensor ID
    char buf[1];
    int result = i2cReadI2CBlockData(i2c_handle, SENSOR_ID_REG, buf, 1);
    if (result != 1) {
        fprintf(stderr, "Error reading sensor ID: %s\n", strerror(errno));
        return -1;
    }

    if (buf[0] != SENSOR_ID_EXPECTED) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x%02X)\n", buf[0], SENSOR_ID_EXPECTED);
        return -1;
    }

    // Configure for continuous mode and 50 mT range
    char config_data[2];
    config_data[0] = CONTINUOUS_MODE; // Example value, check datasheet
    config_data[1] = RANGE_50MT;       // Example value, check datasheet

    result = i2cWriteI2CBlockData(i2c_handle, 0x00, config_data, 2); // Assuming configuration register is at address 0x00
    if (result != 2) {
        fprintf(stderr, "Error configuring sensor: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read raw sensor data from the TMAG5170
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char data[6];
    int result = i2cReadI2CBlockData(i2c_handle, DATA_REG_X, data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading sensor data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *y = (int16_t)((data[2] << 8) | data[3]);
    *z = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

// Convert raw sensor reading to mT
double convert_to_mt(int16_t raw_value) {
    return (double)raw_value * LSB_SCALE_FACTOR;
}

// Get current timestamp in ISO 8601 format
char *get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char buffer[80];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return buffer;
}

// Log data to CSV file
int log_data(double x, double y, double z) {
    char *timestamp = get_iso8601_timestamp();
    if (fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file); // Ensure data is written immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end for appending

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    double x_mt, y_mt, z_mt;

    while (program_running) {
        if (read_sensor_data(&x_raw, &y_raw, &z_raw) == 0) {
            x_mt = convert_to_mt(x_raw);
            y_mt = convert_to_mt(y_raw);
            z_mt = convert_to_mt(z_raw);

            if (log_data(x_mt, y_mt, z_mt) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

