static volatile int running = 1;

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an alert message to the console and the log file
void log_alert() {
    char* timestamp = get_timestamp();
    printf("%s ALERT: Water detected\n", timestamp);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(fp, "%s ALERT: Water detected\n", timestamp);
    fclose(fp);
}

// Function to read the water level sensor
int read_water_level() {
    int level = gpioRead(GPIO_PIN);
    if (level < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", GPIO_PIN, level);
        return -1; // Indicate an error
    }
    return level;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO 23 as an input with a pull-down resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int water_level = read_water_level();
        if (water_level == 1) {
            log_alert();
        } else if (water_level < 0) {
            // Attempt to re-initialize pigpio after a delay
            fprintf(stderr, "Attempting to re-initialize pigpio...\n");
            gpioTerminate();
            gpioDelay(60000); // Wait 60 seconds
            if (gpioInitialise() < 0) {
                fprintf(stderr, "pigpio re-initialisation failed\n");
                // Consider more drastic measures if re-initialization fails repeatedly
            }
        }

        gpioDelay(POLL_INTERVAL_SEC * 1000); // Delay for 2 seconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();
    printf("Water level monitoring stopped.\n");

    return 0;
}

