#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 4
#define LOG_FILE "rpm_log.txt"

volatile unsigned int pulse_count = 0;
FILE *log_file = NULL;

// Function to handle the interrupt
void pulse_callback(int gpio, int level, uint32_t tick)
{
    if (level == PI_HIGH) {
        pulse_count++;
    }
}

// Function to calculate RPM
double calculate_rpm(unsigned int pulses)
{
    return (double)pulses * 60.0;
}

// Function to log RPM to file
int log_rpm(double rpm)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error flushing log file.\n");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioSetTimerFuncEx(GPIO_PIN, 0, NULL, NULL); // Disable timer
    gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL); // Disable alert

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
    exit(0);
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP);

    // Set up interrupt handler
    if (gpioSetAlertFuncEx(GPIO_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function.\n");
        gpioTerminate();
        return 1;
    }

    // Set up timer function
    if (gpioSetTimerFuncEx(GPIO_PIN, 1000, NULL, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    return 0;
}

