        double rpm = calculate_rpm(pulse_count);

        // Log RPM
        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Error logging RPM.\n");
        }

        // Print RPM to stdout
        printf("RPM: %.2f\n", rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    return 0;
}

