// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the mutex to protect the shared state
pthread_mutex_t state_mutex;

// Define the log file pointer
FILE *log_file = NULL;

// Define the previous state of the quadrature decoder
int previous_state = 0;

// Function prototypes
void sensor_a_callback(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_callback(int gpio, int level, uint32_t tick, void *user_data);
void log_rotation(const char *direction);
void signal_handler(int signal);

// Structure to pass data to the callback function
typedef struct {
    int gpio;
    int level;
    uint32_t tick;
} callback_data_t;

// Function to log the rotation event with millisecond precision
void log_rotation(const char *direction) {
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", ts.tv_nsec / 1000000);

    pthread_mutex_lock(&state_mutex);
    fprintf(log_file, "%s %s\n", timestamp, direction);
    fflush(log_file);
    pthread_mutex_unlock(&state_mutex);
}

