void sensor_a_callback(int gpio, int level, uint32_t tick, void *user_data) {
    callback_data_t *data = (callback_data_t *)user_data;
    int current_state = (data->gpio == SENSOR_A_GPIO) ? (data->level == 1) : (data->level == 1);

    pthread_mutex_lock(&state_mutex);
    int previous_state_local = previous_state;
    pthread_mutex_unlock(&state_mutex);

    int new_state = (current_state << 1) | (previous_state_local & 1);

    pthread_mutex_lock(&state_mutex);
    previous_state = current_state;
    pthread_mutex_unlock(&state_mutex);

    if (new_state == 0b01) {
        log_rotation("CW");
    } else if (new_state == 0b10) {
        log_rotation("CCW");
    }
}

// Callback function for Sensor B
void sensor_b_callback(int gpio, int level, uint32_t tick, void *user_data) {
    callback_data_t *data = (callback_data_t *)user_data;
    int current_state = (data->gpio == SENSOR_B_GPIO) ? (data->level == 1) : (data->level == 1);

