    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close the log file
    if (log_file != NULL) {
        pthread_mutex_lock(&state_mutex);
        fclose(log_file);
        pthread_mutex_unlock(&state_mutex);
    }

    // Terminate the pigpio library
    gpioTerminate();

    // Destroy the mutex
    pthread_mutex_destroy(&state_mutex);

    exit(0);
}

int main() {
