    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    // Initialize the mutex
    if (pthread_mutex_init(&state_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open the log file
    pthread_mutex_lock(&state_mutex);
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        pthread_mutex_unlock(&state_mutex);
        gpioTerminate();
        pthread_mutex_destroy(&state_mutex);
        return 1;
    }
    pthread_mutex_unlock(&state_mutex);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up alert functions for both sensors
    callback_data_t sensor_a_data = {SENSOR_A_GPIO, 0, 0};
    callback_data_t sensor_b_data = {SENSOR_B_GPIO, 0, 0};

    gpioSetAlertFuncEx(SENSOR_A_GPIO, sensor_a_callback, &sensor_a_data);
    gpioSetAlertFuncEx(SENSOR_B_GPIO, sensor_b_callback, &sensor_b_data);

    // Main loop (sleep to avoid busy-spinning)
    while (1) {
        sleep(1); // Sleep for 1 second
    }

    return 0;
}

