#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *touch_line = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int initialize_gpio(void);
int read_touch_sensor(void);
int control_led(int state);
void cleanup_gpio(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, cleaning up...");
    cleanup_gpio();
    closelog();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        syslog(LOG_ERR, "Error opening GPIO chip");
        return -1;
    }

    // Get line for touch sensor
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (!touch_line) {
        syslog(LOG_ERR, "Error getting touch sensor line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request touch sensor line for input
    if (gpiod_line_request_input(touch_line, "touch_sensor") < 0) {
        syslog(LOG_ERR, "Error requesting touch sensor line for input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        syslog(LOG_ERR, "Error getting LED line");
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        return -1;
    }

    // Request LED line for output
    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        syslog(LOG_ERR, "Error requesting LED line for output");
        gpiod_chip_close(chip);
        gpiod_line_release(touch_line);
        gpiod_line_release(led_line);
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Function to read the touch sensor
int read_touch_sensor(void) {
    int value = gpiod_line_get_value(touch_line);
    if (value < 0) {
        syslog(LOG_ERR, "Error reading touch sensor value");
        return -1;
    }
    return value;
}

// Function to control the LED
int control_led(int state) {
    if (gpiod_line_set_value(led_line, state) < 0) {
        syslog(LOG_ERR, "Error setting LED value");
        return -1;
    }
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(void) {
    if (touch_line) {
        gpiod_line_release(touch_line);
    }
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    syslog(LOG_INFO, "GPIO resources released");
}

int main(void) {
    // Open syslog
    openlog("touch_led", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Main loop
    while (1) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            syslog(LOG_ERR, "Error reading touch sensor, exiting");
            break;
        }

        if (control_led(touch_state) < 0) {
            syslog(LOG_ERR, "Error controlling LED, exiting");
            break;
        }

        // Log touch event
        if (touch_state == 1) {
            time_t now = time(NULL);
            struct tm *tstruct = localtime(&now);
            char buf[80];
            strftime(buf, sizeof(buf), "%Y-%m-%d.%X", tstruct);
            syslog(LOG_INFO, "Touch detected at %s", buf);
        }

        usleep(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup_gpio();
    closelog();
    return 0;
}

