#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static volatile int led_state = 0; // 0 = off, 1 = on

// Function prototypes
int initialize_gpio();
int setup_touch_sensor();
int setup_led();
int read_touch_sensor();
int toggle_led();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
} gpio_config_t;

gpio_config_t gpio_config = {TOUCH_SENSOR_PIN, LED_PIN};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Setup touch sensor
    if (setup_touch_sensor() != 0) {
        fprintf(stderr, "Failed to setup touch sensor. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Setup LED
    if (setup_led() != 0) {
        fprintf(stderr, "Failed to setup LED. Exiting.\n");
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (running) {
        if (read_touch_sensor() == 1) {
            toggle_led();
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        }
        gpioDelay(1000); // Check every 1 ms
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

// Initialize GPIO library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Setup touch sensor as input with pull-down resistor
int setup_touch_sensor() {
    gpioSetMode(gpio_config.touch_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_config.touch_pin, PI_PUD_DOWN);
    return 0;
}

// Setup LED as output and initialize to LOW
int setup_led() {
    gpioSetMode(gpio_config.led_pin, PI_OUTPUT);
    gpioWrite(gpio_config.led_pin, 0); // Initially turn LED off
    return 0;
}

// Read touch sensor state
int read_touch_sensor() {
    return gpioRead(gpio_config.touch_pin);
}

// Toggle LED state
int toggle_led() {
    led_state = !led_state;
    gpioWrite(gpio_config.led_pin, led_state);
    return 0;
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(gpio_config.led_pin, 0); // Turn off LED
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d. Cleaning up and exiting.\n", signal);
    running = 0;
}

