#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define circular buffer size
#define BUFFER_SIZE 100

// Structure to store log entries
typedef struct {
    int sensor_pin;
    time_t timestamp;
    int new_state;
} log_entry_t;

// Circular buffer structure
typedef struct {
    log_entry_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    int overflow_count;
} circular_buffer_t;

// Global variables
circular_buffer_t log_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int sensor_pin, int new_state);
void print_log_buffer();
void signal_handler(int signal);
void initialize_circular_buffer(circular_buffer_t *cb);

// Function to initialize the circular buffer
void initialize_circular_buffer(circular_buffer_t *cb) {
    cb->head = 0;
    cb->tail = 0;
    cb->count = 0;
    cb->overflow_count = 0;
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set mode for SENSOR_2_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_1_PIN\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set mode for LED_2_PIN\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read sensor state with debounce
int read_sensor(int pin) {
    int count = 0;
    int state = gpioRead(pin);

    while (count < DEBOUNCE_TIME) {
        if (gpioRead(pin) != state) {
            return state; // Return the current state if it changes during debounce
        }
        gpioDelay(1); // Delay for 1 ms
        count++;
    }

    return state; // Return the stable state after debounce
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log events to the circular buffer
void log_event(int sensor_pin, int new_state) {
    time_t now = time(NULL);

    log_buffer.buffer[log_buffer.head].sensor_pin = sensor_pin;
    log_buffer.buffer[log_buffer.head].timestamp = now;
    log_buffer.buffer[log_buffer.head].new_state = new_state;

    log_buffer.head = (log_buffer.head + 1) % BUFFER_SIZE;

    if (log_buffer.count == BUFFER_SIZE) {
        log_buffer.tail = (log_buffer.tail + 1) % BUFFER_SIZE;
        log_buffer.overflow_count++;
    } else {
        log_buffer.count++;
    }
}

