    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize circular buffer
    initialize_circular_buffer(&log_buffer);

    int sensor1_state = 0;
    int sensor2_state = 0;

    printf("Touch sensor interface started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int new_sensor1_state = read_sensor(SENSOR_1_PIN);
        int new_sensor2_state = read_sensor(SENSOR_2_PIN);

        if (new_sensor1_state != sensor1_state) {
            control_led(LED_1_PIN, new_sensor1_state);
            log_event(SENSOR_1_PIN, new_sensor1_state);
            sensor1_state = new_sensor1_state;
        }

        if (new_sensor2_state != sensor2_state) {
            control_led(LED_2_PIN, new_sensor2_state);
            log_event(SENSOR_2_PIN, new_sensor2_state);
            sensor2_state = new_sensor2_state;
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Turn off LEDs
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Print log buffer
    print_log_buffer();

    // Terminate pigpio
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

