#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define GPIO pins for the Hall-Effect sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Debounce time in microseconds
#define DEBOUNCE_TIME 5000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
} SensorStates;

// Function prototypes
int initialize_gpio();
SensorStates read_sensors();
double calculate_rpm(SensorStates current_states, SensorStates previous_states);
void log_data(SensorStates states);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        running = 0;
    }
}

// Initializes the pigpio library and sets up the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Enable pull-up resistors (optional, depending on sensor wiring)
    // gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    // gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Reads the current state of the Hall-Effect sensors
SensorStates read_sensors() {
    SensorStates states;
    states.sensor1_state = gpioRead(SENSOR1_GPIO);
    states.sensor2_state = gpioRead(SENSOR2_GPIO);
    return states;
}

// Calculates the RPM based on the state changes of the sensors
double calculate_rpm(SensorStates current_states, SensorStates previous_states) {
    // Assuming two pulses per revolution
    if (current_states.sensor1_state != previous_states.sensor1_state) {
        return 30.0; // Example RPM value
    } else if (current_states.sensor2_state != previous_states.sensor2_state) {
        return 30.0; // Example RPM value
    } else {
        return 0.0; // No pulse detected
    }
}

// Logs the sensor data to a CSV file
void log_data(SensorStates states) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d\n", timestamp, states.sensor1_state, states.sensor2_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("shaft_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    SensorStates previous_states = {0, 0};
    SensorStates current_states;
    double rpm;

    printf("RPM Monitoring Started. Press Ctrl+C to exit.\n");

    while (running) {
        current_states = read_sensors();
        rpm = calculate_rpm(current_states, previous_states);

        if (rpm > 0) {
            printf("RPM: %.2f\n", rpm);
        }

        log_data(current_states);
        previous_states = current_states;

        gpioDelay(1000); // Delay for 1 ms
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("RPM Monitoring Stopped.\n");
    return 0;
}

