#define I2C_BUS 1
#define SI1182_ADDR 0x28
#define CONFIG_REG 0x30
#define HEART_RATE_REG 0x02
#define SPO2_REG 0x04
#define PART_ID_REG 0x00
#define PART_ID_VALUE 0x82

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int verify_sensor();
int configure_sensor();
int read_heart_rate();
int read_spo2();
int log_data(int heart_rate, int spo2);
void signal_handler(int signal);

// Structure for sensor data (optional)
typedef struct {
    int heart_rate;
    int spo2;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open the I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to verify the sensor
int verify_sensor() {
    int part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID register: %d\n", part_id);
        return -1;
    }
    if (part_id != PART_ID_VALUE) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x%02X)\n", part_id, PART_ID_VALUE);
        return -1;
    }
    return 0;
}

// Function to configure the sensor
int configure_sensor() {
    // Configure for continuous measurement (example configuration)
    int status = i2cWriteByteData(i2c_handle, CONFIG_REG, 0x01); // Example value
    if (status < 0) {
        fprintf(stderr, "Failed to write to CONFIG register: %d\n", status);
        return -1;
    }
    return 0;
}

// Function to read heart rate data
int read_heart_rate() {
    int heart_rate = i2cReadByteData(i2c_handle, HEART_RATE_REG);
    if (heart_rate < 0) {
        fprintf(stderr, "Failed to read HEART_RATE register: %d\n", heart_rate);
        return -1;
    }
    return heart_rate;
}

// Function to read SpO2 data
int read_spo2() {
    int spo2 = i2cReadByteData(i2c_handle, SPO2_REG);
    if (spo2 < 0) {
        fprintf(stderr, "Failed to read SPO2 register: %d\n", spo2);
        return -1;
    }
    return spo2;
}

// Function to log data to file
int log_data(int heart_rate, int spo2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Heart Rate: %d BPM, SpO2: %d%%\n", timestamp, heart_rate, spo2);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Received signal %d, terminating...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        gpioTerminate();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        int heart_rate = read_heart_rate();
        int spo2 = read_spo2();

        if (heart_rate >= 0 && spo2 >= 0) {
            // Log data
            log_data(heart_rate, spo2);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

