#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

// Define tilt duration threshold (in seconds)
#define TILT_DURATION_THRESHOLD 2

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int check_threshold(int sensor1_value, int sensor2_value);
void activate_alarm();
void deactivate_alarm();
void log_event(const char *event_type, int sensor1_value, int sensor2_value);
void signal_handler(int signal);

// Structure to hold sensor states
typedef struct {
    int sensor1_state;
    int sensor2_state;
    int alarm_state;
} SystemState;

SystemState current_state = {0, 0, 0};

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("bridge_integrity.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Check if threshold is exceeded
        if (check_threshold(sensor1_value, sensor2_value)) {
            // Activate alarm if not already active
            if (!current_state.alarm_state) {
                activate_alarm();
                current_state.alarm_state = 1;
                log_event("alarm_activated", sensor1_value, sensor2_value);
            }
        } else {
            // Deactivate alarm if both sensors are LOW
            if (sensor1_value == 0 && sensor2_value == 0 && current_state.alarm_state) {
                deactivate_alarm();
                current_state.alarm_state = 0;
                log_event("alarm_deactivated", sensor1_value, sensor2_value);
            }
        }

        // Log sensor readings
        log_event("sensor_reading", sensor1_value, sensor2_value);

        // Delay
        gpioDelay(100); // 100 ms
    }

    // Clean up and exit
    return 0;
}

// Initialize pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Enable pull-down resistors (optional, depends on sensor wiring)
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    return 0;
}

// Read sensor value
int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on pin %d\n", pin);
        return -1; // Indicate error
    }
    return value;
}

// Check if threshold is exceeded
int check_threshold(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 1 || sensor2_value == 1);
}

// Activate alarm
void activate_alarm() {
    gpioWrite(ALARM_PIN, 1);
}

// Deactivate alarm
void deactivate_alarm() {
    gpioWrite(ALARM_PIN, 0);
}

// Log event to file
void log_event(const char *event_type, int sensor1_value, int sensor2_value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    fprintf(log_file, "%s - %s - Sensor1: %d, Sensor2: %d\n", timestamp, event_type, sensor1_value, sensor2_value);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for clean shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Deactivate alarm
    deactivate_alarm();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

