#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x1D
#define CTRL1_REG 0x1F
#define ACCEL_X_REG 0x28
#define ACCEL_Y_REG 0x2A
#define ACCEL_Z_REG 0x2C
#define LED_GPIO 17
#define THRESHOLD 500
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int on);
void log_event(double magnitude);
void signal_handler(int signal);

// Structure for sensor data (optional, but good practice)
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the sensor
int initialize_sensor() {
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, CTRL1_REG, 0x00) == 0) { // Clear power-down bit
            return 0; // Success
        }
        fprintf(stderr, "Error initializing sensor, retrying... (%d retries left)\n", retries - 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = RETRY_COUNT;
    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, ACCEL_X_REG, buffer, 6) == 6) {
            // Combine the two bytes for each axis (little-endian)
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        }
        fprintf(stderr, "Error reading acceleration data, retrying... (%d retries left)\n", retries - 1);
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        retries--;
    }
    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate the Euclidean magnitude of the acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// Function to control the LED
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Function to log an event to the log file
void log_event(double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Magnitude: %.2f\n", timestamp, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen("seismic_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read acceleration data
        if (read_acceleration(&sensor_data.x, &sensor_data.y, &sensor_data.z) == 0) {
            // Calculate magnitude
            double magnitude = calculate_magnitude(sensor_data.x, sensor_data.y, sensor_data.z);

            // Check if threshold is exceeded
            if (magnitude > THRESHOLD) {
                // Turn on LED
                control_led(1);

                // Log event
                log_event(magnitude);

                // Wait for 1 second
                gpioDelay(1000000); // 1 second in microseconds

                // Turn off LED
                control_led(0);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying initialization.\n");
            i2cClose(i2c_handle);
            i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                terminate = 1; // Exit loop if I2C fails repeatedly
            } else {
                if (initialize_sensor() != 0) {
                    fprintf(stderr, "Sensor re-initialization failed\n");
