#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to read sensor data
int read_sensor(int gpio_pin) {
    return (gpioRead(gpio_pin) == 0) ? 1 : 0; // Active-low logic
}

// Function to control the LED
void control_led(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1_detected = read_sensor(SENSOR_1_PIN);
        int sensor2_detected = read_sensor(SENSOR_2_PIN);
        int sensor3_detected = read_sensor(SENSOR_3_PIN);
        int sensor4_detected = read_sensor(SENSOR_4_PIN);

        // Check if any sensor detects an object
        int object_detected = sensor1_detected || sensor2_detected || sensor3_detected || sensor4_detected;

        // Control the LED
        control_led(LED_PIN, object_detected);

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpio uses microseconds
    }

    // Clean up and terminate pigpio
    gpioTerminate();

    return 0;
}

