#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for the flame sensors
#define SENSOR_1_PIN 2
#define SENSOR_2_PIN 3
#define SENSOR_3_PIN 4
#define SENSOR_4_PIN 17
#define SENSOR_5_PIN 27

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Log file path
#define LOG_FILE "/var/log/flame_events.log"

// Structure to hold sensor data
typedef struct {
    int pin;
    int id;
    int gpio_pin;
    int last_state;
} sensor_t;

// Global flag to signal program termination
volatile sig_atomic_t program_running = 1;

// Array of sensor structures
sensor_t sensors[] = {
    {1, 2, SENSOR_1_PIN, 1},
    {2, 3, SENSOR_2_PIN, 1},
    {3, 4, SENSOR_3_PIN, 1},
    {4, 17, SENSOR_4_PIN, 1},
    {5, 27, SENSOR_5_PIN, 1}
};

const int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

// Function prototypes
int initialize_gpio();
int read_sensor(sensor_t *sensor);
int log_event(sensor_t *sensor);
void signal_handler(int signal);
void cleanup();

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].gpio_pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].gpio_pin, PI_PUD_UP); // Enable pull-up resistor
        sensors[i].last_state = gpioRead(sensors[i].gpio_pin);
    }

    return 0;
}

// Function to read the state of a flame sensor
int read_sensor(sensor_t *sensor) {
    int current_state = gpioRead(sensor->gpio_pin);

    if (current_state != sensor->last_state) {
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        current_state = gpioRead(sensor->gpio_pin);

        if (current_state != sensor->last_state) {
            sensor->last_state = current_state;
            return current_state;
        }
    }

    return sensor->last_state;
}

// Function to log a flame detection event to the log file
int log_event(sensor_t *sensor) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", LOG_FILE);
        return -1;
    }

    // Acquire an exclusive lock on the log file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", LOG_FILE);
        fclose(fp);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *gmtime(&t);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor->id, sensor->gpio_pin);
    fflush(fp);

    // Release the lock on the log file
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", LOG_FILE);
    }

    fclose(fp);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, exiting...");
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up...");
    gpioTerminate();
    closelog();
}

int main() {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        cleanup();
        return 1;
    }

    syslog(LOG_INFO, "Flame monitor started");

    // Main loop
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int sensor_state = read_sensor(&sensors[i]);

            if (sensor_state == 0) { // Flame detected (LOW signal)
                if (log_event(&sensors[i]) != 0) {
                    syslog(LOG_ERR, "Failed to log event for sensor %d", sensors[i].id);
                }
            }
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

