#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define GPIO_PINS {5, 6, 13, 19, 26, 12, 16, 20}

// Structure to hold GPIO line information
struct gpio_line {
    int pin;
    struct gpiod_line *line;
};

// Global variables
struct gpiod_chip *chip = NULL;
struct gpio_line lines[8];
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int request_lines(void);
int read_touch_states(void);
void log_touch_event(int index, int pin, int state);
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;

    // Release GPIO lines
    for (int i = 0; i < 8; i++) {
        if (lines[i].line) {
            gpiod_line_release(lines[i].line);
        }
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Initialize GPIO chip
int init_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return 0;
}

// Request GPIO lines
int request_lines(void) {
    int pins[] = GPIO_PINS;
    for (int i = 0; i < 8; i++) {
        lines[i].pin = pins[i];
        lines[i].line = gpiod_chip_get_line(chip, lines[i].pin);
        if (!lines[i].line) {
            perror("Error getting GPIO line");
            return -1;
        }

        if (gpiod_line_request_input(lines[i].line, "touch_sensor") < 0) {
            perror("Error requesting GPIO line as input");
            return -1;
        }
    }
    return 0;
}

// Read touch states
int read_touch_states(void) {
    int states[8];
    for (int i = 0; i < 8; i++) {
        int value = gpiod_line_get_value(lines[i].line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            return -1;
        }
        states[i] = value;
    }

    for (int i = 0; i < 8; i++) {
        if (states[i] == 1) {
            log_touch_event(i, lines[i].pin, 1);
        } else if (states[i] == 0) {
            log_touch_event(i, lines[i].pin, 0);
        }
    }
    return 0;
}

// Log touch event
void log_touch_event(int index, int pin, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s - Sensor %d (Pin %d): %s\n", timestamp, index, pin, state ? "Touched" : "Released");
}

int main(void) {
    // Install signal handler
    signal(SIGINT, cleanup);

    // Initialize GPIO
    if (init_gpio() < 0) {
        return 1;
    }

    // Request GPIO lines
    if (request_lines() < 0) {
        cleanup(0);
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_touch_states() < 0) {
            fprintf(stderr, "Error reading touch states, exiting...\n");
            cleanup(0);
            return 1;
        }
        struct timespec delay = {0, 50000000}; // 50 milliseconds
        nanosleep(&delay, NULL);
    }

    return 0;
}

