#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x10
#define ALS_REG 0x04
#define CONFIG_REG 0x00
#define GPIO_LED 18
#define PWM_FREQ 1000
#define PWM_RANGE 100
#define LOG_FILE "grow_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c();
int configure_sensor();
int read_lux(uint16_t *raw_lux);
float convert_to_lux(uint16_t raw_lux);
int set_led_brightness(float lux);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration
typedef struct {
    uint8_t gain;
    uint8_t integration_time;
} sensor_config_t;

// Function to initialize pigpio
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to open I2C bus
int open_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure the VEML7700 sensor
int configure_sensor() {
    // Configuration: ALS gain 1/8, ALS integration time 100ms
    uint16_t config_value = 0x0000; // Gain 1/8, Integration time 100ms
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = config_value & 0xFF;       // Low byte
    buf[2] = (config_value >> 8) & 0xFF; // High byte

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read ambient light data from the sensor
int read_lux(uint16_t *raw_lux) {
    char buf[1];
    buf[0] = ALS_REG;
    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to ALS register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return -1;
    }

    *raw_lux = (read_buf[1] << 8) | read_buf[0]; // Little-endian
    return 0;
}

// Function to convert raw lux value to lux
float convert_to_lux(uint16_t raw_lux) {
    return (float)raw_lux * 0.0576;
}

// Function to set LED brightness using PWM
int set_led_brightness(float lux) {
    int brightness;
    if (lux < 100) {
        brightness = PWM_RANGE;
    } else if (lux < 500) {
        brightness = (int)(PWM_RANGE * 0.75);
    } else if (lux < 1000) {
        brightness = (int)(PWM_RANGE * 0.5);
    } else {
        brightness = (int)(PWM_RANGE * 0.25);
    }

    gpioPWM(GPIO_LED, brightness);
    return brightness;
}

// Function to log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    gpioPWM(GPIO_LED, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Set GPIO mode for LED
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioSetPWMfrequency(GPIO_LED, PWM_FREQ);
    gpioSetPWMrange(GPIO_LED, PWM_RANGE);

    uint16_t raw_lux;
    float lux;
    int brightness;
    int error_code = 0;

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_lux(&raw_lux) == 0) {
            lux = convert_to_lux(raw_lux);
            error_code = 0; // Reset error code on success
        } else {
            lux = -1.0; // Indicate error
            error_code = -1;
        }

        // Set LED brightness
        if (lux >= 0) {
            brightness = set_led_brightness(lux);
        } else {
            brightness = -1; // Indicate error
        }

        // Log data
        log_data(lux, brightness, error_code);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

