#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for touch sensors
#define TOUCH_PIN_1 2
#define TOUCH_PIN_2 3
#define TOUCH_PIN_3 4
#define TOUCH_PIN_4 5
#define TOUCH_PIN_5 6
#define TOUCH_PIN_6 7
#define TOUCH_PIN_7 8
#define TOUCH_PIN_8 9

// Define GPIO pin for LED
#define LED_PIN 17

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold previous touch states
typedef struct {
    int pin1;
    int pin2;
    int pin3;
    int pin4;
    int pin5;
    int pin6;
    int pin7;
    int pin8;
} TouchStates;

static TouchStates previous_states = {0, 0, 0, 0, 0, 0, 0, 0};

// Function prototypes
int initialize_gpio();
int read_touch_sensors();
int log_touch_event(int channel);
int control_led(int on);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set touch sensor pins as inputs with pull-down resistors
    gpioSetMode(TOUCH_PIN_1, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_1, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_2, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_2, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_3, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_3, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_4, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_4, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_5, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_5, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_6, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_6, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_7, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_7, PI_PUD_DOWN);
    gpioSetMode(TOUCH_PIN_8, PI_INPUT);
    gpioSetPullUpDown(TOUCH_PIN_8, PI_PUD_DOWN);

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read touch sensor values
int read_touch_sensors() {
    int pin1 = gpioRead(TOUCH_PIN_1);
    int pin2 = gpioRead(TOUCH_PIN_2);
    int pin3 = gpioRead(TOUCH_PIN_3);
    int pin4 = gpioRead(TOUCH_PIN_4);
    int pin5 = gpioRead(TOUCH_PIN_5);
    int pin6 = gpioRead(TOUCH_PIN_6);
    int pin7 = gpioRead(TOUCH_PIN_7);
    int pin8 = gpioRead(TOUCH_PIN_8);

    return (pin1 << 0) | (pin2 << 1) | (pin3 << 2) | (pin4 << 3) |
           (pin5 << 4) | (pin6 << 5) | (pin7 << 6) | (pin8 << 7);
}

// Function to log touch event
int log_touch_event(int channel) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return 1;
    }

    if (fprintf(log_file, "%s - Channel %d Touched\n", timestamp, channel + 1) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to control the LED
int control_led(int on) {
    gpioWrite(LED_PIN, on);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_data = read_touch_sensors();
        int any_touched = 0;

        // Check each channel for touch
        for (int i = 0; i < 8; i++) {
            int current_state = (touch_data >> i) & 1;
            int previous_state = (previous_states.pin1 << i) & 1;

            if (current_state && !previous_state) {
                // Touch detected on channel i+1
                if (log_touch_event(i) == 0) {
                    printf("Touch detected on channel %d\n", i + 1);
                }
                any_touched = 1;
            }

            // Update previous state
            if (i == 0) previous_states.pin1 = current_state;
            if (i == 1) previous_states.pin2 = current_state;
            if (i == 2) previous_states.pin3 = current_state;
            if (i == 3) previous_states.pin4 = current_state;
            if (i == 4) previous_states.pin5 = current_state;
            if (i == 5) previous_states.pin6 = current_state;
            if (i == 6) previous_states.pin7 = current_state;
            if (i == 7) previous_states.pin8 = current_state;
        }

        // Control LED based on touch state
        if (any_touched) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

