}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Security Keypad Simulation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_data = read_touch_sensors();
        int any_touched = 0;

        // Check each channel for touch
        for (int i = 0; i < 8; i++) {
            int current_state = (touch_data >> i) & 1;
            int previous_state = (previous_states.pin1 << i) & 1;

            if (current_state && !previous_state) {
                // Touch detected on channel i+1
                if (log_touch_event(i) == 0) {
                    printf("Touch detected on channel %d\n", i + 1);
                }
                any_touched = 1;
            }

            // Update previous state
            if (i == 0) previous_states.pin1 = current_state;
            if (i == 1) previous_states.pin2 = current_state;
            if (i == 2) previous_states.pin3 = current_state;
            if (i == 3) previous_states.pin4 = current_state;
            if (i == 4) previous_states.pin5 = current_state;
            if (i == 5) previous_states.pin6 = current_state;
            if (i == 6) previous_states.pin7 = current_state;
            if (i == 7) previous_states.pin8 = current_state;
        }

        // Control LED based on touch state
        if (any_touched) {
            control_led(1); // Turn LED on
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce delay
    }

    // Cleanup
    control_led(0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
