#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define OPT3001_ADDR 0x44
#define CONFIG_REG 0x01
#define RESULT_REG 0x00
#define CONFIG_VALUE 0xC810 // Continuous conversion, auto range, 100ms
#define LUX_SCALE 0.01
#define LOG_FILE "light_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int write_config(uint16_t config_value);
int read_result(uint16_t *result);
float calculate_lux(uint16_t raw_result);
int log_data(float lux_value);
void print_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Byte swap function (big-endian to little-endian)
uint16_t byte_swap(uint16_t value) {
    return (value >> 8) | (value << 8);
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Write configuration to OPT3001
int write_config(uint16_t config_value) {
    uint16_t swapped_config = byte_swap(config_value);
    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, swapped_config);
    if (result < 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }
    return 0;
}

// Read result register from OPT3001
int read_result(uint16_t *result) {
    int raw_result = i2cReadWordData(i2c_handle, RESULT_REG);
    if (raw_result < 0) {
        fprintf(stderr, "Error reading from result register: %d\n", raw_result);
        return -1;
    }
    *result = (uint16_t)raw_result; // Cast to uint16_t
    return 0;
}

// Calculate lux value from raw result
float calculate_lux(uint16_t raw_result) {
    uint16_t swapped_result = byte_swap(raw_result);
    int exponent = (swapped_result >> 12) & 0x0F;
    int mantissa = swapped_result & 0x0FFF;
    return (float)mantissa * LUX_SCALE * (1 << exponent);
}

// Log data to file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file);
    fclose(log_file);
    return 0;
}

// Print data to stdout
void print_data(float lux_value) {
    printf("Lux: %.2f\n", lux_value);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Write configuration
    if (write_config(CONFIG_VALUE) != 0) {
        cleanup();
        return 1;
    }

    // Wait for first conversion (100ms)
    gpioDelay(100);

    // Main loop
    while (!terminate) {
        uint16_t raw_result;
        if (read_result(&raw_result) == 0) {
            float lux_value = calculate_lux(raw_result);
            print_data(lux_value);
            log_data(lux_value);
        } else {
            fprintf(stderr, "Failed to read result, retrying...\n");
        }

        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

