    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp for logging.\n");
        return;
    }

    if (log_file != NULL) {
        fprintf(log_file, "%s %s\n", timestamp, message);
        fflush(log_file); // Ensure the message is written immediately
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
    free(timestamp);
}

