#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 4
#define GPIO_LINE "gpio4"
#define LOG_FILE "touch_log.txt"
#define DEBOUNCE_MS 50

static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;
static volatile sig_atomic_t terminate = 0;

// Function to get the current timestamp in the format YYYY-MM-DD HH:MM:SS
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Ensure the buffer is large enough

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to log an event to the file
int log_event(const char *event_type) {
    char *timestamp = get_timestamp();
    if (log_fp == NULL) {
        fprintf(stderr, "Error: Log file not opened.\n");
        return -1;
    }

    if (fprintf(log_fp, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read the touch sensor state
int read_touch_sensor() {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    int prev_state = -1; // Initialize to an invalid state
    int current_state;
    struct timespec debounce_delay = {0, DEBOUNCE_MS * 1000000L}; // 50ms

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIO_CHIP, strerror(errno));
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line '%s': %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input with pull-down resistor
    if (gpiod_line_request_input(line, "touch_sensor") < 0) {
        fprintf(stderr, "Error requesting GPIO line as input: %s\n", strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        current_state = read_touch_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting.\n");
            break;
        }

        if (current_state != prev_state) {
            if (current_state == 1) {
                if (log_event("Touch Detected") != 0) {
                    fprintf(stderr, "Error logging touch event.\n");
                }
            } else {
                if (log_event("Touch Released") != 0) {
                    fprintf(stderr, "Error logging release event.\n");
                }
            }
            prev_state = current_state;
            nanosleep(&debounce_delay, NULL); // Debounce
        }
        nanosleep(&debounce_delay, NULL); // Small delay to avoid busy-waiting
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    if (log_fp) {
        fclose(log_fp);
    }

    fprintf(stderr, "Exiting.\n");
    return 0;
}

