#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x08
#define CONTINUOUS_MEASUREMENT_COMMAND 0x3608
#define FLOW_RATE_SCALE_FACTOR 90.0
#define LOG_FILE "cooling_log.csv"
#define ERROR_RECOVERY_DELAY_MS 100
#define MAX_RETRIES 3

// Global variables
int i2c_handle = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_i2c();
int read_flow_rate(int16_t *raw_flow_rate);
float convert_to_ml_min(int16_t raw_flow_rate);
int validate_flow_rate(float flow_rate);
int log_data(float flow_rate, const char *status);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Send continuous measurement command
    char command[2] = {(CONTINUOUS_MEASUREMENT_COMMAND >> 8) & 0xFF, CONTINUOUS_MEASUREMENT_COMMAND & 0xFF};
    int result = i2cWriteDevice(i2c_handle, command, 2);
    if (result != 0) {
        fprintf(stderr, "Error sending continuous measurement command: %d\n", result);
        i2cClose(i2c_handle);
        i2c_handle = -1;
        return -1;
    }

    gpioDelay(2); // Wait for 2 ms
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int16_t *raw_flow_rate) {
    char buffer[3];
    int result = i2cReadDevice(i2c_handle, buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading flow rate: %d\n", result);
        return -1;
    }

    // Validate CRC
    uint8_t crc = crc8((uint8_t *)buffer, 2);
    if (crc != (uint8_t)buffer[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    // Convert to signed 16-bit integer (big-endian)
    *raw_flow_rate = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Convert raw flow rate to ml/min
float convert_to_ml_min(int16_t raw_flow_rate) {
    return (float)raw_flow_rate / FLOW_RATE_SCALE_FACTOR;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate >= 0.0 && flow_rate <= 100.0) {
        return 0; // Valid
    } else {
        return -1; // Invalid
    }
}

// Log data to file
int log_data(float flow_rate, const char *status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%s\n", timestamp, flow_rate, status);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler
    signal(SIGINT, signal_handler);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Check if the file is new and write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
        fflush(log_file);
    }
    fseek(log_file, 0, SEEK_END);

    // Initialize I2C with retry logic
    int retries = 0;
    while (initialize_i2c() != 0 && retries < MAX_RETRIES) {
        fprintf(stderr, "I2C initialization failed, retrying... (%d/%d)\n", retries + 1, MAX_RETRIES);
        gpioDelay(ERROR_RECOVERY_DELAY_MS);
        retries++;
    }

    if (i2c_handle < 0) {
        fprintf(stderr, "I2C initialization failed after multiple retries. Exiting.\n");
        log_data(0.0, "ERROR");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        int16_t raw_flow_rate;
        if (read_flow_rate(&raw_flow_rate) == 0) {
            float flow_rate = convert_to_ml_min(raw_flow_rate);
            if (validate_flow_rate(flow_rate) == 0) {
                log_data(flow_rate, "OK");
            } else {
                log_data(flow_rate, "INVALID");
            }
        } else {
            log_data(0.0, "ERROR");
        }

        gpioDelay(1000); // Sample every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

