#define GPIO_MIDDLE 27
#define GPIO_RIGHT 22

#define CSV_FILE "path_log.csv"

static volatile int keepRunning = 1;
FILE *logFile = NULL;

// Signal handler for Ctrl+C
void intHandler(int dummy) {
    keepRunning = 0;
}

// Function to get the current timestamp in ISO 8601 format
char* getCurrentTimestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to read sensor values
int readSensors(int gpioLeft, int gpioMiddle, int gpioRight) {
    int leftValue = gpioRead(gpioLeft);
    int middleValue = gpioRead(gpioMiddle);
    int rightValue = gpioRead(gpioRight);

    if (leftValue < 0 || middleValue < 0 || rightValue < 0) {
        fprintf(stderr, "Error reading sensor values: %s\n", strerror(errno));
        return -1; // Indicate an error
    }

    return (leftValue << 2) | (middleValue << 1) | rightValue;
}

// Function to log data to a CSV file
int logData(const char *timestamp, int left, int middle, int right) {
    if (logFile == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(logFile, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fflush(logFile); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(GPIO_LEFT, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_LEFT, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_MIDDLE, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_MIDDLE, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GPIO_RIGHT, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input: %s\n", GPIO_RIGHT, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open the log file
    logFile = fopen(CSV_FILE, "a");
    if (logFile == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", CSV_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(logFile, 0, SEEK_END);
    long fileSize = ftell(logFile);
    if (fileSize == 0) {
        fprintf(logFile, "timestamp,left,middle,right\n");
        fflush(logFile);
    }

    // Set up signal handling for Ctrl+C
    signal(SIGINT, intHandler);

    // Main loop
    while (keepRunning) {
        // Read sensor values
        int sensorValues = readSensors(GPIO_LEFT, GPIO_MIDDLE, GPIO_RIGHT);
        if (sensorValues < 0) {
            fprintf(stderr, "Error reading sensors, exiting.\n");
            break;
        }

        // Get the current timestamp
        char *timestamp = getCurrentTimestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp, exiting.\n");
            break;
        }

        // Extract sensor values
        int left = (sensorValues >> 2) & 1;
        int middle = (sensorValues >> 1) & 1;
        int right = sensorValues & 1;

        // Log the data
        if (logData(timestamp, left, middle, right) != 0) {
            fprintf(stderr, "Error logging data, exiting.\n");
            break;
        }

        free(timestamp);

        // Wait for 50 milliseconds
        gpioDelay(50);
    }

    // Clean up
    fclose(logFile);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

