// Structure to hold GPIO configuration
typedef struct {
    int touch_gpio;
    int led_gpio;
    char gpio_path[64];
} gpio_config_t;

gpio_config_t gpio_config = {
    .touch_gpio = TOUCH_SENSOR_GPIO,
    .led_gpio = LED_GPIO,
    .gpio_path = GPIO_CHIP_PATH
};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Main loop
    while (1) {
        // Read touch sensor
        if (read_touch_sensor() == 1) {
            // Toggle LED
            toggle_led();

            // Log touch event
            log_touch_event(gpioRead(gpio_config.led_gpio));
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    return 0;
}

// Function to initialize GPIO
int initialize_gpio() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(gpio_config.touch_gpio, PI_INPUT);
    gpioSetMode(gpio_config.led_gpio, PI_OUTPUT);

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(gpio_config.touch_gpio);
}

// Function to toggle the LED
void toggle_led() {
    int current_state = gpioRead(gpio_config.led_gpio);
    gpioWrite(gpio_config.led_gpio, !current_state);
}

