    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(log_file, "%s LED: %s\n", timestamp, led_state ? "ON" : "OFF") < 0) {
        fprintf(stderr, "Failed to write to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk
    return 0;
}

// Function to clean up resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
    exit(0);
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Cleaning up...\n", signal);
    cleanup();
}

