#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *flame_line = NULL;
struct gpiod_line *buzzer_line = NULL;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int read_flame_sensor(void);
int activate_buzzer(int duration_ms);
int log_event(const char *message);
void signal_handler(int sig);
int cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        program_running = 0;
    }
}

// Initialize GPIO lines
int initialize_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        goto cleanup_flame_line;
    }

    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        goto cleanup_buzzer_line;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        goto cleanup_flame_line;
    }

    return 0;

cleanup_buzzer_line:
    gpiod_line_release(buzzer_line);
cleanup_flame_line:
    gpiod_line_release(flame_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Read flame sensor value
int read_flame_sensor(void) {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Activate buzzer for a specified duration
int activate_buzzer(int duration_ms) {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value to HIGH: %s\n", strerror(errno));
        return -1;
    }

    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100 * 1000 * 1000; // 100 ms

    int num_slices = duration_ms / 100;
    for (int i = 0; i < num_slices; ++i) {
        nanosleep(&sleep_time, NULL);
    }

    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value to LOW: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log an event to the log file
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    return 0;
}

// Cleanup GPIO resources
int cleanup(void) {
    printf("Cleaning up...\n");

    if (buzzer_line) {
        gpiod_line_set_value(buzzer_line, 0);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line) {
        gpiod_line_release(flame_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

int main(void) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open log file
    log_file = fopen("alert_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return 1;
    }

    // Log system start
    log_event("System started");

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        log_event("GPIO initialization failed");
        cleanup();
        return 1;
    }

    printf("Flame detection system started. Press Ctrl+C to exit.\n");

    int previous_state = 1; // Assume no flame initially (HIGH)

    while (program_running) {
        int current_state = read_flame_sensor();
        if (current_state < 0) {
            fprintf(stderr, "Error reading flame sensor, exiting.\n");
            log_event("Error reading flame sensor");
            break;
        }

        if (current_state == 0 && previous_state == 1) { // Flame detected (LOW to HIGH)
            printf("Flame detected!\n");
            log_event("Flame detected");
            activate_buzzer(2000); // Activate buzzer for 2 seconds
        }

        previous_state = current_state;

        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup and exit
    cleanup();
    log_event("System stopped");
    fclose(log_file);
    return 0;
}

