            debounce_count = 0;
            toggle_led();
            if (log_event() != 0) {
                fprintf(stderr, "Error logging event.\n");
            }
        } else if (touch_state == 1) {
            debounce_count++;
            if (debounce_count >= (DEBOUNCE_DELAY_MS / 10)) {
                toggle_led();
                if (log_event() != 0) {
                    fprintf(stderr, "Error logging event.\n");
                }
                debounce_count = 0; // Reset debounce after toggling
            }
        }

        last_touch_state = touch_state;
        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

