    int sensor1_state;
    int sensor2_state;
    int sensor3_state;
} SensorStates;

SensorStates sensor_states = {1, 1, 1}; // Initialize all states to HIGH (no magnet)

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("magnet_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR1_GPIO);
        if (sensor1_value != -1) {
            if (sensor1_value != sensor_states.sensor1_state) {
                log_event(SENSOR1_GPIO, sensor1_value);
                sensor_states.sensor1_state = sensor1_value;
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR2_GPIO);
        if (sensor2_value != -1) {
            if (sensor2_value != sensor_states.sensor2_state) {
                log_event(SENSOR2_GPIO, sensor2_value);
                sensor_states.sensor2_state = sensor2_value;
            }
        }

        // Read sensor 3
