    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - GPIO %d - Magnet %s\n", timestamp, gpio_pin, state ? "Present" : "Removed");
        fflush(log_file); // Ensure data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open!\n");
        return 1;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
