#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x4A
#define PART_ID_REG 0x00
#define HW_REV_REG 0x01
#define LED_CURRENT_REG 0x3F
#define AVERAGING_REG 0x04
#define ENABLE_REG 0x01
#define HEART_RATE_REG 0x2A
#define BPM_SCALE_FACTOR 0.5
#define MIN_BPM 30
#define MAX_BPM 220
#define MOVING_AVG_SIZE 5
#define LOG_FILE "heart_rate.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure for moving average filter
typedef struct {
    float values[MOVING_AVG_SIZE];
    int index;
    int count;
} MovingAverageFilter;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int verify_sensor();
int configure_sensor();
int read_heart_rate();
float convert_to_bpm(int raw_value);
float apply_moving_average(MovingAverageFilter *filter, float new_value);
int validate_bpm(float bpm);
int log_data(float bpm);
void signal_handler(int signal);
void cleanup();

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Verify sensor presence
int verify_sensor() {
    int part_id, hw_rev;

    part_id = i2cReadByteData(i2c_handle, PART_ID_REG);
    if (part_id < 0) {
        fprintf(stderr, "Error reading PART_ID_REG: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Incorrect PART_ID: 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    hw_rev = i2cReadByteData(i2c_handle, HW_REV_REG);
    if (hw_rev < 0) {
        fprintf(stderr, "Error reading HW_REV_REG: %d\n", hw_rev);
        return -1;
    }
    if (hw_rev != 0x01) {
        fprintf(stderr, "Incorrect HW_REV: 0x%02X (expected 0x01)\n", hw_rev);
        return -1;
    }

    printf("Si1182-A-GM sensor verified\n");
    return 0;
}

// Configure sensor
int configure_sensor() {
    int status;

    // Set LED current (example value)
    status = i2cWriteByteData(i2c_handle, LED_CURRENT_REG, 0x3F); // Max current
    if (status < 0) {
        fprintf(stderr, "Error writing to LED_CURRENT_REG: %d\n", status);
        return -1;
    }

    // Set averaging (example value)
    status = i2cWriteByteData(i2c_handle, AVERAGING_REG, 0x04); // 16 samples
    if (status < 0) {
        fprintf(stderr, "Error writing to AVERAGING_REG: %d\n", status);
        return -1;
    }

    // Enable sensor
    status = i2cWriteByteData(i2c_handle, ENABLE_REG, 0x01); // Enable
    if (status < 0) {
        fprintf(stderr, "Error writing to ENABLE_REG: %d\n", status);
        return -1;
    }

    printf("Sensor configured\n");
    return 0;
}

// Read heart rate
int read_heart_rate() {
    int raw_value;

    raw_value = i2cReadWordData(i2c_handle, HEART_RATE_REG);
    if (raw_value < 0) {
        fprintf(stderr, "Error reading heart rate: %d\n", raw_value);
        return -1;
    }

    return raw_value;
}

// Convert to BPM
float convert_to_bpm(int raw_value) {
    return (float)raw_value * BPM_SCALE_FACTOR;
}

// Apply moving average filter
float apply_moving_average(MovingAverageFilter *filter, float new_value) {
    filter->values[filter->index] = new_value;
    filter->index = (filter->index + 1) % MOVING_AVG_SIZE;
    if (filter->count < MOVING_AVG_SIZE) {
        filter->count++;
    }

    float sum = 0.0;
    for (int i = 0; i < filter->count; i++) {
        sum += filter->values[i];
    }

    return sum / filter->count;
}

// Validate BPM
int validate_bpm(float bpm) {
    return (bpm >= MIN_BPM && bpm <= MAX_BPM);
}

// Log data
int log_data(float bpm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f\n", timestamp, bpm);
    fflush(log_file);

    printf("%s,%.2f\n", timestamp, bpm);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int raw_heart_rate, retry_count;
    float bpm, filtered_bpm;
    MovingAverageFilter bpm_filter = {{0.0}, 0, 0};

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Verify sensor
    if (verify_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (program_running) {
        retry_count = 0;
        do {
            raw_heart_rate = read_heart_rate();
            if (raw_heart_rate < 0) {
                fprintf(stderr, "Retrying I2C read... (%d/%d)\n", retry_count + 1, 3);
                gpioDelay(1000); // Wait 1 second before retrying
                retry_count++;
            } else {
                break; // Exit retry loop if read is successful
            }
        } while (retry_count < 3 && program_running);

        if (raw_heart_rate >= 0) {
            bpm = convert_to_bpm(raw_heart_rate);
            filtered_bpm = apply_moving_average(&bpm_filter, bpm);

            if (validate_bpm(filtered_bpm)) {
                log_data(filtered_bpm);
            } else {
                fprintf(stderr, "Invalid BPM: %.2f\n", filtered_bpm);
            }
        } else {
            fprintf(stderr, "Failed to read heart rate after multiple retries\n");
        }

        gpioDelay(1000); // Read every 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

