#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO chip and line numbers
#define GPIOCHIP "gpiochip0"
#define NUM_CHANNELS 8
#define NUM_OUTPUTS 8
#define NUM_COUNTER_BITS 8

// Define GPIO line numbers for sensor inputs
const int sensor_lines[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};

// Define GPIO line numbers for output bits
const int output_lines[NUM_OUTPUTS] = {17, 18, 19, 20, 21, 22, 23, 24};

// Global variables
struct gpiod_chip *chip = NULL;
struct gpiod_line *sensor_gpios[NUM_CHANNELS] = {NULL};
struct gpiod_line *output_gpios[NUM_OUTPUTS] = {NULL};
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(void);
int read_sensor_data(int *sensor_values);
int update_outputs(int counter);
int log_touch_event(int channel, int counter);
void signal_handler(int sig);
int cleanup(void);

// Structure to hold GPIO line information
struct gpio_line {
    int number;
    struct gpiod_line *line;
};

// Function to initialize a GPIO line
int initialize_gpio_line(struct gpio_line *line, const char *chipname, int linenumber, int direction)
{
    line->line = gpiod_chip_get_line(chip, linenumber);
    if (!line->line) {
        fprintf(stderr, "Error getting line %d from chip %s: %s\n", linenumber, chipname, strerror(errno));
        return -1;
    }

    int ret = gpiod_line_request_output(line->line, "touch_counter", direction);
    if (ret < 0) {
        fprintf(stderr, "Error requesting line %d as output: %s\n", linenumber, strerror(errno));
        gpiod_line_release(line->line);
        return -1;
    }

    return 0;
}

// Function to initialize GPIO lines
int initialize_gpio(void)
{
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    // Initialize sensor GPIOs as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_gpios[i] = gpiod_chip_get_line(chip, sensor_lines[i]);
        if (!sensor_gpios[i]) {
            fprintf(stderr, "Error getting sensor line %d: %s\n", sensor_lines[i], strerror(errno));
            cleanup();
            return -1;
        }

        int ret = gpiod_line_request_input(sensor_gpios[i], "touch_counter");
        if (ret < 0) {
            fprintf(stderr, "Error requesting sensor line %d as input: %s\n", sensor_lines[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    // Initialize output GPIOs as outputs
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        output_gpios[i] = gpiod_chip_get_line(chip, output_lines[i]);
        if (!output_gpios[i]) {
            fprintf(stderr, "Error getting output line %d: %s\n", output_lines[i], strerror(errno));
            cleanup();
            return -1;
        }

        int ret = gpiod_line_request_output(output_gpios[i], "touch_counter", 0); // Initially LOW
        if (ret < 0) {
            fprintf(stderr, "Error requesting output line %d as output: %s\n", output_lines[i], strerror(errno));
            cleanup();
            return -1;
        }
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(int *sensor_values)
{
    for (int i = 0; i < NUM_CHANNELS; i++) {
        int value = gpiod_line_get_value(sensor_gpios[i]);
        if (value < 0) {
            fprintf(stderr, "Error reading sensor value for channel %d: %s\n", i + 1, strerror(errno));
            return -1; // Indicate error
        }
        sensor_values[i] = value;
    }
    return 0;
}

// Function to update output GPIOs based on the counter value
int update_outputs(int counter)
{
    for (int i = 0; i < NUM_COUNTER_BITS; i++) {
        int bit = (counter >> i) & 1;
        int line_number = output_lines[i];
        struct gpiod_line *line = gpiod_chip_get_line(chip, line_number);
        if (!line) {
            fprintf(stderr, "Error getting output line %d: %s\n", line_number, strerror(errno));
            return -1;
        }

        int ret = gpiod_line_set_value(line, bit);
        if (ret < 0) {
            fprintf(stderr, "Error setting output line %d to %d: %s\n", line_number, bit, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to log touch events
int log_touch_event(int channel, int counter)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout only.\n");
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Cleanup function to release resources
int cleanup(void)
{
    // Reset output pins
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output_gpios[i]) {
            gpiod_line_set_value(output_gpios[i], 0);
            gpiod_line_release(output_gpios[i]);
        }
    }

    // Release sensor lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_gpios[i]) {
            gpiod_line_release(sensor_gpios[i]);
        }
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

int main(void)
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    struct timespec delay = {0, 200000000}; // 200 ms
    nanosleep(&delay, NULL);

    int sensor_values[NUM_CHANNELS];
    int counter = 0;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_values) < 0) {
            fprintf(stderr, "Error reading sensor data. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Process sensor data
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (sensor_values[i] == 1) { // Touch detected
                counter++;
                if (counter > 255) {
                    counter = 0;
                }
                update_outputs(counter);
                log_touch_event(i + 1, counter);
                // Debounce delay
                struct timespec debounce_delay = {0, 200000000}; // 200 ms
                nanosleep(&debounce_delay, NULL);
            }
        }

        // Delay before next iteration
        struct timespec loop_delay = {0, 10000000}; // 10 ms
        nanosleep(&loop_delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

