        int line_number = output_lines[i];
        struct gpiod_line *line = gpiod_chip_get_line(chip, line_number);
        if (!line) {
            fprintf(stderr, "Error getting output line %d: %s\n", line_number, strerror(errno));
            return -1;
        }

        int ret = gpiod_line_set_value(line, bit);
        if (ret < 0) {
            fprintf(stderr, "Error setting output line %d to %d: %s\n", line_number, bit, strerror(errno));
            return -1;
        }
    }
    return 0;
}

// Function to log touch events
int log_touch_event(int channel, int counter)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Warning: Could not open log file. Logging to stdout only.\n");
        printf("%s, Channel: %d, Counter: %d\n", timestamp, channel, counter);
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", sig);
}

// Cleanup function to release resources
int cleanup(void)
{
    // Reset output pins
    for (int i = 0; i < NUM_OUTPUTS; i++) {
        if (output_gpios[i]) {
            gpiod_line_set_value(output_gpios[i], 0);
            gpiod_line_release(output_gpios[i]);
        }
    }

    // Release sensor lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (sensor_gpios[i]) {
            gpiod_line_release(sensor_gpios[i]);
        }
    }

    // Close log file
    if (log_file) {
        fclose(log_file);
    }

    // Close chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    return 0;
}

int main(void)
{
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Open log file
    log_file = fopen("touch_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
    }

    // Stabilization delay
    struct timespec delay = {0, 200000000}; // 200 ms
    nanosleep(&delay, NULL);

    int sensor_values[NUM_CHANNELS];
    int counter = 0;

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_sensor_data(sensor_values) < 0) {
            fprintf(stderr, "Error reading sensor data. Continuing.\n");
            continue; // Continue to the next iteration
        }

        // Process sensor data
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (sensor_values[i] == 1) { // Touch detected
                counter++;
                if (counter > 255) {
                    counter = 0;
                }
                update_outputs(counter);
                log_touch_event(i + 1, counter);
                // Debounce delay
                struct timespec debounce_delay = {0, 200000000}; // 200 ms
                nanosleep(&debounce_delay, NULL);
            }
        }

        // Delay before next iteration
        struct timespec loop_delay = {0, 10000000}; // 10 ms
        nanosleep(&loop_delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

