    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate error
    }
    return value;
}

// Function to calculate LED state
int calculate_led_state(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
}

// Function to log data to file
int log_data(FILE *fp, int sensor1_value, int sensor2_value, int led_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, sensor1_value, sensor2_value, led_state) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }
    fflush(fp); // Flush the buffer to ensure data is written to the file
    return 0;
}

