        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Obstacle detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values, exiting...\n");
            break;
        }

        int led_state = calculate_led_state(sensor1_value, sensor2_value);
        gpioWrite(LED_PIN, led_state);

        if (log_data(log_file, sensor1_value, sensor2_value, led_state) != 0) {
            fprintf(stderr, "Error logging data, exiting...\n");
            break;
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Cleanup
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate(); // Terminate pigpio
    fclose(log_file); // Close log file

    printf("Obstacle detection stopped.\n");

    return 0;
}

