#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling rate (8 kHz)
#define SAMPLE_PERIOD_US 125

// Define LED on time (100 ms)
#define LED_ON_TIME_MS 100

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        program_running = 0;
        fprintf(stderr, "\nCaught SIGINT, exiting gracefully...\n");
    }
}

// Function to read the microphone input
int read_microphone() {
    return gpioRead(MIC_PIN);
}

// Function to trigger the LED
void trigger_led() {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(LED_ON_TIME_MS * 1000); // Delay for 100 ms
    gpioWrite(LED_PIN, 0); // Turn LED off
}

// Function to get the current timestamp in milliseconds
long long get_timestamp_ms() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return (long long)(ts.tv_sec * 1000LL + ts.tv_nsec / 1000000LL);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    if (gpioSetMode(MIC_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", MIC_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Read microphone input
        int mic_value = read_microphone();

        // Check for HIGH reading
        if (mic_value == 1) {
            // Get timestamp
            long long timestamp = get_timestamp_ms();

            // Print timestamp to stdout
            printf("%lld\n", timestamp);

            // Trigger LED
            trigger_led();
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
    return 0;
}

