#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN 22

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void sigint_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGINT received, exiting gracefully...\n");
}

// Signal handler for SIGTERM
void sigterm_handler(int signal)
{
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nSIGTERM received, exiting gracefully...\n");
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin)
{
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

int main()
{
    // Register signal handlers for graceful shutdown
    signal(SIGINT, sigint_handler);
    signal(SIGTERM, sigterm_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-up resistors
    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", LEFT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", CENTER_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(CENTER_SENSOR_PIN, PI_PUD_UP);

    if (gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", RIGHT_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    // Main loop to read and log sensor values
    while (program_running) {
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int center_value = read_sensor(CENTER_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        if (left_value != -1 && center_value != -1 && right_value != -1) {
            printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);
        } else {
            fprintf(stderr, "Error reading sensor values\n");
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();
    fprintf(stderr, "pigpio terminated.\n");

    return 0;
}

