#include <stdio.h>
#include <stdlib.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// Define the I2C bus and Si1175 address
#define I2C_BUS "/dev/i2c-1"
#define SI1175_ADDR 0x49

// Define the ALS visible data registers
#define ALS_VIS_LSB_REG 0x24
#define ALS_VIS_MSB_REG 0x25

// Global variable to store the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a 16-bit value from the Si1175 sensor
int read_sensor_data(int fd, unsigned char lsb_reg, unsigned char msb_reg) {
    unsigned char lsb, msb;
    int ret;

    // Read the LSB
    ret = i2c_smbus_read_byte_data(fd, lsb_reg);
    if (ret < 0) {
        perror("Error reading LSB");
        return -1;
    }
    lsb = (unsigned char)ret;

    // Read the MSB
    ret = i2c_smbus_read_byte_data(fd, msb_reg);
    if (ret < 0) {
        perror("Error reading MSB");
        return -1;
    }
    msb = (unsigned char)ret;

    // Combine the LSB and MSB into a 16-bit value
    return ((int)msb << 8) | lsb;
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, SI1175_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Main loop to read and log sensor data
    while (1) {
        int sensor_value = read_sensor_data(i2c_fd, ALS_VIS_LSB_REG, ALS_VIS_MSB_REG);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying in 100ms.\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Log the sensor value to the console
        printf("Sensor Value: %d\n", sensor_value);

        // Wait for 100 milliseconds
        usleep(100000);
    }

    // The program should never reach here due to the infinite loop,
    // but include cleanup code for completeness.
    close(i2c_fd);
    return 0;
}

