#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the number of channels
#define NUM_CHANNELS 8

// Define the GPIO pins for each channel
const int GPIO_PINS[NUM_CHANNELS] = {5, 6, 13, 19, 26, 12, 16, 20};

// Global variables for GPIO chip and lines
struct gpiod_chip *chip = NULL;
struct gpiod_line *lines[NUM_CHANNELS] = {NULL};

// Signal handler for graceful shutdown
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release all GPIO lines
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }

    // Close the GPIO chip
    if (chip != NULL) {
        gpiod_chip_close(chip);
        chip = NULL;
    }

    exit(0);
}

int main()
{
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return 1;
    }

    // Get the number of lines on the chip
    int num_lines = gpiod_chip_num_lines(chip);
    if (num_lines < 0) {
        fprintf(stderr, "Error getting number of lines: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request all GPIO lines as inputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, GPIO_PINS[i]);
        if (!lines[i]) {
            fprintf(stderr, "Error getting line %d: %s\n", GPIO_PINS[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j < i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                    lines[j] = NULL;
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        if (gpiod_line_request_input(lines[i], "touch_sensor") < 0) {
            fprintf(stderr, "Error requesting line %d as input: %s\n", GPIO_PINS[i], strerror(errno));
            // Release previously acquired lines
            for (int j = 0; j <= i; j++) {
                if (lines[j] != NULL) {
                    gpiod_line_release(lines[j]);
                    lines[j] = NULL;
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }
    }

    // Main loop to read and log sensor data
    while (1) {
        // Get the current time
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            fprintf(stderr, "Error getting time: %s\n", strerror(errno));
            // Release all lines and close chip before exiting
            for (int i = 0; i < NUM_CHANNELS; i++) {
                if (lines[i] != NULL) {
                    gpiod_line_release(lines[i]);
                    lines[i] = NULL;
                }
            }
            gpiod_chip_close(chip);
            return 1;
        }

        // Read the state of each channel
        char log_string[100];
        snprintf(log_string, sizeof(log_string), "[%.3fs] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
                 ts.tv_sec + ts.tv_nsec / 1000000000.0,
                 gpiod_line_get_value(lines[0]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[1]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[2]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[3]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[4]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[5]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[6]) == 1 ? 1 : 0,
                 gpiod_line_get_value(lines[7]) == 1 ? 1 : 0);

        // Print the log string to the console
        printf("%s\n", log_string);

        // Wait for 200 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 200000000; // 200 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

