#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <syslog.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define I2C address for BH1750 light sensor
#define BH1750_ADDR 0x23

// Define I2C bus
#define I2C_BUS "/dev/i2c-1"

// Global variables
int i2c_fd;
int running = 1;

// Function prototypes
int init_i2c();
int read_light_level();
void generate_random_hue(float *hue);
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b);
void set_led_color(int r, int g, int b);
void fade_to_color(int r, int g, int b, int steps);
void signal_handler(int signal);

// Function to initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire bus access and/or talk to slave");
        close(i2c_fd);
        return -1;
    }

    // Configure BH1750 for continuous high-resolution mode
    unsigned char config_cmd[1] = {0x10}; // Continuous H-resolution mode
    if (write(i2c_fd, config_cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read light level from BH1750 sensor
int read_light_level() {
    unsigned char data[2];
    int lux = -1;

    // Read 2 bytes from the sensor
    if (read(i2c_fd, data, 2) == 2) {
        lux = (data[0] << 8 | data[1]) / 1.2; // Convert raw data to lux
    } else {
        syslog(LOG_ERR, "Failed to read from I2C device");
        return -1;
    }

    return lux;
}

// Function to generate a random hue value
void generate_random_hue(float *hue) {
    // Seed the random number generator with /dev/urandom
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        *hue = 0.0; // Default to a specific hue if random seeding fails
        return;
    }

    unsigned char random_bytes[4];
    if (read(fd, random_bytes, 4) != 4) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        close(fd);
        *hue = 0.0; // Default to a specific hue if random seeding fails
        return;
    }
    close(fd);

    // Convert the random bytes to a float (hue)
    unsigned int random_value = (random_bytes[0] << 24) | (random_bytes[1] << 16) | (random_bytes[2] << 8) | random_bytes[3];
    *hue = (float)random_value / (float)UINT_MAX; // Normalize to 0.0 - 1.0
}

// Function to convert HSV color space to RGB
void hsv_to_rgb(float h, float s, float v, int *r, int *g, int *b) {
    if (s == 0.0) {
        // Achromatic (gray)
        *r = *g = *b = (int)(v * 255);
        return;
    }

    h = fmodf(h, 1.0); // Ensure h is within 0-1
    float h60 = h * 6.0;
    int i = (int)h60;
    float f = h60 - i;
    float p = v * (1.0 - s);
    float q = v * (1.0 - s * f);
    float t = v * (1.0 - s * (1.0 - f));

    switch (i) {
        case 0:
            *r = (int)(v * 255);
            *g = (int)(t * 255);
            *b = (int)(p * 255);
            break;
        case 1:
            *r = (int)(q * 255);
            *g = (int)(v * 255);
            *b = (int)(p * 255);
            break;
        case 2:
            *r = (int)(p * 255);
            *g = (int)(v * 255);
            *b = (int)(t * 255);
            break;
        case 3:
            *r = (int)(p * 255);
            *g = (int)(q * 255);
            *b = (int)(v * 255);
            break;
        case 4:
            *r = (int)(t * 255);
            *g = (int)(p * 255);
            *b = (int)(v * 255);
            break;
        default: // case 5:
            *r = (int)(v * 255);
            *g = (int)(p * 255);
            *b = (int)(q * 255);
            break;
    }
}

// Function to set the RGB LED color using PWM
void set_led_color(int r, int g, int b) {
    gpioPWM(RED_PIN, 255 - r);   // Common anode, so invert the value
    gpioPWM(GREEN_PIN, 255 - g); // Common anode, so invert the value
    gpioPWM(BLUE_PIN, 255 - b);  // Common anode, so invert the value
}

// Function to fade to a specific color over a number of steps
void fade_to_color(int r, int g, int b, int steps) {
    int current_r = gpioGetPWMdutycycle(RED_PIN);
    int current_g = gpioGetPWMdutycycle(GREEN_PIN);
    int current_b = gpioGetPWMdutycycle(BLUE_PIN);

    int r_diff = r - current_r;
    int g_diff = g - current_g;
    int b_diff = b - current_b;

    float r_step = (float)r_diff / steps;
    float g_step = (float)g_diff / steps;
    float b_step = (float)b_diff / steps;

    for (int i = 0; i < steps; i++) {
        current_r += r_step;
        current_g += g_step;
        current_b += b_step;

        set_led_color((int)current_r, (int)current_g, (int)current_b);
        gpioDelay(10000); // 10ms delay (100Hz)
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Received signal %d, shutting down...", signal);
    running = 0;

    // Turn off the LED
    set_led_color(0, 0, 0);

    // Release pigpio resources
    gpioTerminate();

    // Close I2C bus
    close(i2c_fd);

    // Close syslog
    closelog();

    exit(0);
}

int main() {
    // Initialize syslog
    openlog("mood_lamp", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency to 1000 Hz
    gpioSetPWMfrequency(RED_PIN, 1000);
    gpioSetPWMfrequency(GREEN_PIN, 1000);
    gpioSetPWMfrequency(BLUE_PIN, 1000);

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        closelog();
        return 1;
    }

    float hue;
    int r, g, b;
    int light_level;

    while (running) {
        // Generate a random hue
        generate_random_hue(&hue);

        // Convert hue to RGB
        hsv_to_rgb(hue, 1.0, 1.0, &r, &g, &b);

        // Read light level
        light_level = read_light_level();
        if (light_level < 0) {
            syslog(LOG_ERR, "Failed to read light level, using default brightness");
            light_level = 1000; // Default light level
        }

        // Adjust brightness based on light level (example: reduce brightness if light is low)
        float brightness = (float)light_level / 1000.0; // Normalize light level to 0.0 - 1.0
        if (brightness < 0.2) {
            brightness = 0.2; // Limit minimum brightness
        }

        r = (int)(r * brightness * 255.0);
