            light_level = 1000; // Default light level
        }

        // Adjust brightness based on light level (example: reduce brightness if light is low)
        float brightness = (float)light_level / 1000.0; // Normalize light level to 0.0 - 1.0
        if (brightness < 0.2) {
            brightness = 0.2; // Limit minimum brightness
        }

        r = (int)(r * brightness * 255.0);
        g = (int)(g * brightness * 255.0);
        b = (int)(b * brightness * 255.0);

        // Fade to the new color
        fade_to_color(r, g, b, 50); // 50 steps for a 5-second fade

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup (should not reach here if signal handler is working)
    set_led_color(0, 0, 0);
    gpioTerminate();
    close(i2c_fd);
    closelog();

    return 0;
}

