#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_COMMAND_BIT 0x80
#define TCS34725_ENABLE 0x00
#define TCS34725_ATIME 0x01
#define TCS34725_CONTROL 0x0F
#define TCS34725_ID 0x12
#define TCS34725_CDATA 0x14
#define TCS34725_RDATA 0x16
#define TCS34725_GDATA 0x18
#define TCS34725_BDATA 0x1A

// GPIO Pin for LED
#define LED_PIN 17

// Red Threshold
#define RED_THRESHOLD 200

// Global Variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function Prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int tcs34725_init(int fd);
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue);
void tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, uint16_t *calibrated_red, uint16_t *calibrated_green, uint16_t *calibrated_blue, uint16_t *calibrated_clear);
void gpio_control(int fd, int value);
void signal_handler(int sig);

// I2C Read Byte Function
int i2c_read_byte(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return result;
}

// I2C Write Byte Function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg | TCS34725_COMMAND_BIT, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// TCS34725 Initialization Function
int tcs34725_init(int fd) {
    // Enable power and RGBC
    if (i2c_write_byte(fd, TCS34725_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error enabling TCS34725\n");
        return -1;
    }

    // Set integration time (ATIME)
    if (i2c_write_byte(fd, TCS34725_ATIME, 0x00) < 0) {
        fprintf(stderr, "Error setting integration time\n");
        return -1;
    }

    // Set gain (CONTROL)
    if (i2c_write_byte(fd, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error setting gain\n");
        return -1;
    }

    // Verify sensor ID
    int sensor_id = i2c_read_byte(fd, TCS34725_ID);
    if (sensor_id < 0 || sensor_id != 0x44) {
        fprintf(stderr, "Error verifying sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    return 0;
}

// TCS34725 Read Raw Data Function
int tcs34725_read_raw_data(int fd, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    int c, r, g, b;

    c = i2c_read_byte(fd, TCS34725_CDATA);
    if (c < 0) return -1;
    c |= i2c_read_byte(fd, TCS34725_CDATA + 1) << 8;

    r = i2c_read_byte(fd, TCS34725_RDATA);
    if (r < 0) return -1;
    r |= i2c_read_byte(fd, TCS34725_RDATA + 1) << 8;

    g = i2c_read_byte(fd, TCS34725_GDATA);
    if (g < 0) return -1;
    g |= i2c_read_byte(fd, TCS34725_GDATA + 1) << 8;

    b = i2c_read_byte(fd, TCS34725_BDATA);
    if (b < 0) return -1;
    b |= i2c_read_byte(fd, TCS34725_BDATA + 1) << 8;

    *clear = (uint16_t)c;
    *red = (uint16_t)r;
    *green = (uint16_t)g;
    *blue = (uint16_t)b;

    return 0;
}

// TCS34725 Calibrate Data Function
void tcs34725_calibrate_data(uint16_t clear, uint16_t red, uint16_t green, uint16_t blue, uint16_t *calibrated_red, uint16_t *calibrated_green, uint16_t *calibrated_blue, uint16_t *calibrated_clear) {
    // Simple calibration (adjust gain and offset as needed)
    *calibrated_red = red;
    *calibrated_green = green;
    *calibrated_blue = blue;
    *calibrated_clear = clear;
}

// GPIO Control Function
void gpio_control(int fd, int value) {
    int ret = gpiod_line_set_value(led_line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO value: %s\n", strerror(errno));
    }
}

// Signal Handler Function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize TCS34725 sensor
    if (tcs34725_init(i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed. Attempting re-initialization...\n");
        close(i2c_fd);
        i2c_fd = open("/dev/i2c-1", O_RDWR);
        if (i2c_fd < 0) {
            fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
            return 1;
        }
        if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
            fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
            close(i2c_fd);
            return 1;
        }
        if (tcs34725_init(i2c_fd) < 0) {
            fprintf(stderr, "TCS34725 re-initialization failed.\n");
            close(i2c_fd);
            return 1;
        }
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "tcs34725_led";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    if (gpiod_line_request(led_line, &config, 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    uint16_t clear, red, green, blue;
    uint16_t calibrated_clear, calibrated_red, calibrated_green, calibrated_blue;

    // Main loop
    while (!terminate) {
        // Read raw data from TCS34725
        if (tcs34725_read_raw_data(i2c_fd, &clear, &red, &green, &blue) == 0) {
            // Calibrate the data
            tcs34725_calibrate_data(clear, red, green, blue, &calibrated_red, &calibrated_green, &calibrated_blue, &calibrated_clear);

            // Display calibrated RGB and clear values
            printf("C: %u, R: %u, G: %u, B: %u\n", calibrated_clear, calibrated_red, calibrated_green, calibrated_blue);

            // Control LED based on red value
            if (calibrated_red > RED_THRESHOLD) {
                gpio_control(i2c_fd, 1); // HIGH
            } else {
                gpio_control(i2c_fd, 0); // LOW
            }
        } else {
            fprintf(stderr, "Error reading sensor data. Attempting re-initialization...\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
                break;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
                fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
                close(i2c_fd);
                break;
            }
            if (tcs34725_init(i2c_fd) < 0) {
                fprintf(stderr, "TCS34725 re-initialization failed.\n");
                close(i2c_fd);
                break;
            }
        }

        // Wait 200 ms
        usleep(200000);
    }

    // Cleanup
    gpiod_line_release(led_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);

    return 0;
}

