#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define LED_COUNT 10
#define GPIO_PIN 18
#define BH1750_ADDR 0x23
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x10
#define I2C_BUS 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
void signal_handler(int signal);
int initialize_pigpio();
int initialize_i2c();
int read_bh1750(float *lux);
float map_lux_to_brightness(float lux);
void set_led_brightness(float brightness);
void cleanup();

// WS2812B timing constants (in microseconds)
#define T0H 0.35  // 0.35us
#define T0L 0.8  // 0.8us
#define T1H 0.7  // 0.7us
#define T1L 1.4  // 1.4us

// Structure to hold RGB color values
typedef struct {
    uint8_t r;
    uint8_t g;
    uint8_t b;
} RGB;

// Function to set the RGB color of a single LED
void set_led_color(int led_index, RGB color) {
    // This is a placeholder.  In a real application, you would
    // send the color data to the WS2812B strip via SPI or I2C.
    // For this example, we'll just print the color values.
    printf("LED %d: R=%d, G=%d, B=%d\n", led_index, color.r, color.g, color.b);
}

// Function to set the brightness of all LEDs
void set_led_brightness(float brightness) {
    // Map brightness to RGB values (assuming a single color for simplicity)
    RGB color;
    color.r = (uint8_t)(brightness * 255);
    color.g = (uint8_t)(brightness * 255);
    color.b = (uint8_t)(brightness * 255);

    // Set the color of each LED
    for (int i = 0; i < LED_COUNT; i++) {
        set_led_color(i, color);
    }
}

// Function to map lux value to brightness (logarithmic mapping)
float map_lux_to_brightness(float lux) {
    // Clamp lux value to a reasonable range
    if (lux < 0) lux = 0;
    if (lux > 1000) lux = 1000;

    // Use a logarithmic mapping for non-linear brightness control
    float brightness = log10(lux + 1) / log10(1001); // Maps 0-1000 lux to 0-1

    // Ensure brightness is within the valid range
    if (brightness < 0) brightness = 0;
    if (brightness > 1) brightness = 1;

    return brightness;
}

// Function to read light level from BH1750 sensor
int read_bh1750(float *lux) {
    int retries = 0;
    int status;
    uint8_t buffer[2];

    while (retries < MAX_RETRIES) {
        // Send command to start continuous high-resolution mode
        status = i2cWriteByteData(i2c_handle, 0x00, BH1750_CONTINUOUS_HIGH_RES_MODE);
        if (status != 0) {
            fprintf(stderr, "Error writing to I2C device: %d\n", status);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Wait for measurement (at least 180ms)
        gpioDelay(180000); // 180ms

        // Read 2 bytes of data
        status = i2cReadI2CBlockData(i2c_handle, 0x00, (char *)buffer, 2);
        if (status != 2) {
            fprintf(stderr, "Error reading from I2C device: %d\n", status);
            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            continue;
        }

        // Combine bytes to get lux value
        *lux = (float)((buffer[0] << 8) | buffer[1]) / 1.2;
        return 0; // Success
    }

    fprintf(stderr, "Failed to read BH1750 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    set_led_brightness(0.0); // Turn off LEDs
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    float lux;
    float brightness;

    printf("Starting light-controlled LED strip...\n");

    while (!terminate) {
        // Read light level from BH1750 sensor
        if (read_bh1750(&lux) == 0) {
            // Map lux value to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            set_led_brightness(brightness);

            printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);
        } else {
            fprintf(stderr, "Failed to read light level.\n");
        }

        gpioDelay(100000); // Delay for 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

