// Global variables
int i2c_fd = -1;
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int spi_setup(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed);
int bh1750_init(int fd);
int bh1750_read_lux(int fd);
float map_lux_to_brightness(float lux);
int apa102_send_frame(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red);
int apa102_send_start_frame(int fd);
int apa102_send_end_frame(int fd);
void signal_handler(int sig);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI setup function
int spi_setup(const char *device, uint8_t mode, uint8_t bits_per_word, uint32_t speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode_8 = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_8) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    uint8_t bits_8 = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_8) < 0) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    uint32_t speed_32 = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_32) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

// BH1750 initialization function
int bh1750_init(int fd) {
    uint8_t mode = BH1750_CONTINUOUS_HIGH_RES_MODE;
    if (write(fd, &mode, 1) != 1) {
        perror("Error writing to BH1750");
        return -1;
    }
    return 0;
}

// BH1750 read lux function
int bh1750_read_lux(int fd) {
    uint8_t buffer[2];
    if (read(fd, buffer, 2) != 2) {
        perror("Error reading from BH1750");
        return -1;
    }

    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    return raw_value;
}

// Map lux to brightness function
float map_lux_to_brightness(float lux) {
    float brightness = (lux - 10.0) / (300.0 - 10.0) * 31.0;
    if (brightness < 0.0) {
        brightness = 0.0;
    }
    if (brightness > 31.0) {
        brightness = 31.0;
    }
    return brightness;
}

// APA102 send frame function
int apa102_send_frame(int fd, uint8_t brightness, uint8_t blue, uint8_t green, uint8_t red) {
    uint8_t data[4];
    data[0] = 0xE0 | brightness;
    data[1] = blue;
    data[2] = green;
    data[3] = red;

    uint8_t tx_buf[4];
    tx_buf[0] = data[0];
    tx_buf[1] = data[1];
    tx_buf[2] = data[2];
    tx_buf[3] = data[3];

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)NULL, // Not using receive
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    return 0;
}

// APA102 send start frame function
int apa102_send_start_frame(int fd) {
    uint8_t start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)start_frame,
        .rx_buf = (unsigned long)NULL, // Not using receive
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending start frame");
        return -1;
    }
    return 0;
}

// APA102 send end frame function
int apa102_send_end_frame(int fd) {
    uint8_t end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)end_frame,
        .rx_buf = (unsigned long)NULL, // Not using receive
        .len = 4,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending end frame");
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed, exiting.\n");
        return 1;
    }

    // Initialize SPI
    spi_fd = spi_setup(SPI_DEVICE, 0, 8, SPI_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI setup failed, exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize BH1750
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 initialization failed, exiting.\n");
        close(i2c_fd);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read lux value
        int raw_lux = bh1750_read_lux(i2c_fd);
        if (raw_lux < 0) {
            fprintf(stderr, "Error reading lux value, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Convert to lux
        float lux = (float)raw_lux / 1.2;

        // Map lux to brightness
        float brightness = map_lux_to_brightness(lux);

        // Send start frame
        if (apa102_send_start_frame(spi_fd) < 0) {
            fprintf(stderr, "Error sending start frame, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Send LED frames
        for (int i = 0; i < NUM_LEDS; i++) {
            if (apa102_send_frame(spi_fd, (uint8_t)brightness, 0xFF, 0x00, 0x00) < 0) {
                fprintf(stderr, "Error sending LED frame %d, retrying...\n", i);
                usleep(100000); // Wait 100ms before retrying
                continue;
            }
        }

        // Send end frame
        if (apa102_send_end_frame(spi_fd) < 0) {
            fprintf(stderr, "Error sending end frame, retrying...\n");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        // Print lux value
        printf("Lux: %.2f, Brightness: %.2f\n", lux, brightness);

        // Wait 100ms
        usleep(100000);
    }

    // Turn off LEDs
    apa102_send_start_frame(spi_fd);
    for (int i = 0; i < NUM_LEDS; i++) {
        apa102_send_frame(spi_fd, 0, 0, 0, 0);
    }
    apa102_send_end_frame(spi_fd);

    // Close file descriptors
    close(i2c_fd);
    close(spi_fd);

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

