#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR_LOW 0x23
#define BH1750_ADDR_HIGH 0x5C
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define NUM_LEDS 10       // Number of LEDs in the strip
#define MAX_LUX 1000.0    // Maximum expected lux value
#define MIN_LUX 0.0       // Minimum expected lux value
#define MAX_BRIGHTNESS 31 // Maximum brightness level
#define MIN_BRIGHTNESS 0  // Minimum brightness level
#define BRIGHTNESS_STEP 1 // Brightness step size for fading
#define DELAY_MS 100      // Delay between brightness changes (ms)

// Global variables
int i2c_handle_low = -1;
int i2c_handle_high = -1;
int spi_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c(int bus, int addr);
int init_spi(int channel, int baud);
int read_bh1750(int i2c_handle);
float average_lux(float lux1, float lux2, float lux3);
int map_lux_to_brightness(float average_lux);
int set_apa102_brightness(int spi_handle, int brightness);
void fade_brightness(int spi_handle, int target_brightness);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C
int init_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Initialize SPI
int init_spi(int channel, int baud) {
    int handle = spiOpen(channel, baud, 0); // SPI_MODE_0
    if (handle < 0) {
        fprintf(stderr, "Error opening SPI channel %d: %d\n", channel, handle);
        return -1;
    }
    return handle;
}

// Read lux value from BH1750 sensor
int read_bh1750(int i2c_handle) {
    if (i2c_handle < 0) {
        return -1; // Sensor not initialized
    }

    char config[1] = {0x21}; // One-Time High-Resolution Mode 2
    if (i2cWriteDevice(i2c_handle, config, 1) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", i2c_handle);
        return -1;
    }

    gpioDelay(180); // Wait for conversion (at least 180 ms)

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", i2c_handle);
        return -1;
    }

    unsigned int raw_value = (data[0] << 8) | data[1];
    float lux = (float)raw_value / 1.2; // Convert to lux

    return (int)lux;
}

// Average lux readings
float average_lux(float lux1, float lux2, float lux3) {
    float sum = 0.0;
    int count = 0;

    if (lux1 >= 0) {
        sum += lux1;
        count++;
    }
    if (lux2 >= 0) {
        sum += lux2;
        count++;
    }
    if (lux3 >= 0) {
        sum += lux3;
        count++;
    }

    if (count == 0) {
        return -1.0; // No valid readings
    }

    return sum / count;
}

// Map lux value to brightness level
int map_lux_to_brightness(float average_lux) {
    if (average_lux < 0) {
        return MAX_BRIGHTNESS; // Max brightness if no valid readings
    }

    if (average_lux > MAX_LUX) {
        average_lux = MAX_LUX;
    }

    if (average_lux < MIN_LUX) {
        average_lux = MIN_LUX;
    }

    // Linear mapping
    return MAX_BRIGHTNESS - (int)((average_lux - MIN_LUX) / (MAX_LUX - MIN_LUX) * (MAX_BRIGHTNESS + 1));
}

// Set APA102 strip brightness
int set_apa102_brightness(int spi_handle, int brightness) {
    if (spi_handle < 0) {
        fprintf(stderr, "SPI handle is invalid.\n");
        return -1;
    }

    // APA102 start frame (4 bytes of 0x00)
    char start_frame[4] = {0x00, 0x00, 0x00, 0x00};
    if (spiWrite(spi_handle, start_frame, 4) != 4) {
        fprintf(stderr, "Error writing start frame to SPI.\n");
        return -1;
    }

    // LED data (RGB + brightness for each LED)
    for (int i = 0; i < NUM_LEDS; i++) {
        // Set LED color to white (255, 255, 255)
        char led_data[4] = {0xFF, 0xFF, 0xFF, (char)brightness};
        if (spiWrite(spi_handle, led_data, 4) != 4) {
            fprintf(stderr, "Error writing LED data to SPI.\n");
            return -1;
        }
    }

    // APA102 end frame (4 bytes of 0xFF)
    char end_frame[4] = {0xFF, 0xFF, 0xFF, 0xFF};
    if (spiWrite(spi_handle, end_frame, 4) != 4) {
        fprintf(stderr, "Error writing end frame to SPI.\n");
        return -1;
    }

    return 0;
}

// Fade brightness smoothly
void fade_brightness(int spi_handle, int target_brightness) {
    int current_brightness = MAX_BRIGHTNESS; // Start from max brightness
    int direction = -1; // Decrease brightness
    if (target_brightness > current_brightness) {
        direction = 1; // Increase brightness
    }

    while (current_brightness != target_brightness) {
        current_brightness += direction * BRIGHTNESS_STEP;
        if (current_brightness > MAX_BRIGHTNESS) {
            current_brightness = MAX_BRIGHTNESS;
        } else if (current_brightness < 0) {
            current_brightness = 0;
        }

        if (set_apa102_brightness(spi_handle, current_brightness) != 0) {
            fprintf(stderr, "Error setting brightness during fade.\n");
            return;
        }

        gpioDelay(DELAY_MS); // Delay for smooth fading
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C sensors
    i2c_handle_low = init_i2c(I2C_BUS, BH1750_ADDR_LOW);
    i2c_handle_high = init_i2c(I2C_BUS, BH1750_ADDR_HIGH);

    // Initialize SPI
    spi_handle = init_spi(SPI_CHANNEL, SPI_BAUD);

    if (i2c_handle_low < 0 && i2c_handle_high < 0) {
        fprintf(stderr, "No I2C sensors found. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
        if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
        gpioTerminate();
        return 1;
    }

    printf("Ambient light control started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux values from sensors
        float lux1 = (i2c_handle_low >= 0) ? (float)read_bh1750(i2c_handle_low) : -1.0;
        float lux2 = (i2c_handle_high >= 0) ? (float)read_bh1750(i2c_handle_high) : -1.0;
        float lux3 = -1.0; // No third sensor in this example

        // Average lux readings
        float average_lux_value = average_lux(lux1, lux2, lux3);

        // Map lux to brightness
        int target_brightness = map_lux_to_brightness(average_lux_value);

        // Fade brightness
        fade_brightness(spi_handle, target_brightness);

        gpioDelay(100); // Delay between cycles
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (i2c_handle_low >= 0) i2cClose(i2c_handle_low);
    if (i2c_handle_high >= 0) i2cClose(i2c_handle_high);
    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

