#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN 17
#define LED_PIN 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *flame_line;
struct gpiod_line *buzzer_line;
struct gpiod_line *led_line;

// Function prototypes
int self_test();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void activate_led();
void deactivate_led();
void log_event(const char *event);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT) {
        printf("Caught SIGINT, exiting gracefully.\n");
        log_event("Program terminated by SIGINT.");

        // Deactivate buzzer and LED
        deactivate_buzzer();
        deactivate_led();

        // Release GPIO lines
        if (flame_line) {
            gpiod_line_release(flame_line);
        }
        if (buzzer_line) {
            gpiod_line_release(buzzer_line);
        }
        if (led_line) {
            gpiod_line_release(led_line);
        }

        // Close GPIO chip
        if (chip) {
            gpiod_chip_close(chip);
        }

        exit(0);
    }
}

// Self-test function
int self_test() {
    printf("Starting self-test...\n");

    // Blink LED twice
    for (int i = 0; i < 2; i++) {
        activate_led();
        usleep(500000); // 500 ms
        deactivate_led();
        usleep(500000); // 500 ms
    }

    // Read flame sensor 5 times
    int flame_detected_count = 0;
    for (int i = 0; i < 5; i++) {
        int value = read_flame_sensor();
        if (value == 0) {
            flame_detected_count++;
        }
        usleep(100000); // 100 ms
    }

    printf("Self-test results: Flame detected %d times out of 5.\n", flame_detected_count);

    if (flame_detected_count == 5) {
        printf("Self-test failed: Sensor always reads LOW.\n");
        // Error pattern: LED blinking rapidly (100 ms on/off) for 5 cycles, then buzzer sounding a short-short-long-short pattern (200 ms, 200 ms, 600 ms, 200 ms) repeated 3 times
        for (int i = 0; i < 5; i++) {
            activate_led();
            usleep(100000); // 100 ms
            deactivate_led();
            usleep(100000); // 100 ms
        }

        for (int i = 0; i < 3; i++) {
            activate_buzzer();
            usleep(200000); // 200 ms
            deactivate_buzzer();
            usleep(200000); // 200 ms
            activate_buzzer();
            usleep(600000); // 600 ms
            deactivate_buzzer();
            usleep(200000); // 200 ms
        }
        return 1; // Indicate failure
    } else {
        printf("Self-test passed.\n");
        return 0; // Indicate success
    }
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        log_event("Error reading flame sensor.");
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer() {
    int ret = gpiod_line_set_value(buzzer_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error activating buzzer: %s\n", strerror(errno));
        log_event("Error activating buzzer.");
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer() {
    int ret = gpiod_line_set_value(buzzer_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error deactivating buzzer: %s\n", strerror(errno));
        log_event("Error deactivating buzzer.");
    }
}

// Function to activate the LED
void activate_led() {
    int ret = gpiod_line_set_value(led_line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error activating LED: %s\n", strerror(errno));
        log_event("Error activating LED.");
    }
}

// Function to deactivate the LED
void deactivate_led() {
    int ret = gpiod_line_set_value(led_line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error deactivating LED: %s\n", strerror(errno));
        log_event("Error deactivating LED.");
    }
}

// Function to log events with timestamps
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, event);
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get line for flame sensor
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Get line for buzzer
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        return 1;
    }

    // Get line for LED
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        fprintf(stderr, "Error getting LED line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        return 1;
    }

    // Request lines for input and output
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line for input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    if (gpiod_line_request_output(led_line, "led", 0) < 0) {
        fprintf(stderr, "Error requesting LED line for output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    // Perform self-test
    if (self_test() != 0) {
        fprintf(stderr, "Self-test failed. Exiting.\n");
        gpiod_chip_close(chip);
        gpiod_line_release(flame_line);
        gpiod_line_release(buzzer_line);
        gpiod_line_release(led_line);
        return 1;
    }

    printf("Starting main loop...\n");

    // Main loop
    while (1) {
        int flame_detected = read_flame_sensor();
        if (flame_detected == 0) {
            log_event("Flame detected!");
            activate_buzzer();
            activate_led();

            // Wait for flame to go away
            int flame_gone = 0;
            for (int i = 0; i < 5; i++) {
                usleep(50000); // 50 ms
                if (read_flame_sensor() == 1) {
                    flame_gone = 1;
                    break;
                }
            }

            if (flame_gone) {
                log_event("Flame gone!");
            } else {
                log_event("Flame still present!");
            }

            deactivate_buzzer();
            deactivate_led();
        } else if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor. Exiting.\n");
            break;
        }

        usleep(50000); // 50 ms delay
    }

    // Clean up and exit
    gpiod_chip_close(chip);
    gpiod_line_release(flame_line);
    gpiod_line_release(buzzer_line);
    gpiod_line_release(led_line);

    return 0;
}

