#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_DEVICE "/dev/i2c-1"
#define BH1750_ADDR 0x23
#define GPIO_PIN 17
#define BUFFER_SIZE 60
#define I2C_RETRY_COUNT 3

// Global variables
int i2c_fd = -1;
int gpio_fd = -1;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
float convert_to_lux(uint16_t raw_value);
void circular_buffer_add(CircularBuffer *cb, float value);
float circular_buffer_average(CircularBuffer *cb);
void gpio_set_output(int fd, int value);
void gpio_set_frequency(int fd, float frequency);
void signal_handler(int signal);
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_set_value(int pin, int value);

// I2C read function with retry
int i2c_read_word(int fd, uint8_t reg) {
    int retries = 0;
    int result;
    uint8_t buf[2];

    while (retries < I2C_RETRY_COUNT) {
        if (write(fd, &reg, 1) != 1) {
            fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retry
            continue;
        }

        if (read(fd, buf, 2) == 2) {
            result = (buf[0] << 8) | buf[1];
            return result;
        } else {
            fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
            retries++;
            usleep(10000); // Wait 10ms before retry
        }
    }

    fprintf(stderr, "Failed to read from I2C after %d retries.\n", I2C_RETRY_COUNT);
    return -1; // Indicate failure
}

// Lux conversion function
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Circular buffer add function
void circular_buffer_add(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Circular buffer average function
float circular_buffer_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// GPIO set output function
void gpio_set_output(int fd, int value) {
    char buf[2];
    snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to GPIO value file: %s\n", strerror(errno));
    }
}

// GPIO set frequency function
void gpio_set_frequency(int fd, float frequency) {
    // Calculate period in nanoseconds
    float period = 1000000000.0 / frequency; // Period in nanoseconds
    float duty_cycle = 0.5; // 50% duty cycle

    // Calculate on and off times in nanoseconds
    float on_time = period * duty_cycle;
    float off_time = period * (1.0 - duty_cycle);

    // Convert to microseconds
    int on_time_us = (int)(on_time / 1000.0);
    int off_time_us = (int)(off_time / 1000.0);

    // Write to GPIO value file
    gpio_set_output(fd, 1); // Turn LED on
    usleep(on_time_us);
    gpio_set_output(fd, 0); // Turn LED off
    usleep(off_time_us);
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// GPIO export function
int gpio_export(int pin) {
    char buf[3];
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buf[3];
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set value function
int gpio_set_value(int pin, int value) {
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    char buf[2];
    snprintf(buf, sizeof(buf), "%d", value);
    if (write(fd, buf, strlen(buf)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int main() {
    // Initialize signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_export(GPIO_PIN) < 0) {
        close(i2c_fd);
        return 1;
    }

    if (gpio_set_direction(GPIO_PIN, "out") < 0) {
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    gpio_fd = open("/sys/class/gpio/gpio17/value", O_WRONLY);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening GPIO value file: %s\n", strerror(errno));
        gpio_unexport(GPIO_PIN);
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer = {{0.0}, 0, 0};

    // Main loop
    while (program_running) {
        // Read raw value from BH1750
        int raw_value = i2c_read_word(i2c_fd, 0x10); // Continuous high-resolution mode
        if (raw_value < 0) {
            fprintf(stderr, "Error reading raw value from BH1750.\n");
            sleep(1);
            continue;
        }

        // Convert to lux
        float lux = convert_to_lux((uint16_t)raw_value);

        // Add to circular buffer
        circular_buffer_add(&lux_buffer, lux);

        // Calculate average lux
        float avg_lux = circular_buffer_average(&lux_buffer);

        // Calculate blink rate
        float rate = 0.5 + (avg_lux / 1000.0) * 4.5;
        if (rate < 0.5) {
            rate = 0.5;
        } else if (rate > 5.0) {
            rate = 5.0;
        }

        // Set GPIO frequency
        gpio_set_frequency(gpio_fd, rate);

        // Print lux and average lux
        printf("Lux: %.2f, Average Lux: %.2f\n", lux, avg_lux);

        // Sleep for 1 second
        sleep(1);
    }

    // Cleanup
    gpio_set_output(gpio_fd, 0); // Turn off LED
    close(gpio_fd);
    gpio_unexport(GPIO_PIN);
    close(i2c_fd);

    return 0;
}

