#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9 (common cathode)
const unsigned char segments[] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *data_line;
struct gpiod_line *clock_line;
struct gpiod_line *latch_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);
    gpiod_line_release(data_line);
    gpiod_line_release(clock_line);
    gpiod_line_release(latch_line);
    gpiod_chip_close(chip);
    exit(0);
}

// Function to shift out a byte to the 74HC595
int shift_out(unsigned char data)
{
    for (int i = 0; i < 8; i++) {
        // Set data pin based on the current bit
        if (gpiod_line_set_value(data_line, (data >> (7 - i)) & 1) < 0) {
            fprintf(stderr, "Error setting data pin value\n");
            return -1;
        }

        // Clock the data in
        if (gpiod_line_set_value(clock_line, 1) < 0) {
            fprintf(stderr, "Error setting clock pin high\n");
            return -1;
        }
        usleep(1); // Small delay for clock stability

        if (gpiod_line_set_value(clock_line, 0) < 0) {
            fprintf(stderr, "Error setting clock pin low\n");
            return -1;
        }
        usleep(1); // Small delay for clock stability
    }

    return 0;
}

// Function to display a digit on the seven-segment display
int display_digit(int digit)
{
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return -1;
    }

    // Send the segment pattern to the shift register
    if (shift_out(segments[digit]) < 0) {
        fprintf(stderr, "Error shifting out digit %d\n", digit);
        return -1;
    }

    // Latch the data to the output
    if (gpiod_line_set_value(latch_line, 1) < 0) {
        fprintf(stderr, "Error setting latch pin high\n");
        return -1;
    }
    usleep(1); // Small delay for latch stability

    if (gpiod_line_set_value(latch_line, 0) < 0) {
        fprintf(stderr, "Error setting latch pin low\n");
        return -1;
    }
    usleep(1); // Small delay for latch stability

    return 0;
}

int main()
{
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get GPIO lines
    data_line = gpiod_chip_get_line(chip, DATA_PIN);
    clock_line = gpiod_chip_get_line(chip, CLOCK_PIN);
    latch_line = gpiod_chip_get_line(chip, LATCH_PIN);

    if (!data_line || !clock_line || !latch_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for output
    if (gpiod_line_request_output(data_line, "74HC595", 0) < 0) {
        perror("Error requesting data line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(clock_line, "74HC595", 0) < 0) {
        perror("Error requesting clock line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(latch_line, "74HC595", 0) < 0) {
        perror("Error requesting latch line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to blink the digit '5'
    while (1) {
        // Display the digit '5'
        if (display_digit(5) < 0) {
            fprintf(stderr, "Error displaying digit 5\n");
            break;
        }

        // Wait for 500 milliseconds
        usleep(500000);

