#include <time.h>

// Define GPIO pins
#define LED_PIN 17
#define BUTTON_PIN 18

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip = NULL;
struct gpiod_line *led_line = NULL;
struct gpiod_line *button_line = NULL;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(int signal);
void blink_led(void);

// Signal handler for Ctrl+C
void cleanup_gpio(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off the LED
    if (led_line) {
        gpiod_line_set_value(led_line, 0);
    }

    // Release GPIO lines
    if (led_line) {
        gpiod_line_release(led_line);
    }
    if (button_line) {
        gpiod_line_release(button_line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    struct gpiod_line_request_config config;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get LED line
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (!led_line) {
        perror("Error getting LED line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request LED line as output, initially low
    config.consumer = "blink_button";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;
    if (gpiod_line_request(led_line, &config, 0) < 0) {
        perror("Error requesting LED line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        return -1;
    }

    // Get button line
    button_line = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button_line) {
        perror("Error getting button line");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    // Request button line as input with pull-up
    config.consumer = "blink_button";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;
    if (gpiod_line_request(button_line, &config, 0) < 0) {
        perror("Error requesting button line as input");
        gpiod_chip_close(chip);
        gpiod_line_release(led_line);
        gpiod_line_release(button_line);
        return -1;
    }

    return 0;
}

// Function to blink the LED
void blink_led(void) {
    struct timespec on_time = {1, 0};  // 1 second
    struct timespec off_time = {1, 0}; // 1 second

    // Turn LED on
    if (gpiod_line_set_value(led_line, 1) < 0) {
        perror("Error setting LED value to 1");
        cleanup_gpio(0);
    }
    nanosleep(&on_time, NULL);

    // Turn LED off
    if (gpiod_line_set_value(led_line, 0) < 0) {
        perror("Error setting LED value to 0");
        cleanup_gpio(0);
    }
    nanosleep(&off_time, NULL);
}

int main(void) {
    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup_gpio);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Blinking LED and monitoring button. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        blink_led();

        // Monitor button with a timeout
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(button_line, 1000); // 1 second timeout

        if (ret == 0) {
            // Button pressed (falling edge)
            printf("Button pressed! Stopping blinking.\n");
            break;
        } else if (ret < 0) {
            perror("Error waiting for button event");
            cleanup_gpio(0);
        }
    }

    // Cleanup and exit
    cleanup_gpio(0);

    return 0;
}

