        fprintf(stderr, "GPIO initialization failed\n");
        return 1;
    }

    printf("GPIO initialized. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int button_state = read_button();
        if (button_state < 0) {
            // Error reading button, but continue running
            usleep(10000); // Sleep for 10ms to avoid busy-waiting
            continue;
        }

        if (button_state == 1) {
            // Button is pressed
            for (int i = 0; i < 5; i++) {
                if (write_led(1) < 0) break; // Exit loop on error
                usleep(500000); // 500 ms
                if (write_led(0) < 0) break; // Exit loop on error
                usleep(500000); // 500 ms
            }
        } else {
            // Button is not pressed, turn off the LED
            write_led(0);
        }

        usleep(10000); // Small delay to avoid busy-waiting
    }

    return 0;
}

