#include <gpiod.h>

// Define GPIO pins for RGB LED (BCM numbering)
#define RED_PIN 24
#define GREEN_PIN 23
#define BLUE_PIN 18

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM period (seconds)
#define PWM_PERIOD (1.0 / PWM_FREQUENCY)

// Define PWM resolution (0-100)
#define PWM_RESOLUTION 100

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *red_line, *green_line, *blue_line;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release GPIO lines
    if (red_line) {
        gpiod_line_release(red_line);
    }
    if (green_line) {
        gpiod_line_release(green_line);
    }
    if (blue_line) {
        gpiod_line_release(blue_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

// Function to set the PWM duty cycle for a given GPIO line
void set_pwm_duty_cycle(struct gpiod_line *line, int duty_cycle)
{
    // Calculate the on-time in nanoseconds
    struct timespec on_time;
    on_time.tv_sec = 0;
    on_time.tv_nsec = (long)(PWM_PERIOD * 1000000000.0 * duty_cycle / PWM_RESOLUTION);

    // Set the GPIO line high for the on-time
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("Failed to set GPIO value high");
        exit(1);
    }

    // Sleep for the off-time
    struct timespec off_time;
    off_time.tv_sec = 0;
    off_time.tv_nsec = (long)(PWM_PERIOD * 1000000000.0 * (PWM_RESOLUTION - duty_cycle) / PWM_RESOLUTION);

    if (clock_nanosleep(CLOCK_MONOTONIC, 0, &off_time, NULL) < 0) {
        perror("clock_nanosleep failed");
        exit(1);
    }

    // Set the GPIO line low
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("Failed to set GPIO value low");
        exit(1);
    }
}

int main()
{
    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_number(0);
    if (!chip) {
        perror("Failed to open GPIO chip");
        return 1;
    }

    // Get the GPIO lines for each color
    red_line = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line = gpiod_chip_get_line(chip, BLUE_PIN);

    if (!red_line || !green_line || !blue_line) {
        perror("Failed to get GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO lines for output
    if (gpiod_line_request_output(red_line, "rgb-led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(green_line, "rgb-led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }
    if (gpiod_line_request_output(blue_line, "rgb-led", 0) < 0) {
        perror("Failed to request GPIO line for output");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to generate random RGB values and set PWM duty cycles
    while (1) {
        // Generate random RGB values (0-100)
        int red_value = rand() % 101;
        int green_value = rand() % 101;
        int blue_value = rand() % 101;

        // Set the PWM duty cycles for each color
        set_pwm_duty_cycle(red_line, red_value);
        set_pwm_duty_cycle(green_line, green_value);
        set_pwm_duty_cycle(blue_line, blue_value);

        // Wait for 100 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 ms
        if (clock_nanosleep(CLOCK_MONOTONIC, 0, &sleep_time, NULL) < 0) {
            perror("clock_nanosleep failed");
            exit(1);
        }
    }

    return 0;
}

