#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define LSM303_ADDR 0x19
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define GPIO_PIN 17
#define DEFAULT_THRESHOLD 2.0
#define SAMPLE_RATE 10 // Hz
#define PULSE_DURATION 50 // ms

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm303();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure for accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Initialize LSM303DLHC
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    accelerometer_data_t accel_data;
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Error reading accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Calculate magnitude
        double magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Check for impact
        if (magnitude > threshold) {
            // Trigger GPIO pulse
            gpioWrite(GPIO_PIN, 1);
            gpioDelay(PULSE_DURATION * 1000); // Convert ms to us
            gpioWrite(GPIO_PIN, 0);

            // Log impact
            log_impact(accel_data.x, accel_data.y, accel_data.z);
        }

        // Delay for sampling rate
        gpioDelay(1000000 / SAMPLE_RATE); // Delay in microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

// Initialize LSM303DLHC
int init_lsm303() {
    i2c_handle = i2cOpen(I2C_BUS, LSM303_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }

    // Configure CTRL_REG1_A (0x20): Enable all axes, 100 Hz
    if (i2cWriteByteData(i2c_handle, CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure CTRL_REG4_A (0x23): +/- 2G full-scale, 16384 LSB/G
    if (i2cWriteByteData(i2c_handle, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4_A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle, OUT_X_L_A | 0x80, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calculate magnitude of acceleration vector
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    // Sensitivity is 16384 LSB/G for +/- 2G full-scale
    double x_g = (double)x / 16384.0;
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to file
void log_impact(int16_t x, int16_t y, int16_t z) {
    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, X: %d, Y: %d, Z: %d\n", s, x, y, z);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

