#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define I2C_ADDRESS 0x39
#define MODE_REGISTER 0x0D
#define ALS_LSB_REGISTER 0x64
#define ALS_MSB_REGISTER 0x65
#define RED_REGISTER 0x66
#define GREEN_REGISTER 0x68
#define BLUE_REGISTER 0x6A
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define SAMPLE_INTERVAL_MS 500

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void set_led_brightness(uint16_t als_value);
void signal_handler(int signal);

// Function to initialize the sensor
int initialize_sensor() {
    int retries = 3;
    while (retries > 0) {
        if (i2cWriteByteData(i2c_handle, MODE_REGISTER, 0x01) == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "Error: Failed to initialize sensor (attempt %d). Retrying...\n", 4 - retries);
            gpioDelay(100); // Wait 100 ms before retrying
            retries--;
        }
    }
    fprintf(stderr, "Error: Failed to initialize sensor after multiple retries.\n");
    return -1; // Failure
}

// Function to read sensor data
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t lsb, msb;

    lsb = i2cReadByteData(i2c_handle, ALS_LSB_REGISTER);
    msb = i2cReadByteData(i2c_handle, ALS_MSB_REGISTER);
    if (lsb == PI_BAD_I2C_ADDR || msb == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error: Failed to read ALS data.\n");
        data.als = 0; // Set to 0 to avoid garbage values
    } else {
        data.als = (uint16_t)((msb << 8) | lsb);
    }

    data.red = i2cReadWordData(i2c_handle, RED_REGISTER);
    data.green = i2cReadWordData(i2c_handle, GREEN_REGISTER);
    data.blue = i2cReadWordData(i2c_handle, BLUE_REGISTER);

    return data;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, data.als, data.red, data.green, data.blue);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to set LED brightness using PWM
void set_led_brightness(uint16_t als_value) {
    // Map ALS value (0-65535) to PWM duty cycle (0-255)
    int duty_cycle = (int)(((float)als_value / 65535.0) * 255.0);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
