#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define FXOS8700_ADDR 0x1F
#define WHO_AM_I_REG 0x0D
#define CTRL_REG1 0x2A
#define XYZ_DATA_CFG 0x0E
#define OUT_X_MSB 0x01
#define IMPACT_THRESHOLD 19.62 // m/s^2
#define SENSITIVITY 4096.0   // counts/g for +/- 2g range
#define GRAVITY 9.81         // m/s^2

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_fxos8700();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the FXOS8700 sensor
int init_fxos8700() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0xC7, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Put sensor in standby mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (standby): %d\n", i2c_handle);
        return -1;
    }

    // Configure for ±2g range
    if (i2cWriteByteData(i2c_handle, XYZ_DATA_CFG, 0x00) < 0) {
        fprintf(stderr, "Error writing to XYZ_DATA_CFG: %d\n", i2c_handle);
        return -1;
    }

    // Activate sensor
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1 (active): %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Read acceleration data from the sensor
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
        return -1;
    }

    // Combine MSB and LSB, right-shift by 2 bits, and sign extend
    *x = (int16_t)((((int16_t)buffer[0]) << 8 | buffer[1]) >> 2);
    *y = (int16_t)((((int16_t)buffer[2]) << 8 | buffer[3]) >> 2);
    *z = (int16_t)((((int16_t)buffer[4]) << 8 | buffer[5]) >> 2);

    return 0;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / SENSITIVITY * GRAVITY;
    float y_g = (float)y / SENSITIVITY * GRAVITY;
    float z_g = (float)z / SENSITIVITY * GRAVITY;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Log impact data to a file
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    FILE *fp = fopen("impact_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening impact_log.txt for writing\n");
        return;
    }

    fprintf(fp, "%s,%.3f,%.3f,%.3f,%.3f\n", timestamp, (float)x / SENSITIVITY * GRAVITY, (float)y / SENSITIVITY * GRAVITY, (float)z / SENSITIVITY * GRAVITY, magnitude);
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_fxos8700() != 0) {
        fprintf(stderr, "FXOS8700 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > IMPACT_THRESHOLD) {
                log_impact(x, y, z, magnitude);
                printf("Impact detected! Magnitude: %.3f m/s^2\n", magnitude);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }

        gpioDelay(50); // 50 ms delay
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

