#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Configuration
#define I2C_BUS 1
#define GYRO_ADDRESS 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define WHO_AM_I 0x0F
#define SENSITIVITY 0.00875 // dps/LSB
#define CALIBRATION_SAMPLES 100
#define ODR_100HZ 0x0F // Normal mode, all axes enabled, 100 Hz ODR
#define FS_250DPS 0x00 // +/- 250 dps full-scale
#define GYRO_LOG_FILE "gyro_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold gyroscope data
typedef struct {
    double x;
    double y;
    double z;
} gyro_data_t;

// Function prototypes
int i2c_setup(int bus, int address);
int gyro_init(int fd);
gyro_data_t read_gyro_data(int fd);
gyro_data_t calibrate_gyro(int fd);
void log_gyro_data(FILE *fp, gyro_data_t data);
void check_thresholds(gyro_data_t data);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(int bus, int address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", bus);
    int fd = open(filename, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }
    return fd;
}

// Gyroscope initialization function
int gyro_init(int fd) {
    // Check WHO_AM_I register
    uint8_t who_am_i;
    if (write(fd, &who_am_i, 1) != 1) {
        perror("Error writing to WHO_AM_I register");
        return -1;
    }
    if (read(fd, &who_am_i, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i != 0xD3) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0xD3)\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Normal mode, all axes enabled, 100 Hz ODR)
    uint8_t config1 = ODR_100HZ;
    if (write(fd, &config1, 1) != 1) {
        perror("Error writing to CTRL_REG1");
        return -1;
    }

    // Configure CTRL_REG4 (250 dps full-scale, continuous update)
    uint8_t config4 = FS_250DPS;
    if (write(fd, &config4, 1) != 1) {
        perror("Error writing to CTRL_REG4");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data(int fd) {
    gyro_data_t data;
    uint8_t buffer[6];

    // Read 6 bytes of gyroscope data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = 0.0; // Indicate error
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second
    data.x = (double)x * SENSITIVITY;
    data.y = (double)y * SENSITIVITY;
    data.z = (double)z * SENSITIVITY;

    return data;
}

// Function to calibrate the gyroscope
gyro_data_t calibrate_gyro(int fd) {
    gyro_data_t offset = {0.0, 0.0, 0.0};
    gyro_data_t data;

    printf("Calibrating gyroscope...\n");
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        data = read_gyro_data(fd);
        offset.x += data.x;
        offset.y += data.y;
        offset.z += data.z;
        usleep(50000); // 50 ms delay
    }

    offset.x /= CALIBRATION_SAMPLES;
    offset.y /= CALIBRATION_SAMPLES;
    offset.z /= CALIBRATION_SAMPLES;

    printf("Calibration complete. Offsets: X=%.3f, Y=%.3f, Z=%.3f\n", offset.x, offset.y, offset.z);
    return offset;
}

// Function to log gyroscope data
void log_gyro_data(FILE *fp, gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

