#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// VL6180X I2C address
#define VL6180X_ADDR 0x29

// VL6180X register addresses
#define VL6180X_REG_IDENTIFICATION_MODEL_ID 0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062
#define VL6180X_REG_RESULT_INTERRUPT_STATUS 0x04F
#define VL6180X_REG_SYSTEM_INTERRUPT_CLEAR 0x086

// I2C bus
#define I2C_BUS 1

// Distance threshold for door opening (in mm)
#define DISTANCE_THRESHOLD 100

// Log file name
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl6180x();
int read_distance();
void log_data(int distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the VL6180X sensor
int init_vl6180x() {
    // Mandatory initialization sequence
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET, 0x01) < 0) {
        fprintf(stderr, "Error writing to VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET\n");
        return -1;
    }
    gpioDelay(10); // Delay for 10 ms

    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, 0x10) < 0) {
        fprintf(stderr, "Error writing to VL6180X_REG_SYSTEM_MODE_GPIO1\n");
        return -1;
    }
    gpioDelay(10); // Delay for 10 ms

    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to VL6180X_REG_SYSRANGE_START\n");
        return -1;
    }
    gpioDelay(10); // Delay for 10 ms

    return 0;
}

// Reads the distance from the VL6180X sensor
int read_distance() {
    int distance = -1; // Default to -1 in case of error
    int status;

    // Start a range measurement
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error writing to VL6180X_REG_SYSRANGE_START\n");
        return -1;
    }
    gpioDelay(10); // Delay for 10 ms

    // Read the range value
    distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading from VL6180X_REG_RESULT_RANGE_VAL\n");
        return -1;
    }

    // Read the interrupt status
    status = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_INTERRUPT_STATUS);
    if (status < 0) {
        fprintf(stderr, "Error reading from VL6180X_REG_RESULT_INTERRUPT_STATUS\n");
        return -1;
    }

    // Clear interrupt
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CLEAR, 0x07) < 0) {
        fprintf(stderr, "Error writing to VL6180X_REG_SYSTEM_INTERRUPT_CLEAR\n");
        return -1;
    }
    gpioDelay(10); // Delay for 10 ms

    return distance;
}

// Logs the distance data to a file
void log_data(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (distance < 0) {
        fprintf(log_file, "%s,Sensor Error\n", timestamp);
        fprintf(stderr, "%s,Sensor Error\n", timestamp);
    } else if (distance < DISTANCE_THRESHOLD) {
        fprintf(log_file, "%s,DOOR_OPEN\n", timestamp);
        printf("%s,DOOR_OPEN\n", timestamp);
    } else {
        fprintf(log_file, "%s,DOOR_CLOSED\n", timestamp);
        printf("%s,DOOR_CLOSED\n", timestamp);
    }
    fflush(log_file); // Ensure data is written to file immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL6180X sensor
    if (init_vl6180x() < 0) {
        fprintf(stderr, "VL6180X initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "Error reading distance, attempting re-initialization...\n");
            fprintf(log_file, "Error reading distance, attempting re-initialization...\n");
            fflush(log_file);
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(I2C_BUS, VL6180X_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                program_running = 0; // Exit if re-initialization fails
            } else if (init_vl6180x() < 0) {
                fprintf(stderr, "VL6180X re-initialization failed\n");
                program_running = 0; // Exit if re-initialization fails
            }
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

