        // Read audio samples from both sensors
        sensor1_sample = read_audio_sample(i2c_handle1);
        if (sensor1_sample == -1) {
            fprintf(stderr, "Error reading sensor 1 data, skipping sample.\n");
            continue; // Skip to the next iteration
        }

        sensor2_sample = read_audio_sample(i2c_handle2);
        if (sensor2_sample == -1) {
