#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// ADIS16488A Register Addresses
#define X_GYRO 0x04
#define Y_GYRO 0x06
#define Z_GYRO 0x08
#define X_ACCEL 0x0A
#define Y_ACCEL 0x0C
#define Z_ACCEL 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 3
#define SPI_FLAGS 0b11000000000 // Aux SPI off, CPOL=1, CPHA=1

// Scaling factors
#define GYRO_SCALE 0.005
#define ACCEL_SCALE 0.00025

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function prototypes
int initialize();
int read_register(uint8_t reg_addr, int16_t *data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Open CSV file for logging
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    // Write CSV header
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");

    return 0;
}

// Function to read a single register
int read_register(uint8_t reg_addr, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer (MSB = 0, register address)
    tx_buf[0] = 0x00;
    tx_buf[1] = reg_addr;

    // Perform the SPI transaction
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (result < 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Combine the received bytes into a 16-bit value
    *data = (rx_buf[0] << 8) | rx_buf[1];

    return 0;
}

// Function to read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    int16_t raw_gyro_x, raw_gyro_y, raw_gyro_z;
    int16_t raw_accel_x, raw_accel_y, raw_accel_z;

    // Read gyroscope data
    if (read_register(X_GYRO, &raw_gyro_x) != 0) raw_gyro_x = 0;
    if (read_register(Y_GYRO, &raw_gyro_y) != 0) raw_gyro_y = 0;
    if (read_register(Z_GYRO, &raw_gyro_z) != 0) raw_gyro_z = 0;

    // Read accelerometer data
    if (read_register(X_ACCEL, &raw_accel_x) != 0) raw_accel_x = 0;
    if (read_register(Y_ACCEL, &raw_accel_y) != 0) raw_accel_y = 0;
    if (read_register(Z_ACCEL, &raw_accel_z) != 0) raw_accel_z = 0;

    // Convert raw data to physical units
    data.gyro_x = raw_gyro_x * GYRO_SCALE;
    data.gyro_y = raw_gyro_y * GYRO_SCALE;
    data.gyro_z = raw_gyro_z * GYRO_SCALE;
    data.accel_x = raw_accel_x * ACCEL_SCALE;
    data.accel_y = raw_accel_y * ACCEL_SCALE;
    data.accel_z = raw_accel_z * ACCEL_SCALE;

    // Get timestamp
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;

    return data;
}

// Function to log data to CSV file
void log_data(imu_data_t data) {
    fprintf(fp, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            data.timestamp,
            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Register cleanup function
    atexit(cleanup);

    // Main loop
    while (running) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

