            data.gyro_x,
            data.gyro_y,
            data.gyro_z,
            data.accel_x,
            data.accel_y,
            data.accel_z);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
