    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    // Register cleanup function
    atexit(cleanup);

    // Main loop
    while (running) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

