#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16448 Register Addresses
#define X_GYRO_OUT 0x04
#define Y_GYRO_OUT 0x06
#define Z_GYRO_OUT 0x08
#define X_ACCL_OUT 0x0A
#define Y_ACCL_OUT 0x0C
#define Z_ACCL_OUT 0x0E

// Scaling factors
#define GYRO_SCALE 0.05  // deg/sec/LSB
#define ACCL_SCALE 0.00025 // g/LSB

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0       // SPI Mode 0

int spi_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("\nCtrl+C pressed. Cleaning up...\n");
    spiClose(spi_handle);
    gpioTerminate();
    exit(0);
}

// Function to read a 16-bit register from the ADIS16448
int16_t read_register(int handle, uint8_t reg_addr)
{
    char tx_buf[2];
    char rx_buf[2];
    int16_t data;

    // Construct the read command (register address with MSB set)
    tx_buf[0] = (reg_addr << 1) | 0x80; // MSB = 1 for read
    tx_buf[1] = 0x00;                   // Dummy byte

    // Perform the SPI transaction
    if (spiXfer(handle, tx_buf, rx_buf, 2) != 0) {
        fprintf(stderr, "Error during SPI transfer for register 0x%02X\n", reg_addr);
        return -1; // Indicate error
    }

    // Combine the two bytes into a 16-bit value
    data = (rx_buf[0] << 8) | rx_buf[1];

    return data;
}

// Function to convert raw gyroscope data to degrees per second
float convert_gyro_data(int16_t raw_data)
{
    return (float)raw_data * GYRO_SCALE;
}

// Function to convert raw accelerometer data to g's
float convert_accel_data(int16_t raw_data)
{
    return (float)raw_data * ACCL_SCALE;
}

int main()
{
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t raw_x_gyro = read_register(spi_handle, X_GYRO_OUT);
        int16_t raw_y_gyro = read_register(spi_handle, Y_GYRO_OUT);
        int16_t raw_z_gyro = read_register(spi_handle, Z_GYRO_OUT);

        // Read accelerometer data
        int16_t raw_x_accl = read_register(spi_handle, X_ACCL_OUT);
        int16_t raw_y_accl = read_register(spi_handle, Y_ACCL_OUT);
        int16_t raw_z_accl = read_register(spi_handle, Z_ACCL_OUT);

        // Check for read errors
        if (raw_x_gyro == -1 || raw_y_gyro == -1 || raw_z_gyro == -1 ||
            raw_x_accl == -1 || raw_y_accl == -1 || raw_z_accl == -1) {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Convert raw data to meaningful units
        float gyro_x = convert_gyro_data(raw_x_gyro);
        float gyro_y = convert_gyro_data(raw_y_gyro);
        float gyro_z = convert_gyro_data(raw_z_gyro);
        float accl_x = convert_accel_data(raw_x_accl);
        float accl_y = convert_accel_data(raw_y_accl);
        float accl_z = convert_accel_data(raw_z_accl);

        // Print the data
        printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
               gyro_x, gyro_y, gyro_z, accl_x, accl_y, accl_z);

        // Wait for 100 ms
        gpioDelay(100);
    }

    // This point should not be reached due to the signal handler
    return 0;
}

