#define WHO_AM_I 0x75
#define PWR_MGMT_1 0x6B
#define ACCEL_CONFIG 0x1C
#define GYRO_CONFIG 0x1B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_XOUT_L 0x3C
#define ACCEL_YOUT_H 0x3D
#define ACCEL_YOUT_L 0x3E
#define ACCEL_ZOUT_H 0x3F
#define ACCEL_ZOUT_L 0x40
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6886
int init_mpu6886(int fd) {
    // Wake up the sensor
    if (i2c_smbus_write_byte_data(fd, PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU-6886");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_smbus_write_byte_data(fd, ACCEL_CONFIG, 0x00) < 0) {
        perror("Failed to set accelerometer range");
        return -1;
    }

    // Set gyroscope range to +-250 dps
    if (i2c_smbus_write_byte_data(fd, GYRO_CONFIG, 0x00) < 0) {
        perror("Failed to set gyroscope range");
        return -1;
    }

    return 0;
}

// Function to read a register with retry
int read_register(int fd, uint8_t reg) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            return result;
        } else {
            perror("Failed to read register, retrying...");
            retries--;
            usleep(1000); // Wait 1 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read register after multiple retries.\n");
    return -1;
}

// Function to read accelerometer data
int read_accelerometer(int fd, int16_t *x, int16_t *y, int16_t *z) {
    int x_h, x_l, y_h, y_l, z_h, z_l;

    x_h = read_register(fd, ACCEL_XOUT_H);
    x_l = read_register(fd, ACCEL_XOUT_L);
    y_h = read_register(fd, ACCEL_YOUT_H);
    y_l = read_register(fd, ACCEL_YOUT_L);
    z_h = read_register(fd, ACCEL_ZOUT_H);
    z_l = read_register(fd, ACCEL_ZOUT_L);

    if (x_h < 0 || x_l < 0 || y_h < 0 || y_l < 0 || z_h < 0 || z_l < 0) {
        return -1; // Indicate failure
    }

    *x = (int16_t)((x_h << 8) | x_l);
    *y = (int16_t)((y_h << 8) | y_l);
    *z = (int16_t)((z_h << 8) | z_l);

