#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADXL345_ADDR 0x53
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAY0 0x34
#define DATAZ0 0x36
#define LED_GPIO 17
#define IMPACT_THRESHOLD 2.5f
#define SCALE_FACTOR 256.0f
#define LOG_FILE "impact_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} AccelerationData;

// Function prototypes
int init_adxl345();
AccelerationData read_acceleration();
float calculate_magnitude(AccelerationData data);
void log_impact(AccelerationData data, float magnitude);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int init_adxl345() {
    // Set data format register to +-2g range and full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set power control register to measure mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from the ADXL345
AccelerationData read_acceleration() {
    AccelerationData data;
    char raw_data[6];

    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        data.x = 0.0f;
        data.y = 0.0f;
        data.z = 0.0f;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g-force units
    data.x = (float)x / SCALE_FACTOR;
    data.y = (float)y / SCALE_FACTOR;
    data.z = (float)z / SCALE_FACTOR;

    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(AccelerationData data) {
    return sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
}

// Log impact data to file
void log_impact(AccelerationData data, float magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Magnitude: %.2f g, X: %.2f g, Y: %.2f g, Z: %.2f g\n",
            timestamp, magnitude, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (init_adxl345() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        AccelerationData data = read_acceleration();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            gpioWrite(LED_GPIO, 1); // Turn on LED
            log_impact(data, magnitude);
            gpioDelay(500); // Wait 500 ms
            gpioWrite(LED_GPIO, 0); // Turn off LED
        }

        gpioDelay(10); // Poll every 10 ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Impact detection stopped.\n");
    return 0;
}

