#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define MMA8451Q_ADDR 0x1D
#define WHO_AM_I_REG 0x0D
#define XOUT_L 0x00
#define XOUT_H 0x01
#define YOUT_L 0x02
#define YOUT_H 0x03
#define ZOUT_L 0x04
#define ZOUT_H 0x05
#define CTRL_REG1 0x2A
#define LED_GPIO 17
#define ACCEL_THRESHOLD 2.0f // 2g
#define SENSITIVITY 0.000244f // 2g / 1024
#define IMPACT_LOG_FILE "impact_log.txt"

// Global variables
int i2c_fd = -1;
int led_gpio = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
void control_led(int gpio, int on);
void log_impact(float x, float y, float z);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return value;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, MMA8451Q_ADDR) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Error: Could not write to I2C device");
        return -1;
    }

    return 0;
}

// Read acceleration data
int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t x_raw, y_raw, z_raw;
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = i2c_read_reg(fd, XOUT_L);
    x_h = i2c_read_reg(fd, XOUT_H);
    y_l = i2c_read_reg(fd, YOUT_L);
    y_h = i2c_read_reg(fd, YOUT_H);
    z_l = i2c_read_reg(fd, ZOUT_L);
    z_h = i2c_read_reg(fd, ZOUT_H);

    if (x_l < 0 || x_h < 0 || y_l < 0 || y_h < 0 || z_l < 0 || z_h < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((x_h << 8) | x_l);
    y_raw = (int16_t)((y_h << 8) | y_l);
    z_raw = (int16_t)((z_h << 8) | z_l);

    *x = (float)x_raw * SENSITIVITY;
    *y = (float)y_raw * SENSITIVITY;
    *z = (float)z_raw * SENSITIVITY;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Control LED
void control_led(int gpio, int on) {
    gpioWrite(gpio, on);
}

// Log impact
void log_impact(float x, float y, float z) {
    FILE *fp = fopen(IMPACT_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Impact detected - X: %.2f g, Y: %.2f g, Z: %.2f g\n", s, x, y, z);
    fclose(fp);
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    led_gpio = LED_GPIO;
    gpioSetMode(led_gpio, PI_OUTPUT);

    // Open I2C bus
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != 0x1A) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x1A)\n", who_am_i);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Configure MMA8451Q (Active mode, 800 Hz)
    if (i2c_write_reg(i2c_fd, CTRL_REG1, 0x01) < 0) {
        fprintf(stderr, "Error: Could not configure MMA8451Q\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z, magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);

            if (magnitude > ACCEL_THRESHOLD) {
                control_led(led_gpio, 1); // Turn LED on
                log_impact(x, y, z);
                gpioDelay(500); // Wait 500 ms
                control_led(led_gpio, 0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Poll every 100 ms
    }

    // Cleanup
    close(i2c_fd);
    control_led(led_gpio, 0); // Turn LED off
    gpioTerminate();

    return 0;
}

