        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    led_gpio = LED_GPIO;
    gpioSetMode(led_gpio, PI_OUTPUT);

    // Open I2C bus
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", I2C_BUS);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Could not open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Verify sensor ID
    int who_am_i = i2c_read_reg(i2c_fd, WHO_AM_I_REG);
    if (who_am_i != 0x1A) {
