int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int16_t read_magnetic_field(int fd, uint8_t lsb_reg, uint8_t msb_reg);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Function to read a single byte from an I2C register
int i2c_read_register(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// Function to write a single byte to an I2C register
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read a 16-bit little-endian value from two registers
int16_t read_magnetic_field(int fd, uint8_t lsb_reg, uint8_t msb_reg) {
    int lsb = i2c_read_register(fd, lsb_reg);
    int msb = i2c_read_register(fd, msb_reg);

    if (lsb < 0 || msb < 0) {
        return 0; // Return 0 on error
    }

