    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    fseek(log_file, 0, SEEK_END); // Reset file pointer to the end

    // Main loop to read and log data
    while (1) {
        int16_t x = read_magnetic_field(i2c_fd, REG_X_LSB, REG_X_MSB);
        int16_t y = read_magnetic_field(i2c_fd, REG_Y_LSB, REG_Y_MSB);
        int16_t z = read_magnetic_field(i2c_fd, REG_Z_LSB, REG_Z_MSB);

        log_data(log_file, x, y, z);

        sleep(1); // Wait for 1 second
    }

    return 0;
}

