#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <errno.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADXL345_ADDR 0x53
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 17
#define GPIO_LINE 11
#define FREEFALL_THRESHOLD 300 // mg
#define FREEFALL_DURATION 100 // ms
#define LOG_FILE "freefall_log.csv"

// ADXL345 Registers
#define ADXL345_DEVID 0x00
#define ADXL345_THRESH_FF 0x0A
#define ADXL345_TIME_FF 0x20
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_INT_SOURCE 0x30

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static struct gpiod_line_event_request *gpio_event_request = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int adxl345_init(int fd);
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line);
int gpio_event_loop(struct gpiod_line_event_request *request);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (address) failed");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

// ADXL345 initialization function
int adxl345_init(int fd) {
    uint8_t devid;

    // Verify device ID
    if (i2c_read_reg(fd, ADXL345_DEVID, &devid) != 0) {
        fprintf(stderr, "Error reading device ID\n");
        return -1;
    }

    if (devid != 0xE5) {
        fprintf(stderr, "Incorrect device ID: 0x%02X\n", devid);
        return -1;
    }

    // Set standby mode
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure freefall threshold
    if (i2c_write_reg(fd, ADXL345_THRESH_FF, FREEFALL_THRESHOLD / 4) != 0) { // Scale factor of 4
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Configure freefall duration
    if (i2c_write_reg(fd, ADXL345_TIME_FF, FREEFALL_DURATION) != 0) {
        fprintf(stderr, "Error setting freefall duration\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x02) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    // Enter measurement mode
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error entering measurement mode\n");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("GPIO chip open failed");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("GPIO line get failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(*line, "adxl345_interrupt") != 0) {
        perror("GPIO line request failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// GPIO event loop function
int gpio_event_loop(struct gpiod_line_event_request *request) {
    struct gpiod_line_event event;

    while (program_running) {
        ssize_t ret = gpiod_line_event_wait(request);
        if (ret < 0) {
            perror("GPIO event wait failed");
            return -1;
        }

        if (gpiod_line_event_get(request, &event) != 0) {
            perror("GPIO event get failed");
            return -1;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Freefall detected
            int16_t x, y, z;
            uint8_t int_source;

            // Read INT_SOURCE to verify the interrupt
            if (i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE, &int_source) != 0) {
                fprintf(stderr, "Error reading INT_SOURCE\n");
                continue; // Continue to the next interrupt
            }

            if (int_source & 0x02) {
                // Read acceleration data
                uint8_t data[6];
                if (read(i2c_fd, data, 6) != 6) {
                    perror("I2C block read failed");
                    continue; // Continue to the next interrupt
                }

                x = (int16_t)((data[1] << 8) | data[0]);
                y = (int16_t)((data[3] << 8) | data[2]);
                z = (int16_t)((data[5] << 8) | data[4]);

                // Log the data
                log_data(log_file, x, y, z);
            }
        }
    }

    return 0;
}

// Data logging function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long milliseconds = timeinfo->tm_sec * 1000 + timeinfo->tm_nsec / 1000000;
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", milliseconds % 1000);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open failed");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("I2C slave address set failed");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(&gpio_chip, &gpio_line) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Log file open failed");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Create GPIO event request
    gpio_event_request = gpiod_line_event_request_rising_edge(gpio_line, "adxl345_interrupt");
    if (!gpio_event_request) {
        perror("GPIO event request failed");
        fclose(log_file);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Event loop
    if (gpio_event_loop(gpio_event_request) != 0) {
        fprintf(stderr, "GPIO event loop failed\n");
    }

    // Cleanup
    gpiod_line_event_release(gpio_event_request);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

