    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x00) != 0) {
        fprintf(stderr, "Error setting standby mode\n");
        return -1;
    }

    // Configure freefall threshold
    if (i2c_write_reg(fd, ADXL345_THRESH_FF, FREEFALL_THRESHOLD / 4) != 0) { // Scale factor of 4
        fprintf(stderr, "Error setting freefall threshold\n");
        return -1;
    }

    // Configure freefall duration
    if (i2c_write_reg(fd, ADXL345_TIME_FF, FREEFALL_DURATION) != 0) {
        fprintf(stderr, "Error setting freefall duration\n");
        return -1;
    }

    // Enable freefall interrupt
    if (i2c_write_reg(fd, ADXL345_INT_ENABLE, 0x02) != 0) {
        fprintf(stderr, "Error enabling freefall interrupt\n");
        return -1;
    }

    // Map freefall interrupt to INT1
    if (i2c_write_reg(fd, ADXL345_INT_MAP, 0x00) != 0) {
        fprintf(stderr, "Error mapping freefall interrupt\n");
        return -1;
    }

    // Enter measurement mode
    if (i2c_write_reg(fd, ADXL345_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error entering measurement mode\n");
        return -1;
    }

    return 0;
}

// GPIO initialization function
int gpio_init(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!*chip) {
        perror("GPIO chip open failed");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        perror("GPIO line get failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    if (gpiod_line_request_rising_edge_events(*line, "adxl345_interrupt") != 0) {
        perror("GPIO line request failed");
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// GPIO event loop function
int gpio_event_loop(struct gpiod_line_event_request *request) {
    struct gpiod_line_event event;

    while (program_running) {
        ssize_t ret = gpiod_line_event_wait(request);
        if (ret < 0) {
            perror("GPIO event wait failed");
            return -1;
        }

        if (gpiod_line_event_get(request, &event) != 0) {
            perror("GPIO event get failed");
            return -1;
        }

        if (event.event_type == GPIOD_LINE_EVENT_RISING_EDGE) {
            // Freefall detected
            int16_t x, y, z;
            uint8_t int_source;

            // Read INT_SOURCE to verify the interrupt
            if (i2c_read_reg(i2c_fd, ADXL345_INT_SOURCE, &int_source) != 0) {
                fprintf(stderr, "Error reading INT_SOURCE\n");
                continue; // Continue to the next interrupt
            }

            if (int_source & 0x02) {
                // Read acceleration data
                uint8_t data[6];
                if (read(i2c_fd, data, 6) != 6) {
                    perror("I2C block read failed");
                    continue; // Continue to the next interrupt
                }

                x = (int16_t)((data[1] << 8) | data[0]);
                y = (int16_t)((data[3] << 8) | data[2]);
                z = (int16_t)((data[5] << 8) | data[4]);

                // Log the data
                log_data(log_file, x, y, z);
            }
        }
    }

    return 0;
}

// Data logging function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    long milliseconds = timeinfo->tm_sec * 1000 + timeinfo->tm_nsec / 1000000;
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%03ld", milliseconds % 1000);

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z);
    fflush(fp);
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Signal received, exiting...\n");
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("I2C open failed");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADXL345_ADDR) < 0) {
        perror("I2C slave address set failed");
        close(i2c_fd);
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init(i2c_fd) != 0) {
        fprintf(stderr, "ADXL345 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize GPIO
    if (gpio_init(&gpio_chip, &gpio_line) != 0) {
        fprintf(stderr, "GPIO initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Log file open failed");
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Write header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Create GPIO event request
    gpio_event_request = gpiod_line_event_request_rising_edge(gpio_line, "adxl345_interrupt");
    if (!gpio_event_request) {
        perror("GPIO event request failed");
        fclose(log_file);
        gpiod_line_release(gpio_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Event loop
    if (gpio_event_loop(gpio_event_request) != 0) {
        fprintf(stderr, "GPIO event loop failed\n");
    }

    // Cleanup
    gpiod_line_event_release(gpio_event_request);
    gpiod_line_release(gpio_line);
    gpiod_chip_close(gpio_chip);
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

