#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6A

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensor states
typedef enum {
    IDLE,
    FREEFALL,
    IMPACT
} sensor_state_t;

// Global variables
int i2c_handle;
FILE *log_file;
sensor_state_t current_state = IDLE;
time_t freefall_start_time = 0;

// Function prototypes
int init_lsm6dsr();
int read_accel_gyro_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float calculate_acceleration_magnitude(int16_t accel_x, int16_t accel_y, int16_t accel_z);
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float accel_magnitude);
void handle_sensor_state(float accel_magnitude);
void signal_handler(int signal);

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Configure accelerometer: +-2g range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x80) < 0) { // 0x80: 104 Hz, +-2g
        fprintf(stderr, "Error writing to CTRL1_XL\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps range, 104 Hz ODR
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x80) < 0) { // 0x80: 104 Hz, +-250 dps
        fprintf(stderr, "Error writing to CTRL2_G\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_accel_gyro_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buffer[12];

    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) < 0) {
        fprintf(stderr, "Error reading accelerometer/gyroscope data\n");
        return -1;
    }

    *gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *accel_x = (int16_t)((buffer[7] << 8) | buffer[6]);
    *accel_y = (int16_t)((buffer[9] << 8) | buffer[8]);
    *accel_z = (int16_t)((buffer[11] << 8) | buffer[10]);

    return 0;
}

// Function to calculate the magnitude of the acceleration vector
float calculate_acceleration_magnitude(int16_t accel_x, int16_t accel_y, int16_t accel_z) {
    float x = (float)accel_x / 16384.0f; // Convert to g (assuming +-2g range)
    float y = (float)accel_y / 16384.0f;
    float z = (float)accel_z / 16384.0f;
    return sqrt(x * x + y * y + z * z);
}

// Function to log data to a CSV file
void log_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z, float accel_magnitude) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d,%d,%d,%d,%.4f\n", timestamp, accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, accel_magnitude);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to handle the sensor state machine
void handle_sensor_state(float accel_magnitude) {
    time_t now = time(NULL);

    switch (current_state) {
        case IDLE:
            if (accel_magnitude < 0.2f) {
                current_state = FREEFALL;
                freefall_start_time = now;
            }
            break;
        case FREEFALL:
            if (accel_magnitude > 2.5f) {
                current_state = IMPACT;
            } else if (difftime(now, freefall_start_time) > 1.0) {
                current_state = IDLE;
            }
            break;
        case IMPACT:
            // Impact detected, log the event
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
            fprintf(log_file, "%s,IMPACT DETECTED\n", timestamp);
            fflush(log_file);
            current_state = IDLE; // Reset state after impact
            break;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float accel_magnitude;

    // Main loop
    while (1) {
        // Read accelerometer and gyroscope data
        if (read_accel_gyro_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Calculate acceleration magnitude
            accel_magnitude = calculate_acceleration_magnitude(accel_x, accel_y, accel_z);

            // Log data
            log_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z, accel_magnitude);

            // Handle sensor state
            handle_sensor_state(accel_magnitude);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Delay for approximately 10ms (104 Hz ODR)
        gpioDelay(10000); // 10000 microseconds = 10 milliseconds
    }

    return 0;
}

