#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define SENSITIVITY 8.75 // mdps/LSB
#define SAMPLE_RATE 100 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE)
#define WHO_AM_I_REG 0x0F
#define WHO_AM_I_VALUE 0xD3
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gyro();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps);
void log_data(struct timespec ts, float x, float y, float z);
void signal_handler(int signal);

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 0;
    int status;

    // Enable all axes and set full-scale range
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // Normal mode, all axes enabled
        if (status >= 0) break;
        fprintf(stderr, "Error writing to CTRL_REG1 (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1 ms before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write to CTRL_REG1 after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // +-250 dps
        if (status >= 0) break;
        fprintf(stderr, "Error writing to CTRL_REG4 (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1 ms before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to write to CTRL_REG4 after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Verify WHO_AM_I register
    int who_am_i;
    retries = 0;
    while (retries < RETRY_COUNT) {
        who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I_REG);
        if (who_am_i >= 0 && who_am_i == WHO_AM_I_VALUE) break;
        fprintf(stderr, "Error reading WHO_AM_I (attempt %d): %d\n", retries + 1, who_am_i);
        retries++;
        gpioDelay(1000); // Wait 1 ms before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read correct WHO_AM_I value after %d retries. Expected 0xD3, got 0x%X\n", RETRY_COUNT, who_am_i);
        return -1;
    }

    printf("Gyroscope initialized successfully.\n");
    return 0;
}

// Read gyroscope data
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = 0;
    int status;

    while (retries < RETRY_COUNT) {
        status = i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6);
        if (status == 6) break;
        fprintf(stderr, "Error reading gyro data (attempt %d): %d\n", retries + 1, status);
        retries++;
        gpioDelay(1000); // Wait 1 ms before retrying
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Failed to read gyro data after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to degrees per second
void convert_to_dps(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / SENSITIVITY;
    *y_dps = (float)y / SENSITIVITY;
    *z_dps = (float)z / SENSITIVITY;
}

// Log data to file
void log_data(struct timespec ts, float x, float y, float z) {
    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f\n", ts.tv_sec, ts.tv_nsec, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Gyroscope initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,X,Y,Z\n");

    // Set up signal handling
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t x_raw, y_raw, z_raw;
    float x_dps, y_dps, z_dps;
    struct timespec ts;

    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x_raw, &y_raw, &z_raw) == 0) {
            // Convert to degrees per second
            convert_to_dps(x_raw, y_raw, z_raw, &x_dps, &y_dps, &z_dps);

            // Get timestamp
            if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
                // Log data
                log_data(ts, x_dps, y_dps, z_dps);
            } else {
                fprintf(stderr, "Error getting timestamp\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }

        // Delay for sampling period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

