#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME "flame_events.log"

static volatile int running = 1;
FILE *log_file = NULL;

// Function to handle Ctrl+C signal
void signal_handler(int signal) {
    running = 0;
    printf("\nExiting gracefully...\n");
}

// Function to initialize the pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to enable the internal pull-up resistor on a GPIO pin
int enable_pullup_resistor(int gpio_pin) {
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame event to a file
int log_flame_event(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

// Function to print a fire alarm message to the console
void print_fire_alarm() {
    printf("FLAME DETECTED!\n");
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Enable the pull-up resistor
    if (enable_pullup_resistor(FLAME_SENSOR_GPIO) != 0) {
        gpioTerminate();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int flame_detected = read_flame_sensor(FLAME_SENSOR_GPIO);
        if (flame_detected == 0) {
            print_fire_alarm();
