    return 0;
}

// Function to enable the internal pull-up resistor on a GPIO pin
int enable_pullup_resistor(int gpio_pin) {
    if (gpioSetPullUpDown(gpio_pin, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up resistor on GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame event to a file
int log_flame_event(int flame_detected) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Flame detected: %s\n", timestamp, flame_detected ? "YES" : "NO");
        fflush(log_file); // Ensure the data is written to the file immediately
        return 0;
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }
}

