#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define I2C_SLAVE_ADDR 0x53
#define ACCEL_REG_X_LSB 0x28
#define ACCEL_REG_X_MSB 0x29
#define ACCEL_REG_Y_LSB 0x2A
#define ACCEL_REG_Y_MSB 0x2B
#define ACCEL_REG_Z_LSB 0x2C
#define ACCEL_REG_Z_MSB 0x2D
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_setup(const char *bus, int addr);
int i2c_read_register(int fd, uint8_t reg);
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size);
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// I2C setup function
int i2c_setup(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// I2C read register function
int i2c_read_register(int fd, uint8_t reg) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return value;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// I2C write register function
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Read acceleration data function
int read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (i2c_read_block(fd, ACCEL_REG_X_LSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Get ISO 8601 timestamp function
char *get_iso8601_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    time_t rawtime;
    struct tm *info;
    time(&rawtime);
    info = gmtime(&rawtime);
    strftime(timestamp_str, timestamp_str_size, "%Y-%m-%dT%H:%M:%SZ", info);
    return timestamp_str;
}

// Log data to CSV file function
int log_data(FILE *fp, const char *timestamp, int16_t x, int16_t y, int16_t z) {
    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = i2c_setup(I2C_BUS, I2C_SLAVE_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C setup failed, exiting\n");
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    int16_t x, y, z;
    char timestamp_str[32];

    while (program_running) {
        // Read acceleration data
        if (read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Get timestamp
            get_iso8601_timestamp(timestamp_str, sizeof(timestamp_str));

            // Log data
            if (log_data(log_file, timestamp_str, x, y, z) != 0) {
                fprintf(stderr, "Error logging data, but continuing...\n");
            }
        } else {
            fprintf(stderr, "Error reading acceleration data, but continuing...\n");
        }

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert ms to microseconds
    }

    // Cleanup
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

