#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 27
#define LOG_FILE "conveyor_log.txt"

static volatile int running = 1;

// Structure to hold GPIO configuration
typedef struct {
    int sensor1_gpio;
    int sensor2_gpio;
} gpio_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Function to get current timestamp with millisecond precision
char* get_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    time_t nowtime = ts.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%03ld", tmbuf, ts.tv_nsec / 1000000);
    return strdup(buf); // Allocate memory for the timestamp string
}

// Function to read sensor state
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to file
void log_data(const char* timestamp, int sensor1_state, int sensor2_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }
    fprintf(fp, "%s, Sensor1: %d, Sensor2: %d\n", timestamp, sensor1_state, sensor2_state);
    fclose(fp);
}

// Function to check if both sensors are triggered
int are_sensors_triggered(int sensor1_state, int sensor2_state) {
    return (sensor1_state == 1 && sensor2_state == 1);
}

// Function to handle conveyor belt halt
void halt_conveyor() {
    printf("Conveyor belt halted!\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO pins as inputs with pull-ups
    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor states
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Get timestamp
        char* timestamp = get_timestamp();

        // Log data
        log_data(timestamp, sensor1_state, sensor2_state);

        // Check if both sensors are triggered
        if (are_sensors_triggered(sensor1_state, sensor2_state)) {
            halt_conveyor();
        }

        free(timestamp); // Free the allocated memory

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Conveyor belt monitoring stopped.\n");

    return 0;
}

