void convert_to_mgauss(int16_t x, int16_t y, int16_t z, float *x_mg, float *y_mg, float *z_mg);
void log_data(float x_mg, float y_mg, float z_mg);
void check_metal_detection(float x_mg, float y_mg, float z_mg);
void signal_handler(int signal);

// I2C read register function
int i2c_read_reg(int fd, uint8_t reg) {
    int result = i2c_smbus_read_byte_data(fd, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int result = i2c_smbus_write_byte_data(fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Sensor initialization function
int initialize_sensor(int fd) {
    int retries = 3;
    while (retries > 0) {
        // Check WHO_AM_I register
        int who_am_i = i2c_read_reg(fd, LIS3MDL_WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I register, retrying...\n");
            retries--;
            usleep(100000); // Wait 100ms before retrying
            continue;
        }
        if (who_am_i != 0x3D) {
            fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x3D. Sensor not found or not responding.\n", who_am_i);
            return -1;
        }

        // Configure CTRL_REG1 (ODR = 80 Hz, continuous conversion, high-performance)
        if (i2c_write_reg(fd, LIS3MDL_CTRL_REG1, 0x70) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG1, retrying...\n");
            retries--;
            usleep(100000);
            continue;
        }

        // Configure CTRL_REG4 (XY-axis enabled, high-performance)
        if (i2c_write_reg(fd, LIS3MDL_CTRL_REG4, 0x0C) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG4, retrying...\n");
            retries--;
            usleep(100000);
            continue;
        }

        // Configure CTRL_REG3 (Z-axis enabled, high-performance)
        if (i2c_write_reg(fd, LIS3MDL_CTRL_REG3, 0x00) < 0) {
            fprintf(stderr, "Error writing to CTRL_REG3, retrying...\n");
            retries--;
            usleep(100000);
            continue;
        }

        return 0; // Initialization successful
    }

    fprintf(stderr, "Sensor initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Read magnetometer data function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int result = i2c_smbus_read_i2c_block_data(fd, LIS3MDL_OUT_X_L, 6, buffer);
    if (result < 0) {
        fprintf(stderr, "Error reading magnetometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert to milliGauss function
void convert_to_mgauss(int16_t x, int16_t y, int16_t z, float *x_mg, float *y_mg, float *z_mg) {
    *x_mg = (float)x * 0.146;
    *y_mg = (float)y * 0.146;
    *z_mg = (float)z * 0.146;
}

// Log data function
void log_data(float x_mg, float y_mg, float z_mg) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_mg, y_mg, z_mg);
    fflush(log_file); // Ensure data is written to file immediately
}

// Check for metal detection function
void check_metal_detection(float x_mg, float y_mg, float z_mg) {
    float magnitude = sqrt(x_mg * x_mg + y_mg * y_mg + z_mg * z_mg);
    if (magnitude > METAL_THRESHOLD) {
        fprintf(stderr, "Metal detected! Magnitude: %.2f mG\n", magnitude);
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Initialize sensor
    if (initialize_sensor(i2c_fd) < 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    int16_t x, y, z;
    float x_mg, y_mg, z_mg;

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer_data(i2c_fd, &x, &y, &z) == 0) {
            // Convert to milliGauss
            convert_to_mgauss(x, y, z, &x_mg, &y_mg, &z_mg);

            // Apply calibration
            x_mg = (x_mg - X_OFFSET) * X_SCALE;
            y_mg = (y_mg - Y_OFFSET) * Y_SCALE;
            z_mg = (z_mg - Z_OFFSET) * Z_SCALE;

            // Log data
            log_data(x_mg, y_mg, z_mg);

            // Check for metal detection
            check_metal_detection(x_mg, y_mg, z_mg);
        } else {
            fprintf(stderr, "Error reading magnetometer data. Retrying initialization.\n");
            close(i2c_fd);
            i2c_fd = open("/dev/i2c-1", O_RDWR);
            if (i2c_fd < 0) {
                fprintf(stderr, "Error re-opening I2C device: %s\n", strerror(errno));
                program_running = 0; // Exit loop if I2C fails repeatedly
                break;
            }
            if (ioctl(i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
                fprintf(stderr, "Error re-setting I2C slave address: %s\n", strerror(errno));
                program_running = 0;
                break;
            }
            if (initialize_sensor(i2c_fd) < 0) {
                fprintf(stderr, "Sensor re-initialization failed.\n");
                program_running = 0;
                break;
            }
        }

        usleep(100000); // 10 Hz sampling rate
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    return 0;
}

