#define ADXL354B_REG_XDATA_L   0x08
#define ADXL354B_REG_XDATA_H   0x09
#define ADXL354B_REG_YDATA_L   0x0A
#define ADXL354B_REG_YDATA_H   0x0B
#define ADXL354B_REG_ZDATA_L   0x0C
#define ADXL354B_REG_ZDATA_H   0x0D
#define ADXL354B_REG_STATUS    0x04
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_FILTER    0x28
#define ADXL354B_REG_RESET     0x1F

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 // 1 MHz
#define SPI_MODE    0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// SPI Read Register Function
int spi_read_register(int handle, uint8_t reg) {
    char tx[2], rx[2];
    tx[0] = reg | 0x80; // Read bit set
    tx[1] = 0x00;       // Dummy byte

    int result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Read Error: %d\n", result);
        return -1;
    }

    return rx[1];
}

// SPI Write Register Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx[2], rx[2];
    tx[0] = reg & 0x7F; // Write bit clear
    tx[1] = value;

    int result = spiXfer(handle, tx, rx, 2);
    if (result != 2) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "ADXL354B Reset Failed\n");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms
    return 0;
}

// ADXL354B Initialization Function
int adxl354B_init(int handle) {
    // Check PARTID
    int partid = spi_read_register(handle, ADXL354B_REG_PARTID);
    if (partid != 0x1D) {
        fprintf(stderr, "ADXL354B Not Found (PARTID = 0x%02X)\n", partid);
        return -1;
    }

    // Reset the device
    if (adxl354b_reset(handle) != 0) {
        return -1;
    }

    // Configure for +-2g range and 100 Hz ODR
    if (spi_write_register(handle, ADXL354B_REG_FILTER, 0x03) != 0) { // Set FILTER register for 100Hz ODR
        return -1;
    }

    // Start measurement
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) { // Set RUN bit to start measurement
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, float *x, float *y, float *z) {
    int16_t x_raw, y_raw, z_raw;
    int x_l, x_h, y_l, y_h, z_l, z_h;

    x_l = spi_read_register(handle, ADXL354B_REG_XDATA_L);
    x_h = spi_read_register(handle, ADXL354B_REG_XDATA_H);
    y_l = spi_read_register(handle, ADXL354B_REG_YDATA_L);
    y_h = spi_read_register(handle, ADXL354B_REG_YDATA_H);
    z_l = spi_read_register(handle, ADXL354B_REG_ZDATA_L);
    z_h = spi_read_register(handle, ADXL354B_REG_ZDATA_H);

    if (x_l == -1 || x_h == -1 || y_l == -1 || y_h == -1 || z_l == -1 || z_h == -1) {
        fprintf(stderr, "Error reading acceleration data\n");
        return -1;
    }

    x_raw = (int16_t)((x_h << 8) | x_l);
    y_raw = (int16_t)((y_h << 8) | y_l);
    z_raw = (int16_t)((z_h << 8) | z_l);

    *x = (float)x_raw * 0.0000039; // Convert to g
    *y = (float)y_raw * 0.0000039; // Convert to g
    *z = (float)z_raw * 0.0000039; // Convert to g

    return 0;
}

// Log Data Function
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, X: %.6f g, Y: %.6f g, Z: %.6f g\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to file immediately
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("vibration_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL354B
    if (adxl354B_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL354B initialization failed\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;
    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

