#define Z_GYRO 0x08
#define X_ACCL 0x0A
#define Y_ACCL 0x0C
#define Z_ACCL 0x0E

// Scaling factors
#define GYRO_SCALE 0.05
#define ACCL_SCALE 0.0025

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_MODE 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double x_gyro;
    double y_gyro;
    double z_gyro;
    double x_accel;
    double y_accel;
    double z_accel;
} imu_data_t;

// Function prototypes
int init_pigpio();
int open_spi();
int read_register(uint8_t address, int16_t *data);
imu_data_t read_imu_data();
int log_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open SPI channel
int open_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from ADIS16362 register
int read_register(uint8_t address, int16_t *data) {
    char tx_buf[2];
    char rx_buf[2];
    int result;

    // Construct the transmit buffer (MSB set for read)
    tx_buf[0] = address | 0x80; // Set MSB for read
    tx_buf[1] = 0x00; // Dummy byte

    result = spiXfer(spi_handle, tx_buf, rx_buf, 2);

    if (result != 2) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
