#include <stdio.h>
#include <stdlib.h>
#include <gpiod.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the GPIO chip and line numbers
#define GPIO_CHIP "gpiochip4"
#define GPIO_LINE 17

// Global variables for GPIO chip and line
struct gpiod_chip *chip = NULL;
struct gpiod_line *line = NULL;

// Signal handler for Ctrl+C
void signal_handler(int sig)
{
    printf("\nCaught signal %d, cleaning up...\n", sig);

    // Release the GPIO line
    if (line) {
        gpiod_line_release(line);
    }

    // Close the GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    exit(0);
}

int main()
{
    int rc;
    struct timespec sleep_time;

    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return 1;
    }

    // Get the GPIO line
    line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return 1;
    }

    // Request the GPIO line for input
    rc = gpiod_line_request_input(line, "obstacle_sensor");
    if (rc < 0) {
        perror("Error requesting GPIO line for input");
        gpiod_chip_close(chip);
        return 1;
    }

    // Main loop to read the sensor
    while (1) {
        // Read the sensor value
        int value = gpiod_line_get_value(line);
        if (value < 0) {
            perror("Error reading GPIO line value");
            break; // Exit loop on error
        }

        // Check if an obstacle is detected (LOW signal)
        if (value == 0) {
            // Get current time
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Log the start of the self-parking sequence
            char timestamp[80];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Self-parking sequence started\n", timestamp);

            // Simulate self-parking sequence (sleep for 5 seconds)
            sleep_time.tv_sec = 5;
            sleep_time.tv_nsec = 0;
            nanosleep(&sleep_time, NULL);

            // Get current time
            time(&rawtime);
            timeinfo = localtime(&rawtime);

            // Log the completion of the self-parking sequence
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
            printf("%s - Self-parking sequence completed\n", timestamp);
        }

        // Sleep for 1 second
        sleep_time.tv_sec = 1;
        sleep_time.tv_nsec = 0;
        nanosleep(&sleep_time, NULL);
    }

    // Clean up and exit
    gpiod_line_release(line);
    gpiod_chip_close(chip);

    return 0;
}

