// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define WHO_AM_I 0x0F
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_L_XL 0x28

// Sensitivity values
#define GYRO_SENSITIVITY 8.75f  // mdps/LSB
#define ACCEL_SENSITIVITY 0.061f // mg/LSB

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the LSM6DSR sensor
int init_lsm6dsr() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I mismatch: Expected 0x6B, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: +-2g full-scale, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: +-250 dps, 104 Hz
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x42) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read accelerometer and gyroscope data
int read_sensor_data(float *gyro_x, float *gyro_y, float *gyro_z, float *accel_x, float *accel_y, float *accel_z) {
    char buffer[12];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (bytes_read != 12) {
        fprintf(stderr, "Error reading sensor data: %d bytes read\n", bytes_read);
        return -1;
    }

    // Combine low and high bytes for each axis
    int16_t gyro_x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t gyro_y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t gyro_z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);
    int16_t accel_x_raw = (int16_t)((buffer[7] << 8) | buffer[6]);
    int16_t accel_y_raw = (int16_t)((buffer[9] << 8) | buffer[8]);
    int16_t accel_z_raw = (int16_t)((buffer[11] << 8) | buffer[10]);

    // Convert to physical units
    *gyro_x = (float)gyro_x_raw * GYRO_SENSITIVITY;
    *gyro_y = (float)gyro_y_raw * GYRO_SENSITIVITY;
    *gyro_z = (float)gyro_z_raw * GYRO_SENSITIVITY;
    *accel_x = (float)accel_x_raw * ACCEL_SENSITIVITY;
    *accel_y = (float)accel_y_raw * ACCEL_SENSITIVITY;
    *accel_z = (float)accel_z_raw * ACCEL_SENSITIVITY;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR sensor
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    float gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;
    while (!terminate) {
        if (read_sensor_data(&gyro_x, &gyro_y, &gyro_z, &accel_x, &accel_y, &accel_z) == 0) {
            printf("Gyro: X=%.2f, Y=%.2f, Z=%.2f | Accel: X=%.2f, Y=%.2f, Z=%.2f\n",
                   gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // 100 ms delay
    }

    // Clean up
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

