// FXOS8700 I2C address
#define FXOS8700_ADDR 0x1D

// FXOS8700 register addresses
#define FXOS8700_WHO_AM_I 0x0D
#define FXOS8700_CTRL_REG1 0x2A
#define FXOS8700_CTRL_REG2 0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB 0x01

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", sig);
    terminate = 1;
}

// Function to initialize the FXOS8700 sensor
int init_fxos8700() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Configure CTRL_REG1 (Hybrid mode, active)
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG1, 0x01 | (1 << 1)) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG2 (High resolution, 200 Hz ODR)
    if (i2cWriteByteData(i2c_handle, FXOS8700_CTRL_REG2, 0x02) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    // Configure M_CTRL_REG1 (Hybrid mode, active)
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG1, 0x01 | (1 << 1)) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG1\n");
        return -1;
    }

    // Configure M_CTRL_REG2 (High resolution, 200 Hz ODR)
    if (i2cWriteByteData(i2c_handle, FXOS8700_M_CTRL_REG2, 0x02) < 0) {
        fprintf(stderr, "Error writing to M_CTRL_REG2\n");
        return -1;
    }

    return 0;
}

