#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATAX0 0x32
#define ADXL345_REG_DATAX1 0x33
#define ADXL345_REG_DATAY0 0x34
#define ADXL345_REG_DATAY1 0x35
#define ADXL345_REG_DATAZ0 0x36
#define ADXL345_REG_DATAZ1 0x37

// Tilt angle threshold (degrees)
#define TILT_THRESHOLD 30.0

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// Log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Global variables
int i2c_fd = -1; // I2C file descriptor
FILE *log_file = NULL; // Log file pointer
volatile sig_atomic_t program_running = 1; // Flag to control the main loop

// Function prototypes
int i2c_read_register(int fd, uint8_t reg);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int16_t read_acceleration_axis(int fd, uint8_t reg_low, uint8_t reg_high);
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z);
void log_tilt_event(float x_angle, float y_angle, float z_angle);
void signal_handler(int signal);
int initialize_i2c(const char *bus);
int initialize_adxl345(int fd);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to read a single byte from an I2C register
int i2c_read_register(int fd, uint8_t reg) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Error: Could not write register address");
        return -1;
    }

    uint8_t value;
    if (read(fd, &value, 1) != 1) {
        perror("Error: Could not read register value");
        return -1;
    }

    return value;
}

// Function to write a single byte to an I2C register
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    if (fd < 0) {
        fprintf(stderr, "Error: Invalid I2C file descriptor.\n");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        perror("Error: Could not set I2C slave address");
        return -1;
    }

    uint8_t buffer[2];
    buffer[0] = reg;
    buffer[1] = value;

    if (write(fd, buffer, 2) != 2) {
        perror("Error: Could not write to I2C device");
        return -1;
    }

    return 0;
}

// Function to read a 16-bit acceleration value from two registers
int16_t read_acceleration_axis(int fd, uint8_t reg_low, uint8_t reg_high) {
    int8_t low = i2c_read_register(fd, reg_low);
    int8_t high = i2c_read_register(fd, reg_high);

    if (low < 0 || high < 0) {
        return 0; // Return 0 on error
    }

    return (int16_t)((high << 8) | low);
}

// Function to calculate tilt angles from raw acceleration data
float calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    float x_angle = atan2(x, sqrt(y * y + z * z)) * 180 / M_PI;
    float y_angle = atan2(y, sqrt(x * x + z * z)) * 180 / M_PI;
    float z_angle = atan2(z, sqrt(x * x + y * y)) * 180 / M_PI;
    return z_angle; // Return the z-axis angle for simplicity
}

// Function to log tilt events to a file
void log_tilt_event(float x_angle, float y_angle, float z_angle) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - Tilt event: X=%.2f, Y=%.2f, Z=%.2f\n", timestamp, x_angle, y_angle, z_angle);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("Ctrl+C pressed. Exiting...\n");
        program_running = 0;
    }
}

// Function to initialize the I2C bus
int initialize_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error: Could not open I2C bus");
        return -1;
    }
    return fd;
}

// Function to initialize the ADXL345 sensor
int initialize_adxl345(int fd) {
    // Set data format: +/- 2g range, full resolution
    if (i2c_write_register(fd, ADXL345_REG_POWER_CTL, 0x08) < 0) { // Enable measurement mode
        fprintf(stderr, "Error: Could not set ADXL345 data format.\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = initialize_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize ADXL345
    if (initialize_adxl345(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: Could not open log file");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 100000000; // 100 milliseconds

    while (program_running) {
        // Read acceleration data
        int16_t x = read_acceleration_axis(i2c_fd, ADXL345_REG_DATAX0, ADXL345_REG_DATAX1);
        int16_t y = read_acceleration_axis(i2c_fd, ADXL345_REG_DATAY0, ADXL345_REG_DATAY1);
        int16_t z = read_acceleration_axis(i2c_fd, ADXL345_REG_DATAZ0, ADXL345_REG_DATAZ1);

        // Calculate tilt angles
        float tilt_angle = calculate_tilt_angle(x, y, z);

        // Check for tilt events
        if (fabs(tilt_angle) > TILT_THRESHOLD) {
            log_tilt_event(tilt_angle, tilt_angle, tilt_angle); // Log the z-axis angle
        }

        // Sleep for 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up resources
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

