#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5 // seconds
#define SAMPLE_RATE 1 // milliseconds
#define ALERT_THRESHOLD 10

volatile sig_atomic_t program_running = 1;

void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return 1;
    }

    char *endptr;
    long threshold = strtol(argv[1], &endptr, 10);

    if (*endptr != '\0' || threshold <= 0) {
        fprintf(stderr, "Error: Invalid threshold value. Must be a positive integer.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);

    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    time_t start_time, current_time;
    time(&start_time);
    int high_count = 0;

    while (program_running) {
        time(&current_time);
        double elapsed_time = difftime(current_time, start_time);

        if (elapsed_time >= WINDOW_SIZE) {
            if (gpioRead(GPIO_PIN) == 1) {
                high_count++;
            }

            if (high_count > threshold) {
                time_t now;
                time(&now);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                printf("%s ALERT: High noise level detected!\n", timestamp);
            } else {
                time_t now;
                time(&now);
                char timestamp[30];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));
                printf("%s Status: Noise level normal (%d/%d)\n", timestamp, high_count, threshold);
            }

