#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define DOOR_A_PIN 17
#define DOOR_B_PIN 27

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the number of digits in the security code
#define CODE_LENGTH 6

// Define the range of the random number generator
#define RANDOM_MIN 100000
#define RANDOM_MAX 999999

// Global variables
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *door_a_line = NULL;
static struct gpiod_line *door_b_line = NULL;
static FILE *log_file = NULL;

// Function prototypes
int generate_random_code(int min, int max);
int check_code(int entered_code, int correct_code);
int unlock_door(int door_pin);
int lock_door(int door_pin);
int log_access(int code);
void signal_handler(int sig);
int setup_gpio(void);
void cleanup_gpio(void);

// Function to generate a random 6-digit code
int generate_random_code(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to check if the entered code matches the correct code
int check_code(int entered_code, int correct_code) {
    return (entered_code == correct_code);
}

// Function to unlock a door
int unlock_door(int door_pin) {
    struct gpiod_line *line = NULL;

    if (door_pin == DOOR_A_PIN) {
        line = door_a_line;
    } else if (door_pin == DOOR_B_PIN) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d HIGH: %s\n", door_pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to lock a door
int lock_door(int door_pin) {
    struct gpiod_line *line = NULL;

    if (door_pin == DOOR_A_PIN) {
        line = door_a_line;
    } else if (door_pin == DOOR_B_PIN) {
        line = door_b_line;
    } else {
        fprintf(stderr, "Error: Invalid door pin: %d\n", door_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d LOW: %s\n", door_pin, strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log access attempts
int log_access(int code) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%06d\n", timestamp, code) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting...\n");
}

// Function to set up GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip '%s': %s\n", GPIOCHIP, strerror(errno));
        return -1;
    }

    door_a_line = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (!door_a_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_chip;
    }

    door_b_line = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (!door_b_line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_door_a;
    }

    if (gpiod_line_request_output(door_a_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup_door_b;
    }

    if (gpiod_line_request_output(door_b_line, "door_access", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO %d as output: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup_door_a_request;
    }

    return 0;

cleanup_door_a_request:
    gpiod_line_release(door_a_line);
cleanup_door_b:
    gpiod_line_release(door_b_line);
cleanup_door_a:
    gpiod_line_release(door_a_line);
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to clean up GPIO resources
void cleanup_gpio(void) {
    if (door_a_line) {
        gpiod_line_release(door_a_line);
    }
    if (door_b_line) {
        gpiod_line_release(door_b_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    int correct_code, entered_code;
    char input[7]; // Allow for null terminator

    // Seed the random number generator
    srand(time(NULL));

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (setup_gpio() < 0) {
        fprintf(stderr, "GPIO setup failed. Exiting.\n");
        return 1;
    }

    // Generate a random security code
    correct_code = generate_random_code(RANDOM_MIN, RANDOM_MAX);
    printf("Correct code: %06d\n", correct_code);

    // Open the log file
    log_file = fopen("access_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Main loop
    while (!terminate) {
        printf("Enter code: ");
        if (fgets(input, sizeof(input), stdin) == NULL) {
            if (feof(stdin)) {
                printf("End of input. Exiting.\n");
                break;
            } else {
                fprintf(stderr, "Error reading input: %s\n", strerror(errno));
                break;
            }
        }

        // Remove trailing newline character
        input[strcspn(input, "\n")] = 0;

        // Check if the input is a valid 6-digit number
        if (strlen(input) == CODE_LENGTH && strspn(input, "0123456789") == CODE_LENGTH) {
            entered_code = atoi(input);

            // Check if the entered code matches the correct code
            if (check_code(entered_code, correct_code)) {
                printf("Access granted!\n");

                // Unlock Door A
                if (unlock_door(DOOR_A_PIN) < 0) {
                    fprintf(stderr, "Failed to unlock Door A.\n");
                } else {
                    // Wait for 5 seconds
                    struct timespec sleep_time;
                    sleep_time.tv_sec = 5;
                    sleep_time.tv_nsec = 0;
                    nanosleep(&sleep_time, NULL);

                    // Lock Door A
                    if (lock_door(DOOR_A_PIN) < 0) {
                        fprintf(stderr, "Failed to lock Door A.\n");
                    }
                }

                // Log the access attempt
                if (log_access(correct_code) < 0) {
                    fprintf(stderr, "Failed to log access.\n");
                }

                // Generate a new random code
                correct_code = generate_random_code(RANDOM_MIN, RANDOM_MAX);
                printf("New code: %06d\n", correct_code);
            } else {
                printf("Access denied.\n");
                log_access(entered_code); // Log the attempt
            }
        } else {
            // Invalid input
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
        }
    }

    // Clean up resources
    cleanup_gpio();

    if (log_file) {
        fclose(log_file);
    }

    return 0;
}

