#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <string.h>
#include <signal.h>
#include <errno.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define BH1750_ADDR 0x23

// Define the measurement mode
#define BH1750_CONTINUOUS_HIGH_RES_MODE 0x21

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to write a command to the BH1750 sensor
int write_command(int fd, uint8_t command) {
    uint8_t buf[1];
    buf[0] = command;
    if (write(fd, buf, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// Function to read data from the BH1750 sensor
int read_data(int fd, uint16_t *data) {
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }
    *data = (buf[0] << 8) | buf[1];
    return 0;
}

// Function to calculate the illuminance in lux
float calculate_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to log the data to a file
int log_data(float lux_value) {
    FILE *fp = fopen("light_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux_value);
    fclose(fp);
    return 0;
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS, BH1750_ADDR);
    if (i2c_fd < 0) {
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_value;
        float lux_value;

        // Write the measurement command
        if (write_command(i2c_fd, BH1750_CONTINUOUS_HIGH_RES_MODE) < 0) {
            fprintf(stderr, "Error writing command, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Wait for the measurement to complete (at least 180ms)
        usleep(200000); // 200ms

        // Read the data
        if (read_data(i2c_fd, &raw_value) < 0) {
            fprintf(stderr, "Error reading data, retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Calculate the illuminance
        lux_value = calculate_lux(raw_value);

        // Log the data
        if (log_data(lux_value) < 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close the I2C bus (this will never be reached in the current loop)
    close(i2c_fd);

    return 0;
}

