#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define PWM_GPIO 18
#define SERVER_PORT 12345
#define SHARED_SECRET "MySecretKey"
#define FREQUENCY_LOG_FILE "frequency_log.txt"
#define NUM_ELECTRODES 12

// Global variables
int i2c_handle;
int server_socket;
FILE *log_file;

// Function prototypes
int initialize_mpr121();
int read_touch_data(int *touch_data);
float map_touch_data_to_frequency(int touch_data);
void play_tone(float frequency);
void handle_client(int client_socket);
void signal_handler(int signal);

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_FILTERTH_L 0x24
#define MPR121_FILTERTH_H 0x25
#define MPR121_BASELINE_L 0x1E
#define MPR121_BASELINE_H 0x1F
#define MPR121_ELECTRODECONFIG 0x5E
#define MPR121_SOFTRESET 0x80

// Function to initialize the MPR121
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        perror("Error: Soft reset failed");
        return -1;
    }
    gpioDelay(100000); // Wait for reset to complete

    // Configure electrode sensitivity
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_L, 0x10) < 0) {
        perror("Error: Failed to set filter threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_H, 0x00) < 0) {
        perror("Error: Failed to set filter threshold");
        return -1;
    }

    // Configure electrode baseline
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_L, 0x05) < 0) {
        perror("Error: Failed to set baseline");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_H, 0x00) < 0) {
        perror("Error: Failed to set baseline");
        return -1;
    }

    // Configure electrode configuration
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODECONFIG, 0x0C) < 0) {
        perror("Error: Failed to set electrode configuration");
        return -1;
    }

    return 0;
}

// Function to read touch data from the MPR121
int read_touch_data(int *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        perror("Error: Failed to read touch data");
        return -1;
    }

    touch_data[0] = buf[0];
    touch_data[1] = buf[1];

    return 0;
}

// Function to map touch data to frequency
float map_touch_data_to_frequency(int touch_data) {
    // Map the maximum electrode filtered data value to a frequency
    // using a logarithmic scale
    float frequency = 220.0 + (log10(touch_data + 1) / log10(1024)) * (880.0 - 220.0);
    return frequency;
}

// Function to play a tone using hardware PWM
void play_tone(float frequency) {
    if (frequency > 0) {
        gpioSetPWMfrequency(PWM_GPIO, (int)frequency);
        gpioPWM(PWM_GPIO, 128); // 50% duty cycle
    } else {
        gpioPWM(PWM_GPIO, 0); // Stop PWM
    }
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[256];
    ssize_t bytes_received;

    // Receive data from the client
    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received > 0) {
        buffer[bytes_received] = '\0';
        printf("Received: %s\n", buffer);

        // Check for the authentication message
        if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
            // Extract the shared secret
            char *secret = buffer + 16;

            // Check if the secret matches
            if (strcmp(secret, SHARED_SECRET) == 0) {
                printf("Authentication successful\n");

                // Play tones for 5 seconds
                for (int i = 0; i < 50; ++i) {
                    int touch_data[2];
                    if (read_touch_data(touch_data) == 0) {
                        int max_touch_value = 0;
                        for (int j = 0; j < NUM_ELECTRODES; ++j) {
                            if (touch_data[j / 8] & (1 << (j % 8))) {
                                max_touch_value++;
                            }
                        }

                        float frequency = map_touch_data_to_frequency(max_touch_value);
                        play_tone(frequency);

                        // Log the frequency
                        if (log_file != NULL) {
                            fprintf(log_file, "%.2f\n", frequency);
                            fflush(log_file);
                        }
                    } else {
                        fprintf(stderr, "Error reading touch data during playback\n");
                    }
                    gpioDelay(20000); // 20 ms delay
                }

                // Stop PWM
                play_tone(0.0);
            } else {
                fprintf(stderr, "Authentication failed\n");
            }
        }
    } else if (bytes_received == 0) {
        printf("Client disconnected\n");
    } else {
        perror("Error receiving data");
    }

    close(client_socket);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, cleaning up...\n");

    // Stop PWM
    play_tone(0.0);

    // Close I2C
    i2cClose(i2c_handle);

    // Close socket
    close(server_socket);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() != 0) {
        fprintf(stderr, "Error: MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Configure PWM
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, 440); // Initial frequency
    gpioSetPWMrange(PWM_GPIO, 255);

    // Open log file
    log_file = fopen(FREQUENCY_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(SERVER_PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("Server listening on port %d\n", SERVER_PORT);

    // Accept connections and handle them
    while (1) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        int client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket < 0) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        handle_client(client_socket);
    }

    return 0;
}

