#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>
#include <signal.h>
#include <math.h>
#include <errno.h>

// Configuration
#define I2C_BUS 1
#define LSM303_ADDR 0x1E
#define LED_GPIO 17
#define PWM_CHIP 0
#define PWM_NUM 0
#define PWM_PERIOD 1000000 // 1 kHz
#define SAMPLE_INTERVAL_MS 100

// LSM303DLHC Registers
#define CTRL_REG1_M 0x20
#define OUT_X_L_M 0x08

// Global variables
static int i2c_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *led_line = NULL;
static struct gpiod_line *pwm_line = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int initialize_magnetometer(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
int set_led_brightness(double magnitude);
void signal_handler(int sig);
int initialize_gpio(int led_gpio, int pwm_chip, int pwm_num);
int set_pwm_duty_cycle(int duty_cycle);

// I2C read function
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Failed to read data");
        return -1;
    }
    return 0;
}

// I2C write function
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Failed to write byte");
        return -1;
    }
    return 0;
}

// Magnetometer initialization function
int initialize_magnetometer(int fd) {
    // Enable continuous conversion mode (10 Hz)
    if (i2c_write_byte(fd, CTRL_REG1_M, 0x18) < 0) {
        fprintf(stderr, "Error initializing magnetometer\n");
        return -1;
    }
    return 0;
}

// Magnetometer data reading function
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (i2c_read_bytes(fd, OUT_X_L_M, data, 6) < 0) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Magnitude calculation function
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z);
}

// LED brightness control function
int set_led_brightness(double magnitude) {
    // Map magnitude to PWM duty cycle (0-100%)
    int duty_cycle = (int)(magnitude / 1000.0 * 100.0); // Assuming max magnitude of 1000
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    return set_pwm_duty_cycle(duty_cycle);
}

// PWM control function
int set_pwm_duty_cycle(int duty_cycle) {
    if (pwm_line == NULL) {
        fprintf(stderr, "PWM line is not initialized\n");
        return -1;
    }

    // Calculate the period and duty cycle values
    uint64_t period = PWM_PERIOD;
    uint64_t duty_cycle_ns = (uint64_t)((double)period * duty_cycle / 100.0);

    // Set the duty cycle
    if (gpiod_line_set_value(pwm_line, 1) < 0) {
        perror("Failed to set PWM line value (HIGH)");
        return -1;
    }
    usleep(duty_cycle_ns / 1000); // Convert nanoseconds to microseconds

    if (gpiod_line_set_value(pwm_line, 0) < 0) {
        perror("Failed to set PWM line value (LOW)");
        return -1;
    }
    usleep((period - duty_cycle_ns) / 1000); // Convert nanoseconds to microseconds

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// GPIO initialization function
int initialize_gpio(int led_gpio, int pwm_chip, int pwm_num) {
    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Failed to open GPIO chip");
        return -1;
    }

    // Get LED GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, led_gpio);
    if (!led_line) {
        perror("Failed to get LED GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request LED GPIO line for output
    if (gpiod_line_request_output(led_line, "magnetometer-led", 0) < 0) {
        perror("Failed to request LED GPIO line for output");
