    pwm_line = gpiod_chip_get_line(gpio_chip, pwm_num);
    if (!pwm_line) {
        perror("Failed to get PWM GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Request PWM GPIO line for output
    if (gpiod_line_request_output(pwm_line, "magnetometer-pwm", 0) < 0) {
        perror("Failed to request PWM GPIO line for output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    // Set PWM period
    if (gpiod_line_set_period(pwm_line, PWM_PERIOD) < 0) {
        perror("Failed to set PWM period");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

int main() {
