#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron offset window size
#define OFFSET_WINDOW_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold hard-iron offsets
typedef struct {
    int16_t x_offset;
    int16_t y_offset;
    int16_t z_offset;
} offsets_t;

offsets_t offsets = {0, 0, 0};

// Function prototypes
int init_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
void update_offsets(int16_t x, int16_t y, int16_t z);
void apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initialize the HMC5883L sensor
int init_hmc5883l() {
    // Configure register A: 8-average, 15 Hz, normal measurement
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config register A\n");
        return -1;
    }

    // Configure register B: Gain = 1.3 Gauss
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to config register B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        return -1;
    }

    return 0;
}

// Read raw magnetometer data
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Update hard-iron offsets using a running average
void update_offsets(int16_t x, int16_t y, int16_t z) {
    static int offset_index = 0;
    static int16_t x_sum = 0, y_sum = 0, z_sum = 0;

    x_sum -= offsets.x_offset;
    y_sum -= offsets.y_offset;
    z_sum -= offsets.z_offset;

    x_sum += x;
    y_sum += y;
    z_sum += z;

    offsets.x_offset = x_sum / OFFSET_WINDOW_SIZE;
    offsets.y_offset = y_sum / OFFSET_WINDOW_SIZE;
    offsets.z_offset = z_sum / OFFSET_WINDOW_SIZE;

    offset_index = (offset_index + 1) % OFFSET_WINDOW_SIZE;
}

// Apply hard-iron offsets to raw data
void apply_offsets(int16_t raw_x, int16_t raw_y, int16_t raw_z, int16_t *offset_x, int16_t *offset_y, int16_t *offset_z) {
    *offset_x = raw_x - offsets.x_offset;
    *offset_y = raw_y - offsets.y_offset;
    *offset_z = raw_z - offsets.z_offset;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize HMC5883L
    if (init_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_x, raw_y, raw_z;
    int16_t offset_x, offset_y, offset_z;

    // Main loop
    while (!terminate) {
        // Read raw data
        if (read_raw_data(&raw_x, &raw_y, &raw_z) == 0) {
            // Update hard-iron offsets
            update_offsets(raw_x, raw_y, raw_z);

            // Apply offsets
            apply_offsets(raw_x, raw_y, raw_z, &offset_x, &offset_y, &offset_z);

            // Print offset-corrected values
            printf("X: %d, Y: %d, Z: %d\n", offset_x, offset_y, offset_z);
        } else {
            fprintf(stderr, "Failed to read data, retrying...\n");
        }

        // Wait 500 ms
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

