        fprintf(stderr, "Error writing I2C register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// I2C read block function
int i2c_read_block(int fd, uint8_t reg, uint8_t *data, int len) {
    int result = i2c_smbus_read_i2c_block_data(fd, reg | 0x80, len, data);
    if (result < 0) {
        fprintf(stderr, "Error reading I2C block from register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return result;
}

