int init_lsm303d(int fd) {
    // Verify WHO_AM_I register
    int who_am_i = i2c_read_byte(fd, 0x0F);
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: WHO_AM_I register (0x0F) returned 0x%02X, expected 0x49\n", who_am_i);
        return -1;
    }

