    if (i2c_write_byte(fd, 0x20, 0x57) < 0) return -1; // CTRL_REG1: ODR = 50 Hz, X, Y, Z enabled
    if (i2c_write_byte(fd, 0x23, 0x00) < 0) return -1; // CTRL_REG4: +-2g full scale
