#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_GPIO 17
#define SOLENOID_2_GPIO 27

// Define the delay between solenoid activations (in milliseconds)
#define DELAY_MS 500

// Global variable to track program termination for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up and exiting...\n", signal);
    program_running = 0;
}

// Function to initialize the pigpio library and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_GPIO, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_GPIO, PI_OUTPUT);

    // Ensure both solenoids are initially off
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    return 0;
}

// Function to activate a solenoid
void activate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO pin HIGH to activate solenoid
}

// Function to deactivate a solenoid
void deactivate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO pin LOW to deactivate solenoid
}

// Function to introduce a delay
void delay_ms(int milliseconds) {
    gpioDelay(milliseconds * 1000); // pigpioDelay takes microseconds
}

// Function to cleanup GPIO resources and terminate the pigpio library
void cleanup_gpio() {
    // Ensure both solenoids are off before exiting
    gpioWrite(SOLENOID_1_GPIO, 0);
    gpioWrite(SOLENOID_2_GPIO, 0);

    gpioTerminate(); // Terminate pigpio
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    fprintf(stderr, "Solenoid actuator started. Press Ctrl+C to exit.\n");

    // Main loop: Alternate between solenoids
    while (program_running) {
        // Activate solenoid 1
        activate_solenoid(SOLENOID_1_GPIO);
        fprintf(stderr, "Solenoid 1 activated\n");

        // Delay
        delay_ms(DELAY_MS);

        // Deactivate solenoid 1
        deactivate_solenoid(SOLENOID_1_GPIO);
        fprintf(stderr, "Solenoid 1 deactivated\n");

        // Activate solenoid 2
        activate_solenoid(SOLENOID_2_GPIO);
        fprintf(stderr, "Solenoid 2 activated\n");

        // Delay
        delay_ms(DELAY_MS);

        // Deactivate solenoid 2
        deactivate_solenoid(SOLENOID_2_GPIO);
        fprintf(stderr, "Solenoid 2 deactivated\n");
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    fprintf(stderr, "Solenoid actuator stopped.\n");

    return 0;
}

