#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <termios.h>
#include <fcntl.h>
#include <errno.h>

// Define GPIO pins
#define LOCK1_GPIO 17
#define LOCK2_GPIO 27

// Define serial port paths
#define SERIAL1_PORT "/dev/serial0"
#define SERIAL2_PORT "/dev/serial1"

// Define baud rate
#define BAUD_RATE 9600

// Define code length
#define CODE_LENGTH 6

// Define timeout duration (seconds)
#define TIMEOUT_DURATION 5

// Define unlock duration (seconds)
#define UNLOCK_DURATION 2

// Define expected code
#define EXPECTED_CODE "123456"

// Global variables
int serial1_fd = -1;
int serial2_fd = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio();
int init_serial(const char *port);
int read_code(int fd, char *code, int max_length);
int compare_codes(const char *code1, const char *code2);
int unlock_doors();
void lock_doors();
void cleanup();
void signal_handler(int signal);

// Function to initialize GPIO pins
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    lock_doors(); // Ensure doors are locked on startup

    return 0;
}

// Function to initialize serial port
int init_serial(const char *port) {
    int fd = open(port, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        fprintf(stderr, "Failed to open serial port %s: %s\n", port, strerror(errno));
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        fprintf(stderr, "Error from tcgetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, B9600);
    cfsetispeed(&tty, B9600);

    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~PARENB;
    tty.c_cflag &= ~CSTOPB;
    tty.c_cflag &= ~CSIZE;
    tty.c_cflag |= CS8;
    tty.c_lflag &= ~ICANON;
    tty.c_lflag &= ~ECHO;
    tty.c_lflag &= ~ECHOE;
    tty.c_lflag &= ~ECHONL;
    tty.c_lflag &= ~ISIG;
    tty.c_iflag &= ~(IXON | IXOFF | IXANY);
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_oflag &= ~OPOST;
    tty.c_oflag &= ~ONLCR;

    tty.c_cc[VMIN] = 0;  // Non-blocking read
    tty.c_cc[VTIME] = 0; // No timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        fprintf(stderr, "Error from tcsetattr: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read a code from the serial port
int read_code(int fd, char *code, int max_length) {
    fd_set readfds;
    struct timeval timeout;
    int i = 0;
    char c;

    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    timeout.tv_sec = TIMEOUT_DURATION;
    timeout.tv_usec = 0;

    if (select(fd + 1, &readfds, NULL, NULL, &timeout) < 0) {
        fprintf(stderr, "Select error: %s\n", strerror(errno));
        return -1;
    }

    if (FD_ISSET(fd, &readfds)) {
        while (i < max_length) {
            if (read(fd, &c, 1) > 0) {
                if (c >= '0' && c <= '9') {
                    code[i++] = c;
                } else {
                    // Reset the buffer on non-digit character
                    i = 0;
                    break;
                }
            } else {
                break; // No more data available
            }
        }
    } else {
        // Timeout occurred
        return -1;
    }

    code[i] = '\0'; // Null-terminate the string
    return 0;
}

// Function to compare two codes for equality
int compare_codes(const char *code1, const char *code2) {
    if (strlen(code1) != CODE_LENGTH || strlen(code2) != CODE_LENGTH) {
        return 0; // Codes must be of length CODE_LENGTH
    }

