#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <gpiod.h>
#include <time.h>

// Define GPIO pins
#define PIR_GPIO 4
#define RELAY_GPIO 17

// Define chip name
#define GPIOCHIP "gpiochip0"

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define failsafe time in seconds
#define FAILSAFE_TIME 10

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *pir_line;
struct gpiod_line *relay_line;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_gpio(void);
int read_pir_sensor(void);
int control_relay(int state);
void failsafe_shutdown(void);
void signal_handler(int sig);
void cleanup(void);

// Structure to hold GPIO line information
struct gpio_config {
    int gpio;
    const char *name;
    struct gpiod_line *line;
};

// Initialize GPIO lines
int init_gpio(void) {
    struct gpio_config pir_config = {PIR_GPIO, "pir_sensor", NULL};
    struct gpio_config relay_config = {RELAY_GPIO, "relay", NULL};

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        syslog(LOG_ERR, "Failed to open GPIO chip %s", GPIOCHIP);
        return -1;
    }

    // Get PIR line
    pir_line = gpiod_chip_get_line(chip, pir_config.gpio);
    if (!pir_line) {
        syslog(LOG_ERR, "Failed to get PIR line %d", pir_config.gpio);
        gpiod_chip_close(chip);
        return -1;
    }

    // Request PIR line as input
    if (gpiod_line_request_input(pir_line, "motion_sensor") < 0) {
        syslog(LOG_ERR, "Failed to request PIR line as input");
        gpiod_chip_close(chip);
        return -1;
    }

    // Get Relay line
    relay_line = gpiod_chip_get_line(chip, relay_config.gpio);
    if (!relay_line) {
        syslog(LOG_ERR, "Failed to get Relay line %d", relay_config.gpio);
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        return -1;
    }

    // Request Relay line as output
    if (gpiod_line_request_output(relay_line, "relay_control", 0) < 0) {
        syslog(LOG_ERR, "Failed to request Relay line as output");
        gpiod_chip_close(chip);
        gpiod_line_release(pir_line);
        gpiod_line_release(relay_line);
        return -1;
    }

    return 0;
}

// Read PIR sensor value
int read_pir_sensor(void) {
    int value = gpiod_line_get_value(pir_line);
    if (value < 0) {
        syslog(LOG_ERR, "Failed to read PIR sensor value");
        return -1;
    }
    return value;
}

// Control relay state
int control_relay(int state) {
    if (gpiod_line_set_value(relay_line, state) < 0) {
        syslog(LOG_ERR, "Failed to set relay state to %d", state);
        return -1;
    }
    return 0;
}

// Failsafe shutdown procedure
void failsafe_shutdown(void) {
    syslog(LOG_WARNING, "Failsafe triggered: PIR sensor remained HIGH for %d seconds. De-energizing relay.", FAILSAFE_TIME);
    control_relay(0);
    cleanup();
    exit(EXIT_FAILURE);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup GPIO resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up GPIO resources...");

    // De-energize relay
    if (relay_line) {
        control_relay(0);
    }

    // Release GPIO lines
    if (pir_line) {
        gpiod_line_release(pir_line);
    }
    if (relay_line) {
        gpiod_line_release(relay_line);
    }

    // Close GPIO chip
    if (chip) {
        gpiod_chip_close(chip);
    }

    syslog(LOG_INFO, "GPIO resources cleaned up. Exiting.");
}

int main(void) {
    // Open syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (init_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed. Exiting.");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Motion detector started.");

    int pir_state = 0;
    int failsafe_counter = 0;
    struct timespec last_motion_time, current_time;
    clock_gettime(CLOCK_MONOTONIC, &last_motion_time);

    // Main loop
    while (!terminate) {
        int motion_detected = read_pir_sensor();
        if (motion_detected < 0) {
            syslog(LOG_ERR, "Failed to read PIR sensor. Retrying...");
            usleep(100000); // Wait 100ms before retrying
            continue;
        }

        if (motion_detected == 1 && pir_state == 0) {
            // Motion detected
            syslog(LOG_INFO, "Motion detected!");
            control_relay(1); // Energize relay
            pir_state = 1;
            clock_gettime(CLOCK_MONOTONIC, &last_motion_time);
        } else if (motion_detected == 0 && pir_state == 1) {
            // Motion stopped
            syslog(LOG_INFO, "Motion stopped.");
            control_relay(0); // De-energize relay
            pir_state = 0;
        }

        if (pir_state == 1) {
            clock_gettime(CLOCK_MONOTONIC, &current_time);
            double time_diff = (current_time.tv_sec - last_motion_time.tv_sec) + (current_time.tv_nsec - last_motion_time.tv_nsec) / 1e9;
            if (time_diff > FAILSAFE_TIME) {
                failsafe_counter++;
                if (failsafe_counter >= 3) {
                    failsafe_shutdown();
                }
            } else {
                failsafe_counter = 0;
            }
        }

        usleep(DEBOUNCE_TIME * 1000); // Debounce
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return EXIT_SUCCESS;
}

