#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define relay activation and deactivation times (in seconds)
#define RELAY_ACTIVATION_TIME 300 // 5 minutes
#define RELAY_DEACTIVATION_TIME 60 // 1 minute
#define PAUSE_TIME 60             // 1 minute

// Define the number of relays
#define NUM_RELAYS 4

// Enum for relay states
enum {
    OFF,
    ON
};

// Enum for relay actions
enum {
    ACTIVATE,
    DEACTIVATE,
    PAUSE
};

// Structure to hold relay state and action
typedef struct {
    int state;
    int action;
} RelayState;

// Global array to store relay states
RelayState relays[NUM_RELAYS];

// Global variable to track the current relay index
int current_relay = 0;

// Global variable to track the current action
int current_action = ACTIVATE;

// Global variable to track the timer ID
int timer_id = 0;

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Function prototypes
void initialize_relays();
void activate_relay(int relay_pin);
void deactivate_relay(int relay_pin);
void timer_callback(int timer_id);
void signal_handler(int signal);

// Function to initialize the relays to OFF (HIGH)
void initialize_relays() {
    for (int i = 0; i < NUM_RELAYS; i++) {
        gpioSetMode(i == 0 ? RELAY1_PIN : (i == 1 ? RELAY2_PIN : (i == 2 ? RELAY3_PIN : RELAY4_PIN)), PI_OUTPUT);
        gpioWrite(i == 0 ? RELAY1_PIN : (i == 1 ? RELAY2_PIN : (i == 2 ? RELAY3_PIN : RELAY4_PIN)), 1); // Set HIGH (OFF)
        relays[i].state = OFF;
        relays[i].action = PAUSE; // Initialize all relays to PAUSE
    }
