#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_CONFIG 0x1C
#define ACCEL_XOUT_H 0x3B

// Accelerometer range
#define ACCEL_RANGE_2G 0x00

// Circular buffer size
#define BUFFER_SIZE 100

// Sysfs path
#define SYSFS_PATH "/sys/kernel/mpu6050_accel"

// Global variables
static int i2c_fd = -1;
static int timer_id = -1;
static volatile sig_atomic_t program_running = 1;

// Structure to hold accelerometer data
typedef struct {
    double x;
    double y;
    double z;
} accelerometer_data_t;

// Circular buffer
accelerometer_data_t circular_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int i2c_open(const char *device);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len);
int mpu6050_init(int fd);
int read_accelerometer_data(int fd, accelerometer_data_t *data);
void timer_callback(union sigval sv);
void signal_handler(int sig);
int create_sysfs_entry(const char *path);
int remove_sysfs_entry(const char *path);
int read_latest_data(accelerometer_data_t *data);

// I2C open function
int i2c_open(const char *device) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }
    return fd;
}

// I2C write register function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        perror("Error writing to I2C device");
        return -1;
    }
    return 0;
}

// I2C read registers function
int i2c_read_regs(int fd, uint8_t reg, uint8_t *data, int len) {
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }
    if (read(fd, data, len) != len) {
        perror("Error reading from I2C device");
        return -1;
    }
    return 0;
}

// MPU6050 initialization function
int mpu6050_init(int fd) {
    // Wake up the MPU6050
    if (i2c_write_reg(fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error waking up MPU6050\n");
        return -1;
    }

    // Set accelerometer range to +-2g
    if (i2c_write_reg(fd, ACCEL_CONFIG, ACCEL_RANGE_2G) < 0) {
        fprintf(stderr, "Error setting accelerometer range\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data function
int read_accelerometer_data(int fd, accelerometer_data_t *data) {
    uint8_t raw_data[6];

    if (i2c_read_regs(fd, ACCEL_XOUT_H, raw_data, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }

    // Combine high and low bytes, and scale to g
    int16_t x = (raw_data[0] << 8) | raw_data[1];
    int16_t y = (raw_data[2] << 8) | raw_data[3];
    int16_t z = (raw_data[4] << 8) | raw_data[5];

    data->x = (double)x / 16384.0;
    data->y = (double)y / 16384.0;
    data->z = (double)z / 16384.0;

    return 0;
}

// Timer callback function
void timer_callback(union sigval sv) {
    static struct timespec last_time = {0, 0};
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Calculate the time difference since the last call
    long time_diff_ns = (current_time.tv_sec - last_time.tv_sec) * 1000000000L + (current_time.tv_nsec - last_time.tv_nsec);

    // Calculate the delay needed to achieve 100 Hz
    long delay_ns = 10000000 - time_diff_ns; // 10 ms = 10000000 ns

    // Convert delay to seconds and nanoseconds
    long delay_sec = delay_ns / 1000000000L;
    long delay_nsec = delay_ns % 1000000000L;

    struct timespec delay_time;
    delay_time.tv_sec = delay_sec;
    delay_time.tv_nsec = delay_nsec;

    // Wait for the specified delay
    nanosleep(&delay_time, NULL);

    // Read accelerometer data
    accelerometer_data_t data;
    if (read_accelerometer_data(i2c_fd, &data) == 0) {
        // Store data in circular buffer
        circular_buffer[buffer_index] = data;
        buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    } else {
        fprintf(stderr, "Error reading accelerometer data in timer callback\n");
    }

    // Update last call time
    last_time = current_time;
}

// Signal handler function
void signal_handler(int sig) {
    program_running = 0;
    printf("Caught signal %d, exiting...\n", sig);
}

// Create sysfs entry function
int create_sysfs_entry(const char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        perror("Error creating sysfs entry");
        return -1;
    }
    fclose(fp);
    return 0;
}

// Remove sysfs entry function
int remove_sysfs_entry(const char *path) {
    if (remove(path) != 0) {
        perror("Error removing sysfs entry");
        return -1;
    }
    return 0;
}

// Read latest data function
int read_latest_data(accelerometer_data_t *data) {
    // Calculate the index of the latest data in the circular buffer
    int latest_index = (buffer_index - 1 + BUFFER_SIZE) % BUFFER_SIZE;

    // Copy the latest data to the provided buffer
    *data = circular_buffer[latest_index];

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = i2c_open("/dev/i2c-1");
    if (i2c_fd < 0) {
        return 1;
    }

    // Initialize MPU6050
    if (mpu6050_init(i2c_fd) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Create sysfs entry
    if (create_sysfs_entry(SYSFS_PATH) < 0) {
        close(i2c_fd);
        return 1;
    }

    // Set up timer
    struct sigevent sev;
    struct itimerspec its;

    sev.sigev_notify = SIGEV_THREAD;
    sev.sigev_notify_function = timer_callback;
    sev.sigev_value.sival_ptr = &i2c_fd; // Pass I2C file descriptor to the callback

    if (timer_create(CLOCK_MONOTONIC, &sev, &timer_id) < 0) {
        perror("Error creating timer");
        remove_sysfs_entry(SYSFS_PATH);
        close(i2c_fd);
        return 1;
    }

    // Configure timer interval (10ms = 100Hz)
    its.it_value.tv_sec = 0;
    its.it_value.tv_nsec = 10000000; // 10ms
    its.it_interval.tv_sec = 0;
    its.it_interval.tv_nsec = 10000000; // 10ms

    // Start the timer
    if (timer_settime(timer_id, 0, &its, NULL) < 0) {
        perror("Error starting timer");
        timer_delete(timer_id);
        remove_sysfs_entry(SYSFS_PATH);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (program_running) {
        pause(); // Wait for a signal
    }

    // Clean up
    timer_delete(timer_id);
    remove_sysfs_entry(SYSFS_PATH);
    close(i2c_fd);

    return 0;
}

