#include <gpiod.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>

// Define GPIO pins (BCM numbering)
#define GPIO_18 18
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

// Define prime number intervals (in seconds)
#define INTERVAL_1 2
#define INTERVAL_2 3
#define INTERVAL_3 5
#define INTERVAL_4 7

// Define the number of lights
#define NUM_LIGHTS 4

// Structure to hold GPIO lines and chip
struct gpio_state {
    struct gpiod_chip *chip;
    struct gpiod_line *lines[NUM_LIGHTS];
};

// Global variable to store the GPIO state
struct gpio_state gpio_data;

// Function prototypes
int initialize_gpio(struct gpio_state *state);
void cleanup_gpio(struct gpio_state *state);
void signal_handler(int sig);
int set_relay_state(struct gpio_state *state, int line_index, int state);
int get_relay_state(struct gpio_state *state, int line_index);
int toggle_relay(struct gpio_state *state, int line_index);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio(&gpio_data);
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpio_state *state) {
    int chip_num = 0; // Default GPIO chip number
    char chip_name[20];
    snprintf(chip_name, sizeof(chip_name), "gpiochip%d", chip_num);

    state->chip = gpiod_chip_open_by_name(chip_name);
    if (!state->chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    int lines[NUM_LIGHTS] = {GPIO_18, GPIO_23, GPIO_24, GPIO_25};
    int flags = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;

    for (int i = 0; i < NUM_LIGHTS; i++) {
        state->lines[i] = gpiod_chip_get_line(state->chip, lines[i]);
        if (!state->lines[i]) {
            perror("Error getting GPIO line");
            cleanup_gpio(state);
            return -1;
        }

        int ret = gpiod_line_request(state->lines[i], NULL, flags);
        if (ret < 0) {
            perror("Error requesting GPIO line");
            cleanup_gpio(state);
            return -1;
        }
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(struct gpio_state *state) {
    if (state->chip) {
        for (int i = 0; i < NUM_LIGHTS; i++) {
            if (state->lines[i]) {
                gpiod_line_release(state->lines[i]);
            }
        }
        gpiod_chip_close(state->chip);
    }
}

// Function to set the state of a relay
int set_relay_state(struct gpio_state *state, int line_index, int state) {
    if (line_index < 0 || line_index >= NUM_LIGHTS) {
        fprintf(stderr, "Error: Invalid line index: %d\n", line_index);
        return -1;
    }

    int ret = gpiod_line_set_value(state->lines[line_index], state);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to get the state of a relay
int get_relay_state(struct gpio_state *state, int line_index) {
    if (line_index < 0 || line_index >= NUM_LIGHTS) {
        fprintf(stderr, "Error: Invalid line index: %d\n", line_index);
        return -1;
    }

    int value = gpiod_line_get_value(state->lines[line_index]);
    if (value < 0) {
        perror("Error getting GPIO line value");
        return -1;
    }
    return value;
}

// Function to toggle the state of a relay
int toggle_relay(struct gpio_state *state, int line_index) {
    int current_state = get_relay_state(state, line_index);
    if (current_state < 0) {
        return -1;
    }

    int new_state = !current_state;
    return set_relay_state(state, line_index, new_state);
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&gpio_data) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Smart Lighting System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Light 1 (GPIO 18) - 2 seconds
        if (toggle_relay(&gpio_data, 0) < 0) {
            fprintf(stderr, "Error toggling light 1.\n");
        }
        sleep(INTERVAL_1);

        // Light 2 (GPIO 23) - 3 seconds
        if (toggle_relay(&gpio_data, 1) < 0) {
            fprintf(stderr, "Error toggling light 2.\n");
        }
        sleep(INTERVAL_2);

        // Light 3 (GPIO 24) - 5 seconds
        if (toggle_relay(&gpio_data, 2) < 0) {
            fprintf(stderr, "Error toggling light 3.\n");
        }
        sleep(INTERVAL_3);

        // Light 4 (GPIO 25) - 7 seconds
        if (toggle_relay(&gpio_data, 3) < 0) {
            fprintf(stderr, "Error toggling light 4.\n");
        }
        sleep(INTERVAL_4);
    }

    return 0;
}

