#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define ALARM_DURATION_MS 3000
#define DEBOUNCE_DELAY_MS 500
#define POLL_INTERVAL_MS 100

// Global variables
static volatile int running = 1;
static volatile unsigned long last_alarm_time = 0;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int deactivate_relay();
int log_alarm();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sound_sensor_pin;
    int relay_pin;
} gpio_config_t;

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Read the sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Activate the relay for 3 seconds
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Turn relay ON
    gpioDelay(ALARM_DURATION_MS);
    gpioWrite(RELAY_PIN, 0); // Turn relay OFF
    return 0;
}

// Deactivate the relay
int deactivate_relay() {
    gpioWrite(RELAY_PIN, 0);
    return 0;
}

// Log the alarm event to a file
int log_alarm() {
    FILE *fp = fopen("alarm_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alarm_log.txt for writing\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s: Alarm triggered\n", timestamp);
    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    deactivate_relay();
    gpioTerminate();
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            unsigned long current_time = gpioTick();
            if (current_time - last_alarm_time > DEBOUNCE_DELAY_MS * 1000) {
                printf("Sound detected! Activating alarm.\n");
                activate_relay();
                log_alarm();
                last_alarm_time = current_time;
            }
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    return 0;
}

