#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define WHO_AM_I     0x75
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Gyroscope sensitivity (LSB/deg/s)
#define GYRO_SENSITIVITY 131.0

// Circular buffer size
#define BUFFER_SIZE 100

// Angular velocity threshold (deg/s)
#define ANGULAR_VELOCITY_THRESHOLD 50.0

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Circular buffer structure
typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_fd;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_init(int address);
int mpu6050_init();
int read_gyro_data(gyro_data_t *data);
void buffer_init(circular_buffer_t *buffer);
void buffer_add(circular_buffer_t *buffer, gyro_data_t data);
int buffer_is_full(const circular_buffer_t *buffer);
void callback_function(const gyro_data_t *data);
void signal_handler(int signal);

// I2C initialization function
int i2c_init(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// MPU-6050 initialization function
int mpu6050_init() {
    // Wake up the MPU-6050
    uint8_t wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(i2c_fd, wake_up_data, 2) != 2) {
        perror("Error waking up MPU-6050");
        return -1;
    }

    // Verify WHO_AM_I register
    uint8_t who_am_i_data[2] = {WHO_AM_I, 0x00};
    if (write(i2c_fd, who_am_i_data, 1) != 1) {
        perror("Error writing to WHO_AM_I register");
        return -1;
    }

    uint8_t who_am_i_read[1] = {0x00};
    if (read(i2c_fd, who_am_i_read, 1) != 1) {
        perror("Error reading WHO_AM_I register");
        return -1;
    }

    if (who_am_i_read[0] != 0x68) {
        fprintf(stderr, "WHO_AM_I register returned 0x%02X, expected 0x68\n", who_am_i_read[0]);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    uint8_t gyro_data[6];

    // Read all 6 bytes at once
    if (read(i2c_fd, gyro_data, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes for each axis
    data->x = (int16_t)((gyro_data[0] << 8) | gyro_data[1]);
    data->y = (int16_t)((gyro_data[2] << 8) | gyro_data[3]);
    data->z = (int16_t)((gyro_data[4] << 8) | gyro_data[5]);

    return 0;
}

// Circular buffer initialization function
void buffer_init(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Circular buffer add function
void buffer_add(circular_buffer_t *buffer, gyro_data_t data) {
    buffer->data[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Circular buffer is full function
int buffer_is_full(const circular_buffer_t *buffer) {
    return buffer->count == BUFFER_SIZE;
}

// Callback function
void callback_function(const gyro_data_t *data) {
    printf("Angular velocity threshold exceeded: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n",
           (double)data->x / GYRO_SENSITIVITY,
           (double)data->y / GYRO_SENSITIVITY,
           (double)data->z / GYRO_SENSITIVITY);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize I2C
    i2c_fd = i2c_init(MPU6050_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (mpu6050_init() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Initialize circular buffer
    buffer_init(&gyro_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("MPU-6050 gyroscope data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        gyro_data_t gyro_data;

        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Add data to circular buffer
            buffer_add(&gyro_buffer, gyro_data);

            // Calculate angular velocity magnitude
            double magnitude = sqrt(
                (double)gyro_data.x * gyro_data.x / (GYRO_SENSITIVITY * GYRO_SENSITIVITY) +
                (double)gyro_data.y * gyro_data.y / (GYRO_SENSITIVITY * GYRO_SENSITIVITY) +
                (double)gyro_data.z * gyro_data.z / (GYRO_SENSITIVITY * GYRO_SENSITIVITY)
            );

            // Check if threshold is exceeded
            if (magnitude > ANGULAR_VELOCITY_THRESHOLD) {
                callback_function(&gyro_data);
            }
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying.\n");
        }

        // Delay for a short period
        usleep(10000); // 10 milliseconds
    }

    // Close I2C device
    close(i2c_fd);

    printf("Program terminated.\n");

    return 0;
}

