#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE 9600
#define CO2_READ_COMMAND {0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79}
#define CO2_READ_COMMAND_LENGTH 9
#define CO2_RESPONSE_LENGTH 9
#define CO2_LOG_FILE "co2_log.json"
#define CO2_ERROR_LOG_FILE "co2_error.log"
#define TIMEOUT_MS 1000

int uart_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold CO2 data
typedef struct {
    long long timestamp_us;
    int co2_ppm;
    int error_flag;
} CO2Data;

// Function prototypes
int initialize_pigpio();
int open_uart();
int send_co2_read_command();
int read_co2_response(unsigned char *response);
int validate_checksum(const unsigned char *response);
int extract_co2_ppm(const unsigned char *response);
int log_co2_data(long long timestamp_us, int co2_ppm, int error_flag);
void print_co2_data_json(long long timestamp_us, int co2_ppm, int error_flag);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

int main() {
    unsigned char response[CO2_RESPONSE_LENGTH];
    int co2_ppm;
    long long timestamp_us;
    int error_flag = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open UART
    if (open_uart() != 0) {
        log_error("Failed to open UART.");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(CO2_LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open co2_log.json");
        log_error("Failed to open co2_log.json.");
        cleanup();
        return 1;
    }

    // Open error log file
    error_log_file = fopen(CO2_ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Failed to open co2_error.log");
        log_error("Failed to open co2_error.log.");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Send CO2 read command
        if (send_co2_read_command() != 0) {
            log_error("Failed to send CO2 read command.");
            error_flag = 1;
        } else {
            // Read CO2 response
            if (read_co2_response(response) != 0) {
                log_error("Failed to read CO2 response.");
                error_flag = 1;
            } else {
                // Validate checksum
                if (validate_checksum(response) != 0) {
                    log_error("Checksum validation failed.");
                    error_flag = 1;
                } else {
                    // Extract CO2 PPM
                    co2_ppm = extract_co2_ppm(response);

                    // Get timestamp
                    struct timespec ts;
                    clock_gettime(CLOCK_REALTIME, &ts);
                    timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

                    // Log CO2 data
                    if (log_co2_data(timestamp_us, co2_ppm, error_flag) != 0) {
                        log_error("Failed to log CO2 data.");
                    }

                    // Print CO2 data to stdout
                    print_co2_data_json(timestamp_us, co2_ppm, error_flag);

                    error_flag = 0; // Reset error flag
                }
            }
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup
    cleanup();

    return 0;
}

// Initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Open UART
int open_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Failed to open UART: %s\n", UART_DEVICE);
        return 1;
    }
    return 0;
}

// Send CO2 read command
int send_co2_read_command() {
    if (serWrite(uart_handle, CO2_READ_COMMAND, CO2_READ_COMMAND_LENGTH) != CO2_READ_COMMAND_LENGTH) {
        fprintf(stderr, "Failed to write CO2 read command\n");
        return 1;
    }
    gpioDelay(100); // Wait 100 ms
    return 0;
}

// Read CO2 response
int read_co2_response(unsigned char *response) {
    int bytes_read = 0;
    int start_time = gpioTick();

    while (bytes_read < CO2_RESPONSE_LENGTH && (gpioTick() - start_time) < TIMEOUT_MS * 1000) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int result = serRead(uart_handle, response + bytes_read, available);
            if (result > 0) {
                bytes_read += result;
            } else {
                fprintf(stderr, "Error reading from UART: %d\n", result);
                return 1;
            }
        } else {
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
    }

    if (bytes_read != CO2_RESPONSE_LENGTH) {
        fprintf(stderr, "Timeout reading CO2 response\n");
        return 1;
    }

    return 0;
}

// Validate checksum
int validate_checksum(const unsigned char *response) {
    unsigned char checksum = 0;
    for (int i = 1; i < 7; i++) {
        checksum += response[i];
    }
    checksum = 0xFF - checksum + 1;
    if (checksum != response[8]) {
        fprintf(stderr, "Checksum mismatch: expected 0x%02X, got 0x%02X\n", response[8], checksum);
        return 1;
    }
    return 0;
}

// Extract CO2 PPM
int extract_co2_ppm(const unsigned char *response) {
    return (response[2] << 8) | response[3];
}

// Log CO2 data
int log_co2_data(long long timestamp_us, int co2_ppm, int error_flag) {
    if (fprintf(log_file, "{\"timestamp_us\": %lld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_us, co2_ppm, error_flag) < 0) {
        perror("Failed to write to co2_log.json");
        return 1;
    }
    fflush(log_file);
    return 0;
}

// Print CO2 data to stdout in JSON format
void print_co2_data_json(long long timestamp_us, int co2_ppm, int error_flag) {
    printf("{\"timestamp_us\": %lld, \"co2_ppm\": %d, \"error_flag\": %d}\n", timestamp_us, co2_ppm, error_flag);
}

// Log error messages
void log_error(const char *message) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long long timestamp_us = (long long)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;

    fprintf(error_log_file, "%lld: %s\n", timestamp_us, message);
    fflush(error_log_file);
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }
    gpioTerminate();
}

