#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03

// GPIO pin for output
#define GPIO_PIN 17

// Target heading
#define TARGET_HEADING 90.0

// Hard-iron offsets
#define X_OFFSET 100.0
#define Y_OFFSET -50.0

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer heading_buffer;

// Function prototypes
int initialize_hmc5883l();
int read_raw_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_heading(int16_t x, int16_t y);
void add_to_buffer(float heading);
float get_average_heading();
void signal_handler(int signal);

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a new heading to the circular buffer
void add_to_buffer(float heading) {
    heading_buffer.buffer[heading_buffer.head] = heading;
    heading_buffer.head = (heading_buffer.head + 1) % BUFFER_SIZE;
    if (heading_buffer.count < BUFFER_SIZE) {
        heading_buffer.count++;
    }
}

// Calculate the average heading from the circular buffer
float get_average_heading() {
    if (heading_buffer.count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < heading_buffer.count; i++) {
        sum += heading_buffer.buffer[i];
    }
    return sum / heading_buffer.count;
}

// Initialize the HMC5883L sensor
int initialize_hmc5883l() {
    // Set configuration register A
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A register\n");
        return -1;
    }

    // Set configuration register B
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B register\n");
        return -1;
    }

    // Set mode register
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE register\n");
        return -1;
    }

    return 0;
}

// Read raw data from the HMC5883L sensor
int read_raw_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) < 0) {
        fprintf(stderr, "Error reading data from HMC5883L\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate the compensated heading
float calculate_heading(int16_t x, int16_t y) {
    float heading = atan2((float)y - Y_OFFSET, (float)x - X_OFFSET) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

