#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PWM range (0-255)
#define PWM_RANGE 255

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, stopping motors and cleaning up...\n");
}

// Function to set motor direction and PWM duty cycle
void set_motor_direction(int in1_pin, int in2_pin, int pwm_pin, int distance) {
    if (distance < 50) {
        // Forward
        gpioWrite(in1_pin, 1);
        gpioWrite(in2_pin, 0);

        // Map distance to PWM duty cycle (0-255)
        int duty_cycle = (int)(((float)(distance - 10) / (100 - 10)) * 255);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        gpioPWM(pwm_pin, duty_cycle);
    } else {
        // Backward
        gpioWrite(in1_pin, 0);
        gpioWrite(in2_pin, 1);

        // Map distance to PWM duty cycle (0-255)
        int duty_cycle = (int)(((float)(distance - 50) / (100 - 50)) * 255);
        if (duty_cycle < 0) duty_cycle = 0;
        if (duty_cycle > 255) duty_cycle = 255;

        gpioPWM(pwm_pin, duty_cycle);
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY);
