#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

// Servo PWM GPIO pin (WiringPi pin number)
#define SERVO_PIN 18

// PWM chip and channel
#define PWM_CHIP 2
#define PWM_CHANNEL 0

// PWM period (in nanoseconds)
#define PWM_PERIOD 20000000 // 20ms

// PWM duty cycle range (in nanoseconds)
#define PWM_DUTY_MIN 1000000
#define PWM_DUTY_MAX 1900000

// Servo angle range (degrees)
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

// Log file path
#define LOG_FILE "solar_tracker.log"

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int address);
int init_mpu6050(int fd);
int read_mpu6050_data(int fd, float *pitch, float *roll);
int set_servo_angle(int angle);
int log_data(float pitch, float roll, int servo_angle);
void signal_handler(int signal);

// I2C initialization function with exponential backoff
int init_i2c(int address) {
    int fd = -1;
    int retries = 0;
    const int max_retries = 5;
    const int delay_ms = 10;

    while (retries < max_retries) {
        fd = wiringPiI2CSetup(address);
        if (fd != -1) {
            return fd;
        }

        fprintf(stderr, "I2C initialization failed (attempt %d/%d): %s\n", retries + 1, max_retries, strerror(errno));
        retries++;
        delay(delay_ms * (1 << retries)); // Exponential backoff
    }

    fprintf(stderr, "I2C initialization failed after %d retries.\n", max_retries);
    return -1;
}

// MPU-6050 initialization function
int init_mpu6050(int fd) {
    // Wake up the MPU-6050 (clear sleep bit)
    if (wiringPiI2CWriteReg8(fd, MPU6050_PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Error writing to PWR_MGMT_1 register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read accelerometer and gyroscope data
int read_mpu6050_data(int fd, float *pitch, float *roll) {
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;

    // Read accelerometer data
    accel_x = wiringPiI2CReadReg16(fd, MPU6050_ACCEL_XOUT_H);
    accel_y = wiringPiI2CReadReg16(fd, MPU6050_ACCEL_XOUT_H + 2);
    accel_z = wiringPiI2CReadReg16(fd, MPU6050_ACCEL_XOUT_H + 4);

    // Read gyroscope data
    gyro_x = wiringPiI2CReadReg16(fd, MPU6050_GYRO_XOUT_H);
    gyro_y = wiringPiI2CReadReg16(fd, MPU6050_GYRO_XOUT_H + 2);
    gyro_z = wiringPiI2CReadReg16(fd, MPU6050_GYRO_XOUT_H + 4);

    if (accel_x == -1 || accel_y == -1 || accel_z == -1 || gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
        fprintf(stderr, "Error reading MPU-6050 data: %s\n", strerror(errno));
        return -1;
    }

    // Convert to signed 16-bit integers
    accel_x = (int16_t)accel_x;
    accel_y = (int16_t)accel_y;
    accel_z = (int16_t)accel_z;
    gyro_x = (int16_t)gyro_x;
    gyro_y = (int16_t)gyro_y;
    gyro_z = (int16_t)gyro_z;

    // Calculate pitch and roll (simplified)
    *pitch = atan2(accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
    *roll = atan2(accel_y, sqrt(accel_x * accel_x + accel_z * accel_z)) * 180 / M_PI;

    return 0;
}

// Function to set the servo angle using PWM
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    // Calculate duty cycle based on angle
    int duty_cycle = PWM_DUTY_MIN + (int)(((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (PWM_DUTY_MAX - PWM_DUTY_MIN));

    // Set the PWM duty cycle
    char duty_cycle_str[20];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);

    char path[100];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);

    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error opening duty_cycle file: %s\n", strerror(errno));
        return -1;
    }

    if (fwrite(duty_cycle_str, 1, strlen(duty_cycle_str), fp) != strlen(duty_cycle_str)) {
        fprintf(stderr, "Error writing to duty_cycle file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    return 0;
}

// Function to log data to a file
int log_data(float pitch, float roll, int servo_angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, servo_angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    float pitch, roll;
    int servo_angle;

    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(MPU6050_ADDR);
    if (i2c_fd == -1) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) == -1) {
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(i2c_fd);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export PWM channel
    char path[100];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    FILE *export_fp = fopen(path, "w");
    if (export_fp == NULL) {
        fprintf(stderr, "Error opening PWM export file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    fprintf(export_fp, "%d", PWM_CHANNEL);
    fclose(export_fp);

    // Set PWM period
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    FILE *period_fp = fopen(path, "w");
    if (period_fp == NULL) {
        fprintf(stderr, "Error opening PWM period file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    fprintf(period_fp, "%d", PWM_PERIOD);
    fclose(period_fp);

    // Set PWM enable
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *enable_fp = fopen(path, "w");
    if (enable_fp == NULL) {
        fprintf(stderr, "Error opening PWM enable file: %s\n", strerror(errno));
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }
    fprintf(enable_fp, "1");
    fclose(enable_fp);

    // Main loop
    while (program_running) {
        // Read sensor data
        if (read_mpu6050_data(i2c_fd, &pitch, &roll) == 0) {
            // Calculate servo angle (example mapping)
            servo_angle = (int)(pitch * 1.5); // Map pitch to servo angle
            if (servo_angle < SERVO_MIN_ANGLE) servo_angle = SERVO_MIN_ANGLE;
            if (servo_angle > SERVO_MAX_ANGLE) servo_angle = SERVO_MAX_ANGLE;

            // Set servo angle
            if (set_servo_angle(servo_angle) == 0) {
                // Log data
                log_data(pitch, roll, servo_angle);
            } else {
                fprintf(stderr, "Error setting servo angle.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        delay(100); // Delay for 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");

    // Disable PWM
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    FILE *disable_fp = fopen(path, "w");
    if (disable_fp != NULL) {
        fprintf(disable_fp, "0");
        fclose(disable_fp);
    }

    // Unexport PWM channel
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
    export_fp = fopen(path, "w");
    if (export_fp != NULL) {
        fprintf(export_fp, "%d", PWM_CHANNEL);
