#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-100)
#define PWM_RANGE 100

// Define sunrise/sunset transition time (seconds)
#define TRANSITION_TIME 1800

// Define the schedule file name
#define SCHEDULE_FILE "lighting_schedule.txt"

// Structure to represent a schedule entry
typedef struct {
    int hour;
    int minute;
    int second;
    int relay_number;
    int on_off;
} schedule_entry_t;

// Global variables
static volatile int running = 1;
static FILE *schedule_file = NULL;
static schedule_entry_t *schedule = NULL;
static int schedule_size = 0;

// Function prototypes
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size);
int validate_schedule(const schedule_entry_t *schedule, int schedule_size);
void signal_handler(int signal);
void turn_off_all_relays();
void turn_on_relay(int relay_number, int brightness);
void turn_off_relay(int relay_number);
void fade_brightness(int relay_number, int target_brightness, int transition_time);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
    turn_off_all_relays();
    gpioTerminate();
    if (schedule_file != NULL) {
        fclose(schedule_file);
    }
    if (schedule != NULL) {
        free(schedule);
    }
    exit(0);
}

// Function to turn off all relays
void turn_off_all_relays() {
    turn_off_relay(RELAY1_PIN);
    turn_off_relay(RELAY2_PIN);
    turn_off_relay(RELAY3_PIN);
    turn_off_relay(RELAY4_PIN);
}

// Function to turn on a relay with PWM brightness control
void turn_on_relay(int relay_number, int brightness) {
    gpioWrite(relay_number, 1); // Turn on the relay
    gpioPWM(relay_number, brightness); // Set PWM duty cycle
}

// Function to turn off a relay
void turn_off_relay(int relay_number) {
    gpioWrite(relay_number, 0); // Turn off the relay
    gpioPWM(relay_number, 0); // Set PWM duty cycle to 0
}

// Function to fade the brightness of a relay over a given time
void fade_brightness(int relay_number, int target_brightness, int transition_time) {
    int current_brightness = 0;
    int step = (target_brightness > current_brightness) ? 1 : -1;
    int num_steps = (target_brightness - current_brightness) / step;
    if (num_steps == 0) num_steps = 1; // Ensure at least one step

    for (int i = 0; i <= num_steps; ++i) {
        current_brightness += step;
        if (current_brightness < 0) current_brightness = 0;
        if (current_brightness > PWM_RANGE) current_brightness = PWM_RANGE;
        gpioPWM(relay_number, current_brightness);
        gpioDelay(transition_time / num_steps); // Delay for each step
    }
}

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, schedule_entry_t **schedule, int *schedule_size) {
    schedule_file = fopen(filename, "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    // Determine the number of lines in the file
    int line_count = 0;
    char ch;
    while ((ch = fgetc(schedule_file)) != EOF) {
        if (ch == '\n') {
            line_count++;
        }
    }
    fseek(schedule_file, 0, SEEK_SET); // Reset file pointer to the beginning

    *schedule_size = line_count;
    *schedule = (schedule_entry_t *)malloc(line_count * sizeof(schedule_entry_t));
    if (*schedule == NULL) {
        perror("Error allocating memory for schedule");
        fclose(schedule_file);
        return -1;
    }

    char line[256];
    for (int i = 0; i < line_count; ++i) {
        if (fgets(line, sizeof(line), schedule_file) == NULL) {
            fprintf(stderr, "Error reading line %d from schedule file\n", i + 1);
            free(*schedule);
            fclose(schedule_file);
            return -1;
        }

        if (sscanf(line, "%d:%d:%d,%d,%d", &((*schedule)[i].hour), &((*schedule)[i].minute), &((*schedule)[i].second), &((*schedule)[i].relay_number), &((*schedule)[i].on_off)) != 5) {
            fprintf(stderr, "Error parsing line %d from schedule file: %s", i + 1, line);
            free(*schedule);
            fclose(schedule_file);
            return -1;
        }
    }

    fclose(schedule_file);
    return 0;
}

// Function to validate the schedule entries
int validate_schedule(const schedule_entry_t *schedule, int schedule_size) {
    for (int i = 0; i < schedule_size; ++i) {
        if (schedule[i].hour < 0 || schedule[i].hour > 23 ||
            schedule[i].minute < 0 || schedule[i].minute > 59 ||
            schedule[i].second < 0 || schedule[i].second > 59 ||
            schedule[i].relay_number < 1 || schedule[i].relay_number > 4 ||
            (schedule[i].on_off != 0 && schedule[i].on_off != 1)) {
            fprintf(stderr, "Invalid schedule entry at index %d: %d:%d:%d,%d,%d\n",
                    i, schedule[i].hour, schedule[i].minute, schedule[i].second, schedule[i].relay_number, schedule[i].on_off);
            return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    // Read the lighting schedule
    if (read_schedule(SCHEDULE_FILE, &schedule, &schedule_size) != 0) {
        fprintf(stderr, "Failed to read schedule\n");
        gpioTerminate();
        return 1;
    }

    // Validate the schedule
    if (validate_schedule(schedule, schedule_size) != 0) {
        fprintf(stderr, "Schedule contains invalid entries\n");
        free(schedule);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        int current_hour = time_info->tm_hour;
        int current_minute = time_info->tm_min;
        int current_second = time_info->tm_sec;

        for (int i = 0; i < schedule_size; ++i) {
            if (schedule[i].hour == current_hour &&
                schedule[i].minute == current_minute &&
                schedule[i].second == current_second) {

                int relay_number = schedule[i].relay_number;
                int on_off = schedule[i].on_off;

                if (on_off == 1) {
                    // Sunrise/sunset effect
                    for (int brightness = 0; brightness <= PWM_RANGE; ++brightness) {
                        turn_on_relay(relay_number, brightness);
                        gpioDelay(TRANSITION_TIME / PWM_RANGE);
                    }
                } else {
                    // Turn off the relay
                    turn_off_relay(relay_number);
                }
            }
        }

        gpioDelay(1000); // Check every second
    }

    // Clean up and exit
    turn_off_all_relays();
    gpioTerminate();
    free(schedule);
    return 0;
}

