    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range
    gpioSetPWMrange(RELAY1_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY2_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY3_PIN, PWM_RANGE);
    gpioSetPWMrange(RELAY4_PIN, PWM_RANGE);

    // Read the lighting schedule
    if (read_schedule(SCHEDULE_FILE, &schedule, &schedule_size) != 0) {
        fprintf(stderr, "Failed to read schedule\n");
        gpioTerminate();
        return 1;
    }

    // Validate the schedule
    if (validate_schedule(schedule, schedule_size) != 0) {
        fprintf(stderr, "Schedule contains invalid entries\n");
        free(schedule);
        gpioTerminate();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        struct tm *time_info = localtime(&current_time);
        int current_hour = time_info->tm_hour;
        int current_minute = time_info->tm_min;
        int current_second = time_info->tm_sec;

        for (int i = 0; i < schedule_size; ++i) {
            if (schedule[i].hour == current_hour &&
                schedule[i].minute == current_minute &&
                schedule[i].second == current_second) {

                int relay_number = schedule[i].relay_number;
                int on_off = schedule[i].on_off;

                if (on_off == 1) {
                    // Sunrise/sunset effect
                    for (int brightness = 0; brightness <= PWM_RANGE; ++brightness) {
                        turn_on_relay(relay_number, brightness);
                        gpioDelay(TRANSITION_TIME / PWM_RANGE);
                    }
                } else {
                    // Turn off the relay
                    turn_off_relay(relay_number);
                }
            }
        }

        gpioDelay(1000); // Check every second
    }

    // Clean up and exit
    turn_off_all_relays();
    gpioTerminate();
    free(schedule);
    return 0;
}

