#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define MIN_DISTANCE 2.0       // Minimum distance in cm
#define MAX_DISTANCE 30.0      // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz
#define TIMEOUT_US 50000        // Timeout in microseconds (50ms)

// Global variable for program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microsecond pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width
long measurePulseWidth() {
    long start_tick, end_tick, pulse_width;

    // Wait for the echo pin to go high
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse start timeout\n");
        return -1; // Timeout
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse end timeout\n");
        return -1; // Timeout
    }

    end_tick = gpioTick();

    pulse_width = end_tick - start_tick;
    if (pulse_width < 0) {
        pulse_width += 0xFFFFFFFF; // Handle tick rollover
    }

    return pulse_width;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (float)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to map distance to frequency
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) {
        return MAX_FREQUENCY;
    } else if (distance > MAX_DISTANCE) {
        return MIN_FREQUENCY;
    } else {
        return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
    }
}

// Function to set the buzzer frequency
void setBuzzerFrequency(float frequency) {
    if (frequency < MIN_FREQUENCY) {
        frequency = MIN_FREQUENCY;
    } else if (frequency > MAX_FREQUENCY) {
        frequency = MAX_FREQUENCY;
    }

    int dutyCycle = (int)(128.0 * (frequency - MIN_FREQUENCY) / (MAX_FREQUENCY - MIN_FREQUENCY)); // Map frequency to duty cycle (0-128)
    gpioPWM(BUZZER_PIN, dutyCycle);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 1000); // 1 kHz

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 128);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulse_width = measurePulseWidth();

        if (pulse_width < 0) {
            fprintf(stderr, "Error: Failed to measure pulse width\n");
            gpioDelay(60000); // Wait 60ms before retrying
            continue;
        }

        float distance = calculateDistance(pulse_width);

        if (distance < 0) {
            fprintf(stderr, "Error: Failed to calculate distance\n");
            gpioDelay(60000); // Wait 60ms before retrying
            continue;
        }

        float frequency = mapDistanceToFrequency(distance);
        setBuzzerFrequency(frequency);

        gpioDelay(10000); // 10ms delay
    }

    // Stop the buzzer
    gpioPWM(BUZZER_PIN, 0);

    // Deinitialize pigpio
    gpioTerminate();

    fprintf(stderr, "Theremin stopped.\n");

    return 0;
}

