#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
    }
}

// Function to set the RGB color of the LED
void set_rgb_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Function to generate a sine wave proximity value
float generate_proximity_value(float time) {
    return (0.5 + 0.5 * sin(time * M_PI));
}

// Function to map proximity value to RGB color components
void map_proximity_to_rgb(float proximity, int *red, int *green, int *blue) {
    if (proximity < 0.5) {
        // Blue to Green
        *red = 0;
        *green = (int)(255 * (1 - (proximity / 0.5)));
        *blue = (int)(255 * (proximity / 0.5));
    } else {
        // Green to Red
        *red = (int)(255 * ((proximity - 0.5) / 0.5));
        *green = (int)(255 * (1 - ((proximity - 0.5) / 0.5)));
        *blue = 0;
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins to output mode
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Set PWM frequency for all pins
    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN, 255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN, 255);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    float time = 0.0;
    while (program_running) {
        // Generate proximity value
        float proximity = generate_proximity_value(time);

        // Map proximity to RGB color components
        int red, green, blue;
        map_proximity_to_rgb(proximity, &red, &green, &blue);

        // Set RGB color
        set_rgb_color(red, green, blue);

        // Increment time
        time += 0.01;

        // Sleep for 10 milliseconds
        usleep(10000);
    }

    // Turn off LED
    set_rgb_color(0, 0, 0);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

