#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define GYRO_XOUT_H 0x43

// Sensitivity scale factor for ±250 deg/s
#define GYRO_SENSITIVITY 131.0

// I2C device file
#define I2C_DEV "/dev/i2c-1"

// Log file name
#define LOG_FILE "gyro_log.txt"

// Global file descriptor for I2C
int i2c_fd = -1;

// Global file pointer for log file
FILE *log_fp = NULL;

// Function prototypes
int i2c_read_byte(int fd, uint8_t reg);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int16_t read_gyro_data(int fd, uint8_t reg);
float convert_to_degrees_per_second(int16_t raw_data);
void log_data(FILE *fp, float x, float y, float z);
void signal_handler(int signal);

// Function to read a single byte from an I2C register
int i2c_read_byte(int fd, uint8_t reg) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    uint8_t data;
    if (read(fd, &data, 1) != 1) {
        perror("Failed to read data");
        return -1;
    }

    return data;
}

// Function to write a single byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to read a 16-bit value from two I2C registers
int16_t read_gyro_data(int fd, uint8_t reg) {
    int16_t high_byte, low_byte;

    high_byte = i2c_read_byte(fd, reg);
    if (high_byte < 0) return -1;

    low_byte = i2c_read_byte(fd, reg + 1);
    if (low_byte < 0) return -1;

    return (high_byte << 8) | low_byte;
}

// Function to convert raw gyroscope data to degrees per second
float convert_to_degrees_per_second(int16_t raw_data) {
    return (float)raw_data / GYRO_SENSITIVITY;
}

// Function to log data to a file
void log_data(FILE *fp, float x, float y, float z) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            x, y, z);
    fflush(fp); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_fp != NULL) {
        fclose(log_fp);
    }
    exit(0);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open(I2C_DEV, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Open log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Wake up the MPU-6050
    if (i2c_write_byte(i2c_fd, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Failed to wake up MPU-6050\n");
        close(i2c_fd);
        fclose(log_fp);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        int16_t gyro_x = read_gyro_data(i2c_fd, GYRO_XOUT_H);
        int16_t gyro_y = read_gyro_data(i2c_fd, GYRO_XOUT_H + 2);
        int16_t gyro_z = read_gyro_data(i2c_fd, GYRO_XOUT_H + 4);

        if (gyro_x == -1 || gyro_y == -1 || gyro_z == -1) {
            fprintf(stderr, "Failed to read gyroscope data\n");
            continue; // Skip to the next iteration
        }

        // Convert to degrees per second
        float x = convert_to_degrees_per_second(gyro_x);
        float y = convert_to_degrees_per_second(gyro_y);
        float z = convert_to_degrees_per_second(gyro_z);

        // Log the data
        log_data(log_fp, x, y, z);

        // Wait for 100 milliseconds
        usleep(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

