#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody parameters
#define NUM_NOTES 5
#define DURATION_MS 200
#define DEBOUNCE_MS 50

// Define note frequencies (Hz)
const int notes[NUM_NOTES] = {262, 294, 330, 349, 392};

// Global variables
volatile int playback_active = 0;
volatile int button_pressed = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = gpioTick();

    if (current_tick - last_tick > DEBOUNCE_MS * 1000) { // Debounce
        button_pressed = 1;
        last_tick = current_tick;
    }
}

// Function to play the melody
void play_melody() {
    playback_active = 1;
    for (int i = 0; i < NUM_NOTES; i++) {
        if (!playback_active) break; // Check for stop signal
        gpioHardwarePWM(BUZZER_PIN, 128, 500000 / notes[i]); // 50% duty cycle, frequency
        gpioDelay(DURATION_MS * 1000); // Delay for note duration
    }
    playback_active = 0;
}

// Function to stop the melody
void stop_melody() {
    playback_active = 0;
    gpioHardwarePWM(BUZZER_PIN, 0, 0); // Stop PWM
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Enable internal pull-up resistor on the button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up interrupt handler for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Musical Doorbell running...\n");

    // Main loop
    while (1) {
        if (button_pressed) {
            button_pressed = 0; // Reset flag
            if (!playback_active) {
                play_melody();
            } else {
                stop_melody();
            }
        }
        gpioDelay(1000); // Check button every 1 ms
    }

    return 0; // This line will never be reached due to the infinite loop
}

