#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>
#include <errno.h>

#define GPIO_PIN 17
#define LOG_FILE "vibration_events.log"
#define EARTHQUAKE_THRESHOLD 3
#define WINDOW_SIZE 5

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_fp = NULL;

// Structure to hold the event history
typedef struct {
    int events[WINDOW_SIZE];
    int index;
    int count;
} EventHistory;

// Function to initialize the event history
void init_event_history(EventHistory *history) {
    history->index = 0;
    history->count = 0;
    memset(history->events, 0, sizeof(history->events));
}

// Function to add an event to the history
void add_event(EventHistory *history, int event) {
    history->events[history->index] = event;
    history->index = (history->index + 1) % WINDOW_SIZE;
    if (history->count < WINDOW_SIZE) {
        history->count++;
    }
}

// Function to check if an earthquake is imminent
int is_earthquake_imminent(const EventHistory *history) {
    if (history->count < EARTHQUAKE_THRESHOLD) {
        return 0;
    }
    int high_count = 0;
    for (int i = 0; i < history->count; i++) {
        if (history->events[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= EARTHQUAKE_THRESHOLD);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, exiting gracefully.\n");
}

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp
    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime);

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log an event to the log file
int log_event(FILE *log_fp, int value) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Failed to get timestamp.\n");
        return -1;
    }

    if (fprintf(log_fp, "%s %d\n", timestamp, value) < 0) {
        perror("Failed to write to log file");
        free(timestamp);
        return -1;
    }

    if (fflush(log_fp) != 0) {
        perror("Failed to flush log file");
        free(timestamp);
        return -1;
    }

    free(timestamp);
    return 0;
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = 1000;

    if (argc > 1) {
        char *endptr;
        long timeout = strtol(argv[1], &endptr, 10);
        if (*endptr != '\0' || timeout <= 0) {
            fprintf(stderr, "Invalid timeout value. Using default timeout (1000ms).\n");
        } else {
            poll_timeout_ms = (int)timeout;
        }
    }

    // Open the log file
    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        perror("Failed to open log file");
        return EXIT_FAILURE;
    }

    // Initialize libgpiod
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(line, "vibration_sensor") != 0) {
        fprintf(stderr, "Failed to request GPIO line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        fclose(log_fp);
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    EventHistory history;
    init_event_history(&history);

    // Main loop
    while (!terminate) {
        struct gpiod_line_event event;
        int ret = gpiod_line_event_wait(line, poll_timeout_ms * 1000); // Convert ms to ns

        if (ret == 0) {
            // Timeout occurred
            continue;
        } else if (ret < 0) {
            fprintf(stderr, "Error waiting for event: %s\n", strerror(errno));
            break;
        }

        if (gpiod_line_event_read(line, &event) != 0) {
            fprintf(stderr, "Error reading event: %s\n", strerror(errno));
            break;
        }

        int value = gpiod_line_get_value(line);
        if (log_event(log_fp, value) != 0) {
            fprintf(stderr, "Error logging event.\n");
            break;
        }

        add_event(&history, value);

        if (is_earthquake_imminent(&history)) {
            char *timestamp = get_iso8601_timestamp();
            if (timestamp != NULL) {
                printf("EARTHQUAKE ALERT: %s\n", timestamp);
                free(timestamp);
            }
        }
    }

    // Cleanup
    gpiod_line_release(line);
    gpiod_chip_close(chip);
    fclose(log_fp);

    return EXIT_SUCCESS;
}

