#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Global variables
static volatile int relay_state = 0; // 0 = OFF, 1 = ON
static volatile unsigned long last_touch_time = 0;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void touch_sensor_isr(int gpio, int level, unsigned int tick, void *user_data);
int toggle_relay();
int log_relay_state(int state);
void cleanup_handler(int signum);

// Structure to hold program state
typedef struct {
    int relay_pin;
    int touch_pin;
    int debounce_time;
    int current_relay_state;
    unsigned long last_touch_time;
    FILE *log_file;
} ProgramState;

ProgramState state = {RELAY_PIN, TOUCH_SENSOR_PIN, DEBOUNCE_TIME, 0, 0, NULL};

int main() {
    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("relay_log.json", "a");
    if (log_file == NULL) {
        perror("Error opening relay_log.json");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop (currently empty, ISR handles everything)
    while (1) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

// Initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(state.touch_pin, PI_INPUT);
    gpioSetPullUpDown(state.touch_pin, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(state.relay_pin, PI_OUTPUT);

    // Set up interrupt service routine for touch sensor
    if (gpioSetISRFuncEx(state.touch_pin, RISING_EDGE, 0, touch_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt service routine for touch sensor
void touch_sensor_isr(int gpio, int level, unsigned int tick, void *user_data) {
    unsigned long current_time = gpioTick();

    // Debounce the touch sensor
    if (current_time - state.last_touch_time > state.debounce_time * 1000) {
        // Toggle the relay state
        state.current_relay_state = !state.current_relay_state;

        // Toggle the relay
        if (toggle_relay() != 0) {
            fprintf(stderr, "Failed to toggle relay\n");
        }

        // Log the relay state
        if (log_relay_state(state.current_relay_state) != 0) {
            fprintf(stderr, "Failed to log relay state\n");
        }

        state.last_touch_time = current_time;
    }
}

// Toggle the relay state
int toggle_relay() {
    gpioWrite(state.relay_pin, state.current_relay_state);
    return 0;
}

// Log the relay state to a JSON file
int log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "{\"timestamp\":\"%s\", \"relay_state\": \"%s\"}\n", timestamp, state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

// Cleanup handler for Ctrl+C
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);

    // Turn the relay OFF
    gpioWrite(state.relay_pin, 0);

    // Log the final OFF state
    log_relay_state(0);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

