#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO_17 17
#define GPIO_23 23
#define GPIO_24 24
#define GPIO_25 25

// Define chip name
#define CHIP_NAME "gpiochip0"

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *line17, *line23, *line24, *line25;
FILE *log_file;

// Function prototypes
int setup_gpio(void);
int activate_relay(int gpio_pin);
int deactivate_relay(int gpio_pin);
int log_event(int gpio_pin, int moisture_level);
int cleanup(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    cleanup(signal);
    exit(0);
}

// Function to set up GPIO lines
int setup_gpio(void) {
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s\n", CHIP_NAME);
        return -1;
    }

    line17 = gpiod_chip_get_line(chip, GPIO_17);
    line23 = gpiod_chip_get_line(chip, GPIO_23);
    line24 = gpiod_chip_get_line(chip, GPIO_24);
    line25 = gpiod_chip_get_line(chip, GPIO_25);

    if (!line17 || !line23 || !line24 || !line25) {
        fprintf(stderr, "Error getting GPIO line\n");
        gpiod_chip_close(chip);
        return -1;
    }

    if (gpiod_line_request_output(line17, "irrigation", 1) < 0 ||
        gpiod_line_request_output(line23, "irrigation", 1) < 0 ||
        gpiod_line_request_output(line24, "irrigation", 1) < 0 ||
        gpiod_line_request_output(line25, "irrigation", 1) < 0) {
        fprintf(stderr, "Error requesting GPIO line as output\n");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to activate a relay
int activate_relay(int gpio_pin) {
    struct gpiod_line *line = NULL;

    if (gpio_pin == GPIO_17) {
        line = line17;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else if (gpio_pin == GPIO_24) {
        line = line24;
    } else if (gpio_pin == GPIO_25) {
        line = line25;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error setting GPIO %d to active (LOW)\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to deactivate a relay
int deactivate_relay(int gpio_pin) {
    struct gpiod_line *line = NULL;

    if (gpio_pin == GPIO_17) {
        line = line17;
    } else if (gpio_pin == GPIO_23) {
        line = line23;
    } else if (gpio_pin == GPIO_24) {
        line = line24;
    } else if (gpio_pin == GPIO_25) {
        line = line25;
    } else {
        fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
        return -1;
    }

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error setting GPIO %d to inactive (HIGH)\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to log an event
int log_event(int gpio_pin, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s - Relay %d activated - Moisture: %d\n", timestamp, gpio_pin, moisture_level);
    fflush(log_file);

    return 0;
}

// Function to clean up resources
int cleanup(int signal) {
    printf("Cleaning up and exiting...\n");

    // Deactivate all relays
    deactivate_relay(GPIO_17);
    deactivate_relay(GPIO_23);
    deactivate_relay(GPIO_24);
    deactivate_relay(GPIO_25);

