#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define VALVE_GPIO 17
#define NOZZLE_GPIO 18

// Define moisture thresholds
#define MOISTURE_THRESHOLD_LOW 50
#define MOISTURE_THRESHOLD_HIGH 50

// Define servo pulse widths (microseconds)
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Define nozzle angles (degrees)
#define NOZZLE_ANGLE_0 0
#define NOZZLE_ANGLE_45 45
#define NOZZLE_ANGLE_90 90
#define NOZZLE_ANGLE_135 135
#define NOZZLE_ANGLE_180 180

// Global flag to signal program termination
volatile sig_atomic_t terminate = 0;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "\nCaught signal, stopping servos and exiting...\n");
}

// Function to initialize the pigpio library
int initialize_gpio()
{
    if (gpioInitialise() < 0)
    {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to set the servo pulse width
int set_servo_pulse_width(int gpio, int pulse_width)
{
    int retries = 0;
    int result = -1;

    while (retries < 3 && result != 0)
    {
        result = gpioServo(gpio, pulse_width);
        if (result != 0)
        {
            fprintf(stderr, "Error setting servo pulse width for GPIO %d: %d. Retrying in 100ms...\n", gpio, result);
            gpioDelay(100000); // 100ms
            retries++;
        }
    }

    if (result != 0)
    {
        fprintf(stderr, "Failed to set servo pulse width for GPIO %d after multiple retries.\n", gpio);
        return -1;
    }

    return 0;
}

// Function to open the water valve
int open_valve()
{
    return set_servo_pulse_width(VALVE_GPIO, SERVO_MAX_PULSE_WIDTH);
}

// Function to close the water valve
int close_valve()
{
    return set_servo_pulse_width(VALVE_GPIO, SERVO_MIN_PULSE_WIDTH);
}

// Function to set the nozzle angle
int set_nozzle_angle(int angle)
{
    int pulse_width;

    if (angle == NOZZLE_ANGLE_0)
    {
        pulse_width = SERVO_MIN_PULSE_WIDTH;
    }
    else if (angle == NOZZLE_ANGLE_45)
    {
        pulse_width = (SERVO_MIN_PULSE_WIDTH + SERVO_MAX_PULSE_WIDTH) / 2;
    }
    else if (angle == NOZZLE_ANGLE_90)
    {
        pulse_width = (SERVO_MAX_PULSE_WIDTH + SERVO_MIN_PULSE_WIDTH) / 2;
    }
    else if (angle == NOZZLE_ANGLE_135)
    {
        pulse_width = (SERVO_MAX_PULSE_WIDTH + SERVO_MIN_PULSE_WIDTH) / 2 + (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) / 4;
    }
    else if (angle == NOZZLE_ANGLE_180)
    {
        pulse_width = SERVO_MAX_PULSE_WIDTH;
    }
    else
    {
        fprintf(stderr, "Invalid nozzle angle: %d\n", angle);
        return -1;
    }

    return set_servo_pulse_width(NOZZLE_GPIO, pulse_width);
}

// Function to perform the watering cycle
int watering_cycle(int moisture_level)
{
    if (moisture_level < MOISTURE_THRESHOLD_LOW)
    {
        printf("Moisture level: %d, below threshold. Watering...\n", moisture_level);

        // Open the valve
        if (open_valve() != 0)
        {
            fprintf(stderr, "Error opening valve.\n");
            return -1;
        }

        // Sweep the nozzle through all angles
        int angles[] = {NOZZLE_ANGLE_0, NOZZLE_ANGLE_45, NOZZLE_ANGLE_90, NOZZLE_ANGLE_135, NOZZLE_ANGLE_180};
        int num_angles = sizeof(angles) / sizeof(angles[0]);
        for (int i = 0; i < num_angles; i++)
        {
            if (set_nozzle_angle(angles[i]) != 0)
            {
                fprintf(stderr, "Error setting nozzle angle %d.\n", angles[i]);
                continue; // Continue to the next angle
            }
            gpioDelay(2000000); // 2 seconds
        }

        // Hold for 5 seconds
        gpioDelay(5000000); // 5 seconds

        // Close the valve
        if (close_valve() != 0)
        {
            fprintf(stderr, "Error closing valve.\n");
            return -1;
        }
    }
    else
    {
        printf("Moisture level: %d, above threshold. Skipping watering.\n", moisture_level);
    }

    return 0;
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0)
    {
        return 1;
    }

    // Define moisture readings
    int moisture_readings[] = {20, 40, 60, 80, 100};
    int num_readings = sizeof(moisture_readings) / sizeof(moisture_readings[0]);

    // Main loop
    while (!terminate)
    {
        for (int i = 0; i < num_readings; i++)
        {
            if (terminate) break; // Exit loop if termination signal received

            int moisture_level = moisture_readings[i];
            printf("Simulating moisture level: %d\n", moisture_level);

            if (watering_cycle(moisture_level) != 0)
            {
                fprintf(stderr, "Error during watering cycle.\n");
            }

            gpioDelay(5000000); // 5 seconds delay between readings
        }
    }

    // Stop servos and terminate pigpio
    gpioServo(VALVE_GPIO, 0);
    gpioServo(NOZZLE_GPIO, 0);
    gpioTerminate();

    return 0;
}

