    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    printf("Ultrasonic sensor program started. Logging to distance_log.txt\n");

    // Main loop
    while (running) {
        trigger_sensor();
        gpioDelay(GUARD_MS * 1000); // Guard time

        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            log_distance(-1.0);
            fprintf(stderr, "Error: Invalid pulse width\n");
        }

        gpioDelay(1000); // Wait 1 second
    }

    // Cleanup
    fclose(log_file);
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

