// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define RESET_REG 0x0000
#define RANGING_MODE_REG 0x0080
#define INTERRUPT_STATUS_REG 0x0044
#define DISTANCE_MSB_REG 0x0096
#define DISTANCE_LSB_REG 0x0097
#define RELAY_GPIO 18
#define DISTANCE_THRESHOLD 50 // cm

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int vl53l1x_init();
int vl53l1x_read_distance(uint16_t *distance);
void control_relay(uint16_t distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the VL53L1X sensor
int vl53l1x_init() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, RESET_REG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset VL53L1X sensor\n");
        return -1;
    }
    gpioDelay(10000); // Wait 10ms

    // Set ranging mode to continuous
    if (i2cWriteByteData(i2c_handle, RANGING_MODE_REG, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set ranging mode\n");
        return -1;
    }

    return 0;
}

// Read distance from the VL53L1X sensor
int vl53l1x_read_distance(uint16_t *distance) {
    uint8_t int_status;

    // Check if data is ready
    int_status = i2cReadByteData(i2c_handle, INTERRUPT_STATUS_REG);
    if (int_status < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status\n");
        return -1;
    }

    if (int_status & 0x04) { // Data ready bit
        uint8_t msb, lsb;

        // Read distance MSB
        msb = i2cReadByteData(i2c_handle, DISTANCE_MSB_REG);
        if (msb < 0) {
            fprintf(stderr, "Error: Failed to read distance MSB\n");
            return -1;
        }

        // Read distance LSB
        lsb = i2cReadByteData(i2c_handle, DISTANCE_LSB_REG);
        if (lsb < 0) {
            fprintf(stderr, "Error: Failed to read distance LSB\n");
            return -1;
        }

        *distance = (uint16_t)((msb << 8) | lsb);
