        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off on exit
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

