#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Signal handler for graceful shutdown
void signal_handler(int sig);

// Function to initialize the MPU-6050
int init_mpu6050(int fd);

// Function to read raw gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);

// Function to convert raw data to degrees per second
void convert_gyro_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps);

int main() {
    int16_t gyro_x_raw, gyro_y_raw, gyro_z_raw;
    float gyro_x_dps, gyro_y_dps, gyro_z_dps;

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050(i2c_fd) != 0) {
        fprintf(stderr, "MPU-6050 initialization failed.\n");
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        // Read gyroscope data
        if (read_gyro_data(i2c_fd, &gyro_x_raw, &gyro_y_raw, &gyro_z_raw) == 0) {
            // Convert raw data to degrees per second
            convert_gyro_data(gyro_x_raw, gyro_y_raw, gyro_z_raw, &gyro_x_dps, &gyro_y_dps, &gyro_z_dps);

            // Log data to console
            printf("Gyro X: %.2f dps, Gyro Y: %.2f dps, Gyro Z: %.2f dps\n", gyro_x_dps, gyro_y_dps, gyro_z_dps);
        } else {
            fprintf(stderr, "Error reading gyroscope data.\n");
        }

        // Delay for 100 milliseconds
        usleep(100000); // 100 ms
    }

    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, exiting gracefully.\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the MPU-6050
int init_mpu6050(int fd) {
    // Wake up the MPU-6050
    uint8_t wake_up_data[2] = {PWR_MGMT_1, 0x00};
    if (write(fd, wake_up_data, 2) != 2) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Set gyroscope full-scale range to ±250 dps
    uint8_t gyro_config_data[2] = {GYRO_CONFIG, 0x00};
    if (write(fd, gyro_config_data, 2) != 2) {
        perror("Error writing to GYRO_CONFIG register");
        return -1;
    }

    return 0;
}

// Function to read raw gyroscope data
int read_gyro_data(int fd, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    uint8_t reg = GYRO_XOUT_H;
    uint8_t buffer[6];

    // Set the register address from which to read
    if (write(fd, &reg, 1) != 1) {
        perror("Error writing to register address");
        return -1;
    }

    // Read 6 bytes of gyroscope data
    if (read(fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        return -1;
    }

    // Combine high and low bytes to form 16-bit signed integers
    *gyro_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *gyro_y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *gyro_z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Function to convert raw data to degrees per second
void convert_gyro_data(int16_t gyro_x_raw, int16_t gyro_y_raw, int16_t gyro_z_raw, float *gyro_x_dps, float *gyro_y_dps, float *gyro_z_dps) {
    *gyro_x_dps = (float)gyro_x_raw / GYRO_SENSITIVITY;
    *gyro_y_dps = (float)gyro_y_raw / GYRO_SENSITIVITY;
    *gyro_z_dps = (float)gyro_z_raw / GYRO_SENSITIVITY;
}

