#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define GPIO17 17
#define GPIO18 18
#define GPIO27 27
#define GPIO22 22

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define log file name
#define LOG_FILE "watering_log.txt"

// Global variables
struct gpiod_chip *chip;
struct gpiod_line *line17, *line18, *line27, *line22;
FILE *log_file;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void activate_relay(int gpio_pin);
void deactivate_relay(int gpio_pin);
void log_watering_cycle(void);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get line handles
    line17 = gpiod_chip_get_line(chip, GPIO17);
    line18 = gpiod_chip_get_line(chip, GPIO18);
    line27 = gpiod_chip_get_line(chip, GPIO27);
    line22 = gpiod_chip_get_line(chip, GPIO22);

    if (!line17 || !line18 || !line27 || !line22) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request lines as outputs with active-low semantics
    ret = gpiod_line_request_output(line17, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 17 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line18, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 18 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line27, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 27 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(line22, "watering_system", 1);
    if (ret < 0) {
        perror("Error requesting GPIO line 22 as output");
        gpiod_chip_close(chip);
        return -1;
    }

    // Set initial state to HIGH (inactive)
    gpiod_line_set_value(line17, 1);
    gpiod_line_set_value(line18, 1);
    gpiod_line_set_value(line27, 1);
    gpiod_line_set_value(line22, 1);

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (line17) {
        gpiod_line_release(line17);
    }
    if (line18) {
        gpiod_line_release(line18);
    }
    if (line27) {
        gpiod_line_release(line27);
    }
    if (line22) {
        gpiod_line_release(line22);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to activate a relay
void activate_relay(int gpio_pin) {
    struct gpiod_line *line = NULL;

    switch (gpio_pin) {
        case GPIO17:
            line = line17;
            break;
        case GPIO18:
            line = line18;
            break;
        case GPIO27:
            line = line27;
            break;
        case GPIO22:
            line = line22;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return;
    }

    if (line) {
        gpiod_line_set_value(line, 0); // Active low
        printf("Relay on GPIO %d activated\n", gpio_pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int gpio_pin) {
    struct gpiod_line *line = NULL;

    switch (gpio_pin) {
        case GPIO17:
            line = line17;
            break;
        case GPIO18:
            line = line18;
            break;
        case GPIO27:
            line = line27;
            break;
        case GPIO22:
            line = line22;
            break;
        default:
            fprintf(stderr, "Invalid GPIO pin: %d\n", gpio_pin);
            return;
    }

    if (line) {
        gpiod_line_set_value(line, 1); // Active low
        printf("Relay on GPIO %d deactivated\n", gpio_pin);
    }
}

// Function to log watering cycle
void log_watering_cycle(void) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
