// Define GPIO pins for the relays
#define RELAY1_GPIO 17
#define RELAY2_GPIO 18
#define RELAY3_GPIO 27
#define RELAY4_GPIO 22

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define log file name
#define LOG_FILE "smart_lighting.log"

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_relay_state(int gpio, int state);
int set_pwm_duty_cycle(int gpio, int duty_cycle);
int simulate_sunrise(int duration_seconds);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        program_running = 0;
        log_event("Received signal, shutting down...");

        // Turn off all relays
        set_relay_state(RELAY1_GPIO, 0);
        set_relay_state(RELAY2_GPIO, 0);
        set_relay_state(RELAY3_GPIO, 0);
        set_relay_state(RELAY4_GPIO, 0);

        // Stop PWM on all GPIOs
        gpioPWM(RELAY1_GPIO, 0);
        gpioPWM(RELAY2_GPIO, 0);
        gpioPWM(RELAY3_GPIO, 0);
        gpioPWM(RELAY4_GPIO, 0);

        // Terminate pigpio library
        gpioTerminate();

        log_event("Program terminated.");
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY2_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY3_GPIO, PI_OUTPUT);
    gpioSetMode(RELAY4_GPIO, PI_OUTPUT);

    // Set PWM frequency for all GPIOs
    gpioSetPWMfrequency(RELAY1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_GPIO, PWM_FREQUENCY);

    log_event("GPIO initialization complete.");
    return 0; // Indicate success
}

// Function to set the state of a relay (0 or 1)
int set_relay_state(int gpio, int state) {
    gpioWrite(gpio, state);
    char message[100];
    sprintf(message, "Relay on GPIO %d set to %d", gpio, state);
    log_event(message);
    return 0;
}

