int set_pwm_duty_cycle(int gpio, int duty_cycle) {
    gpioPWM(gpio, duty_cycle);
    char message[100];
    sprintf(message, "PWM duty cycle for GPIO %d set to %d", gpio, duty_cycle);
    log_event(message);
    return 0;
}

