int simulate_sunrise(int duration_seconds) {
    int i;
    for (i = 0; i <= 255 && program_running; i++) {
        set_pwm_duty_cycle(RELAY1_GPIO, i);
        set_pwm_duty_cycle(RELAY2_GPIO, i);
        set_pwm_duty_cycle(RELAY3_GPIO, i);
        set_pwm_duty_cycle(RELAY4_GPIO, i);
