#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define SMPLRT_DIV   0x19
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47
#define WHO_AM_I     0x75

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Structure to store gyroscope data and timestamp
typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

// Circular buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// I2C handle
int i2c_handle;

// Function prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void store_data(float x, float y, float z);
void check_threshold(float x, float y, float z);
void signal_handler(int signal);

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); // Turn off LED initially

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    // Main loop
    while (program_running) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Store data in circular buffer
            store_data(x, y, z);

            // Check threshold and control LED
            check_threshold(x, y, z);
        } else {
            fprintf(stderr, "Failed to read gyroscope data\n");
        }

        // Delay for 50 ms (20 Hz sampling rate)
        gpioDelay(50000); // 50 ms = 50000 microseconds
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    int retries = 3;
    int status;

    while (retries > 0) {
        // Open I2C device
        i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
        if (i2c_handle < 0) {
            fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
            retries--;
            gpioDelay(100000); // Wait 100 ms before retrying
            continue;
        }

        // Wake up the MPU-6050
        status = i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to PWR_MGMT_1: %d\n", status);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        // Set sample rate divider
        status = i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07);
        if (status < 0) {
            fprintf(stderr, "Error writing to SMPLRT_DIV: %d\n", status);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        // Set gyroscope full-scale range
        status = i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00);
        if (status < 0) {
            fprintf(stderr, "Error writing to GYRO_CONFIG: %d\n", status);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        // Verify WHO_AM_I register
        int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (who_am_i < 0) {
            fprintf(stderr, "Error reading WHO_AM_I: %d\n", who_am_i);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        if (who_am_i != 0x68) {
            fprintf(stderr, "WHO_AM_I returned 0x%x, expected 0x68\n", who_am_i);
            i2cClose(i2c_handle);
            retries--;
            gpioDelay(100000);
            continue;
        }

        return 0; // Initialisation successful
    }

    fprintf(stderr, "MPU-6050 initialisation failed after multiple retries\n");
    return -1; // Initialisation failed
}

// Read gyroscope data
int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int status;
    int retries = 3;

    while (retries > 0) {
        status = i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6);
        if (status == 6) {
            // Combine high and low bytes, convert to signed 16-bit integer
            int16_t gyro_x = (buf[0] << 8) | buf[1];
            int16_t gyro_y = (buf[2] << 8) | buf[3];
            int16_t gyro_z = (buf[4] << 8) | buf[5];

            // Convert to degrees per second
            *x = (float)gyro_x / 131.0;
            *y = (float)gyro_y / 131.0;
            *z = (float)gyro_z / 131.0;

            return 0; // Success
        } else {
            fprintf(stderr, "Error reading gyroscope data: %d\n", status);
            retries--;
            gpioDelay(100000); // Wait 100 ms before retrying
        }
    }

    fprintf(stderr, "Failed to read gyroscope data after multiple retries\n");
    return -1; // Failure
}

// Store data in circular buffer
void store_data(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    gyro_buffer[buffer_index].timestamp = ts;
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Check threshold and control LED
void check_threshold(float x, float y, float z) {
    if (fabs(x) > 250 || fabs(y) > 250 || fabs(z) > 250) {
        gpioWrite(LED_PIN, 1); // Turn on LED
    } else {
        gpioWrite(LED_PIN, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Received signal %d, shutting down...\n", signal);
}

