// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 8
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define SPI_BITS_PER_WORD 8
#define SPI_MSB_FIRST 1
#define GYRO_SCALE_FACTOR 131.0
#define LOG_FILE "gyro_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *gpio_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(void);
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len);
int gpio_init(void);
int gpio_set_value(int value);
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
double convert_to_dps(int16_t raw_value);
int log_data(double x_rate, double y_rate, double z_rate);
void signal_handler(int sig);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    int ret;

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    ret = ioctl(spi_fd, SPI_IOC_WR_MODE, &mode);
    if (ret == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    ret = ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits);
    if (ret == -1) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed
    uint32_t speed = SPI_SPEED;
    ret = ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed);
    if (ret == -1) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        return -1;
    }

    // Configure SPI MSB first
    uint8_t msb = SPI_MSB_FIRST;
    ret = ioctl(spi_fd, SPI_IOC_WR_LSB_FIRST, &msb);
    if (ret == -1) {
        perror("Error setting SPI MSB first");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI transfer function with retry
int spi_transfer(uint8_t *tx_buf, uint8_t *rx_buf, size_t len) {
    int ret, i;

    for (i = 0; i < RETRY_COUNT; ++i) {
        gpio_set_value(0); // Assert CS low
        ret = write(spi_fd, tx_buf, len);
        if (ret == len) {
            ret = read(spi_fd, rx_buf, len);
            if (ret == len) {
                gpio_set_value(1); // De-assert CS high
                return 0; // Success
            } else {
                perror("Error reading SPI data");
            }
        } else {
            perror("Error writing SPI data");
        }
        gpio_set_value(1); // De-assert CS high
        usleep(RETRY_DELAY_MS * 1000); // Wait before retry
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", RETRY_COUNT);
    return -1; // Failure
}

// GPIO initialization function
int gpio_init(void) {
    int ret;

    gpio_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    gpio_line = gpiod_chip_get_line(gpio_chip, GPIO_PIN);
    if (!gpio_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    ret = gpiod_line_request_output(gpio_line, "gyro_cs", 1); // Initial value: high
    if (ret < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// GPIO set value function
int gpio_set_value(int value) {
    int ret;

    ret = gpiod_line_set_value(gpio_line, value);
    if (ret < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }

    return 0;
}

// Read gyroscope data function
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[7] = {0x43, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00}; // Read 6 bytes starting from 0x43
    uint8_t rx_buf[7];

    if (spi_transfer(tx_buf, rx_buf, 7) != 0) {
        fprintf(stderr, "Error reading gyro data.\n");
        return -1;
    }

    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);
    *z = (int16_t)((rx_buf[4] << 8) | rx_buf[5]);

    return 0;
}

// Convert raw data to degrees per second
double convert_to_dps(int16_t raw_value) {
    return (double)raw_value / GYRO_SCALE_FACTOR;
}

// Log data to file
int log_data(double x_rate, double y_rate, double z_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1;
        }
    }

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, x_rate, y_rate, z_rate);
    fflush(log_file); // Ensure data is written to disk

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup(void) {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_line) {
        gpiod_line_release(gpio_line);
    }
    if (gpio_chip) {
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main(void) {
    int16_t raw_x, raw_y, raw_z;
    double x_rate, y_rate, z_rate;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize hardware
    if (spi_init() != 0) {
        fprintf(stderr, "SPI initialization failed.\n");
        return 1;
    }

    if (gpio_init() != 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_gyro_data(&raw_x, &raw_y, &raw_z) == 0) {
            x_rate = convert_to_dps(raw_x);
            y_rate = convert_to_dps(raw_y);
            z_rate = convert_to_dps(raw_z);

            if (log_data(x_rate, y_rate, z_rate) != 0) {
                fprintf(stderr, "Error logging data.\n");
            }
        } else {
            fprintf(stderr, "Failed to read gyro data. Retrying...\n");
        }

        usleep(10000); // 10 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

