#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define SI1145_ADDR 0x5A
#define AMBIENT_LIGHT_REG 0x20
#define PROXIMITY_REG 0x22
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define LOG_FILE "biometric_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
struct gpiod_chip *gpio_chip = NULL;
struct gpiod_line *led_line = NULL;

// Function prototypes
int i2c_read_register(int fd, uint8_t reg, uint8_t *value);
int i2c_write_register(int fd, uint8_t reg, uint8_t value);
int read_ambient_light(int fd);
int read_proximity(int fd);
void log_data(int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int signal);

// I2C read function with retry
int i2c_read_register(int fd, uint8_t reg, uint8_t *value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %d. Retrying...\n", reg, result);
            usleep(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C read failed after multiple retries (reg 0x%02X).\n", reg);
    return -1; // Failure
}

// I2C write function with retry
int i2c_write_register(int fd, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;

    while (retries > 0) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %d. Retrying...\n", reg, value, result);
            usleep(10000); // 10 ms delay
            retries--;
        }
    }

    fprintf(stderr, "I2C write failed after multiple retries (reg 0x%02X, value 0x%02X).\n", reg, value);
    return -1; // Failure
}

// Function to read ambient light value
int read_ambient_light(int fd) {
    uint8_t low_byte, high_byte;
    int ambient_light;

    if (i2c_read_register(fd, AMBIENT_LIGHT_REG, &low_byte) != 0) {
        return -1;
    }
    if (i2c_read_register(fd, AMBIENT_LIGHT_REG + 1, &high_byte) != 0) {
        return -1;
    }

    ambient_light = (high_byte << 8) | low_byte;
    return ambient_light;
}

// Function to read proximity value
int read_proximity(int fd) {
    uint8_t low_byte, high_byte;
    int proximity;

    if (i2c_read_register(fd, PROXIMITY_REG, &low_byte) != 0) {
        return -1;
    }
    if (i2c_read_register(fd, PROXIMITY_REG + 1, &high_byte) != 0) {
        return -1;
    }

    proximity = (high_byte << 8) | low_byte;
    return proximity;
}

// Function to log data to file
void log_data(int ambient_light, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control LED based on proximity
void control_led(int proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        gpiod_line_set_value(led_line, 1); // Turn LED on
    } else {
        gpiod_line_set_value(led_line, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (i2c_fd != -1) {
        close(i2c_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0); // Turn LED off
        gpiod_line_release(led_line);
    }

    if (gpio_chip != NULL) {
        gpiod_chip_close(gpio_chip);
    }

    exit(0);
}

int main() {
    int ambient_light, proximity;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Open GPIO chip
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        close(i2c_fd);
        return 1;
    }

    // Get GPIO line
    led_line = gpiod_chip_get_line(gpio_chip, LED_GPIO);
    if (!led_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Request GPIO line for output
    if (gpiod_line_request_output(led_line, "biometric_sensor", 0) < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpiod_line_release(led_line);
        gpiod_chip_close(gpio_chip);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    while (1) {
        ambient_light = read_ambient_light(i2c_fd);
        proximity = read_proximity(i2c_fd);

        if (ambient_light != -1 && proximity != -1) {
            log_data(ambient_light, proximity);
            control_led(proximity);
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

