#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <string.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define ADXRS290 register addresses
#define X_AXIS_REG 0x02
#define Y_AXIS_REG 0x04

// Define sensitivity (LSB/deg/s)
#define SENSITIVITY 200.0

// Global variables
int spi_handle;
FILE *fp;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int initialize_spi();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize SPI
int initialize_spi() {
    int retries = 0;
    while (retries < 3) {
        spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        if (spi_handle >= 0) {
            printf("SPI initialized successfully.\n");
            return 0; // Success
        } else {
            fprintf(stderr, "Error opening SPI channel: %d. Retrying...\n", spi_handle);
            retries++;
            gpioDelay(100000); // Wait 100ms before retrying
        }
    }
    fprintf(stderr, "Failed to initialize SPI after multiple retries.\n");
    return -1; // Failure
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char tx_buf[2], rx_buf[2];
    int status;

    // Read X-axis data
    tx_buf[0] = X_AXIS_REG | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading X-axis data: %d\n", status);
        data.x_rate = 0; // Set to 0 on error
    } else {
        data.x_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    }

    // Read Y-axis data
    tx_buf[0] = Y_AXIS_REG | 0x80; // Read command
    tx_buf[1] = 0x00; // Dummy byte
    status = spiXfer(spi_handle, tx_buf, rx_buf, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading Y-axis data: %d\n", status);
        data.y_rate = 0; // Set to 0 on error
    } else {
        data.y_rate = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    }

    return data;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(fp, "%ld.%06ld,%d,%d\n", ts.tv_sec, ts.tv_nsec / 1000, data.x_rate, data.y_rate);
    fflush(fp); // Ensure data is written to file immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (fp != NULL) {
        fclose(fp);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    fp = fopen("gyro_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening gyro_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long fsize = ftell(fp);
    if (fsize == 0) {
        fprintf(fp, "timestamp,X rate,Y rate\n");
    }

    // Main loop
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 10000000; // 10 ms

    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        nanosleep(&delay, NULL);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

