#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>
#include <unistd.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define GYRO_X_REG 0x02
#define GYRO_Y_REG 0x04
#define GYRO_Z_REG 0x06
#define GYRO_SENSITIVITY 200.0 // LSB/deg/s
#define THRESHOLD 20.0 // deg/s
#define LED_GPIO 17
#define BUFFER_SIZE 100

// Data structure for gyroscope readings
typedef struct {
    struct timespec timestamp;
    int16_t x_rate;
    int16_t y_rate;
    int16_t z_rate;
} gyro_data_t;

// Circular buffer
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

// Global variables
int spi_handle;
circular_buffer_t gyro_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int read_gyro_register(uint8_t reg_addr, uint8_t *data, int len);
int16_t combine_bytes(uint8_t high_byte, uint8_t low_byte);
double convert_to_dps(int16_t raw_rate);
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data);
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index);
void check_threshold(double x_rate, double y_rate, double z_rate);
void signal_handler(int signal);
void init_circular_buffer(circular_buffer_t *buffer);

// Initialize circular buffer
void init_circular_buffer(circular_buffer_t *buffer) {
    buffer->head = 0;
    buffer->tail = 0;
    buffer->count = 0;
    pthread_mutex_init(&buffer->mutex, NULL);
}

// Add data to the circular buffer
void add_to_buffer(circular_buffer_t *buffer, gyro_data_t data) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head] = data;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count == BUFFER_SIZE) {
        buffer->tail = (buffer->tail + 1) % BUFFER_SIZE;
    } else {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from the circular buffer
gyro_data_t get_from_buffer(circular_buffer_t *buffer, int index) {
    pthread_mutex_lock(&buffer->mutex);
    int actual_index = (buffer->tail + index) % BUFFER_SIZE;
    gyro_data_t data = buffer->buffer[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return data;
}

// Initialize SPI
int init_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from gyroscope register
int read_gyro_register(uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[1];
    char rx_buf[len];

    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation

    if (spiXfer(spi_handle, tx_buf, rx_buf, len + 1) != (len + 1)) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Combine high and low bytes into a 16-bit signed integer
int16_t combine_bytes(uint8_t high_byte, uint8_t low_byte) {
    return (int16_t)((high_byte << 8) | low_byte);
}

// Convert raw rate data to degrees per second
double convert_to_dps(int16_t raw_rate) {
    return (double)raw_rate / GYRO_SENSITIVITY;
}

// Check if any axis exceeds the threshold
void check_threshold(double x_rate, double y_rate, double z_rate) {
    if (abs(x_rate) > THRESHOLD || abs(y_rate) > THRESHOLD || abs(z_rate) > THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn on LED
    } else {
        gpioWrite(LED_GPIO, 0); // Turn off LED
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    init_circular_buffer(&gyro_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t x_data[2], y_data[2], z_data[2];
    int16_t x_raw, y_raw, z_raw;
    double x_dps, y_dps, z_dps;
    struct timespec ts;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_register(GYRO_X_REG, x_data, 2) != 0) {
            fprintf(stderr, "Error reading X axis data\n");
            continue;
        }
        if (read_gyro_register(GYRO_Y_REG, y_data, 2) != 0) {
            fprintf(stderr, "Error reading Y axis data\n");
            continue;
        }
        if (read_gyro_register(GYRO_Z_REG, z_data, 2) != 0) {
            fprintf(stderr, "Error reading Z axis data\n");
            continue;
        }

        // Combine bytes
        x_raw = combine_bytes(x_data[0], x_data[1]);
        y_raw = combine_bytes(y_data[0], y_data[1]);
        z_raw = combine_bytes(z_data[0], z_data[1]);

        // Convert to degrees per second
        x_dps = convert_to_dps(x_raw);
        y_dps = convert_to_dps(y_raw);
        z_dps = convert_to_dps(z_raw);

        // Get timestamp
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            perror("clock_gettime");
            continue;
        }

        // Store data in circular buffer
        gyro_data_t data = {ts, x_raw, y_raw, z_raw};
        add_to_buffer(&gyro_buffer, data);

        // Check threshold and control LED
        check_threshold(x_dps, y_dps, z_dps);

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

