#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RED_LIGHT_PIN 17
#define YELLOW_LIGHT_PIN 22
#define GREEN_LIGHT_PIN 23
#define ALL_LIGHTS_PIN 24

// Define states
typedef enum {
    RED,
    RED_YELLOW,
    GREEN,
    YELLOW
} TrafficLightState;

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    (void)signal; // Suppress unused parameter warning
    program_running = 0;
    fprintf(stderr, "\nCaught signal, exiting gracefully...\n");
}

// Function to set the state of a relay
int set_relay_state(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", gpio_pin);
        return -1;
    }
    return 0;
}

// Function to turn all relays ON
int turn_all_lights_on() {
    if (set_relay_state(RED_LIGHT_PIN, 0) != 0) return -1;
    if (set_relay_state(YELLOW_LIGHT_PIN, 0) != 0) return -1;
    if (set_relay_state(GREEN_LIGHT_PIN, 0) != 0) return -1;
    if (set_relay_state(ALL_LIGHTS_PIN, 0) != 0) return -1;
    return 0;
}

// Function to turn all relays OFF
int turn_all_lights_off() {
    if (set_relay_state(RED_LIGHT_PIN, 1) != 0) return -1;
    if (set_relay_state(YELLOW_LIGHT_PIN, 1) != 0) return -1;
    if (set_relay_state(GREEN_LIGHT_PIN, 1) != 0) return -1;
    if (set_relay_state(ALL_LIGHTS_PIN, 1) != 0) return -1;
    return 0;
}

// Function to cycle through the traffic light states
int cycle_traffic_lights() {
    TrafficLightState current_state = RED;

    while (program_running) {
        switch (current_state) {
            case RED:
                printf("Red light ON\n");
                if (turn_all_lights_off() != 0) return -1;
                if (set_relay_state(RED_LIGHT_PIN, 0) != 0) return -1;
                gpioDelay(10000000); // 10 seconds
                current_state = RED_YELLOW;
                break;
            case RED_YELLOW:
                printf("Red and Yellow lights ON\n");
                if (set_relay_state(RED_LIGHT_PIN, 1) != 0) return -1;
                if (set_relay_state(YELLOW_LIGHT_PIN, 0) != 0) return -1;
                gpioDelay(2000000); // 2 seconds
                current_state = GREEN;
                break;
            case GREEN:
                printf("Green light ON\n");
                if (set_relay_state(RED_LIGHT_PIN, 1) != 0) return -1;
                if (set_relay_state(YELLOW_LIGHT_PIN, 1) != 0) return -1;
                if (set_relay_state(GREEN_LIGHT_PIN, 0) != 0) return -1;
                gpioDelay(10000000); // 10 seconds
                current_state = YELLOW;
                break;
            case YELLOW:
                printf("Yellow light ON\n");
                if (set_relay_state(GREEN_LIGHT_PIN, 1) != 0) return -1;
                if (set_relay_state(YELLOW_LIGHT_PIN, 0) != 0) return -1;
                gpioDelay(3000000); // 3 seconds
                current_state = RED;
                break;
            default:
                fprintf(stderr, "Invalid state\n");
                return -1;
        }
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_LIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RED_LIGHT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW_LIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", YELLOW_LIGHT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_LIGHT_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GREEN_LIGHT_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ALL_LIGHTS_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALL_LIGHTS_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Turn all lights off initially
    if (turn_all_lights_off() != 0) {
        fprintf(stderr, "Failed to turn off all lights\n");
        gpioTerminate();
        return 1;
    }

    // Cycle through traffic light states
    if (cycle_traffic_lights() != 0) {
        fprintf(stderr, "Traffic light cycle failed\n");
        gpioTerminate();
        return 1;
    }

    // Turn off all lights before exiting
    if (turn_all_lights_off() != 0) {
        fprintf(stderr, "Failed to turn off all lights before exiting\n");
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Program finished.\n");
    return 0;
}

