#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define RELAY_GPIO 17
#define MPR121_ADDR 0x5A
#define I2C_BUS 1
#define TOUCH_THRESHOLD 0x0A
#define RELEASE_THRESHOLD 0x08
#define DEBOUNCE_TIME 100 // milliseconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_mpr121();
int read_touch_status();
void control_relay(int touch_status);
void log_message(const char *message);
void signal_handler(int signal);

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure MPR121
int configure_mpr121() {
    // Reset MPR121
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        log_message("Error: Failed to reset MPR121");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete (10ms)

    // Configure electrode 0
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x01) < 0) {
        log_message("Error: Failed to enable electrode 0");
        return -1;
    }

    // Set touch and release thresholds
    if (i2cWriteByteData(i2c_handle, 0x41, TOUCH_THRESHOLD) < 0) {
        log_message("Error: Failed to set touch threshold");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x42, RELEASE_THRESHOLD) < 0) {
        log_message("Error: Failed to set release threshold");
        return -1;
    }

    // Set debounce and charge time
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x21) < 0) {
        log_message("Error: Failed to set debounce");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5C, 0x0D) < 0) {
        log_message("Error: Failed to set charge time");
        return -1;
    }

    // Start MPR121 in run mode
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0D) < 0) {
        log_message("Error: Failed to start MPR121 in run mode");
        return -1;
    }

    return 0;
}

// Function to read touch status
int read_touch_status() {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        log_message("Error: Failed to read touch status");
        return -1;
    }
    return touch_status;
}

// Function to control the relay
void control_relay(int touch_status) {
    if (touch_status & 0x01) { // Electrode 0 touched
        gpioWrite(RELAY_GPIO, !gpioRead(RELAY_GPIO)); // Toggle relay state
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
    }
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file); // Ensure the message is written to the file immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received signal, shutting down...");
}

int main() {
    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        log_message("Failed to initialize pigpio");
        fclose(log_file);
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_message("Failed to initialize I2C");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Configure MPR121
    if (configure_mpr121() != 0) {
        log_message("Failed to configure MPR121");
        i2cClose(i2c_handle);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    log_message("System initialized successfully");

    // Main loop
    while (program_running) {
        int touch_status = read_touch_status();
        if (touch_status >= 0) {
            control_relay(touch_status);
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();
    fclose(log_file);

    log_message("System shutdown complete");

    return 0;
}

