// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Define dispense duration (in milliseconds)
#define DISPENSE_DURATION 1000

// Define dispense interval (in seconds)
#define DISPENSE_INTERVAL 5

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int activate_solenoid(int gpio_pin);
int deactivate_solenoid(int gpio_pin);
int dispense_cycle();
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, deactivating solenoids and exiting...\n");
        program_running = 0;
        deactivate_solenoid(SOLENOID_1_PIN);
        deactivate_solenoid(SOLENOID_2_PIN);
        gpioTerminate();
        exit(0);
    }
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    return 0;
}

// Function to activate a solenoid
int activate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 1); // Set GPIO pin HIGH
    return 0;
}

// Function to deactivate a solenoid
int deactivate_solenoid(int gpio_pin) {
    gpioWrite(gpio_pin, 0); // Set GPIO pin LOW
    return 0;
}

// Function to perform a dispense cycle
int dispense_cycle() {
    // Activate solenoid 1 for half the duration
    if (activate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Error activating solenoid 1\n");
        return 1;
    }
    gpioDelay(DISPENSE_DURATION / 2 * 1000); // Delay for half the duration (in microseconds)

    // Activate solenoid 2 for the remaining half of the duration
    if (activate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Error activating solenoid 2\n");
        return 1;
    }
    gpioDelay((DISPENSE_DURATION / 2) * 1000); // Delay for the remaining half (in microseconds)

    // Deactivate both solenoids
    if (deactivate_solenoid(SOLENOID_1_PIN) != 0) {
        fprintf(stderr, "Error deactivating solenoid 1\n");
        return 1;
    }
    if (deactivate_solenoid(SOLENOID_2_PIN) != 0) {
        fprintf(stderr, "Error deactivating solenoid 2\n");
        return 1;
    }

    return 0;
}

// Function to log dispense event
int log_dispense_event(int solenoid1_pin, int solenoid2_pin, int duration_ms) {
    FILE *fp = fopen("dispense_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return 1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Solenoid 1: %d, Solenoid 2: %d, Duration: %d ms\n", timestamp, solenoid1_pin, solenoid2_pin, duration_ms);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file\n");
        return 1;
    }

    return 0;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Pneumatic dispensing system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (dispense_cycle() != 0) {
            fprintf(stderr, "Error in dispense cycle\n");
        }

        if (log_dispense_event(SOLENOID_1_PIN, SOLENOID_2_PIN, DISPENSE_DURATION) != 0) {
            fprintf(stderr, "Error logging dispense event\n");
        }

        gpioDelay(DISPENSE_INTERVAL * 1000000); // Delay for the dispense interval (in microseconds)
    }

    // Cleanup (should not reach here if signal handler works correctly)
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();

    return 0;
}

