#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// L298N Enable pins
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// PID parameters
#define Kp 1.0
#define Ki 0.01
#define Kd 0.1

// Obstacle avoidance threshold (cm)
#define OBSTACLE_THRESHOLD 20.0

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_motor_speed(char motor, int speed);
int calculate_pid(float tilt_error, float distance);
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void obstacle_avoidance(float distance);
void stop_motors();
void signal_handler(int signal);

// Structure to hold motor state
typedef struct {
    int forward_pin;
    int backward_pin;
    int enable_pin;
} Motor;

Motor motor_a = {MOTOR_A_FORWARD, MOTOR_A_BACKWARD, MOTOR_A_ENABLE};
Motor motor_b = {MOTOR_B_FORWARD, MOTOR_B_BACKWARD, MOTOR_B_ENABLE};

int main() {
    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen("balance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Simulate tilt error and distance
        float tilt_error = (float)(rand() % 21 - 10); // Random float between -10.0 and 10.0
        float distance = (float)(rand() % 381 + 20); // Random float between 20.0 and 400.0

        // Calculate PID output
        int pid_output = calculate_pid(tilt_error, distance);

        // Set motor speeds
        set_motor_speed('A', pid_output);
        set_motor_speed('B', pid_output);

        // Obstacle avoidance
        obstacle_avoidance(distance);

        // Log data
        log_data(tilt_error, distance, pid_output, pid_output); // Log both motor speeds as they are the same

        // Delay
        gpioDelay(50000); // 50 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motors();
    fclose(log_file);
    gpioTerminate();

    return 0;
}

// Initialize pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set motor control pins as outputs
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);

    // Set enable pins as outputs
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_ENABLE, PWM_FREQUENCY);

    // Enable PWM for motors
    gpioPWM(MOTOR_A_ENABLE, 0); // Start with 0 PWM
    gpioPWM(MOTOR_B_ENABLE, 0); // Start with 0 PWM

    return 0;
}

// Set motor speed (0-255)
void set_motor_speed(char motor, int speed) {
    if (speed < -255) speed = -255;
    if (speed > 255) speed = 255;

    int forward_pin, backward_pin, enable_pin;

    if (motor == 'A') {
        forward_pin = motor_a.forward_pin;
        backward_pin = motor_a.backward_pin;
        enable_pin = motor_a.enable_pin;
    } else if (motor == 'B') {
        forward_pin = motor_b.forward_pin;
        backward_pin = motor_b.backward_pin;
        enable_pin = motor_b.enable_pin;
    } else {
        fprintf(log_file, "%s", "Invalid motor character\n");
        fflush(log_file);
        return;
    }

    if (speed > 0) {
        gpioWrite(forward_pin, 1);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, abs(speed));
    } else if (speed < 0) {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 1);
        gpioPWM(enable_pin, abs(speed));
    } else {
        gpioWrite(forward_pin, 0);
        gpioWrite(backward_pin, 0);
        gpioPWM(enable_pin, 0);
    }
}

// Calculate PID output
int calculate_pid(float tilt_error, float distance) {
    static float integral = 0.0;
    static float previous_error = 0.0;

    float error = tilt_error;
    float derivative = error - previous_error;

    integral += error;

    float output = Kp * error + Ki * integral + Kd * derivative;

    previous_error = error;

    // Clamp output to 0-255
    if (output < -255) output = -255;
    if (output > 255) output = 255;

    return (int)output;
}

// Log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to file immediately
}

// Obstacle avoidance
void obstacle_avoidance(float distance) {
    if (distance < OBSTACLE_THRESHOLD) {
        set_motor_speed('A', -127);
        set_motor_speed('B', -127);
    }
}

// Stop motors
void stop_motors() {
    set_motor_speed('A', 0);
    set_motor_speed('B', 0);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Ctrl+C pressed. Stopping motors and exiting.\n");
}

