#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void debounce();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initializes the pigpio library and sets up the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO4 as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set GPIO17 as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    return 0; // Indicate success
}

// Reads the state of the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Controls the relay (active-high)
void control_relay(int state) {
    gpioWrite(RELAY_PIN, state);
    relay_state = state; // Update the global relay state
}

// Implements a debounce delay
void debounce() {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
}

// Cleans up the GPIO pins and terminates the pigpio library
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Smart Light Switch running...\n");

    // Main loop
    while (1) {
        // Read the touch sensor
        if (read_touch_sensor() == 1) {
            // Touch detected
            printf("Touch detected!\n");

            // Toggle the relay state
            relay_state = !relay_state;
            control_relay(relay_state);

            // Debounce the touch sensor
            debounce();
        }

        // Small delay to prevent busy-waiting
        gpioDelay(1000); // 1 ms delay
    }

    return 0; // This line will never be reached due to the infinite loop
}

