#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <sys/time.h>
#include <pigpio.h>
#include <alsa/asoundlib.h>

// Configuration
#define RED_PIN 17
#define GREEN_PIN 18
#define BLUE_PIN 27
#define SAMPLE_RATE 8000
#define PERIOD_SIZE 1024
#define NUM_CHANNELS 1
#define BITS_PER_SAMPLE 16
#define SENSITIVITY_DEFAULT 1.0
#define SIMULATE_AUDIO 0 // Set to 1 to simulate audio input

// Global variables
static volatile int running = 1;
static snd_pcm_t *pcm_handle = NULL;
static double sensitivity = SENSITIVITY_DEFAULT;

// Function prototypes
int init_alsa(snd_pcm_t **pcm_handle);
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size);
double calculate_rms(const short *buffer, int buffer_size);
void map_amplitude_to_color(double amplitude, double sensitivity, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, exiting...\n");
    running = 0;
}

// Cleanup function
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (pcm_handle != NULL) {
        snd_pcm_drain(pcm_handle);
        snd_pcm_close(pcm_handle);
    }
    gpioTerminate();
    fprintf(stderr, "Cleanup complete.\n");
}

// Initialize ALSA
int init_alsa(snd_pcm_t **pcm_handle) {
    snd_pcm_hw_params_t *hw_params;
    int err;

    if ((err = snd_pcm_open(pcm_handle, "default", SND_PCM_STREAM_CAPTURE, 0)) < 0) {
        fprintf(stderr, "Error opening PCM device: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_alloca(&hw_params);

    if ((err = snd_pcm_hw_params_any(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_access(*pcm_handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED)) < 0) {
        fprintf(stderr, "Error setting access: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_format(*pcm_handle, hw_params, SND_PCM_FORMAT_S16_LE)) < 0) {
        fprintf(stderr, "Error setting format: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_channels(*pcm_handle, hw_params, NUM_CHANNELS)) < 0) {
        fprintf(stderr, "Error setting channels: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    unsigned int rate = SAMPLE_RATE;
    if ((err = snd_pcm_hw_params_set_rate_near(*pcm_handle, hw_params, &rate, 0)) < 0) {
        fprintf(stderr, "Error setting rate: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params_set_period_size(*pcm_handle, hw_params, PERIOD_SIZE, 0)) < 0) {
        fprintf(stderr, "Error setting period size: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    if ((err = snd_pcm_hw_params(*pcm_handle, hw_params)) < 0) {
        fprintf(stderr, "Error setting HW params: %s\n", snd_strerror(err));
        snd_pcm_close(*pcm_handle);
        return -1;
    }

    return 0;
}

// Capture audio from ALSA
int capture_audio(snd_pcm_t *pcm_handle, short *buffer, int buffer_size) {
    int err;
    if ((err = snd_pcm_readi(pcm_handle, buffer, buffer_size / NUM_CHANNELS)) != buffer_size / NUM_CHANNELS) {
        fprintf(stderr, "Error reading PCM data: %s\n", snd_strerror(err));
        if (err == -EPIPE) {
            fprintf(stderr, "EPIPE: Recovering from buffer overrun...\n");
            snd_pcm_prepare(pcm_handle);
        } else if (err == -ESTRPIPE) {
            fprintf(stderr, "ESTRPIPE: Recovering from suspension...\n");
            snd_pcm_resume(pcm_handle);
        } else {
            return -1; // Propagate the error
        }
    }
    return 0;
}

// Calculate RMS amplitude
double calculate_rms(const short *buffer, int buffer_size) {
    double sum_sq = 0.0;
    for (int i = 0; i < buffer_size; i++) {
        sum_sq += (double)buffer[i] * buffer[i];
    }
    return sqrt(sum_sq / buffer_size);
}

// Map amplitude to RGB color values
void map_amplitude_to_color(double amplitude, double sensitivity, int *red, int *green, int *blue) {
    // Non-linear mapping (logarithmic)
    double log_amplitude = log10(amplitude + 1) / log10(sensitivity + 1); // Normalize and take log

    // Map to RGB values (example: blue -> red)
    *red = (int)(log_amplitude * 255);
    *green = (int)((1 - log_amplitude) * 255);
    *blue = (int)((1 - log_amplitude) * 255);

    // Clamp values to 0-255 range
    if (*red > 255) *red = 255;
    if (*red < 0) *red = 0;
    if (*green > 255) *green = 255;
    if (*green < 0) *green = 0;
    if (*blue > 255) *blue = 255;
    if (*blue < 0) *blue = 0;
}

// Set LED color using pigpio
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

int main(int argc, char *argv[]) {
    int opt;
    short *audio_buffer;
    int red, green, blue;
    struct timeval start, end;
    double elapsed_time;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                sensitivity = atof(optarg);
                if (sensitivity <= 0) {
                    fprintf(stderr, "Error: Sensitivity must be positive.\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-s sensitivity]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes for PWM output
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Initialize ALSA
    if (init_alsa(&pcm_handle) != 0) {
        fprintf(stderr, "ALSA initialization failed\n");
        cleanup();
        return 1;
    }

    // Allocate audio buffer
    audio_buffer = (short *)malloc(PERIOD_SIZE * sizeof(short));
    if (audio_buffer == NULL) {
        fprintf(stderr, "Failed to allocate audio buffer\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        // Capture audio
        if (capture_audio(pcm_handle, audio_buffer, PERIOD_SIZE) != 0) {
            fprintf(stderr, "Error capturing audio, exiting...\n");
            break;
        }

        // Calculate RMS amplitude
        double amplitude = calculate_rms(audio_buffer, PERIOD_SIZE);

        // Map amplitude to color
        map_amplitude_to_color(amplitude, sensitivity, &red, &green, &blue);

        // Set LED color
        set_led_color(red, green, blue);

        // Delay
        usleep(10000); // 10 ms
    }

    // Cleanup
    free(audio_buffer);
    cleanup();

    return 0;
}

