#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 13
#define RELAY3_PIN 11
#define RELAY4_PIN 15

// Define the number of phases
#define NUM_PHASES 4

// Define the duration of each phase in seconds
#define SUNRISE_DURATION 3600
#define DAYTIME_DURATION 21600
#define SUNSET_DURATION 3600
#define NIGHTTIME_DURATION 50400

// Define the total duration of the simulation in seconds
#define TOTAL_DURATION (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION + NIGHTTIME_DURATION)

// Global variables for GPIO chip and lines
struct gpiod_chip *chip;
struct gpiod_line *relay1_line, *relay2_line, *relay3_line, *relay4_line;

// Function prototypes
int initialize_gpio(void);
void cleanup_gpio(void);
void signal_handler(int sig);
void run_simulation(void);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    cleanup_gpio();
    exit(0);
}

// Function to initialize GPIO lines
int initialize_gpio(void) {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    // Get the GPIO lines
    relay1_line = gpiod_chip_get_line(chip, RELAY1_PIN);
    relay2_line = gpiod_chip_get_line(chip, RELAY2_PIN);
    relay3_line = gpiod_chip_get_line(chip, RELAY3_PIN);
    relay4_line = gpiod_chip_get_line(chip, RELAY4_PIN);

    if (!relay1_line || !relay2_line || !relay3_line || !relay4_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO lines for output
    ret = gpiod_line_request_output(relay1_line, "sunrise_simulator", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay2_line, "sunrise_simulator", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay3_line, "sunrise_simulator", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    ret = gpiod_line_request_output(relay4_line, "sunrise_simulator", 0);
    if (ret < 0) {
        perror("Error requesting GPIO line for output");
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO lines
void cleanup_gpio(void) {
    if (relay1_line) {
        gpiod_line_release(relay1_line);
    }
    if (relay2_line) {
        gpiod_line_release(relay2_line);
    }
    if (relay3_line) {
        gpiod_line_release(relay3_line);
    }
    if (relay4_line) {
        gpiod_line_release(relay4_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

// Function to run the simulation
void run_simulation(void) {
    time_t start_time, current_time;
    double elapsed_time;
    int phase = 0;
    int duty_cycle = 0;
    int increment = 1; // Increase duty cycle during sunrise, decrease during sunset

    time(&start_time);

    while (1) {
        time(&current_time);
        elapsed_time = difftime(current_time, start_time);

        switch (phase) {
            case 0: // Sunrise
                if (elapsed_time < SUNRISE_DURATION) {
                    duty_cycle = (int)(((double)elapsed_time / SUNRISE_DURATION) * 100);
                    if (duty_cycle > 100) duty_cycle = 100;
                    gpiod_line_set_value(relay1_line, duty_cycle > 0);
                    gpiod_line_set_value(relay2_line, duty_cycle > 0);
                    gpiod_line_set_value(relay3_line, duty_cycle > 0);
                    gpiod_line_set_value(relay4_line, duty_cycle > 0);
                } else {
                    phase = 1;
                    time(&start_time);
                }
                break;
            case 1: // Daytime
                if (elapsed_time < (SUNRISE_DURATION + DAYTIME_DURATION)) {
                    gpiod_line_set_value(relay1_line, 1);
                    gpiod_line_set_value(relay2_line, 1);
                    gpiod_line_set_value(relay3_line, 1);
                    gpiod_line_set_value(relay4_line, 1);
                } else {
                    phase = 2;
                    time(&start_time);
                }
                break;
            case 2: // Sunset
                if (elapsed_time < (SUNRISE_DURATION + DAYTIME_DURATION + SUNSET_DURATION)) {
                    duty_cycle = 100 - (int)(((double)(elapsed_time - (SUNRISE_DURATION + DAYTIME_DURATION)) / SUNSET_DURATION) * 100);
                    if (duty_cycle < 0) duty_cycle = 0;
                    gpiod_line_set_value(relay1_line, duty_cycle > 0);
                    gpiod_line_set_value(relay2_line, duty_cycle > 0);
                    gpiod_line_set_value(relay3_line, duty_cycle > 0);
                    gpiod_line_set_value(relay4_line, duty_cycle > 0);
                } else {
                    phase = 3;
                    time(&start_time);
                }
                break;
            case 3: // Nighttime
                if (elapsed_time < TOTAL_DURATION) {
                    gpiod_line_set_value(relay1_line, 0);
                    gpiod_line_set_value(relay2_line, 0);
                    gpiod_line_set_value(relay3_line, 0);
                    gpiod_line_set_value(relay4_line, 0);
                } else {
                    phase = 0;
                    time(&start_time);
                }
                break;
        }

        usleep(100000); // Sleep for 100ms
    }
}

int main(void) {
    // Set up signal handling for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Run the simulation
    run_simulation();

    // Cleanup GPIO (this should not be reached unless the simulation loop is broken)
    cleanup_gpio();

    return 0;
}

