typedef struct {
    int gpio;
    time_t last_trigger_time;
} sensor_data_t;

// Array of sensor data
sensor_data_t sensors[] = {
    {SENSOR_1_GPIO, 0},
    {SENSOR_2_GPIO, 0},
    {SENSOR_3_GPIO, 0}
};

int main() {
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        perror("Failed to register signal handler");
        return 1;
    }

    if (initialize_gpio() != 0) {
