#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1 0x6B
#define SMPLRT_DIV 0x19
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_XOUT_L 0x44
#define GYRO_YOUT_H 0x45
#define GYRO_YOUT_L 0x46
#define GYRO_ZOUT_H 0x47
#define GYRO_ZOUT_L 0x48

// Sensitivity scale factor
#define GYRO_SENSITIVITY 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x_degps;
    float y_degps;
    float z_degps;
} gyro_data_t;

// Function prototypes
int initialize_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the MPU-6050
int initialize_mpu6050() {
    int retries = 3;
    while (retries > 0) {
        // Wake up the MPU-6050
        if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
            fprintf(stderr, "Error: Could not wake up MPU-6050. Retrying...\n");
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Set sample rate divider to 125 Hz
        if (i2cWriteByteData(i2c_handle, SMPLRT_DIV, 0x07) < 0) {
            fprintf(stderr, "Error: Could not set sample rate divider. Retrying...\n");
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        // Set gyroscope full-scale range to ±250°/s
        if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0x00) < 0) {
            fprintf(stderr, "Error: Could not set gyroscope full-scale range. Retrying...\n");
            retries--;
            gpioDelay(10000); // Wait 10ms before retrying
            continue;
        }

        printf("MPU-6050 initialized successfully.\n");
        return 0; // Initialization successful
    }

    fprintf(stderr, "Error: MPU-6050 initialization failed after multiple retries.\n");
    return -1; // Initialization failed
}

// Function to read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        data.x_degps = 0.0;
        data.y_degps = 0.0;
        data.z_degps = 0.0;
        return data;
    }

    // Combine high and low bytes, convert to signed 16-bit integers
    int16_t x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t y = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t z = (int16_t)((buffer[4] << 8) | buffer[5]);

    // Convert to degrees per second
    data.x_degps = (float)x / GYRO_SENSITIVITY;
    data.y_degps = (float)y / GYRO_SENSITIVITY;
    data.z_degps = (float)z / GYRO_SENSITIVITY;

    return data;
}

// Function to log data to a CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    fprintf(log_file, "%ld,%.2f,%.2f,%.2f\n", timestamp_ms, data.x_degps, data.y_degps, data.z_degps);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (initialize_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 10000000; // 10 ms

    while (!terminate) {
        gyro_data_t gyro_data = read_gyro_data();
        log_data(gyro_data);
        nanosleep(&sleep_time, NULL);
    }

    // Close log file and I2C bus
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

