#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define moisture threshold
#define MOISTURE_THRESHOLD 30

// Global variable for the log file
FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor(int zone);
void control_relay(int zone, int moisture_level);
void log_data(int zone, int moisture_level, int relay_state);
void cleanup_handler(int signum);

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("irrigation_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Install signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    // Main loop
    while (1) {
        // Read moisture sensors
        int moisture1 = read_moisture_sensor(1);
        int moisture2 = read_moisture_sensor(2);
        int moisture3 = read_moisture_sensor(3);
        int moisture4 = read_moisture_sensor(4);

        // Control relays based on moisture levels
        control_relay(1, moisture1);
        control_relay(2, moisture2);
        control_relay(3, moisture3);
        control_relay(4, moisture4);

        // Log data
        log_data(1, moisture1, (moisture1 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(2, moisture2, (moisture2 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(3, moisture3, (moisture3 < MOISTURE_THRESHOLD) ? 0 : 1);
        log_data(4, moisture4, (moisture4 < MOISTURE_THRESHOLD) ? 0 : 1);

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    return 0;
}

// Function to initialize pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to HIGH (deactivated state)
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Function to read moisture sensor
int read_moisture_sensor(int zone) {
    return rand() % 101;
}

// Function to control relay
void control_relay(int zone, int moisture_level) {
    int pin;

    switch (zone) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid zone number: %d\n", zone);
            return;
    }

