#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDR 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32

// GPIO pin for alarm
#define ALARM_PIN 27

// Freefall threshold (g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (seconds)
#define FREEFALL_DURATION 0.5

// I2C handle
int i2c_handle;

// Function prototypes
int init_adxl345();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
float convert_to_g(int16_t raw_value);
int detect_freefall(float x, float y, float z);
void trigger_alarm();
void log_freefall(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize ADXL345
    if (init_adxl345() != 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        int16_t raw_x, raw_y, raw_z;
        float x, y, z;

        // Read accelerometer data
        if (read_accelerometer(&raw_x, &raw_y, &raw_z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
            continue; // Continue to the next iteration
        }

        // Convert raw data to g-force
        x = convert_to_g(raw_x);
        y = convert_to_g(raw_y);
        z = convert_to_g(raw_z);

        // Detect freefall
        if (detect_freefall(x, y, z)) {
            trigger_alarm();
            log_freefall(x, y, z);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    return 0;
}

// Initialize ADXL345
int init_adxl345() {
    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return 1;
    }

    // Set data format: +/- 2g range, full resolution
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Failed to write to DATA_FORMAT register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to write to POWER_CTL register\n");
        i2cClose(i2c_handle);
        return 1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];

    // Read 6 bytes from DATAX0 register
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        return 1;
    }

    // Combine bytes to form 16-bit signed integers
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Convert raw data to g-force
float convert_to_g(int16_t raw_value) {
    return (float)raw_value / 256.0;
}

// Detect freefall
int detect_freefall(float x, float y, float z) {
    float magnitude = abs(x) + abs(y) + abs(z);
    return (magnitude < FREEFALL_THRESHOLD);
}

// Trigger alarm
void trigger_alarm() {
    gpioSetMode(ALARM_PIN, PI_OUTPUT);
    gpioWrite(ALARM_PIN, 1);
    gpioDelay(5000000); // 5 seconds
    gpioWrite(ALARM_PIN, 0);
}

// Log freefall event
void log_freefall(float x, float y, float z) {
    FILE *fp = fopen("freefall.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open freefall.log\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", s, x, y, z);
    fclose(fp);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed, exiting...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0);
    gpioTerminate();
    exit(0);
}

