#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <string.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TRIGGER_PULSE_DURATION 10 // Trigger pulse duration in microseconds
#define MAX_DISTANCE 4000.0      // Maximum measurable distance in cm
#define MAX_PULSE_WIDTH 23200.0   // Maximum pulse width before timeout (4 meters)
#define TIMEOUT_MS 100            // Timeout in milliseconds

// Global variables
static volatile uint32_t start_tick = 0;
static volatile uint32_t end_tick = 0;
static volatile int echo_received = 0;
static pthread_mutex_t mutex;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to send a 10 µs trigger pulse
void trigger_pulse() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(TRIGGER_PULSE_DURATION);
    gpioWrite(TRIG_PIN, 0);
}

// Interrupt handler for rising edge of the ECHO signal
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    start_tick = tick;
    echo_received = 1; // Indicate that the rising edge has been received
    pthread_mutex_unlock(&mutex);
}

// Interrupt handler for falling edge of the ECHO signal
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    pthread_mutex_lock(&mutex);
    end_tick = tick;
    pthread_mutex_unlock(&mutex);
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_width) {
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 1000000.0 to convert us to s and multiply by 2 for one-way distance
}

// Function to log distance to a file
void log_distance(double distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    uint64_t timestamp_ns = (uint64_t)ts.tv_sec * 1000000000ULL + (uint64_t)ts.tv_nsec;

    if (log_file != NULL) {
        fprintf(log_file, "%llu,%.2f\n", timestamp_ns, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0; // Stop the measurement loop

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(TRIG_PIN, NULL, NULL);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    // Destroy the mutex
    pthread_mutex_destroy(&mutex);

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Initialize mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handlers
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main measurement loop
    while (running) {
        trigger_pulse();
        gpioDelay(200); // Wait 200 ms before next trigger

        pthread_mutex_lock(&mutex);
        uint32_t pulse_width = end_tick - start_tick;
        echo_received = 0; // Reset the flag
        pthread_mutex_unlock(&mutex);

        // Validate pulse width
        if (pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Pulse width exceeds maximum value (%f us).\n", MAX_PULSE_WIDTH);
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Log distance
        log_distance(distance);

        printf("Distance: %.2f cm\n", distance);
    }

    return 0;
}

