    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        pthread_mutex_destroy(&mutex);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handlers
    gpioSetAlertFuncEx(ECHO_PIN, echo_rising_edge, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, echo_falling_edge, NULL);

    printf("Distance measurement started. Press Ctrl+C to exit.\n");

    // Main measurement loop
    while (running) {
        trigger_pulse();
        gpioDelay(200); // Wait 200 ms before next trigger

        pthread_mutex_lock(&mutex);
        uint32_t pulse_width = end_tick - start_tick;
        echo_received = 0; // Reset the flag
        pthread_mutex_unlock(&mutex);

        // Validate pulse width
        if (pulse_width > MAX_PULSE_WIDTH) {
            fprintf(stderr, "Error: Pulse width exceeds maximum value (%f us).\n", MAX_PULSE_WIDTH);
            continue; // Skip to the next iteration
        }

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        // Log distance
        log_distance(distance);

        printf("Distance: %.2f cm\n", distance);
    }

    return 0;
}

