#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <math.h>

// Constants
#define I2C_BUS 1
#define LIS3DH_ADDR 0x18
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define BUZZER_GPIO 17
#define NUM_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Configuration parameters
float freefall_threshold = 0.2;
float impact_threshold = 1.5;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void detect_freefall(float magnitude);
void detect_impact(float magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to initialize LIS3DH
int init_lis3dh() {
    // Set data rate to 100 Hz and full scale to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data
int read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int retries = NUM_RETRIES;

    while (retries > 0) {
        if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) == 6) {
            *x = (int16_t)((buffer[1] << 8) | buffer[0]);
            *y = (int16_t)((buffer[3] << 8) | buffer[2]);
            *z = (int16_t)((buffer[5] << 8) | buffer[4]);
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error, retrying...\n");
            gpioDelay(1000); // Wait 1ms before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read acceleration data after multiple retries.\n");
    return -1; // Failure
}

// Function to calculate acceleration magnitude
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    float x_g = (float)x / 16384.0;
    float y_g = (float)y / 16384.0;
    float z_g = (float)z / 16384.0;
    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Function to detect freefall
void detect_freefall(float magnitude) {
    if (magnitude < freefall_threshold) {
        printf("Freefall detected!\n");
    }
}

// Function to detect impact
void detect_impact(float magnitude) {
    if (magnitude > impact_threshold) {
        printf("Impact detected!\n");
        activate_buzzer();
    }
}

// Function to activate the buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    gpioDelay(1000);           // Wait for 1 second
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() < 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int16_t x, y, z;
    float magnitude;

    // Main loop
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            magnitude = calculate_magnitude(x, y, z);
            printf("Acceleration magnitude: %.2f g\n", magnitude);
            detect_freefall(magnitude);
            detect_impact(magnitude);
        } else {
            fprintf(stderr, "Failed to read acceleration data.\n");
        }

        gpioDelay(10); // Delay for 10ms (100 Hz data rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

