#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins for Motor 1 (X-axis)
#define MOTOR1_IN1 4
#define MOTOR1_IN2 17
#define MOTOR1_IN3 27
#define MOTOR1_IN4 22

// Define GPIO pins for Motor 2 (Y-axis)
#define MOTOR2_IN1 5
#define MOTOR2_IN2 6
#define MOTOR2_IN3 13
#define MOTOR2_IN4 19

// Define the number of steps per revolution for the 28BYJ-48 motor
#define STEPS_PER_REVOLUTION 2048.0

// Define the conversion factor from steps to millimeters
#define STEPS_PER_MM 10.0

// Define the delay between steps in microseconds
#define STEP_DELAY 1000

// Define the number of steps to draw the square
#define SQUARE_SIDE_LENGTH 50.0 // mm
#define SQUARE_STEPS (int)(SQUARE_SIDE_LENGTH * STEPS_PER_MM)

// Define the waveform sequence for single-coil excitation
const int waveform[] = {1, 0, 0, 0};

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void move_motor(int motor_id, int steps, int direction);
void draw_square();
void cleanup_handler(int signum);

// Function to move a motor a specified number of steps in a given direction
void move_motor(int motor_id, int steps, int direction) {
    int in1, in2, in3, in4;

    if (motor_id == 1) {
        in1 = MOTOR1_IN1;
        in2 = MOTOR1_IN2;
        in3 = MOTOR1_IN3;
        in4 = MOTOR1_IN4;
    } else if (motor_id == 2) {
        in1 = MOTOR2_IN1;
        in2 = MOTOR2_IN2;
        in3 = MOTOR2_IN3;
        in4 = MOTOR2_IN4;
    } else {
        fprintf(stderr, "Error: Invalid motor ID: %d\n", motor_id);
        return;
    }

    for (int i = 0; i < steps; i++) {
        if (direction == 1) { // Clockwise
            gpioWrite(in1, waveform[0]);
            gpioWrite(in2, waveform[1]);
            gpioWrite(in3, waveform[2]);
            gpioWrite(in4, waveform[3]);
        } else { // Counter-clockwise
            gpioWrite(in1, waveform[3]);
            gpioWrite(in2, waveform[2]);
            gpioWrite(in3, waveform[1]);
            gpioWrite(in4, waveform[0]);
        }
        gpioDelay(STEP_DELAY);
    }
}

// Function to draw a square
void draw_square() {
    // Move Motor 1 (X-axis)
    printf("Moving Motor 1 (X-axis) to draw square...\n");
    move_motor(1, SQUARE_STEPS, 1); // Clockwise
    printf("Motor 1 (X-axis) complete.\n");

    // Move Motor 2 (Y-axis)
    printf("Moving Motor 2 (Y-axis) to draw square...\n");
    move_motor(2, SQUARE_STEPS, 1); // Clockwise
    printf("Motor 2 (Y-axis) complete.\n");

    // Move Motor 1 (X-axis)
    printf("Moving Motor 1 (X-axis) back to start...\n");
    move_motor(1, SQUARE_STEPS, 0); // Counter-clockwise
    printf("Motor 1 (X-axis) back to start.\n");

    // Move Motor 2 (Y-axis)
    printf("Moving Motor 2 (Y-axis) back to start...\n");
    move_motor(2, SQUARE_STEPS, 0); // Counter-clockwise
    printf("Motor 2 (Y-axis) back to start.\n");
}

// Signal handler for Ctrl+C
void cleanup_handler(int signum) {
    printf("\nCaught signal %d, cleaning up...\n", signum);
    program_running = 0;

    // Stop both motors by setting all GPIO pins low
    gpioWrite(MOTOR1_IN1, 0);
    gpioWrite(MOTOR1_IN2, 0);
    gpioWrite(MOTOR1_IN3, 0);
    gpioWrite(MOTOR1_IN4, 0);
    gpioWrite(MOTOR2_IN1, 0);
    gpioWrite(MOTOR2_IN2, 0);
    gpioWrite(MOTOR2_IN3, 0);
    gpioWrite(MOTOR2_IN4, 0);

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, cleanup_handler);

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR1_IN4, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR2_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO mode\n");
        gpioTerminate();
        return 1;
    }

    // Draw the square
    draw_square();

    // Cleanup and exit
    cleanup_handler(0);

    return 0;
}

