    return gpioRead(gpio_pin);
}

// Function to add a reading to the circular buffer
void add_reading(CircularBuffer *buffer, int left, int center, int right) {
    buffer->readings[buffer->head].left = left;
    buffer->readings[buffer->head].center = center;
    buffer->readings[buffer->head].right = right;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Function to check if the center sensor has been no line for 5 consecutive readings
int check_center_no_line(const CircularBuffer *buffer) {
    if (buffer->count < BUFFER_SIZE) return 0; // Not enough readings

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer->head - 1 - i + BUFFER_SIZE) % BUFFER_SIZE; // Corrected index calculation
        if (buffer->readings[index].center == 0) {
            return 0; // Found a line, not no line
        }
    }
    return 1; // No line detected for all 5 readings
}

