}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(ALERT_PIN, 0); // Ensure ALERT_PIN is LOW
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    cleanup_gpio();
    exit(0);
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Initialize circular buffer
    line_buffer.head = 0;
    line_buffer.count = 0;

    printf("Line following robot started. Press Ctrl+C to exit.\n");

    while (running) {
        // Read sensor values
        int left = read_sensor(LEFT_SENSOR);
        int center = read_sensor(CENTER_SENSOR);
        int right = read_sensor(RIGHT_SENSOR);

        // Add reading to circular buffer
        add_reading(&line_buffer, left, center, right);

        // Check for no line detection
