#define CONVERSION_TIMEOUT_US 50000 // 50ms
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device();
int read_register(int handle, uint8_t reg);
int write_register(int handle, uint8_t reg, uint8_t value);
int start_conversion(int handle);
int read_field_data(int handle, int16_t *field_raw);
float convert_to_mT(int16_t field_raw);
int control_relay(int gpio, int state);
int log_event(const char *message);
void signal_handler(int signal);

// Structure for sensor configuration (optional)
typedef struct {
    int i2c_bus;
    int i2c_address;
    int relay_gpio;
    float field_threshold;
    int sample_interval_ms;
} sensor_config_t;

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to open I2C device: %d", i2c_handle);
        log_event(error_message);
        return -1;
    }
    return 0;
}

// Read a single byte from a register
int read_register(int handle, uint8_t reg) {
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to read register 0x%02X: %d", reg, value);
        log_event(error_message);
        return -1;
    }
    return value;
}

// Write a single byte to a register
int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "Failed to write 0x%02X to register 0x%02X: %d", value, reg, result);
        log_event(error_message);
        return -1;
    }
    return 0;
}

// Start a conversion
int start_conversion(int handle) {
    if (write_register(handle, 0xC1, 0x01) < 0) {
        log_event("Failed to start conversion");
        return -1;
    }
    return 0;
}

// Read field data
int read_field_data(int handle, int16_t *field_raw) {
    int lsb, msb;

    lsb = read_register(handle, 0xC0);
    if (lsb < 0) return -1;

    msb = read_register(handle, 0xC1);
    if (msb < 0) return -1;

    *field_raw = (msb << 8) | lsb;
    return 0;
}

