#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define PORT 5000
#define GPIO_PIN 18
#define LOG_FILE "relay_log.txt"

int server_fd, new_socket;
FILE *log_file;

// Function to log events with timestamps
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[26];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "[%s] %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Shutting down gracefully...\n");
        log_event("Server shutting down...");

        // Close socket
        if (new_socket > 0) {
            close(new_socket);
        }
        if (server_fd > 0) {
            close(server_fd);
        }

        // Close log file
        if (log_file != NULL) {
            fclose(log_file);
        }

        // Turn off relay
        gpioWrite(GPIO_PIN, 0);

        // Terminate pigpio
        gpioTerminate();

        exit(0);
    }
}

// Function to handle client connections
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t bytes_received;

    bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (bytes_received < 0) {
        perror("recv failed");
        log_event("Error receiving data from client");
        close(client_socket);
        return;
    } else if (bytes_received == 0) {
        printf("Client disconnected.\n");
        log_event("Client disconnected");
        close(client_socket);
        return;
    }

    // Trim trailing whitespace
    size_t len = strlen(buffer);
    while (len > 0 && isspace(buffer[len - 1])) {
        buffer[--len] = 0;
    }

    if (strcasecmp(buffer, "ON") == 0) {
        gpioWrite(GPIO_PIN, 1);
        log_event("Relay ON");
        send(client_socket, "ON", strlen("ON"), 0);
    } else if (strcasecmp(buffer, "OFF") == 0) {
        gpioWrite(GPIO_PIN, 0);
        log_event("Relay OFF");
        send(client_socket, "OFF", strlen("OFF"), 0);
    } else {
        log_event("Invalid command received");
        send(client_socket, "Invalid command", strlen("Invalid command"), 0);
    }

    close(client_socket);
}

int main() {
    struct sockaddr_in address;
    int opt = 1;
    int addrlen = sizeof(address);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    log_event("Server started");

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_event("pigpio initialisation failed");
        fclose(log_file);
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        log_event("Socket creation failed");
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Set socket options to reuse address
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        log_event("setsockopt failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        log_event("Socket bind failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        log_event("Socket listen failed");
        close(server_fd);
        gpioTerminate();
        fclose(log_file);
        return 1;
    }

    printf("Server listening on port %d\n", PORT);
    log_event("Server listening for connections");

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Accept connections in a loop
    while (1) {
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t*)&addrlen)) < 0) {
            perror("accept");
            log_event("Socket accept failed");
            continue; // Continue listening for new connections
        }

        printf("Connection accepted\n");
        log_event("Client connected");

        handle_client(new_socket);
    }

    return 0;
}

