#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x08
#define SENSOR2_ADDR 0x09
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0
#define SCALE_FACTOR 1500.0
#define CRC_POLYNOMIAL 0x31
#define CRC_INIT 0xFF
#define CRC_FINAL_XOR 0x00

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int open_i2c_device(int bus, int addr);
int write_i2c_command(int handle, const char *command, int len);
int read_i2c_data(int handle, char *data, int len);
uint8_t calculate_crc(const char *data, int len);
float convert_to_ml_min(int16_t raw_value);
void control_relay(int gpio, int state);
void log_flow_rates(float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float flow_rate;
    int16_t raw_value;
} sensor_data_t;

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Open I2C devices
    i2c_handle1 = open_i2c_device(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1. Exiting.\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = open_i2c_device(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Configure relay GPIO
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(RELAY_GPIO, 0); // De-energize relay on startup

    // Main loop
    while (!terminate) {
        char data[3];
        sensor_data_t sensor1_data, sensor2_data;

        // Read data from sensor 1
        if (read_i2c_data(i2c_handle1, data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 1.\n");
            sensor1_data.flow_rate = -1.0; // Indicate error
        } else {
            uint8_t crc = calculate_crc(data, 2);
            if (crc != (uint8_t)data[2]) {
                fprintf(stderr, "CRC mismatch on sensor 1 data.\n");
                sensor1_data.flow_rate = -1.0; // Indicate error
            } else {
                sensor1_data.raw_value = (int16_t)((data[0] << 8) | data[1]);
                sensor1_data.flow_rate = convert_to_ml_min(sensor1_data.raw_value);
            }
        }

        // Read data from sensor 2
        if (read_i2c_data(i2c_handle2, data, 3) != 0) {
            fprintf(stderr, "Error reading data from sensor 2.\n");
            sensor2_data.flow_rate = -1.0; // Indicate error
        } else {
            uint8_t crc = calculate_crc(data, 2);
            if (crc != (uint8_t)data[2]) {
                fprintf(stderr, "CRC mismatch on sensor 2 data.\n");
                sensor2_data.flow_rate = -1.0; // Indicate error
            } else {
                sensor2_data.raw_value = (int16_t)((data[0] << 8) | data[1]);
                sensor2_data.flow_rate = convert_to_ml_min(sensor2_data.raw_value);
            }
        }

        // Control relay based on flow rates
        if (sensor1_data.flow_rate >= 0 && sensor2_data.flow_rate >= 0) {
            if (sensor1_data.flow_rate < FLOW_THRESHOLD && sensor2_data.flow_rate < FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Energize relay
            } else {
                control_relay(RELAY_GPIO, 0); // De-energize relay
            }
        }

        // Log flow rates
        if (sensor1_data.flow_rate >= 0 && sensor2_data.flow_rate >= 0) {
            log_flow_rates(sensor1_data.flow_rate, sensor2_data.flow_rate);
        }

        gpioDelay(100); // Polling interval
    }

    // Cleanup and exit
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C device
int open_i2c_device(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02x: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Write I2C command
int write_i2c_command(int handle, const char *command, int len) {
    int result = i2cWriteDevice(handle, command, len);
