#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define constants
#define DRY_THRESHOLD 3
#define MOTOR_RUN_TIME 5000 // 5 seconds in milliseconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_detected = gpioRead(RAIN_SENSOR_PIN);
    if (rain_detected < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", rain_detected);
        return -1; // Indicate error
    }
    return rain_detected;
}

// Function to close the window
void close_window() {
    syslog(LOG_INFO, "Closing window...");

    // Set motor control pins
    if (gpioWrite(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_ENA_PIN HIGH: %d", gpioWrite(MOTOR_ENA_PIN, 1));
    }
    if (gpioWrite(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN1_PIN HIGH: %d", gpioWrite(MOTOR_IN1_PIN, 1));
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN2_PIN LOW: %d", gpioWrite(MOTOR_IN2_PIN, 0));
    }

    // Run motor for specified time
    gpioDelay(MOTOR_RUN_TIME);

    // Stop motor
    stop_motor();

    syslog(LOG_INFO, "Window closed.");
}

// Function to stop the motor
void stop_motor() {
    syslog(LOG_INFO, "Stopping motor...");

    // Set motor control pins to LOW
    if (gpioWrite(MOTOR_ENA_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_ENA_PIN LOW: %d", gpioWrite(MOTOR_ENA_PIN, 0));
    }
    if (gpioWrite(MOTOR_IN1_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN1_PIN LOW: %d", gpioWrite(MOTOR_IN1_PIN, 0));
    }
    if (gpioWrite(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN2_PIN LOW: %d", gpioWrite(MOTOR_IN2_PIN, 0));
    }

    syslog(LOG_INFO, "Motor stopped.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    program_running = 0;
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed: %d", gpioInitialise());
        closelog();
        return 1;
    }
    syslog(LOG_INFO, "pigpio initialised successfully.");

    // Set GPIO modes
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "Error setting RAIN_SENSOR_PIN to input: %d", gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT));
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_ENA_PIN to output: %d", gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT));
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN1_PIN to output: %d", gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT));
        gpioTerminate();
        closelog();
        return 1;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Error setting MOTOR_IN2_PIN to output: %d", gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT));
        gpioTerminate();
        closelog();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int dry_count = 0;
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected < 0) {
            // Error reading sensor, but continue running
            gpioDelay(200);
            continue;
        }

        if (rain_detected == 0) { // Rain detected (LOW signal)
            if (dry_count >= DRY_THRESHOLD) {
                close_window();
                dry_count = 0; // Reset dry count after closing window
            } else {
                dry_count++;
            }
        } else { // Dry (HIGH signal)
            dry_count = 0; // Reset dry count if still dry
        }

        gpioDelay(200); // Poll every 200 ms
    }

    // Stop motor before exiting
    stop_motor();

    // Terminate pigpio
    gpioTerminate();
    syslog(LOG_INFO, "pigpio terminated.");

    // Close syslog
    closelog();

    return 0;
}

