#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths (microseconds)
#define LOCKED_PULSE_WIDTH 2000
#define UNLOCKED_PULSE_WIDTH 1000

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
    program_running = 0;
}

// Function to set the servo pulse width
int set_servo_pulse_width(int pulse_width) {
    int result = gpioServo(SERVO_PIN, pulse_width);
    if (result != 0) {
        fprintf(stderr, "Error setting servo pulse width: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to lock the door
int lock_door() {
    printf("Locking door...\n");
    if (set_servo_pulse_width(LOCKED_PULSE_WIDTH) != 0) {
        return -1;
    }
    return 0;
}

// Function to unlock the door
int unlock_door() {
    printf("Unlocking door...\n");
    if (set_servo_pulse_width(UNLOCKED_PULSE_WIDTH) != 0) {
        return -1;
    }
    return 0;
}

// Function to read the button state with debouncing
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
    return button_state;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable internal pull-ups for the buttons
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_pressed = (read_button(LOCK_BUTTON_PIN) == 0);
        int unlock_button_pressed = (read_button(UNLOCK_BUTTON_PIN) == 0);

        // Handle button presses
        if (lock_button_pressed) {
            lock_door();
        }
        if (unlock_button_pressed) {
            unlock_door();
        }

        // Small delay to avoid busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Stop the servo and terminate pigpio
    set_servo_pulse_width(0); // Stop the servo
    gpioTerminate();

    printf("Door lock control system stopped.\n");

    return 0;
}

