#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define DEBOUNCE_MS 200

// Global variables
int i2c_handle;
volatile int relay_state = 0; // 0 = OFF, 1 = ON
volatile unsigned long last_touch_time = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void toggle_relay();
void cleanup(int signal);

// Signal handler for graceful shutdown
void cleanup(int signal) {
    printf("\nCleaning up and exiting...\n");
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is OFF
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// MPR121 Initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(10000); // Wait for reset to complete

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) return -1; // MHD
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) return -1; // NHD
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) return -1; // NCL
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x01) < 0) return -1; // FDL

    // Set debounce
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x0A) < 0) return -1; // Debounce = 10ms

    // Set FFI/SFI/CDT
    if (i2cWriteByteData(i2c_handle, 0x2F, 0x01) < 0) return -1; // FFI
    if (i2cWriteByteData(i2c_handle, 0x30, 0x01) < 0) return -1; // SFI
    if (i2cWriteByteData(i2c_handle, 0x31, 0x01) < 0) return -1; // CDT

    // Auto-config
    if (i2cWriteByteData(i2c_handle, 0x7B, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x7C, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x7D, 0x01) < 0) return -1;

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) return -1; // Enable electrodes 0-3

    return 0;
}

// Function to read touch status from MPR121
int mpr121_read_touch_status() {
    int touch_status = i2cReadWordData(i2c_handle, 0x00);
    if (touch_status < 0) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }
    return touch_status;
}

// Function to toggle the relay
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    printf("MPR121 and Relay Control Program started\n");

    // Main loop
    while (1) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
            continue;
        }

        // Check if electrode 0 is touched (bit 0 of touch_status)
        if (touch_status & 0x0001) {
            unsigned long current_time = gpioTick();
            if (current_time - last_touch_time > DEBOUNCE_MS * 1000) {
                toggle_relay();
                last_touch_time = current_time;
            }
        }

        gpioDelay(50000); // Check every 50ms
    }

    return 0;
}

