#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pthread.h>
#include <errno.h>
#include <stdarg.h>
#include <fcntl.h>
#include <sys/file.h>
#include <gpiod.h>

// Configuration
#define SERVO_PIN 17
#define PIR_PIN 4
#define TCP_PORT 5000
#define PWM_FREQUENCY 50
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY) // Period in microseconds
#define PWM_HIGH_US 1000 // 1ms
#define PWM_LOW_US 1000  // 1ms
#define LOG_FILE "security.log"

// Global variables
static int server_fd = -1;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *servo_line = NULL;
static struct gpiod_line *pir_line = NULL;
static pthread_t pwm_thread;
static volatile int running = 1;
static int log_fd = -1;

// Function prototypes
void log_message(int priority, const char *format, ...);
void *pwm_thread_func(void *arg);
void signal_handler(int sig);
int parse_command(char *command, char *action, int *angle);
int set_servo_angle(int angle);
int read_pir_sensor();
int handle_client(int client_fd);
int setup_gpio();
void cleanup_gpio();

// Logging function
void log_message(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    // Get current timestamp
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Log to syslog
    vsyslog(priority, format, args);

    // Log to file
    if (log_fd != -1) {
        flock(log_fd, LOCK_EX);
        dprintf(log_fd, "%s ", timestamp);
        vdprintf(log_fd, format, args);
        flock(log_fd, LOCK_UN);
    }

    va_end(args);
}

// PWM thread function
void *pwm_thread_func(void *arg) {
    (void)arg; // Suppress unused parameter warning
    struct timespec high_time = {0, PWM_HIGH_US * 1000};
    struct timespec low_time = {0, PWM_LOW_US * 1000};

    while (running) {
        if (gpiod_line_set_value(servo_line, 1) < 0) {
            log_message(LOG_ERR, "Error setting servo line high: %s", strerror(errno));
            break;
        }
        nanosleep(&high_time, NULL);

        if (gpiod_line_set_value(servo_line, 0) < 0) {
            log_message(LOG_ERR, "Error setting servo line low: %s", strerror(errno));
            break;
        }
        nanosleep(&low_time, NULL);
    }

    return NULL;
}

// Signal handler
void signal_handler(int sig) {
    log_message(LOG_INFO, "Signal received: %d. Shutting down...", sig);
    running = 0;

    // Cancel PWM thread
    pthread_cancel(pwm_thread);
    pthread_join(pwm_thread, NULL);

    // Close socket
    if (server_fd != -1) {
        close(server_fd);
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close log file
    if (log_fd != -1) {
        close(log_fd);
    }

    closelog();
    exit(0);
}

// Command parsing function
int parse_command(char *command, char *action, int *angle) {
    if (sscanf(command, "%s %d", action, angle) == 2) {
        if (strcmp(action, "SERVO") == 0 && *angle >= 0 && *angle <= 180) {
            return 0; // Success
        }
    } else if (strcmp(command, "PIR") == 0) {
        return 0; // Success
    }
    return -1; // Failure
}

// Servo control function
int set_servo_angle(int angle) {
    // Calculate the pulse width based on the angle (0-180)
    // Assuming a 20ms period (50Hz) and a 1ms pulse width (1000us)
    // The pulse width is calculated as a percentage of the period: pulse_width = angle * (period / 180)
    // For example, angle 90 (90 * (20000 / 180) = 10000 us, which is 50% of the period.
    // In this example, we are using a period of 1ms, so the pulse width is directly proportional to the angle.

    // Convert angle to microseconds
    int pulse_width_us = (int)(((float)angle / 180.0) * PWM_PERIOD_US);

    // Calculate the high time and low time
    struct timespec high_time = {0, pulse_width_us * 1000};
    struct timespec low_time = {0, (PWM_PERIOD_US - pulse_width_us) * 1000};

    // Set the servo line high
    if (gpiod_line_set_value(servo_line, 1) < 0) {
        log_message(LOG_ERR, "Error setting servo line high: %s", strerror(errno));
        return -1;
    }
    nanosleep(&high_time, NULL);

    // Set the servo line low
