#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define BH1750_ADDR 0x23
#define GROW_LIGHT_GPIO 23
#define LUX_THRESHOLD 150.0
#define I2C_BUS 1
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL 2 // seconds

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void control_grow_light(float lux);
void log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler
void signal_handler(int signal) {
    terminate = 1;
    printf("Signal received, cleaning up...\n");
}

// Initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750
int read_bh1750(float *lux) {
    char config_cmd = 0x20; // One-Time High-Resolution Mode
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 120 ms)
    gpioDelay(120000); // 120 ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the grow light relay
void control_grow_light(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(GROW_LIGHT_GPIO, 1); // Activate grow light
        printf("Grow light ON (Lux: %.2f)\n", lux);
    } else {
        gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate grow light
        printf("Grow light OFF (Lux: %.2f)\n", lux);
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for grow light relay
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_grow_light(lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor!\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

