    return 0;
}

// Read lux value from BH1750
int read_bh1750(float *lux) {
    char config_cmd = 0x20; // One-Time High-Resolution Mode
    char buffer[2];
    int result;

    // Send configuration command
    result = i2cWriteByte(i2c_handle, config_cmd);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for conversion (at least 120 ms)
    gpioDelay(120000); // 120 ms

    // Read 2 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Convert to lux
    unsigned int raw_value = (buffer[0] << 8) | buffer[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Control the grow light relay
void control_grow_light(float lux) {
    if (lux < LUX_THRESHOLD) {
        gpioWrite(GROW_LIGHT_GPIO, 1); // Activate grow light
        printf("Grow light ON (Lux: %.2f)\n", lux);
    } else {
        gpioWrite(GROW_LIGHT_GPIO, 0); // Deactivate grow light
        printf("Grow light OFF (Lux: %.2f)\n", lux);
    }
}

// Log data to file
void log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO mode for grow light relay
    gpioSetMode(GROW_LIGHT_GPIO, PI_OUTPUT);
    gpioWrite(GROW_LIGHT_GPIO, 0); // Ensure relay is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    // Main loop
    while (!terminate) {
        if (read_bh1750(&lux) == 0) {
            control_grow_light(lux);
            log_data(lux);
        } else {
            fprintf(stderr, "Error reading BH1750 sensor!\n");
        }

        gpioDelay(SAMPLE_INTERVAL * 1000000); // Delay for 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

