#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <getopt.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Default values
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_SCALE 1.0
#define DEFAULT_DURATION 200

// Global variables
static volatile int running = 1;
static double threshold = DEFAULT_THRESHOLD;
static double scale = DEFAULT_SCALE;
static int duration = DEFAULT_DURATION;
static int tare_count = 10;
static int read_count = 5;

// Function prototypes
int read_hx711(int *raw_value);
double calculate_weight(int raw_value, double scale, int tare_offset);
void control_solenoid(int duration);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    syslog(LOG_INFO, "Cleaning up resources...");
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is LOW
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog
    exit(0);
}

// Function to read data from HX711
int read_hx711(int *raw_value) {
    int i;
    int data[3];
    int timeout = 1000; // Timeout after 1 second

    // Wait for DOUT to go LOW
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Wait 1 ms
        timeout--;
    }

    if (timeout == 0) {
        syslog(LOG_ERR, "HX711 timeout waiting for data ready signal.");
        return -1; // Timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 3; i++) {
        data[i] = 0;
        for (int j = 0; j < 8; j++) {
            gpioWrite(HX711_SCK, 1);
            gpioDelay(1); // Short delay
            data[i] = data[i] << 1;
            if (gpioRead(HX711_DOUT)) {
                data[i]++;
            }
            gpioWrite(HX711_SCK, 0);
            gpioDelay(1); // Short delay
        }
    }

    // Combine the three bytes into a 24-bit value
    *raw_value = (data[0] << 16) | (data[1] << 8) | data[2];

    // Select Channel A / Gain 128 (one clock pulse)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Short delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Short delay

    return 0; // Success
}

// Function to calculate weight
double calculate_weight(int raw_value, double scale, int tare_offset) {
    return (double)(raw_value - tare_offset) / scale;
}

// Function to control the solenoid
void control_solenoid(int duration) {
    gpioWrite(SOLENOID_PIN, 1); // Set solenoid HIGH
    gpioDelay(duration);        // Wait for specified duration
    gpioWrite(SOLENOID_PIN, 0); // Set solenoid LOW
}

int main(int argc, char *argv[]) {
    int opt;
    int tare_offset = 0;
    int raw_value;
    double weight;
    int retry_count;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                break;
            case 's':
                scale = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-s scale] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Set solenoid LOW initially
    gpioWrite(SOLENOID_PIN, 0);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Tare the load cell
    syslog(LOG_INFO, "Taring load cell...");
    for (int i = 0; i < tare_count; i++) {
        retry_count = 0;
        while (retry_count < 3) {
            if (read_hx711(&raw_value) == 0) {
                tare_offset += raw_value;
                break; // Success, move to the next iteration
            } else {
                syslog(LOG_ERR, "Tare read failed, retrying... (%d/%d)", retry_count + 1, 3);
                retry_count++;
                gpioDelay(10); // Small delay before retrying
            }
        }
        if (retry_count == 3) {
            syslog(LOG_ERR, "Tare failed after multiple retries.");
            cleanup();
        }
    }
    tare_offset /= tare_count;
    syslog(LOG_INFO, "Tare offset: %d", tare_offset);

    // Main loop
    while (running) {
        int sum = 0;
        for (int i = 0; i < read_count; i++) {
            retry_count = 0;
            while (retry_count < 3) {
                if (read_hx711(&raw_value) == 0) {
                    sum += raw_value;
                    break; // Success, move to the next iteration
                } else {
                    syslog(LOG_ERR, "Read failed, retrying... (%d/%d)", retry_count + 1, 3);
                    retry_count++;
                    gpioDelay(10); // Small delay before retrying
                }
            }
            if (retry_count == 3) {
                syslog(LOG_ERR, "Read failed after multiple retries.");
                cleanup();
            }
        }
        int average_raw = sum / read_count;

        weight = calculate_weight(average_raw, scale, tare_offset);

        syslog(LOG_INFO, "Weight: %.2f grams", weight);

        if (weight > threshold) {
            syslog(LOG_INFO, "Threshold exceeded, activating solenoid for %d ms", duration);
            control_solenoid(duration);
        }

        gpioDelay(500); // Poll every 500 ms
    }

    // Cleanup and exit
    cleanup();

    return 0;
}

