#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <mosquitto.h>
#include <pigpio.h>

#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_KEEPALIVE 60
#define MQTT_CLIENT_ID "relay_controller_1"
#define MQTT_TOPIC "home/lights/control"
#define GPIO_PIN 17

static struct mosquitto *mosq = NULL;
static volatile int running = 1;

// Function to log messages to syslog
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
}

// Function to handle MQTT connection
int mqtt_connect_and_subscribe(struct mosquitto **mosq) {
    int rc;

    rc = mosquitto_connect(*mosq, MQTT_HOST, MQTT_PORT, MQTT_KEEPALIVE);
    if (rc != MOSQ_ERR_SUCCESS) {
        char *connack_string = mosquitto_connack_string(rc);
        log_message(LOG_ERR, connack_string);
        free(connack_string);
        return rc;
    }

    rc = mosquitto_subscribe(*mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message(LOG_ERR, "Failed to subscribe to topic");
        return rc;
    }

    log_message(LOG_INFO, "Connected to MQTT broker and subscribed to topic");
    return MOSQ_ERR_SUCCESS;
}

// Function to handle MQTT disconnection
void mqtt_disconnect(struct mosquitto **mosq) {
    if (*mosq) {
        mosquitto_disconnect(*mosq);
        mosquitto_destroy(*mosq);
        *mosq = NULL;
        log_message(LOG_INFO, "Disconnected from MQTT broker");
    }
}

// Function to handle MQTT messages
void message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        char *payload = (char *)message->payload;
        if (strcmp(payload, "ON") == 0) {
            gpioWrite(GPIO_PIN, 1); // Turn relay ON
            log_message(LOG_INFO, "Received ON, turning relay ON");
        } else if (strcmp(payload, "OFF") == 0) {
            gpioWrite(GPIO_PIN, 0); // Turn relay OFF
            log_message(LOG_INFO, "Received OFF, turning relay OFF");
        } else {
            log_message(LOG_ERR, "Received invalid payload");
        }
    } else {
        log_message(LOG_ERR, "Received empty message");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        running = 0;
    }
}

int main() {
    int rc;

    // Initialize syslog
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Initialize relay to OFF
    log_message(LOG_INFO, "GPIO initialized and set to OFF");

    // Initialize libmosquitto
    mosquitto_lib_init();

    // Create a new mosquitto client instance
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message(LOG_ERR, "Failed to create mosquitto client instance");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set callbacks
    mosquitto_message_callback_set(mosq, message_callback);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        rc = mqtt_connect_and_subscribe(&mosq);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "Failed to connect to MQTT broker, retrying in 5 seconds");
            sleep(5);
            continue;
        }

        rc = mosquitto_loop_forever(mosq, -1, 1); // -1 timeout means blocking
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message(LOG_ERR, "MQTT loop error, attempting to reconnect");
            mqtt_disconnect(&mosq);
            sleep(5);
        }
    }

    // Cleanup
    mqtt_disconnect(&mosq);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is OFF on exit
    gpioTerminate();
    mosquitto_lib_cleanup();
    closelog();

    return 0;
}

