#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <pthread.h>
#include <string.h>

// Motor A GPIOs
#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18

// Motor B GPIOs
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

// Encoder A GPIOs
#define ENCODER_A_A 4
#define ENCODER_A_B 5

// Encoder B GPIOs
#define ENCODER_B_A 6
#define ENCODER_B_B 12

// PWM frequency (Hz)
#define PWM_FREQUENCY 10000

// Target RPM
#define TARGET_RPM 50.0

// PI controller parameters
#define Kp 0.5
#define Ki 0.05

// Encoder stall detection threshold (ticks per second)
#define ENCODER_STALL_THRESHOLD 1.0

// PWM duty cycle clamping values
#define MIN_DUTY_CYCLE 0
#define MAX_DUTY_CYCLE 255

// Global variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile int running = 1; // Flag to control the main loop

// Mutexes for thread-safe access to encoder counts
pthread_mutex_t encoder_a_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder_b_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void signal_handler(int signal);
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user);
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_rpm(int encoder_count);
double calculate_error(double target_rpm, double current_rpm);
double calculate_proportional(double error);
double calculate_integral(double error, double integral);
int calculate_pwm(double proportional, double integral);
void set_motor_direction(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4, int direction);
void set_motor_speed(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4, int pwm_duty_cycle);
void check_encoder_stall(int encoder_a_count, int encoder_b_count);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0; // Set the flag to exit the main loop
    set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0); // Stop motors
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

// Interrupt service routine for Encoder A
void encoder_a_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder_a_mutex);
    encoder_a_count++;
    pthread_mutex_unlock(&encoder_a_mutex);
}

// Interrupt service routine for Encoder B
void encoder_b_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user; // unused

    pthread_mutex_lock(&encoder_b_mutex);
    encoder_b_count++;
    pthread_mutex_unlock(&encoder_b_mutex);
}

// Function to calculate RPM from encoder count
double calculate_rpm(int encoder_count) {
    // Assuming 64 ticks per revolution and 100 ms period
    return (double)encoder_count * 60000.0 / 64.0; // RPM
}

// Function to calculate the error between target and current RPM
double calculate_error(double target_rpm, double current_rpm) {
    return target_rpm - current_rpm;
}

// Function to calculate the proportional term
double calculate_proportional(double error) {
    return Kp * error;
}

// Function to calculate the integral term
double calculate_integral(double error, double integral) {
    return integral + Ki * error;
}

// Function to calculate the PWM duty cycle
int calculate_pwm(double proportional, double integral) {
    double output = proportional + integral;

    // Clamp the output to the valid range
    if (output < MIN_DUTY_CYCLE) {
        output = MIN_DUTY_CYCLE;
    } else if (output > MAX_DUTY_CYCLE) {
        output = MAX_DUTY_CYCLE;
    }

    return (int)output;
}

// Function to set the direction of a motor
void set_motor_direction(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4, int direction) {
    if (direction == 1) { // Forward
        gpioWrite(motor_a_in1, 1);
        gpioWrite(motor_a_in2, 0);
        gpioWrite(motor_b_in3, 1);
        gpioWrite(motor_b_in4, 0);
    } else { // Reverse
        gpioWrite(motor_a_in1, 0);
        gpioWrite(motor_a_in2, 1);
        gpioWrite(motor_b_in3, 0);
        gpioWrite(motor_b_in4, 1);
    }
}

// Function to set the speed of a motor using PWM
void set_motor_speed(int motor_a_in1, int motor_a_in2, int motor_b_in3, int motor_b_in4, int pwm_duty_cycle) {
    gpioPWM(motor_a_in1, pwm_duty_cycle);
    gpioPWM(motor_b_in3, pwm_duty_cycle);
}

// Function to check for encoder stall
void check_encoder_stall(int encoder_a_count, int encoder_b_count) {
    static time_t last_non_zero_time_a = 0;
    static time_t last_non_zero_time_b = 0;
    time_t current_time = time(NULL);

    if (encoder_a_count > 0) {
        last_non_zero_time_a = current_time;
    }
    if (encoder_b_count > 0) {
        last_non_zero_time_b = current_time;
    }

    double time_since_a_last_non_zero = difftime(current_time, last_non_zero_time_a);
    double time_since_b_last_non_zero = difftime(current_time, last_non_zero_time_b);

    if (time_since_a_last_non_zero > 2.0 && encoder_a_count == 0) {
        printf("WARNING: Encoder A stalled!\n");
    }
    if (time_since_b_last_non_zero > 2.0 && encoder_b_count == 0) {
        printf("WARNING: Encoder B stalled!\n");
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR_A_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR_B_IN4, PI_OUTPUT);

    gpioSetMode(ENCODER_A_A, PI_INPUT);
    gpioSetMode(ENCODER_A_B, PI_INPUT);
    gpioSetMode(ENCODER_B_A, PI_INPUT);
    gpioSetMode(ENCODER_B_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR_A_IN1, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR_B_IN3, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_A_IN1, 255);
    gpioSetPWMrange(MOTOR_B_IN3, 255);

    // Set PWM duty cycle (initially 0)
    gpioPWM(MOTOR_A_IN1, 0);
    gpioPWM(MOTOR_B_IN3, 0);

    // Set direction to forward
    set_motor_direction(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 1);

    // Register interrupt service routines
    gpioSetISRFuncEx(ENCODER_A_A, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_A_B, RISING_EDGE, 0, encoder_a_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_A, RISING_EDGE, 0, encoder_b_isr, NULL);
    gpioSetISRFuncEx(ENCODER_B_B, RISING_EDGE, 0, encoder_b_isr, NULL);

    // Install signal handler
    signal(SIGINT, signal_handler);

    // PI controller variables
    double integral_a = 0.0;
    double integral_b = 0.0;

    // Main control loop
    while (running) {
        // Read encoder counts
        int current_encoder_a_count;
        int current_encoder_b_count;

        pthread_mutex_lock(&encoder_a_mutex);
        current_encoder_a_count = encoder_a_count;
        encoder_a_count = 0; // Reset encoder count for next iteration
        pthread_mutex_unlock(&encoder_a_mutex);

        pthread_mutex_lock(&encoder_b_mutex);
        current_encoder_b_count = encoder_b_count;
        encoder_b_count = 0; // Reset encoder count for next iteration
        pthread_mutex_unlock(&encoder_b_mutex);

        // Calculate RPM
        double current_rpm_a = calculate_rpm(current_encoder_a_count);
        double current_rpm_b = calculate_rpm(current_encoder_b_count);

        // Calculate error
        double error_a = calculate_error(TARGET_RPM, current_rpm_a);
        double error_b = calculate_error(TARGET_RPM, current_rpm_b);

        // Calculate proportional and integral terms
        double proportional_a = calculate_proportional(error_a);
        double proportional_b = calculate_proportional(error_b);

        integral_a = calculate_integral(error_a, integral_a);
        integral_b = calculate_integral(error_b, integral_b);

        // Calculate PWM duty cycle
        int pwm_duty_cycle_a = calculate_pwm(proportional_a, integral_a);
        int pwm_duty_cycle_b = calculate_pwm(proportional_b, integral_b);

        // Set motor speed
        set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, pwm_duty_cycle_a);

        // Print RPM and PWM duty cycle
        printf("Motor A RPM: %.2f, PWM: %d\n", current_rpm_a, pwm_duty_cycle_a);
        printf("Motor B RPM: %.2f, PWM: %d\n", current_rpm_b, pwm_duty_cycle_b);

        // Check for encoder stall
        check_encoder_stall(current_encoder_a_count, current_encoder_b_count);

        // Sleep for 100 ms
        gpioDelay(100000); // 100 ms
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_motor_speed(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, 0); // Stop motors
    gpioTerminate(); // Terminate pigpio

    return 0;
}

