#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to store the current relay state
int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int debounce_touch();
int toggle_relay();
void log_relay_state();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        cleanup_gpio();
        exit(0);
    }
}

// Initializes the pigpio library and configures the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO 4 as input
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }

    // Set GPIO 17 as output
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Reads the state of the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Implements software debouncing
int debounce_touch() {
    int i;
    for (i = 0; i < DEBOUNCE_DELAY; ++i) {
        if (read_touch_sensor() == 0) {
            return 0; // Touch released during debounce
        }
        gpioDelay(1); // Delay for 1 ms
    }
    return 1; // Touch still held after debounce
}

// Toggles the relay state
int toggle_relay() {
    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", RELAY_PIN);
        return 1; // Indicate failure
    }
    return 0; // Indicate success
}

// Logs the relay state change with an ISO-8601 timestamp
void log_relay_state() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    printf("%s Relay is now %s\n", timestamp, relay_state ? "ON" : "OFF");
}

// Cleans up the pigpio library and releases GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        if (read_touch_sensor() == 1) {
            if (debounce_touch()) {
                if (toggle_relay() == 0) {
                    log_relay_state();
                }
            }
        }
        gpioDelay(10); // Sleep for 10 ms to reduce CPU usage
    }

    return 0;
}

