#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define FLOW_SENSOR_GPIO 17
#define SOLENOID_GPIO 27
#define PULSES_PER_LITER 450.0
#define LPM_THRESHOLD_HIGH 5.0
#define LPM_THRESHOLD_LOW 4.5
#define DEBOUNCE_TIMEOUT 1000 // milliseconds

// Global variables
volatile int pulse_count = 0;
pthread_mutex_t pulse_mutex;
FILE *log_file = NULL;

// Function prototypes
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void control_solenoid(double lpm);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);

// Function to handle the interrupt service routine (ISR)
void flow_sensor_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == PI_HIGH) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM from pulse count
double calculate_lpm(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to control the solenoid valve
void control_solenoid(double lpm) {
    int solenoid_state = PI_HIGH; // Initially open

    if (lpm > LPM_THRESHOLD_HIGH) {
        solenoid_state = PI_LOW; // Close the valve
    } else if (lpm < LPM_THRESHOLD_LOW) {
        solenoid_state = PI_HIGH; // Open the valve
    }

    gpioWrite(SOLENOID_GPIO, solenoid_state);
}

// Function to log data to a file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n",
            timestamp, lpm, solenoid_state == PI_HIGH ? "OPEN" : "CLOSED");
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Log the event
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, SIGNAL RECEIVED: %d\n", timestamp, signal);
    fflush(log_file);

    // Reopen the solenoid valve
    gpioWrite(SOLENOID_GPIO, PI_HIGH);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Destroy the mutex
    pthread_mutex_destroy(&pulse_mutex);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(SOLENOID_GPIO, PI_OUTPUT);

    // Initialize solenoid to open state
    gpioWrite(SOLENOID_GPIO, PI_HIGH);

    // Initialize mutex
    if (pthread_mutex_init(&pulse_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("water_flow.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine (ISR) with debouncing
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Sample pulse count
        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

        // Calculate LPM
        double lpm = calculate_lpm(current_pulse_count);

        // Control solenoid
        control_solenoid(lpm);

        // Log data
        log_data(lpm, gpioRead(SOLENOID_GPIO));

        // Wait for 1 second
        gpioDelay(1000); // Delay in milliseconds
    }

    return 0;
}

