    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt service routine (ISR) with debouncing
    if (gpioSetISRFuncEx(FLOW_SENSOR_GPIO, RISING_EDGE, DEBOUNCE_TIMEOUT, flow_sensor_isr, NULL) != 0) {
        fprintf(stderr, "Error setting up ISR!\n");
        fclose(log_file);
        pthread_mutex_destroy(&pulse_mutex);
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (1) {
        // Sample pulse count
        int current_pulse_count;
        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count
        pthread_mutex_unlock(&pulse_mutex);

