#include <arpa/inet.h>
#include <pigpio.h>

// Configuration file path
#define CONFIG_FILE "config.ini"

// Default values
#define DEFAULT_CALIBRATION_FACTOR 1.0
#define DEFAULT_SERVER_IP "127.0.0.1"
#define DEFAULT_SERVER_PORT 12345

// GPIO pins
#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18

// Servo pulse width limits (microseconds)
#define SERVO_MIN_PULSE_WIDTH 1000
#define SERVO_MAX_PULSE_WIDTH 2000

// HX711 timeout (microseconds)
#define HX711_TIMEOUT 1000

// Global variables
static volatile int running = 1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static char server_ip[20] = DEFAULT_SERVER_IP;
static int server_port = DEFAULT_SERVER_PORT;
static int socket_fd = -1;

// Function prototypes
int read_config();
int hx711_read();
double hx711_calibrate(double weight);
int servo_set_pulse_width(int pulse_width);
int dispense(double target_weight);
int send_weight_to_server(double actual_weight);
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message);
void signal_handler(int signal);

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open config file %s. Using default values.\n", CONFIG_FILE);
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "server_ip") == 0) {
                strncpy(server_ip, value, sizeof(server_ip) - 1);
                server_ip[sizeof(server_ip) - 1] = 0; // Ensure null termination
            } else if (strcmp(key, "server_port") == 0) {
                server_port = atoi(value);
            }
        }
    }

    fclose(fp);
    printf("Configuration loaded: calibration_factor=%.2f, server_ip=%s, server_port=%d\n", calibration_factor, server_ip, server_port);
    return 0;
}

// Function to read data from HX711
int hx711_read() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);

    // Wait for DATA pin to go low
    int timeout_count = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout_count < HX711_TIMEOUT) {
        gpioDelay(1); // Wait 1 microsecond
        timeout_count++;
    }

    if (timeout_count >= HX711_TIMEOUT) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Clock pulse width
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Clock pulse width
    }

    // Apply the 25th clock pulse for gain selection (default gain = 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calibrate the HX711 reading
double hx711_calibrate(double weight) {
    int raw_value = hx711_read();
    if (raw_value == -1) {
        return -1.0; // Propagate error
    }
    return (double)raw_value / calibration_factor;
}

// Function to set the servo pulse width
int servo_set_pulse_width(int pulse_width) {
    if (pulse_width < SERVO_MIN_PULSE_WIDTH || pulse_width > SERVO_MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Invalid servo pulse width: %d. Must be between %d and %d.\n", pulse_width, SERVO_MIN_PULSE_WIDTH, SERVO_MAX_PULSE_WIDTH);
        return -1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(SERVO_PIN, 50); // Set PWM frequency to 50 Hz
    gpioSetPWMrange(SERVO_PIN, 1000000); // Set PWM range to 1000000 (microseconds)
    gpioPWM(SERVO_PIN, pulse_width); // Set PWM duty cycle

    return 0;
}

// Function to dispense the ingredient
int dispense(double target_weight) {
    int pulse_width;
    double actual_weight;
    char error_message[256] = {0};

    // Calculate servo pulse width based on target weight
    pulse_width = (int)((target_weight / 1000.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH) + SERVO_MIN_PULSE_WIDTH);

    // Set servo pulse width
    if (servo_set_pulse_width(pulse_width) != 0) {
        strcpy(error_message, "Servo control failed.");
        goto error;
    }

    // Wait for 1 second for load cell to stabilize
    gpioDelay(1000); // 1000 milliseconds = 1 second

    // Read actual weight from HX711
    actual_weight = hx711_calibrate(target_weight);
    if (actual_weight == -1.0) {
        strcpy(error_message, "HX711 read failed.");
        goto error;
    }

    // Send weight to server
    if (send_weight_to_server(actual_weight) != 0) {
        strcpy(error_message, "Failed to send weight to server.");
        goto error;
    }

    // Log dispensing event
    if (log_dispensing_event(target_weight, actual_weight, error_message) != 0) {
        fprintf(stderr, "Error: Failed to log dispensing event.\n");
    }

    return 0;

error:
    log_dispensing_event(target_weight, 0.0, error_message);
    return -1;
}

// Function to send weight to server
int send_weight_to_server(double actual_weight) {
    char buffer[256];
    snprintf(buffer, sizeof(buffer), "%.2f\n", actual_weight);

    if (send(socket_fd, buffer, strlen(buffer), 0) < 0) {
        perror("Error: Send failed");
        return -1;
    }

    return 0;
}

// Function to log dispensing event
int log_dispensing_event(double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open dispensing_log.json for writing.\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "{\"timestamp\": \"%s\", \"target_weight\": %.2f, \"actual_weight\": %.2f, \"error\": \"%s\"}\n",
            timestamp, target_weight, actual_weight, error_message);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Close socket
    if (socket_fd != -1) {
        close(socket_fd);
    }

    // Stop servo
    gpioWrite(SERVO_PIN, 0);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Read configuration
    if (read_config() != 0) {
        fprintf(stderr, "Warning: Using default configuration values.\n");
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    socket_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (socket_fd == -1) {
        perror("Error: Could not create socket");
        gpioTerminate();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(server_port);

    if (bind(socket_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Error: Bind failed");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    // Listen for connections
    if (listen(socket_fd, 3) < 0) {
        perror("Error: Listen failed");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    printf("Listening on %s:%d...\n", server_ip, server_port);

    // Accept connection
    int client_socket;
    struct sockaddr_in client_address;
    int client_address_len = sizeof(client_address);

    client_socket = accept(socket_fd, (struct sockaddr *)&client_address, (socklen_t *)&client_address_len);
    if (client_socket < 0) {
        perror("Error: Accept failed");
        close(socket_fd);
        gpioTerminate();
        return 1;
    }

    printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

    // Main loop
    while (running) {
        char buffer[256];
        double target_weight;

        // Receive target weight from client
        ssize_t bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (bytes_received < 0) {
            perror("Error: Receive failed");
            break;
        } else if (bytes_received == 0) {
            printf("Client disconnected.\n");
            break;
        }

        buffer[bytes_received] = '\0';
        target_weight = atof(buffer);

        printf("Received target weight: %.2f grams\n", target_weight);

        // Dispense the ingredient
        if (dispense(target_weight) != 0) {
            fprintf(stderr, "Error: Dispensing failed.\n");
        }
    }

    // Clean up
    close(client_socket);
    close(socket_fd);
    gpioTerminate();

    return 0;
}

