#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Default debounce time in milliseconds
#define DEFAULT_DEBOUNCE_TIME 50

// Global variable to store the relay state
static volatile int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void toggle_relay();
void log_relay_state(int state);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold program configuration
typedef struct {
    int debounce_time_ms;
} ProgramConfig;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set TOUCH_SENSOR_PIN to input\n");
        cleanup_gpio();
        return 1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set RELAY_PIN to output\n");
        cleanup_gpio();
        return 1;
    }

    return 0; // Indicate success
}

// Function to read the touch sensor with debouncing
int read_touch_sensor() {
    int stable_state = gpioRead(TOUCH_SENSOR_PIN);
    int start_time = gpioTick();

    while (gpioTick() - start_time < DEFAULT_DEBOUNCE_TIME * 1000) {
        if (gpioRead(TOUCH_SENSOR_PIN) != stable_state) {
            return 0; // Not stable
        }
        gpioDelay(1); // Small delay to avoid busy-waiting
    }

    return stable_state;
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_PIN, relay_state);
    log_relay_state(relay_state);
}

