#include <stdio.h>
#include <stdlib.h>
#include <termios.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define SERVO_GPIO 18
#define PWM_FREQUENCY 50
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define MIN_ANGLE 0
#define MAX_ANGLE 180
#define DEFAULT_ANGLE 90

volatile sig_atomic_t program_running = 1;

// Structure to hold terminal settings
struct termios orig_termios;

// Function to handle Ctrl+C signal
void signal_handler(int signum) {
    if (signum == SIGINT) {
        printf("\nCtrl+C pressed. Exiting gracefully.\n");
        program_running = 0;
    }
}

// Function to set the servo angle
int set_servo_angle(int angle) {
    if (angle < MIN_ANGLE) {
        angle = MIN_ANGLE;
    } else if (angle > MAX_ANGLE) {
        angle = MAX_ANGLE;
    }

    // Calculate pulse width based on angle
    int pulse_width = MIN_PULSE_WIDTH + (int)(((float)(angle) / MAX_ANGLE) * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH));

    // Set the servo pulse width
    gpioServo(SERVO_GPIO, pulse_width);

    return angle;
}

// Function to restore terminal settings
void restore_terminal_settings() {
    tcsetattr(0, TCSANOW, &orig_termios);
}

int main() {
    int angle = DEFAULT_ANGLE;
    char input;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 to output mode
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);

    // Set initial servo angle
    set_servo_angle(angle);

    // Save terminal settings
    tcgetattr(0, &orig_termios);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set raw terminal mode
    struct termios raw = orig_termios;
    raw.c_lflag &= ~(ICANON | ECHO);
    tcsetattr(0, TCSANOW, &raw);

    printf("Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");

    while (program_running) {
        // Read input from the keyboard
        if (read(0, &input, 1) > 0) {
            switch (input) {
                case '+':
                    angle = set_servo_angle(angle + 10);
                    printf("Angle: %d\n", angle);
                    break;
                case '-':
                    angle = set_servo_angle(angle - 10);
                    printf("Angle: %d\n", angle);
                    break;
                case 'q':
                    printf("Quitting.\n");
                    program_running = 0;
                    break;
                default:
                    // Do nothing
                    break;
            }
        }
        gpioDelay(1000); // Delay for 1 ms
    }

    // Stop PWM signal
    gpioServo(SERVO_GPIO, 0);

    // Restore terminal settings
    restore_terminal_settings();

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

