#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <gpiod.h>

#define GPIO_PIN 17
#define DEBOUNCE_MS 2
#define LOG_FILE "motor_rpm.log"

// Global variables for signal handling
static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;
static FILE *log_file = NULL;

// Structure to hold program state
typedef struct {
    int pulse_count;
    struct timespec last_pulse_time;
} ProgramState;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line);
int initialize_logging(FILE **log_file);
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line, FILE *log_file);
void signal_handler(int sig);
int read_sensor(struct gpiod_line *line);
double calculate_rpm(int pulse_count);
int log_rpm(FILE *log_file, double rpm);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received: %d. Terminating program.\n", sig);
    terminate = 1;
}

// Initialize GPIO using libgpiod
int initialize_gpio(struct gpiod_chip **chip, struct gpiod_line **line) {
    *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!*chip) {
        fprintf(stderr, "Error opening GPIO chip.\n");
        return -1;
    }

    *line = gpiod_chip_get_line(*chip, GPIO_PIN);
    if (!*line) {
        fprintf(stderr, "Error getting GPIO line.\n");
        gpiod_chip_close(*chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "conveyor_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP;

    int ret = gpiod_line_request(*line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line: %d\n", ret);
        gpiod_chip_close(*chip);
        return -1;
    }

    return 0;
}

// Initialize logging
int initialize_logging(FILE **log_file) {
    *log_file = fopen(LOG_FILE, "a");
    if (!*log_file) {
        fprintf(stderr, "Error opening log file.\n");
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup(struct gpiod_chip *chip, struct gpiod_line *line, FILE *log_file) {
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
    }
}

// Read sensor value with debouncing
int read_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor value.\n");
        return -1;
    }
    return value;
}

// Calculate RPM
double calculate_rpm(int pulse_count) {
    return (double)pulse_count * 60.0 / 5.0;
}

// Log RPM to file
int log_rpm(FILE *log_file, double rpm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    if (fprintf(log_file, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main() {
    ProgramState state = {0, {0, 0}};
    struct timespec current_time;
    int last_pulse_value = 0;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &line) != 0) {
        return 1;
    }

    // Initialize logging
    if (initialize_logging(&log_file) != 0) {
        cleanup(chip, line, NULL);
        return 1;
    }

    // Main loop
    while (!terminate) {
        int sensor_value = read_sensor(line);
        if (sensor_value < 0) {
            break; // Exit loop on sensor read error
        }

        clock_gettime(CLOCK_MONOTONIC, &current_time);

        if (sensor_value == 1 && last_pulse_value == 0) {
            // Rising edge detected
            double time_diff = (current_time.tv_sec - state.last_pulse_time.tv_sec) +
                               (current_time.tv_nsec - state.last_pulse_time.tv_nsec) / 1e9;

            if (time_diff * 1000.0 > DEBOUNCE_MS) {
                state.pulse_count++;
                state.last_pulse_time = current_time;
            }
        }

        last_pulse_value = sensor_value;

        // Calculate and log RPM every 5 seconds
        if (current_time.tv_sec % 5 == 0) {
            double rpm = calculate_rpm(state.pulse_count);
            printf("RPM: %.2f\n", rpm);
            if (log_rpm(log_file, rpm) != 0) {
                break; // Exit loop on log write error
            }
            state.pulse_count = 0; // Reset pulse count for the next 5-second interval
        }

        usleep(1000); // Check every 1 ms
    }

    // Cleanup and exit
    cleanup(chip, line, log_file);
    return 0;
}

