#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Define constants
#define FAILSAFE_TIMEOUT 10 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
void control_relay(int state);
void failsafe_shutdown();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    return 0; // Indicate success
}

// Read the touch sensor
int read_touch_sensor() {
    int touch_state = gpioRead(TOUCH_SENSOR_PIN);
    if (touch_state < 0) {
        fprintf(stderr, "Failed to read GPIO%d\n", TOUCH_SENSOR_PIN);
        return -1; // Indicate error
    }
    return touch_state;
}

// Control the relay
void control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to GPIO%d\n", RELAY_PIN);
    }
}

// Failsafe shutdown procedure
void failsafe_shutdown() {
    printf("Failsafe triggered! Shutting down relay.\n");
    control_relay(0); // Turn off the relay
    gpioTerminate();   // Terminate pigpio
    exit(1);           // Exit the program
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    int relay_state = 0; // Initial relay state: OFF
    control_relay(relay_state);

    time_t last_touch_time = 0;
    int failsafe_active = 0;

    printf("Relay control program started. Press Ctrl+C to exit.\n");

