#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <unistd.h>

// Define GPIO pins
#define VALVE_PWM_PIN 18
#define VALVE_ENABLE_PIN 23
#define FLOW_SENSOR_PIN 24

// Define constants
#define PWM_FREQUENCY 1000  // Hz
#define PWM_RANGE 255
#define YF_S201_PULSES_PER_LITER 450.0
#define KP 1.0
#define LOG_FILE "flow_log.csv"

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
void enable_valve();
void disable_valve();
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
float calculate_flow_rate(int pulse_count);
int set_valve_position(float flow_rate, float target_flow_rate);
int log_data(float flow_rate, int valve_position);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PWM pin as output
    gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE);

    // Set enable pin as output
    gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT);
    enable_valve(); // Enable the valve at startup

    // Set flow sensor pin as input
    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Register interrupt handler for flow sensor
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_counter_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        return 1;
    }

    return 0;
}

// Function to enable the valve
void enable_valve() {
    gpioWrite(VALVE_ENABLE_PIN, 1); // Set HIGH to enable
}

// Function to disable the valve
void disable_valve() {
    gpioWrite(VALVE_ENABLE_PIN, 0); // Set LOW to disable
}

// Interrupt service routine for flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    pulse_count++;
}

// Function to calculate flow rate in L/min
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / YF_S201_PULSES_PER_LITER * 60.0; // Convert pulses/second to L/min
}

// Function to set valve position using proportional control
int set_valve_position(float flow_rate, float target_flow_rate) {
    float error = target_flow_rate - flow_rate;
    float duty_cycle = KP * error;

    // Clamp duty cycle to [0, 255]
    if (duty_cycle < 0) {
        duty_cycle = 0;
    } else if (duty_cycle > 255) {
        duty_cycle = 255;
    }

    gpioPWM(VALVE_PWM_PIN, (int)duty_cycle);
    return (int)duty_cycle;
}

// Function to log data to CSV file
int log_data(float flow_rate, int valve_position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return 1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, shutting down...\n", signal);
    running = 0;
}

int main(int argc, char *argv[]) {
    float target_flow_rate;

    // Parse command-line arguments
    if (argc != 2) {
        fprintf(stderr, "Usage: %s -t <target_flow_rate_L/min>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "-t") != 0) {
        fprintf(stderr, "Invalid argument. Use -t to specify the target flow rate.\n");
        return 1;
    }

    if (argc != 3) {
        fprintf(stderr, "Missing target flow rate value.\n");
        return 1;
    }

    char *endptr;
    target_flow_rate = strtof(argv[2], &endptr);

    if (*endptr != '\0' || target_flow_rate <= 0) {
        fprintf(stderr, "Invalid target flow rate value. Must be a positive number.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flow control system started. Target flow rate: %.2f L/min\n", target_flow_rate);

    // Main loop
    while (running) {
        // Reset pulse count
        pulse_count = 0;

        // Wait for 100 ms
        gpioDelay(100000); // 100 ms = 100000 microseconds

        // Calculate flow rate
        float flow_rate = calculate_flow_rate(pulse_count);

        // Set valve position
        int valve_position = set_valve_position(flow_rate, target_flow_rate);

        // Log data
        if (log_data(flow_rate, valve_position) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        printf("Flow Rate: %.2f L/min, Valve Position: %d\n", flow_rate, valve_position);
    }

    // Shutdown sequence
    printf("Shutting down valve and cleaning up...\n");
    disable_valve(); // Disable the valve
    gpioPWM(VALVE_PWM_PIN, 0); // Set PWM to 0
    fclose(log_file);
    gpioTerminate();

    printf("Flow control system stopped.\n");
    return 0;
}

