#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK1_PIN 17
#define LOCK2_PIN 27
#define BUTTON_PIN 22

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 100000 // 100 kHz

// Define valid RFID tag
const unsigned char valid_tag[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rfid();
int validate_tag(const unsigned char *tag);
int read_button();
void log_event(const char *event);
void lock_engage();
void lock_disengage();
void signal_handler(int signal);

// Function to read RFID tag from SPI
int read_rfid() {
    unsigned char rx_buffer[10];
    int result;

    result = spiXfer(spi_handle, NULL, rx_buffer, 10);

    if (result != 10) {
        log_event("RFID read failed");
        return -1; // Indicate failure
    }

    // Check for all-zero response (no tag present)
    for (int i = 0; i < 10; i++) {
        if (rx_buffer[i] != 0x00) {
            return 0; // Tag present
        }
    }

    return -1; // No tag present
}

// Function to validate the RFID tag
int validate_tag(const unsigned char *tag) {
    return (memcmp(tag, valid_tag, 10) == 0) ? 1 : 0;
}

// Function to read the button state
int read_button() {
    return (gpioRead(BUTTON_PIN) == 0) ? 1 : 0; // Active-low button
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Function to engage the locks
void lock_engage() {
    gpioWrite(LOCK1_PIN, 1);
    gpioWrite(LOCK2_PIN, 1);
    log_event("Locks engaged");
}

// Function to disengage the locks
void lock_disengage() {
    gpioWrite(LOCK1_PIN, 0);
    gpioWrite(LOCK2_PIN, 0);
    log_event("Locks disengaged");
    gpioDelay(5000); // 5 seconds
    lock_engage();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Program terminated by signal");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LOCK1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK2_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int rfid_result = read_rfid();
        int button_pressed = read_button();

        if (rfid_result == 0 && button_pressed) {
            log_event("Two-factor authentication successful");
            lock_disengage();
        } else if (rfid_result == -1) {
            log_event("Invalid RFID tag");
        } else if (button_pressed) {
            log_event("Button pressed without valid RFID tag");
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LOCK1_PIN, 1); // Ensure locks are engaged on exit
    gpioWrite(LOCK2_PIN, 1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

