        fprintf(stderr, "SPI open failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        int rfid_result = read_rfid();
        int button_pressed = read_button();

        if (rfid_result == 0 && button_pressed) {
            log_event("Two-factor authentication successful");
            lock_disengage();
        } else if (rfid_result == -1) {
            log_event("Invalid RFID tag");
        } else if (button_pressed) {
            log_event("Button pressed without valid RFID tag");
        }

        gpioDelay(100); // Small delay to prevent busy-waiting
    }

    // Cleanup
    spiClose(spi_handle);
    gpioWrite(LOCK1_PIN, 1); // Ensure locks are engaged on exit
    gpioWrite(LOCK2_PIN, 1);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

