#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <pthread.h>
#include <signal.h>
#include <time.h>
#include <string.h>
#include <unistd.h>

// Motor 1 GPIOs
#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25

// Motor 2 GPIOs
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

// Encoder 1 GPIOs
#define ENCODER1_A 5
#define ENCODER1_B 6

// Encoder 2 GPIOs
#define ENCODER2_A 26
#define ENCODER2_B 19

// PID Constants
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Sample Time (ms)
#define SAMPLE_TIME 100

// Target RPM
#define TARGET_RPM 60.0

// PWM Frequency (Hz)
#define PWM_FREQUENCY 100

// PWM Range
#define PWM_RANGE 1000

// Global Variables
volatile int encoder1_count = 0;
volatile int encoder2_count = 0;
pthread_mutex_t encoder1_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t encoder2_mutex = PTHREAD_MUTEX_INITIALIZER;
FILE *log_file = NULL;

// Function Prototypes
void motor_forward(int motor_num, int speed);
void motor_backward(int motor_num, int speed);
void motor_stop(int motor_num);
void encoder1_isr(int gpio, int level, uint32_t tick, void *user);
void encoder2_isr(int gpio, int level, uint32_t tick, void *user);
double calculate_pid(double setpoint, double actual_value, double *integral, double *previous_error);
void log_data(double motor1_rpm, double motor2_rpm, double pid1_output, double pid2_output, double pid1_p, double pid1_i, double pid1_d, double pid2_p, double pid2_i, double pid2_d);
void signal_handler(int signal);

// Motor Control Functions
void motor_forward(int motor_num, int speed) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_IN1, 1);
        gpioWrite(MOTOR1_IN2, 0);
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_IN3, 1);
        gpioWrite(MOTOR2_IN4, 0);
        gpioPWM(MOTOR2_ENB, speed);
    }
}

void motor_backward(int motor_num, int speed) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 1);
        gpioPWM(MOTOR1_ENA, speed);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 1);
        gpioPWM(MOTOR2_ENB, speed);
    }
}

void motor_stop(int motor_num) {
    if (motor_num == 1) {
        gpioWrite(MOTOR1_IN1, 0);
        gpioWrite(MOTOR1_IN2, 0);
        gpioPWM(MOTOR1_ENA, 0);
    } else if (motor_num == 2) {
        gpioWrite(MOTOR2_IN3, 0);
        gpioWrite(MOTOR2_IN4, 0);
        gpioPWM(MOTOR2_ENB, 0);
    }
}

// Encoder Interrupt Service Routines
void encoder1_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // unused parameters
    pthread_mutex_lock(&encoder1_mutex);
    if (gpioRead(ENCODER1_A) == gpioRead(ENCODER1_B)) {
        encoder1_count++;
    } else {
        encoder1_count--;
    }
    pthread_mutex_unlock(&encoder1_mutex);
}

void encoder2_isr(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)tick; (void)user; // unused parameters
    pthread_mutex_lock(&encoder2_mutex);
    if (gpioRead(ENCODER2_A) == gpioRead(ENCODER2_B)) {
        encoder2_count++;
    } else {
        encoder2_count--;
    }
    pthread_mutex_unlock(&encoder2_mutex);
}

// PID Controller Function
double calculate_pid(double setpoint, double actual_value, double *integral, double *previous_error) {
    double error = setpoint - actual_value;
    *integral += error * (SAMPLE_TIME / 1000.0);
    double derivative = (error - *previous_error) / (SAMPLE_TIME / 1000.0);
    double output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

// Logging Function
void log_data(double motor1_rpm, double motor2_rpm, double pid1_output, double pid2_output, double pid1_p, double pid1_i, double pid1_d, double pid2_p, double pid2_i, double pid2_d) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, motor1_rpm, motor2_rpm, pid1_output, pid2_output, pid1_p, pid1_i, pid1_d, pid2_p, pid2_i, pid2_d);
    fflush(log_file);
}

// Signal Handler
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    motor_stop(1);
    motor_stop(2);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENA, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN1, PI_OUTPUT);
    gpioSetMode(MOTOR1_IN2, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENB, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN3, PI_OUTPUT);
    gpioSetMode(MOTOR2_IN4, PI_OUTPUT);
    gpioSetMode(ENCODER1_A, PI_INPUT);
    gpioSetMode(ENCODER1_B, PI_INPUT);
    gpioSetMode(ENCODER2_A, PI_INPUT);
    gpioSetMode(ENCODER2_B, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(MOTOR1_ENA, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENB, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENA, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENB, PWM_RANGE);

    // Set up interrupts for encoders
    gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_isr, NULL);
    gpioSetISRFuncEx(ENCODER2_A, RISING_EDGE, 0, encoder2_isr, NULL);

    // Open log file
    log_file = fopen("motor_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Write header to log file
    fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID1_Output,PID2_Output,PID1_P,PID1_I,PID1_D,PID2_P,PID2_I,PID2_D\n");

    // Signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // PID variables
    double pid1_integral = 0.0;
    double pid1_previous_error = 0.0;
    double pid2_integral = 0.0;
    double pid2_previous_error = 0.0;

    // Main control loop
    while (1) {
        // Read encoder counts
        int encoder1_count_local, encoder2_count_local;
        pthread_mutex_lock(&encoder1_mutex);
        encoder1_count_local = encoder1_count;
        pthread_mutex_unlock(&encoder1_mutex);
        pthread_mutex_lock(&encoder2_mutex);
        encoder2_count_local = encoder2_count;
        pthread_mutex_unlock(&encoder2_mutex);

        // Calculate RPM
        double motor1_rpm = (double)encoder1_count_local / 600.0 * (PWM_FREQUENCY / 1000.0);
        double motor2_rpm = (double)encoder2_count_local / 600.0 * (PWM_FREQUENCY / 1000.0);

        // Calculate PID outputs
        double pid1_output = calculate_pid(TARGET_RPM, motor1_rpm, &pid1_integral, &pid1_previous_error);
        double pid2_output = calculate_pid(TARGET_RPM, motor2_rpm, &pid2_integral, &pid2_previous_error);

        // Control motors
        int motor1_speed = (int)pid1_output;
        int motor2_speed = (int)pid2_output;

        if (motor1_speed > PWM_RANGE) motor1_speed = PWM_RANGE;
        if (motor1_speed < 0) motor1_speed = 0;
        if (motor2_speed > PWM_RANGE) motor2_speed = PWM_RANGE;
        if (motor2_speed < 0) motor2_speed = 0;

        motor_forward(1, motor1_speed);
        motor_forward(2, motor2_speed);

        // Log data
        log_data(motor1_rpm, motor2_rpm, pid1_output, pid2_output, KP, KI, KD, KP, KI, KD);

        // Wait for the next sample time
        gpioDelay(SAMPLE_TIME * 1000); // pigpioDelay takes microseconds
    }

    return 0;
}

