#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define POLL_INTERVAL_MS 50

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_mpr121();
int read_touch_status(uint16_t *touch_status);
void control_relay(int state);
void log_relay_state(int state);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the MPR121 sensor
int initialize_mpr121() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Set Electrode Configuration to enable all 12 electrodes
        fprintf(stderr, "Error: Electrode config failed\n");
        return -1;
    }

    // Configure baseline filtering (example values)
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x05) < 0) { // MHD_R
        fprintf(stderr, "Error: MHD_R config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x05) < 0) { // NHD_R
        fprintf(stderr, "Error: NHD_R config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x01) < 0) { // NCL_R
        fprintf(stderr, "Error: NCL_R config failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x0E) < 0) { // FDL_R
        fprintf(stderr, "Error: FDL_R config failed\n");
        return -1;
    }

    // Set touch and release thresholds (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + 2 * i, 0x30) < 0) { // Touch threshold
            fprintf(stderr, "Error: Touch threshold config failed for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + 2 * i, 0x10) < 0) { // Release threshold
            fprintf(stderr, "Error: Release threshold config failed for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes and enter run mode
    if (i2cWriteByteData(i2c_handle, 0x5B, 0x01) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Electrode enable failed\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x5D, 0x04) < 0) { // Enter run mode
        fprintf(stderr, "Error: Run mode failed\n");
        return -1;
    }

    return 0;
}

// Reads the touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Controls the relay (activates or deactivates it)
void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

// Logs the relay state to a file with a timestamp
void log_relay_state(int state) {
    FILE *fp = fopen("relay_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open relay_log.txt for writing\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s: Relay is %s\n", s, state ? "ON" : "OFF");
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (initialize_mpr121() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    uint16_t touch_status;
