#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins for the valves
#define VALVE1_GPIO 17
#define VALVE2_GPIO 18

// Define GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the log file name
#define LOG_FILE "valve_log.txt"

// Structure to hold GPIO line pointers
struct gpio_lines {
    struct gpiod_line *valve1_line;
    struct gpiod_line *valve2_line;
};

// Global variable to hold the GPIO chip
struct gpiod_chip *chip = NULL;

// Global variable to hold the GPIO lines
struct gpio_lines lines;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio(struct gpiod_chip **chip, struct gpio_lines *lines);
int set_valve_state(struct gpiod_line *line, int state);
int log_event(const char *message);
void cleanup_gpio(struct gpiod_chip *chip, struct gpio_lines *lines);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Received signal %d, shutting down...\n", sig);
        program_running = 0;
    }
}

// Function to initialize GPIO lines
int initialize_gpio(struct gpiod_chip **chip, struct gpio_lines *lines) {
    *chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!*chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    lines->valve1_line = gpiod_chip_get_line(*chip, VALVE1_GPIO);
    if (!lines->valve1_line) {
        perror("Error getting GPIO line for Valve 1");
        gpiod_chip_close(*chip);
        return -1;
    }

    lines->valve2_line = gpiod_chip_get_line(*chip, VALVE2_GPIO);
    if (!lines->valve2_line) {
        perror("Error getting GPIO line for Valve 2");
        gpiod_chip_close(*chip);
        gpiod_line_release(lines->valve1_line);
        return -1;
    }

    if (gpiod_line_request_output(lines->valve1_line, "valve1", 0) < 0) {
        perror("Error requesting GPIO line for Valve 1 as output");
        gpiod_chip_close(*chip);
        gpiod_line_release(lines->valve1_line);
        gpiod_line_release(lines->valve2_line);
        return -1;
    }

    if (gpiod_line_request_output(lines->valve2_line, "valve2", 0) < 0) {
        perror("Error requesting GPIO line for Valve 2 as output");
        gpiod_chip_close(*chip);
        gpiod_line_release(lines->valve1_line);
        gpiod_line_release(lines->valve2_line);
        return -1;
    }

    return 0;
}

// Function to set the state of a valve (ON or OFF)
int set_valve_state(struct gpiod_line *line, int state) {
    if (gpiod_line_set_value(line, state) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Function to log an event to the log file
int log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", &tm);

    fprintf(fp, "%s: %s\n", timestamp, message);
    fclose(fp);
    return 0;
}

// Function to cleanup GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpio_lines *lines) {
    if (lines->valve1_line) {
        gpiod_line_release(lines->valve1_line);
    }
    if (lines->valve2_line) {
        gpiod_line_release(lines->valve2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio(&chip, &lines) < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    printf("Valve control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Valve 1 ON
        if (set_valve_state(lines.valve1_line, 1) < 0) {
            fprintf(stderr, "Failed to activate Valve 1. Continuing.\n");
        } else {
            log_event("Valve 1 activated");
        }
        gpiod_line_set_value(lines.valve1_line, 1);
