#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17
#define I2C_BUS 1

// MPR121 Register Addresses
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_FILTERTH 0x24
#define MPR121_BASELINE 0x1E
#define MPR121_MHDR 0x2B
#define MPR121_NHDR 0x2C
#define MPR121_NCLR 0x2D
#define MPR121_FDLR 0x2E
#define MPR121_MHDF 0x2F
#define MPR121_NHDF 0x30
#define MPR121_NCLF 0x31
#define MPR121_FDLF 0x32
#define MPR121_ELE_EN 0x5E

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status();
void relay_toggle();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to set MPR121 to stop mode.\n");
        return -1;
    }
    gpioDelay(100); // Wait for 100ms

    // Configure touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x10) < 0) {
            fprintf(stderr, "Error: Failed to set touch threshold for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Failed to set release threshold for electrode %d.\n", i);
            return -1;
        }
    }

    // Configure filter and charge time
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH, 0x20) < 0) {
        fprintf(stderr, "Error: Failed to set filter threshold.\n");
        return -1;
    }

    // Configure electrode current
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set baseline current.\n");
        return -1;
    }

    // Configure debounce settings
    if (i2cWriteByteData(i2c_handle, MPR121_MHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDR, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLR, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLR.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLR, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to set FDLR.\n");
        return -1;
    }

    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set MHDF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set NHDF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to set NCLF.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to set FDLF.\n");
        return -1;
    }

    // Enable electrodes
    if (i2cWriteByteData(i2c_handle, MPR121_ELE_EN, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to enable electrodes.\n");
        return -1;
    }

    gpioDelay(100); // Wait for 100ms

    return 0;
}

// Read the touch status from the MPR121
int mpr121_read_touch_status() {
    int touch_status_low = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_L);
    int touch_status_high = i2cReadByteData(i2c_handle, MPR121_TOUCHSTATUS_H);

    if (touch_status_low < 0 || touch_status_high < 0) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }

    return (touch_status_high << 8) | touch_status_low;
}

// Toggle the relay state
void relay_toggle() {
    int current_state = gpioRead(RELAY_GPIO);
    gpioWrite(RELAY_GPIO, !current_state);
    printf("Relay toggled to state: %d\n", !current_state);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initialize relay to OFF state

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus. %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status > 0) {
            relay_toggle();
        }
        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay on exit
    gpioTerminate();

    return 0;
}

