#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define RELAY_PIN 18

// Define rate limiting interval (in milliseconds)
#define RATE_LIMIT_INTERVAL 2000

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static unsigned long last_unlock_time = 0;

// Function prototypes
int initialize_gpio();
void motion_detected_callback(int gpio, int level, uint32_t tick);
void unlock_door();
void log_event(const char *event_type, int gpio);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio;
    int last_state;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR sensor pins as inputs with pull-down resistors
    gpioSetMode(PIR_SENSOR_1, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_1, PI_PUD_DOWN);
    gpioSetMode(PIR_SENSOR_2, PI_INPUT);
    gpioSetPullUpDown(PIR_SENSOR_2, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Callback function for motion detection
void motion_detected_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge detected
        log_event("Motion Detected", gpio);

        // Check if rate limiting is active
        unsigned long current_time = gpioTick();
        if (current_time - last_unlock_time < RATE_LIMIT_INTERVAL) {
            log_event("Rate Limited", gpio);
            return;
        }

        unlock_door();
    }
}

// Function to unlock the door
void unlock_door() {
    log_event("Door Unlocked", -1); // -1 indicates no specific GPIO
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(500);          // Wait for 500 ms
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    last_unlock_time = gpioTick();
}

// Function to log events to file
void log_event(const char *event_type, int gpio) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long timestamp_ms = (ts.tv_sec * 1000) + (ts.tv_nsec / 1000000);

    if (log_file != NULL) {
        fprintf(log_file, "%ld,%s", timestamp_ms, event_type);
        if (gpio != -1) {
            fprintf(log_file, ",GPIO %d", gpio);
        }
        fprintf(log_file, "\n");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("door_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Set up callbacks for motion detection
    gpioSetAlertFunc(PIR_SENSOR_1, motion_detected_callback);
    gpioSetAlertFunc(PIR_SENSOR_2, motion_detected_callback);

    printf("Door unlock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(50); // Poll every 50 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

