// Define GPIO pins for the motors
#define MOTOR1_PIN 17
#define MOTOR2_PIN 27

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global flag to signal program termination
volatile sig_atomic_t shutdown = 0;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    shutdown = 1;
    printf("\nCaught signal %d, shutting down gracefully...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(MOTOR1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR1_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(MOTOR2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", MOTOR2_PIN);
        gpioTerminate();
        return -1;
    }

    // Set PWM frequency for both motors
    gpioSetPWMfrequency(MOTOR1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_PIN, PWM_FREQUENCY);

    // Set PWM range for both motors
    gpioSetPWMrange(MOTOR1_PIN, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_PIN, PWM_RANGE);

    return 0;
}

// Function to generate a random PWM duty cycle
int generate_random_duty_cycle() {
    return rand() % (PWM_RANGE + 1);
}

// Function to generate a random duration in milliseconds
int generate_random_duration() {
    return (rand() % 151) + 50; // Duration between 50 and 200 ms
}

// Function to generate a haptic pattern
int generate_haptic_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int *num_steps) {
    *num_steps = (rand() % 11) + 5; // Number of steps between 5 and 15

    for (int i = 0; i < *num_steps; i++) {
        motor1_duty_cycles[i] = generate_random_duty_cycle();
        motor2_duty_cycles[i] = generate_random_duty_cycle();
        durations[i] = generate_random_duration();
    }

    return 0;
}

