int play_haptic_pattern(int *motor1_duty_cycles, int *motor2_duty_cycles, int *durations, int num_steps) {
    for (int i = 0; i < num_steps; i++) {
        gpioPWM(MOTOR1_PIN, motor1_duty_cycles[i]);
        gpioPWM(MOTOR2_PIN, motor2_duty_cycles[i]);
        gpioDelay(durations[i] * 1000); // Convert ms to us
    }
    return 0;
}

// Function to stop the motors
int stop_motors() {
    gpioPWM(MOTOR1_PIN, 0);
    gpioPWM(MOTOR2_PIN, 0);
    return 0;
}

