    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library and set GPIO modes
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Allocate memory for the haptic pattern arrays
    int *motor1_duty_cycles = (int *)malloc(15 * sizeof(int));
    int *motor2_duty_cycles = (int *)malloc(15 * sizeof(int));
    int *durations = (int *)malloc(15 * sizeof(int));
    int num_steps;

    if (motor1_duty_cycles == NULL || motor2_duty_cycles == NULL || durations == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        stop_motors();
        gpioTerminate();
        return 1;
    }

    // Main loop to generate and play haptic patterns
    while (!shutdown) {
        // Generate a haptic pattern
        if (generate_haptic_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, &num_steps) != 0) {
            fprintf(stderr, "Failed to generate haptic pattern\n");
            break;
        }

        // Play the haptic pattern
        if (play_haptic_pattern(motor1_duty_cycles, motor2_duty_cycles, durations, num_steps) != 0) {
            fprintf(stderr, "Failed to play haptic pattern\n");
            break;
        }
    }

    // Stop the motors and release resources before exiting
    stop_motors();
    gpioTerminate();

    // Free allocated memory
    free(motor1_duty_cycles);
    free(motor2_duty_cycles);
    free(durations);

    printf("Program terminated.\n");
    return 0;
}

