#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA 4
#define HX711_CLOCK 17
#define SOLENOID_PIN 27

// Define constants
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"
#define NUM_CALIBRATION_READINGS 100
#define WEIGHT_THRESHOLD 10.0
#define TIMEOUT_MS 500

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold calibration data
typedef struct {
    double scale_factor;
    double offset;
} CalibrationData;

// Function prototypes
int initialize_gpio();
CalibrationData load_calibration_data(const char *filename);
CalibrationData calibrate_sensor(int data_pin, int clock_pin, int num_readings);
double raw_to_weight(long raw_value, CalibrationData calibration);
void control_solenoid(int solenoid_pin, int state);
void log_data(double weight);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA, PI_INPUT);
    gpioSetMode(HX711_CLOCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    return 0;
}

// Function to load calibration data from file
CalibrationData load_calibration_data(const char *filename) {
    CalibrationData calibration = {1.0, 0.0};
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found, using default values\n");
        return calibration;
    }

    if (fscanf(fp, "%lf %lf", &calibration.scale_factor, &calibration.offset) != 2) {
        fprintf(stderr, "Invalid calibration file format, using default values\n");
        fclose(fp);
        return calibration;
    }

    fclose(fp);
    return calibration;
}

// Function to calibrate the sensor
CalibrationData calibrate_sensor(int data_pin, int clock_pin, int num_readings) {
    CalibrationData calibration = {1.0, 0.0};
    long sum = 0;

    printf("Calibrating sensor...\n");
    for (int i = 0; i < num_readings; i++) {
        long reading = read_hx711(data_pin, clock_pin);
        if (reading == -1) {
            fprintf(stderr, "Calibration timeout, skipping reading %d\n", i + 1);
            continue; // Skip the reading if it times out
        }
        sum += reading;
        gpioDelay(1); // Small delay between readings
    }

    calibration.offset = (double)sum / num_readings;
    printf("Calibration complete. Offset: %lf\n", calibration.offset);
    return calibration;
}

// Function to convert raw value to weight
double raw_to_weight(long raw_value, CalibrationData calibration) {
    return (raw_value - calibration.offset) / calibration.scale_factor;
}

// Function to control the solenoid
void control_solenoid(int solenoid_pin, int state) {
    gpioWrite(solenoid_pin, state);
}

// Function to log data to file
void log_data(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Function to read data from HX711
long read_hx711(int data_pin, int clock_pin) {
    long value = 0;
    int i;

    gpioSetMode(data_pin, PI_INPUT); // Ensure data pin is in input mode
    gpioSetMode(clock_pin, PI_OUTPUT); // Ensure clock pin is in output mode

    // Wait for data pin to go low (with timeout)
    int timeout_count = 0;
    while (gpioRead(data_pin) == 1 && timeout_count < TIMEOUT_MS) {
        gpioDelay(1); // Wait 1 ms
        timeout_count++;
    }

    if (timeout_count >= TIMEOUT_MS) {
        fprintf(stderr, "HX711 timeout waiting for data pin to go low\n");
        return -1; // Indicate timeout
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1); // Short delay
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1); // Short delay
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    // Sign extend if negative
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return value;
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio()) {
        return 1;
    }

    // Load calibration data
    CalibrationData calibration = load_calibration_data(CALIBRATION_FILE);

    // Calibrate sensor if calibration file is missing or invalid
    if (calibration.scale_factor == 1.0 && calibration.offset == 0.0) {
        calibration = calibrate_sensor(HX711_DATA, HX711_CLOCK, NUM_CALIBRATION_READINGS);

        // Save calibration data to file
        FILE *fp = fopen(CALIBRATION_FILE, "w");
        if (fp != NULL) {
            fprintf(fp, "%lf %lf", calibration.scale_factor, calibration.offset);
            fclose(fp);
            printf("Calibration data saved to %s\n", CALIBRATION_FILE);
        } else {
            fprintf(stderr, "Error saving calibration data to %s\n", CALIBRATION_FILE);
        }
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        long raw_value = read_hx711(HX711_DATA, HX711_CLOCK);
        if (raw_value != -1) {
            double weight = raw_to_weight(raw_value, calibration);
            printf("Raw: %ld, Weight: %.2f kg\n", raw_value, weight);

            if (weight > WEIGHT_THRESHOLD) {
                control_solenoid(SOLENOID_PIN, 1); // Engage lock
            } else {
                control_solenoid(SOLENOID_PIN, 0); // Release lock
            }

            log_data(weight);
        } else {
            fprintf(stderr, "Error reading HX711, skipping iteration\n");
        }

        gpioDelay(500); // Wait 500 ms
    }

    // Cleanup
    control_solenoid(SOLENOID_PIN, 0); // Release lock on exit
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

