    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        long raw_value = read_hx711(HX711_DATA, HX711_CLOCK);
        if (raw_value != -1) {
            double weight = raw_to_weight(raw_value, calibration);
            printf("Raw: %ld, Weight: %.2f kg\n", raw_value, weight);

            if (weight > WEIGHT_THRESHOLD) {
                control_solenoid(SOLENOID_PIN, 1); // Engage lock
