#define MOTOR_PWM_FREQUENCY 1000
#define MOTOR_PWM_DUTYCYCLE 150
#define MOTOR_RUN_TIME_S 5
#define CHECK_INTERVAL_S 60

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_rain_sensor();
int debounce_rain_sensor(int num_readings);
void close_window();
void stop_motor();
void signal_handler(int signal);

// Function to read the rain sensor with debouncing
int read_rain_sensor() {
    return gpioRead(RAIN_SENSOR_PIN);
}

// Function to debounce the rain sensor readings
int debounce_rain_sensor(int num_readings) {
    int low_count = 0;
    for (int i = 0; i < num_readings; i++) {
        if (read_rain_sensor() == 0) {
            low_count++;
        }
        gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Convert ms to microseconds
    }
    return (low_count >= RAIN_THRESHOLD);
}

