void close_window() {
    syslog(LOG_INFO, "Closing window...");

    // Set motor direction to close
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);

    // Enable PWM and set frequency and duty cycle
    gpioPWM(MOTOR_PWM_PIN, MOTOR_PWM_DUTYCYCLE);
    gpioSetPWMfrequency(MOTOR_PWM_PIN, MOTOR_PWM_FREQUENCY);

    // Run the motor for the specified time
    gpioDelay(MOTOR_RUN_TIME_S * 1000000); // Convert seconds to microseconds

    // Stop the motor
    stop_motor();

    syslog(LOG_INFO, "Window closed.");
}

