void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, stopping motor and exiting...");
    program_running = 0;
    stop_motor();
    gpioTerminate();
    closelog();
    exit(0);
}

