        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "Window control program started.");

    // Main loop
    while (program_running) {
        // Read rain sensor with debouncing
        if (debounce_rain_sensor(DEBOUNCE_READINGS)) {
            syslog(LOG_INFO, "Rain detected!");
            close_window();
        }

        // Wait before checking again
        gpioDelay(CHECK_INTERVAL_S * 1000000); // Convert seconds to microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();
    closelog();
    return 0;
}

