#include <string.h>

// Define GPIO pins
#define HX711_DT 23
#define HX711_SCK 24
#define SOLENOID_PIN 17

// Define stock level threshold
#define STOCK_THRESHOLD 100.0

// Define solenoid activation time
#define SOLENOID_ACTIVATION_TIME 5

// Define timeout duration (in microseconds)
#define TIMEOUT_US 1000000 // 1 second

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold HX711 calibration data
typedef struct {
    float scale;
    float offset;
} HX711Calibration;

// Function prototypes
int read_hx711(int dt_pin, int sck_pin, int timeout_us);
float convert_to_grams(int raw_value, HX711Calibration calibration);
void activate_solenoid(int solenoid_pin, int activation_time);
void log_event(const char *event_message);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// HX711 read function with timeout and retry
int read_hx711(int dt_pin, int sck_pin, int timeout_us) {
    int32_t value = 0;
    int i;

    gpioSetMode(dt_pin, PI_INPUT);
    gpioSetMode(sck_pin, PI_OUTPUT);

    // Wait for the data line to go low, with timeout
    int start_time = gpioTick();
    while (gpioRead(dt_pin) == 1) {
        if (gpioTick() - start_time > timeout_us) {
            fprintf(stderr, "Error: HX711 data line stuck high (DT=%d, SCK=%d)\n", dt_pin, sck_pin);
            return -1; // Indicate error
        }
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(sck_pin, 1);
        gpioDelay(1); // Small delay
        value = value << 1;
        if (gpioRead(dt_pin)) {
            value++;
        }
        gpioWrite(sck_pin, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain 128
    gpioWrite(sck_pin, 1);
    gpioDelay(1); // Small delay
    gpioWrite(sck_pin, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (value & 0x800000) {
        value |= 0xFF000000;
    }

    return (int)value;
}

// Function to convert raw HX711 reading to grams
float convert_to_grams(int raw_value, HX711Calibration calibration) {
    return (float)raw_value / calibration.scale + calibration.offset;
}

// Function to activate the solenoid lock
void activate_solenoid(int solenoid_pin, int activation_time) {
    gpioWrite(solenoid_pin, 1); // Activate solenoid
    gpioDelay(activation_time * 1000); // Wait for activation time (in milliseconds)
    gpioWrite(solenoid_pin, 0); // Deactivate solenoid
}

// Function to log events to a file
void log_event(const char *event_message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0; // Indicate success
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is off
    gpioTerminate();
}

int main() {
    // Calibration data (example values, replace with your actual calibration)
    HX711Calibration calibration = { .scale = 123.45, .offset = -67.89 };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("stock_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        cleanup_gpio();
        return 1;
    }

    printf("Stock monitoring system started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw_value = read_hx711(HX711_DT, HX711_SCK, TIMEOUT_US);
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 value\n");
        } else {
            float weight_grams = convert_to_grams(raw_value, calibration);
            printf("Weight: %.2f g\n", weight_grams);

            if (weight_grams < STOCK_THRESHOLD) {
                printf("Stock level low, activating solenoid lock.\n");
                activate_solenoid(SOLENOID_PIN, SOLENOID_ACTIVATION_TIME);
                log_event("Solenoid activated");
            }
        }

        gpioDelay(1000); // Check every 1 second
    }

    // Cleanup and exit
    printf("Cleaning up...\n");
    fclose(log_file);
    cleanup_gpio();

    return 0;
}

