#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Calibration file path
#define CALIBRATION_FILE "calibration.txt"

// Log file path
#define LOG_FILE "security.log"

// Weight threshold in kg
#define WEIGHT_THRESHOLD 5.0

// Solenoid activation time in seconds
#define SOLENOID_ACTIVATION_TIME 5

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *calibration_file = NULL;

// Function prototypes
int read_hx711();
double calibrate_load_cell();
double get_calibration_factor();
double convert_raw_to_kg(int raw_value, double calibration_factor);
void control_solenoid(double weight);
void log_event(double weight);
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 100) {
        gpioDelay(1); // Wait 1 us
        timeout++;
    }

    if (timeout >= 100) {
        fprintf(stderr, "Error: HX711 data line timeout (high for %d ms).\n", timeout);
        return -1; // Indicate timeout error
    }

    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high duration
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low duration
    }

    // 25th pulse for gain setting (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= ~0xffffff;
    }

    return data;
}

// Function to calibrate the load cell
double calibrate_load_cell() {
    int raw_value;
    double known_weight;
    double calibration_factor;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1.0;
    }

    // Read raw value from HX711
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value during calibration.\n");
        return -1.0;
    }

    // Calculate calibration factor
    calibration_factor = (double)raw_value / known_weight;

    // Save calibration factor to file
    calibration_file = fopen(CALIBRATION_FILE, "w");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for writing.\n");
        return -1.0;
    }

    if (fprintf(calibration_file, "%lf", calibration_factor) < 0) {
        fprintf(stderr, "Error: Could not write calibration factor to file.\n");
        fclose(calibration_file);
        return -1.0;
    }

    if (fclose(calibration_file) != 0) {
        fprintf(stderr, "Error: Could not close calibration file.\n");
        return -1.0;
    }

    printf("Calibration complete. Calibration factor: %lf\n", calibration_factor);
    return calibration_factor;
}

// Function to get the calibration factor from the file
double get_calibration_factor() {
    double calibration_factor;

    calibration_file = fopen(CALIBRATION_FILE, "r");
    if (calibration_file == NULL) {
        fprintf(stderr, "Error: Could not open calibration file for reading.\n");
        return -1.0;
    }

    if (fscanf(calibration_file, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error: Could not read calibration factor from file.\n");
        fclose(calibration_file);
        return -1.0;
    }

    if (fclose(calibration_file) != 0) {
        fprintf(stderr, "Error: Could not close calibration file.\n");
        return -1.0;
    }

    return calibration_factor;
}

// Function to convert raw value to kilograms
double convert_raw_to_kg(int raw_value, double calibration_factor) {
    return (double)raw_value / calibration_factor;
}

// Function to control the solenoid door lock
void control_solenoid(double weight) {
    if (weight > WEIGHT_THRESHOLD) {
        printf("Weight exceeds threshold. Activating solenoid.\n");
        gpioWrite(SOLENOID_PIN, 1); // Activate solenoid
        gpioDelay(SOLENOID_ACTIVATION_TIME * 1000); // Wait for activation time
        gpioWrite(SOLENOID_PIN, 0); // Deactivate solenoid
        printf("Solenoid deactivated.\n");
    }
}

// Function to log events to a file
void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file for writing.\n");
        return;
    }

    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, Weight: %.2f kg\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, weight);

    if (fclose(log_file) != 0) {
        fprintf(stderr, "Error: Could not close log file.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d. Exiting gracefully.\n", signal);
    running = 0;
    gpioWrite(SOLENOID_PIN, 0); // Unlock solenoid
    gpioTerminate(); // Terminate pigpio
