#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins
#define PIR_SENSOR_1 17
#define PIR_SENSOR_2 22
#define BUZZER 18

// Define chip and line names
#define CHIP_NAME "gpiochip0"

// Global variables for GPIO lines and chip
struct gpiod_chip *chip;
struct gpiod_line *pir_sensor_1_line;
struct gpiod_line *pir_sensor_2_line;
struct gpiod_line *buzzer_line;

// Global variable for log file
FILE *log_file;

// Function prototypes
int read_pir_sensor(struct gpiod_line *line);
void activate_buzzer(struct gpiod_line *line);
void deactivate_buzzer(struct gpiod_line *line);
void log_motion(int sensor_number);
void signal_handler(int sig);

// Function to read the state of a PIR sensor
int read_pir_sensor(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading PIR sensor value: %s\n", strerror(errno));
        return -1; // Indicate error
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 1);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Function to deactivate the buzzer
void deactivate_buzzer(struct gpiod_line *line) {
    int ret = gpiod_line_set_value(line, 0);
    if (ret < 0) {
        fprintf(stderr, "Error setting buzzer value: %s\n", strerror(errno));
    }
}

// Function to log motion detection event
void log_motion(int sensor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Motion detected by sensor %d\n", timestamp, sensor_number);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    printf("Caught signal %d, cleaning up...\n", sig);
    deactivate_buzzer(buzzer_line);
    fclose(log_file);

    gpiod_line_release(pir_sensor_1_line);
    gpiod_line_release(pir_sensor_2_line);
    gpiod_line_release(buzzer_line);
    gpiod_chip_close(chip);

    exit(0);
}

int main() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return 1;
    }

    // Get GPIO lines
    pir_sensor_1_line = gpiod_chip_get_line(chip, PIR_SENSOR_1);
    pir_sensor_2_line = gpiod_chip_get_line(chip, PIR_SENSOR_2);
    buzzer_line = gpiod_chip_get_line(chip, BUZZER);

    if (!pir_sensor_1_line || !pir_sensor_2_line || !buzzer_line) {
        fprintf(stderr, "Error getting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Request GPIO lines for input
    if (gpiod_line_request_input(pir_sensor_1_line, "motion_sensor") < 0 ||
        gpiod_line_request_input(pir_sensor_2_line, "motion_sensor") < 0 ||
        gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting GPIO line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpiod_line_release(pir_sensor_1_line);
        gpiod_line_release(pir_sensor_2_line);
        gpiod_line_release(buzzer_line);
        gpiod_chip_close(chip);
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        int motion1 = read_pir_sensor(pir_sensor_1_line);
        int motion2 = read_pir_sensor(pir_sensor_2_line);

        if (motion1 == 1) {
            printf("Motion detected by sensor 1\n");
            log_motion(1);
            activate_buzzer(buzzer_line);
            usleep(2000000); // 2 seconds
            deactivate_buzzer(buzzer_line);
        }

        if (motion2 == 1) {
            printf("Motion detected by sensor 2\n");
            log_motion(2);
            activate_buzzer(buzzer_line);
            usleep(2000000); // 2 seconds
            deactivate_buzzer(buzzer_line);
        }

        usleep(100000); // Check every 0.1 seconds
    }

    return 0;
}

