#include <gpiod.h>

#define GPIO_CHIP "gpiochip0"
#define GPIO_PIN 18
#define CONFIG_FILE "watering.conf"

static volatile sig_atomic_t terminate = 0;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *line = NULL;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int sig)
{
    (void)sig; // Suppress unused parameter warning
    terminate = 1;
    fprintf(stderr, "Signal received, terminating...\n");
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening config file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fprintf(stderr, "Error reading from config file %s: %s\n", filename, strerror(errno));
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Parse the duration from the line
    char *key = strtok(line, "=");
    char *value_str = strtok(NULL, "=");

    if (key == NULL || value_str == NULL) {
        fprintf(stderr, "Error parsing config file %s: Invalid format\n", filename);
        return -1;
    }

    int duration = atoi(value_str);

    // Validate the duration
    if (duration <= 0 || duration > 3600) {
        fprintf(stderr, "Error: Invalid duration in config file %s.  Must be between 1 and 3600.\n", filename);
        return -1;
    }

    return duration;
}

// Function to initialize the GPIO line
int initialize_gpio(const char *chip_name, int pin)
{
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip %s: %s\n", chip_name, strerror(errno));
        return -1;
    }

    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    struct gpiod_line_request_config config;
    memset(&config, 0, sizeof(config));
    config.consumer = "watering_system";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_OUTPUT;
    config.flags = 0;

    int ret = gpiod_line_request(line, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    return 0;
}

// Function to set the GPIO line value
int set_gpio_value(struct gpiod_line *line, int value)
{
    int ret = gpiod_line_set_value(line, value);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to perform the watering action
int water(struct gpiod_line *line, int duration)
{
    // Turn the valve on
    if (set_gpio_value(line, 1) != 0) {
        return -1;
    }
    printf("Valve ON\n");

    // Wait for the specified duration
    sleep(duration);

    // Turn the valve off
    if (set_gpio_value(line, 0) != 0) {
        return -1;
    }
    printf("Valve OFF\n");

    return 0;
}

// Function to clean up GPIO resources
void cleanup_gpio(struct gpiod_chip *chip, struct gpiod_line *line)
{
    if (line) {
        gpiod_line_release(line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main()
{
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Read the watering duration from the configuration file
    int duration = read_watering_duration(CONFIG_FILE);
    if (duration < 0) {
        fprintf(stderr, "Failed to read watering duration. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Initialize the GPIO line
    if (initialize_gpio(GPIO_CHIP, GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return EXIT_FAILURE;
    }

    // Perform the watering action
    if (water(line, duration) != 0) {
        fprintf(stderr, "Failed to perform watering. Exiting.\n");
        cleanup_gpio(chip, line);
        return EXIT_FAILURE;
    }

    // Clean up GPIO resources
    cleanup_gpio(chip, line);

    printf("Watering completed successfully.\n");
    return EXIT_SUCCESS;
}

