#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define LEFT_MOTOR_FORWARD 22
#define LEFT_MOTOR_BACKWARD 23
#define RIGHT_MOTOR_FORWARD 24
#define RIGHT_MOTOR_BACKWARD 25
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define motor speeds
#define BASE_SPEED 150
#define TURN_SPEED 75

// Define PWM frequency
#define PWM_FREQUENCY 1000 // 1 kHz

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
int read_sensors();
void control_motors(int sensor_state);
void log_data(int sensor_state, int left_speed, int right_speed);
void signal_handler(int signal);

// Function to read sensor values
int read_sensors() {
    int left = gpioRead(LEFT_SENSOR);
    int middle = gpioRead(MIDDLE_SENSOR);
    int right = gpioRead(RIGHT_SENSOR);

    // Combine sensor values into a single integer
    return (left << 2) | (middle << 1) | right;
}

// Function to control motor speeds based on sensor state
void control_motors(int sensor_state) {
    int left_speed = BASE_SPEED;
    int right_speed = BASE_SPEED;

    switch (sensor_state) {
        case 0b001: // Left sensor only
            left_speed = TURN_SPEED;
            break;
        case 0b010: // Right sensor only
            right_speed = TURN_SPEED;
            break;
        case 0b100: // Middle sensor only
            // Do nothing, already at base speed
            break;
        case 0b111: // No sensors
            left_speed = 0;
            right_speed = 0;
            break;
        default:
            fprintf(stderr, "Error: Invalid sensor state: %d\n", sensor_state);
            break;
    }

    gpioPWM(LEFT_MOTOR_FORWARD, left_speed);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0); // Ensure backward motor is off
    gpioPWM(RIGHT_MOTOR_FORWARD, right_speed);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0); // Ensure backward motor is off
}

// Function to log data to file
void log_data(int sensor_state, int left_speed, int right_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S%z", timeinfo);

    fprintf(log_file, "%s, %d, %d, %d, %d\n", timestamp, sensor_state, left_speed, right_speed, BASE_SPEED);
    fflush(log_file); // Ensure data is written to file immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
    running = 0;

    // Stop motors
    gpioPWM(LEFT_MOTOR_FORWARD, 0);
    gpioPWM(LEFT_MOTOR_BACKWARD, 0);
    gpioPWM(RIGHT_MOTOR_FORWARD, 0);
    gpioPWM(RIGHT_MOTOR_BACKWARD, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LEFT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(LEFT_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_FORWARD, PI_OUTPUT);
    gpioSetMode(RIGHT_MOTOR_BACKWARD, PI_OUTPUT);
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(LEFT_MOTOR_FORWARD, PWM_FREQUENCY);
    gpioSetPWMfrequency(RIGHT_MOTOR_FORWARD, PWM_FREQUENCY);

    // Open log file
    log_file = fopen("trace_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Main loop
    while (running) {
        int sensor_state = read_sensors();
        control_motors(sensor_state);
        log_data(sensor_state, BASE_SPEED, BASE_SPEED);
        gpioDelay(10000); // 10 ms delay
    }

    return 0;
}

