#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse widths (microseconds)
#define LOCKED_PULSE_WIDTH 1000
#define UNLOCKED_PULSE_WIDTH 2000

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 100

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_button(int gpio_pin);
int set_servo_pulse_width(int gpio_pin, int pulse_width);
void debounce_button(int gpio_pin);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT) {
        printf("\nCaught SIGINT, exiting gracefully...\n");
        program_running = 0;
        gpioTerminate();
        exit(0);
    }
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors on button pins
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0; // Indicate success
}

// Read button state with debouncing
int read_button(int gpio_pin) {
    int button_state = gpioRead(gpio_pin);
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (microseconds)
    return button_state;
}

// Set servo pulse width
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Pulse width out of range (500-2500 us)\n");
        return 1; // Indicate failure
    }
    gpioServo(gpio_pin, pulse_width);
    return 0; // Indicate success
}

// Debounce button press
void debounce_button(int gpio_pin) {
    gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay (microseconds)
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Check for lock button press
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            printf("Lock button pressed. Locking door.\n");
            if (set_servo_pulse_width(SERVO_PIN, LOCKED_PULSE_WIDTH) == 0) {
                debounce_button(LOCK_BUTTON_PIN);
            }
        }

        // Check for unlock button press
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            printf("Unlock button pressed. Unlocking door.\n");
            if (set_servo_pulse_width(SERVO_PIN, UNLOCKED_PULSE_WIDTH) == 0) {
                debounce_button(UNLOCK_BUTTON_PIN);
            }
        }

        gpioDelay(10000); // Small delay to prevent busy-waiting (10ms)
    }

    // Clean up and exit
    gpioTerminate();
    return 0;
}

