#include <gpiod.h>

// Define GPIO pins for motor control
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27

// Define pulse duration in milliseconds
#define PULSE_DURATION 200

// Global variables for GPIO lines and chip
struct gpiod_line *motor1_line = NULL;
struct gpiod_line *motor2_line = NULL;
struct gpiod_chip *chip = NULL;

// Function prototypes
int initialize_gpio(int gpio_pin);
int set_motor_state(struct gpiod_line *line, int state);
void cleanup_gpio(struct gpiod_line *line);
void cleanup_chip(struct gpiod_chip *chip);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    set_motor_state(motor1_line, 0);
    set_motor_state(motor2_line, 0);
    cleanup_gpio(motor1_line);
    cleanup_gpio(motor2_line);
    cleanup_chip(chip);
    gpioTerminate();
    exit(0);
}

// Function to initialize a GPIO pin as output
int initialize_gpio(int gpio_pin) {
    struct gpiod_line *line;
    int ret;

    line = gpiod_chip_get_line(chip, gpio_pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line %d\n", gpio_pin);
        return -1;
    }

    ret = gpiod_line_request_output(line, "haptic_feedback", 0);
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line %d as output: %s\n", gpio_pin, strerror(-ret));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Function to set the state of a motor (1 for ON, 0 for OFF)
int set_motor_state(struct gpiod_line *line, int state) {
    int ret;

    ret = gpiod_line_set_value(line, state);
    if (ret < 0) {
        fprintf(stderr, "Error setting GPIO line value: %s\n", strerror(-ret));
        return -1;
    }

    return 0;
}

// Function to cleanup a GPIO line
void cleanup_gpio(struct gpiod_line *line) {
    if (line) {
        gpiod_line_release(line);
    }
}

// Function to cleanup the GPIO chip
void cleanup_chip(struct gpiod_chip *chip) {
    if (chip) {
        gpiod_chip_close(chip);
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip\n");
        gpioTerminate();
        return 1;
    }

    // Initialize motor 1 GPIO
    if (initialize_gpio(MOTOR1_GPIO) < 0) {
        cleanup_chip(chip);
        gpioTerminate();
        return 1;
    }
    motor1_line = gpiod_chip_get_line(chip, MOTOR1_GPIO);

    // Initialize motor 2 GPIO
    if (initialize_gpio(MOTOR2_GPIO) < 0) {
        cleanup_gpio(motor1_line);
        cleanup_chip(chip);
        gpioTerminate();
        return 1;
    }
    motor2_line = gpiod_chip_get_line(chip, MOTOR2_GPIO);

    // Main loop
    while (1) {
        // Pulse motor 1
        if (set_motor_state(motor1_line, 1) < 0) {
            break;
        }
        gpioDelay(PULSE_DURATION * 1000); // Convert ms to us
        if (set_motor_state(motor1_line, 0) < 0) {
            break;
        }

        // Pulse motor 2
        if (set_motor_state(motor2_line, 1) < 0) {
            break;
        }
        gpioDelay(PULSE_DURATION * 1000); // Convert ms to us
        if (set_motor_state(motor2_line, 0) < 0) {
            break;
        }

        // Delay to prevent immediate re-triggering
        gpioDelay(100 * 1000); // 100ms delay
    }

    // Cleanup and exit
    set_motor_state(motor1_line, 0);
    set_motor_state(motor2_line, 0);
    cleanup_gpio(motor1_line);
    cleanup_gpio(motor2_line);
    cleanup_chip(chip);
    gpioTerminate();

    return 0;
}

