#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <zmq.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoint
#define ZMQ_ENDPOINT "tcp://*:5555"

// Define ZeroMQ topic
#define ZMQ_TOPIC "SOUND_ALERTS"

// Global variables for ZeroMQ context and socket
void *context = NULL;
void *publisher = NULL;
void *subscriber = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
int publish_sound_alert();
int subscribe_to_alerts();
void cleanup();
void signal_handler(int signal);

// Structure to hold program state
struct ProgramState {
    int running;
};

struct ProgramState state = {1}; // Initialize running to 1

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        if (initialize_gpio() != 0) {
            fprintf(stderr, "Failed to initialize GPIO.\n");
            return 1;
        }

        if (initialize_zmq() != 0) {
            fprintf(stderr, "Failed to initialize ZeroMQ.\n");
            cleanup();
            return 1;
        }

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

        while (state.running) {
            if (publish_sound_alert() != 0) {
                fprintf(stderr, "Failed to publish sound alert.\n");
                break;
            }
            gpioDelay(10000); // 10 ms delay
        }

        cleanup();
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        if (initialize_gpio() != 0) {
            fprintf(stderr, "Failed to initialize GPIO.\n");
            return 1;
        }

        if (initialize_zmq() != 0) {
            fprintf(stderr, "Failed to initialize ZeroMQ.\n");
            cleanup();
            return 1;
        }

        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);

        if (subscribe_to_alerts() != 0) {
            fprintf(stderr, "Failed to subscribe to alerts.\n");
            cleanup();
            return 1;
        }

        cleanup();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    return 0;
}

int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

int initialize_zmq() {
    context = zmq_ctx_new();
    if (!context) {
        fprintf(stderr, "Failed to create ZeroMQ context.\n");
        return 1;
    }

    publisher = zmq_socket(context, ZMQ_PUB);
    if (!publisher) {
        fprintf(stderr, "Failed to create ZeroMQ publisher socket.\n");
        return 1;
    }

    int rc = zmq_bind(publisher, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ publisher socket: %s\n", zmq_strerror(zmq_errno()));
        return 1;
    }

    subscriber = zmq_socket(context, ZMQ_SUB);
    if (!subscriber) {
        fprintf(stderr, "Failed to create ZeroMQ subscriber socket.\n");
        return 1;
    }

    rc = zmq_connect(subscriber, ZMQ_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to connect ZeroMQ subscriber socket: %s\n", zmq_strerror(zmq_errno()));
        return 1;
    }

    rc = zmq_setsockopt(subscriber, ZMQ_SUBSCRIBE, ZMQ_TOPIC, strlen(ZMQ_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ subscriber socket option: %s\n", zmq_strerror(zmq_errno()));
        return 1;
    }

    return 0;
}

int publish_sound_alert() {
    int sound_detected = gpioRead(SOUND_SENSOR_PIN);

    if (sound_detected == 0) { // Active low
        zmq_msg_t message;
        zmq_msg_init_size(&message, strlen(ZMQ_TOPIC));
        memcpy(zmq_msg_data(&message), ZMQ_TOPIC, strlen(ZMQ_TOPIC));

        int rc = zmq_msg_send(&message, publisher, 0);
        zmq_msg_close(&message);

        if (rc == -1) {
            fprintf(stderr, "Failed to send message: %s\n", zmq_strerror(zmq_errno()));
            return 1;
        }

        printf("Published sound alert.\n");
    }

    return 0;
}

int subscribe_to_alerts() {
    zmq_msg_t message;
    zmq_msg_init(&message);

    while (state.running) {
        int rc = zmq_msg_recv(&message, subscriber, 0);
        if (rc == -1) {
            if (state.running) {
                fprintf(stderr, "Failed to receive message: %s\n", zmq_strerror(zmq_errno()));
            }
            break;
        }

        char *topic = (char *)zmq_msg_data(&message);
        size_t topic_len = zmq_msg_size(&message);

        if (topic_len == strlen(ZMQ_TOPIC) && strncmp(topic, ZMQ_TOPIC, strlen(ZMQ_TOPIC)) == 0) {
            printf("Received sound alert.\n");
            gpioWrite(ALARM_LED_PIN, 1); // Turn on LED
            gpioDelay(1000000);          // 1 second delay
            gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
        }

        zmq_msg_close(&message);
    }

    zmq_msg_close(&message);
    return 0;
}

void cleanup() {
    printf("Cleaning up...\n");

    if (publisher) {
        zmq_close(publisher);
    }
    if (subscriber) {
        zmq_close(subscriber);
    }
    if (context) {
        zmq_ctx_destroy(context);
    }

    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

void signal_handler(int signal) {
    printf("Signal received: %d.  Shutting down...\n", signal);
    state.running = 0;
}

