#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>
#include <mosquitto.h>
#include <stdint.h>

// Configuration
#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MQTT_CLIENT_ID "ir_decoder"
#define PULSE_BUFFER_SIZE 100
#define TIMEOUT_US 100000 // 100ms timeout

// NEC Protocol Constants
#define NEC_HEADER_MARK 9000
#define NEC_HEADER_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// Global Variables
static volatile int pulse_buffer[PULSE_BUFFER_SIZE];
static volatile int pulse_count = 0;
static volatile uint32_t last_tick = 0;
static volatile int decoding = 0;
static volatile uint32_t decoded_address = 0;
static volatile uint32_t decoded_command = 0;
static struct mosquitto *mosq = NULL;
static int running = 1;

// Function Prototypes
void ir_callback(int gpio, int level, uint32_t tick);
int decode_nec(const int *pulses, int pulse_count, uint32_t *address, uint32_t *command);
int validate_checksum(uint32_t address, uint32_t command);
int publish_mqtt(uint32_t address, uint32_t command);
void signal_handler(int sig);

// IR Callback Function
void ir_callback(int gpio, int level, uint32_t tick) {
    uint32_t pulse_length;

    if (tick < last_tick) {
        // Handle tick rollover
        pulse_length = (0xFFFFFFFF - last_tick) + tick;
    } else {
        pulse_length = tick - last_tick;
    }

    last_tick = tick;

    if (decoding) {
        if (pulse_count < PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_count++] = pulse_length;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow!");
            pulse_count = 0; // Reset buffer
            decoding = 0;    // Stop decoding
        }
    }

    if (level == 0) { // Falling edge
        if (pulse_length > NEC_HEADER_MARK * 0.8 && pulse_length < NEC_HEADER_MARK * 1.2) {
            // Start of header
            pulse_count = 0;
            decoding = 1;
        } else {
            decoding = 0;
        }
    } else if (level == 1) { // Rising edge
        if (decoding) {
            if (pulse_length > NEC_BIT_MARK * 0.8 && pulse_length < NEC_BIT_MARK * 1.2) {
                // Bit mark
                if (pulse_count % 2 == 0) {
                    if (pulse_length > NEC_ONE_SPACE * 0.8 && pulse_length < NEC_ONE_SPACE * 1.2) {
                        // Logic 1
                        pulse_buffer[pulse_count - 1] = 1;
                    } else {
                        // Invalid space
                        pulse_count = 0;
                        decoding = 0;
                    }
                } else {
                    if (pulse_length > NEC_ZERO_SPACE * 0.8 && pulse_length < NEC_ZERO_SPACE * 1.2) {
                        // Logic 0
                        pulse_buffer[pulse_count - 1] = 0;
                    } else {
                        // Invalid space
                        pulse_count = 0;
                        decoding = 0;
                    }
                }
            } else {
                // Invalid mark
                pulse_count = 0;
                decoding = 0;
            }
        }
    }

    if (decoding && pulse_count >= 68) {
        // Enough pulses to decode a frame
        uint32_t address, command;
        if (decode_nec(pulse_buffer, pulse_count, &address, &command)) {
            if (validate_checksum(address, command)) {
                if (publish_mqtt(address, command)) {
                    syslog(LOG_INFO, "Decoded: Address = 0x%02X, Command = 0x%02X", address, command);
                } else {
                    syslog(LOG_ERR, "Failed to publish MQTT message.");
                }
            } else {
                syslog(LOG_ERR, "Checksum validation failed.");
            }
        } else {
            syslog(LOG_ERR, "NEC decoding failed.");
        }
        pulse_count = 0;
        decoding = 0;
    }
}

// NEC Decoding Function
int decode_nec(const int *pulses, int pulse_count, uint32_t *address, uint32_t *command) {
    if (pulse_count < 68) return 0; // Not enough pulses

    uint32_t raw_address = 0;
    uint32_t raw_command = 0;

    // Decode address (8 bits)
    for (int i = 0; i < 8; i++) {
        if (pulses[2 + (i * 2)] != 1) return 0; // Bit mark
        if (pulses[3 + (i * 2)] == 0) {
            raw_address |= (1 << (7 - i));
        }
    }

    // Decode command (8 bits)
    for (int i = 0; i < 8; i++) {
        if (pulses[18 + (i * 2)] != 1) return 0; // Bit mark
        if (pulses[19 + (i * 2)] == 0) {
            raw_command |= (1 << (7 - i));
        }
    }

    *address = raw_address;
    *command = raw_command;

    return 1;
}

// Checksum Validation Function
int validate_checksum(uint32_t address, uint32_t command) {
    uint32_t inv_address = ~address;
    uint32_t inv_command = ~command;

    // Calculate checksum for address and command
    uint32_t address_checksum = (inv_address & 0xFF) + ((inv_address >> 8) & 0xFF) + ((inv_address >> 16) & 0xFF);
    uint32_t command_checksum = (inv_command & 0xFF) + ((inv_command >> 8) & 0xFF) + ((inv_command >> 16) & 0xFF);

    // Extract checksum bits from address and command
    uint32_t address_checksum_bits = (address >> 24) & 0xFF;
    uint32_t command_checksum_bits = (command >> 24) & 0xFF;

    // Validate checksum
    return (address_checksum_bits == address_checksum) && (command_checksum_bits == command_checksum);
}

// MQTT Publishing Function
int publish_mqtt(uint32_t address, uint32_t command) {
    char payload[100];
    int ret;

    snprintf(payload, sizeof(payload), "{\"address\": \"0x%02X\", \"command\": \"0x%02X\"}", address, command);

    ret = mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(payload), payload, 0, false);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish error: %s", mosquitto_strerror(ret));
        return 0;
    }

    return 1;
}

// Signal Handler
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, exiting...");
    running = 0;
}

int main() {
    // Initialize syslog
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO mode
    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    // Set alert function
    gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL);

    // Initialize MQTT
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create MQTT client instance.");
        gpioTerminate();
        closelog();
        return 1;
    }

    int ret = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (ret != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(ret));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_loop_start(mosq);

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    syslog(LOG_INFO, "IR decoder started");

    // Main loop
    while (running) {
        gpioDelay(100); // Sleep for 100ms
    }

    // Cleanup
    mosquitto_loop_stop(mosq, false);
    mosquitto_disconnect(mosq);
    mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();

    return 0;
}

