#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

#define I2C_BUS "/dev/i2c-1"
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define NUM_SENSORS 4

// Sensor addresses
const int sensor_addresses[NUM_SENSORS] = {0x23, 0x24, 0x25, 0x26};

// Global flag for signal handling
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read lux value from a BH1750FVI sensor
float read_bh1750(int fd, int sensor_id) {
    unsigned char data[2];
    int ret;

    // Set the I2C slave address
    if (ioctl(fd, I2C_SLAVE, sensor_addresses[sensor_id - 1]) < 0) {
        perror("Error setting I2C slave address");
        return NAN;
    }

    // Send the One-Time High-Resolution mode command
    unsigned char command = 0x20;
    if (write(fd, &command, 1) != 1) {
        perror("Error writing to I2C device");
        return NAN;
    }

    // Wait for the measurement to complete (at least 180ms)
    usleep(180000);

    // Read the two bytes of data
