#define I2C_BUS "/dev/i2c-1"
#define I2C_ADDR 0x28
#define LOG_FILE "airflow_log.txt"

// Global variable for I2C file descriptor
int i2c_fd = -1;

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus, int addr) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read airflow data from the sensor
int read_airflow(int fd) {
    uint8_t buffer[2];
    int retries = 3;
    int bytes_read;

    while (retries > 0) {
        bytes_read = read(fd, buffer, 2);
        if (bytes_read == 2) {
            // Combine the two bytes into a 14-bit value
            int16_t raw_value = (buffer[0] << 8) | buffer[1];
            return raw_value;
        } else {
            perror("Error reading from I2C device");
            retries--;
            usleep(100000); // 100 ms delay
        }
    }

    fprintf(stderr, "Failed to read airflow after multiple retries.\n");
    return -1; // Indicate failure
}

// Function to convert raw value to SLPM
float convert_to_slpm(int raw_value) {
    return (raw_value - 3277) * 0.1;
}

// Function to log the airflow data to a file
void log_airflow(float flow_rate) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    FILE *log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return;
    }

    fprintf(log_file, "%s, %.2f SLPM\n", timestamp, flow_rate);
    fclose(log_file);
}

int main() {
    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    i2c_fd = init_i2c(I2C_BUS, I2C_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (1) {
        // Read airflow data
        int raw_value = read_airflow(i2c_fd);
        if (raw_value >= 0) {
            // Convert to SLPM
            float flow_rate = convert_to_slpm(raw_value);

            // Log the data
            log_airflow(flow_rate);

            printf("Flow Rate: %.2f SLPM\n", flow_rate);
        } else {
            fprintf(stderr, "Failed to read airflow data.\n");
        }

        sleep(1); // Sample every second
    }

    return 0;
}

