#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 Register Addresses
#define AS7341_WHO_AM_I 0x24
#define AS7341_ENABLE 0x80
#define AS7341_CFG6 0xAF
#define AS7341_STATUS 0x73
#define AS7341_F1DATAH 0x60

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int as7341_init(int fd);
int read_spectral_data(int fd, uint16_t *data);
float calculate_lux(uint16_t *data);
int log_data(FILE *fp, uint16_t *data, float lux);
void signal_handler(int signal);

// I2C read function
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, &reg, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        perror("Failed to read register value");
        return -1;
    }

    return 0;
}

// I2C write function
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, buf, 2) != 2) {
        perror("Failed to write to register");
        return -1;
    }

    return 0;
}

// AS7341 initialization function
int as7341_init(int fd) {
    uint8_t who_am_i;

    // Verify WHO_AM_I register
    if (i2c_read_reg(fd, AS7341_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register\n");
        return -1;
    }

    if (who_am_i != 0x19) {
        fprintf(stderr, "WHO_AM_I check failed. Expected 0x19, got 0x%02X\n", who_am_i);
        return -1;
    }

    // Power on the sensor
    if (i2c_write_reg(fd, AS7341_ENABLE, 0x01) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure SMUX for spectral readings
    if (i2c_write_reg(fd, AS7341_CFG6, 0x0F) < 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2c_write_reg(fd, AS7341_ENABLE, 0x41) < 0) {
        fprintf(stderr, "Error writing to ENABLE register to enable spectral measurement\n");
        return -1;
    }

    return 0;
}

// Function to read spectral data
int read_spectral_data(int fd, uint16_t *data) {
    uint8_t buffer[20]; // 10 channels * 2 bytes per channel

    if (ioctl(fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("Failed to acquire bus access and/or talk to slave");
        return -1;
    }

    if (write(fd, (uint8_t[]){AS7341_F1DATAH}, 1) != 1) {
        perror("Failed to write register address for spectral data");
        return -1;
    }

    if (read(fd, buffer, 20) != 20) {
        perror("Failed to read spectral data");
        return -1;
    }

    for (int i = 0; i < 10; i++) {
        data[i] = (buffer[i * 2 + 1] << 8) | buffer[i * 2];
    }

    return 0;
}

// Function to calculate lux (simplified)
float calculate_lux(uint16_t *data) {
    // This is a placeholder.  A real implementation would use a calibration curve.
    // For demonstration purposes, we'll just return a simple average.
    float sum = 0.0;
    for (int i = 0; i < 10; i++) {
        sum += data[i];
    }
    return sum / 10.0;
}

// Function to log data to CSV file
int log_data(FILE *fp, uint16_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,", timestamp);
    for (int i = 0; i < 10; i++) {
        fprintf(fp, "%u", data[i]);
        if (i < 9) {
            fprintf(fp, ",");
        }
    }
    fprintf(fp, ",%.2f\n", lux);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    uint16_t spectral_data[10];
    float lux;

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Open I2C device
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C device");
        return 1;
    }

    // Initialize AS7341 sensor
    if (as7341_init(i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Main loop
    while (program_running) {
        // Read spectral data
        if (read_spectral_data(i2c_fd, spectral_data) < 0) {
            fprintf(stderr, "Failed to read spectral data\n");
        } else {
            // Calculate lux
            lux = calculate_lux(spectral_data);

            // Log data
            if (log_data(log_file, spectral_data, lux) < 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close I2C device and log file
    close(i2c_fd);
    fclose(log_file);

    return 0;
}

