// I2C setup function
int i2c_setup(int address) {
    int fd = open("/dev/i2c-1", O_RDWR);
    if (fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read sensor data
int read_sensor_data(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];
    int retries = 3;
    int delay_ms = 10;

    while (retries > 0) {
        // Read X_L, X_H, Y_L, Y_H, Z_L, Z_H
        if (read(fd, buffer, 6) != 6) {
            log_error(error_file, "I2C read error");
            retries--;
            usleep(delay_ms * 1000); // Exponential backoff
            delay_ms *= 2;
            continue;
        }

        *x = (int16_t)((buffer[1] << 8) | buffer[0]);
        *y = (int16_t)((buffer[3] << 8) | buffer[2]);
        *z = (int16_t)((buffer[5] << 8) | buffer[4]);

        return 0; // Success
    }

    log_error(error_file, "I2C read failed after multiple retries");
    return -1; // Failure
}

