                break;
            default:
                fprintf(stderr, "Usage: %s [-a i2c_address] [-i interval] [-f filename]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Open error log file
    error_file = fopen("seismic_error.log", "a");
    if (error_file == NULL) {
        perror("Error opening error log file");
        return EXIT_FAILURE;
    }

    // Open data file
    data_file = fopen(filename, "a");
    if (data_file == NULL) {
        log_error(error_file, "Error opening data file");
        fclose(error_file);
        return EXIT_FAILURE;
    }

    // Write CSV header if the file is newly created
    fseek(data_file, 0, SEEK_END);
    long file_size = ftell(data_file);
    if (file_size == 0) {
        fprintf(data_file, "timestamp,x_g,y_g,z_g\n");
        fflush(data_file);
    }

    // Setup I2C
    i2c_fd = i2c_setup(i2c_address);
    if (i2c_fd < 0) {
        log_error(error_file, "I2C setup failed");
        fclose(data_file);
        fclose(error_file);
        return EXIT_FAILURE;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x_raw, y_raw, z_raw;
    double x_g, y_g, z_g;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(i2c_fd, &x_raw, &y_raw, &z_raw) == 0) {
            // Convert to g
            x_g = convert_to_g(x_raw);
            y_g = convert_to_g(y_raw);
            z_g = convert_to_g(z_raw);

            // Log data
            if (log_data(data_file, x_g, y_g, z_g) != 0) {
                log_error(error_file, "Failed to log data");
            }
        } else {
            log_error(error_file, "Failed to read sensor data");
        }

        sleep(interval);
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

