// Function to initialize the BH1750 sensor
int init_bh1750(int fd) {
    uint8_t init_cmd = 0x01; // Power on
    if (write(fd, &init_cmd, 1) != 1) {
        perror("Failed to write power-on command");
        return -1;
    }
    usleep(100000); // Wait for power-on (100ms)

    init_cmd = 0x10; // Continuous high-resolution mode
    if (write(fd, &init_cmd, 1) != 1) {
        perror("Failed to write continuous mode command");
        return -1;
    }
    usleep(100000); // Wait for mode change (100ms)

    return 0;
}

// Function to read the raw light value from the BH1750 sensor
int read_bh1750(int fd, uint16_t *raw_value) {
    uint8_t buffer[2];

    if (read(fd, buffer, 2) != 2) {
        perror("Failed to read light value");
        return -1;
    }

    *raw_value = (buffer[0] << 8) | buffer[1];
    return 0;
}

// Function to convert the raw value to lux
float convert_to_lux(uint16_t raw_value) {
    return (float)raw_value / 1.2;
}

// Function to send the lux value over UDP multicast
int send_udp_multicast(float lux_value) {
    struct sockaddr_in addr;
    int addrlen = sizeof(addr);
    char buffer[32];

    // Format the lux value as a string
    snprintf(buffer, sizeof(buffer), "%.2f", lux_value);

    // Configure the destination address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send the data
    if (sendto(udp_socket, buffer, strlen(buffer), 0, (struct sockaddr *)&addr, addrlen) < 0) {
        perror("Failed to send UDP multicast");
        return -1;
    }

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        return 1;
    }

    // Initialize the BH1750 sensor
    if (init_bh1750(i2c_fd) < 0) {
        fprintf(stderr, "Failed to initialize BH1750 sensor. Exiting.\n");
        close(i2c_fd);
        return 1;
    }

    // Create the UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Failed to create UDP socket");
        close(i2c_fd);
        return 1;
    }

    // Configure multicast TTL
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, &ttl, sizeof(ttl)) < 0) {
        perror("Failed to set multicast TTL");
        close(i2c_fd);
        close(udp_socket);
        return 1;
    }

    // Main loop
    while (1) {
        uint16_t raw_value;
        if (read_bh1750(i2c_fd, &raw_value) == 0) {
            float lux_value = convert_to_lux(raw_value);
            if (send_udp_multicast(lux_value) == 0) {
                printf("Lux: %.2f\n", lux_value);
            } else {
                fprintf(stderr, "Failed to send lux value.\n");
            }
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        sleep(1);
    }

    // Cleanup (should not reach here in normal operation due to the signal handler)
    close(i2c_fd);
    close(udp_socket);

    return 0;
}

