// Constants
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define MAGIC_WORD_SIZE 8
#define MAGIC_WORD_1 0x0204
#define MAGIC_WORD_2 0x0306
#define MAGIC_WORD_3 0x0805
#define MAGIC_WORD_4 0x0709
#define TLV_TYPE_DETECTED_OBJECTS 1
#define MAX_BUFFER_SIZE 2048
#define MAX_OBJECTS 100
#define RANGE_MIN 0.0
#define RANGE_MAX 10.0
#define VELOCITY_MIN -5.0
#define VELOCITY_MAX 5.0

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t program_running = 1;

// Structure for detected object data
typedef struct {
    int object_index;
    float range_m;
    float velocity_mps;
} DetectedObject;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int buffer_size);
int find_magic_word(const char *buffer, int buffer_size, int *magic_word_index);
int validate_tlv_payload(const char *buffer, int buffer_size);
int extract_detected_objects(const char *buffer, int buffer_size, DetectedObject *objects, int *num_objects);
int write_data_to_csv(time_t timestamp, DetectedObject *objects, int num_objects);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the UART interface
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); //0 for default flags
    if (uart_handle < 0) {
        fprintf(stderr, "Error opening UART: %s\n", UART_DEVICE);
        return -1;
    }
    return 0;
}

// Reads data from the UART port
int read_uart_data(char *buffer, int buffer_size) {
    int bytes_read = serRead(uart_handle, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from UART: %d\n", bytes_read);
        return -1;
    }
    return bytes_read;
}

// Finds the magic word in the buffer
int find_magic_word(const char *buffer, int buffer_size, int *magic_word_index) {
    if (buffer_size < MAGIC_WORD_SIZE) {
        return -1; // Not enough data to find the magic word
    }

    for (int i = 0; i <= buffer_size - MAGIC_WORD_SIZE; i++) {
        if (buffer[i] == MAGIC_WORD_1 && buffer[i + 1] == MAGIC_WORD_2 &&
            buffer[i + 2] == MAGIC_WORD_3 && buffer[i + 3] == MAGIC_WORD_4) {
            *magic_word_index = i;
            return 0; // Magic word found
        }
    }
    return -1; // Magic word not found
}

// Validates the TLV payload
int validate_tlv_payload(const char *buffer, int buffer_size) {
    // Basic validation: Check if the TLV type is 1 (Detected Objects)
    if (buffer_size < 4) return -1; // Need at least 4 bytes for type and length

    int tlv_type = *((int *)buffer); // Assuming type is an integer
    if (tlv_type != TLV_TYPE_DETECTED_OBJECTS) {
        fprintf(stderr, "Error: Invalid TLV type: %d\n", tlv_type);
        return -1;
    }

    // Add more sophisticated validation here if needed
    return 0;
}

// Extracts detected objects from the TLV payload
int extract_detected_objects(const char *buffer, int buffer_size, DetectedObject *objects, int *num_objects) {
    *num_objects = 0;

    // Assuming the TLV payload contains a list of detected objects
    // Each object has a range and velocity (assuming float for simplicity)
    // The number of objects is determined by the TLV length

    if (buffer_size < 8) return -1; // Need at least 8 bytes for type and length

    int tlv_length = *((int *)(buffer + 4)); // Get the TLV length

    if (buffer_size < tlv_length) {
        fprintf(stderr, "Error: TLV length exceeds buffer size\n");
        return -1;
    }

    int object_count = (tlv_length - 8) / (2 * sizeof(float)); // Each object is 2 floats (range, velocity)
    if (object_count > MAX_OBJECTS) {
        fprintf(stderr, "Warning: Too many objects detected (%d), limiting to %d\n", object_count, MAX_OBJECTS);
        object_count = MAX_OBJECTS;
    }

    for (int i = 0; i < object_count; i++) {
        float range = *((float *)(buffer + 8 + i * 2 * sizeof(float)));
        float velocity = *((float *)(buffer + 8 + i * 2 * sizeof(float) + sizeof(float)));

        // Validate range and velocity
        if (range < RANGE_MIN || range > RANGE_MAX || velocity < VELOCITY_MIN || velocity > VELOCITY_MAX) {
            fprintf(stderr, "Warning: Invalid range or velocity (%f, %f) for object %d, skipping\n", range, velocity, i);
            continue; // Skip invalid objects
        }

        objects[i].object_index = i;
        objects[i].range_m = range;
        objects[i].velocity_mps = velocity;
        (*num_objects)++;
    }

    return 0;
}

// Writes data to the CSV file
int write_data_to_csv(time_t timestamp, DetectedObject *objects, int num_objects) {
    struct tm *timeinfo = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(csv_file, "%s", timestamp_str);
    for (int i = 0; i < num_objects; i++) {
        fprintf(csv_file, ",%d,%.2f,%.2f", objects[i].object_index, objects[i].range_m, objects[i].velocity_mps);
    }
    fprintf(csv_file, "\n");
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (initialize_uart() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open CSV file for writing
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file\n");
        serClose(uart_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file
    fprintf(csv_file, "timestamp");
    for (int i = 0; i < MAX_OBJECTS; i++) {
        fprintf(csv_file, ",object_index,range_m,velocity_mps");
    }
    fprintf(csv_file, "\n");
    fflush(csv_file);

    char buffer[MAX_BUFFER_SIZE];
    int magic_word_index;
    time_t current_time;
    DetectedObject objects[MAX_OBJECTS];
    int num_objects;

    fprintf(stderr, "Starting data acquisition...\n");

    while (program_running) {
        // Read data from UART
        int bytes_read = read_uart_data(buffer, MAX_BUFFER_SIZE);
        if (bytes_read > 0) {
            // Find magic word
            if (find_magic_word(buffer, bytes_read, &magic_word_index) == 0) {
                // Validate TLV payload
                if (validate_tlv_payload(buffer + magic_word_index, bytes_read - magic_word_index) == 0) {
                    // Extract detected objects
                    if (extract_detected_objects(buffer + magic_word_index, bytes_read - magic_word_index, objects, &num_objects) == 0) {
                        // Get current timestamp
                        current_time = time(NULL);

                        // Write data to CSV file
                        write_data_to_csv(current_time, objects, num_objects);
                    } else {
                        fprintf(stderr, "Error extracting detected objects\n");
                    }
                } else {
                    fprintf(stderr, "Error validating TLV payload\n");
                }
            } else {
                //fprintf(stderr, "Magic word not found\n"); //Commented out to reduce verbosity
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            gpioDelay(100); // Wait before retrying
        }

        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    // Close UART and CSV file
    serClose(uart_handle);
    fclose(csv_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program finished.\n");
    return 0;
}

