#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <errno.h>
#include <sys/select.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_SEC 0.5
#define BUFFER_SIZE 256
#define MAX_RANGE 10.0 // Maximum expected range in meters

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold program state
typedef struct {
    int uart_fd;
    char buffer[BUFFER_SIZE];
    int buffer_index;
} ProgramState;

// Function prototypes
int setup_uart(const char *device, speed_t baud_rate);
int read_uart_data(int fd, char *buffer, int buffer_size, struct timeval timeout);
int parse_radar_data(const char *line, double *timestamp, double *range);
void log_detection(double timestamp, double range);
void signal_handler(int signal);
void cleanup(ProgramState *state);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, exiting gracefully.\n", signal);
        program_running = 0;
    }
}

// Setup UART communication
int setup_uart(const char *device, speed_t baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_NONBLOCK);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    tty.c_cflag = baud_rate | CS8 | CLOCAL | CREAD;  // 8N1, no parity
    tty.c_iflag = IGNPAR;                           // Ignore parity errors
    tty.c_oflag = 0;
    tty.c_lflag = 0;                                // Non-canonical mode

    tty.c_cc[VMIN] = 0;  // Read at least 0 characters
    tty.c_cc[VTIME] = (int)(TIMEOUT_SEC * 10); // Timeout of 0.5 seconds (deciseconds)

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART with timeout
int read_uart_data(int fd, char *buffer, int buffer_size, struct timeval timeout) {
    fd_set readfds;
    FD_ZERO(&readfds);
    FD_SET(fd, &readfds);

    int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval) {
        // Data is available
        ssize_t bytes_read = read(fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        }
        buffer[bytes_read] = '\0'; // Null-terminate the buffer
        return (int)bytes_read;
    } else {
        // Timeout occurred
        return 0;
    }
}

// Parse radar data
int parse_radar_data(const char *line, double *timestamp, double *range) {
    char *token;
    char *line_copy = strdup(line); // Duplicate the line to avoid modifying the original
    if (line_copy == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line_copy, ",");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing timestamp in line: %s\n", line);
        free(line_copy);
        return -1;
    }
    *timestamp = strtod(token, NULL);

    token = strtok(NULL, "\n");
    if (token == NULL) {
        fprintf(stderr, "Error: Missing range in line: %s\n", line);
        free(line_copy);
        return -1;
    }
    *range = strtod(token, NULL);

    free(line_copy);

    if (*range < 0.0 || *range > MAX_RANGE) {
        fprintf(stderr, "Error: Invalid range value: %lf\n", *range);
        return -1;
    }

    return 0;
}

// Log detection data
void log_detection(double timestamp, double range) {
    time_t rawtime = (time_t)timestamp;
    struct tm *timeinfo = localtime(&rawtime);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

// Cleanup resources
void cleanup(ProgramState *state) {
    if (state->uart_fd != -1) {
