#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR 4
#define MIDDLE_SENSOR 17
#define RIGHT_SENSOR 27

// Define serial port and baud rate
#define SERIAL_PORT "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variable for the serial handle
int serial_handle = -1;

// Function prototypes
int read_sensor(int gpio_pin);
void log_sensor_data(int left, int middle, int right);
void send_emergency_stop();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    if (serial_handle != -1) {
        serClose(serial_handle);
    }
    gpioTerminate();
    exit(0);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the sensor data with a timestamp
void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
}

// Function to send the emergency stop message over serial
void send_emergency_stop() {
    char message[] = "EMERGENCY STOP!\n";
    int result = serWrite(serial_handle, message, strlen(message));
    if (result < 0) {
        fprintf(stderr, "Error sending emergency stop message: %d\n", result);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(LEFT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR, PI_PUD_UP);
    gpioSetMode(MIDDLE_SENSOR, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR, PI_PUD_UP);
    gpioSetMode(RIGHT_SENSOR, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR, PI_PUD_UP);

    // Open the serial port
    serial_handle = serOpen(SERIAL_PORT, BAUD_RATE, 0); // 0 for no flags
    if (serial_handle < 0) {
        fprintf(stderr, "Error opening serial port: %d\n", serial_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (1) {
        int left_value = read_sensor(LEFT_SENSOR);
        int middle_value = read_sensor(MIDDLE_SENSOR);
        int right_value = read_sensor(RIGHT_SENSOR);

        if (left_value == -1 || middle_value == -1 || right_value == -1) {
            // Handle error from read_sensor, but continue the loop
            gpioDelay(100); // Delay for 100 ms
            continue;
        }

        log_sensor_data(left_value, middle_value, right_value);

        // Check if all sensors detect an obstacle
        if (left_value == 0 && middle_value == 0 && right_value == 0) {
            send_emergency_stop();
        }

        gpioDelay(100); // Delay for 100 ms
    }

    // The following lines will never be reached due to the infinite loop
    serClose(serial_handle);
    gpioTerminate();
    return 0;
}

